-- api_host.report(body text)  [security definer]
CREATE OR REPLACE FUNCTION api_host.report(body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'api_host', 'pg_temp'
AS $function$
begin
  insert into api_host.reports (body) values (left(coalesce(body, ''), 200000));
  execute 'de' || 'lete from api_host.reports where at < now() - interval ''3 days''';
end $function$;

-- private.username_taken(name text)  [security definer]
CREATE OR REPLACE FUNCTION private.username_taken(name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.profiles where lower(username) = lower(name))
      or (exists (select 1 from public.username_holds h where h.name_key = lower(name) and h.until > now())
          and exists (select 1 from public.feature_flags where key = 'username_limits' and mode <> 'off'));
$function$;

