$function$;

-- public.add_group_members(cid uuid, member_ids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.add_group_members(cid uuid, member_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  people uuid[];
  staff_ boolean;
  n int;
begin
  if me is null then raise exception 'Not signed in'; end if;
  if not exists (select 1 from public.channels where id = cid and kind = 'group') then
    raise exception 'Group not found';
  end if;
  if not public.is_channel_member(cid) then raise exception 'Group not found'; end if;
  people := array(
    select distinct x from unnest(coalesce(member_ids, '{}')) x
    where not exists (select 1 from public.channel_members where channel_id = cid and user_id = x)
  );
  perform public.check_addable(people);
  if (select count(*) from public.channel_members where channel_id = cid) + cardinality(people) > 10 then
    raise exception 'Group chats can have up to 10 people';
  end if;
  if cardinality(people) = 0 then return; end if;
  staff_ := coalesce(public.is_staff(), false);
  if not staff_ then
    perform pg_advisory_xact_lock(hashtext('gc_cap:' || me::text));
    select count(*) into n from public.group_add_log
      where actor = me and via = 'add' and created_at > now() - interval '10 minutes';
    if n >= 20 then raise exception 'Slow down. You can add 20 people to group chats every 10 minutes.'; end if;
  end if;
  perform public.check_group_adds(me, people, staff_);
  insert into public.channel_members (channel_id, user_id) select cid, x from unnest(people) x;
  insert into public.group_add_log (actor, target, channel_id, via)
    select me, x, cid, 'add' from unnest(people) x;
end;
$function$;

-- public.admin_boost_bot(bid uuid, days integer, p_mult integer)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_boost_bot(bid uuid, days integer, p_mult integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  if not public.bot_promo_ok(bid) then raise exception 'Only verified, listed bots can be boosted'; end if;
  insert into public.mod_log (actor, action, target_id, reason) values ((select auth.uid()), 'bot_boost_free', bid, '×' || p_mult || ', ' || days || ' days');
  return public.book_bot_boost(bid, p_mult, 'admin', null, (select auth.uid()), days);
end $function$;

-- public.admin_boost_server(sid uuid, days integer, mult integer)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_boost_server(sid uuid, days integer, mult integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  if days is null or days < 1 or days > 60 then raise exception 'Pick 1 to 60 days'; end if;
  perform public.book_promotion(sid, 'boost', 'admin', null, auth.uid(), days, mult);
end $function$;

