-- public.admin_clear_timeout(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_clear_timeout(uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  perform public.mod_guard('untimeout', uid, null);
  update public.profiles set muted_until = null, muted_reason = null, voice_muted_until = null where id = uid;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'timeout_cleared', uid, '');
end; $function$;

-- public.admin_confirm_ban(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_confirm_ban(uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  update public.site_bans set expires_at = null where user_id = uid and (expires_at is null or expires_at > now());
  -- 157: a lifted ban stays lifted; ban them again instead.
  if not found then raise exception 'That ban isn''t running anymore. Ban them again instead.'; end if;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'ban_confirmed', uid, '');
end;
$function$;

