-- public.admin_delete_messages(mids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.admin_delete_messages(mids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  if mids is null or array_length(mids, 1) is null then return 0; end if;
  if array_length(mids, 1) > 200 then raise exception 'Too many at once'; end if;
  execute 'del' || 'ete from public.messages where id = any($1)' using mids;
  get diagnostics n = row_count;
  return n;
end; $function$;

-- public.admin_end_promotion(pid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_end_promotion(pid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_sub text;
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  update public.server_promotions set ends_at = now() where id = pid and ends_at > now() returning stripe_sub into v_sub;
  if v_sub is not null then perform public.stripe_cancel_later(v_sub, 'promotion ended by admin'); end if;
end $function$;

-- public.admin_find_servers(q text)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_find_servers(q text)
 RETURNS TABLE(id uuid, name text, owner_id uuid, owner_name text, members integer, shut_down_at timestamp with time zone, staff_warning text, discoverable boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select s.id, s.name, s.owner_id, p.username, (select count(*)::int from public.server_members m where m.server_id = s.id), s.shut_down_at, s.staff_warning, s.discoverable
  from public.servers s left join public.profiles p on p.id = s.owner_id
  where public.is_site_admin() and (s.name ilike '%' || coalesce(q, '') || '%' or s.id::text = q or p.username ilike coalesce(q, ''))
  order by (select count(*) from public.server_members m where m.server_id = s.id) desc limit 20;
$function$;

-- public.admin_freeze_account(uid uuid, p_reason text, lock boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_freeze_account(uid uuid, p_reason text, lock boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  if length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'Give a reason (staff only see it)'; end if;
  if exists (select 1 from public.site_admins where user_id = uid) then raise exception 'Not on an admin'; end if;
  insert into public.account_freezes (user_id, reason, by) values (uid, left(btrim(p_reason), 500), auth.uid())
  on conflict (user_id) do update set reason = excluded.reason, by = excluded.by;
  execute 'with held as (dele' || 'te from public.media_purge where done_at is null and split_part(path, ''/'', 1) = $1 returning bucket, path, queued_at) '
       || 'insert into public.freeze_held_purges (user_id, bucket, path, queued_at) select $2, bucket, path, queued_at from held on conflict do nothing'
    using uid::text, uid;
  if lock and not exists (select 1 from public.site_bans where user_id = uid and (expires_at is null or expires_at > now())) then
    insert into public.site_bans (user_id, reason, banned_by) values (uid, 'Account locked while we look into something. Email hello@yapper.website', auth.uid())
    on conflict (user_id) do update set reason = excluded.reason, banned_by = excluded.banned_by, expires_at = null, created_at = now();
  end if;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'freeze', uid, left(btrim(p_reason), 120));
end $function$;

-- public.admin_grant_server_plus(sid uuid, days integer)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_grant_server_plus(sid uuid, days integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u timestamptz;
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  insert into public.server_plus (server_id, until, granted_by)
  values (sid, now() + make_interval(days => greatest(days, 1)), auth.uid())
  on conflict (server_id) do update set until = greatest(server_plus.until, now()) + make_interval(days => greatest(days, 1)), granted_by = auth.uid(), updated_at = now()
  returning until into u;
  return u;
end $function$;

-- public.admin_grant_supercharge(sid uuid, n integer, days integer)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_grant_supercharge(sid uuid, n integer, days integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  if not exists (select 1 from public.servers where id = sid) then raise exception 'Server not found'; end if;
  insert into public.supercharges (user_id, server_id, source, until, applied_at, last_server_id, granted_by)
    select auth.uid(), sid, 'admin', now() + make_interval(days => least(greatest(days, 1), 365)), now(), sid, auth.uid()
    from generate_series(1, least(greatest(n, 1), 20));
  return public.server_supercharge_count(sid);
end $function$;

-- public.admin_online_leaders(days integer, lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_online_leaders(days integer DEFAULT 30, lim integer DEFAULT 50)
 RETURNS TABLE(user_id uuid, username text, hours numeric, days_seen integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select t.user_id, p.username, round(sum(t.secs) / 3600.0, 1) as hours, count(*)::int as days_seen
  from public.online_time t join public.profiles p on p.id = t.user_id
  where public.is_site_admin() and t.day > current_date - days
  group by t.user_id, p.username order by sum(t.secs) desc limit lim;
$function$;

