-- public.admin_set_area_manager(uid uuid, p_area text, on_off boolean, note text)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_set_area_manager(uid uuid, p_area text, on_off boolean, note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int; v_tag text;
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  if p_area not in ('art', 'dev') or on_off is null then raise exception 'Unknown role'; end if;
  v_tag := p_area || '_manager';
  if on_off then
    if not public.feature_on('area_managers', null) then raise exception 'Art and Dev Managers aren''t on yet'; end if;
    if uid is null or not exists (select 1 from public.profiles where id = uid) then raise exception 'Not found'; end if;
    if exists (select 1 from public.site_admins where user_id = uid) then raise exception 'Admins don''t need the role'; end if;
    if public.is_site_banned(uid) then raise exception 'That account is banned'; end if;
    insert into public.site_area_managers (user_id, area, added_by) values (uid, p_area, auth.uid()) on conflict (user_id, area) do nothing;
    get diagnostics n = row_count;
    if n > 0 then insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), v_tag || '_added', uid, left(note, 300)); end if;
  else
    execute 'de' || 'lete from public.site_area_managers where user_id = $1 and area = $2' using uid, p_area;
    get diagnostics n = row_count;
    if n > 0 then insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), v_tag || '_removed', uid, left(note, 300)); end if;
  end if;
end;
$function$;

-- public.admin_set_badge(uid uuid, badge text, on_off boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_set_badge(uid uuid, badge text, on_off boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  tiers constant text[] := array['creator_1', 'creator_2', 'creator_3'];
begin
  -- A null badge made both checks below null, so neither raised and a null went into badges.
  if badge is null or on_off is null then raise exception 'Unknown badge'; end if;
  if not (public.is_site_admin() or (badge not in ('staff', 'developer', 'community_manager') and public.is_site_manager())
          or (public.is_site_mod() and badge = 'bug_hunter') or (badge = 'artist' and public.is_art_manager())
          or (badge in ('artist', 'community_helper') and public.feature_on('head_mod_badges', null) and public.is_head_mod())) then
    raise exception 'Admins only';
  end if;
  if badge not in ('bug_hunter', 'partner', 'early', 'staff', 'developer', 'community_manager', 'creator_1', 'creator_2', 'creator_3', 'artist', 'community_helper') then
    raise exception 'Unknown badge';
  end if;
  if not public.is_site_admin() and public.is_site_manager() then perform public.manager_guard('badge', uid); else perform public.mod_guard('badge', uid, null); end if;
  if on_off then
    update public.profiles set
      badges = array(select distinct unnest(
        array(select b from unnest(coalesce(badges, '{}'::text[])) b where not (badge = any(tiers) and b = any(tiers) and b <> badge))
        || badge)),
      shown_badge = case when badge = any(tiers) and shown_badge = any(tiers) then badge else shown_badge end
    where id = uid;
  else
    update public.profiles set
      badges = array_remove(badges, badge),
      shown_badge = case when shown_badge = badge then null else shown_badge end
    where id = uid;
  end if;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), case when on_off then 'badge_given' else 'badge_removed' end, uid, badge);
end; $function$;

-- public.admin_set_community_manager(uid uuid, on_off boolean, note text)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_set_community_manager(uid uuid, on_off boolean, note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if not public.is_site_admin() then perform public.manager_guard('staff', uid); end if;
  if on_off and exists (select 1 from public.site_managers where user_id = uid) then raise exception 'Take Management off first'; end if;
  if on_off then
    if exists (select 1 from public.site_admins where user_id = uid) then raise exception 'Admins don''t need the role'; end if;
    if public.is_site_banned(uid) then raise exception 'That account is banned'; end if;
    execute 'de' || 'lete from public.site_moderators where user_id = $1' using uid;
    get diagnostics n = row_count;
    if n > 0 then
      insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'mod_removed', uid, 'Moved to Community Manager');
    end if;
    insert into public.site_community_managers (user_id, added_by) values (uid, auth.uid()) on conflict (user_id) do nothing;
    get diagnostics n = row_count;
    if n > 0 then
      insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'cm_added', uid, left(note, 300));
    end if;
    update public.profiles set badges = array(select distinct unnest(coalesce(badges, '{}'::text[]) || 'community_manager'::text))
     where id = uid and not ('community_manager' = any(coalesce(badges, '{}'::text[])));
  else
    execute 'de' || 'lete from public.site_community_managers where user_id = $1' using uid;
    get diagnostics n = row_count;
    if n > 0 then
      insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'cm_removed', uid, left(note, 300));
    end if;
    update public.profiles set badges = array_remove(badges, 'community_manager'),
           shown_badge = case when shown_badge = 'community_manager' then null else shown_badge end
     where id = uid and 'community_manager' = any(badges);
  end if;
end;
$function$;

-- public.admin_set_developer(uid uuid, on_off boolean, note text)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_set_developer(uid uuid, on_off boolean, note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if not public.is_site_admin() then perform public.manager_guard('staff', uid); end if;
  if on_off then
    if exists (select 1 from public.site_admins where user_id = uid) then raise exception 'Admins don''t need the role'; end if;
    if public.is_site_banned(uid) then raise exception 'That account is banned'; end if;
    insert into public.site_developers (user_id, added_by) values (uid, auth.uid()) on conflict (user_id) do nothing;
    get diagnostics n = row_count;
    if n > 0 then
      insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'dev_added', uid, left(note, 300));
    end if;
    update public.profiles set badges = array(select distinct unnest(coalesce(badges, '{}'::text[]) || 'developer'::text))
     where id = uid and not ('developer' = any(coalesce(badges, '{}'::text[])));
  else
    execute 'de' || 'lete from public.site_developers where user_id = $1' using uid;
    get diagnostics n = row_count;
    if n > 0 then
      insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'dev_removed', uid, left(note, 300));
    end if;
    update public.profiles set badges = array_remove(badges, 'developer'),
           shown_badge = case when shown_badge = 'developer' then null else shown_badge end
     where id = uid and 'developer' = any(badges);
  end if;
end;
$function$;

-- public.admin_set_head_mod(uid uuid, on_off boolean, note text)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_set_head_mod(uid uuid, on_off boolean, note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_site_admin() then
    if not public.is_site_manager() then raise exception 'Admins only'; end if;
    perform public.manager_guard('staff', uid);
    if on_off and (select l.action from public.mod_log l join public.site_admins a on a.user_id = l.actor
                    where l.target_id = uid and l.action in ('head_mod_added', 'head_mod_removed')
                    order by l.created_at desc limit 1) = 'head_mod_removed' then
      raise exception 'An admin took head mod off them. Ask an admin';
    end if;
  end if;
  if on_off and not public.feature_on('head_mods', null) then raise exception 'Head mods aren''t on yet'; end if;
  if on_off then
    if not exists (select 1 from public.site_moderators where user_id = uid and suspended_at is null) then
      raise exception 'Make them a moderator first (and not paused)';
    end if;
    update public.site_moderators set head = true where user_id = uid and not head;
    if found then insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'head_mod_added', uid, left(note, 300)); end if;
  else
    if exists (select 1 from public.site_managers where user_id = uid) then raise exception 'Take Management off first'; end if;
    update public.site_moderators set head = false where user_id = uid and head;
    if found then insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'head_mod_removed', uid, left(note, 300)); end if;
  end if;
end $function$;

-- public.admin_set_manager(uid uuid, on_off boolean, note text)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_set_manager(uid uuid, on_off boolean, note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  if on_off then
    if not public.feature_on('management', null) then raise exception 'Management isn''t on yet'; end if;
    if uid is null or not exists (select 1 from public.profiles where id = uid) then raise exception 'Not found'; end if;
    if exists (select 1 from public.site_admins where user_id = uid) then raise exception 'Admins don''t need the role'; end if;
    if public.is_site_banned(uid) then raise exception 'That account is banned'; end if;
    if exists (select 1 from public.site_community_managers where user_id = uid) then
      raise exception 'They''re a Community Manager. Take that role off first';
    end if;
    insert into public.site_moderators (user_id, added_by, head) values (uid, auth.uid(), true)
    on conflict (user_id) do update set head = true, suspended_at = null, suspended_reason = null
      where not site_moderators.head or site_moderators.suspended_at is not null;
    insert into public.site_managers (user_id, added_by) values (uid, auth.uid()) on conflict (user_id) do nothing;
    get diagnostics n = row_count;
    if n > 0 then insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'manager_added', uid, left(note, 300)); end if;
  else
    execute 'de' || 'lete from public.site_managers where user_id = $1' using uid;
    get diagnostics n = row_count;
    if n > 0 then insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'manager_removed', uid, left(note, 300)); end if;
  end if;
end;
$function$;

-- public.admin_set_moderator(uid uuid, on_off boolean, note text)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_set_moderator(uid uuid, on_off boolean, note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  perform public.head_mod_may_change(uid);
  if on_off then
    if exists (select 1 from public.site_admins where user_id = uid) then raise exception 'Admins don''t need the role'; end if;
    if not public.is_site_admin() and (
         (select l.action from public.mod_log l
           where l.target_id = uid and l.action in ('mod_added', 'mod_removed', 'mod_suspended')
             and (exists (select 1 from public.site_admins a where a.user_id = l.actor)
                  or (not public.is_site_manager() and exists (select 1 from public.site_managers m where m.user_id = l.actor)))
           order by l.created_at desc limit 1) in ('mod_removed', 'mod_suspended')
         or exists (select 1 from public.site_moderators where user_id = uid and suspended_reason like 'Automatic:%')) then
      raise exception 'Someone above you took them off. Ask them';
    end if;
    if public.is_site_banned(uid) then raise exception 'That account is banned'; end if;
    if exists (select 1 from public.site_community_managers where user_id = uid) then
      raise exception 'They''re a Community Manager (no reports). Take that role off first if they should see reports';
    end if;
    insert into public.site_moderators (user_id, added_by) values (uid, auth.uid())
    on conflict (user_id) do update set suspended_at = null, suspended_reason = null where site_moderators.suspended_at is not null;
    get diagnostics n = row_count;
    if n > 0 then insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'mod_added', uid, left(note, 300)); end if;
  else
    if exists (select 1 from public.site_managers where user_id = uid) then raise exception 'Take Management off first'; end if;
    execute 'de' || 'lete from public.site_moderators where user_id = $1' using uid;
    get diagnostics n = row_count;
    if n > 0 then insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'mod_removed', uid, left(note, 300)); end if;
  end if;
end;
$function$;

-- public.admin_set_plus_since(uid uuid, since timestamp with time zone)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_set_plus_since(uid uuid, since timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  if since > now() then raise exception 'Plus since can''t be in the future'; end if;
  update public.profiles set plus_since = since where id = uid;
  if not found then raise exception 'No such user'; end if;
  insert into public.mod_log (actor, action, target_id, reason)
    values (auth.uid(), 'plus_since_set', uid, case when since is null then 'reset' else to_char(since, 'YYYY-MM-DD') end);
end $function$;

-- public.admin_set_plus(uid uuid, p_until timestamp with time zone, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_set_plus(uid uuid, p_until timestamp with time zone, why text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  update public.profiles set plus_until = p_until where id = uid;
  insert into public.mod_log (actor, action, target_id, reason)
    values (auth.uid(), case when p_until is null then 'plus_removed' else 'plus_gift' end, uid,
            case when p_until is null then left(coalesce(why, ''), 300) else 'Until ' || to_char(p_until, 'YYYY-MM-DD') || coalesce(nullif(': ' || left(why, 250), ': '), '') end);
end;
$function$;

-- public.admin_shutdown_server(sid uuid, why text, p_on boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_shutdown_server(sid uuid, why text DEFAULT ''::text, p_on boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare own uuid;
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  select owner_id into own from public.servers where id = sid;
  if own is null then raise exception 'Server not found'; end if;
  if p_on then
    perform public.require_staff_reauth();
    -- Shut down: nobody can post or join, it leaves Discovery, members still see the notice.
    update public.servers set shut_down_at = now(), shut_down_reason = left(coalesce(why, ''), 500),
      locked_until = timestamptz '2999-01-01', lock_reason = 'shut down by Yapper', discoverable = false where id = sid;
  else
    update public.servers set shut_down_at = null, shut_down_reason = null, locked_until = null, lock_reason = null where id = sid;
  end if;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), case when p_on then 'server_shutdown' else 'server_reopened' end, own, left(coalesce(why, ''), 500) || ' [' || (select name from public.servers where id = sid) || ']');
end; $function$;

-- public.admin_storage_left()  [security definer]
CREATE OR REPLACE FUNCTION public.admin_storage_left()
 RETURNS TABLE(bucket text, total bigint, bytes bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select o.bucket_id, count(*), coalesce(sum((o.metadata->>'size')::bigint), 0)
  from storage.objects o
  where o.bucket_id in ('attachments', 'avatars', 'banners', 'icons', 'emojis')
  group by o.bucket_id;
$function$;

-- public.admin_storage_migrated(b text, lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_storage_migrated(b text, lim integer DEFAULT 200)
 RETURNS TABLE(name text, bytes bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select o.name, m.bytes
  from storage.objects o
  join public.media_migrated m on m.bucket = b and m.path = o.name
  where o.bucket_id = b
  order by o.created_at
  limit least(coalesce(lim, 200), 300);
$function$;

-- public.admin_storage_objects(b text, lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_storage_objects(b text, lim integer DEFAULT 50)
 RETURNS TABLE(name text, size bigint, mime text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select o.name, (o.metadata->>'size')::bigint, o.metadata->>'mimetype'
  from storage.objects o
  where o.bucket_id = b
    and o.name like '%/%'
    and not exists (select 1 from public.media_migrated m where m.bucket = b and m.path = o.name)
  order by o.created_at
  limit least(coalesce(lim, 50), 200);
$function$;

-- public.admin_storage_remaining()  [security definer]
CREATE OR REPLACE FUNCTION public.admin_storage_remaining()
 RETURNS TABLE(bucket text, remaining bigint, bytes bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select o.bucket_id, count(*), coalesce(sum((o.metadata->>'size')::bigint), 0)
  from storage.objects o
  where o.bucket_id in ('attachments', 'avatars', 'banners', 'icons', 'emojis')
    and not exists (select 1 from public.media_migrated m where m.bucket = o.bucket_id and m.path = o.name)
  group by o.bucket_id;
$function$;

-- public.admin_suspend_moderator(uid uuid, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_suspend_moderator(uid uuid, why text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  perform public.head_mod_may_change(uid);
  update public.site_moderators set suspended_at = now(), suspended_reason = nullif(left(why, 200), '') where user_id = uid and suspended_at is null;
  get diagnostics n = row_count;
  if n > 0 then insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'mod_suspended', uid, left(why, 300)); end if;
end;
$function$;

-- public.admin_unallow_appeal(aid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_unallow_appeal(aid uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  execute 'del' || 'ete from public.nsfw_allowed_hashes where appeal_id = $1' using aid;
  get diagnostics n = row_count;
  update public.upload_appeals set allowed = false where id = aid;
  if n > 0 then
    insert into public.mod_log (actor, action, target_id, reason)
    select auth.uid(), 'appeal_unallowed', a.user_id, 'Picture taken off the allowlist' from public.upload_appeals a where a.id = aid;
  end if;
  return n;
end;
$function$;

-- public.admin_unfreeze_account(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_unfreeze_account(uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  execute 'dele' || 'te from public.account_freezes where user_id = $1' using uid;
  execute 'with back as (dele' || 'te from public.freeze_held_purges where user_id = $1 returning bucket, path, queued_at) '
       || 'insert into public.media_purge (bucket, path, queued_at) select bucket, path, coalesce(queued_at, now()) from back on conflict do nothing'
    using uid;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'unfreeze', uid, '');
end $function$;

-- public.admin_verify_bot(bid uuid, ok boolean, note text, was_private boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_verify_bot(bid uuid, ok boolean, note text DEFAULT NULL::text, was_private boolean DEFAULT NULL::boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b public.bots;
begin
  if not public.can_review_bots() then raise exception 'Moderators only'; end if;
  perform public.mod_guard('bot_review', null, note);
  select * into b from public.bots where id = bid for update;
  if b.id is null then raise exception 'No such bot'; end if;
  if b.owner_id = auth.uid() and not public.is_site_admin() then raise exception 'You can''t review your own bot'; end if;
  if not (b.public or b.unlisted) then raise exception 'That bot isn''t waiting for review any more'; end if;
  if was_private is not null and was_private <> b.unlisted then raise exception 'That bot changed since you opened the queue. Reload it and look again'; end if;
  if ok then
    update public.bots set verified_at = now(), review_note = null where id = bid;
  else
    update public.bots set public = false, unlisted = false, verified_at = null, review_note = left(coalesce(note, 'Not approved'), 300) where id = bid;
  end if;
  insert into public.mod_log (actor, action, target_id, reason)
    values (auth.uid(), case when ok then 'bot_verified' else 'bot_rejected' end, bid,
            left(coalesce(nullif(btrim(note), ''), case when ok then 'Approved' else 'Not approved' end) || case when b.unlisted then ' (private)' else '' end
                 || ' [' || b.name || ']', 500));
end $function$;

-- public.admin_warn_server(sid uuid, msg text)  [security definer]
CREATE OR REPLACE FUNCTION public.admin_warn_server(sid uuid, msg text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare own uuid;
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  select owner_id into own from public.servers where id = sid;
  if own is null then raise exception 'Server not found'; end if;
  update public.servers set staff_warning = nullif(left(trim(coalesce(msg, '')), 500), ''), staff_warned_at = case when nullif(trim(coalesce(msg, '')), '') is null then null else now() end where id = sid;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), case when nullif(trim(coalesce(msg, '')), '') is null then 'server_warning_cleared' else 'server_warned' end, own, left(coalesce(msg, ''), 500) || ' [' || (select name from public.servers where id = sid) || ']');
end; $function$;

-- public.alerts_add(sid uuid, p_yt text, p_name text, p_channel uuid, p_role uuid, p_template text)  [security definer]
CREATE OR REPLACE FUNCTION public.alerts_add(sid uuid, p_yt text, p_name text, p_channel uuid, p_role uuid DEFAULT NULL::uuid, p_template text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cap int; wid uuid; t text := nullif(btrim(coalesce(p_template, '')), '');
begin
  if not public.server_perm(sid, 'manage_server') then raise exception 'Only server managers can set up alerts'; end if;
  if not public.feature_on('creator_alerts', sid) then raise exception 'Alerts aren''t available here yet'; end if;
  if p_yt is null or p_yt !~ '^UC[A-Za-z0-9_-]{22}$' then raise exception 'That doesn''t look like a YouTube channel'; end if;
  perform public.alerts_check_target(sid, p_channel, p_role, t);
  if exists (select 1 from public.alert_watches where server_id = sid and yt_channel_id = p_yt) then raise exception 'You''re already watching that channel'; end if;
  cap := case when public.server_plus_on(sid) then 25 else 3 end;
  perform 1 from public.servers where id = sid for update; -- two adds at once can't both squeeze under the cap
  if (select count(*) from public.alert_watches where server_id = sid) >= cap then
    raise exception '%', case when cap = 25 then 'That''s the most (25 channels).' else 'Free servers can watch 3 channels. Server Plus gets 25.' end;
  end if;
  -- add/remove/add can't be used to hammer YouTube or skip the backoff
  if not public.alerts_bump('add:' || sid::text, interval '1 hour', 10) then raise exception 'That''s a lot of channels in one go. Try again in an hour.'; end if;
  insert into public.yt_feeds (channel_id) values (p_yt) on conflict (channel_id) do nothing;
  -- A feed stuck in backoff gets a fresh look now that someone wants it again (not more than every 10 minutes).
  update public.yt_feeds set next_check_at = now()
  where channel_id = p_yt and last_error is not null and pending_req is null and last_checked_at < now() - interval '10 minutes';
  insert into public.alert_watches (server_id, yt_channel_id, channel_id, role_id, template, created_by)
  values (sid, p_yt, p_channel, p_role, t, auth.uid()) returning id into wid;
  -- Make sure the bot is switched on (keeps any look already set).
  insert into public.server_bots (server_id, bot, enabled, config) values (sid, 'alerts', true, '{}'::jsonb)
  on conflict (server_id, bot) do nothing;
  return wid;
end $function$;

-- public.alerts_bump(p_key text, win interval, maxn integer)  [security definer]
CREATE OR REPLACE FUNCTION public.alerts_bump(p_key text, win interval, maxn integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cnt int;
begin
  insert into public.alerts_rate as r (k, since, n) values (p_key, now(), 1)
  on conflict (k) do update set
    since = case when r.since < now() - win then now() else r.since end,
    n = case when r.since < now() - win then 1 else r.n + 1 end
  returning n into cnt;
  return cnt <= maxn;
end $function$;

-- public.alerts_check_target(sid uuid, p_channel uuid, p_role uuid, p_template text)  [security definer]
CREATE OR REPLACE FUNCTION public.alerts_check_target(sid uuid, p_channel uuid, p_role uuid, p_template text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from public.channels where id = p_channel and server_id = sid and kind = 'text') then raise exception 'Pick a text channel in this server'; end if;
  if p_role is not null and not exists (select 1 from public.roles where id = p_role and server_id = sid) then raise exception 'That role isn''t in this server'; end if;
  if p_template is not null and char_length(p_template) > 500 then raise exception 'Keep the message under 500 characters'; end if;
end $function$;

-- public.alerts_defuse(t text)
CREATE OR REPLACE FUNCTION public.alerts_defuse(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select regexp_replace(regexp_replace(coalesce(t, ''), '<@!?([0-9a-f-]{36})>', '@user', 'gi'), '@(everyone|here)', '@' || chr(8203) || '\1', 'gi')
$function$;

-- public.alerts_feed_failed(cid text, msg text)  [security definer]
CREATE OR REPLACE FUNCTION public.alerts_feed_failed(cid text, msg text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.yt_feeds set fails = fails + 1, last_error = left(msg, 200), last_checked_at = now(),
    pending_req = null, requested_at = null,
    next_check_at = now() + least(interval '10 minutes' * power(2, least(fails + 1, 10)), interval '12 hours')
  where channel_id = cid;
$function$;

-- public.alerts_feed_result(cid text, status integer, body text)  [security definer]
CREATE OR REPLACE FUNCTION public.alerts_feed_result(cid text, status integer, body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f public.yt_feeds; p jsonb; vids jsonb; v jsonb; nm text; fresh text[] := '{}'; w record;
begin
  select * into f from public.yt_feeds where channel_id = cid;
  if f.channel_id is null then return; end if;
  if status = 404 then perform public.alerts_feed_failed(cid, 'YouTube says this channel doesn''t exist'); return; end if;
  if status is distinct from 200 then perform public.alerts_feed_failed(cid, 'YouTube answered ' || coalesce(status::text, 'nothing')); return; end if;
  begin
    p := public.yt_parse_feed(body);
  exception when others then
    perform public.alerts_feed_failed(cid, 'Couldn''t read the feed'); return;
  end;
  vids := p -> 'videos';
  nm := coalesce(nullif(p ->> 'name', ''), f.name);
  if f.baseline then
    -- Oldest first, at most 5 per check, only recent ones (a deleted video can bring an old one back into the 15).
    for v in select e from jsonb_array_elements(vids) e
      where not ((e ->> 'id') = any (f.seen_ids)) and (e ->> 'published')::timestamptz > now() - interval '2 days'
      order by (e ->> 'published')::timestamptz limit 5
    loop
      fresh := fresh || (v ->> 'id');
      for w in
        select aw.id from public.alert_watches aw
        join public.server_bots b on b.server_id = aw.server_id and b.bot = 'alerts' and b.enabled
        where aw.yt_channel_id = cid and aw.created_at < (v ->> 'published')::timestamptz
          -- over the cap (Plus ran out): only the oldest ones keep working
          and (select count(*) from public.alert_watches o where o.server_id = aw.server_id and (o.created_at, o.id) < (aw.created_at, aw.id))
              < case when public.server_plus_on(aw.server_id) then 25 else 3 end
      loop
        begin
          perform public.alerts_post(w.id, v, nm);
        exception when others then null; -- one broken server must not stop the others
        end;
      end loop;
    end loop;
    fresh := fresh || f.seen_ids;
  else
    select coalesce(array_agg(e ->> 'id'), '{}') into fresh from jsonb_array_elements(vids) e;
  end if;
  -- newest first, no repeats, keep 60
  select coalesce(array_agg(x order by o), '{}') into fresh
  from (select x, min(o) as o from unnest(fresh) with ordinality u(x, o) group by x order by min(o) limit 60) s;
  update public.yt_feeds set name = nm, baseline = true, seen_ids = fresh,
    latest = case when jsonb_array_length(vids) > 0 then vids -> 0 else latest end,
    last_published = greatest(last_published, (select max((e ->> 'published')::timestamptz) from jsonb_array_elements(vids) e)),
    fails = 0, last_error = null, last_checked_at = now(), next_check_at = now() + interval '10 minutes',
    pending_req = null, requested_at = null
  where channel_id = cid;
end $function$;

-- public.alerts_flag_for(uid uuid, sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.alerts_flag_for(uid uuid, sid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select mode = 'everyone' or (mode = 'test' and (sid = any(servers) or uid = any(users)))
    from public.feature_flags where key = 'creator_alerts'), false)
$function$;

-- public.alerts_list(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.alerts_list(sid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.server_perm(sid, 'manage_server') then raise exception 'Only server managers can set up alerts'; end if;
  return jsonb_build_object(
    'max', case when public.server_plus_on(sid) then 25 else 3 end,
    'watches', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', w.id, 'yt_channel_id', w.yt_channel_id, 'name', f.name, 'channel_id', w.channel_id, 'role_id', w.role_id,
        'template', w.template, 'created_at', w.created_at, 'last_posted_at', w.last_posted_at,
        'last_checked_at', f.last_checked_at, 'last_error', f.last_error, 'checked', f.baseline,
        'latest_title', f.latest ->> 'title') order by w.created_at, w.id)
      from public.alert_watches w join public.yt_feeds f on f.channel_id = w.yt_channel_id
      where w.server_id = sid), '[]'::jsonb));
end $function$;

-- public.alerts_post(wid uuid, v jsonb, creator text, p_test boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.alerts_post(wid uuid, v jsonb, creator text, p_test boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare w public.alert_watches; body text; ping boolean;
begin
  select * into w from public.alert_watches where id = wid;
  if w.id is null or not exists (select 1 from public.channels where id = w.channel_id and server_id = w.server_id) then return; end if;
  if not exists (select 1 from public.server_bots where server_id = w.server_id and bot = 'alerts' and enabled) then return; end if;
  ping := w.role_id is not null and not p_test;
  body := replace(coalesce(nullif(btrim(w.template), ''), '{creator} just posted: **{title}**' || E'\n' || '{url}'), chr(1), '');
  if position('{role}' in body) > 0 then body := replace(body, '{role}', chr(1));
  elsif ping then body := chr(1) || ' ' || body;
  end if;
  body := replace(body, '{url}', coalesce(v ->> 'url', ''));
  body := replace(body, '{creator}', translate(public.alerts_untag(coalesce(nullif(creator, ''), 'Someone')), '{}' || E'\n' || chr(1), '() '));
  body := replace(body, '{title}', translate(public.alerts_untag(v ->> 'title'), E'\n' || chr(1), ' '));
  -- once, on the finished text
  body := public.alerts_defuse(public.alerts_untag(body));
  body := replace(body, chr(1), case when ping then '<@&' || w.role_id::text || '>' else '' end);
  perform public.bot_say(w.channel_id, 'alerts', btrim(body));
  if not p_test then
    update public.alert_watches set last_posted_at = now(), last_video_id = v ->> 'id' where id = wid;
  end if;
end $function$;

-- public.alerts_remove(wid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.alerts_remove(wid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid;
begin
  select server_id into sid from public.alert_watches where id = wid;
  if sid is null or not public.server_perm(sid, 'manage_server') then raise exception 'Only server managers can set up alerts'; end if;
  execute 'del' || 'ete from public.alert_watches where id = $1' using wid;
end $function$;

-- public.alerts_resolve_gate(uid uuid, sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.alerts_resolve_gate(uid uuid, sid uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if uid is null or sid is null or not public.server_perm_as(uid, sid, 'manage_server') then return 'Only server managers can set up alerts'; end if;
  if not public.alerts_flag_for(uid, sid) then return 'Alerts aren''t available here yet'; end if;
  if not public.alerts_bump('resolve:' || uid::text, interval '10 minutes', 20) then return 'Slow down a bit. Try again in a few minutes.'; end if;
  return null;
end $function$;

-- public.alerts_test(wid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.alerts_test(wid uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare w public.alert_watches; f public.yt_feeds; claimed uuid;
begin
  select * into w from public.alert_watches where id = wid;
  if w.id is null or not public.server_perm(w.server_id, 'manage_server') then raise exception 'Only server managers can set up alerts'; end if;
  if not public.feature_on('creator_alerts', w.server_id) then raise exception 'Alerts aren''t available here yet'; end if;
  if not exists (select 1 from public.server_bots where server_id = w.server_id and bot = 'alerts' and enabled) then raise exception 'Turn Alerts on first'; end if;
  select * into f from public.yt_feeds where channel_id = w.yt_channel_id;
  if f.latest is null then
    if f.last_error is not null then raise exception '%', f.last_error; end if;
    raise exception 'Still checking this channel. Try again in a minute.';
  end if;
  -- claim the cooldown atomically: one per channel per 10 s, one per server per 30 s
  update public.alert_watches set last_test_at = now()
  where id = wid and (last_test_at is null or last_test_at < now() - interval '10 seconds') returning id into claimed;
  if claimed is null or not public.alerts_bump('test:' || w.server_id::text, interval '30 seconds', 1) then raise exception 'Slow down a sec'; end if;
  perform public.alerts_post(wid, f.latest, f.name, true);
  return f.latest ->> 'title';
end $function$;

-- public.alerts_tick()  [security definer]
CREATE OR REPLACE FUNCTION public.alerts_tick()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f record; r record; got boolean;
begin
  if coalesce((select mode from public.feature_flags where key = 'creator_alerts'), 'off') = 'off' then return; end if;
  -- 1. finished fetches
  for f in select channel_id, pending_req, requested_at from public.yt_feeds where pending_req is not null loop
    begin
      select status_code, content, timed_out, error_msg into r from net._http_response where id = f.pending_req;
      got := found;
      -- read once, then gone: no response bodies piling up in pg_net
      if got then execute 'del' || 'ete from net._http_response where id = $1' using f.pending_req; end if;
      if not got then
        if f.requested_at < now() - interval '5 minutes' then perform public.alerts_feed_failed(f.channel_id, 'YouTube didn''t answer'); end if;
      elsif coalesce(r.timed_out, false) or r.status_code is null then
        perform public.alerts_feed_failed(f.channel_id, coalesce('Couldn''t reach YouTube: ' || left(r.error_msg, 120), 'YouTube didn''t answer in time'));
      else
        perform public.alerts_feed_result(f.channel_id, r.status_code, r.content);
      end if;
    exception when others then
      perform public.alerts_feed_failed(f.channel_id, 'Something broke while checking');
    end;
  end loop;
  -- 2. once an hour: feeds nobody watches any more, old rate-limit rows
  if extract(minute from now()) = 0 then
    execute 'del' || 'ete from public.yt_feeds y where pending_req is null and created_at < now() - interval ''1 hour'''
      || ' and not exists (select 1 from public.alert_watches w where w.yt_channel_id = y.channel_id)';
    execute 'del' || 'ete from public.alerts_rate where since < now() - interval ''1 day''';
  end if;
  -- 3. fire the ones that are due (one request per YouTube channel, however many servers watch it)
  for f in
    select y.channel_id from public.yt_feeds y
    where y.pending_req is null and y.next_check_at <= now()
      and exists (select 1 from public.alert_watches w join public.server_bots b on b.server_id = w.server_id and b.bot = 'alerts' and b.enabled
                  where w.yt_channel_id = y.channel_id)
    order by y.next_check_at limit 100
  loop
    update public.yt_feeds set requested_at = now(), pending_req = net.http_get(
      'https://www.youtube.com/feeds/videos.xml?channel_id=' || f.channel_id,
      '{}'::jsonb, '{"User-Agent":"Mozilla/5.0 (compatible; YapperAlerts/1.0; +https://www.yapper.website)"}'::jsonb, 15000)
    where channel_id = f.channel_id;
  end loop;
end $function$;

-- public.alerts_untag(t text)
CREATE OR REPLACE FUNCTION public.alerts_untag(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select regexp_replace(coalesce(t, ''), '<@[!&]?[0-9a-fA-F-]{36}>', '', 'g')
$function$;

-- public.alerts_update(wid uuid, p_channel uuid, p_role uuid, p_template text)  [security definer]
CREATE OR REPLACE FUNCTION public.alerts_update(wid uuid, p_channel uuid, p_role uuid DEFAULT NULL::uuid, p_template text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; t text := nullif(btrim(coalesce(p_template, '')), '');
begin
  select server_id into sid from public.alert_watches where id = wid;
  if sid is null or not public.server_perm(sid, 'manage_server') then raise exception 'Only server managers can set up alerts'; end if;
  if not public.feature_on('creator_alerts', sid) then raise exception 'Alerts aren''t available here yet'; end if;
  perform public.alerts_check_target(sid, p_channel, p_role, t);
  update public.alert_watches set channel_id = p_channel, role_id = p_role, template = t where id = wid;
end $function$;

-- public.am_i_site_banned()  [security definer]
CREATE OR REPLACE FUNCTION public.am_i_site_banned()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.site_bans
    where user_id = (select auth.uid()) and (expires_at is null or expires_at > now())
  );
$function$;

-- public.app_host_secrets()  [security definer]
CREATE OR REPLACE FUNCTION public.app_host_secrets()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  return coalesce((select jsonb_object_agg(s.name, s.value) from app_host.secrets s), '{}'::jsonb);
end;
$function$;

-- public.app_host_set_secrets(p jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.app_host_set_secrets(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  k text;
  v text;
  done jsonb := '{}'::jsonb;
begin
  if p is null or jsonb_typeof(p) <> 'object' then
    return done;
  end if;
  for k, v in select * from jsonb_each_text(p) loop
    if k !~ '^[A-Z][A-Z0-9_]{1,63}$' or v is null or length(v) < 1 or length(v) > 4096 then
      continue;
    end if;
    insert into app_host.secrets (name, value) values (k, v)
      on conflict (name) do update set value = excluded.value, updated_at = now();
    done := done || jsonb_build_object(k, length(v));
  end loop;
  return done;
end;
$function$;

-- public.appeal_upload(b text, p text, note text)  [security definer]
CREATE OR REPLACE FUNCTION public.appeal_upload(b text, p text, note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  sc public.media_scans%rowtype;
  q public.upload_quarantine%rowtype;
  n text := nullif(trim(coalesce(note, '')), '');
  new_id uuid;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if n is not null and char_length(n) > 300 then raise exception 'Keep the note under 300 characters'; end if;
  select * into sc from public.media_scans where bucket = b and path = p and user_id = me;
  if not found or sc.verdict <> 'blocked' or coalesce(sc.score, 0) <= 0 then
    raise exception 'That upload can''t be sent for review';
  end if;
  if sc.scanned_at < now() - interval '14 days' then raise exception 'That one is too old to send for review'; end if;
  perform pg_advisory_xact_lock(hashtextextended('upload_appeal:' || me::text, 0));
  if exists (select 1 from public.upload_appeals where bucket = b and path = p) then
    raise exception 'You already sent that one for review';
  end if;
  if (select count(*) from public.upload_appeals where user_id = me and created_at > now() - interval '1 day') >= 5 then
    raise exception 'That''s a lot of reviews for one day. Try again tomorrow.';
  end if;
  select * into q from public.upload_quarantine where bucket = b and path = p and removed_at is null;
  insert into public.upload_appeals (user_id, bucket, path, quarantine_key, phash, sha256, score, details, note)
  values (me, b, p, q.key, sc.phash, coalesce(q.sha256, sc.details ->> 'sha256'), sc.score, sc.details, n)
  returning id into new_id;
  return new_id;
end;
$function$;

-- public.apply_area_manager(p_area text, p_why text, p_links text, p_experience text, p_agree boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.apply_area_manager(p_area text, p_why text, p_links text DEFAULT ''::text, p_experience text DEFAULT ''::text, p_agree boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b text; w text := btrim(coalesce(p_why, '')); l text := btrim(coalesce(p_links, '')); ex text := btrim(coalesce(p_experience, '')); rid uuid;
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if p_area not in ('art', 'dev') then raise exception 'Unknown role'; end if;
  if not public.feature_on('area_managers', null) then raise exception 'Applications aren''t open yet'; end if;
  perform pg_advisory_xact_lock(hashtextextended('area_apply:' || auth.uid()::text, 0));
  b := public.area_apply_block(p_area);
  if b is not null then raise exception '%', b; end if;
  if not coalesce(p_agree, false) then raise exception 'You need to agree to the rules'; end if;
  if length(w) < 30 then raise exception 'Tell us a bit more about why (30 characters at least)'; end if;
  if length(w) > 1000 or length(ex) > 1000 then raise exception 'Keep each answer under 1000 characters'; end if;
  if length(l) > 500 then raise exception 'Keep the links under 500 characters'; end if;
  update public.area_applications set seen_at = now() where user_id = auth.uid() and area = p_area and seen_at is null;
  insert into public.area_applications (user_id, area, why, links, experience) values (auth.uid(), p_area, w, l, ex) returning id into rid;
  return rid;
end $function$;

-- public.apply_auto_action(target uuid, r public.reports)  [security definer]
CREATE OR REPLACE FUNCTION public.apply_auto_action(target uuid, r public.reports)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare reporters_1h int; reporters_7d int; mu timestamptz; slur boolean; since timestamptz;
begin
  if target is null or target = (select a.webhook_user_id from public.app_settings a limit 1) or exists (select 1 from public.site_admins where user_id = target) or public.is_site_banned(target) then return null; end if;
  -- 157: a lifted ban leaves its row behind; only reports made since it ended count.
  select coalesce(max(b.expires_at), '-infinity') into since from public.site_bans b where b.user_id = target;
  slur := public.has_slur(coalesce(r.message_content, ''));
  select count(distinct x.reporter_id) into reporters_1h from public.reports x
    where x.target_id = target and x.created_at > greatest(now() - interval '1 hour', since) and public.trusted_reporter(x.reporter_id);
  select count(distinct x.reporter_id) into reporters_7d from public.reports x
    where x.target_id = target and x.created_at > greatest(now() - interval '7 days', since) and public.trusted_reporter(x.reporter_id);
  if (slur and reporters_7d >= 2) or reporters_1h >= 10 then
    insert into public.site_bans (user_id, reason)
    values (target, case when slur then 'Auto-ban: slurs, reported by ' || reporters_7d || ' people' else 'Auto-ban: reported by ' || reporters_1h || ' trusted people in an hour' end)
    on conflict (user_id) do update
    set reason = excluded.reason, banned_by = excluded.banned_by, created_at = now(), expires_at = excluded.expires_at
    -- 157: a lifted (expired) ban is replaced; a running one only by a ban at least as long (null = permanent).
    where site_bans.expires_at <= now() or excluded.expires_at is null
       or (site_bans.expires_at is not null and excluded.expires_at >= site_bans.expires_at);
    update public.reports set status = 'actioned', triage = 'auto', triage_note = 'Auto-banned', resolved_at = now() where target_id = target and status = 'open';
    return 'Auto-banned';
  end if;
  if reporters_1h >= 5 then
    select muted_until into mu from public.profiles where id = target;
    if mu is null or mu < now() then
      update public.profiles set muted_until = now() + interval '1 hour', muted_reason = 'reported by ' || reporters_1h || ' people' where id = target;
    end if;
    return 'Auto timeout 1h';
  end if;
  return null;
end;
$function$;

-- public.apply_creator(p_followers integer, p_content_link text, p_note text, p_recent_link text, p_check jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.apply_creator(p_followers integer, p_content_link text, p_note text DEFAULT ''::text, p_recent_link text DEFAULT NULL::text, p_check jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid()); rid uuid; last_rej timestamptz; chk jsonb; last_post timestamptz; born timestamptz; n_videos int;
begin
  if jsonb_typeof(p_check) = 'object' then
    chk := jsonb_strip_nulls(jsonb_build_object(
      'platform', left(p_check->>'platform', 20), 'checked', (p_check->>'checked')::boolean, 'ok', (p_check->>'ok')::boolean,
      'reasons', case when jsonb_typeof(p_check->'reasons') = 'array' then (select jsonb_agg(left(x, 200)) from jsonb_array_elements_text(p_check->'reasons') x limit 5) else null end,
      'handle', left(p_check->>'handle', 100), 'subscribers', (p_check->>'subscribers')::bigint, 'lastPost', left(p_check->>'lastPost', 40),
      'posts90d', (p_check->>'posts90d')::int, 'videos', (p_check->>'videos')::int, 'createdAt', left(p_check->>'createdAt', 40), 'source', left(p_check->>'source', 10)));
    if pg_column_size(chk) > 4096 then raise exception 'Bad check'; end if;
  end if;
  if me is null then raise exception 'Sign in first'; end if;
  if not public.feature_on_for_me('creator_program') then raise exception 'Not available yet'; end if;
  if public.is_site_banned(me) then raise exception 'That account is banned'; end if;
  if (select verified_as from public.profiles where id = me) is null then raise exception 'Get verified first'; end if;
  if exists (select 1 from public.profiles where id = me and badges && array['creator_1', 'creator_2', 'creator_3']) then
    raise exception 'You''re already in the Creator Program';
  end if;
  perform 1 from public.profiles where id = me for no key update;
  if exists (select 1 from public.creator_applications where user_id = me and status in ('pending', 'needs_proof')) then
    raise exception 'You already have an application waiting for review';
  end if;
  select max(reviewed_at) into last_rej from public.creator_applications where user_id = me and status = 'rejected';
  if last_rej is not null and last_rej > now() - interval '30 days' then
    raise exception 'You can apply again 30 days after a rejection';
  end if;
  if p_followers is null or p_followers < 0 then raise exception 'How many followers do you have?'; end if;
  if p_followers < 1000 then raise exception 'You need 1,000+ followers or subscribers to join'; end if;
  if p_content_link is null or btrim(p_content_link) = '' then raise exception 'Add a link'; end if;
  if chk is not null and (chk->>'ok') = 'false' then raise exception 'Your channel didn''t pass the check: %', coalesce(chk->'reasons'->>0, 'see the form'); end if;
  if chk is not null and (chk->>'checked') = 'true' and public.feature_on_for_me('creator_apply_v2') then
    begin last_post := (chk->>'lastPost')::timestamptz; exception when others then last_post := null; end;
    begin born := (chk->>'createdAt')::timestamptz; exception when others then born := null; end;
    n_videos := (chk->>'videos')::int;
    if last_post is null then raise exception 'Your channel has no public uploads. The program is for channels that post: upload something first, then apply.'; end if;
    if last_post < now() - interval '60 days' then raise exception 'Your last upload was % days ago. The program needs a channel that posted in the last 60 days.', floor(extract(epoch from now() - last_post) / 86400)::int; end if;
    if n_videos is not null and n_videos < 3 then raise exception 'Your channel has % public %. The program needs at least 3 videos on the channel.', n_videos, case when n_videos = 1 then 'video' else 'videos' end; end if;
    if born is not null and born > now() - interval '30 days' then raise exception 'Your channel is % days old. The program needs a channel that is at least 30 days old.', floor(extract(epoch from now() - born) / 86400)::int; end if;
  end if;
  insert into public.creator_applications (user_id, followers, content_link, note, recent_link, channel_check)
  values (me, p_followers, btrim(p_content_link), left(coalesce(p_note, ''), 1000), null, chk)
  returning id into rid;
  return rid;
end; $function$;

-- public.apply_for_staff(p_why text, p_hours text, p_experience text, p_agree boolean, p_adult boolean, p_answers jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.apply_for_staff(p_why text, p_hours text, p_experience text DEFAULT ''::text, p_agree boolean DEFAULT false, p_adult boolean DEFAULT false, p_answers jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b text; w text := btrim(coalesce(p_why, '')); hr text := btrim(coalesce(p_hours, '')); ex text := btrim(coalesce(p_experience, ''));
        a jsonb := coalesce(p_answers, '{}'); clean jsonb := '{}'; k text; v text; rid uuid;
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if not public.staff_apps_on() then raise exception 'Staff applications aren''t open yet'; end if;
  perform pg_advisory_xact_lock(hashtextextended('staff_apply:' || auth.uid()::text, 0));
  b := public.staff_apply_block();
  if b is not null then raise exception '%', b; end if;
  if not coalesce(p_adult, false) then raise exception 'You need to be 18 or older to join the staff team'; end if;
  if not coalesce(p_agree, false) then raise exception 'You need to agree to the rules'; end if;
  if jsonb_typeof(a) <> 'object' then raise exception 'Something went wrong with the form, reload and try again'; end if;
  if length(w) < 30 then raise exception 'Tell us a bit more about why (30 characters at least)'; end if;
  if length(w) > 1000 or length(ex) > 1000 then raise exception 'Keep each answer under 1000 characters'; end if;
  if hr = '' then raise exception 'Add your timezone and when you''re usually on'; end if;
  if length(hr) > 100 then raise exception 'Keep your timezone and hours under 100 characters'; end if;
  v := coalesce(a ->> 'hours_week', '');
  if v not in ('1-3', '4-7', '8-15', '15+') then raise exception 'Pick how many hours a week you can help'; end if;
  clean := clean || jsonb_build_object('hours_week', v);
  v := btrim(coalesce(a ->> 'languages', ''));
  if v = '' then raise exception 'Add the languages you speak'; end if;
  if length(v) > 100 then raise exception 'Keep languages under 100 characters'; end if;
  clean := clean || jsonb_build_object('languages', v);
  foreach k in array array['good_mod', 'scenario_raid', 'scenario_friend', 'scenario_grey', 'scenario_minor', 'scenario_appeal', 'scenario_mistake'] loop
    v := btrim(coalesce(a ->> k, ''));
    if length(v) < 20 then raise exception 'Answer each question in a sentence or two (20 characters at least)'; end if;
    if length(v) > 1000 then raise exception 'Keep each answer under 1000 characters'; end if;
    clean := clean || jsonb_build_object(k, v);
  end loop;
  v := btrim(coalesce(a ->> 'extra', ''));
  if length(v) > 1000 then raise exception 'Keep each answer under 1000 characters'; end if;
  if v <> '' then clean := clean || jsonb_build_object('extra', v); end if;
  update public.staff_applications set seen_at = now() where user_id = auth.uid() and seen_at is null;
  insert into public.staff_applications (user_id, why, hours, experience, adult, answers)
    values (auth.uid(), w, hr, ex, true, clean) returning id into rid;
  return rid;
end $function$;

-- public.apply_supercharge(cid uuid, sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.apply_supercharge(cid uuid, sid uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); r public.supercharges;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if sid is null or not public.supercharge_on(sid) then raise exception 'Supercharge isn''t available here yet'; end if;
  if not exists (select 1 from public.server_members m where m.server_id = sid and m.user_id = me) then raise exception 'Join the server first'; end if;
  if cid is null then
    if not exists (select 1 from public.profiles p where p.id = me and p.plus_until > now()) then
      raise exception 'Get Yapper Plus to use your free supercharge';
    end if;
    insert into public.supercharges (user_id, source) values (me, 'plus') on conflict (user_id) where source = 'plus' do nothing;
    select id into cid from public.supercharges where user_id = me and source = 'plus';
  end if;
  select * into r from public.supercharges where id = cid and user_id = me for update;
  if r.id is null then raise exception 'That supercharge isn''t yours'; end if;
  if r.source = 'plus' and not exists (select 1 from public.profiles p where p.id = me and p.plus_until > now()) then
    raise exception 'Your Plus ran out, so its free supercharge is paused';
  end if;
  if r.source <> 'plus' and r.until <= now() then raise exception 'That supercharge ran out'; end if;
  if r.server_id = sid then return r.id; end if;
  if r.last_server_id is distinct from sid and r.last_server_id is not null and r.applied_at > now() - interval '7 days' then
    raise exception 'You can move this supercharge again on %', to_char(r.applied_at + interval '7 days', 'Mon DD');
  end if;
  update public.supercharges set server_id = sid, last_server_id = sid,
    applied_at = case when r.last_server_id = sid then r.applied_at else now() end
  where id = r.id;
  return r.id;
end $function$;

-- public.apply_to_server(invite_code text, p_message text, p_answers text[])  [security definer]
CREATE OR REPLACE FUNCTION public.apply_to_server(invite_code text, p_message text DEFAULT ''::text, p_answers text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare i public.invites; r public.server_join_requests; msg text; ans text[] := '{}'; a text; nq int; staff boolean := public.is_staff();
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if public.is_site_banned(auth.uid()) then raise exception 'That account is banned'; end if;
  select * into i from public.invites where lower(code) = lower(invite_code);
  if i.code is null then raise exception 'This invite is invalid or has expired'; end if;
  if public.is_server_member(i.server_id) then return jsonb_build_object('joined', true, 'server_id', i.server_id); end if;
  if not public.join_apply_on(i.server_id) or i.skip_apply or staff
     or exists (select 1 from public.servers where id = i.server_id and owner_id = auth.uid()) then
    perform set_config('yapper.join_ok', i.server_id::text, true);
    return jsonb_build_object('joined', true, 'server_id', public.join_server(invite_code));
  end if;
  if public.server_locked(i.server_id) then raise exception 'This server is locked right now. Try again in a few minutes.'; end if;
  if exists (select 1 from public.server_bans where server_id = i.server_id and user_id = auth.uid()) then
    raise exception 'You''re banned from this server';
  end if;
  msg := left(btrim(coalesce(p_message, '')), 500);
  nq := cardinality(coalesce((select join_questions from public.servers where id = i.server_id), '{}'));
  foreach a in array coalesce(p_answers, '{}') loop ans := ans || left(btrim(coalesce(a, '')), 300); end loop;
  ans := ans[1:nq];
  select * into r from public.server_join_requests where server_id = i.server_id and user_id = auth.uid();
  if r.id is not null then
    if r.status = 'pending' then return jsonb_build_object('joined', false, 'server_id', i.server_id, 'status', 'pending'); end if;
    if r.status = 'declined' and r.decided_at > now() - interval '24 hours' then
      raise exception 'This server said no for now. You can apply again in about % h.', greatest(1, ceil(extract(epoch from (r.decided_at + interval '24 hours' - now())) / 3600))::int;
    end if;
    if r.status = 'withdrawn' and r.decided_at > now() - interval '1 minute' then raise exception 'Give it a minute before applying again'; end if;
    update public.server_join_requests
      set status = 'pending', message = msg, answers = ans, invite_code = i.code, note = '', decided_by = null, decided_at = null,
          seen_at = null, created_at = now()
      where id = r.id;
  else
    if (select count(*) from public.server_join_requests where user_id = auth.uid() and status = 'pending') >= 20 then
      raise exception 'You have too many applications waiting';
    end if;
    insert into public.server_join_requests (server_id, user_id, invite_code, message, answers)
      values (i.server_id, auth.uid(), i.code, msg, ans);
  end if;
  perform public.bc_notice('server:' || i.server_id, 'join_request', jsonb_build_object('server_id', i.server_id, 'status', 'pending'));
  return jsonb_build_object('joined', false, 'server_id', i.server_id, 'status', 'pending');
end $function$;

-- public.apply_verification(p_platform text, p_handle text, p_link text, p_note text, p_proof_path text)  [security definer]
CREATE OR REPLACE FUNCTION public.apply_verification(p_platform text, p_handle text, p_link text, p_note text, p_proof_path text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare rid uuid; last_rej timestamptz; host text; pathpart text; me_name text; me_display text; handle text;
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  if public.is_site_banned(auth.uid()) then raise exception 'That account is banned'; end if;
  handle := btrim(regexp_replace(btrim(coalesce(p_handle, '')), '^@+', ''));
  if handle = '' then raise exception 'What''s your channel called?'; end if;
  select username, display_name, verified_as into me_name, me_display, pathpart from public.profiles where id = auth.uid();
  if pathpart is not null then raise exception 'You''re already verified'; end if;
  if exists (select 1 from public.verification_requests where user_id = auth.uid() and status in ('pending', 'needs_proof')) then
    raise exception 'You already have an application waiting for review';
  end if;
  select max(reviewed_at) into last_rej from public.verification_requests where user_id = auth.uid() and status = 'rejected';
  if last_rej is not null and last_rej > now() - interval '7 days' then
    raise exception 'You can apply again 7 days after a rejection';
  end if;
  if public.brand_name(handle) or public.brand_name(me_name) then
    if public.brand_name(me_name) then raise exception 'Your username "%" looks like a platform, brand or staff name. Change it to your channel name in Settings → My Profile, then apply again.', me_name; end if; raise exception 'Channel names can''t be platform, brand or staff names';
  end if;
  if public.bad_name(handle) or public.bad_name(coalesce(p_note, '')) then raise exception 'That isn''t allowed'; end if;
  host := lower(regexp_replace(regexp_replace(p_link, '^https?://', '', 'i'), '/.*$', ''));
  host := regexp_replace(host, '^(www|m|mobile)\.', '');
  pathpart := regexp_replace(regexp_replace(p_link, '^https?://[^/]+', '', 'i'), '[?#].*$', '');
  if char_length(btrim(pathpart, '/')) < 2 then raise exception 'Link to your channel page, not the site''s homepage'; end if;
  if (p_platform = 'youtube' and host not in ('youtube.com', 'youtu.be'))
     or (p_platform = 'twitch' and host <> 'twitch.tv')
     or (p_platform = 'tiktok' and host not in ('tiktok.com', 'vm.tiktok.com', 'vt.tiktok.com'))
     or (p_platform = 'instagram' and host <> 'instagram.com')
     or (p_platform = 'x' and host not in ('x.com', 'twitter.com')) then
    raise exception 'That link isn''t a % channel', p_platform;
  end if;
  if public.verify_name_key(handle) = '' then
    raise exception 'We can only verify channel names with Latin letters or numbers for now. Use your @handle from the link instead.';
  end if;
  if exists (select 1 from public.profiles where verified_as is not null
             and public.verify_name_key(split_part(verified_as, ' · ', 2)) = public.verify_name_key(handle)
             ) then
    raise exception 'That channel is already verified on another account';
  end if;
  if public.verify_name_key(handle) not in (public.verify_name_key(me_name), public.verify_name_key(me_display)) then
    raise exception 'Your Yapper username or display name must match your channel name (%). Change it in Settings → My Profile, then apply.', handle;
  end if;
  handle := normalize(handle, NFKC);
  if char_length(handle) > 60 or handle !~ '[[:alnum:]]' or handle ~ '[[:cntrl:]­·͏؜ᅟᅠ᠋-᠏​-‏‪-‮⁠-⁯⠀ㅤ︀-️﻿ﾠ\U000e0000-\U000e007f]' then
    raise exception 'Use your channel name as it is spelled on the site';
  end if;
  if p_proof_path is null then raise exception 'Add a proof screenshot'; end if;
  if p_proof_path !~ ('^' || auth.uid()::text || '/') then raise exception 'Bad proof'; end if;
  insert into public.verification_requests (user_id, platform, handle, link, note, proof_path)
  values (auth.uid(), p_platform, handle, btrim(p_link), coalesce(p_note, ''), p_proof_path)
  returning id into rid;
  return rid;
end;
$function$;

-- public.arabic_letters(t text)
CREATE OR REPLACE FUNCTION public.arabic_letters(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select translate(
    regexp_replace(normalize(coalesce(t, ''), NFKC), E'[^ء-غف-يٱ-ۓ]', '', 'g'),
    E'أإآٱىیةکگ',
    E'ااااييهكغ');
$function$;

-- public.are_friends(x uuid, y uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.are_friends(x uuid, y uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.friendships
    where status = 'accepted'
      and least(requester, addressee) = least(x, y)
      and greatest(requester, addressee) = greatest(x, y)
  );
$function$;

-- public.area_applications_list()  [security definer]
CREATE OR REPLACE FUNCTION public.area_applications_list()
 RETURNS TABLE(id uuid, area text, user_id uuid, why text, links text, experience text, created_at timestamp with time zone, joined_at timestamp with time zone, servers integer, past_declines integer, work integer, work_ok integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare areas text[] := '{}';
begin
  if public.is_staff() then areas := array['art', 'dev'];
  else
    if public.is_art_manager() then areas := array_append(areas, 'art'); end if;
    if public.is_dev_manager() then areas := array_append(areas, 'dev'); end if;
  end if;
  if areas = '{}' then raise exception 'Staff only'; end if;
  return query select a.id, a.area, a.user_id, a.why, a.links, a.experience, a.created_at, p.created_at,
      (select count(*)::int from public.server_members m where m.user_id = a.user_id),
      (select count(*)::int from public.area_applications d where d.user_id = a.user_id and d.area = a.area and d.status = 'declined'),
      case when a.area = 'art' then (select count(*)::int from public.community_decos d where d.artist_id = a.user_id and d.status in ('pending', 'approved'))
           else (select count(*)::int from public.bots b where b.owner_id = a.user_id) end,
      case when a.area = 'art' then (select count(*)::int from public.community_decos d where d.artist_id = a.user_id and d.status = 'approved')
           else (select count(*)::int from public.bots b where b.owner_id = a.user_id and b.verified_at is not null) end
    from public.area_applications a join public.profiles p on p.id = a.user_id
    where a.status = 'pending' and a.area = any(areas) order by a.created_at limit 200;
end $function$;

-- public.area_apply_block(p_area text)  [security definer]
CREATE OR REPLACE FUNCTION public.area_apply_block(p_area text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare made timestamptz; last public.area_applications;
begin
  if auth.uid() is null then return 'Not signed in'; end if;
  if p_area not in ('art', 'dev') then return 'Unknown role'; end if;
  if exists (select 1 from public.site_admins where user_id = auth.uid()) then return 'You''re an admin already'; end if;
  if exists (select 1 from public.site_area_managers where user_id = auth.uid() and area = p_area) then
    return 'You''re ' || case when p_area = 'art' then 'an Art Manager' else 'a Dev Manager' end || ' already';
  end if;
  if public.is_site_banned(auth.uid()) then return 'That account is banned'; end if;
  if coalesce((select muted_until > now() from public.profiles where id = auth.uid()), false) then return 'You''re timed out right now'; end if;
  select created_at into made from public.profiles where id = auth.uid();
  if made is null or made > now() - interval '14 days' then return 'Your account needs to be at least 14 days old to apply'; end if;
  select * into last from public.area_applications where user_id = auth.uid() and area = p_area order by created_at desc limit 1;
  if last.status = 'pending' then return 'You already have an application waiting'; end if;
  if last.status = 'declined' and last.decided_at > now() - interval '30 days' then
    return 'You can apply again ' || to_char(last.decided_at + interval '30 days', 'Mon FMDD');
  end if;
  if last.status = 'withdrawn' and last.decided_at > now() - interval '1 day' then return 'You took one back recently. Try again tomorrow'; end if;
  return null;
end $function$;

-- public.area_manager_may(p_action text)  [security definer]
CREATE OR REPLACE FUNCTION public.area_manager_may(p_action text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when p_action in ('deco_review', 'deco_takedown', 'badge') then public.is_art_manager()
    else false end;
$function$;

-- public.area_managers_list()  [security definer]
CREATE OR REPLACE FUNCTION public.area_managers_list()
 RETURNS TABLE(user_id uuid, area text, added_by uuid, created_at timestamp with time zone, in_server boolean, has_role boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  return query
    select m.user_id, m.area, m.added_by, m.created_at,
      exists (select 1 from public.server_members s where s.server_id = public.area_server_id(m.area) and s.user_id = m.user_id),
      exists (select 1 from public.member_roles r where r.user_id = m.user_id and r.role_id = public.area_role_id(m.area))
    from public.site_area_managers m
    order by m.created_at;
end;
$function$;

-- public.area_managers_role_sync()  [security definer]
CREATE OR REPLACE FUNCTION public.area_managers_role_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.sync_area_role(coalesce(new.user_id, old.user_id), coalesce(new.area, old.area));
  return null;
end;
$function$;

-- public.area_role_id(p_area text)
CREATE OR REPLACE FUNCTION public.area_role_id(p_area text)
 RETURNS uuid
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case p_area when 'art' then '651a0c1e-4b2d-4e8f-9a01-0c2b5a7e1a01'::uuid when 'dev' then '651a0c1e-4b2d-4e8f-9a01-0c2b5a7e1a02'::uuid end
$function$;

-- public.area_role_on_join()  [security definer]
CREATE OR REPLACE FUNCTION public.area_role_on_join()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a text;
begin
  a := case new.server_id when public.area_server_id('art') then 'art' when public.area_server_id('dev') then 'dev' end;
  if a is not null and exists (select 1 from public.site_area_managers m where m.user_id = new.user_id and m.area = a) then
    perform public.sync_area_role(new.user_id, a);
  end if;
  return null;
end;
$function$;

-- public.area_server_id(p_area text)
CREATE OR REPLACE FUNCTION public.area_server_id(p_area text)
 RETURNS uuid
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case p_area when 'art' then '00000000-0000-4000-8000-00000000b004'::uuid when 'dev' then '00000000-0000-4000-8000-00000000b005'::uuid end
$function$;

-- public.art_apply_channel_id()
CREATE OR REPLACE FUNCTION public.art_apply_channel_id()
 RETURNS uuid
 LANGUAGE sql
 IMMUTABLE
AS $function$ select '6240a7c1-9b1e-4a8e-8d3f-0c2b5a7e1a01'::uuid $function$;

-- public.art_count(t text)
CREATE OR REPLACE FUNCTION public.art_count(t text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(char_length(regexp_replace(t,
    '[^⠀-⣿▀-▟■-◿⬛⬜\U0001F7E5-\U0001F7EB]', '', 'g')), 0);
$function$;

-- public.ask_creator_proof(rid uuid, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.ask_creator_proof(rid uuid, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.creator_applications;
begin
  p_note := left(btrim(coalesce(p_note, '')), 300);
  if not public.is_site_admin() then perform public.manager_guard('creator_other', (select x.user_id from public.creator_applications x where x.id = rid)); end if;
  select * into r from public.creator_applications where id = rid for update;
  if r.id is null then raise exception 'Not found'; end if;
  if r.status = 'needs_proof' then raise exception 'Already asked'; end if;
  if r.status <> 'pending' then raise exception 'Already reviewed'; end if;
  if r.user_id = (select auth.uid()) then raise exception 'Someone else has to review your own'; end if;
  if length(p_note) < 3 then raise exception 'Say what you need from them'; end if;
  update public.creator_applications set status = 'needs_proof', review_note = p_note, asked_at = now(), proof_added_at = null,
    proof_link = null, proof_path = null, proof_note = '', reviewed_by = (select auth.uid()) where id = rid;
  insert into public.mod_log (actor, action, target_id, reason) values ((select auth.uid()), 'creator_ask_proof', r.user_id, p_note);
  perform public.bc('user:' || r.user_id, 'creator_application', 'UPDATE', 'creator_applications', 'public', null, null);
end; $function$;

-- public.ask_verification_proof(rid uuid, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.ask_verification_proof(rid uuid, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.verification_requests;
begin
  if not public.is_staff() then raise exception 'Moderators only'; end if;
  select * into r from public.verification_requests where id = rid for update;
  if r.id is null then raise exception 'Not found'; end if;
  if r.user_id = auth.uid() and not public.is_site_admin() then
    raise exception 'You can''t review your own verification. Ask another moderator.';
  end if;
  if r.status not in ('pending', 'needs_proof') then raise exception 'Already reviewed'; end if;
  perform public.mod_guard('verify', null, null);
  update public.verification_requests set status = 'needs_proof',
    review_note = coalesce(nullif(btrim(p_note), ''), 'Put "yapper: ' || (select username from public.profiles where id = r.user_id) || '" in your channel bio or description so we can see it''s really you.'),
    asked_at = now(), proof_added_at = null, reviewed_by = auth.uid() where id = rid;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'verify_ask_proof', r.user_id, coalesce(p_note, ''));
  perform public.bc('user:' || r.user_id, 'verification', 'UPDATE', 'verification_requests', 'public', null, null);
end; $function$;

-- public.assign_mod_head(uid uuid, head_mod uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.assign_mod_head(uid uuid, head_mod uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cur uuid; hname text;
begin
  if not public.feature_on_for_me('assigned_mods') then raise exception 'Assigned mods aren''t on yet'; end if;
  if not (public.is_site_admin() or public.is_site_manager() or public.is_head_mod()) then
    raise exception 'Admins, Management and head mods only';
  end if;
  if not exists (select 1 from public.site_moderators where user_id = uid and not head) then
    raise exception 'They''re not a regular moderator';
  end if;
  if head_mod is not null and not exists (select 1 from public.site_moderators where user_id = head_mod and head and suspended_at is null) then
    raise exception 'That''s not an active head mod';
  end if;
  select head_id into cur from public.mod_assignments where user_id = uid;
  if head_mod is null then
    if cur is null then return; end if;
    execute 'del' || 'ete from public.mod_assignments where user_id = $1' using uid;
    insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'mod_unassigned', uid, '');
  else
    if cur = head_mod then return; end if;
    insert into public.mod_assignments (user_id, head_id, assigned_by) values (uid, head_mod, auth.uid())
      on conflict (user_id) do update set head_id = excluded.head_id, assigned_by = excluded.assigned_by, created_at = now();
    select username into hname from public.profiles where id = head_mod;
    insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'mod_assigned', uid, 'to ' || coalesce(hname, '?'));
  end if;
end $function$;

-- public.assigned_mods_list()  [security definer]
CREATE OR REPLACE FUNCTION public.assigned_mods_list()
 RETURNS TABLE(user_id uuid, head_id uuid, head boolean, suspended boolean, assigned_at timestamp with time zone, actions_7d integer, last_action timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sees_all boolean;
begin
  if not public.feature_on_for_me('assigned_mods') then return; end if;
  sees_all := public.is_site_admin() or public.is_site_manager() or public.is_head_mod();
  if not sees_all and not public.is_site_mod() then raise exception 'Staff only'; end if;
  return query
  select m.user_id, a.head_id, m.head, m.suspended_at is not null, a.created_at,
         case when sees_all then (select count(*)::int from public.mod_log l
                                   where l.actor = m.user_id and l.created_at > now() - interval '7 days') end,
         case when sees_all then (select max(l.created_at) from public.mod_log l where l.actor = m.user_id) end
    from public.site_moderators m
    left join public.mod_assignments a on a.user_id = m.user_id
   where sees_all or m.user_id = auth.uid()
   order by m.head desc, m.created_at;
end $function$;

-- public.attach_report_clip(rid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.attach_report_clip(rid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.reports; p text;
begin
  select * into r from public.reports where id = rid;
  if r.id is null or r.reporter_id is distinct from auth.uid() then raise exception 'Report not found'; end if;
  if r.details is null or r.details not like '[voice]%' then raise exception 'Only voice reports can have a clip'; end if;
  if not public.feature_on('voice_report_clips', r.server_id) then raise exception 'Voice clips aren''t available here yet'; end if;
  if r.created_at < now() - interval '10 minutes' then raise exception 'Too late to attach a clip'; end if;
  if r.voice_clip_path is not null then raise exception 'This report already has a clip'; end if;
  p := auth.uid()::text || '/' || rid::text || '.wav';
  if not exists (select 1 from storage.objects where bucket_id = 'report_clips' and name = p) then
    raise exception 'Clip upload not found';
  end if;
  update public.reports set voice_clip_path = p where id = rid;
end $function$;

-- public.audit_add(sid uuid, act text, kind text, tid uuid, tname text, extra jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.audit_add(sid uuid, act text, kind text, tid uuid, tname text, extra jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare actor uuid := auth.uid(); named boolean := true; staff boolean;
begin
  if actor is null or sid is null or coalesce(current_setting('yapper.bulk', true), '') = '1' then return; end if;
  if not exists (select 1 from public.servers where id = sid) then return; end if;
  staff := public.is_staff_user(actor);
  -- Staff in a server they don't run: the staff log always gets it, by name, flag or no flag.
  if staff and not public.server_perm(sid, 'manage_server') then
    perform public.staff_audit_add(sid, actor, act, kind, tid, tname, coalesce(extra, '{}'::jsonb) - 'staff');
  end if;
  if not public.feature_on('audit_log', sid) then return; end if;
  -- Staff with no footing in the server (not a member, not the owner) show as "Yapin' staff" rather than by name.
  if staff
     and not exists (select 1 from public.servers s where s.id = sid and s.owner_id = actor)
     and not exists (select 1 from public.server_members m where m.server_id = sid and m.user_id = actor) then
    named := false;
  end if;
  insert into public.server_audit_log (server_id, actor_id, action, target_kind, target_id, target_name, extra)
  values (sid, case when named then actor end, act, kind, tid, left(tname, 100),
          (coalesce(extra, '{}'::jsonb) - 'staff') || case when named then '{}'::jsonb else '{"staff": true}'::jsonb end);
end $function$;

-- public.audit_bans()  [security definer]
CREATE OR REPLACE FUNCTION public.audit_bans()
 RETURNS trigger
 LANGUAGE plpgsql
