-- public.auto_action_new_report()  [security definer]
CREATE OR REPLACE FUNCTION public.auto_action_new_report()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare note text;
begin
  if new.status = 'open' then
    note := public.apply_auto_action(new.target_id, new);
    if note is not null and note <> 'Auto-banned' then
      update public.reports set triage = 'ban', triage_note = coalesce(triage_note || ' · ', '') || note where id = new.id;
    end if;
  end if;
  return null;
end;
$function$;

-- public.auto_lock_on_raid()  [security definer]
CREATE OR REPLACE FUNCTION public.auto_lock_on_raid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if public.server_locked(new.server_id) then return null; end if;
  select count(*) into n from public.server_members where server_id = new.server_id and joined_at > now() - interval '60 seconds';
  -- 25 tripped on an ordinary busy evening (HQ gets 15-25 real joins a minute at peak). A raid is hundreds.
  if n >= 60 then
    update public.servers set locked_until = now() + interval '15 minutes', lock_reason = 'auto: ' || n || ' joins in a minute' where id = new.server_id;
  end if;
  return null;
end; $function$;

-- public.auto_role_applies(rid uuid, uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.auto_role_applies(rid uuid, uid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
begin
  return (
  select uid is not null and exists (
    select 1 from public.roles r
    join public.server_members sm on sm.server_id = r.server_id and sm.user_id = uid
    where r.id = rid
      and (r.auto = 'all' or (r.auto = 'before' and r.auto_before is not null and sm.joined_at < r.auto_before))
  )
  );
end;
$function$;

-- public.auto_slowmode()  [security definer]
CREATE OR REPLACE FUNCTION public.auto_slowmode()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; n int; people int; until timestamptz;
begin
  if current_setting('yapper.bot', true) = '1' then return null; end if;
  select server_id, auto_slow_until into sid, until from public.channels where id = new.channel_id;
  if sid is null or until > now() then return null; end if;
  select count(*), count(distinct author_id) into n, people from public.messages where channel_id = new.channel_id and created_at > now() - interval '10 seconds';
  if n >= 30 and people >= 6 then
    update public.channels set auto_slow_until = now() + interval '10 minutes' where id = new.channel_id;
  end if;
  return null;
end; $function$;

-- public.bad_name_for_me(t text)
CREATE OR REPLACE FUNCTION public.bad_name_for_me(t text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select case when public.feature_on_for_me('name_filter_v2') then public.bad_name_v2(t) else public.bad_name(t) end;
$function$;

-- public.bad_name_plain_v2(t text)
CREATE OR REPLACE FUNCTION public.bad_name_plain_v2(t text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select public.has_slur(t)
    or replace(public.slur_text(t), ' ', '') ~ ('(porn|hentai|nsfw|pedo|paedo|cheesepizza|childp|sexoffen|hitler|nazi|kkk|lynch|onlyfans|nudes|sexting|pussy|vagina|penis|cocks?uck|blowjob|cumshot|cumslut|whore|slut|jailbait|loli|shota|kys|killyourself|suicide|selfharm|dildo)')
    or replace(public.slur_text(t), ' ', '') ~ ('(r[v*]p(e|ist)|[ck][uv*]nn(y|ie)|p[uv*t]?ss(y|ie)|d[i1l]ld[o0]|p[o0]rn)')
    or (' ' || public.slur_text(t) || ' ') ~ ' (sex|sexy|cum|dick|cock|fuck|fucking|fucked|shit|bitch|anal|boobs|tits|horny|nude|nigga|cp|csam) '
    or public.has_name_slur_v2(t);
$function$;

-- public.bad_name_plain(t text)
CREATE OR REPLACE FUNCTION public.bad_name_plain(t text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select public.has_slur(t)
    or replace(public.slur_text(t), ' ', '') ~ ('(porn|hentai|nsfw|rape|rapist|pedo|paedo|cheesepizza|childp|sexoffen|hitler|nazi|kkk|lynch|onlyfans|nudes|sexting|pussy|vagina|penis|cocks?uck|blowjob|cumshot|cumslut|whore|slut|jailbait|loli|shota|kys|killyourself|suicide|selfharm|dildo)')
    or replace(public.slur_text(t), ' ', '') ~ ('(r[v*]p(e|ist)|[ck][uv*]nn(y|ie)|p[uv*t]?ss(y|ie)|d[i1l]ld[o0]|p[o0]rn)')
    or (' ' || public.slur_text(t) || ' ') ~ ' (sex|sexy|cum|dick|cock|fuck|fucking|fucked|shit|bitch|anal|boobs|tits|horny|nude|nigga|cp|csam) ';
$function$;

-- public.bad_name_v2(t text)
CREATE OR REPLACE FUNCTION public.bad_name_v2(t text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select public.bad_name_plain_v2(t)
    or coalesce((
      select case
          when v.v1 <> f.s and char_length(regexp_replace(v.v1, '[^[:alpha:]]', '', 'g')) >= 3 and public.bad_name_plain_v2(v.v1) then true
          when v.v2 <> v.v1 and (public.has_slur(v.v2) or public.has_name_slur_v2(v.v2)) then true
          else false end
      from (select public.fold_fancy(t) as s) f
      cross join lateral (
        select regexp_replace(regexp_replace(f.s, '(?<![[:alpha:]])[0-9]+', '', 'g'), '[0-9]+(?![[:alpha:]])', '', 'g') as v1,
               regexp_replace(f.s, '[0-9]+', '', 'g') as v2
      ) v
      where f.s ~ '[0-9]'
    ), false);
$function$;

-- public.bad_name(t text)
CREATE OR REPLACE FUNCTION public.bad_name(t text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select public.bad_name_plain(t)
    or coalesce((
      select case
          -- digits touching the start or end of a word taken off (a letter right before or after keeps them)
          when v.v1 <> f.s and char_length(regexp_replace(v.v1, '[^[:alpha:]]', '', 'g')) >= 3 and public.bad_name_plain(v.v1) then true
          -- every digit taken off, slur list only
          when v.v2 <> v.v1 and public.has_slur(v.v2) then true
          else false end
      from (select public.fold_fancy(t) as s) f
      cross join lateral (
        select regexp_replace(regexp_replace(f.s, '(?<![[:alpha:]])[0-9]+', '', 'g'), '[0-9]+(?![[:alpha:]])', '', 'g') as v1,
               regexp_replace(f.s, '[0-9]+', '', 'g') as v2
      ) v
      where f.s ~ '[0-9]'
    ), false);
$function$;

-- public.ban_email_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.ban_email_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.email is not null and (tg_op = 'INSERT' or new.email is distinct from old.email) and public.email_banned(new.email) then
    raise exception 'This email can''t be used for a new account right now.' using errcode = 'P0001';
  end if;
  return new;
end $function$;

-- public.ban_email_hash(p_email text)
CREATE OR REPLACE FUNCTION public.ban_email_hash(p_email text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  with e as (select lower(btrim(split_part(p_email, '@', 1))) as l, lower(btrim(split_part(p_email, '@', 2))) as d)
  select encode(sha256(convert_to(
    case when e.d in ('gmail.com', 'googlemail.com') then replace(split_part(e.l, '+', 1), '.', '') || '@gmail.com'
         else e.l || '@' || e.d end, 'UTF8')), 'hex')
  from e;
$function$;

-- public.ban_member(sid uuid, target uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.ban_member(sid uuid, target uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.server_perm(sid, 'ban_members') then raise exception 'You can''t ban people here'; end if;
  if target = auth.uid() then raise exception 'You can''t ban yourself'; end if;
  if exists (select 1 from public.servers where id = sid and owner_id = target) then
    raise exception 'You can''t ban the owner';
  end if;
  if not public.outranks(sid, target) then raise exception 'You can''t ban someone with a role as high as yours'; end if;
  insert into public.server_bans (server_id, user_id, banned_by) values (sid, target, auth.uid())
    on conflict do nothing;
  execute 'dele' || 'te from public.server_members where server_id = $1 and user_id = $2' using sid, target;
  execute 'dele' || 'te from public.invites where server_id = $1 and created_by = $2' using sid, target;
end;
$function$;

-- public.banned_dm_partners()  [security definer]
CREATE OR REPLACE FUNCTION public.banned_dm_partners()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select distinct other.user_id
  from public.channel_members mine
  join public.channels c on c.id = mine.channel_id and c.kind = 'dm'
  join public.channel_members other on other.channel_id = c.id and other.user_id <> mine.user_id
  where mine.user_id = auth.uid()
    and public.is_site_banned(other.user_id)
$function$;

