end; $function$;

-- public.bc_channel()  [security definer]
CREATE OR REPLACE FUNCTION public.bc_channel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid;
begin
  -- 593: threads aren't broadcast server-wide; a change to one (closed, reopened, retagged) goes to its own topic.
  if coalesce(new.kind, old.kind) = 'thread' then
    if tg_op = 'UPDATE' then perform public.bc('chan:' || new.id, 'channel', tg_op, tg_table_name, tg_table_schema, new, old); end if;
    return null;
  end if;
  sid := coalesce(new.server_id, old.server_id);
  if sid is not null then perform public.bc('server:' || sid, 'channel', tg_op, tg_table_name, tg_table_schema, new, old); end if;
  return null;
end; $function$;

