-- public.bc(topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record)  [security definer]
CREATE OR REPLACE FUNCTION public.bc(topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare mode text; url text; secret text;
begin
  select rt_mode into mode from public.app_settings limit 1;
  mode := coalesce(mode, 'supabase');
  if mode in ('supabase', 'both') then
    perform realtime.broadcast_changes(topic_name, event_name, operation, table_name, table_schema, new, old);
  end if;
  if mode in ('both', 'vps') then
    select decrypted_secret into url from vault.decrypted_secrets where name = 'rt_url';
    select decrypted_secret into secret from vault.decrypted_secrets where name = 'rt_secret';
    if url is null or secret is null then return; end if;
    perform net.http_post(
      url := url || '/publish',
      headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || secret),
      body := jsonb_build_object('topic', topic_name, 'event', event_name,
        'payload', jsonb_build_object('operation', operation, 'table', table_name, 'schema', table_schema,
          'record', case when new is null then null else to_jsonb(new) end,
          'old_record', case when old is null then null else to_jsonb(old) end)),
      timeout_milliseconds := 3000);
  end if;
end; $function$;

-- public.billing_event_claim(p_id text, p_kind text, p_business text)  [security definer]
CREATE OR REPLACE FUNCTION public.billing_event_claim(p_id text, p_kind text, p_business text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare st text; got text;
begin
  if coalesce(p_id, '') = '' then raise exception 'event id required'; end if;
  insert into public.plus_events (id, kind, business_id, state, claimed_at, attempts)
    values (p_id, left(coalesce(p_kind, ''), 80), p_business, 'pending', now(), 1)
    on conflict (id) do nothing
    returning id into got;
  if got is not null then return 'go'; end if;
  update public.plus_events set claimed_at = now(), attempts = attempts + 1, business_id = coalesce(business_id, p_business)
   where id = p_id and state = 'pending' and (claimed_at is null or claimed_at < now() - interval '2 minutes')
   returning id into got;
  if got is not null then return 'go'; end if;
  select state into st from public.plus_events where id = p_id;
  return case when st = 'done' then 'dup' else 'busy' end;
end $function$;

-- public.billing_event_finish(p_id text, p_ok boolean, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.billing_event_finish(p_id text, p_ok boolean, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.plus_events
     set state = case when p_ok then 'done' else 'pending' end,
         done_at = case when p_ok then now() else null end,
         claimed_at = case when p_ok then claimed_at else null end,
         note = coalesce(left(p_note, 500), note)
   where id = p_id;
$function$;

-- public.block_server_timeouts()  [security definer]
CREATE OR REPLACE FUNCTION public.block_server_timeouts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; u timestamptz;
begin
  if current_setting('yapper.bot', true) = '1' then return new; end if;
  select server_id into sid from public.channels where id = new.channel_id;
  if sid is null then return new; end if;
  u := public.server_timed_out(sid, new.author_id);
  if u is not null then
    raise exception 'You''re timed out in this server until %.', to_char(u at time zone 'UTC', 'YYYY-MM-DD HH24:MI "UTC"') using errcode = 'check_violation';
  end if;
  return new;
end; $function$;

-- public.block_throwaway_emails()  [security definer]
CREATE OR REPLACE FUNCTION public.block_throwaway_emails()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  dom text := split_part(lower(coalesce(new.email, '')), '@', 2);
begin
  if dom <> '' and exists (select 1 from public.blocked_email_domains b
                           where b.domain in (dom, public.signup_domain_base(dom))) then
    raise exception 'Sign-ups from that email provider aren''t allowed. Use a normal email address.' using errcode = 'check_violation';
  end if;
  return new;
end;
$function$;

-- public.block_user(other uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.block_user(other uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if other = auth.uid() then raise exception 'You can''t block yourself'; end if;
  if not exists (select 1 from public.profiles where id = other) then raise exception 'User not found'; end if;
  perform public.remove_friend(other);
  insert into public.blocks (blocker, blocked) values (auth.uid(), other) on conflict do nothing;
end;
$function$;

-- public.block_while_paused()  [security definer]
CREATE OR REPLACE FUNCTION public.block_while_paused()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.site_paused() and not public.is_site_admin() then
    raise exception '%', coalesce((select paused_message from public.app_settings limit 1), 'Yapper is paused for a short cleanup.') using errcode = 'check_violation';
  end if;
  return coalesce(new, old);
end;
$function$;

-- public.book_bot_boost(bid uuid, p_mult integer, p_source text, p_event text, p_by uuid, p_days integer)  [security definer]
CREATE OR REPLACE FUNCTION public.book_bot_boost(bid uuid, p_mult integer, p_source text, p_event text, p_by uuid DEFAULT NULL::uuid, p_days integer DEFAULT 7)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_start timestamptz;
begin
  if p_days is null or p_days < 1 or p_days > 60 then raise exception 'Pick 1 to 60 days'; end if;
  if p_mult is null or not (p_mult = any(public.bot_boost_tiers())) then raise exception 'Unknown boost tier'; end if;
  if not exists (select 1 from public.bots where id = bid) then raise exception 'Bot not found'; end if;
  perform pg_advisory_xact_lock(hashtext('bot_promo'));
  select greatest(now(), coalesce(max(ends_at), now())) into v_start from public.bot_promotions
    where bot_id = bid and kind = 'boost' and mult >= p_mult and ends_at > now();
  insert into public.bot_promotions (bot_id, starts_at, ends_at, source, stripe_event, created_by, kind, mult)
  values (bid, v_start, v_start + make_interval(days => p_days), p_source, p_event, p_by, 'boost', p_mult);
  return v_start;
end $function$;

-- public.book_bot_placement_sub(bid uuid, p_kind text, p_mult integer, p_sub text, p_event text, p_by uuid, p_days integer)  [security definer]
CREATE OR REPLACE FUNCTION public.book_bot_placement_sub(bid uuid, p_kind text, p_mult integer, p_sub text, p_event text, p_by uuid, p_days integer DEFAULT 31)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_start timestamptz;
begin
  if p_sub is null or p_sub !~ '^sub_[A-Za-z0-9]+$' then raise exception 'subscription id required'; end if;
  if p_kind not in ('promote', 'boost') then raise exception 'Unknown kind'; end if;
  if p_days is null or p_days < 1 or p_days > 60 then raise exception 'Pick 1 to 60 days'; end if;
  select starts_at into v_start from public.bot_promotions where stripe_sub = p_sub order by starts_at limit 1;
  if v_start is not null then return v_start; end if;
  if p_kind = 'promote' then
    v_start := public.book_bot_promotion(bid, 'stripe', p_event, p_by, p_days);
  else
    v_start := public.book_bot_boost(bid, p_mult, 'stripe', p_event, p_by, p_days);
  end if;
  update public.bot_promotions set stripe_sub = p_sub where stripe_event = p_event and stripe_sub is null;
  return v_start;
end $function$;

-- public.book_bot_promotion(bid uuid, p_source text, p_event text, p_by uuid, p_days integer)  [security definer]
CREATE OR REPLACE FUNCTION public.book_bot_promotion(bid uuid, p_source text, p_event text, p_by uuid DEFAULT NULL::uuid, p_days integer DEFAULT 7)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_start timestamptz;
begin
  if p_days is null or p_days < 1 or p_days > 60 then raise exception 'Pick 1 to 60 days'; end if;
  if not exists (select 1 from public.bots where id = bid) then raise exception 'Bot not found'; end if;
  perform pg_advisory_xact_lock(hashtext('bot_promo'));
  v_start := public.next_bot_promo_start(bid, p_days);
  insert into public.bot_promotions (bot_id, starts_at, ends_at, source, stripe_event, created_by)
  values (bid, v_start, v_start + make_interval(days => p_days), p_source, p_event, p_by);
  return v_start;
end $function$;

-- public.book_promotion_sub(sid uuid, p_kind text, p_mult integer, p_sub text, p_event text, p_by uuid, p_days integer)  [security definer]
CREATE OR REPLACE FUNCTION public.book_promotion_sub(sid uuid, p_kind text, p_mult integer, p_sub text, p_event text, p_by uuid, p_days integer DEFAULT 31)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_start timestamptz;
begin
  if p_sub is null or p_sub !~ '^sub_[A-Za-z0-9]+$' then raise exception 'subscription id required'; end if;
  if p_kind not in ('promote', 'boost') then raise exception 'Unknown kind'; end if;
  if p_days is null or p_days < 1 or p_days > 60 then raise exception 'Pick 1 to 60 days'; end if;
  select starts_at into v_start from public.server_promotions where stripe_sub = p_sub order by starts_at limit 1;
  if v_start is not null then return v_start; end if;
  v_start := public.book_promotion(sid, p_kind, 'stripe', p_event, p_by, p_days, coalesce(p_mult, 4));
  update public.server_promotions set stripe_sub = p_sub where stripe_event = p_event and stripe_sub is null;
  return v_start;
end $function$;

-- public.book_promotion(sid uuid, p_kind text, p_source text, p_event text, p_by uuid, p_days integer, p_mult integer)  [security definer]
CREATE OR REPLACE FUNCTION public.book_promotion(sid uuid, p_kind text, p_source text, p_event text, p_by uuid, p_days integer, p_mult integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_start timestamptz;
begin
  if p_kind = 'promote' then
    v_start := public.next_promo_start(sid);
  else
    if p_mult is null or not (p_mult = any(public.boost_tiers())) then raise exception 'Unknown boost tier'; end if;
    select greatest(now(), coalesce(max(ends_at), now())) into v_start from public.server_promotions
      where server_id = sid and kind = 'boost' and mult = p_mult and ends_at > now();
  end if;
  insert into public.server_promotions (server_id, starts_at, ends_at, source, stripe_event, created_by, kind, mult)
  values (sid, v_start, v_start + make_interval(days => p_days), p_source, p_event, p_by, p_kind, coalesce(p_mult, 4));
  return v_start;
end $function$;

-- public.book_promotion(sid uuid, p_kind text, p_source text, p_event text, p_by uuid, p_days integer)  [security definer]
CREATE OR REPLACE FUNCTION public.book_promotion(sid uuid, p_kind text, p_source text, p_event text, p_by uuid DEFAULT NULL::uuid, p_days integer DEFAULT 7)
 RETURNS timestamp with time zone
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.book_promotion(sid, p_kind, p_source, p_event, p_by, p_days, 4);
$function$;

-- public.boost_lifts()
CREATE OR REPLACE FUNCTION public.boost_lifts()
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$ select 6 $function$;

-- public.boost_max()
CREATE OR REPLACE FUNCTION public.boost_max()
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$ select 5 $function$;

-- public.boost_tiers()
CREATE OR REPLACE FUNCTION public.boost_tiers()
 RETURNS integer[]
 LANGUAGE sql
 IMMUTABLE
AS $function$ select array[2, 4, 8] $function$;

-- public.bootstrap_fast()  [security definer]
CREATE OR REPLACE FUNCTION public.bootstrap_fast()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  vis public.channels[] := array(select c from public.visible_server_channels_fast(null) c);
  lazy boolean := public.feature_on_for_me('lazy_boot');
begin
  return (
  with my_servers as (
    select sm.server_id from public.server_members sm where sm.user_id = auth.uid()
  ),
  my_cm as (
    select cm.channel_id, cm.hidden_at from public.channel_members cm where cm.user_id = auth.uid()
  ),
  dm_chans as (
    select c.* from public.channels c
    join my_cm on my_cm.channel_id = c.id
    where c.server_id is null
      and (my_cm.hidden_at is null or c.last_message_at > my_cm.hidden_at)
  ),
  dm_members as (
    select cm.channel_id, cm.user_id from public.channel_members cm where cm.channel_id in (select id from dm_chans)
  ),
  members as (
    select * from public.server_members_slice((select coalesce(array_agg(server_id), '{}'::uuid[]) from my_servers))
  ),
  small as (
    select server_id from members where not lazy group by server_id having count(*) <= 300
  ),
  fr as (
    select requester, addressee, status from public.friendships where requester = auth.uid() or addressee = auth.uid()
  ),
  bl as (select blocked from public.blocks where blocker = auth.uid()),
  dr as (select from_id from public.dm_requests where to_id = auth.uid() order by created_at desc limit 100),
  pids as (
    select user_id as id from dm_members
    union select requester from fr
    union select addressee from fr
    union select blocked from bl
    union select from_id from dr
    union select user_id from members where server_id in (select server_id from small)
    union select auth.uid()
  ),
  plain_roles as (
    select r.id from public.roles r
    where r.server_id in (select server_id from my_servers) and coalesce(r.auto, 'none') = 'none'
  ),
  assigned as (
    select mr.server_id, mr.user_id, mr.role_id from public.member_roles mr
    join plain_roles pr on pr.id = mr.role_id
    union
    select mr.server_id, mr.user_id, mr.role_id from public.member_roles mr
    where mr.manual and mr.server_id in (select server_id from my_servers)
  )
  select jsonb_build_object(
    'now', now(),
    'profiles', (select coalesce(jsonb_agg(to_jsonb(p)), '[]'::jsonb) from (
      select id, username, created_at, bio, avatar_path, banner_path, banner_x, banner_y, avatar_x, avatar_y,
             avatar_zoom, avatar_rot, banner_zoom, links, verified_as, verified_hidden, badges, display_name,
             pronouns, accent_color, accent_color2, plus_until, plus_badge_hidden, dms_from, server_tag, tag, case when profiles.id = (select auth.uid()) then server_order end as server_order, shown_badge, verify_required, profile_effect, custom_status, avatar_deco, discriminator, name_style
      from public.profiles where id in (select id from pids) limit 1500) p),
    'dm_channels', (select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb) from dm_chans c),
    'dm_members', (select coalesce(jsonb_agg(jsonb_build_array(channel_id, user_id)), '[]'::jsonb) from dm_members),
    'calls', (select coalesce(jsonb_agg(jsonb_build_object('channel_id', k.channel_id, 'started_by', k.started_by, 'started_at', k.started_at)), '[]'::jsonb) from public.calls k where k.ended_at is null and k.channel_id in (select id from dm_chans)),
    'servers', (select coalesce(jsonb_agg(to_jsonb(s)), '[]'::jsonb) from public.servers s where s.id in (select server_id from my_servers)),
    'channels', (select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb) from unnest(vis) c),
    'channel_roles', (select coalesce(jsonb_agg(jsonb_build_array(channel_id, role_id)), '[]'::jsonb) from public.channel_roles where server_id in (select server_id from my_servers)),
    'post_roles', (select coalesce(jsonb_agg(jsonb_build_array(channel_id, role_id)), '[]'::jsonb) from public.channel_post_roles where server_id in (select server_id from my_servers)),
    'roles', (select coalesce(jsonb_agg(to_jsonb(r)), '[]'::jsonb) from public.roles r where r.server_id in (select server_id from my_servers)),
    'member_roles', (select coalesce(jsonb_agg(jsonb_build_array(a.server_id, a.user_id, a.role_id)), '[]'::jsonb) from assigned a),
    'members', (select coalesce(jsonb_object_agg(server_id, arr), '{}'::jsonb) from (
      select server_id, jsonb_agg(case when nickname is null then jsonb_build_array(user_id, extract(epoch from joined_at)::bigint)
                                       else jsonb_build_array(user_id, extract(epoch from joined_at)::bigint, nickname) end) as arr
      from members group by server_id) x),
    'member_counts', (select coalesce(jsonb_object_agg(server_id, n), '{}'::jsonb) from public.server_member_counts((select coalesce(array_agg(server_id), '{}'::uuid[]) from my_servers))),
    'friends', (select coalesce(jsonb_agg(jsonb_build_array(requester, addressee, status)), '[]'::jsonb) from fr),
    'blocks', (select coalesce(jsonb_agg(blocked), '[]'::jsonb) from bl),
    'dm_requests', (select coalesce(jsonb_agg(from_id), '[]'::jsonb) from dr),
    'unread', (select coalesce(jsonb_agg(to_jsonb(u)), '[]'::jsonb) from public.unread_counts_for(vis) u),
    'server_mutes', (select coalesce(jsonb_agg(server_id), '[]'::jsonb) from public.server_mutes where user_id = auth.uid()),
    'flags', (select coalesce(jsonb_agg(to_jsonb(f)), '[]'::jsonb) from public.my_flags() f),
    'emojis', (select coalesce(jsonb_agg(to_jsonb(e)), '[]'::jsonb) from public.emojis e where e.server_id in (select server_id from my_servers)),
    'categories', (select coalesce(jsonb_agg(to_jsonb(k)), '[]'::jsonb) from public.channel_categories k where k.server_id in (select server_id from my_servers)),
    'is_admin', exists (select 1 from public.site_admins where user_id = auth.uid()),
    'mod', (select to_jsonb(m) from (select suspended_at from public.site_moderators where user_id = auth.uid()) m),
    'ban', (select to_jsonb(b) from (select reason, created_at, expires_at from public.site_bans where user_id = auth.uid()) b)
  ));
end
$function$;

-- public.bootstrap_v1()  [security definer]
CREATE OR REPLACE FUNCTION public.bootstrap_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with my_servers as (
    select sm.server_id from public.server_members sm where sm.user_id = auth.uid()
  ),
  my_cm as (
    select cm.channel_id, cm.hidden_at from public.channel_members cm where cm.user_id = auth.uid()
  ),
  dm_chans as (
    select c.* from public.channels c
    join my_cm on my_cm.channel_id = c.id
    where c.server_id is null
      and (my_cm.hidden_at is null or c.last_message_at > my_cm.hidden_at)
  ),
  dm_members as (
    select cm.channel_id, cm.user_id from public.channel_members cm where cm.channel_id in (select id from dm_chans)
  ),
  members as (
    select * from public.server_members_slice((select coalesce(array_agg(server_id), '{}'::uuid[]) from my_servers))
  ),
  small as (
    select server_id from members group by server_id having count(*) <= 300
  ),
  fr as (
    select requester, addressee, status from public.friendships where requester = auth.uid() or addressee = auth.uid()
  ),
  bl as (select blocked from public.blocks where blocker = auth.uid()),
  dr as (select from_id from public.dm_requests where to_id = auth.uid() order by created_at desc limit 100),
  pids as (
    select user_id as id from dm_members
    union select requester from fr
    union select addressee from fr
    union select blocked from bl
    union select from_id from dr
    union select user_id from members where server_id in (select server_id from small)
    union select auth.uid()
  )
  select jsonb_build_object(
    'now', now(),
    'profiles', (select coalesce(jsonb_agg(to_jsonb(p)), '[]'::jsonb) from (
      select id, username, created_at, bio, avatar_path, banner_path, banner_x, banner_y, avatar_x, avatar_y,
             avatar_zoom, avatar_rot, banner_zoom, links, verified_as, verified_hidden, badges, display_name,
             pronouns, accent_color, accent_color2, plus_until, plus_badge_hidden, dms_from, server_tag, tag, case when profiles.id = (select auth.uid()) then server_order end as server_order, shown_badge, verify_required, profile_effect, custom_status, avatar_deco, discriminator, name_style
      from public.profiles where id in (select id from pids) limit 1500) p),
    'dm_channels', (select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb) from dm_chans c),
    'dm_members', (select coalesce(jsonb_agg(jsonb_build_array(channel_id, user_id)), '[]'::jsonb) from dm_members),
    'calls', (select coalesce(jsonb_agg(jsonb_build_object('channel_id', k.channel_id, 'started_by', k.started_by, 'started_at', k.started_at)), '[]'::jsonb) from public.calls k where k.ended_at is null and k.channel_id in (select id from dm_chans)),
    'servers', (select coalesce(jsonb_agg(to_jsonb(s)), '[]'::jsonb) from public.servers s where s.id in (select server_id from my_servers)),
    'channels', (select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb) from public.my_visible_server_channels() c),
    'channel_roles', (select coalesce(jsonb_agg(jsonb_build_array(channel_id, role_id)), '[]'::jsonb) from public.channel_roles where server_id in (select server_id from my_servers)),
    'post_roles', (select coalesce(jsonb_agg(jsonb_build_array(channel_id, role_id)), '[]'::jsonb) from public.channel_post_roles where server_id in (select server_id from my_servers)),
    'roles', (select coalesce(jsonb_agg(to_jsonb(r)), '[]'::jsonb) from public.roles r where r.server_id in (select server_id from my_servers)),
    'member_roles', (select coalesce(jsonb_agg(jsonb_build_array(mr.server_id, mr.user_id, mr.role_id)), '[]'::jsonb)
      from public.member_roles mr
      where mr.server_id in (select server_id from my_servers)
        and not exists (select 1 from public.roles r where r.id = mr.role_id and r.auto <> 'none')),
    'members', (select coalesce(jsonb_object_agg(server_id, arr), '{}'::jsonb) from (
      select server_id, jsonb_agg(case when nickname is null then jsonb_build_array(user_id, extract(epoch from joined_at)::bigint)
                                       else jsonb_build_array(user_id, extract(epoch from joined_at)::bigint, nickname) end) as arr
      from members group by server_id) x),
    'member_counts', (select coalesce(jsonb_object_agg(server_id, n), '{}'::jsonb) from public.server_member_counts((select coalesce(array_agg(server_id), '{}'::uuid[]) from my_servers))),
    'friends', (select coalesce(jsonb_agg(jsonb_build_array(requester, addressee, status)), '[]'::jsonb) from fr),
    'blocks', (select coalesce(jsonb_agg(blocked), '[]'::jsonb) from bl),
    'dm_requests', (select coalesce(jsonb_agg(from_id), '[]'::jsonb) from dr),
    'unread', (select coalesce(jsonb_agg(to_jsonb(u)), '[]'::jsonb) from public.unread_counts_v1() u),
    'server_mutes', (select coalesce(jsonb_agg(server_id), '[]'::jsonb) from public.server_mutes where user_id = auth.uid()),
    'flags', (select coalesce(jsonb_agg(to_jsonb(f)), '[]'::jsonb) from public.my_flags() f),
    'emojis', (select coalesce(jsonb_agg(to_jsonb(e)), '[]'::jsonb) from public.emojis e where e.server_id in (select server_id from my_servers)),
    'categories', (select coalesce(jsonb_agg(to_jsonb(k)), '[]'::jsonb) from public.channel_categories k where k.server_id in (select server_id from my_servers)),
    'is_admin', exists (select 1 from public.site_admins where user_id = auth.uid()),
    'mod', (select to_jsonb(m) from (select suspended_at from public.site_moderators where user_id = auth.uid()) m),
    'ban', (select to_jsonb(b) from (select reason, created_at, expires_at from public.site_bans where user_id = auth.uid()) b)
  );
$function$;

-- public.bootstrap()  [security definer]
CREATE OR REPLACE FUNCTION public.bootstrap()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.feature_on_for_me('fast_startup') then
    return public.bootstrap_fast();
  end if;
  return public.bootstrap_v1();
end
$function$;

-- public.bot_add_targets(bid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_add_targets(bid uuid)
 RETURNS TABLE(id uuid, name text, icon_path text, added boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select s.id, s.name, s.icon_path, exists (select 1 from public.bot_servers bs where bs.bot_id = bid and bs.server_id = s.id)
  from public.server_members m
  join public.servers s on s.id = m.server_id
  where m.user_id = (select auth.uid())
    and public.server_perm(s.id, 'manage_server')
    and public.feature_on('bot_api', s.id)
  order by lower(s.name)
  limit 200;
$function$;

-- public.bot_add_to_server(bid uuid, sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_add_to_server(bid uuid, sid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b public.bots;
begin
  if not public.feature_on('bot_api', sid) then raise exception 'Bots aren''t available here yet'; end if;
  if not public.server_perm(sid, 'manage_server') then raise exception 'Only server managers can add bots'; end if;
  select * into b from public.bots where id = bid;
  if b.id is null or not (b.owner_id = auth.uid() or ((b.public or b.unlisted) and b.verified_at is not null)) then
    if b.id is null or not b.shareable or not public.feature_on('bot_share_add', sid) or public.is_site_banned(b.owner_id) then
      raise exception 'That bot isn''t available (community bots must be verified by Yapper first)';
    end if;
    perform 1 from public.bots where id = bid for update;
    if (select count(*) from public.bot_servers where bot_id = bid and added_by is distinct from b.owner_id) >= 10
       and not exists (select 1 from public.bot_servers where bot_id = bid and server_id = sid) then
      raise exception 'That bot is in 10 servers already. It needs to be verified by Yapper before more servers can add it';
    end if;
  end if;
  if (select count(*) from public.bot_servers where server_id = sid) >= 25 then raise exception 'That server has enough bots already'; end if;
  if b.owner_id is distinct from auth.uid() and not public.is_site_admin()
     and not exists (select 1 from public.bot_servers where bot_id = bid and server_id = sid)
     and (select count(distinct x.server_id) from public.bot_servers x join public.bots xb on xb.id = x.bot_id
          where x.added_by = auth.uid() and x.added_at > now() - interval '24 hours'
            and xb.owner_id is distinct from auth.uid() and x.server_id <> sid) >= 5 then
    raise exception 'You already added bots to 5 servers today. Try again tomorrow';
  end if;
  insert into public.bot_servers (bot_id, server_id, added_by) values (bid, sid, auth.uid()) on conflict do nothing;
  perform set_config('yapper.bot', '1', true);
  insert into public.server_members (server_id, user_id) values (sid, bid) on conflict do nothing;
  perform set_config('yapper.bot', '', true);
end $function$;

-- public.bot_api_edit(bid uuid, mid uuid, body text, p_embeds jsonb, set_embeds boolean, p_components jsonb, set_components boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_api_edit(bid uuid, mid uuid, body text, p_embeds jsonb, set_embeds boolean, p_components jsonb DEFAULT NULL::jsonb, set_components boolean DEFAULT false)
 RETURNS public.messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m public.messages; sid uuid; new_c jsonb; new_e jsonb; new_b text;
begin
  select * into m from public.messages where id = mid and author_id = bid;
  if m.id is null then raise exception 'Bots can only edit their own messages'; end if;
  select server_id into sid from public.channels where id = m.channel_id;
  new_c := case when set_components then p_components else m.components end;
  new_e := case when set_embeds then p_embeds else m.embeds end;
  new_b := case when body is null then m.content else body end;
  if public.components_v2(m.components) or public.components_v2(new_c) then
    -- 315: Components V2. Like Discord, a V2 message stays V2, and never gets content or embeds.
    if not public.components_v2(new_c) then raise exception 'Components V2 messages stay V2: send components with flags 32768'; end if;
    if set_components and not public.feature_on('bot_components_v2', sid) then raise exception 'Components V2 messages aren''t available in this server yet'; end if;
    if btrim(coalesce(new_b, '')) <> '' or new_e is not null then raise exception 'Components V2 messages take no content or embeds: put text in a text display'; end if;
  else
    if set_embeds and p_embeds is not null and not public.feature_on('bot_embeds', sid) then raise exception 'Embeds aren''t available in this server yet'; end if;
    if set_components and p_components is not null and not public.feature_on('bot_buttons', sid) then raise exception 'Buttons aren''t available in this server yet'; end if;
    if btrim(coalesce(new_b, '')) = '' and new_e is null then
      raise exception 'A message needs content or embeds';
    end if;
  end if;
  perform set_config('yapper.bot', '1', true);
  update public.messages set content = case when body is null then content else left(body, 2000) end,
    embeds = case when set_embeds then p_embeds else embeds end,
    components = case when set_components then p_components else components end
  where id = mid returning * into m;
  perform set_config('yapper.bot', '', true);
  return m;
end $function$;

-- public.bot_api_post(bid uuid, cid uuid, body text, reply uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_api_post(bid uuid, cid uuid, body text, reply uuid DEFAULT NULL::uuid)
 RETURNS public.messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m public.messages; recent int;
begin
  if not public.bot_channel_visible(bid, cid) then raise exception 'No such channel, or the bot cannot see it'; end if;
  if exists (select 1 from public.channels c where c.id = cid and c.kind = 'voice' and not public.feature_on('voice_chat', c.server_id)) then
    raise exception 'Chat in voice channels isn''t on in this server';
  end if;
  -- 212: per-server and overall limits (verified bots get more, command replies don't count overall).
  perform public.bot_send_gate(bid, cid, reply);
  if body is null or btrim(body) = '' then raise exception 'Empty message'; end if;
  perform set_config('yapper.bot', '1', true);
  insert into public.messages (channel_id, author_id, content, reply_to_id) values (cid, bid, left(body, 2000), reply) returning * into m;
  perform set_config('yapper.bot', '', true);
  return m;
end $function$;

-- public.bot_api_send(bid uuid, cid uuid, body text, reply uuid, p_embeds jsonb, p_components jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_api_send(bid uuid, cid uuid, body text, reply uuid DEFAULT NULL::uuid, p_embeds jsonb DEFAULT NULL::jsonb, p_components jsonb DEFAULT NULL::jsonb)
 RETURNS public.messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m public.messages; recent int; sid uuid;
begin
  if not public.bot_channel_visible(bid, cid) then raise exception 'No such channel, or the bot cannot see it'; end if;
  if exists (select 1 from public.channels c where c.id = cid and c.kind = 'voice' and not public.feature_on('voice_chat', c.server_id)) then
    raise exception 'Chat in voice channels isn''t on in this server';
  end if;
  -- Lock the bot's own row first: one send per bot at a time (parallel calls can't all slip under the limit),
  -- and taken before the insert so it never waits while holding locks the message triggers took.
  -- A failed send below rolls this back too.
  -- 212: per-server and overall limits (verified bots get more, command replies don't count overall).
  perform public.bot_send_gate(bid, cid, reply);
  select server_id into sid from public.channels where id = cid;
  if public.components_v2(p_components) then
    -- 315: Components V2. The layout is the whole message.
    if not public.feature_on('bot_components_v2', sid) then raise exception 'Components V2 messages aren''t available in this server yet'; end if;
    if btrim(coalesce(body, '')) <> '' or p_embeds is not null then raise exception 'Components V2 messages take no content or embeds: put text in a text display'; end if;
  else
    if p_embeds is not null and not public.feature_on('bot_embeds', sid) then raise exception 'Embeds aren''t available in this server yet'; end if;
    if p_components is not null and not public.feature_on('bot_buttons', sid) then raise exception 'Buttons aren''t available in this server yet'; end if;
    if (body is null or btrim(body) = '') and p_embeds is null then raise exception 'Empty message: send content or embeds'; end if;
  end if;
  perform set_config('yapper.bot', '1', true);
  insert into public.messages (channel_id, author_id, content, reply_to_id, embeds, components)
  values (cid, bid, left(coalesce(body, ''), 2000), reply, p_embeds, p_components) returning * into m;
  perform set_config('yapper.bot', '', true);
  return m;
end $function$;

-- public.bot_boost_tiers()
CREATE OR REPLACE FUNCTION public.bot_boost_tiers()
 RETURNS integer[]
 LANGUAGE sql
 IMMUTABLE
AS $function$ select array[2, 4, 8] $function$;

-- public.bot_cfg(sid uuid, p_bot text)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_cfg(sid uuid, p_bot text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select config from public.server_bots where server_id = sid and bot = p_bot and enabled
$function$;

-- public.bot_channel_history_ok(bid uuid, cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_channel_history_ok(bid uuid, cid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select case when c.server_id is null then true
                               when c.kind = 'voice' and not public.feature_on('voice_chat', c.server_id) then false
                               when exists (select 1 from public.feature_flags f where f.key = 'channel_perms'
                                            and (f.mode = 'everyone' or (f.mode = 'test' and c.server_id = any(f.servers))))
                                    and exists (select 1 from public.channel_overrides o where o.channel_id = c.id or o.category_id = c.category_id)
                                 then public.channel_perm_of(bid, c.id, 'read_history', public.bot_server_perm(bid, c.server_id, 'read_history'))
                               else public.bot_server_perm(bid, c.server_id, 'read_history') end
                   from public.channels c where c.id = coalesce((select t.parent_id from public.channels t where t.id = cid), cid) /* 593: */), false);
$function$;

-- public.bot_channel_visible(bid uuid, cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_channel_visible(bid uuid, cid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.channels c
    where c.id = coalesce((select t.parent_id from public.channels t where t.id = cid), cid) /* 593: */
      and (
        (c.server_id is not null and exists (select 1 from public.bot_servers bs where bs.bot_id = bid and bs.server_id = c.server_id)
          and case when exists (select 1 from public.feature_flags f where f.key = 'channel_perms'
                              and (f.mode = 'everyone' or (f.mode = 'test' and c.server_id = any(f.servers))))
                  and exists (select 1 from public.channel_overrides o where o.channel_id = c.id or o.category_id = c.category_id)
            then public.channel_perm_of(bid, c.id, 'view_channel',
                   exists (select 1 from public.channel_members cm where cm.channel_id = c.id and cm.user_id = bid)
                   or exists (select 1 from public.channel_roles cr join public.member_roles mr on mr.role_id = cr.role_id and mr.user_id = bid where cr.channel_id = c.id))
            else (not c.private
               or exists (select 1 from public.channel_members cm where cm.channel_id = c.id and cm.user_id = bid)
               or exists (select 1 from public.channel_roles cr join public.member_roles mr on mr.role_id = cr.role_id and mr.user_id = bid where cr.channel_id = c.id)
               /* 662: */ or exists (select 1 from public.member_roles mr join public.roles r on r.id = mr.role_id
                                     where mr.server_id = c.server_id and mr.user_id = bid
                                       and coalesce((r.perms ->> 'administrator')::boolean, false)))
          end)
        or (c.server_id is null and exists (select 1 from public.channel_members cm where cm.channel_id = c.id and cm.user_id = bid))
      )
  );
$function$;

-- public.bot_directory(q text, cat text, sort text)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_directory(q text DEFAULT ''::text, cat text DEFAULT ''::text, sort text DEFAULT 'popular'::text)
 RETURNS TABLE(id uuid, name text, description text, category text, owner_id uuid, owner_name text, owner_plus boolean, servers bigint, commands bigint, online boolean, created_at timestamp with time zone, verified_at timestamp with time zone, command_list jsonb, boost integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select b.id, b.name, b.description, b.category, b.owner_id, coalesce(p.display_name, p.username), coalesce(p.plus_until > now(), false),
         o.servers,
         (select count(*) from public.bot_commands c where c.bot_id = b.id),
         (b.last_poll_at > now() - interval '90 seconds' or b.last_event_at > now() - interval '5 minutes'),
         b.created_at, b.verified_at,
         coalesce((select jsonb_agg(jsonb_build_object('name', c.name, 'description', c.description) order by c.name)
                   from (select * from public.bot_commands c where c.bot_id = b.id order by c.name limit 25) c), '[]'::jsonb),
         o.boost
  from public.bot_order(null, null, public.feature_on_for_me('bot_promoted')) o
  join public.bots b on b.id = o.id
  join public.profiles p on p.id = b.owner_id
  where (coalesce(cat, '') = '' or b.category = cat)
    and (coalesce(q, '') = '' or b.name ilike '%' || q || '%' or b.description ilike '%' || q || '%'
         or exists (select 1 from public.bot_commands c where c.bot_id = b.id and c.name ilike '%' || q || '%'))
  order by case when sort = 'new' then extract(epoch from b.verified_at) else 0 end desc,
           case when sort = 'name' then lower(b.name) end asc,
           o.pos, b.name
  limit 100;
$function$;

-- public.bot_events_cleanup()  [security definer]
CREATE OR REPLACE FUNCTION public.bot_events_cleanup()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int := 0; k int;
begin
  loop
    execute 'del' || 'ete from public.bot_events where id in (select id from public.bot_events where created_at < now() - interval ''1 day'' limit 20000)';
    get diagnostics k = row_count;
    n := n + k;
    exit when k < 20000 or n >= 200000;
  end loop;
  return n;
end $function$;

-- public.bot_goodbye()  [security definer]
CREATE OR REPLACE FUNCTION public.bot_goodbye()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cfg jsonb; cid uuid; tpl text; nm text;
begin
  if exists (select 1 from public.bots where id = old.user_id) or exists (select 1 from public.bot_accounts where user_id = old.user_id) then return null; end if;
  select config into cfg from public.server_bots where server_id = old.server_id and bot = 'welcome' and enabled;
  if cfg is null or not public.server_plus_on(old.server_id) then return null; end if;
  cid := nullif(cfg ->> 'leave_channel_id', '')::uuid;
  if cid is null or not exists (select 1 from public.channels where id = cid and server_id = old.server_id and kind = 'text') then return null; end if;
  select coalesce(display_name, username) into nm from public.profiles where id = old.user_id;
  tpl := coalesce(nullif(cfg ->> 'leave_message', ''), '{name} left. See you around 👋');
  tpl := replace(tpl, '{name}', coalesce(nm, 'someone'));
  tpl := replace(tpl, '{server}', (select name from public.servers where id = old.server_id));
  tpl := replace(tpl, '{count}', (select count(*)::text from public.server_members where server_id = old.server_id));
  perform public.bot_say(cid, 'welcome', tpl);
  return null;
end $function$;

-- public.bot_helper(sid uuid, cid uuid, uid uuid, body text)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_helper(sid uuid, cid uuid, uid uuid, body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cmd text; arg text; r record; nm text; parts text[]; n int; d int; i int; tot int := 0; rolls text := ''; rec record; line text;
begin
  -- Coming back from AFK, and mentioning someone who is AFK.
  update public.bot_afk set away = false where server_id = sid and user_id = uid and away
    and lower(body) not like '!afk%';
  if found then perform public.bot_say(cid, 'helper', 'Welcome back, <@' || uid::text || '>. Your AFK is off.'); end if;
  for r in select a.user_id, a.reason, a.since from public.bot_afk a where a.server_id = sid and a.away
             and body like '%<@' || a.user_id::text || '>%' limit 3 loop
    select coalesce(display_name, username) into nm from public.profiles where id = r.user_id;
    perform public.bot_say(cid, 'helper', '💤 ' || coalesce(nm, 'They') || ' is AFK' || coalesce(': ' || r.reason, '') || ' (since ' || to_char(r.since, 'HH24:MI') || ' UTC)');
  end loop;

  if left(body, 1) <> '!' then return; end if;
  cmd := lower(split_part(body, ' ', 1));
  arg := btrim(substr(body, length(cmd) + 2));
  if cmd = '!help' then
    perform public.bot_say(cid, 'helper', '**Helper commands**' || E'\n' ||
      '`!8ball question` · `!roll` or `!roll 2d6` · `!flip` · `!choose a | b | c` · `!afk reason` · `!rank` · `!top`');
  elsif cmd = '!8ball' then
    perform public.bot_say(cid, 'helper', '🎱 ' || (array['It is certain.','Without a doubt.','Yes.','Most likely.','Signs point to yes.','Ask again later.','Better not tell you now.','Cannot predict now.','Don''t count on it.','My reply is no.','Very doubtful.','No.'])[1 + floor(random() * 12)::int]);
  elsif cmd = '!flip' then
    perform public.bot_say(cid, 'helper', '🪙 ' || (case when random() < 0.5 then 'Heads' else 'Tails' end));
  elsif cmd = '!roll' then
    n := 1; d := 6;
    if arg ~ '^\d{1,2}d\d{1,4}$' then n := split_part(arg, 'd', 1)::int; d := split_part(arg, 'd', 2)::int; elsif arg ~ '^\d{1,4}$' then d := arg::int; end if;
    n := least(greatest(n, 1), 20); d := least(greatest(d, 2), 1000);
    for i in 1 .. n loop
      i := i; rec := null;
      tot := tot + (1 + floor(random() * d)::int);
    end loop;
    perform public.bot_say(cid, 'helper', '🎲 ' || n || 'd' || d || ' → **' || tot || '**');
  elsif cmd = '!choose' then
    parts := regexp_split_to_array(arg, '\s*\|\s*');
    if coalesce(array_length(parts, 1), 0) < 2 then
      perform public.bot_say(cid, 'helper', 'Give me options: `!choose pizza | sushi | tacos`');
    else
      perform public.bot_say(cid, 'helper', '🤔 I pick **' || btrim(parts[1 + floor(random() * array_length(parts, 1))::int]) || '**');
    end if;
  elsif cmd = '!afk' then
    insert into public.bot_afk (server_id, user_id, reason, since, away) values (sid, uid, nullif(left(arg, 100), ''), now(), true)
      on conflict (server_id, user_id) do update set reason = excluded.reason, since = now(), away = true;
    perform public.bot_say(cid, 'helper', '💤 <@' || uid::text || '> is now AFK' || coalesce(': ' || nullif(left(arg, 100), ''), ''));
  elsif cmd = '!rank' then
    select * into rec from public.server_xp where server_id = sid and user_id = uid;
    if rec.user_id is null then
      perform public.bot_say(cid, 'levels', 'No XP yet. Chat a bit first!');
    else
      perform public.bot_say(cid, 'levels', '<@' || uid::text || '> is **level ' || rec.level || '** with ' || rec.xp || ' XP. Next level at ' || (((rec.level + 1) ^ 2) * 100)::int || ' XP.');
    end if;
  elsif cmd = '!top' then
    line := '**Top chatters**' || E'\n';
    i := 0;
    for rec in select x.user_id, x.xp, x.level, coalesce(p.display_name, p.username) as nm from public.server_xp x join public.profiles p on p.id = x.user_id
               where x.server_id = sid and exists (select 1 from public.server_members top_m where top_m.server_id = sid and top_m.user_id = x.user_id) and not exists (select 1 from public.site_bans top_b where top_b.user_id = x.user_id and (top_b.expires_at is null or top_b.expires_at > now())) order by x.xp desc limit 10 loop
      i := i + 1;
      line := line || i || '. ' || rec.nm || ' · level ' || rec.level || ' · ' || rec.xp || ' XP' || E'\n';
    end loop;
    if i = 0 then line := 'Nobody has XP yet.'; end if;
    perform public.bot_say(cid, 'levels', line);
  end if;
end; $function$;

-- public.bot_hosting_apply_report(p_runner text, p_bots jsonb, p_plus_free boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_hosting_apply_report(p_runner text, p_bots jsonb, p_plus_free boolean DEFAULT false)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r jsonb; bid uuid; st text; why text; stop uuid[] := '{}'; h record;
begin
  if jsonb_typeof(p_bots) is distinct from 'array' then return stop; end if;
  for r in select value from jsonb_array_elements(p_bots) limit 500 loop
    if coalesce(r->>'id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then continue; end if;
    bid := (r->>'id')::uuid;
    select * into h from public.bot_hosting where bot_id = bid;
    if not found or h.runner_id is distinct from p_runner then stop := stop || bid; continue; end if;
    st := r->>'status';
    if st not in ('stopped', 'starting', 'running', 'crashed', 'oom') then st := h.status; end if;
    update public.bot_hosting set
      status = st,
      crash_count = case when r->>'crash_count' ~ '^\d{1,6}$' then (r->>'crash_count')::int else crash_count end,
      oom_count = case when r->>'oom_count' ~ '^\d{1,6}$' then (r->>'oom_count')::int else oom_count end,
      updated_at = now()
    where bot_id = bid;
    if r->>'started_at' ~ '^\d{4}-\d\d-\d\dT[0-9:.]+(Z|[+-]\d\d:?\d\d)?$' then
      begin
        update public.bot_hosting set started_at = (r->>'started_at')::timestamptz where bot_id = bid;
      exception when others then null;
      end;
    end if;
    why := public.bot_hosting_stop_reason(bid, p_plus_free);
    if why is not null then
      stop := stop || bid;
      update public.bot_hosting set want_running = false, host_token_hash = null, host_token_prefix = null where bot_id = bid;
    elsif not h.want_running and st in ('running', 'starting') then
      stop := stop || bid;
    end if;
  end loop;
  update public.bot_hosting set want_running = false, host_token_hash = null, host_token_prefix = null, updated_at = now()
   where host_token_hash is not null and public.bot_hosting_stop_reason(bot_id, p_plus_free) is not null;
  return stop;
end $function$;

-- public.bot_hosting_hit(bid uuid, act text, lim integer, secs integer)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_hosting_hit(bid uuid, act text, lim integer, secs integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  perform pg_advisory_xact_lock(hashtext('bot_hosting_hit:' || bid::text));
  select count(*) into n from public.bot_hosting_actions
   where bot_id = bid and action = act and at > now() - make_interval(secs => secs);
  if n >= lim then return false; end if;
  insert into public.bot_hosting_actions (bot_id, action) values (bid, act);
  execute 'dele' || 'te from public.bot_hosting_actions where bot_id = $1 and at < now() - interval ''1 day''' using bid;
  return true;
end $function$;

-- public.bot_hosting_paid(p_bot uuid, p_owner uuid, p_tier text, p_customer text, p_sub text, p_days integer, p_small_per_large numeric)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_hosting_paid(p_bot uuid, p_owner uuid, p_tier text, p_customer text, p_sub text, p_days integer DEFAULT 31, p_small_per_large numeric DEFAULT 0.5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o uuid; cur record; left_ interval := interval '0'; f numeric := 1; u timestamptz;
begin
  if p_tier not in ('small', 'large') then raise exception 'bad tier'; end if;
  if p_days is null or p_days < 1 or p_days > 400 then raise exception 'bad days'; end if;
  if p_small_per_large is null or p_small_per_large <= 0 or p_small_per_large > 1 then raise exception 'bad ratio'; end if;
  select owner_id into o from public.bots where id = p_bot;
  if o is null then raise exception 'bot not found'; end if;
  if o is distinct from p_owner then raise exception 'not the owner'; end if;
  perform pg_advisory_xact_lock(hashtext('bot_hosting_paid:' || p_bot::text));
  select tier, until, stripe_sub into cur from public.bot_hosting where bot_id = p_bot;
  if found and p_sub is not null and cur.stripe_sub = p_sub then
    return jsonb_build_object('until', cur.until, 'old_sub', null);
  end if;
  if found and cur.until is not null and cur.until > now() then
    left_ := cur.until - now();
    if cur.tier = 'small' and p_tier = 'large' then f := p_small_per_large;
    elsif cur.tier = 'large' and p_tier = 'small' then f := 1 / p_small_per_large; end if;
  end if;
  u := now() + left_ * f::double precision + make_interval(days => p_days);
  insert into public.bot_hosting as h (bot_id, owner_id, tier, until, stripe_customer, stripe_sub, free_slot, updated_at)
  values (p_bot, o, p_tier, u, p_customer, p_sub, false, now())
  on conflict (bot_id) do update set
    tier = excluded.tier,
    until = excluded.until,
    stripe_customer = coalesce(excluded.stripe_customer, h.stripe_customer),
    stripe_sub = coalesce(excluded.stripe_sub, h.stripe_sub),
    free_slot = false,
    updated_at = now()
  returning until into u;
  return jsonb_build_object('until', u, 'old_sub', case when p_sub is not null and cur.stripe_sub is distinct from p_sub then cur.stripe_sub end);
end $function$;

-- public.bot_hosting_renew_once(p_sub text, p_days integer, p_business text, p_event text)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_hosting_renew_once(p_sub text, p_days integer, p_business text, p_event text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare got text; until timestamptz;
begin
  if coalesce(p_business, '') = '' then raise exception 'business id required'; end if;
  insert into public.billing_fulfilments (business_id, kind, event_id) values (p_business, 'bot_hosting', p_event)
    on conflict (business_id) do nothing returning business_id into got;
  if got is null then
    select h.until into until from public.bot_hosting h where h.stripe_sub = p_sub;
    return until;
  end if;
  return public.bot_hosting_renew(p_sub, p_days);
end $function$;

-- public.bot_hosting_renew(p_sub text, p_days integer)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_hosting_renew(p_sub text, p_days integer DEFAULT 31)
 RETURNS timestamp with time zone
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.bot_hosting set until = greatest(now(), coalesce(until, now())) + make_interval(days => p_days), updated_at = now()
  where stripe_sub = p_sub and p_sub is not null
  returning until;
$function$;

-- public.bot_hosting_stop_reason(bid uuid, plus_free boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_hosting_stop_reason(bid uuid, plus_free boolean DEFAULT false)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when h.bot_id is null then 'not set up'
    when h.blocked then 'blocked'
    when b.id is null then 'bot deleted'
    when not coalesce((select f.mode = 'everyone' or (f.mode = 'test' and (b.owner_id = any(coalesce(f.users, '{}'))
                 or exists (select 1 from public.server_members m where m.user_id = b.owner_id and m.server_id = any(coalesce(f.servers, '{}')))))
               from public.feature_flags f where f.key = 'bot_hosting'), false) then 'flag off'
    when b.verified_at is null then 'not verified'
    when public.is_site_banned(b.owner_id) or public.is_site_banned(b.id) then 'banned'
    when h.until is not null and h.until + interval '3 days' > now() then null
    when plus_free and h.free_slot and h.tier = 'small'
         and exists (select 1 from public.profiles p where p.id = b.owner_id and p.plus_until > now()) then null
    else 'not paid'
  end
  from (select bid as id) x
  left join public.bot_hosting h on h.bot_id = x.id
  left join public.bots b on b.id = x.id;
$function$;

-- public.bot_id(p_bot text)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_id(p_bot text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select user_id from public.bot_accounts where bot = p_bot;
$function$;

-- public.bot_interaction_respond(bid uuid, iid uuid, tok text, kind text, body text, p_embeds jsonb, p_components jsonb, set_embeds boolean, set_components boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_interaction_respond(bid uuid, iid uuid, tok text, kind text, body text DEFAULT NULL::text, p_embeds jsonb DEFAULT NULL::jsonb, p_components jsonb DEFAULT NULL::jsonb, set_embeds boolean DEFAULT false, set_components boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare i public.bot_interactions; r public.bot_interaction_replies; msg public.messages; h text; prev public.bot_interactions;
begin
  if tok is null or tok !~ '^[0-9a-f]{48}$' then raise exception 'No such interaction'; end if;
  h := encode(extensions.digest(tok, 'sha256'), 'hex');
  -- One atomic claim: right bot, right token, not expired, under 10 answers. (Raising later undoes it.)
  update public.bot_interactions set replies = replies + 1, answered_at = coalesce(answered_at, now())
   where id = iid and bot_id = bid and token = h and created_at > now() - interval '15 minutes' and replies < 10
  returning * into i;
  if i.id is null then
    select * into prev from public.bot_interactions where id = iid and bot_id = bid and token = h;
    if prev.id is null then raise exception 'No such interaction'; end if;
    if prev.created_at <= now() - interval '15 minutes' then raise exception 'That interaction expired: answer within 15 minutes'; end if;
    raise exception 'Slow down: up to 10 answers per interaction';
  end if;
  if not public.bot_channel_visible(bid, i.channel_id) then raise exception 'That bot can''t see this channel anymore'; end if;
  if kind = 'reply' then
    -- 212: the first 5 answers to a button press don't count toward the bot's overall limit (still per server).
    if i.replies <= 5 then perform set_config('yapper.bot_reply', '1', true); end if;
    msg := public.bot_api_send(bid, i.channel_id, body, null, p_embeds, p_components);
    perform set_config('yapper.bot_reply', '', true);
  elsif kind = 'update' then
    msg := public.bot_api_edit(bid, i.message_id, body, p_embeds, set_embeds, p_components, set_components);
  elsif kind = 'ephemeral' then
    if btrim(coalesce(body, '')) = '' and p_embeds is null then raise exception 'An ephemeral reply needs content or embeds'; end if;
    if p_embeds is not null and not public.feature_on('bot_embeds', i.server_id) then raise exception 'Embeds aren''t available in this server yet'; end if;
  elsif kind is distinct from 'ack' then
    raise exception 'type must be reply, ephemeral, update or ack';
  end if;
  insert into public.bot_interaction_replies (interaction_id, bot_id, user_id, channel_id, message_id, kind, content, embeds)
  values (i.id, bid, i.user_id, i.channel_id, i.message_id, kind,
          case when kind = 'ephemeral' then left(coalesce(body, ''), 2000) end, case when kind = 'ephemeral' then p_embeds end)
  returning * into r;
  perform public.bc('user:' || i.user_id, 'interaction', 'INSERT', 'bot_interaction_replies', 'public', r, null);
  return jsonb_build_object('ok', true, 'type', kind, 'message', case when msg.id is null then null else to_jsonb(msg) end);
end $function$;

-- public.bot_left_server()  [security definer]
CREATE OR REPLACE FUNCTION public.bot_left_server()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  execute 'dele' || 'te from public.bot_servers where bot_id = $1 and server_id = $2' using old.user_id, old.server_id;
  return null;
end $function$;

-- public.bot_levels(sid uuid, cid uuid, uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_levels(sid uuid, cid uuid, uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cfg jsonb; row public.server_xp; gain int; lvl int; ann uuid; plus boolean; mult numeric; tpl text; rw jsonb;
begin
  select config into cfg from public.server_bots where server_id = sid and bot = 'levels' and enabled;
  if cfg is null then return; end if;
  select * into row from public.server_xp where server_id = sid and user_id = uid;
  if row.user_id is not null and row.last_at > now() - interval '60 seconds' then return; end if;
  plus := public.server_plus_on(sid);
  mult := case when plus then least(greatest(coalesce((cfg ->> 'xp_mult')::numeric, 1), 1), 2) else 1 end;
  gain := round((15 + floor(random() * 11)) * mult)::int;
  insert into public.server_xp (server_id, user_id, xp, level, last_at) values (sid, uid, gain, 0, now())
    on conflict (server_id, user_id) do update set xp = server_xp.xp + excluded.xp, last_at = now()
    returning * into row;
  lvl := floor(sqrt(row.xp / 100.0))::int;
  if lvl > row.level then
    update public.server_xp set level = lvl where server_id = sid and user_id = uid;
    if plus and jsonb_typeof(cfg -> 'rewards') = 'array' then
      perform set_config('yapper.bot', '1', true);
      for rw in select * from jsonb_array_elements(cfg -> 'rewards') loop
        if (rw ->> 'level')::int <= lvl and exists (select 1 from public.roles r where r.id = (rw ->> 'role_id')::uuid and r.server_id = sid and r.auto = 'none') then
          insert into public.member_roles (server_id, user_id, role_id, manual) values (sid, uid, (rw ->> 'role_id')::uuid, true) on conflict do nothing;
        end if;
      end loop;
      perform set_config('yapper.bot', '', true);
    end if;
    if coalesce((cfg ->> 'announce')::boolean, true) then
      ann := coalesce(nullif(cfg ->> 'channel_id', '')::uuid, cid);
      if not exists (select 1 from public.channels where id = ann and server_id = sid) then ann := cid; end if;
      tpl := case when plus then nullif(cfg ->> 'message', '') end;
      tpl := coalesce(tpl, '🎉 {user} just reached **level {level}**!');
      tpl := replace(replace(tpl, '{user}', '<@' || uid::text || '>'), '{level}', lvl::text);
      perform public.bot_say(ann, 'levels', tpl);
    end if;
  end if;
end $function$;

-- public.bot_log_kind(kind text, sid uuid, body text)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_log_kind(kind text, sid uuid, body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cfg jsonb; cid uuid;
begin
  if not exists (select 1 from public.servers where id = sid) then return; end if;
  cfg := public.bot_cfg(sid, 'logger');
  if cfg is null then return; end if;
  cid := nullif(cfg ->> 'channel_id', '')::uuid;
  -- Logger+: member events (joins, leaves, bans, timeouts, roles) can go to their own channel.
  if kind = 'members' and nullif(cfg ->> 'member_channel_id', '') is not null and public.server_plus_on(sid) then
    cid := (cfg ->> 'member_channel_id')::uuid;
  end if;
  if cid is null or not exists (select 1 from public.channels where id = cid and server_id = sid) then return; end if;
  perform public.bot_say(cid, 'logger', body);
exception when others then return;
end $function$;

-- public.bot_log(sid uuid, body text)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_log(sid uuid, body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cfg jsonb; cid uuid;
begin
  if not exists (select 1 from public.servers where id = sid) then return; end if;
  cfg := public.bot_cfg(sid, 'logger');
  if cfg is null then return; end if;
  cid := nullif(cfg ->> 'channel_id', '')::uuid;
  if cid is null or not exists (select 1 from public.channels where id = cid and server_id = sid) then return; end if;
  perform public.bot_say(cid, 'logger', body);
exception when others then return;
end $function$;

-- public.bot_member_events()  [security definer]
CREATE OR REPLACE FUNCTION public.bot_member_events()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid := coalesce(new.server_id, old.server_id); uid uuid := coalesce(new.user_id, old.user_id); b record; payload jsonb;
begin
  if not exists (select 1 from public.bot_servers bs where bs.server_id = sid) then return null; end if;
  if public.is_bot_user(uid) then return null; end if;
  payload := jsonb_build_object('server_id', sid, 'user_id', uid,
    'username', (select username from public.profiles where id = uid),
    'joined_at', case when tg_op = 'INSERT' then new.joined_at else null end,
    'member_count', (select member_count from public.servers where id = sid));
  for b in select bo.id, bo.webhook_url, bo.webhook_secret from public.bot_servers bs join public.bots bo on bo.id = bs.bot_id where bs.server_id = sid loop
    perform public.bot_push(b.id, b.webhook_url, b.webhook_secret, case when tg_op = 'INSERT' then 'member_join' else 'member_leave' end, payload);
  end loop;
  return null;
end $function$;

-- public.bot_member_perms(sid uuid, uid uuid, cid uuid, keys text[])  [security definer]
CREATE OR REPLACE FUNCTION public.bot_member_perms(sid uuid, uid uuid, cid uuid, keys text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  k text; own boolean; adm boolean; live boolean := false; vbase boolean; base boolean; v boolean;
  srv jsonb := '{}'; chan jsonb := null;
  c record;
begin
  if sid is null or uid is null or coalesce(array_length(keys, 1), 0) > 64 then return null; end if;
  own := exists (select 1 from public.servers s where s.id = sid and s.owner_id = uid);
  if not own and not exists (select 1 from public.server_members sm where sm.server_id = sid and sm.user_id = uid) then
    return null;
  end if;
  adm := own or public.server_perm_of(sid, uid, 'administrator');
  foreach k in array coalesce(keys, '{}') loop
    srv := srv || jsonb_build_object(k, public.server_perm_of(sid, uid, k));
  end loop;

  if cid is not null then
    -- Threads and forum posts follow their parent's rules plus the thread ones (603); not answered here.
    select ch.id, ch.category_id, ch.private, ch.read_only, ch.kind into c
      from public.channels ch where ch.id = cid and ch.server_id = sid and ch.kind <> 'thread';
    if c.id is null then return null; end if;
    live := exists (select 1 from public.feature_flags f where f.key = 'channel_perms'
                    and (f.mode = 'everyone' or (f.mode = 'test' and sid = any(f.servers))))
            and exists (select 1 from public.channel_overrides o where o.channel_id = c.id or o.category_id = c.category_id);
    vbase := public.server_perm_of(sid, uid, 'manage_server')
      or exists (select 1 from public.channel_roles cr join public.member_roles mr on mr.role_id = cr.role_id and mr.user_id = uid
                 where cr.channel_id = c.id)
      or exists (select 1 from public.channel_roles cr where cr.channel_id = c.id and public.auto_role_applies(cr.role_id, uid));
    chan := '{}';
    foreach k in array array_append(array_remove(coalesce(keys, '{}'), 'view_channel'), 'view_channel') loop
      if k = 'view_channel' then
        v := case when live then public.channel_perm_of(uid, c.id, k, vbase) else (not coalesce(c.private, false) or vbase) end;
      else
        base := coalesce((srv->>k)::boolean, public.server_perm_of(sid, uid, k));
        v := case when live then public.channel_perm_of(uid, c.id, k, base) else base end;
        if k = 'send_messages' and c.kind = 'forum' then v := false; end if;
        if k = 'send_messages' and coalesce(c.read_only, false) then
          v := v and (public.server_perm_of(sid, uid, 'manage_server')
                      or exists (select 1 from public.channel_post_roles pr join public.member_roles mr on mr.role_id = pr.role_id and mr.user_id = uid
                                 where pr.channel_id = c.id)
                      or exists (select 1 from public.channel_post_roles pr where pr.channel_id = c.id and public.auto_role_applies(pr.role_id, uid)));
        end if;
      end if;
      chan := chan || jsonb_build_object(k, v);
    end loop;
  end if;

  return jsonb_build_object('owner', own, 'administrator', adm, 'server', srv, 'channel', chan);
end $function$;

-- public.bot_on_message()  [security definer]
CREATE OR REPLACE FUNCTION public.bot_on_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; helper_on boolean; levels_on boolean; hcfg jsonb; c jsonb; cmd text;
begin
  if current_setting('yapper.bot', true) = '1' then return null; end if;
  if exists (select 1 from public.bot_accounts where user_id = new.author_id) then return null; end if;
  select server_id into sid from public.channels where id = new.channel_id;
  if sid is null or not public.feature_on('bots', sid) then return null; end if;
  select bool_or(bot = 'helper' and enabled), bool_or(bot = 'levels' and enabled) into helper_on, levels_on from public.server_bots where server_id = sid;
  if coalesce(levels_on, false) then perform public.bot_levels(sid, new.channel_id, new.author_id); end if;
  if coalesce(helper_on, false) and left(new.content, 1) in ('!', '/') and public.server_plus_on(sid) then
    select config into hcfg from public.server_bots where server_id = sid and bot = 'helper';
    cmd := lower(substr(split_part(new.content, ' ', 1), 2));
    if jsonb_typeof(hcfg -> 'commands') = 'array' then
      for c in select * from jsonb_array_elements(hcfg -> 'commands') loop
        if lower(c ->> 'name') = cmd and nullif(c ->> 'reply', '') is not null then
          perform public.bot_say(new.channel_id, 'helper', replace(left(c ->> 'reply', 1000), '{user}', '<@' || new.author_id::text || '>'));
          return null;
        end if;
      end loop;
    end if;
  end if;
  if coalesce(helper_on, false) or (coalesce(levels_on, false) and lower(new.content) in ('!rank', '!top')) then
    perform public.bot_helper(sid, new.channel_id, new.author_id, new.content);
  end if;
  return null;
end $function$;

-- public.bot_order(extra uuid, extra_mult integer, use_boosts boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_order(extra uuid DEFAULT NULL::uuid, extra_mult integer DEFAULT NULL::integer, use_boosts boolean DEFAULT true)
 RETURNS TABLE(id uuid, pos bigint, servers bigint, boost integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with boosts as (
    select p.bot_id, max(p.mult)::int as b from public.bot_promotions p
    where use_boosts and p.kind = 'boost' and p.starts_at <= now() and p.ends_at > now() and public.bot_promo_ok(p.bot_id)
    group by p.bot_id
  ),
  base as (
    select b.id, lower(b.name) as ln, coalesce(b.real_servers::bigint, public.bot_real_server_count(b.id)) as n,
           greatest(coalesce(bo.b, 1), case when b.id is not distinct from extra then coalesce(extra_mult, 1) else 1 end) as m
    from public.bots b left join boosts bo on bo.bot_id = b.id
    where b.public and b.verified_at is not null
  ),
  organic as (select n, row_number() over (order by n desc, ln) as r from base where m = 1),
  floors as (
    select coalesce((select n from organic where r = 19), -1) as f2,
           coalesce((select n from organic where r = 9), -1) as f4,
           coalesce((select n from organic where r = 4), -1) as f8
  )
  select e.id,
         row_number() over (order by greatest(e.n::numeric, case e.m when 8 then f.f8 + 0.5 when 4 then f.f4 + 0.5 when 2 then f.f2 + 0.5 else 0 end) desc, e.n desc, e.ln, e.id),
         e.n, case when e.m > 1 then e.m else 0 end
  from base e cross join floors f;
$function$;

-- public.bot_perms_gate(bid uuid, sid uuid, act boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_perms_gate(bid uuid, sid uuid, act boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if bid is null or sid is null then return 'Bad request'; end if;
  if not exists (select 1 from public.bot_servers bs where bs.bot_id = bid and bs.server_id = sid) then
    return 'The bot is not in that server';
  end if;
  if not public.feature_on('bot_perms', sid) then
    return 'Bot permissions aren''t on in this server yet';
  end if;
  if act then
    insert into public.bot_perm_rate as r (bot_id, window_start, n) values (bid, now(), 1)
    on conflict (bot_id) do update
      set window_start = case when r.window_start < now() - interval '1 minute' then now() else r.window_start end,
          n = case when r.window_start < now() - interval '1 minute' then 1 else r.n + 1 end
    returning r.n into n;
    if n > 30 then return 'Slow down: 30 role and permission changes a minute per bot'; end if;
  else
    insert into public.bot_perm_rate as r (bot_id, read_window_start, read_n) values (bid, now(), 1)
    on conflict (bot_id) do update
      set read_window_start = case when r.read_window_start < now() - interval '1 minute' then now() else r.read_window_start end,
          read_n = case when r.read_window_start < now() - interval '1 minute' then 1 else r.read_n + 1 end
    returning r.read_n into n;
    if n > 120 then return 'Slow down: 120 permission checks a minute per bot'; end if;
  end if;
  return null;
end $function$;

-- public.bot_presence(bid uuid, st text, act jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_presence(bid uuid, st text DEFAULT NULL::text, act jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare saved jsonb; s text; a jsonb;
begin
  if st is null then
    select presence into saved from public.bots where id = bid;
    s := coalesce(saved ->> 'st', 'online');
    a := saved -> 'act';
  else
    s := st; a := act;
  end if;
  if s not in ('online', 'idle', 'dnd') then s := 'online'; end if;
  if a is not null and (jsonb_typeof(a) <> 'object' or coalesce(a ->> 'name', '') = '') then a := null; end if;
  insert into public.presence (user_id, status, activity, activity_at) values (bid, s, a, case when a is null then null else now() end)
  on conflict (user_id) do update set
    last_seen = now(),
    online_since = case when presence.last_seen < now() - public.presence_ttl() then now() else presence.online_since end,
    status = s,
    status_at = case when presence.status is distinct from s then now() else presence.status_at end,
    activity = case when (presence.activity ->> 'name') is distinct from (a ->> 'name') then a else presence.activity end,
    activity_at = case when (presence.activity ->> 'name') is distinct from (a ->> 'name') then now() else presence.activity_at end;
end $function$;

-- public.bot_promo_availability(bid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_promo_availability(bid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if (select auth.uid()) is null or not (public.is_staff() or exists (select 1 from public.bots where id = bid and owner_id = (select auth.uid()))) then
    raise exception 'Only the bot’s owner can see this';
  end if;
  return jsonb_build_object(
    'ok', public.bot_promo_ok(bid),
    'slots', public.bot_promo_slots(),
    'taken', (select count(distinct bot_id) from public.bot_promotions where kind = 'promote' and starts_at <= now() and ends_at > now()),
    'next', public.next_bot_promo_start(bid),
    'until', (select max(ends_at) from public.bot_promotions where bot_id = bid and kind = 'promote' and ends_at > now())
  );
end $function$;

-- public.bot_promo_event(pids uuid[], kind text)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_promo_event(pids uuid[], kind text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if (select auth.uid()) is null or bot_promo_event.kind not in ('view', 'click', 'add') or not public.feature_on_for_me('bot_promoted') then return; end if;
  update public.bot_promotions p set
    views = p.views + (bot_promo_event.kind = 'view')::int,
    clicks = p.clicks + (bot_promo_event.kind = 'click')::int,
    adds = p.adds + (bot_promo_event.kind = 'add')::int
  where p.id = any(pids[1:6]) and p.kind = 'promote' and p.starts_at <= now() and p.ends_at > now() and public.bot_promo_ok(p.bot_id);
end $function$;

-- public.bot_promo_ok(bid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_promo_ok(bid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((
    select b.public and b.verified_at is not null and not coalesce(b.unlisted, false)
       and not public.is_site_banned(b.id) and not public.is_site_banned(b.owner_id) and not public.bad_name(b.name)
    from public.bots b where b.id = bid), false);
$function$;

-- public.bot_promo_slots()
CREATE OR REPLACE FUNCTION public.bot_promo_slots()
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$ select 2 $function$;

-- public.bot_public_submit()  [security definer]
CREATE OR REPLACE FUNCTION public.bot_public_submit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.public and not coalesce(old.public, false) then
    new.submitted_at := now();
    new.verified_at := null;
    new.review_note := null;
    new.unlisted := false;
  elsif not new.public and not new.unlisted then
    new.verified_at := null;
  elsif new.unlisted and not old.unlisted and not old.public then
    new.verified_at := null;
  end if;
  return new;
end $function$;

-- public.bot_push(bid uuid, hook_url text, hook_secret text, ev text, payload jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_push(bid uuid, hook_url text, hook_secret text, ev text, payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare body text; sig text; cid uuid; sid uuid; eid bigint;
begin
  -- Every event carries channel_id and server_id (null when the event isn't in a channel / is in a DM).
  payload := coalesce(payload, '{}'::jsonb);
  cid := nullif(payload ->> 'channel_id', '')::uuid;
  if cid is null and nullif(payload ->> 'message_id', '') is not null then
    select channel_id into cid from public.messages where id = (payload ->> 'message_id')::uuid;
  end if;
  sid := nullif(payload ->> 'server_id', '')::uuid;
  if sid is null and cid is not null then select server_id into sid from public.channels where id = cid; end if;
  payload := payload || jsonb_build_object('channel_id', cid, 'server_id', sid);
  insert into public.bot_events (bot_id, type, data) values (bid, ev, payload) returning id into eid;
  -- Never wait for the bots row here (that is what deadlocked parallel sends); a minute-old stamp is fine.
  update public.bots set last_event_at = now()
   where id in (select b.id from public.bots b
                 where b.id = bid and (b.last_event_at is null or b.last_event_at < now() - interval '1 minute')
                 for no key update skip locked);
  if hook_url is not null then
    body := jsonb_build_object('id', eid, 'event', ev, 'data', payload)::text;
    sig := encode(extensions.hmac(body, coalesce(hook_secret, ''), 'sha256'), 'hex');
    perform net.http_post(
      url := hook_url,
      headers := jsonb_build_object('Content-Type', 'application/json', 'X-Yapper-Signature', 'sha256=' || sig, 'X-Yapper-Bot', bid::text),
      body := body::jsonb,
      timeout_milliseconds := 3000);
  end if;
end $function$;

-- public.bot_rank_tiers(bid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_rank_tiers(bid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if (select auth.uid()) is null or not (public.is_staff() or exists (select 1 from public.bots where id = bid and owner_id = (select auth.uid()))) then
    raise exception 'Only the bot’s owner can see this';
  end if;
  return jsonb_build_object(
    'now', (select o.pos from public.bot_order(null, null, true) o where o.id = bid),
    'x2', (select o.pos from public.bot_order(bid, 2, true) o where o.id = bid),
    'x4', (select o.pos from public.bot_order(bid, 4, true) o where o.id = bid),
    'x8', (select o.pos from public.bot_order(bid, 8, true) o where o.id = bid),
    'mult', (select coalesce(max(p.mult), 1) from public.bot_promotions p where p.bot_id = bid and p.kind = 'boost' and p.starts_at <= now() and p.ends_at > now()),
    'until', (select max(p.ends_at) from public.bot_promotions p where p.bot_id = bid and p.kind = 'boost' and p.ends_at > now())
  );
end $function$;

-- public.bot_reaction_events()  [security definer]
CREATE OR REPLACE FUNCTION public.bot_reaction_events()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare live boolean; r record := coalesce(new, old); cid uuid; sid uuid; priv boolean; author uuid; b record; payload jsonb;
begin
  select m.channel_id, m.author_id into cid, author from public.messages m where m.id = r.message_id;
  if cid is null then return null; end if;
  select server_id, private into sid, priv from public.channels where id = cid;
  if sid is null then return null; end if;
  if not exists (select 1 from public.bot_servers bs where bs.server_id = sid) then return null; end if;
  payload := jsonb_build_object('message_id', r.message_id, 'channel_id', cid, 'server_id', sid, 'user_id', r.user_id,
    'username', (select username from public.profiles where id = r.user_id), 'emoji', r.emoji, 'message_author_id', author);
  live := public.channel_overrides_live(cid);
  for b in select bo.id, bo.webhook_url, bo.webhook_secret from public.bot_servers bs join public.bots bo on bo.id = bs.bot_id
           where bs.server_id = sid and bo.id <> r.user_id loop
    if (coalesce(priv, false) or live) and not public.bot_channel_visible(b.id, cid) then continue; end if;
    perform public.bot_push(b.id, b.webhook_url, b.webhook_secret, case when tg_op = 'INSERT' then 'reaction_add' else 'reaction_remove' end, payload);
  end loop;
  return null;
end $function$;

-- public.bot_real_server_count(bid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_real_server_count(bid uuid)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(*) from public.bot_real_servers(bid);
$function$;

-- public.bot_real_servers(bid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_real_servers(bid uuid)
 RETURNS TABLE(server_id uuid, owner_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select s.id, s.owner_id
  from public.bot_servers bs
  join public.servers s on s.id = bs.server_id
  where bs.bot_id = bid
    and s.shut_down_at is null
    and (select count(*) from (select 1 from public.server_members m
                               where m.server_id = s.id and not public.is_bot_user(m.user_id)
                               limit 3) h) >= 3;
$function$;

-- public.bot_remove_from_server(bid uuid, sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_remove_from_server(bid uuid, sid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not (public.server_perm(sid, 'manage_server') or exists (select 1 from public.bots b where b.id = bid and b.owner_id = auth.uid())) then
    raise exception 'Only server managers (or the bot''s owner) can remove bots';
  end if;
  delete from public.bot_servers where bot_id = bid and server_id = sid;
  delete from public.server_members where server_id = sid and user_id = bid;
end; $function$;

-- public.bot_rename(p_bot uuid, p_name text, p_username text, p_tag text)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_rename(p_bot uuid, p_name text, p_username text, p_tag text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  b public.bots%rowtype;
  old_username text;
  old_display text;
begin
  select * into b from public.bots where id = p_bot for update;
  if not found then raise exception 'That bot is gone'; end if;
  if b.renamed_at is not null and b.renamed_at > now() - interval '7 days' then
    raise exception 'Bots can be renamed once a week. Try again on %.', to_char(b.renamed_at + interval '7 days', 'Mon FMDD');
  end if;
  select username, display_name into old_username, old_display from public.profiles where id = p_bot for update;
  update public.profiles
     set username = p_username,
         discriminator = p_tag,
         display_name = case when display_name is null or display_name = b.name then p_name else display_name end
   where id = p_bot;
  update public.bots set name = p_name, tag = p_tag, renamed_at = now() where id = p_bot;
  if old_username is not null and lower(old_username) <> lower(p_username) then
    insert into public.username_holds (name_key, user_id, until) values (lower(old_username), p_bot, now() + interval '7 days')
    on conflict (name_key) do update set user_id = excluded.user_id, until = excluded.until;
  end if;
  return jsonb_build_object('name', p_name, 'tag', p_tag, 'username', p_username);
end $function$;

-- public.bot_review_queue()  [security definer]
CREATE OR REPLACE FUNCTION public.bot_review_queue()
 RETURNS TABLE(id uuid, name text, description text, owner_id uuid, owner_name text, owner_plus boolean, submitted_at timestamp with time zone, servers bigint, posts bigint, commands bigint, unlisted boolean, real_servers bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select b.id, b.name, b.description, b.owner_id, p.username, coalesce(p.plus_until > now(), false), b.submitted_at,
         (select count(*) from public.bot_servers s where s.bot_id = b.id), b.posts,
         (select count(*) from public.bot_commands c where c.bot_id = b.id), b.unlisted,
         public.bot_real_server_count(b.id)
  from public.bots b join public.profiles p on p.id = b.owner_id
  where (b.public or b.unlisted) and b.verified_at is null and public.can_review_bots()
  order by coalesce(p.plus_until > now(), false) desc, b.submitted_at nulls last;
$function$;

-- public.bot_say(cid uuid, p_bot text, body text)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_say(cid uuid, p_bot text, body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare bid uuid := public.bot_id(p_bot);
begin
  if cid is null or bid is null or body is null or btrim(body) = '' then return; end if;
  perform set_config('yapper.bot', '1', true);
  insert into public.messages (channel_id, author_id, content, created_at) values (cid, bid, left(body, 2000), clock_timestamp());
  perform set_config('yapper.bot', '', true);
end; $function$;

-- public.bot_send_gate(bid uuid, cid uuid, reply uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_send_gate(bid uuid, cid uuid, reply uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  b public.bots;
  sid uuid;
  in_server int;
  oldest timestamptz;
  free_reply boolean := false;
  cap int;
  t timestamptz;
  bucket timestamptz;
  frac float8;
  cur int; prev int;
  est float8;
  wait int;
begin
  -- Lock the bot's own row first: one send per bot at a time (149), and the overall counter lives on it.
  update public.bots set last_used_at = now(), posts = posts + 1 where id = bid returning * into b;
  if b.id is null then raise exception 'No such bot'; end if;
  -- The time after the lock, not the transaction start: a send that waited on the lock across a minute boundary
  -- must not write an older window back.
  t := clock_timestamp();
  bucket := date_trunc('minute', t);

  -- 1. Per server (per DM for DMs): every message counts.
  select server_id into sid from public.channels where id = cid;
  if sid is not null then
    select count(*), min(x.created_at) into in_server, oldest from (
      select m.created_at from public.messages m
       where m.channel_id = any (array(select c.id from public.channels c where c.server_id = sid))
         and m.author_id = bid and m.created_at > t - interval '1 minute'
       order by m.created_at desc limit 30) x;
  else
    select count(*), min(x.created_at) into in_server, oldest from (
      select m.created_at from public.messages m
       where m.channel_id = cid and m.author_id = bid and m.created_at > t - interval '1 minute'
       order by m.created_at desc limit 30) x;
  end if;
  if in_server >= 30 then
    wait := greatest(1, least(60, ceil(extract(epoch from (oldest + interval '1 minute' - t)))::int));
    raise exception 'Slow down: 30 messages a minute in this server (try again in % s)', wait using errcode = 'P0001';
  end if;

  -- 2. Overall, unless this answers a button press or a slash command.
  if current_setting('yapper.bot_reply', true) = '1' then
    free_reply := true;
  elsif reply is not null then
    select true into free_reply
      from public.messages u
     where u.id = reply and u.channel_id = cid and u.author_id <> bid
       and u.webhook is null and not public.is_bot_user(u.author_id)   -- a person's command, not another bot's
       and u.created_at > t - interval '15 minutes'
       and left(u.content, 1) = '/'
       and exists (select 1 from public.bot_commands c
                    where c.bot_id = bid and c.name = lower(substring(u.content from '^/([^\s/]+)')))
       and (select count(*) from public.messages r
             where r.reply_to_id = reply and r.author_id = bid and r.created_at > t - interval '15 minutes') < 5;
    free_reply := coalesce(free_reply, false);
  end if;
  if free_reply then return; end if;

  cap := case when b.verified_at is not null then 300 else 30 end;
  -- Roll the window: the minute before becomes "prev", older ones are forgotten.
  if b.rate_min is null or b.rate_min < bucket - interval '1 minute' then
    prev := 0; cur := 0;
  elsif b.rate_min < bucket then
    prev := b.rate_cur; cur := 0;
  else
    prev := b.rate_prev; cur := b.rate_cur;
  end if;
  frac := extract(epoch from (t - bucket)) / 60.0;
  est := prev * (1 - frac) + cur;
  if est >= cap then
    -- When the estimate drops under the cap: the previous minute's share fades out over this minute.
    if cur >= cap or prev = 0 then
      wait := ceil(extract(epoch from (bucket + interval '1 minute' - t)))::int;
    else
      wait := ceil(60.0 * (1 - (cap - cur)::float8 / prev) - frac * 60.0)::int;
    end if;
    wait := greatest(1, least(60, wait));
    raise exception 'Slow down: % messages a minute overall (try again in % s)', cap, wait using errcode = 'P0001';
  end if;
  update public.bots set rate_min = greatest(bucket, b.rate_min), rate_prev = prev, rate_cur = cur + 1 where id = bid;
end $function$;

-- public.bot_server_perm(bid uuid, sid uuid, perm text)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_server_perm(bid uuid, sid uuid, perm text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select sid is not null and bid is not null and (
    exists (
      select 1 from public.member_roles mr join public.roles r on r.id = mr.role_id
      where mr.server_id = sid and mr.user_id = bid
        and (coalesce((r.perms->>'administrator')::boolean, false) or coalesce((r.perms->>perm)::boolean, false))
    )
    or (public.basic_perm(perm)
        and exists (select 1 from public.bot_servers bs where bs.bot_id = bid and bs.server_id = sid)
        and coalesce(((select everyone_perms from public.servers where id = sid)->>perm)::boolean, true))
  );
$function$;

-- public.bot_set_shareable(bid uuid, on_off boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_set_shareable(bid uuid, on_off boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.feature_on_for_me('bot_share_add') then raise exception 'Not available yet'; end if;
  update public.bots set shareable = on_off where id = bid and owner_id = auth.uid();
  if not found then raise exception 'Bot not found'; end if;
end $function$;

-- public.bot_test_event(bid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_test_event(bid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b record;
begin
  select id, owner_id, webhook_url, webhook_secret, name into b from public.bots where id = bid;
  if b.id is null or b.owner_id <> auth.uid() then raise exception 'Not your bot'; end if;
  perform public.bot_push(b.id, b.webhook_url, b.webhook_secret, 'test',
    jsonb_build_object('bot', b.name, 'by', auth.uid(), 'at', now(), 'hello', 'If you can read this, your bot is wired up.'));
end $function$;

-- public.bot_test_welcome(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_test_welcome(sid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cfg jsonb; cid uuid; tpl text; nm text;
begin
  if not public.server_perm(sid, 'manage_server') then raise exception 'Managers only'; end if;
  select config into cfg from public.server_bots where server_id = sid and bot = 'welcome' and enabled;
  if cfg is null then raise exception 'Switch Welcomer on first'; end if;
  cid := nullif(cfg ->> 'channel_id', '')::uuid;
  if cid is null or not exists (select 1 from public.channels where id = cid and server_id = sid and kind = 'text') then raise exception 'Pick a channel first'; end if;
  select coalesce(display_name, username) into nm from public.profiles where id = auth.uid();
  tpl := coalesce(nullif(cfg ->> 'message', ''), 'Welcome to {server}, {user}! 👋');
  tpl := replace(tpl, '{user}', '<@' || auth.uid()::text || '>');
  tpl := replace(tpl, '{name}', coalesce(nm, 'friend'));
  tpl := replace(tpl, '{server}', (select name from public.servers where id = sid));
  tpl := replace(tpl, '{count}', (select count(*)::text from public.server_members where server_id = sid));
  perform public.bot_say(cid, 'welcome', tpl || ' (test)');
end $function$;

-- public.bot_verified_badge()  [security definer]
CREATE OR REPLACE FUNCTION public.bot_verified_badge()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  bid uuid := case when tg_op = 'DELETE' then old.id else new.id end;
  want boolean := tg_op <> 'DELETE' and new.verified_at is not null and (new.public or new.unlisted);
begin
  if want then
    update public.profiles set badges = coalesce(badges, '{}'::text[]) || 'verified_bot'::text
     where id = bid and not ('verified_bot' = any(coalesce(badges, '{}'::text[])));
  else
    update public.profiles set badges = array_remove(badges, 'verified_bot')
     where id = bid and 'verified_bot' = any(coalesce(badges, '{}'::text[]));
  end if;
  return null;
end $function$;

-- public.bot_verify_progress(bid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_verify_progress(bid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b public.bots;
begin
  select * into b from public.bots where id = bid and owner_id = auth.uid();
  if b.id is null then raise exception 'Bot not found'; end if;
  return jsonb_build_object(
    'servers', (select count(*) from public.bot_servers bs where bs.bot_id = b.id),
    'real_servers', (select count(*) from public.bot_real_servers(b.id) r where r.owner_id <> b.owner_id),
    'need_servers', 3,
    'has_avatar', exists (select 1 from public.profiles p where p.id = b.id and p.avatar_path is not null),
    'commands', (select count(*) from public.bot_commands c where c.bot_id = b.id),
    'online', coalesce(greatest(b.last_poll_at, b.last_used_at) > now() - interval '7 days', false),
    'description_ok', char_length(btrim(coalesce(b.description, ''))) >= 20
  );
end $function$;

-- public.bot_visible_channels(bid uuid, sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_visible_channels(bid uuid, sid uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, name text, type text, server_id uuid, category_id uuid, category_name text, category_position integer, "position" integer, private boolean, read_only boolean, slowmode integer, nsfw boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select c.id, c.name, c.kind::text, c.server_id, c.category_id, cc.name, cc.position, c.position, c.private, coalesce(c.read_only, false), coalesce(c.slowmode, 0), false
  from public.channels c
  join public.bot_servers bs on bs.bot_id = bid and bs.server_id = c.server_id
  left join public.channel_categories cc on cc.id = c.category_id
  where (sid is null or c.server_id = sid) and c.kind in ('text', 'voice') /* 593: */
    and ((not c.private and not public.channel_overrides_live(c.id)) or public.bot_channel_visible(bid, c.id))
  order by c.server_id, cc.position nulls first, c.position, c.name;
$function$;

-- public.bot_voice_event(cid uuid, uid uuid, ev text)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_voice_event(cid uuid, uid uuid, ev text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; k text; b record; sent int := 0; joins boolean; pres record;
begin
  if ev not in ('voice_join', 'voice_leave') then raise exception 'Unknown voice event %', ev; end if;
  if cid is null or uid is null then return 0; end if;
  select c.server_id, c.kind into sid, k from public.channels c where c.id = cid;
  if sid is null or k is distinct from 'voice' then return 0; end if;
  joins := public.feature_on('bot_voice_join', sid);
  -- 453: a bot in a call shows in the server's voice list (ops/realtime/server.mjs, event bot_voice).
  if exists (select 1 from public.bots bo where bo.id = uid) and (ev = 'voice_leave' or joins) then
    select uid as user_id, sid as server_id, cid as channel_id, ev = 'voice_join' as joined into pres;
    perform public.bc('server:' || sid, 'bot_voice', 'UPDATE', 'bot_voice', 'public', pres, null);
  end if;
  if not public.feature_on('bot_voice', sid) then return 0; end if;
  for b in select bo.id, bo.webhook_url, bo.webhook_secret
             from public.bot_servers bs join public.bots bo on bo.id = bs.bot_id
            where bs.server_id = sid and (bo.id <> uid or joins) loop
    if not public.bot_channel_visible(b.id, cid) then continue; end if;
    perform public.bot_push(b.id, b.webhook_url, b.webhook_secret, ev,
      jsonb_build_object('user_id', uid, 'channel_id', cid, 'server_id', sid));
    sent := sent + 1;
  end loop;
  return sent;
end $function$;

-- public.bot_voice_gate(bid uuid, sid uuid, act boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_voice_gate(bid uuid, sid uuid, act boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if bid is null or sid is null then return 'Bad request'; end if;
  if not exists (select 1 from public.bot_servers bs where bs.bot_id = bid and bs.server_id = sid) then
    return 'The bot is not in that server';
  end if;
  if not public.feature_on('bot_voice', sid) then
    return 'Bot voice isn''t on in this server yet';
  end if;
  if act then
    insert into public.bot_voice_rate as r (bot_id, window_start, n) values (bid, now(), 1)
    on conflict (bot_id) do update
      set window_start = case when r.window_start < now() - interval '1 minute' then now() else r.window_start end,
          n = case when r.window_start < now() - interval '1 minute' then 1 else r.n + 1 end
    returning r.n into n;
    if n > 30 then return 'Slow down: 30 voice moves a minute per bot'; end if;
  else
    insert into public.bot_voice_rate as r (bot_id, read_window_start, read_n) values (bid, now(), 1)
    on conflict (bot_id) do update
      set read_window_start = case when r.read_window_start < now() - interval '1 minute' then now() else r.read_window_start end,
          read_n = case when r.read_window_start < now() - interval '1 minute' then 1 else r.read_n + 1 end
    returning r.read_n into n;
    if n > 60 then return 'Slow down: 60 voice lookups a minute per bot'; end if;
  end if;
  return null;
end $function$;

-- public.bot_voice_join_gate(bid uuid, sid uuid, leaving boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.bot_voice_join_gate(bid uuid, sid uuid, leaving boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if bid is null or sid is null then return 'Bad request'; end if;
  if not coalesce(leaving, false) then
    if not exists (select 1 from public.bot_servers bs where bs.bot_id = bid and bs.server_id = sid) then
      return 'The bot is not in that server';
    end if;
    if not public.feature_on('bot_voice_join', sid) then
      return 'Bots can''t join voice in this server yet';
    end if;
  end if;
  insert into public.bot_voice_rate as r (bot_id, join_window_start, join_n) values (bid, now(), 1)
  on conflict (bot_id) do update
    set join_window_start = case when r.join_window_start < now() - interval '1 minute' then now() else r.join_window_start end,
        join_n = case when r.join_window_start < now() - interval '1 minute' then 1 else r.join_n + 1 end
  returning r.join_n into n;
  if n > 10 then return 'Slow down: 10 voice joins and leaves a minute per bot'; end if;
  return null;
end $function$;

-- public.bot_webhooks()  [security definer]
CREATE OR REPLACE FUNCTION public.bot_webhooks()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare live boolean; sid uuid; b record; chname text; priv boolean; payload jsonb; cmd text; args text; m text[];
  targets uuid[]; has_cmd boolean; my_args text;
begin
  select server_id, name, private into sid, chname, priv from public.channels where id = new.channel_id;
  if sid is null then return null; end if;
  if not exists (select 1 from public.bot_servers bs where bs.server_id = sid) then return null; end if;
  m := regexp_match(coalesce(new.content, ''), '^[/!]([a-z0-9_-]{1,32})(?:\s+([\s\S]*))?$', 'i');
  if m is not null then cmd := lower(m[1]); args := coalesce(btrim(m[2]), ''); end if;
  -- Flag command_target: "/fish <@bot> ..." is for that bot when it has /fish here, not every bot that has it.
  if cmd is not null and args like '<@%' and public.feature_on('command_target', sid) then
    select array_agg(c.bot_id) into targets
      from public.bot_commands c join public.bot_servers bs on bs.bot_id = c.bot_id and bs.server_id = sid
     where c.name = cmd and starts_with(args, '<@' || c.bot_id::text || '>')
       and (not (coalesce(priv, false) or public.channel_overrides_live(new.channel_id)) or public.bot_channel_visible(c.bot_id, new.channel_id));
  end if;
  payload := jsonb_build_object(
    'id', new.id, 'channel_id', new.channel_id, 'channel_name', chname, 'server_id', sid, 'author_id', new.author_id,
    'author', (select username from public.profiles where id = new.author_id),
    'content', new.content, 'attachment', new.attachment_path, 'reply_to_id', new.reply_to_id, 'created_at', new.created_at,
    'author_bot', new.webhook is not null or public.is_bot_user(new.author_id));
  live := public.channel_overrides_live(new.channel_id);
  for b in select bo.id, bo.webhook_url, bo.webhook_secret from public.bot_servers bs join public.bots bo on bo.id = bs.bot_id
           where bs.server_id = sid and bo.id <> new.author_id loop
    if (coalesce(priv, false) or live) and not public.bot_channel_visible(b.id, new.channel_id) then continue; end if;
    has_cmd := cmd is not null and exists (select 1 from public.bot_commands c where c.bot_id = b.id and c.name = cmd);
    my_args := args;
    if targets is not null and has_cmd then
      if b.id = any(targets) then my_args := btrim(substr(args, length(b.id::text) + 4));
      else has_cmd := false; end if;  -- another bot's /fish: the message, not the command
    end if;
    perform public.bot_push(b.id, b.webhook_url, b.webhook_secret, 'message',
      payload || jsonb_build_object('mentioned', coalesce(new.content, '') like '%<@' || b.id::text || '>%')
              || case when has_cmd then jsonb_build_object('command', cmd, 'args', my_args) else '{}'::jsonb end
              || case when targets is not null then jsonb_build_object('command_for', to_jsonb(targets)) else '{}'::jsonb end);
  end loop;
  return null;
end $function$;

-- public.bot_welcome()  [security definer]
CREATE OR REPLACE FUNCTION public.bot_welcome()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cfg jsonb; cid uuid; tpl text; nm text; ls jsonb;
begin
  select config into cfg from public.server_bots where server_id = new.server_id and bot = 'welcome' and enabled;
  if cfg is null or not public.feature_on('bots', new.server_id) then return null; end if;
  cid := nullif(cfg ->> 'channel_id', '')::uuid;
  if cid is null or not exists (select 1 from public.channels where id = cid and server_id = new.server_id and kind = 'text') then return null; end if;
  select coalesce(display_name, username) into nm from public.profiles where id = new.user_id;
  tpl := nullif(cfg ->> 'message', '');
  ls := cfg -> 'lines';
  if public.server_plus_on(new.server_id) and jsonb_typeof(ls) = 'array' and jsonb_array_length(ls) > 0 then
    ls := ls || to_jsonb(coalesce(tpl, 'Welcome to {server}, {user}! 👋'));
    tpl := ls ->> floor(random() * jsonb_array_length(ls))::int;
  end if;
  tpl := coalesce(tpl, 'Welcome to {server}, {user}! 👋');
  tpl := replace(tpl, '{user}', '<@' || new.user_id::text || '>');
  tpl := replace(tpl, '{name}', coalesce(nm, 'friend'));
  tpl := replace(tpl, '{server}', (select name from public.servers where id = new.server_id));
  tpl := replace(tpl, '{count}', (select count(*)::text from public.server_members where server_id = new.server_id));
  perform public.bot_say(cid, 'welcome', tpl);
  return null;
end $function$;

-- public.bots_only_in_bots()  [security definer]
CREATE OR REPLACE FUNCTION public.bots_only_in_bots()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ch record;
begin
  if current_setting('yapper.bot', true) = '1' then return new; end if;
  if not exists (select 1 from public.profiles p where p.id = new.author_id and 'bot' = any(coalesce(p.badges, '{}'::text[]))) then return new; end if;
  if exists (select 1 from public.bot_accounts where user_id = new.author_id) then return new; end if;
  select c.name, c.server_id into ch from public.channels c where c.id = new.channel_id;
  if ch.server_id is not null and exists (select 1 from public.bot_servers where bot_id = new.author_id and server_id = ch.server_id) then return new; end if;
  if ch.server_id is not null and ch.name !~* 'bot' then
    raise exception 'Bots can only post in bot channels (like #bots).' using errcode = 'check_violation';
  end if;
  return new;
end $function$;

-- public.brand_like(t text)
CREATE OR REPLACE FUNCTION public.brand_like(t text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select public.brand_name(t) or regexp_replace(public.skeleton(coalesce(t, '')), '[^a-z0-9]', '', 'g')
    ~ '^(google|youtube|discord|proton|microsoft|apple|amazon|netflix|spotify|roblox|minecraft|fortnite|tiktok|instagram|facebook|twitter|twitch|snapchat|reddit|steam|nintendo|playstation|xbox|sony|samsung|tesla|openai|chatgpt|adobe|nvidia|intel|cocacola|pepsi|mcdonalds|nike|adidas|disney|marvel|pokemon|brave|firefox|mozilla|chrome|windows|android|yapper|paypal|cloudflare|github|epicgames|valorant|ubisoft|rockstar)'
$function$;

-- public.brand_name(t text)
CREATE OR REPLACE FUNCTION public.brand_name(t text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select regexp_replace(public.skeleton(t), '[^a-z0-9]', '', 'g') ~ '^(youtube|yt|facebook|fb|meta|instagram|insta|ig|twitch|tiktok|twitter|x|google|discord|yapper|snapchat|reddit|netflix|spotify|roblox|minecraft|fortnite|epicgames|steam|valve|nintendo|playstation|xbox|microsoft|apple|amazon|tesla|openai|chatgpt|mrbeast|pewdiepie|kaicenat|ishowspeed|xqc|ninja|admin|administrator|moderator|mod|staff|support|official|verified|system|owner|ceo|nasa|fbi|cia|police|government|gov|un|nato)$'
    or regexp_replace(public.skeleton(t), '[^a-z0-9]', '', 'g') ~ '(ant[il]c|yapperstaff|yapperadmin|yapperteam)';
$function$;

-- public.broadcast_member_change()  [security definer]
CREATE OR REPLACE FUNCTION public.broadcast_member_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid := coalesce(new.server_id, old.server_id); uid uuid := coalesce(new.user_id, old.user_id); n int;
begin
  select count(*) into n from (select 1 from public.server_members where server_id = sid limit 1001) t;
  if n > 1000 then
    perform public.bc('user:' || uid, 'member', tg_op, tg_table_name, tg_table_schema, new, old);
  else
    perform public.bc('server:' || sid, 'member', tg_op, tg_table_name, tg_table_schema, new, old);
    -- 372: the person's other devices aren't on server:<id> before they join (or after they leave): tell them directly.
    if tg_op in ('INSERT', 'DELETE') then
      perform public.bc('user:' || uid, 'member', tg_op, tg_table_name, tg_table_schema, new, old);
    end if;
  end if;
  return null;
end;
$function$;

-- public.broadcast_message_change()  [security definer]
CREATE OR REPLACE FUNCTION public.broadcast_message_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  cid uuid; sid uuid; uid uuid; o public.messages;
  body text; targets uuid[]; open_ boolean; vis boolean; restricted boolean; old_claims text; old_sub text;
  uuid_re constant text := '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
begin
  if current_setting('yapper.bulk', true) = '1' then return null; end if;
  cid := coalesce(new.channel_id, old.channel_id);
  if tg_op = 'DELETE' then
    o := jsonb_populate_record(null::public.messages, jsonb_build_object('id', old.id, 'channel_id', old.channel_id, 'author_id', old.author_id));
  else
    o := old;
  end if;
  select ch.server_id,
         coalesce(ch.private, false)
         or exists (select 1 from public.channel_overrides ov where ov.channel_id = ch.id or (ch.category_id is not null and ov.category_id = ch.category_id))
    into sid, restricted from public.channels ch where ch.id = coalesce((select t.parent_id from public.channels t where t.id = cid), cid); /* 593: */
  restricted := coalesce(restricted, true);
  open_ := not restricted;
  if sid is not null then
    perform public.bc('chan:' || cid, 'message', tg_op, tg_table_name, tg_table_schema, new, o);
    body := coalesce(new.content, '');
    if tg_op in ('INSERT', 'DELETE') and exists (
         select 1 from public.feature_flags f
         where f.key = 'live_badges' and (f.mode = 'everyone' or (f.mode = 'test' and sid = any(f.servers)))) then
      perform public.bc_notice('server:' || sid, 'unread', jsonb_build_object(
        'operation', tg_op,
        'id', coalesce(new.id, old.id),
        'channel_id', cid,
        'author_id', coalesce(new.author_id, old.author_id),
        'created_at', coalesce(new.created_at, old.created_at),
        'everyone', tg_op = 'INSERT' and not starts_with(body, chr(8618) || ' Forwarded' || chr(10)) and body ~ '(^|[^A-Za-z0-9_@])@everyone\M',
        'restricted', restricted));
    end if;
    if tg_op = 'INSERT' and not starts_with(body, chr(8618) || ' Forwarded' || chr(10))
       and (strpos(body, '<@') > 0 or new.reply_to_id is not null) then
      select array_agg(distinct t.x) into targets from (
        (select m[1]::uuid as x from regexp_matches(body, '<@(' || uuid_re || ')>', 'g') m limit 20)
        union all
        (select mr.user_id from public.member_roles mr
          where mr.server_id = sid
            and mr.role_id in (select m[1]::uuid from regexp_matches(body, '<@&(' || uuid_re || ')>', 'g') m limit 10)
          limit 50)
        union all
        (select pm.author_id from public.messages pm where new.reply_to_id is not null and pm.id = new.reply_to_id and pm.channel_id = cid)
      ) t
      where t.x is not null and t.x is distinct from new.author_id;
      if targets is not null then
        old_claims := current_setting('request.jwt.claims', true);
        old_sub := current_setting('request.jwt.claim.sub', true);
        foreach uid in array targets loop
          if not exists (select 1 from public.server_members sm where sm.server_id = sid and sm.user_id = uid) then continue; end if;
          if public.is_site_banned(uid) then continue; end if;
          if not coalesce(open_, false) then
            perform set_config('request.jwt.claims', jsonb_build_object('sub', uid::text, 'role', 'authenticated')::text, true);
            perform set_config('request.jwt.claim.sub', uid::text, true);
            vis := public.can_access_channel(cid);
            perform set_config('request.jwt.claims', coalesce(nullif(old_claims, ''), '{}'), true);
            perform set_config('request.jwt.claim.sub', coalesce(old_sub, ''), true);
            if not coalesce(vis, false) then continue; end if;
          end if;
          perform public.bc('user:' || uid, 'message', tg_op, tg_table_name, tg_table_schema, new, o);
        end loop;
      end if;
    end if;
  else
    for uid in select cm.user_id from public.channel_members cm where cm.channel_id = cid and not public.is_site_banned(cm.user_id) loop
      perform public.bc('user:' || uid, 'message', tg_op, tg_table_name, tg_table_schema, new, o);
    end loop;
  end if;
  return null;
end; $function$;

-- public.broadcast_poll_ballot()  [security definer]
CREATE OR REPLACE FUNCTION public.broadcast_poll_ballot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cid uuid; sid uuid; uid uuid; voter uuid; is_quiz boolean; n public.poll_ballots; o public.poll_ballots;
begin
  if tg_op = 'UPDATE' and new.option_ids is not distinct from old.option_ids then return null; end if;
  select channel_id, quiz into cid, is_quiz from public.polls where id = coalesce(new.poll_id, old.poll_id);
  if cid is null then return null; end if;
  voter := coalesce(new.user_id, old.user_id);
  -- Copies without the voter (and, for a quiz, without the picks), for everyone else.
  if tg_op <> 'DELETE' then n := new; n.user_id := null; if is_quiz then n.option_ids := '{}'; end if; end if;
  if tg_op <> 'INSERT' then o := old; o.user_id := null; if is_quiz then o.option_ids := '{}'; end if; end if;
  select server_id into sid from public.channels where id = cid;
  if sid is not null then
    perform public.bc('chan:' || cid, 'poll', tg_op, tg_table_name, tg_table_schema,
      case when tg_op = 'DELETE' then null else n end, case when tg_op = 'INSERT' then null else o end);
    perform public.bc('user:' || voter, 'poll', tg_op, tg_table_name, tg_table_schema, new, old);
  else
    for uid in select user_id from public.channel_members where channel_id = cid loop
      if uid = voter then
        perform public.bc('user:' || uid, 'poll', tg_op, tg_table_name, tg_table_schema, new, old);
      else
        perform public.bc('user:' || uid, 'poll', tg_op, tg_table_name, tg_table_schema,
          case when tg_op = 'DELETE' then null else n end, case when tg_op = 'INSERT' then null else o end);
      end if;
    end loop;
  end if;
  return null;
end;
$function$;

-- public.broadcast_reaction_change()  [security definer]
CREATE OR REPLACE FUNCTION public.broadcast_reaction_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cid uuid; sid uuid; uid uuid;
begin
  select channel_id into cid from public.messages where id = coalesce(new.message_id, old.message_id);
  if cid is null then return null; end if;
  select server_id into sid from public.channels where id = cid;
  if sid is not null then
    perform public.bc('chan:' || cid, 'reaction', tg_op, tg_table_name, tg_table_schema, new, old);
  else
    for uid in select user_id from public.channel_members where channel_id = cid loop
      perform public.bc('user:' || uid, 'reaction', tg_op, tg_table_name, tg_table_schema, new, old);
    end loop;
  end if;
  return null;
end;
$function$;

-- public.bug_hunter_on_fix()  [security definer]
CREATE OR REPLACE FUNCTION public.bug_hunter_on_fix()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status <> 'fixed' or old.status = 'fixed' then return new; end if;
  -- Only staff can mark reports fixed (RLS), and staff can't award themselves this way (admin_set_badge's
  -- mod limits would be skipped). SQL editor / service role (no auth.uid()) is fine.
  if auth.uid() is not null and (not (public.is_staff() or public.is_site_dev()) or (new.user_id = auth.uid() and not public.is_site_admin())) then
    return new;
  end if;
  if exists (select 1 from public.site_bans b where b.user_id = new.user_id and (b.expires_at is null or b.expires_at > now())) then
    return new;
  end if;
  -- Never let the badge stop the report from being marked fixed (e.g. a profile guard refusing the update).
  begin
    update public.profiles p set badges = array(select distinct unnest(coalesce(p.badges, '{}'::text[]) || 'bug_hunter'::text))
     where p.id = new.user_id and not ('bug_hunter' = any(coalesce(p.badges, '{}'::text[])));
    if found then
      insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'badge_auto', new.user_id, 'bug_hunter (report fixed)');
      perform public.rt_profile_changed(array[new.user_id]);
    end if;
  exception when others then
    raise warning 'bug_hunter_on_fix: % (report %)', sqlerrm, new.id;
  end;
  return new;
end $function$;

-- public.bug_images_ok(uid uuid, imgs text[])  [security definer]
CREATE OR REPLACE FUNCTION public.bug_images_ok(uid uuid, imgs text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'storage'
AS $function$
  select cardinality(coalesce(imgs, '{}')) <= 4
     and cardinality(coalesce(imgs, '{}')) = (select count(distinct p) from unnest(coalesce(imgs, '{}')) p)
     and not exists (
       select 1 from unnest(coalesce(imgs, '{}')) p
       where p is null
          or p !~ ('^' || uid::text || '/[A-Za-z0-9_-][A-Za-z0-9._-]{0,99}\.(png|jpe?g|webp)$')
          or not exists (select 1 from storage.objects o where o.bucket_id = 'proofs' and o.name = p
                         and coalesce(o.metadata ->> 'mimetype', '') in ('image/png', 'image/jpeg', 'image/webp')));
$function$;

-- public.bug_report_images_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.bug_report_images_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'UPDATE' and new.images is not distinct from old.images then return new; end if;
  if cardinality(new.images) > 0 then
    if auth.uid() is not null and not public.feature_on_for_me('bug_report_edit') then
      raise exception 'Screenshots on bug reports aren''t available yet';
    end if;
    if not public.bug_images_ok(new.user_id, new.images) then
      raise exception 'Those screenshots didn''t upload right. Try adding them again';
    end if;
  end if;
  return new;
end $function$;

-- public.bug_report_limit()  [security definer]
CREATE OR REPLACE FUNCTION public.bug_report_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform pg_advisory_xact_lock(hashtextextended('bug:' || new.user_id::text, 0));
  if (select count(*) from public.bug_reports where user_id = new.user_id and created_at > now() - interval '1 day') >= 5 then raise exception 'You can file 5 bug reports a day'; end if;
  if auth.uid() is not null and not public.is_staff() then
    new.status := 'open';
    new.staff_pick := false;
    new.staff_note := '';
    new.created_at := now();
    new.updated_at := null;
    new.edited_at := null;
  end if;
  return new;
end; $function$;

-- public.bump_member_count()  [security definer]
CREATE OR REPLACE FUNCTION public.bump_member_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    if public.is_bot_user(new.user_id) then return null; end if;
    update public.servers set member_count = member_count + 1 where id = new.server_id;
  elsif tg_op = 'DELETE' then
    if public.is_bot_user(old.user_id) then return null; end if;
    update public.servers set member_count = greatest(0, member_count - 1) where id = old.server_id;
  end if;
  return null;
end $function$;

-- public.buy_community_deco(p_id uuid, p_price integer)  [security definer]
CREATE OR REPLACE FUNCTION public.buy_community_deco(p_id uuid, p_price integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid()); d public.community_decos; cfg jsonb := public.shard_config(); share int;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if not public.feature_on_for_me('shards') then raise exception 'Not available yet'; end if;
  select * into d from public.community_decos where id = p_id for share;
  if not found or d.status <> 'approved' then raise exception 'That decoration isn''t available'; end if;
  if d.price is null then raise exception 'That one''s free'; end if;
  if d.price is distinct from p_price then raise exception 'The price changed to % Shards. Have another look.', d.price; end if;
  if d.artist_id = me then raise exception 'It''s yours already'; end if;
  if exists (select 1 from public.deco_owned where user_id = me and deco_id = p_id) then raise exception 'You have it already'; end if;
  if public.shard_is_bot(me) then raise exception 'Bots can''t buy decorations'; end if;
  if public.is_site_banned(d.artist_id) then raise exception 'That one isn''t for sale right now'; end if;
  if not public.deco_seller_ok(d.artist_id) then raise exception 'That one isn''t for sale yet'; end if;
  if not exists (select 1 from public.profiles where id = me
                 and created_at <= now() - make_interval(days => (cfg->>'buyer_age_days')::int)) then
    raise exception 'Your account needs to be a week old to buy decorations';
  end if;
  if public.shard_shared_device(me, d.artist_id) then raise exception 'You can''t buy from this artist'; end if;
  insert into public.shard_wallets (user_id) values (me), (d.artist_id) on conflict (user_id) do nothing;
  perform 1 from public.shard_wallets where user_id in (me, d.artist_id) order by user_id for update;
  perform public.shard_post(me, -d.price, 'deco_buy', p_id::text, d.name);
  share := (d.price * (cfg->>'artist_share')::int) / 100;
  begin
    perform public.shard_post(d.artist_id, share, 'deco_sale', p_id::text || ':' || me::text, d.name, me);
  exception when others then
    if sqlerrm <> 'Your Shards are frozen' then raise; end if;
  end;
  insert into public.deco_owned (user_id, deco_id, price_paid) values (me, p_id, d.price);
  return public.my_shards();
end; $function$;

-- public.call_e2ee(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.call_e2ee(cid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((
    select f.mode = 'everyone' or (f.mode = 'test' and case
      when c.server_id is not null then c.server_id = any(f.servers)
      else exists (select 1 from public.channel_members m
                    where m.channel_id = c.id and m.user_id = any(f.users))
    end)
    from public.channels c, public.feature_flags f
    where c.id = cid and c.kind in ('voice', 'dm', 'group') and f.key = 'call_e2ee'
      and public.can_access_channel(c.id)
  ), false);
$function$;

-- public.call_joined(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.call_joined(cid uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.calls set answered_at = now()
  where channel_id = cid and ended_at is null and answered_at is null
    and started_by <> auth.uid() and public.is_channel_member(cid);
$function$;

-- public.call_note()  [security definer]
CREATE OR REPLACE FUNCTION public.call_note()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare secs int; rang int; body text; sys jsonb;
begin
  if not exists (select 1 from public.channels c where c.id = new.channel_id and c.kind = 'dm') then return null; end if;
  if not exists (
    select 1 from public.feature_flags f
    where f.key = 'missed_calls'
      and (f.mode = 'everyone' or (f.mode = 'test' and exists (
        select 1 from public.channel_members cm
        where cm.channel_id = new.channel_id
          and (cm.user_id = any(f.users)
               or exists (select 1 from public.server_members sm where sm.user_id = cm.user_id and sm.server_id = any(f.servers))))))
  ) then return null; end if;

  if new.answered_at is null then
    if exists (
      select 1 from public.messages m
      where m.channel_id = new.channel_id and m.author_id = new.started_by
        and m.created_at > now() - interval '60 seconds' and m.system ->> 'kind' = 'call_missed'
    ) then return null; end if;
    rang := greatest(0, extract(epoch from (new.ended_at - new.started_at))::int);
    body := 'Missed call';
    sys := jsonb_build_object('kind', 'call_missed', 'rang', rang);
  else
    secs := greatest(0, extract(epoch from (new.ended_at - new.answered_at))::int);
    rang := greatest(0, extract(epoch from (new.answered_at - new.started_at))::int);
    body := 'Call, ' || case when secs < 60 then secs || ' sec' else (secs / 60) || ' min' end;
    sys := jsonb_build_object('kind', 'call', 'secs', secs, 'rang', rang);
  end if;

  begin
    perform set_config('yapper.bot', '1', true);
    perform set_config('yapper.system', '1', true);
    insert into public.messages (channel_id, author_id, content, system) values (new.channel_id, new.started_by, body, sys);
    perform set_config('yapper.bot', '', true);
    perform set_config('yapper.system', '', true);
  exception when others then
    perform set_config('yapper.bot', '', true);
    perform set_config('yapper.system', '', true);
  end;
  return null;
end;
$function$;

-- public.can_access_channel(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.can_access_channel(cid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
begin
  -- 593: a thread or forum post follows its parent channel.
  cid := coalesce((select ch.parent_id from public.channels ch where ch.id = cid), cid);
  return (
  select
    not public.is_site_banned(auth.uid())
    and (
      public.is_channel_member(cid)
      or exists (
        select 1 from public.channels c
        where c.id = cid and c.server_id is not null and public.is_server_member(c.server_id)
          and not exists (select 1 from public.servers sd where sd.id = c.server_id and sd.shut_down_at is not null and not public.is_staff())
          and case when exists (select 1 from public.feature_flags f where f.key = 'channel_perms'
                                and (f.mode = 'everyone' or (f.mode = 'test' and c.server_id = any(f.servers))))
                    and exists (select 1 from public.channel_overrides o where o.channel_id = c.id or o.category_id = c.category_id)
            then public.channel_perm_of(auth.uid(), c.id, 'view_channel', public.channel_view_base(c.id))
            else (
              not c.private
              or public.server_perm(c.server_id, 'manage_server')
              or exists (
                select 1 from public.channel_roles cr
                join public.member_roles mr on mr.role_id = cr.role_id and mr.user_id = auth.uid()
                where cr.channel_id = c.id
              )
              or exists (select 1 from public.channel_roles cr where cr.channel_id = c.id and public.auto_role_applies(cr.role_id, auth.uid()))
              or (public.is_staff() and c.ticket_by is null and exists (select 1 from public.channel_roles cr where cr.channel_id = c.id) and (public.is_site_admin() or public.staff_peek_ok(c.server_id)))
            ) end
      )
    )
  );
end;
$function$;

-- public.can_edit_role(rid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.can_edit_role(rid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.roles r join public.servers s on s.id = r.server_id where r.id = rid and s.owner_id = auth.uid())
    or exists (
      select 1 from public.roles r
      where r.id = rid and public.server_perm(r.server_id, 'manage_roles')
        and r.position < coalesce((select max(r2.position) from public.member_roles mr join public.roles r2 on r2.id = mr.role_id
                                   where mr.server_id = r.server_id and mr.user_id = auth.uid()), -1)
    );
$function$;

-- public.can_give_role_perms(sid uuid, rid uuid)
CREATE OR REPLACE FUNCTION public.can_give_role_perms(sid uuid, rid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare rp jsonb; rms boolean; rmm boolean; k text;
begin
  if exists (select 1 from public.servers where id = sid and owner_id = auth.uid()) or public.is_site_admin()
     or public.server_perm(sid, 'administrator') then
    return true;
  end if;
  select perms, manage_server, manage_messages into rp, rms, rmm from public.roles where id = rid and server_id = sid;
  if not found then return false; end if;
  -- The legacy Manage Server switch needs Administrator, as when editing a role.
  if coalesce(rms, false) then return false; end if;
  if coalesce(rmm, false) and not public.server_perm(sid, 'manage_messages') then return false; end if;
  -- Anything not plainly false counts (Administrator included: we know they don't have it).
  for k in select key from jsonb_each(coalesce(rp, '{}'::jsonb)) where value not in ('false'::jsonb, 'null'::jsonb) loop
    if not public.server_perm(sid, k) then return false; end if;
  end loop;
  return true;
end; $function$;

-- public.can_manage_overrides(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.can_manage_overrides(sid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select sid is not null and (public.server_perm(sid, 'manage_roles') or public.server_perm(sid, 'manage_channels'));
$function$;

-- public.can_post_channel(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.can_post_channel(cid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
begin
  -- 593: nobody posts in a forum itself (its posts are threads); a closed thread takes posts from mods only.
  if exists (select 1 from public.channels t where t.id = cid and t.kind = 'forum') then return false; end if;
  if exists (select 1 from public.channels t where t.id = cid and t.kind = 'thread' and t.locked /* forums_v2: locked, not closed */
             and not public.channel_allows(t.parent_id, 'manage_messages') and not public.channel_allows(t.parent_id, 'manage_threads')
             and not public.server_perm(t.server_id, 'manage_channels')) then return false; end if;
  -- 603: replying in a thread or forum post needs Send Messages in Threads on its parent.
  if exists (select 1 from public.channels t where t.id = cid and t.kind = 'thread'
             and not public.channel_allows(t.parent_id, 'send_in_threads')) then return false; end if;
  -- 593: a thread or forum post follows its parent channel.
  cid := coalesce((select ch.parent_id from public.channels ch where ch.id = cid), cid);
  return (
  select coalesce((
    select
      (c.server_id is null
        or case when exists (select 1 from public.feature_flags f where f.key = 'channel_perms'
                              and (f.mode = 'everyone' or (f.mode = 'test' and c.server_id = any(f.servers))))
                  and exists (select 1 from public.channel_overrides o where o.channel_id = c.id or o.category_id = c.category_id)
             then public.channel_perm(c.id, 'send_messages')
             else public.server_perm(c.server_id, 'send_messages') end)
      and (
        not c.read_only
        or public.server_perm(c.server_id, 'manage_server')
        or exists (
          select 1 from public.channel_post_roles cr
          join public.member_roles mr on mr.role_id = cr.role_id and mr.user_id = auth.uid()
          where cr.channel_id = c.id
        )
        or exists (select 1 from public.channel_post_roles cr where cr.channel_id = c.id and public.auto_role_applies(cr.role_id, auth.uid()))
      )
    from public.channels c where c.id = cid
  ), true)
  );
end;
$function$;

