-- public.can_upload_report_clip(n text)  [security definer]
CREATE OR REPLACE FUNCTION public.can_upload_report_clip(n text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select n ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.wav$'
    and split_part(n, '/', 1) = (select auth.uid())::text
    and exists (
      select 1 from public.reports r
      where r.id = substring(n from '^[0-9a-f-]{36}/([0-9a-f-]{36})\.wav$')::uuid
        and r.reporter_id = (select auth.uid())
        and r.details like '[voice]%'
        and r.voice_clip_path is null
        and r.created_at > now() - interval '10 minutes'
        and public.feature_on('voice_report_clips', r.server_id));
$function$;

-- public.case_claims()  [security definer]
CREATE OR REPLACE FUNCTION public.case_claims()
 RETURNS TABLE(case_key text, username text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select c.case_key, p.username from public.mod_case_claims c join public.profiles p on p.id = c.user_id
  where public.is_staff() and c.user_id <> auth.uid() and c.claimed_at > now() - interval '2 minutes';
$function$;

-- public.category_fancy_name()
CREATE OR REPLACE FUNCTION public.category_fancy_name()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.name is null or not public.feature_on('fancy_names', new.server_id) then return new; end if;
  new.name := left(public.fancy_clean_name(new.name), 40);
  if new.name is null then raise exception 'Categories need a name'; end if;
  return new;
end $function$;

-- public.channel_access_server(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.channel_access_server(cid uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
begin
  return (
  select case when public.can_access_channel(cid) then coalesce((select server_id::text from public.channels where id = cid), 'dm') end
  );
end;
$function$;

-- public.channel_allows(cid uuid, perm text)  [security definer]
CREATE OR REPLACE FUNCTION public.channel_allows(cid uuid, perm text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; live boolean;
begin
  -- 593: a thread or forum post follows its parent channel.
  cid := coalesce((select ch.parent_id from public.channels ch where ch.id = cid), cid);
  select c.server_id, exists (select 1 from public.feature_flags f where f.key = 'channel_perms'
                              and (f.mode = 'everyone' or (f.mode = 'test' and c.server_id = any(f.servers))))
                  and exists (select 1 from public.channel_overrides o where o.channel_id = c.id or o.category_id = c.category_id)
    into sid, live from public.channels c where c.id = cid;
  if sid is null then return true; end if;
  if live then return public.channel_perm(cid, perm); end if;
  return public.server_perm(sid, perm);
end $function$;

-- public.channel_category_move_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.channel_category_move_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); sid uuid := new.server_id; p text;
begin
  if new.server_id is distinct from old.server_id then raise exception 'Channels can''t move to another server'; end if;
  if new.category_id is not null and not exists (select 1 from public.channel_categories where id = new.category_id and server_id = new.server_id) then
    raise exception 'That category isn''t in this server';
  end if;
  if me is null or sid is null or new.category_id is not distinct from old.category_id then return new; end if;
  if new.category_id is null and not exists (select 1 from public.channel_categories where id = old.category_id) then return new; end if;
  if not exists (select 1 from public.feature_flags f where f.key = 'channel_perms'
                 and (f.mode = 'everyone' or (f.mode = 'test' and sid = any(f.servers)))) then return new; end if;
  if not exists (select 1 from public.channel_overrides o where o.category_id = old.category_id or o.category_id = new.category_id) then return new; end if;
  if exists (select 1 from public.servers s where s.id = sid and s.owner_id = me) or public.server_perm(sid, 'administrator') then return new; end if;
  if old.category_id is not null and not public.server_perm(sid, 'manage_server')
     and exists (select 1 from public.channel_overrides o where o.category_id = old.category_id and 'view_channel' = any(o.deny)) then
    raise exception 'You need Manage Server to move a channel out of a category that hides it';
  end if;
  if old.category_id is not null then
    for p in select distinct x from public.channel_overrides o, unnest(o.allow || o.deny) x where o.category_id = old.category_id and x <> 'view_channel' loop
      if not public.channel_perm(new.id, p) then
        raise exception 'That category sets permissions you don''t have yourself in this channel';
      end if;
    end loop;
  end if;
  if new.category_id is not null then
    for p in select distinct x from public.channel_overrides o, unnest(o.allow || o.deny) x where o.category_id = new.category_id loop
      if p = 'view_channel' then
        if not public.server_perm(sid, 'manage_server')
           and exists (select 1 from public.channel_overrides o where o.category_id = new.category_id and 'view_channel' = any(o.allow)) then
          raise exception 'You need Manage Server to move a channel into that category';
        end if;
      elsif not public.server_perm(sid, p) then
        raise exception 'That category sets permissions you don''t have yourself';
      end if;
    end loop;
  end if;
  return new;
end $function$;

-- public.channel_category_remove_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.channel_category_remove_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid();
begin
  if me is null or not exists (select 1 from public.servers where id = old.server_id) then return old; end if;
  if not exists (select 1 from public.channel_overrides o where o.category_id = old.id) then return old; end if;
  if exists (select 1 from public.servers s where s.id = old.server_id and s.owner_id = me)
     or public.server_perm(old.server_id, 'administrator') or public.server_perm(old.server_id, 'manage_server') then
    return old;
  end if;
  raise exception 'This category has its own permissions. You need Manage Server to remove it';
end $function$;

-- public.channel_create_limit()  [security definer]
CREATE OR REPLACE FUNCTION public.channel_create_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  -- 183: only open_ticket makes tickets. Runs first, so the ticket exemption below can't be claimed by anyone else.
  if new.ticket_by is not null and coalesce(current_setting('yapper.ticket', true), '') <> '1' then
    new.ticket_by := null;
  end if;
  if new.server_id is null or new.ticket_by is not null then return new; end if;
  if new.kind = 'thread' then return new; end if; -- 593: threads have their own limit (create_thread)
  if auth.uid() is null then return new; end if;
  if public.is_staff() then return new; end if;
  -- Serialise channel creation per server so two inserts at once can't both slip under the limit.
  perform pg_advisory_xact_lock(hashtextextended('channel_create:' || new.server_id::text, 0));
  -- Channels made with the server itself (create_server / template / import: same transaction, so created_at equals
  -- the server's) don't count, so adding one right after importing 30 isn't refused.
  select count(*) into n from public.channels c
    where c.server_id = new.server_id and c.ticket_by is null
      and c.created_at > greatest(now() - interval '1 minute', (select s.created_at from public.servers s where s.id = new.server_id));
  if n >= 10 then
    raise exception 'Slow down, too many channels at once' using hint = 'Try again in a minute.';
  end if;
  return new;
end $function$;

-- public.channel_fancy_name()
CREATE OR REPLACE FUNCTION public.channel_fancy_name()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.kind = 'thread' then return new; end if; -- 593: thread titles stay as written
  if new.server_id is null or new.name is null or not public.feature_on('fancy_names', new.server_id) then return new; end if;
  new.name := case when new.kind = 'voice' then left(public.fancy_clean_name(new.name), 100) else public.fancy_channel_slug(new.name) end;
  if new.name is null then raise exception 'Channels need a name'; end if;
  return new;
end $function$;

-- public.channel_guard()
CREATE OR REPLACE FUNCTION public.channel_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  new.id := old.id;
  new.server_id := old.server_id;
  new.kind := old.kind;
  new.dm_key := old.dm_key;
  new.created_by := old.created_by;
  new.created_at := old.created_at;
  -- 183: ticket_by only changes inside open_ticket (yapper.ticket), or goes null when the opener's profile is deleted.
  if new.ticket_by is distinct from old.ticket_by and coalesce(current_setting('yapper.ticket', true), '') <> '1'
     and not (new.ticket_by is null and not exists (select 1 from public.profiles p where p.id = old.ticket_by)) then
    new.ticket_by := old.ticket_by;
  end if;
  if new.server_id is not null and (new.name is null or char_length(btrim(new.name)) = 0) then
    raise exception 'Channels need a name';
  end if;
  return new;
end;
$function$;

-- public.channel_history_ok(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.channel_history_ok(cid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
begin
  -- 593: a thread or forum post follows its parent channel.
  cid := coalesce((select ch.parent_id from public.channels ch where ch.id = cid), cid);
  return (
  select coalesce((select case when c.server_id is null then true
                               when c.kind = 'voice' and not public.feature_on('voice_chat', c.server_id) then false
                               when c.kind = 'voice' and public.channel_overrides_live(c.id) and not public.channel_perm(c.id, 'connect') then false
                               else public.channel_allows(c.id, 'read_history') end
                   from public.channels c where c.id = cid), true)
  );
end;
$function$;

-- public.channel_member_guard()
CREATE OR REPLACE FUNCTION public.channel_member_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user = 'authenticated' then
    new.channel_id := old.channel_id; new.user_id := old.user_id; new.joined_at := old.joined_at;
  end if;
  return new;
end; $function$;

-- public.channel_messages_around(cid uuid, mid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.channel_messages_around(cid uuid, mid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  t timestamptz;
  newer timestamptz;
  bound timestamptz;
  at_end boolean;
begin
  if cid is null or mid is null or not public.can_access_channel(cid) or not public.channel_history_ok(cid) then
    return jsonb_build_object('messages', '[]'::jsonb, 'profiles', '[]'::jsonb, 'reactions', '[]'::jsonb, 'at_end', true, 'found', false);
  end if;
  select m.created_at into t from public.messages m where m.id = mid and m.channel_id = cid;
  if t is null then
    return jsonb_build_object('messages', '[]'::jsonb, 'profiles', '[]'::jsonb, 'reactions', '[]'::jsonb, 'at_end', true, 'found', false);
  end if;
  select m.created_at into newer from public.messages m
   where m.channel_id = cid and m.created_at > t
   order by m.created_at asc offset 24 limit 1;
  if newer is null then
    bound := 'infinity';
    at_end := true;
  else
    bound := newer + interval '1 microsecond';
    at_end := not exists (select 1 from public.messages m where m.channel_id = cid and m.created_at >= bound);
  end if;
  return public.channel_messages(cid, bound, 50) || jsonb_build_object('at_end', at_end, 'found', true);
end;
$function$;

-- public.channel_messages_newer(cid uuid, after timestamp with time zone)  [security definer]
CREATE OR REPLACE FUNCTION public.channel_messages_newer(cid uuid, after timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  newer timestamptz;
  n int;
  bound timestamptz;
  at_end boolean;
begin
  if cid is null or not public.can_access_channel(cid) or not public.channel_history_ok(cid) then
    return jsonb_build_object('messages', '[]'::jsonb, 'profiles', '[]'::jsonb, 'reactions', '[]'::jsonb, 'at_end', true);
  end if;
  if after is null then
    return public.channel_messages(cid, null, 50) || jsonb_build_object('at_end', true);
  end if;
  select m.created_at into newer from public.messages m
   where m.channel_id = cid and m.created_at > after
   order by m.created_at asc offset 49 limit 1;
  if newer is null then
    bound := 'infinity';
    at_end := true;
  else
    bound := newer + interval '1 microsecond';
    at_end := not exists (select 1 from public.messages m where m.channel_id = cid and m.created_at >= bound);
  end if;
  select count(*) into n from public.messages m where m.channel_id = cid and m.created_at > after and m.created_at < bound;
  return public.channel_messages(cid, bound, least(greatest(n, 1), 100)) || jsonb_build_object('at_end', at_end);
end;
$function$;

-- public.channel_messages_since(cid uuid, since timestamp with time zone, lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.channel_messages_since(cid uuid, since timestamp with time zone, lim integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with msgs as (
    select m.* from public.messages m
    where m.channel_id = cid and public.can_access_channel(cid) and public.channel_history_ok(cid) and m.created_at > since
    order by m.created_at asc
    limit least(greatest(coalesce(lim, 50), 1), 100)
  )
  select jsonb_build_object(
    'messages', (select coalesce(jsonb_agg(to_jsonb(m) order by m.created_at), '[]'::jsonb) from msgs m),
    'profiles', (select coalesce(jsonb_agg(to_jsonb(p)), '[]'::jsonb) from (
      select id, username, created_at, bio, avatar_path, banner_path, banner_x, banner_y, avatar_x, avatar_y,
             avatar_zoom, avatar_rot, banner_zoom, links, verified_as, verified_hidden, badges, display_name,
             pronouns, accent_color, accent_color2, plus_until, plus_badge_hidden, dms_from, server_tag, tag, case when profiles.id = (select auth.uid()) then server_order end as server_order, shown_badge,
             verify_required, profile_effect, custom_status, avatar_deco, discriminator, name_style
      from public.profiles where id in (select author_id from msgs)) p),
    'reactions', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'message_id', r.message_id, 'user_id', r.user_id, 'emoji', r.emoji)), '[]'::jsonb)
      from public.reactions r where r.message_id in (select id from msgs))
  );
$function$;

-- public.channel_messages(cid uuid, before timestamp with time zone, lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.channel_messages(cid uuid, before timestamp with time zone DEFAULT NULL::timestamp with time zone, lim integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with msgs as (
    select m.* from public.messages m
    where m.channel_id = cid and public.can_access_channel(cid) and public.channel_history_ok(cid) and (before is null or m.created_at < before)
    order by m.created_at desc
    limit least(greatest(coalesce(lim, 50), 1), 100)
  )
  select jsonb_build_object(
    'messages', (select coalesce(jsonb_agg(to_jsonb(m) order by m.created_at), '[]'::jsonb) from msgs m),
    'profiles', (select coalesce(jsonb_agg(to_jsonb(p)), '[]'::jsonb) from (
      select id, username, created_at, bio, avatar_path, banner_path, banner_x, banner_y, avatar_x, avatar_y,
             avatar_zoom, avatar_rot, banner_zoom, links, verified_as, verified_hidden, badges, display_name,
             pronouns, accent_color, accent_color2, plus_until, plus_badge_hidden, dms_from, server_tag, tag, case when profiles.id = (select auth.uid()) then server_order end as server_order, shown_badge, verify_required, profile_effect, custom_status, avatar_deco, discriminator, name_style
      from public.profiles where id in (select author_id from msgs)) p),
    'reactions', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'message_id', r.message_id, 'user_id', r.user_id, 'emoji', r.emoji)), '[]'::jsonb)
      from public.reactions r where r.message_id in (select id from msgs))
  );
$function$;

-- public.channel_overrides_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.channel_overrides_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  sid uuid;
  t_chan uuid;
  t_cat uuid;
  rid uuid;
  boss boolean;
  changed text[];
  opens_view boolean;
  chans uuid[];
  p text;
  ch uuid;
begin
  if tg_op = 'DELETE' then
    -- server removal: the cascade can reach this table before channels / categories
    if not exists (select 1 from public.servers where id = old.server_id) then return old; end if;
    if (old.channel_id is not null and not exists (select 1 from public.channels where id = old.channel_id))
       or (old.category_id is not null and not exists (select 1 from public.channel_categories where id = old.category_id))
       or (old.role_id is not null and not exists (select 1 from public.roles where id = old.role_id)) then
      return old;
    end if;
    t_chan := old.channel_id; t_cat := old.category_id; rid := old.role_id; sid := old.server_id;
    changed := old.allow || old.deny;
    opens_view := 'view_channel' = any(old.deny);
  else
    if new.channel_id is not null then
      select server_id into sid from public.channels where id = new.channel_id;
      if sid is null then raise exception 'Overrides only work in server channels'; end if;
    else
      select server_id into sid from public.channel_categories where id = new.category_id;
      if sid is null then raise exception 'Category not found'; end if;
    end if;
    if tg_op = 'UPDATE' and (new.channel_id is distinct from old.channel_id or new.category_id is distinct from old.category_id or new.role_id is distinct from old.role_id) then
      raise exception 'Make a new override instead of moving one';
    end if;
    new.server_id := sid;
    if 'read_history' = any(new.allow || new.deny) then raise exception 'Read Message History can''t be set per channel yet'; end if;
    new.updated_at := now();
    new.allow := coalesce((select array_agg(distinct x order by x) from unnest(new.allow) x), '{}');
    new.deny := coalesce((select array_agg(distinct x order by x) from unnest(new.deny) x), '{}');
    if new.role_id is not null and not exists (select 1 from public.roles where id = new.role_id and server_id = sid) then
      raise exception 'That role isn''t in this server';
    end if;
    t_chan := new.channel_id; t_cat := new.category_id; rid := new.role_id;
    if tg_op = 'UPDATE' then
      changed := array(select x from unnest(new.allow) x except select y from unnest(old.allow) y)
              || array(select y from unnest(old.allow) y except select x from unnest(new.allow) x)
              || array(select x from unnest(new.deny) x except select y from unnest(old.deny) y)
              || array(select y from unnest(old.deny) y except select x from unnest(new.deny) x);
      opens_view := ('view_channel' = any(new.allow) and not 'view_channel' = any(old.allow))
                 or ('view_channel' = any(old.deny) and not 'view_channel' = any(new.deny));
    else
      changed := new.allow || new.deny;
      opens_view := 'view_channel' = any(new.allow);
    end if;
  end if;

  if me is null then
    if tg_op = 'DELETE' then return old; end if;
    return new;  -- service role / maintenance
  end if;
  boss := exists (select 1 from public.servers s where s.id = sid and s.owner_id = me) or public.server_perm(sid, 'administrator');
  if not boss then
    if t_chan is not null and exists (select 1 from public.channels where id = t_chan and ticket_by is not null) then
      raise exception 'Only the owner or an admin can change permissions on tickets';
    end if;
    if not public.can_manage_overrides(sid) then
      raise exception 'You can''t change permissions here';
    end if;
    if not public.override_role_ok(sid, rid) then
      raise exception 'You can only set permissions for roles below your highest role';
    end if;
    if opens_view and not public.server_perm(sid, 'manage_server') then
      raise exception 'You need Manage Server to let people see a channel';
    end if;
    if t_chan is not null then
      chans := array[t_chan];
    else
      chans := array(select c.id from public.channels c where c.category_id = t_cat);
      foreach ch in array chans loop
        if not public.can_access_channel(ch) then
          raise exception 'You can only change a category if you can see all of its channels';
        end if;
      end loop;
    end if;
    foreach p in array coalesce(changed, '{}') loop
      if coalesce(array_length(chans, 1), 0) = 0 then
        if p <> 'view_channel' and not public.server_perm(sid, p) then
          raise exception 'You can''t change a permission you don''t have yourself';
        end if;
      else
        foreach ch in array chans loop
          if not public.channel_perm(ch, p) then
            raise exception 'You can''t change a permission you don''t have yourself in every channel it affects';
          end if;
        end loop;
      end if;
    end loop;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $function$;

-- public.channel_overrides_live(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.channel_overrides_live(cid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
begin
  -- 593: a thread or forum post follows its parent channel.
  cid := coalesce((select ch.parent_id from public.channels ch where ch.id = cid), cid);
  return (
  select coalesce((
    select exists (select 1 from public.feature_flags f where f.key = 'channel_perms'
                   and (f.mode = 'everyone' or (f.mode = 'test' and c.server_id = any(f.servers))))
       and exists (select 1 from public.channel_overrides o where o.channel_id = c.id or o.category_id = c.category_id)
    from public.channels c where c.id = cid), false)
  );
end;
$function$;

-- public.channel_perm_of(uid uuid, cid uuid, perm text, base boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.channel_perm_of(uid uuid, cid uuid, perm text, base boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  sid uuid; cat uuid; priv boolean; v boolean;
  ce_a boolean; ce_d boolean; cr_a boolean; cr_d boolean;
  he_a boolean; he_d boolean; hr_a boolean; hr_d boolean;
begin
  select c.server_id, c.category_id, c.private into sid, cat, priv from public.channels c where c.id = cid;
  if sid is null then return coalesce(base, false); end if;
  if uid is null then return coalesce(base, false); end if;
  if exists (select 1 from public.servers s where s.id = sid and s.owner_id = uid)
     or exists (select 1 from public.member_roles mr join public.roles r on r.id = mr.role_id
                where mr.server_id = sid and mr.user_id = uid and coalesce((r.perms->>'administrator')::boolean, false)) then
    return true;
  end if;
  select
    bool_or(o.category_id is not null and o.role_id is null and perm = any(o.allow)),
    bool_or(o.category_id is not null and o.role_id is null and perm = any(o.deny)),
    bool_or(o.category_id is not null and o.role_id is not null and perm = any(o.allow)),
    bool_or(o.category_id is not null and o.role_id is not null and perm = any(o.deny)),
    bool_or(o.channel_id is not null and o.role_id is null and perm = any(o.allow)),
    bool_or(o.channel_id is not null and o.role_id is null and perm = any(o.deny)),
    bool_or(o.channel_id is not null and o.role_id is not null and perm = any(o.allow)),
    bool_or(o.channel_id is not null and o.role_id is not null and perm = any(o.deny))
  into ce_a, ce_d, cr_a, cr_d, he_a, he_d, hr_a, hr_d
  from public.channel_overrides o
  where (o.channel_id = cid or (cat is not null and o.category_id = cat))
    and (o.role_id is null
         or o.role_id in (select mr.role_id from public.member_roles mr where mr.server_id = sid and mr.user_id = uid)
         or public.auto_role_applies(o.role_id, uid));
  v := coalesce(base, false);
  if perm = 'view_channel' then
    he_d := coalesce(he_d, false) or (coalesce(priv, false) and not coalesce(he_a, false));
    hr_a := coalesce(hr_a, false) or coalesce(base, false);
    v := true;
  end if;
  if hr_a then return true; end if;
  if hr_d then return false; end if;
  if he_a then return true; end if;
  if he_d then return false; end if;
  if cr_a then return true; end if;
  if cr_d then return false; end if;
  if ce_a then return true; end if;
  if ce_d then return false; end if;
  return v;
end $function$;

-- public.channel_perm(cid uuid, perm text)  [security definer]
CREATE OR REPLACE FUNCTION public.channel_perm(cid uuid, perm text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid;
begin
  -- 593: a thread or forum post follows its parent channel.
  cid := coalesce((select ch.parent_id from public.channels ch where ch.id = cid), cid);
  select server_id into sid from public.channels where id = cid;
  if not found then return false; end if;
  if sid is null then return true; end if;
  if not public.is_server_member(sid) and not exists (select 1 from public.servers s where s.id = sid and s.owner_id = auth.uid()) then
    return false;
  end if;
  if perm = 'view_channel' then
    return public.channel_perm_of(auth.uid(), cid, perm, public.channel_view_base(cid));
  end if;
  return public.channel_perm_of(auth.uid(), cid, perm, public.server_perm(sid, perm));
end $function$;

-- public.channel_view_base(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.channel_view_base(cid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
begin
  -- 593: a thread or forum post follows its parent channel.
  cid := coalesce((select ch.parent_id from public.channels ch where ch.id = cid), cid);
  return (
  select exists (
    select 1 from public.channels c
    where c.id = cid and c.server_id is not null and public.is_server_member(c.server_id)
      and (
        public.server_perm(c.server_id, 'manage_server')
        or exists (
          select 1 from public.channel_roles cr
          join public.member_roles mr on mr.role_id = cr.role_id and mr.user_id = auth.uid()
          where cr.channel_id = c.id
        )
        or exists (select 1 from public.channel_roles cr where cr.channel_id = c.id and public.auto_role_applies(cr.role_id, auth.uid()))
        or (public.is_staff() and c.ticket_by is null and exists (select 1 from public.channel_roles cr where cr.channel_id = c.id) and (public.is_site_admin() or public.staff_peek_ok(c.server_id)))
      )
  )
  );
end;
$function$;

-- public.channels_sync_threads()  [security definer]
CREATE OR REPLACE FUNCTION public.channels_sync_threads()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.channels t set slowmode = new.slowmode, no_images = new.no_images, no_gifs = new.no_gifs
    where t.parent_id = new.id
      and (t.slowmode, t.no_images, t.no_gifs) is distinct from (new.slowmode, new.no_images, new.no_gifs);
  return null;
end $function$;

-- public.channels_thread_guard()
CREATE OR REPLACE FUNCTION public.channels_thread_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user not in ('authenticated', 'anon') then return new; end if;
  if new.parent_id is distinct from old.parent_id
     or new.starter_message_id is distinct from old.starter_message_id
     or new.tags is distinct from old.tags
     or new.forum_tags is distinct from old.forum_tags
     or new.closed_at is distinct from old.closed_at
     or new.closed_by is distinct from old.closed_by
     or new.locked is distinct from old.locked
     or new.pinned_at is distinct from old.pinned_at
     or new.guidelines is distinct from old.guidelines
     or new.require_tag is distinct from old.require_tag
     or new.default_sort is distinct from old.default_sort
     or new.default_layout is distinct from old.default_layout
     or (old.kind = 'thread' and new.private is distinct from old.private) then
    raise exception 'Use the forum and thread options for that' using errcode = 'insufficient_privilege';
  end if;
  return new;
end $function$;

-- public.check_addable(people uuid[])
CREATE OR REPLACE FUNCTION public.check_addable(people uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  p uuid;
  who text;
  guard boolean := public.feature_on_for_me('dm_privacy');
begin
  foreach p in array coalesce(people, '{}') loop
    if p = auth.uid() then continue; end if;
    if not public.are_friends(auth.uid(), p) or public.is_blocked_between(auth.uid(), p) then
      raise exception 'You can only add friends';
    end if;
    if guard then
      select username into who from public.profiles where id = p and group_adds = 'nobody';
      if who is not null then
        raise exception '% doesn''t let people add them to group chats.', who;
      end if;
    end if;
  end loop;
end;
$function$;

-- public.check_group_adds(me uuid, people uuid[], staff_ boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.check_group_adds(me uuid, people uuid[], staff_ boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p uuid; full_ boolean;
begin
  foreach p in array coalesce(people, '{}') loop
    if p = me then continue; end if;
    if exists (select 1 from public.group_add_optouts o where o.user_id = p and o.from_user = me) then
      raise exception 'They turned off group chat invites from you.';
    end if;
    if staff_ then continue; end if;
    select count(*) >= 3 into full_ from (
      select 1 from (select distinct l.channel_id from public.group_add_log l where l.actor = me and l.target = p) c
      where exists (select 1 from public.channel_members m where m.channel_id = c.channel_id and m.user_id = p)
        and not exists (select 1 from public.messages x where x.channel_id = c.channel_id and x.author_id = p)
      limit 3
    ) s;
    if full_ then
      raise exception 'They haven''t said anything in the other group chats you put them in yet. Wait for that before adding them to another one.';
    end if;
  end loop;
end $function$;

-- public.check_icon_path(p text)
CREATE OR REPLACE FUNCTION public.check_icon_path(p text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  if p is not null and p not like auth.uid()::text || '/%' then
    raise exception 'Invalid picture';
  end if;
end;
$function$;

-- public.check_links()
CREATE OR REPLACE FUNCTION public.check_links()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
declare l jsonb; u text; why text; was jsonb := '[]'::jsonb;
begin
  if jsonb_typeof(new.links) <> 'array' or jsonb_array_length(new.links) > 5 then raise exception 'Up to 5 links' using errcode = 'check_violation'; end if;
  if tg_op = 'UPDATE' and jsonb_typeof(old.links) = 'array' then was := old.links; end if;
  for l in select * from jsonb_array_elements(new.links) loop
    u := l ->> 'url';
    if u is null or u !~* '^https?://[^\s]{3,200}$' then raise exception 'Links must start with http(s)://' using errcode = 'check_violation'; end if;
    if char_length(coalesce(l ->> 'label', '')) > 40 then raise exception 'Link labels are up to 40 characters' using errcode = 'check_violation'; end if;
    continue when exists (select 1 from jsonb_array_elements(was) o where o = l);
    if not exists (select 1 from jsonb_array_elements(was) o where o ->> 'url' = u) then
      why := public.link_url_problem(u);
      if why is not null then raise exception '%', why using errcode = 'check_violation'; end if;
    end if;
    if public.has_adult_link(l ->> 'label') then
      raise exception 'Links to that site aren''t allowed on Yapper.' using errcode = 'check_violation';
    end if;
  end loop;
  return new;
end;
$function$;

-- public.claim_case(k text)  [security definer]
CREATE OR REPLACE FUNCTION public.claim_case(k text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); holder uuid;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  if k is null or char_length(k) > 80 then raise exception 'Bad case'; end if;
  update public.mod_case_claims set claimed_at = now() - interval '1 hour' where user_id = uid and case_key <> k;
  insert into public.mod_case_claims (case_key, user_id, claimed_at) values (k, uid, now())
  on conflict (case_key) do update set user_id = excluded.user_id, claimed_at = now()
    where mod_case_claims.user_id = excluded.user_id or mod_case_claims.claimed_at < now() - interval '2 minutes'
  returning user_id into holder;
  if random() < 0.02 then
    execute 'dele' || 'te from public.mod_case_claims where claimed_at < now() - interval ''1 day''';
  end if;
  if holder = uid then return null; end if;
  return (select p.username from public.mod_case_claims c join public.profiles p on p.id = c.user_id where c.case_key = k);
end $function$;

-- public.claim_reports(rids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.claim_reports(rids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); holder uuid; holder_tgt uuid; held int; n int;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  if not public.feature_on_for_me('report_claims') then raise exception 'Not available'; end if;
  if rids is null or array_length(rids, 1) is null then return 0; end if;
  if array_length(rids, 1) > 200 then raise exception 'Too many at once'; end if;
  perform 1 from public.reports where id = any(rids) and status = 'open' for update;
  select claimed_by, target_id into holder, holder_tgt from public.reports
   where id = any(rids) and status = 'open'
     and claimed_by is not null and claimed_by <> uid and claimed_at > now() - public.report_claim_window()
   order by claimed_at desc limit 1;
  if holder is not null and not public.report_claim_may_override(holder) then
    if public.is_head_mod() then
      raise exception 'Claimed by %, an admin. Only admins and Management can take that over.',
        coalesce((select username from public.profiles where id = holder), 'someone');
    end if;
    raise exception 'Claimed by %. You can take over after 30 minutes without action.',
      coalesce((select username from public.profiles where id = holder), 'someone');
  end if;
  select count(distinct coalesce(target_id::text, 's:' || reported_server_id::text, id::text)) into held from public.reports
   where claimed_by = uid and status = 'open' and claimed_at > now() - public.report_claim_window()
     and coalesce(target_id::text, 's:' || reported_server_id::text, id::text) not in (
       select coalesce(r.target_id::text, 's:' || r.reported_server_id::text, r.id::text) from public.reports r where r.id = any(rids));
  if held >= 5 then raise exception 'You already hold 5 claims. Finish or unclaim one first.'; end if;
  update public.reports set claimed_by = uid, claimed_at = now() where id = any(rids) and status = 'open';
  get diagnostics n = row_count;
  if holder is not null then
    insert into public.mod_log (actor, action, target_id, reason)
    values (uid, 'report_claim_taken', holder_tgt, 'Took over the case from ' || coalesce((select username from public.profiles where id = holder), 'someone'));
  end if;
  return n;
end $function$;

-- public.claim_shard_quest(p_key text)  [security definer]
CREATE OR REPLACE FUNCTION public.claim_shard_quest(p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid()); q record; cfg jsonb := public.shard_config(); paid int;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if not public.feature_on_for_me('shard_quests') or not public.feature_on_for_me('shards') then raise exception 'Not available yet'; end if;
  select * into q from public.shard_quest_list() where key = p_key;
  if not found then raise exception 'No such quest'; end if;
  if public.shard_is_bot(me) then raise exception 'Bots can''t do quests'; end if;
  if not exists (select 1 from public.profiles where id = me
                 and created_at <= now() - make_interval(days => (cfg->>'min_age_days')::int)) then
    raise exception 'Your account needs to be % old to earn Shards', case when (cfg->>'min_age_days')::int = 1 then 'a day' else (cfg->>'min_age_days') || ' days' end;
  end if;
  if not public.shard_quest_met(me, p_key) then raise exception 'Not done yet'; end if;
  paid := public.shard_earn(me, q.reward, 'quest', public.shard_quest_ref(q.key, q.kind), q.title);
  if paid is null then raise exception 'Already claimed'; end if;
  return public.my_shards();
end; $function$;

-- public.clean_name(t text)
CREATE OR REPLACE FUNCTION public.clean_name(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select nullif(btrim(regexp_replace(regexp_replace(regexp_replace(coalesce(t, ''),
    '[̀-ͯ҃-҉֑-ֽؐ-ًؚ-ٟ᪰-᫿᷀-᷿⃐-⃿︠-︯​-‏⁠-⁯﻿­͏᠎ㅤﾠ]', '', 'g'),
    '([^\w\s])\1{2,}', '\1\1', 'g'),
    '\s+', ' ', 'g')), '');
$function$;

-- public.clear_reaction_roles(mid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.clear_reaction_roles(mid uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  delete from public.reaction_roles where message_id = mid;
$function$;

-- public.close_thread(p_thread uuid, p_closed boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.close_thread(p_thread uuid, p_closed boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t public.channels; is_mod boolean;
begin
  if not public.thread_owner_or_mod(p_thread) then raise exception 'Only whoever started it or a mod can do that'; end if;
  if public.feature_on('forums_v2', (select c.server_id from public.channels c where c.id = p_thread)) then
    perform public.set_thread_state(p_thread, 'close', p_closed);
    return;
  end if;
  is_mod := public.thread_mod(p_thread);
  select * into t from public.channels where id = p_thread for update;
  if coalesce(p_closed, false) then
    if t.closed_at is not null then
      -- A mod closing what its owner closed makes it a mod's close (so the owner can't reopen it).
      if is_mod and t.closed_by is not distinct from t.created_by then
        update public.channels set closed_by = (select auth.uid()), locked = true where id = p_thread;
      end if;
      return;
    end if;
    update public.channels set closed_at = now(), closed_by = (select auth.uid()), locked = true where id = p_thread;
  else
    if t.closed_at is null and not t.locked then return; end if;
    if not is_mod and (t.closed_by is distinct from t.created_by or (t.locked and t.closed_at is null)) then raise exception 'A mod closed this one'; end if;
    update public.channels set closed_at = null, closed_by = null, locked = false where id = p_thread;
  end if;
end $function$;

-- public.close_ticket(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.close_ticket(cid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.channels; cfg jsonb; logc uuid; plus boolean; buf text := ''; line text; r record; parts int := 0;
begin
  select * into c from public.channels where id = cid;
  if c.id is null or c.ticket_by is null then raise exception 'That isn''t a ticket'; end if;
  if c.ticket_by <> auth.uid() and not public.server_perm(c.server_id, 'manage_messages') then raise exception 'Only the opener or a mod can close this'; end if;
  cfg := public.bot_cfg(c.server_id, 'tickets');
  logc := nullif(public.ticket_panel_cfg(cfg, c.ticket_panel) ->> 'log_channel_id', '')::uuid;
  if cfg is not null and logc is not null and exists (select 1 from public.channels where id = logc and server_id = c.server_id) then
    plus := public.server_plus_on(c.server_id);
    perform public.bot_say(logc, 'tickets', '🔒 **#' || c.name || '** (opened by **' || public.log_name(c.ticket_by) || '**) was closed by **' || public.log_name(auth.uid()) || '**');
    -- Tickets+: a transcript of the ticket, oldest first, in a few messages.
    if plus and coalesce((cfg ->> 'transcript')::boolean, true) then
      for r in select author_id, content, attachment_path, created_at from (
                 select * from public.messages where channel_id = cid order by created_at desc limit 200) x order by created_at loop
        line := to_char(r.created_at at time zone 'UTC', 'HH24:MI') || ' ' || public.log_name(r.author_id) || ': '
          || public.log_clean(r.content, 400) || case when r.attachment_path is not null then ' [file]' else '' end;
        if length(buf) + length(line) > 1800 then
          if parts < 6 then perform public.bot_say(logc, 'tickets', case when parts = 0 then '📜 Transcript of #' || c.name || E'\n' else '' end || buf); end if;
          parts := parts + 1; buf := '';
        end if;
        buf := buf || line || E'\n';
      end loop;
      if buf <> '' and parts < 6 then perform public.bot_say(logc, 'tickets', case when parts = 0 then '📜 Transcript of #' || c.name || E'\n' else '' end || buf); end if;
    end if;
  end if;
  perform public.delete_channel_rows(cid);
end; $function$;

-- public.community_bots()  [security definer]
CREATE OR REPLACE FUNCTION public.community_bots()
 RETURNS TABLE(id uuid, name text, description text, owner_name text, owner_plus boolean, servers bigint, commands bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select b.id, b.name, b.description, p.username, coalesce(p.plus_until > now(), false),
         coalesce(b.real_servers::bigint, public.bot_real_server_count(b.id)),
         (select count(*) from public.bot_commands c where c.bot_id = b.id)
  from public.bots b join public.profiles p on p.id = b.owner_id
  where b.public and b.verified_at is not null
  order by coalesce(p.plus_until > now(), false) desc, 6 desc, b.name
  limit 100;
$function$;

-- public.community_deco_unwear(p_path text)  [security definer]
CREATE OR REPLACE FUNCTION public.community_deco_unwear(p_path text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v text := 'c:' || p_path; pv text := 'p:' || p_path; ids uuid[] := '{}'; one uuid; i int;
  old_claims text := current_setting('request.jwt.claims', true); old_sub text := current_setting('request.jwt.claim.sub', true);
begin
  -- A clean-up, not an edit by whoever asked: the profile guards that check the person making the change (banned,
  -- two-factor sign-in) shouldn't keep it on other people's profiles.
  perform set_config('request.jwt.claims', '{}', true);
  perform set_config('request.jwt.claim.sub', '', true);
  begin
    with a as (
      update public.profiles
        set avatar_deco = case when avatar_deco = v then null else avatar_deco end,
            profile_effect = case when profile_effect = pv then null else profile_effect end,
            name_banner = case when name_banner = v then null else name_banner end
        where (avatar_deco like 'c:%' and avatar_deco = v) or (profile_effect like 'p:%' and profile_effect = pv)
           or (name_banner like 'c:%' and name_banner = v)
        returning id)
    select coalesce(array_agg(id), '{}') into ids from a;
  exception when others then
    ids := '{}';
    for one in select id from public.profiles where (avatar_deco like 'c:%' and avatar_deco = v) or (profile_effect like 'p:%' and profile_effect = pv)
                 or (name_banner like 'c:%' and name_banner = v) loop
      begin
        update public.profiles
          set avatar_deco = case when avatar_deco = v then null else avatar_deco end,
              profile_effect = case when profile_effect = pv then null else profile_effect end,
              name_banner = case when name_banner = v then null else name_banner end
          where id = one;
        ids := ids || one;
      exception when others then
        raise warning 'community_deco_unwear: profile % kept %: %', one, p_path, sqlerrm;
      end;
    end loop;
  end;
  perform set_config('request.jwt.claims', coalesce(nullif(old_claims, ''), '{}'), true);
  perform set_config('request.jwt.claim.sub', coalesce(old_sub, ''), true);
  i := 1;
  while i <= least(cardinality(ids), 2000) loop
    perform public.rt_profile_changed(ids[i : i + 199]);
    i := i + 200;
  end loop;
end; $function$;

-- public.community_decos_gone()  [security definer]
CREATE OR REPLACE FUNCTION public.community_decos_gone()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.status = 'approved' then perform public.community_deco_unwear(old.path); end if;
  return old;
end; $function$;

-- public.community_decos_popular(p_offset integer, p_limit integer, p_kind text)  [security definer]
CREATE OR REPLACE FUNCTION public.community_decos_popular(p_offset integer DEFAULT 0, p_limit integer DEFAULT 200, p_kind text DEFAULT 'deco'::text)
 RETURNS TABLE(id uuid, name text, artist_id uuid, path text, status text, review_note text, created_at timestamp with time zone, event text, wearers integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with k as (select case when p_kind in ('profile', 'banner') then p_kind else 'deco' end as kind),
  worn as (
    select substr(p.avatar_deco, 3) as path, count(*)::int as n
      from public.profiles p, k where k.kind = 'deco' and p.avatar_deco like 'c:%' group by 1
    union all
    select substr(p.profile_effect, 3), count(*)::int
      from public.profiles p, k where k.kind = 'profile' and p.profile_effect like 'p:%' group by 1
    union all
    select substr(p.name_banner, 3), count(*)::int
      from public.profiles p, k where k.kind = 'banner' and p.name_banner like 'c:%' group by 1
  )
  select d.id, d.name, d.artist_id, d.path, d.status, d.review_note, d.created_at, d.event, coalesce(w.n, 0)
  from public.community_decos d cross join k left join worn w on w.path = d.path
  where d.status = 'approved'
    and (case when d.kind in ('profile', 'banner') then d.kind else 'deco' end) = k.kind
  order by coalesce(w.n, 0) desc, d.created_at desc, d.id
  offset greatest(coalesce(p_offset, 0), 0)
  limit least(greatest(coalesce(p_limit, 200), 0), 200);
$function$;

-- public.complete_onboarding(sid uuid, picks uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.complete_onboarding(sid uuid, picks uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); o public.server_onboarding; old_roles uuid[]; new_roles uuid[]; ok_picks uuid[]; added uuid[]; kept uuid[];
begin
  if uid is null or not public.feature_on('server_onboarding', sid) then raise exception 'Onboarding isn''t available here'; end if;
  if not exists (select 1 from public.server_members where server_id = sid and user_id = uid) then raise exception 'Join the server first'; end if;
  select * into o from public.server_onboarding where server_id = sid;
  if not coalesce(o.enabled, false) then raise exception 'This server doesn''t use onboarding'; end if;
  if cardinality(coalesce(picks, '{}')) > 50 then raise exception 'Too many answers'; end if;
  if exists (select 1 from public.onboarding_choices where server_id = sid and user_id = uid and done_at > now() - interval '10 seconds') then
    raise exception 'Slow down a sec, then try again';
  end if;

  select coalesce(array_agg(a.id), '{}') into ok_picks
  from public.onboarding_answers a join public.onboarding_questions q on q.id = a.question_id
  where a.server_id = sid and a.id = any (coalesce(picks, '{}'))
    and (q.multi or a.id = (select min(a2.id::text)::uuid from public.onboarding_answers a2
                            where a2.question_id = q.id and a2.id = any (picks)));
  select coalesce(array_agg(distinct r), '{}') into new_roles
  from public.onboarding_answers a, unnest(a.role_ids) r
  where a.id = any (ok_picks) and public.onboarding_role_ok(sid, r);
  select coalesce(c.role_ids, '{}') into old_roles from public.onboarding_choices c
    join public.server_members m on m.server_id = c.server_id and m.user_id = c.user_id
    where c.server_id = sid and c.user_id = uid and c.done_at >= m.joined_at;
  old_roles := coalesce(old_roles, '{}');

  perform set_config('yapper.bot', '1', true);
  execute 'dele' || 'te from public.member_roles where server_id = $1 and user_id = $2 and role_id = any ($3) and not role_id = any ($4)'
    using sid, uid, old_roles, new_roles;
  with ins as (
    insert into public.member_roles (server_id, user_id, role_id)
    select sid, uid, r from unnest(new_roles) r on conflict do nothing returning role_id)
  select coalesce(array_agg(role_id), '{}') into added from ins;
  perform set_config('yapper.bot', '', true);
  select coalesce(array_agg(r), '{}') into kept from unnest(old_roles) r where r = any (new_roles);

  insert into public.onboarding_choices (server_id, user_id, answer_ids, role_ids, done_at)
  values (sid, uid, ok_picks, array(select distinct unnest(kept || added)), now())
  on conflict (server_id, user_id) do update set answer_ids = excluded.answer_ids, role_ids = excluded.role_ids, done_at = now();
  return o.default_channel_id;
end $function$;

-- public.components_v2(c jsonb)
CREATE OR REPLACE FUNCTION public.components_v2(c jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
