-- public.create_category(sid uuid, p_name text)  [security definer]
CREATE OR REPLACE FUNCTION public.create_category(sid uuid, p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cid uuid; n text := btrim(coalesce(p_name, ''));
begin
  if not public.server_perm(sid, 'manage_channels') then raise exception 'You can''t manage channels here'; end if;
  if char_length(n) not between 1 and 40 then raise exception 'Category names are 1 to 40 characters'; end if;
  if (select count(*) from public.channel_categories where server_id = sid) >= 50 then raise exception 'Up to 50 categories'; end if;
  insert into public.channel_categories (server_id, name, position)
    values (sid, n, coalesce((select max(position) + 1 from public.channel_categories where server_id = sid), 0))
    returning id into cid;
  return cid;
end; $function$;

-- public.create_channel(sid uuid, channel_name text, channel_kind text)  [security definer]
CREATE OR REPLACE FUNCTION public.create_channel(sid uuid, channel_name text, channel_kind text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cid uuid; k text := coalesce(channel_kind, 'text'); n text;
begin
  -- 593: text, voice, or a forum where the forums flag is on.
  if k not in ('text', 'voice') and not (k = 'forum' and public.feature_on('forums', sid)) then raise exception 'Unknown channel type'; end if;
  if not public.server_perm(sid, 'manage_channels') then raise exception 'You can''t manage channels here'; end if;
  if k = 'voice' then
    n := left(nullif(regexp_replace(btrim(channel_name), '\s+', ' ', 'g'), ''), 100);
  else
    n := case when public.feature_on('fancy_names', sid) then public.fancy_channel_slug(channel_name) else public.slugify_channel(channel_name) end;
  end if;
  if n is null then raise exception 'Channels need a name'; end if;
  if (select count(*) from public.channels where server_id = sid and kind <> 'thread') >= 100 then raise exception 'Too many channels'; end if;
  insert into public.channels (kind, name, server_id, created_by, position)
    values (k, n, sid, auth.uid(), coalesce((select max(position) + 1 from public.channels where server_id = sid), 0))
    returning id into cid;
  return cid;
end;
$function$;

-- public.create_group(group_name text, group_icon text, member_ids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.create_group(group_name text, group_icon text, member_ids uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  people uuid[];
  cid uuid;
  staff_ boolean;
  n int;
  today int := 0;
begin
  if me is null then raise exception 'Not signed in'; end if;
  people := array(select distinct x from unnest(coalesce(member_ids, '{}')) x where x <> me);
  if cardinality(people) < 1 then raise exception 'Pick at least one friend'; end if;
  if cardinality(people) > 9 then raise exception 'Group chats can have up to 10 people'; end if;
  perform public.check_addable(people);
  perform public.check_icon_path(group_icon);

  staff_ := coalesce(public.is_staff(), false);
  if not staff_ then
    perform pg_advisory_xact_lock(hashtext('gc_cap:' || me::text));
    select count(*) into n from (
      select 1 from public.channels c
      where c.kind = 'group' and c.created_by = me
        and exists (select 1 from public.channel_members m where m.channel_id = c.id and m.user_id = me)
      limit 20
    ) s;
    if n >= 20 then raise exception 'You already have 20 group chats going. Leave one to make a new one.'; end if;
    select count(distinct channel_id) into n from public.group_add_log
      where actor = me and via = 'create' and created_at > now() - interval '10 minutes';
    if n >= 3 then raise exception 'Slow down. You can make 3 group chats every 10 minutes.'; end if;
    select count(distinct channel_id) into today from public.group_add_log
      where actor = me and via = 'create' and created_at > now() - interval '1 day';
    if today >= 10 then raise exception 'That''s enough group chats for today. Try again tomorrow.'; end if;
  end if;
  perform public.check_group_adds(me, people, staff_);

  insert into public.channels (kind, name, icon_path, created_by)
    values ('group', nullif(btrim(group_name), ''), group_icon, me)
    returning id into cid;
  insert into public.channel_members (channel_id, user_id)
    select cid, x from unnest(people || me) x;
  insert into public.group_add_log (actor, target, channel_id, via)
    select me, x, cid, 'create' from unnest(people) x;
  if not staff_ and today + 1 >= 10 then perform public.group_spam_alert(me); end if;
  return cid;
end;
$function$;

-- public.create_poll_ex(cid uuid, question text, opts text[], multi boolean, hours integer, quiz boolean, correct text[], reveal text, anon boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.create_poll_ex(cid uuid, question text, opts text[], multi boolean DEFAULT false, hours integer DEFAULT 24, quiz boolean DEFAULT false, correct text[] DEFAULT '{}'::text[], reveal text DEFAULT 'vote'::text, anon boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; pid uuid; n int := coalesce(array_length(opts, 1), 0); ok text[];
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  select server_id into sid from public.channels where id = cid;
  if not (public.feature_on('quiz_polls', sid) or public.feature_on_for_me('quiz_polls')) then
    raise exception 'Quiz polls aren''t available here yet';
  end if;
  if quiz then
    select coalesce(array_agg(distinct x order by x), '{}') into ok from unnest(coalesce(correct, '{}')) x
     where x ~ '^[0-9]+$' and x::int between 1 and n;
    if coalesce(array_length(ok, 1), 0) = 0 then raise exception 'Mark the right answer'; end if;
    if ok is distinct from (select coalesce(array_agg(distinct x order by x), '{}') from unnest(correct) x) then raise exception 'Mark the right answer'; end if;
    if array_length(ok, 1) = n then raise exception 'Not every answer can be right'; end if;
    if coalesce(reveal, '') not in ('vote', 'close') then raise exception 'Pick when to show the answer'; end if;
    if reveal = 'close' and coalesce(hours, 0) <= 0 then raise exception 'Pick when the quiz ends to show the answer then'; end if;
  end if;
  pid := public.create_poll(cid, question, opts, multi, hours);
  update public.polls set quiz = create_poll_ex.quiz, reveal = case when create_poll_ex.quiz then create_poll_ex.reveal else 'vote' end,
         anonymous = coalesce(anon, false)
   where id = pid;
  if quiz then
    insert into public.poll_answers (poll_id, correct) values (pid, ok) on conflict (poll_id) do update set correct = excluded.correct;
  end if;
  return pid;
end;
$function$;

-- public.create_poll(cid uuid, question text, opts text[], multi boolean, hours integer)  [security definer]
CREATE OR REPLACE FUNCTION public.create_poll(cid uuid, question text, opts text[], multi boolean DEFAULT false, hours integer DEFAULT 24)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; mid uuid; pid uuid; o jsonb := '[]'::jsonb; i int; last_at timestamptz;
begin
  select server_id into sid from public.channels where id = cid;
  if not public.can_access_channel(cid) then raise exception 'Channel not found'; end if;
  if not public.can_post_channel(cid) or public.dm_blocked(cid) then raise exception 'You can''t post in this channel'; end if;
  -- The Create Polls permission (role or @everyone) was never checked here.
  if sid is not null and not public.server_perm(sid, 'create_polls') then raise exception 'You can''t create polls in this server'; end if;
  -- Yapper HQ: polls are for verified people, Bug Hunters and Plus members (and staff / server managers).
  if sid is not null and sid = (select default_server_id from public.app_settings limit 1)
     and not public.is_staff() and not public.server_perm(sid, 'manage_server')
     and not exists (select 1 from public.profiles p where p.id = auth.uid()
                     and (p.verified_as is not null or 'bug_hunter' = any(coalesce(p.badges, '{}'::text[])) or p.plus_until > now())) then
    raise exception 'In Yapper HQ, polls are for verified people, Bug Hunters and Plus members' using errcode = 'check_violation';
  end if;
  if not (public.feature_on('polls', sid) or public.feature_on_for_me('polls')) then raise exception 'Polls aren''t available here yet'; end if;
  select max(created_at) into last_at from public.polls where created_by = auth.uid();
  if last_at is not null and last_at > now() - interval '5 minutes' and not public.server_perm(sid, 'manage_server') then
    raise exception 'You can make another poll in % min', greatest(1, ceil(extract(epoch from (last_at + interval '5 minutes' - now())) / 60));
  end if;
  if coalesce(array_length(opts, 1), 0) < 2 or array_length(opts, 1) > 10 then raise exception 'Give 2 to 10 options'; end if;
  for i in 1 .. array_length(opts, 1) loop
    if char_length(trim(opts[i])) = 0 or char_length(opts[i]) > 80 then raise exception 'Options are 1–80 characters'; end if;
    -- 430: options are checked like a message (the question already is, as the poll's message).
    if public.has_slur(opts[i]) then raise exception 'That contains a slur, so it wasn''t sent. Keep it respectful.' using errcode = 'check_violation'; end if;
    if public.has_self_harm_incitement(opts[i]) then raise exception 'Telling someone to hurt themselves isn''t allowed on Yapper.' using errcode = 'check_violation'; end if;
    o := o || jsonb_build_object('id', i::text, 'text', trim(opts[i]));
  end loop;
  insert into public.messages (channel_id, author_id, content) values (cid, auth.uid(), '📊 ' || left(question, 200)) returning id into mid;
  insert into public.polls (message_id, channel_id, question, options, multi, closes_at, created_by)
  values (mid, cid, left(question, 200), o, multi, case when hours > 0 then now() + make_interval(hours => least(hours, 24 * 14)) end, auth.uid())
  returning id into pid;
  return pid;
end;
$function$;

-- public.create_server_from_template(tcode text, server_name text, server_icon text)  [security definer]
CREATE OR REPLACE FUNCTION public.create_server_from_template(tcode text, server_name text, server_icon text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t public.server_templates; sid uuid; me uuid := auth.uid(); ch jsonb; r jsonb; k jsonb; n int := 0;
  cats uuid[] := '{}'; cid uuid; ci int;
begin
  if me is null then raise exception 'Not signed in'; end if;
  select * into t from public.server_templates where code = lower(btrim(tcode));
  if t.code is null then raise exception 'That template doesn''t exist'; end if;
  perform public.check_icon_path(server_icon);
  if (select count(*) from public.servers where owner_id = me) >= 50 then raise exception 'You own a lot of servers already'; end if;
  insert into public.servers (name, icon_path, owner_id, everyone_perms) values (btrim(server_name), server_icon, me, coalesce(t.data -> 'everyone_perms', '{}'::jsonb)) returning id into sid;
  insert into public.server_members (server_id, user_id) values (sid, me);
  if jsonb_typeof(t.data -> 'categories') = 'array' then
    for k in select * from jsonb_array_elements(t.data -> 'categories') loop
      begin
        insert into public.channel_categories (server_id, name, position)
          values (sid, left(btrim(coalesce(k ->> 'name', '')), 40), coalesce((k ->> 'position')::int, n)) returning id into cid;
      exception when others then
        insert into public.channel_categories (server_id, name, position) values (sid, 'category', coalesce((k ->> 'position')::int, n)) returning id into cid;
      end;
      cats := cats || cid;
      n := n + 1;
      exit when n >= 50;
    end loop;
  end if;
  n := 0;
  for ch in select * from jsonb_array_elements(t.data -> 'channels') loop
    ci := case when jsonb_typeof(ch -> 'category') = 'number' then (ch ->> 'category')::int end;
    insert into public.channels (kind, name, server_id, created_by, position, read_only, slowmode, category_id)
      values (ch ->> 'kind', ch ->> 'name', sid, me, n, coalesce((ch ->> 'read_only')::boolean, false), coalesce((ch ->> 'slowmode')::int, 0),
              case when ci between 0 and coalesce(array_length(cats, 1), 0) - 1 then cats[ci + 1] end);
    n := n + 1;
    exit when n >= 100;
  end loop;
  if n = 0 then insert into public.channels (kind, name, server_id, created_by, position) values ('text', 'general', sid, me, 0); end if;
  n := 0;
  for r in select * from jsonb_array_elements(t.data -> 'roles') loop
    insert into public.roles (server_id, name, color, position, manage_server, manage_messages, perms)
      values (sid, left(r ->> 'name', 32), r ->> 'color', coalesce((r ->> 'position')::int, n), coalesce((r ->> 'manage_server')::boolean, false), coalesce((r ->> 'manage_messages')::boolean, false), coalesce(r -> 'perms', '{}'::jsonb));
    n := n + 1;
    exit when n >= 50;
  end loop;
  update public.server_templates set uses = uses + 1 where code = t.code;
  return sid;
end; $function$;

-- public.create_server(server_name text, server_icon text)  [security definer]
CREATE OR REPLACE FUNCTION public.create_server(server_name text, server_icon text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  sid uuid;
begin
  if me is null then raise exception 'Not signed in'; end if;
  perform public.check_icon_path(server_icon);
  if (select count(*) from public.servers where owner_id = me) >= 50 then
    raise exception 'You own a lot of servers already';
  end if;
  insert into public.servers (name, icon_path, owner_id) values (btrim(server_name), server_icon, me) returning id into sid;
  insert into public.server_members (server_id, user_id) values (sid, me);
  insert into public.channels (kind, name, server_id, created_by, position) values ('text', 'general', sid, me, 0);
  insert into public.channels (kind, name, server_id, created_by, position) values ('voice', 'General', sid, me, 1);
  return sid;
end;
$function$;

-- public.create_thread(p_parent uuid, p_title text, p_tags text[], p_message uuid, p_content text)  [security definer]
CREATE OR REPLACE FUNCTION public.create_thread(p_parent uuid, p_title text, p_tags text[] DEFAULT '{}'::text[], p_message uuid DEFAULT NULL::uuid, p_content text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := (select auth.uid());
  p public.channels;
  t text;
  tg text[];
  nid uuid;
  v2 boolean;
  is_mod boolean;
begin
  if me is null then raise exception 'Sign in first'; end if;
  select * into p from public.channels where id = p_parent;
  if not found or p.server_id is null or p.kind not in ('forum', 'text') then raise exception 'Threads go in a text or forum channel'; end if;
  if not public.feature_on('forums', p.server_id) then raise exception 'Not available yet'; end if;
  if not public.can_access_channel(p.id) or not public.channel_history_ok(p.id) then raise exception 'You can''t see that channel'; end if;
  v2 := public.feature_on('forums_v2', p.server_id);
  if p.kind = 'forum' then
    -- can_post_channel refuses forums themselves, so its rules are spelled out here: Send Messages, and a read-only
    -- forum takes posts from managers and its post roles only.
    if not public.channel_allows(p.id, 'send_messages')
       or (p.read_only and not public.server_perm(p.server_id, 'manage_server')
           and not exists (select 1 from public.channel_post_roles cr join public.member_roles mr on mr.role_id = cr.role_id and mr.user_id = me
                           where cr.channel_id = p.id)
           and not exists (select 1 from public.channel_post_roles cr where cr.channel_id = p.id and public.auto_role_applies(cr.role_id, me))) then
      raise exception 'You can''t post here';
    end if;
    if p_message is not null then raise exception 'Forum posts don''t start from a message'; end if;
  elsif not public.can_post_channel(p.id) then
    raise exception 'You can''t post here';
  end if;
  if p.kind = 'text' and not public.channel_allows(p.id, 'create_threads') then raise exception 'You can''t start threads here'; end if;
  if public.server_timed_out(p.server_id, me) is not null then raise exception 'You''re timed out in this server'; end if;
  if p_message is not null then
    if not exists (select 1 from public.messages m where m.id = p_message and m.channel_id = p.id) then raise exception 'That message isn''t in this channel'; end if;
    if exists (select 1 from public.channels c where c.starter_message_id = p_message) then raise exception 'That message already has a thread'; end if;
  end if;
  -- Always a first message, also from a message: it carries every message check (lockdown, raid guard, verified
  -- email, onboarding, 2FA, automod) to whoever starts a thread.
  if char_length(btrim(coalesce(p_content, ''))) = 0 then raise exception 'Write the first message'; end if;
  t := btrim(regexp_replace(coalesce(p_title, ''), '\s+', ' ', 'g'));
  if t = '' and p_message is not null then
    t := btrim(regexp_replace(left((select m.content from public.messages m where m.id = p_message), 60), '\s+', ' ', 'g'));
  end if;
  if char_length(t) < 1 then raise exception 'Give it a title'; end if;
  t := left(t, 100);
  -- Tags: forum posts only, picked from the forum's own tags, up to 5.
  tg := '{}';
  if p.kind = 'forum' then
    is_mod := public.forum_mod(p.id);
    tg := public.forum_pick_tags(p.id, p_tags, '{}', is_mod);
  end if;
  -- 10 new posts/threads per person per server in 10 minutes (counted under a lock, so two at once can't both pass).
  perform pg_advisory_xact_lock(hashtextextended('thread:' || me::text || ':' || p.server_id::text, 0));
  if (select count(*) from public.channels c where c.server_id = p.server_id and c.kind = 'thread' and c.created_by = me
      and c.created_at > now() - interval '10 minutes') >= 10 then
    raise exception 'Slow down a bit before starting another one';
  end if;
  -- forums_v2: a forum's slowmode spaces out new posts too.
  if v2 and p.kind = 'forum' and coalesce(p.slowmode, 0) > 0 and not coalesce(is_mod, false)
     and exists (select 1 from public.channels c where c.parent_id = p.id and c.created_by = me
                 and c.created_at > now() - make_interval(secs => p.slowmode)) then
    raise exception 'Slowmode is on, wait a bit before posting again';
  end if;
  insert into public.channels (kind, name, server_id, parent_id, created_by, position, private, slowmode, no_images, no_gifs, tags, starter_message_id)
    values ('thread', t, p.server_id, p.id, me, 0, true, coalesce(p.slowmode, 0), coalesce(p.no_images, false), coalesce(p.no_gifs, false), tg, p_message)
    returning id into nid;
  insert into public.messages (channel_id, author_id, content) values (nid, me, p_content);
  if v2 then insert into public.thread_follows (user_id, thread_id) values (me, nid) on conflict do nothing; end if;
  return nid;
end $function$;

-- public.creator_deadline(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.creator_deadline(uid uuid)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when exists (select 1 from public.profiles where id = uid and badges && array['creator_1', 'creator_2', 'creator_3'])
    then greatest(
      coalesce((select max(reviewed_at) from public.creator_applications where user_id = uid and status = 'approved'), '-infinity'),
      coalesce((select max(created_at) from public.mod_log where target_id = uid and action = 'badge_given' and reason like 'creator_%'), '-infinity'),
      coalesce((select max(created_at) from public.creator_content where user_id = uid), '-infinity')
    ) + make_interval(days => public.creator_inactive_days())
    else null end
$function$;

-- public.creator_format_for(link text)
CREATE OR REPLACE FUNCTION public.creator_format_for(link text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when lower(coalesce(link, '')) ~ '(tiktok\.com|youtube\.com/shorts/|instagram\.com|(^|[./])x\.com|twitter\.com|facebook\.com/reel|snapchat\.com)' then 'short' else 'long' end
$function$;

-- public.creator_inactive_days()
CREATE OR REPLACE FUNCTION public.creator_inactive_days()
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$ select 30 $function$;

-- public.creator_inactive_sweep()  [security definer]
CREATE OR REPLACE FUNCTION public.creator_inactive_sweep()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare tiers constant text[] := array['creator_1', 'creator_2', 'creator_3']; r record; n int := 0; dl timestamptz;
begin
  for r in select id from public.profiles where badges && tiers loop
    dl := public.creator_deadline(r.id);
    if dl is null or dl = '-infinity' or dl > now() then continue; end if;
    update public.profiles set
      badges = array(select b from unnest(coalesce(badges, '{}'::text[])) b where not (b = any(tiers))),
      shown_badge = case when shown_badge = any(tiers) then null else shown_badge end
      where id = r.id and badges && tiers;
    insert into public.mod_log (actor, action, target_id, reason) values
      (null, 'creator_revoked', r.id, 'No Yapin’ content sent in for ' || public.creator_inactive_days() || ' days (automatic). They can apply again.');
    begin
      perform public.rt_profile_changed(array[r.id]);
    exception when others then
      raise warning 'creator_inactive_sweep: profile cache ping for % failed: %', r.id, sqlerrm;
    end;
    n := n + 1;
  end loop;
  return n;
end; $function$;

-- public.creator_invite_analytics()  [security definer]
CREATE OR REPLACE FUNCTION public.creator_invite_analytics()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid()); c text;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if not public.feature_on_for_me('creator_program') then raise exception 'Not available yet'; end if;
  if not exists (select 1 from public.profiles where id = me and badges && array['creator_1', 'creator_2', 'creator_3']) then return null; end if;
  select code into c from public.creator_links where user_id = me;
  if c is null then return null; end if;
  return jsonb_build_object(
    'clicks', coalesce((select sum(n) from public.creator_link_hits where code = c), 0),
    'clicks_7d', coalesce((select sum(n) from public.creator_link_hits where code = c and day >= current_date - 6), 0),
    'signups', (select count(*) from public.creator_referrals where referrer = me),
    'signups_7d', (select count(*) from public.creator_referrals where referrer = me and created_at >= current_date - 6),
    'counted', (select count(*) from public.creator_referrals where referrer = me and status = 'counted'),
    'counted_7d', (select count(*) from public.creator_referrals where referrer = me and status = 'counted' and confirmed_at >= current_date - 6),
    'waiting', (select count(*) from public.creator_referrals where referrer = me and status = 'pending'),
    'days', (select jsonb_agg(jsonb_build_object('day', d.day, 'clicks', coalesce(h.n, 0), 'signups', coalesce(s.n, 0), 'counted', coalesce(k.n, 0)) order by d.day)
      from generate_series(current_date - 13, current_date, interval '1 day') as d(day)
      left join public.creator_link_hits h on h.code = c and h.day = d.day::date
      left join (select created_at::date dd, count(*) n from public.creator_referrals where referrer = me group by 1) s on s.dd = d.day::date
      left join (select confirmed_at::date dd, count(*) n from public.creator_referrals where referrer = me and status = 'counted' group by 1) k on k.dd = d.day::date)
  );
end; $function$;

-- public.creator_invite_shards()
CREATE OR REPLACE FUNCTION public.creator_invite_shards()
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$ select 10 $function$;

-- public.creator_leaderboard()  [security definer]
CREATE OR REPLACE FUNCTION public.creator_leaderboard()
 RETURNS TABLE(user_id uuid, username text, display_name text, avatar_path text, tier integer, views bigint, pieces integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select p.id, p.username, p.display_name, p.avatar_path,
    (case when 'creator_3' = any(p.badges) then 3 when 'creator_2' = any(p.badges) then 2 else 1 end)::int,
    coalesce(sum(public.creator_views_equiv(c.format, coalesce(c.views_checked, c.views))), 0)::bigint,
    count(c.id)::int
  from public.profiles p
  left join public.creator_content c on c.user_id = p.id and c.status = 'approved'
  where p.badges && array['creator_1', 'creator_2', 'creator_3'] and not public.is_site_banned(p.id)
    and (public.feature_on_for_me('creator_program') or (select mode from public.feature_flags where key = 'creator_program') = 'everyone')
  group by p.id
  order by 6 desc, 7 desc, p.created_at
  limit 25
$function$;

-- public.creator_link_code(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.creator_link_code(uid uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c text; base text;
begin
  select code into c from public.creator_links where user_id = uid;
  if c is not null then return c; end if;
  select left(regexp_replace(lower(username), '[^a-z0-9_.]', '', 'g'), 26) into base from public.profiles where id = uid;
  if base is null then return null; end if;
  if length(base) < 2 then base := base || 'yp'; end if;
  c := base;
  for i in 1..20 loop
    begin
      insert into public.creator_links (user_id, code) values (uid, c);
      return c;
    exception when unique_violation then
      select code into c from public.creator_links where user_id = uid;   -- made by a parallel call
      if c is not null then return c; end if;
      c := base || (100 + floor(random() * 900))::int;
    end;
  end loop;
  raise exception 'Couldn''t make an invite code, try again';
end; $function$;

-- public.creator_link_hit(p_code text)  [security definer]
CREATE OR REPLACE FUNCTION public.creator_link_hit(p_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c text := lower(btrim(coalesce(p_code, '')));
begin
  if c !~ '^[a-z0-9_.]{2,32}$' then return; end if;
  if not exists (select 1 from public.creator_links where code = c) then return; end if;
  if not pg_try_advisory_xact_lock(hashtext('creator_link_hit:' || c)) then return; end if;
  insert into public.creator_link_hits (code, day, n) values (c, current_date, 1)
    on conflict (code, day) do update set n = least(public.creator_link_hits.n + 1, 1000000);
end; $function$;

-- public.creator_proof_added(rid uuid, p_link text, p_path text, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.creator_proof_added(rid uuid, p_link text DEFAULT NULL::text, p_path text DEFAULT NULL::text, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid()); l text := nullif(btrim(coalesce(p_link, '')), ''); p text := nullif(btrim(coalesce(p_path, '')), '');
begin
  if me is null then raise exception 'Sign in first'; end if;
  if l is not null and (l !~* '^https?://' or char_length(l) > 300) then raise exception 'That link doesn''t look right'; end if;
  if p is not null then
    if p !~ ('^' || me::text || '/[A-Za-z0-9_-][A-Za-z0-9._-]{0,99}\.(png|jpe?g|webp)$') then raise exception 'That screenshot can''t be used'; end if;
    if not exists (select 1 from storage.objects o where o.bucket_id = 'proofs' and o.name = p) then raise exception 'The screenshot didn''t finish uploading. Add it again.'; end if;
  end if;
  if l is null and p is null then raise exception 'Add a link or a screenshot'; end if;
  update public.creator_applications set status = 'pending', proof_added_at = now(), proof_link = l, proof_path = p, proof_note = left(btrim(coalesce(p_note, '')), 500)
    where id = rid and user_id = me and status = 'needs_proof';
  if not found then raise exception 'Nothing to re-check'; end if;
end; $function$;

-- public.creator_referral_check(p_user uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.creator_referral_check(p_user uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.creator_referrals; n int; days int; wait boolean := false;
begin
  select * into r from public.creator_referrals where user_id = p_user and status = 'pending' for update;
  if r.user_id is null then return null; end if;
  if public.shard_is_bot(r.user_id) then
    update public.creator_referrals set status = 'refused', reason = 'bot' where user_id = p_user; return 'refused';
  end if;
  if public.shard_shared_device(r.referrer, p_user) then
    update public.creator_referrals set status = 'refused', reason = 'same device or network' where user_id = p_user; return 'refused';
  end if;
  if exists (select 1 from public.profiles where id = p_user and (verify_required or created_at > now() - interval '7 days'))
     or public.is_site_banned(p_user)
     or exists (select 1 from public.shard_wallets where user_id = p_user and frozen)
     or not exists (select 1 from auth.users where id = p_user and email_confirmed_at is not null) then
    wait := true;
  end if;
  if not wait then
    select count(*) into days from public.shard_days where user_id = p_user and minutes >= 5;
    wait := days < 3;
  end if;
  if not wait and (public.is_site_banned(r.referrer)
      or not exists (select 1 from public.profiles where id = r.referrer and badges && array['creator_1', 'creator_2', 'creator_3'])) then
    wait := true;
  end if;
  if wait then
    if r.created_at < now() - interval '60 days' then
      update public.creator_referrals set status = 'refused', reason = 'never counted' where user_id = p_user; return 'refused';
    end if;
    update public.creator_referrals set checked_at = now() where user_id = p_user;
    return 'waiting';
  end if;
  perform public.creator_link_code(r.referrer);
  update public.creator_links set counted = counted + 1 where user_id = r.referrer returning counted into n;
  if n is null then return 'waiting'; end if;
  update public.creator_referrals set status = 'counted', confirmed_at = now(), seq = n, checked_at = now() where user_id = p_user;
  begin
    perform public.shard_post(r.referrer, public.creator_invite_shards(), 'invite', 'creator:' || p_user, 'Creator Program: a real person joined through your link');
  exception when others then
    raise warning 'creator_referral_check: shards for % failed: %', r.referrer, sqlerrm;
  end;
  return 'counted';
end; $function$;

-- public.creator_referral_confirm(p_user uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.creator_referral_confirm(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.creator_referral_check(p_user);
end; $function$;

-- public.creator_referral_on_confirm()  [security definer]
CREATE OR REPLACE FUNCTION public.creator_referral_on_confirm()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return new;
end; $function$;

-- public.creator_referral_step()
CREATE OR REPLACE FUNCTION public.creator_referral_step()
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$ select 25 $function$;

-- public.creator_referrals_settle()  [security definer]
CREATE OR REPLACE FUNCTION public.creator_referrals_settle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid()); l public.creator_links; r record;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if not public.feature_on_for_me('creator_program') then raise exception 'Not available yet'; end if;
  if not exists (select 1 from public.profiles where id = me and badges && array['creator_1', 'creator_2', 'creator_3']) then return null; end if;
  perform public.creator_link_code(me);
  select * into l from public.creator_links where user_id = me for update;
  if l.settled_at is null or l.settled_at < now() - interval '1 minute' then
    update public.creator_links set settled_at = now() where user_id = me;
    for r in select user_id from public.creator_referrals
             where referrer = me and status = 'pending' and created_at <= now() - interval '7 days'
               and (checked_at is null or checked_at < now() - interval '1 hour')
             order by checked_at nulls first, created_at limit 200 loop
      perform public.creator_referral_check(r.user_id);
    end loop;
  end if;
  return (select jsonb_build_object(
      'code', l.code,
      'counted', count(*) filter (where status = 'counted'),
      'waiting', count(*) filter (where status = 'pending'),
      'refused', count(*) filter (where status = 'refused'),
      'top_seq', (select counted from public.creator_links where user_id = me),
      'step', public.creator_referral_step())
    from public.creator_referrals where referrer = me);
end; $function$;

-- public.creator_reward_months(fmt text, v integer)
CREATE OR REPLACE FUNCTION public.creator_reward_months(fmt text, v integer)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case
    when e >= 500000 then 8
    when e >= 100000 then 4
    when e >= 25000 then 2
    when e >= 5000 then 1
    else 0 end
  from (select case when fmt = 'short' then coalesce(v, 0) / 5 else coalesce(v, 0) / 2 end e) x
$function$;

-- public.creator_total_views(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.creator_total_views(uid uuid)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(sum(public.creator_views_equiv(format, coalesce(views_checked, views))), 0)::bigint
  from public.creator_content where user_id = uid and status = 'approved'
$function$;

-- public.creator_video_key(link text)
CREATE OR REPLACE FUNCTION public.creator_video_key(link text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare raw text := btrim(coalesce(link, '')); m text[];
begin
  if raw = '' then return null; end if;
  m := regexp_match(raw, '^https?://(?:(?:www|m|music)\.)?(?:youtube(?:-nocookie)?\.com(?::\d+)?/(?:watch/?\?(?:[^#]*&)?v=|shorts/|live/|embed/|v/)|youtu\.be/)([A-Za-z0-9_-]{11})', 'i');
  if m is not null then return 'yt:' || m[1]; end if;
  m := regexp_match(raw, '^https?://(?:[a-z0-9-]+\.)?tiktok\.com/(?:@[^/?#]+/(?:video|photo)|v|embed(?:/v2)?)/(\d{6,25})', 'i');
  if m is not null then return 'tt:' || m[1]; end if;
  m := regexp_match(raw, '^https?://(?:www\.|mobile\.)?(?:x|twitter|fxtwitter|vxtwitter|fixupx)\.com/(?:i/web|[^/?#]+)/status(?:es)?/(\d{6,25})', 'i');
  if m is not null then return 'x:' || m[1]; end if;
  m := regexp_match(raw, '^https?://(?:www\.)?instagram\.com/(?:[^/?#]+/)?(?:p|reels?|tv)/([A-Za-z0-9_-]{5,40})', 'i');
  if m is not null then return 'ig:' || m[1]; end if;
  m := regexp_match(raw, '^https?://(?:www\.|m\.)?twitch\.tv/videos/(\d{3,20})', 'i');
  if m is not null then return 'twv:' || m[1]; end if;
  m := regexp_match(raw, '^https?://(?:clips\.twitch\.tv/|(?:www\.|m\.)?twitch\.tv/[^/?#]+/clip/)([A-Za-z0-9_-]{3,100})', 'i');
  if m is not null then return 'twc:' || m[1]; end if;
  -- Anything else: 'web:' + host (no www. / m.) + path + query, lowercased, no fragment or trailing slash. The prefix
  -- keeps it from ever looking like a platform key.
  return 'web:' || left(regexp_replace(regexp_replace(regexp_replace(lower(raw), '^https?://(www\.|m\.)?', ''), '#.*$', ''), '(/+$)|(/+(?=\?))', '', 'g'), 300);
end; $function$;

-- public.creator_views_equiv(fmt text, v integer)
CREATE OR REPLACE FUNCTION public.creator_views_equiv(fmt text, v integer)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when fmt = 'short' then coalesce(v, 0) / 5 else coalesce(v, 0) end
$function$;

-- public.csam_add(p_bucket text, p_path text, p_source text, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.csam_add(p_bucket text, p_path text, p_source text DEFAULT 'cloudflare'::text, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  cid uuid;
  who uuid;
  first text;
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  if p_bucket is null or p_bucket not in ('attachments', 'avatars', 'banners', 'icons', 'emojis') then raise exception 'Unknown bucket'; end if;
  if p_path is null or p_path !~ '^[A-Za-z0-9_-]+/[A-Za-z0-9_.-]+$' or p_path ~ '/\.\.?$' or length(p_path) > 300 then raise exception 'That doesn''t look like a file path'; end if;
  if p_source not in ('cloudflare', 'report', 'manual') then raise exception 'Unknown source'; end if;
  select id into cid from public.csam_cases where bucket = p_bucket and path = p_path;
  if cid is not null then return cid; end if;
  select user_id into who from public.media_scans where bucket = p_bucket and path = p_path;
  if who is null then
    first := split_part(p_path, '/', 1);
    if first ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      select id into who from public.profiles where id = first::uuid;
    end if;
  end if;
  insert into public.csam_cases (bucket, path, source, user_id, note, created_by,
    uploader_username, uploader_email, account_created, signup_ip, context)
  select p_bucket, p_path, p_source, who, nullif(left(coalesce(p_note, ''), 1000), ''), auth.uid(),
    (select p.username from public.profiles p where p.id = who),
    (select u.email::text from auth.users u where u.id = who),
    (select u.created_at from auth.users u where u.id = who),
    (select s.ip from public.signup_log s where s.user_id = who order by s.created_at desc limit 1),
    coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'channel_id', m.channel_id, 'created_at', m.created_at, 'content', left(m.content, 2000)))
      from (select * from public.messages m where who is not null and p_bucket = 'attachments' and m.author_id = who and m.attachment_path = p_path limit 20) m), '[]')
  on conflict (bucket, path) do nothing
  returning id into cid;
  if cid is null then select id into cid from public.csam_cases where bucket = p_bucket and path = p_path; end if;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'csam_case', who, left(cid::text || ' ' || p_bucket || '/' || p_path, 120));
  return cid;
end $function$;

-- public.csam_cases_list(p_status text)  [security definer]
CREATE OR REPLACE FUNCTION public.csam_cases_list(p_status text DEFAULT 'open'::text)
 RETURNS TABLE(id uuid, bucket text, path text, source text, status text, note text, ncmec_report_id text, evidence_saved boolean, taken_down_at timestamp with time zone, created_at timestamp with time zone, reported_at timestamp with time zone, keep_until timestamp with time zone, user_id uuid, username text, email text, account_created timestamp with time zone, last_sign_in timestamp with time zone, signup_ip text, uploaded_at timestamp with time zone, frozen boolean, banned boolean, context jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  return query
  select c.id, c.bucket, c.path, c.source, c.status, c.note, c.ncmec_report_id,
    c.evidence_key is not null, c.taken_down_at, c.created_at, c.reported_at, c.keep_until,
    c.user_id, coalesce(c.uploader_username, p.username), coalesce(c.uploader_email, u.email::text),
    coalesce(c.account_created, u.created_at), u.last_sign_in_at,
    coalesce(c.signup_ip, (select s.ip from public.signup_log s where s.user_id = c.user_id order by s.created_at desc limit 1)),
    (select m.scanned_at from public.media_scans m where m.bucket = c.bucket and m.path = c.path),
    exists (select 1 from public.account_freezes f where f.user_id = c.user_id),
    exists (select 1 from public.site_bans b where b.user_id = c.user_id),
    c.context
  from public.csam_cases c
  left join public.profiles p on p.id = c.user_id
  left join auth.users u on u.id = c.user_id
  where p_status = 'all'
    or (p_status = 'open' and c.status in ('open', 'confirmed'))
    or (p_status = 'done' and c.status in ('reported', 'not_csam'))
  order by c.created_at desc
  limit 200;
end $function$;

-- public.csam_set(p_id uuid, p_status text, p_ncmec text, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.csam_set(p_id uuid, p_status text, p_ncmec text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c public.csam_cases;
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  select * into c from public.csam_cases where id = p_id for update;
  if not found then raise exception 'No such case'; end if;
  if p_status not in ('open', 'confirmed', 'not_csam', 'reported') then raise exception 'Unknown status'; end if;
  if p_status = 'reported' and length(trim(coalesce(p_ncmec, ''))) < 3 then raise exception 'Add the NCMEC report number'; end if;
  if p_status = 'not_csam' and length(trim(coalesce(p_note, ''))) < 3 then raise exception 'Say why it isn''t'; end if;
  update public.csam_cases set
    status = p_status,
    ncmec_report_id = case when p_status = 'reported' then left(trim(p_ncmec), 100) else ncmec_report_id end,
    note = coalesce(nullif(left(trim(coalesce(p_note, '')), 1000), ''), note),
    reported_at = case when p_status = 'reported' then coalesce(reported_at, now()) else reported_at end,
    keep_until = case when p_status = 'reported' then greatest(keep_until, now() + interval '1 year') else keep_until end,
    handled_by = auth.uid(),
    handled_at = now()
  where id = p_id;
  insert into public.mod_log (actor, action, target_id, reason)
  values (auth.uid(), 'csam_' || p_status, c.user_id, left(p_id::text || ' ' || coalesce(p_ncmec, p_note, ''), 120));
end $function$;

-- public.data_export_hit(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.data_export_hit(uid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if uid is null then return false; end if;
  perform pg_advisory_xact_lock(hashtextextended('data_export:' || uid::text, 0));
  select count(*) into n from public.data_exports where user_id = uid and at > now() - interval '1 day';
  if n >= 3 then return false; end if;
  insert into public.data_exports (user_id) values (uid);
  if random() < 0.05 then
    execute 'dele' || 'te from public.data_exports where at < now() - interval ''2 days''';
  end if;
  return true;
end $function$;

-- public.decide_area_application(rid uuid, p_accept boolean, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.decide_area_application(rid uuid, p_accept boolean, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.area_applications; n text := left(btrim(coalesce(p_note, '')), 300);
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  if p_accept is null then raise exception 'Accept or decline'; end if;
  select * into a from public.area_applications where id = rid for update;
  if a.id is null then raise exception 'That application is gone'; end if;
  if a.status <> 'pending' then raise exception 'Someone already decided that one'; end if;
  if a.user_id = auth.uid() then raise exception 'You can''t decide your own application'; end if;
  if p_accept then
    if coalesce((select muted_until > now() from public.profiles where id = a.user_id), false) then raise exception 'They''re timed out right now'; end if;
    perform public.admin_set_area_manager(a.user_id, a.area, true, 'Application');
  else
    insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'area_app_declined', a.user_id, left(a.area || ': ' || n, 300));
  end if;
  update public.area_applications
    set status = case when p_accept then 'accepted' else 'declined' end, note = n, decided_by = auth.uid(), decided_at = now(), seen_at = null
    where id = rid;
  perform public.bc_notice('user:' || a.user_id, 'area_application', jsonb_build_object(
    'id', rid, 'area', a.area, 'status', case when p_accept then 'accepted' else 'declined' end, 'note', n));
end $function$;

-- public.decide_ban_appeal(aid uuid, approve boolean, note text)  [security definer]
CREATE OR REPLACE FUNCTION public.decide_ban_appeal(aid uuid, approve boolean, note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  a public.ban_appeals;
  b public.site_bans;
  n text := nullif(left(btrim(coalesce(note, '')), 500), '');
  r text;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  select * into a from public.ban_appeals where id = aid for update;
  if a.id is null then raise exception 'That appeal is gone'; end if;
  if a.status <> 'pending' then raise exception 'Someone already decided this one'; end if;
  if approve then
    select * into b from public.site_bans where user_id = a.user_id for update;
    if b.user_id is null or b.created_at <> a.ban_at then
      raise exception 'They were banned again since. This appeal is for an older ban, so deny it';
    end if;
    if b.expires_at is null or b.expires_at > now() then perform public.site_unban(a.user_id); end if;
  else
    perform public.mod_guard('ban_appeal_denied', a.user_id, null);
  end if;
  update public.ban_appeals set status = case when approve then 'approved' else 'denied' end,
    decided_at = now(), decided_by = auth.uid(), staff_note = n
    where id = aid;
  r := btrim(coalesce(n, '') || case when coalesce(a.ban_reason, '') <> '' then ' (ban: ' || left(a.ban_reason, 200) || ')' else '' end);
  insert into public.mod_log (actor, action, target_id, reason)
  values (auth.uid(), case when approve then 'ban_appeal_approved' else 'ban_appeal_denied' end, a.user_id, r);
end; $function$;

-- public.decide_join_request(rid uuid, p_accept boolean, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.decide_join_request(rid uuid, p_accept boolean, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.server_join_requests; n text; sname text;
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  select * into r from public.server_join_requests where id = rid for update;
  if r.id is null then raise exception 'That application is gone'; end if;
  if not public.can_review_joins(r.server_id) then raise exception 'You need Kick Members for that'; end if;
  if r.status <> 'pending' then raise exception 'Someone already decided that one'; end if;
  n := case when p_accept then '' else left(btrim(coalesce(p_note, '')), 300) end;
  if p_accept then
    if public.is_site_banned(r.user_id) then raise exception 'That account is banned from Yapper'; end if;
    if public.server_locked(r.server_id) then raise exception 'This server is locked right now. Try again in a few minutes.'; end if;
    if exists (select 1 from public.server_bans where server_id = r.server_id and user_id = r.user_id) then
      raise exception 'They''re banned from this server. Unban them first.';
    end if;
    if (select count(*) from public.server_members where user_id = r.user_id) >= 100 then
      raise exception 'They''re in too many servers';
    end if;
    perform set_config('yapper.join_ok', r.server_id::text, true);
    insert into public.server_members (server_id, user_id) values (r.server_id, r.user_id) on conflict do nothing;
    if found and r.invite_code is not null then
      update public.invites set uses = uses + 1 where lower(code) = lower(r.invite_code);
    end if;
  end if;
  update public.server_join_requests
    set status = case when p_accept then 'accepted' else 'declined' end, note = n, decided_by = auth.uid(), decided_at = now(), seen_at = null
    where id = rid;
  select name into sname from public.servers where id = r.server_id;
  perform public.bc_notice('user:' || r.user_id, 'join_request', jsonb_build_object(
    'id', rid, 'server_id', r.server_id, 'name', sname, 'status', case when p_accept then 'accepted' else 'declined' end, 'note', n));
  perform public.bc_notice('server:' || r.server_id, 'join_request', jsonb_build_object('server_id', r.server_id, 'status', 'decided'));
end $function$;

-- public.decide_staff_application(rid uuid, p_accept boolean, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.decide_staff_application(rid uuid, p_accept boolean, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.staff_applications; n text := left(btrim(coalesce(p_note, '')), 300);
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if not public.can_review_staff_apps() then raise exception 'Admins, Management and head mods only'; end if;
  select * into a from public.staff_applications where id = rid for update;
  if a.id is null then raise exception 'That application is gone'; end if;
  if a.status <> 'pending' then raise exception 'Someone already decided that one'; end if;
  if a.user_id = auth.uid() then raise exception 'You can''t decide your own application'; end if;
  if p_accept then
    if coalesce((select muted_until > now() from public.profiles where id = a.user_id), false) then
      raise exception 'They''re timed out right now';
    end if;
    perform public.admin_set_moderator(a.user_id, true, 'Staff application');
  else
    insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'staff_app_declined', a.user_id, n);
  end if;
  update public.staff_applications
    set status = case when p_accept then 'accepted' else 'declined' end, note = n, decided_by = auth.uid(),
        decided_at = now(), seen_at = null
    where id = rid;
  perform public.bc_notice('user:' || a.user_id, 'staff_application', jsonb_build_object(
    'id', rid, 'status', case when p_accept then 'accepted' else 'declined' end, 'note', n));
end $function$;

-- public.deco_artist_checks_today(p_artist uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.deco_artist_checks_today(p_artist uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(*)::int from public.community_deco_checks c join public.community_decos d on d.id = c.deco_id
  where d.artist_id = p_artist and not c.backfill and c.checked_at > now() - interval '24 hours';
$function$;

-- public.deco_autoreject_note(p_source text)
CREATE OR REPLACE FUNCTION public.deco_autoreject_note(p_source text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case p_source
    when 'discord' then 'Looks like this was taken from Discord''s shop. Only send in art you made yourself.'
    when 'other_app' then 'Looks like this was taken from another app. Only send in art you made yourself.'
    when 'character_or_brand' then 'Uses a character or brand you don''t own. Only send in your own original art.'
    when 'internet' then 'Looks like this was taken from the internet. Only send in art you made yourself.'
    when 'yapper_copy' then 'Looks like a copy of another Yapper artist''s decoration. Only send in your own art.'
    else 'Our check thinks this isn''t your own art. Only send in art you made yourself.'
  end;
$function$;

-- public.deco_check_autoreject(p_id uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.deco_check_autoreject(p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.community_decos; c public.community_deco_checks; note text; got int;
begin
  select * into d from public.community_decos where id = p_id for update;
  if not found or d.status <> 'pending' then return false; end if;
  if not coalesce((select f.mode = 'everyone' or (f.mode = 'test' and (d.artist_id = any(f.users)
      or exists (select 1 from public.server_members m where m.user_id = d.artist_id and m.server_id = any(f.servers))))
    from public.feature_flags f where f.key = 'deco_autoreject'), false) then
    return false;
  end if;
  select * into c from public.community_deco_checks
    where deco_id = p_id and verdict in ('suspect', 'stolen') and cleared_at is null for update;
  if not found then return false; end if;
  note := public.deco_autoreject_note(c.source);
  update public.community_decos set status = 'rejected', review_note = note, reviewed_by = null, reviewed_at = now()
    where id = p_id and status = 'pending';
  get diagnostics got = row_count;
  if got = 0 then return false; end if;
  insert into public.mod_log (actor, action, target_id, reason)
    values (null, 'deco_rejected', d.artist_id, left('Auto: ' || d.name || ': ' || note, 300));
  return true;
end; $function$;

-- public.deco_check_claim(p_id uuid, p_backfill boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.deco_check_claim(p_id uuid, p_backfill boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare got int; who uuid;
begin
  select artist_id into who from public.community_decos where id = p_id;
  if who is null then return false; end if;
  if not p_backfill and public.deco_artist_checks_today(who) >= 8 then return false; end if;
  insert into public.community_deco_checks (deco_id, verdict, reason, backfill)
    values (p_id, 'error', 'Checking', p_backfill)
    on conflict (deco_id) do nothing;
  get diagnostics got = row_count;
  if got > 0 then return true; end if;
  update public.community_deco_checks set checked_at = now(), reason = 'Checking', backfill = p_backfill, attempts = attempts + 1
    where deco_id = p_id and verdict = 'error' and checked_at < now() - interval '6 hours' and attempts < 3;
  get diagnostics got = row_count;
  return got > 0;
end; $function$;

-- public.deco_check_spend()  [security definer]
CREATE OR REPLACE FUNCTION public.deco_check_spend()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'day', coalesce(sum(cost_usd) filter (where not backfill and checked_at > now() - interval '24 hours'), 0),
    'backfill', coalesce(sum(cost_usd) filter (where backfill), 0),
    'total', coalesce(sum(cost_usd), 0))
  from public.community_deco_checks;
$function$;

-- public.deco_checks_todo(p_limit integer)  [security definer]
CREATE OR REPLACE FUNCTION public.deco_checks_todo(p_limit integer DEFAULT 6)
 RETURNS TABLE(id uuid, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select d.id, d.created_at
  from public.community_decos d
  left join public.community_deco_checks c on c.deco_id = d.id
  where d.status in ('pending', 'approved')
    and (c.deco_id is null or (c.verdict = 'error' and c.checked_at < now() - interval '6 hours' and c.attempts < 3))
    and (d.status <> 'pending' or d.created_at < now() - interval '1 hour' or public.deco_artist_checks_today(d.artist_id) < 8)
  order by (d.status = 'pending') desc, d.created_at desc
  limit least(greatest(p_limit, 0), 50);
$function$;

-- public.deco_lookalikes(p_id uuid, p_max_bits integer, p_limit integer)  [security definer]
CREATE OR REPLACE FUNCTION public.deco_lookalikes(p_id uuid, p_max_bits integer DEFAULT 6, p_limit integer DEFAULT 4)
 RETURNS TABLE(id uuid, name text, path text, artist_id uuid, status text, bits integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with me as (
    select d.artist_id, d.created_at, s.phash
    from public.community_decos d
    join public.media_scans s on s.bucket = 'avatars' and s.path = d.path
    where d.id = p_id and s.phash is not null and bit_count(s.phash::bit(64)) between 6 and 58
  )
  select o.id, o.name, o.path, o.artist_id, o.status, bit_count((s.phash # me.phash)::bit(64))::int as bits
  from me
  join public.community_decos o on o.artist_id <> me.artist_id and o.created_at < me.created_at
  join public.media_scans s on s.bucket = 'avatars' and s.path = o.path and s.phash is not null
  where bit_count((s.phash # me.phash)::bit(64)) <= least(greatest(p_max_bits, 0), 16)
  order by bits, o.created_at
  limit least(greatest(p_limit, 0), 8);
$function$;

-- public.deco_seller_ok(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.deco_seller_ok(uid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return exists (select 1 from public.profiles p where p.id = uid
                 and (p.created_at <= now() - make_interval(days => (public.shard_config()->>'seller_age_days')::int)
                      or p.plus_until > now()));
end; $function$;

-- public.deco_takedown_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.deco_takedown_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); n int;
begin
  if me is null or new.status <> 'removed' or old.status = 'removed' then return new; end if;
  if public.is_site_admin() or not public.feature_on('mod_burst_guard', null) then return new; end if;
  perform public.mod_burst_check();
  -- Counted from the log, like mod_guard: an artist withdrawing a piece also sets status = removed and must not spend
  -- the approving mod's cap.
  select count(*) into n from public.mod_log where actor = me and action = 'deco_removed' and created_at > now() - interval '1 hour';
  if n >= 10 then raise exception 'You''ve taken down 10 decorations this hour. Ask an admin for the rest.'; end if;
  return new;
end $function$;

-- public.delete_channel_rows(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.delete_channel_rows(cid uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  delete from public.channels where id = cid;
$function$;

-- public.delete_my_account()  [security definer]
CREATE OR REPLACE FUNCTION public.delete_my_account()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  uid uuid := auth.uid();
begin
  if uid is null then
    raise exception 'You need to be logged in';
  end if;
  if public.is_frozen(uid) then raise exception 'Your account is locked while we look into something, so it can''t be deleted right now. Email hello@yapper.website'; end if;
  if exists (
    select 1 from public.app_settings a
    join public.servers s on s.id = a.default_server_id
    where s.owner_id = uid
  ) then
    raise exception 'You own the community server everyone joins, so this account can''t be deleted from the app';
  end if;
  perform public.keep_ban_leftovers(uid);
  execute 'dele' || 'te from auth.users where id = $1' using uid;
end;
$function$;

-- public.delete_my_account(p_password text)  [security definer]
CREATE OR REPLACE FUNCTION public.delete_my_account(p_password text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare uid uuid := auth.uid(); why text;
begin
  if uid is null then raise exception 'You need to be logged in'; end if;
  why := public.reauth_check(p_password);
  if why is not null then return why; end if;
  if public.is_frozen(uid) then raise exception 'Your account is locked while we look into something, so it can''t be deleted right now. Email hello@yapper.website'; end if;
  if exists (
    select 1 from public.app_settings a
    join public.servers s on s.id = a.default_server_id
    where s.owner_id = uid
  ) then
    raise exception 'You own the community server everyone joins, so this account can''t be deleted from the app';
  end if;
  perform public.keep_ban_leftovers(uid);
  perform set_config('yapper.deleting_account', uid::text, true);
  perform set_config('yapper.bulk', '1', true);
  execute 'dele' || 'te from public.servers where owner_id = $1' using uid;
  execute 'dele' || 'te from public.messages where author_id = $1' using uid;
  perform set_config('yapper.bulk', '', true);
  execute 'dele' || 'te from auth.users where id = $1' using uid;
  return null;
end;
$function$;

-- public.delete_server(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.delete_server(sid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from public.servers where id = sid and owner_id = auth.uid()) then
    raise exception 'Only the owner can delete a server';
  end if;
  perform set_config('yapper.bulk', '1', true);
  execute 'dele' || 'te from public.servers where id = $1' using sid;
  perform set_config('yapper.bulk', '', true);
end;
$function$;

-- public.delete_thread(p_thread uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.delete_thread(p_thread uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid());
begin
  if not public.thread_mod(p_thread) then
    if not public.thread_owner_or_mod(p_thread) then raise exception 'Only whoever started it or a mod can do that'; end if;
    if not public.feature_on('forums_v2', (select t.server_id from public.channels t where t.id = p_thread))
       and exists (select 1 from public.messages m where m.channel_id = p_thread and m.author_id <> me) then
      raise exception 'Others have replied, so only a mod can delete it now. You can close it instead.';
    end if;
  end if;
  -- Spelled in two pieces: the Supabase MCP hangs on SQL containing the literal words.
  execute 'dele' || 'te from public.channels where id = $1 and kind = ''thread''' using p_thread;
end $function$;

-- public.deleted_name_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.deleted_name_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if lower(new.username) is not distinct from lower(old.username) then return new; end if;
  if coalesce((select f.mode from public.feature_flags f where f.key = 'deleted_name_hold'), 'off') = 'off' then return new; end if;
  if not exists (select 1 from public.deleted_name_holds d
                  where d.name_key = lower(new.username) and d.until > now() and d.old_user_id <> new.id) then
    return new;
  end if;
  -- Real user requests on their own name, like username_holds_guard. Staff and server-side work go through.
  if coalesce(current_setting('role', true), 'none') in ('authenticated', 'anon')
     and (select auth.uid()) = new.id and not public.is_staff()
     and public.feature_on_for_me('deleted_name_hold') then
    raise exception 'That username is taken' using errcode = 'check_violation';
  end if;
  perform public.note_deleted_name(new.id, new.username, new.username);
  return new;
end $function$;

-- public.detect_bot_replies()  [security definer]
CREATE OR REPLACE FUNCTION public.detect_bot_replies()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare prev record; sig public.bot_signals;
begin
  if current_setting('yapper.bot', true) = '1' or current_setting('yapper.bulk', true) = '1' then return new; end if;
  if exists (select 1 from public.bots where id = new.author_id) or exists (select 1 from public.bot_accounts where user_id = new.author_id) then return new; end if;
  select m.author_id, m.content, m.created_at into prev from public.messages m
    where m.channel_id = new.channel_id and m.created_at < new.created_at and m.id <> new.id
    order by m.created_at desc limit 1;
  if prev.author_id is null or prev.author_id = new.author_id then return new; end if;
  if new.created_at - prev.created_at > interval '1 second' then return new; end if;
  if coalesce(prev.content, '') !~ '^[!/$][A-Za-z][A-Za-z0-9_-]*(\s|$)' then return new; end if;
  if public.is_staff_user(new.author_id) then return new; end if;
  -- People racing each other with commands in a bot channel are people: a bot answers, it doesn't send a command back.
  if coalesce(new.content, '') ~ '^[!/$?.>][A-Za-z]' then return new; end if;
  -- A bot's answer is longer than a quick "lol"/"ok".
  if char_length(coalesce(new.content, '')) < 8 and new.attachment_path is null then return new; end if;
  insert into public.bot_signals as b (user_id, hits, first_at) values (new.author_id, 1, now())
    on conflict (user_id) do update set
      hits = case when b.first_at < now() - interval '1 hour' then 1 else b.hits + 1 end,
      first_at = case when b.first_at < now() - interval '1 hour' then now() else b.first_at end
    returning * into sig;
  if sig.hits >= 25 and not exists (select 1 from public.profiles where id = new.author_id and 'bot' = any(coalesce(badges, '{}'::text[]))) then
    update public.profiles set badges = array(select distinct unnest(coalesce(badges, '{}'::text[]) || array['bot'])) where id = new.author_id;
    insert into public.mod_log (actor, action, target_id, reason)
      values (null, 'marked_bot', new.author_id, 'Automatic: answered !/ commands within 1 second, 15 times in an hour');
  end if;
  return new;
end $function$;

