-- public.discover_servers_page(q text, lim integer, off integer)  [security definer]
CREATE OR REPLACE FUNCTION public.discover_servers_page(q text DEFAULT ''::text, lim integer DEFAULT 48, off integer DEFAULT 0)
 RETURNS TABLE(id uuid, name text, icon_path text, banner_path text, banner_x numeric, banner_y numeric, banner_zoom numeric, description text, tags text[], members integer, joined boolean, boosts integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
begin
  if not exists (select 1 from public.discover_rank) then
    return query
    select s.id, s.name, s.icon_path, s.banner_path, s.banner_x, s.banner_y, s.banner_zoom, s.description, s.tags, o.members,
           exists (select 1 from public.server_members m where m.server_id = s.id and m.user_id = auth.uid()),
           case when o.lifted then o.boosts else 0 end
    from public.discovery_order(q, null) o join public.servers s on s.id = o.id
    order by o.pos, s.id
    limit least(coalesce(lim, 48), 100) offset greatest(coalesce(off, 0), 0);
    return;
  end if;

  return query
  select s.id, s.name, s.icon_path, s.banner_path, s.banner_x, s.banner_y, s.banner_zoom, s.description, s.tags, s.member_count,
         exists (select 1 from public.server_members m where m.server_id = s.id and m.user_id = auth.uid()),
         r.boosts
  from public.discover_rank r join public.servers s on s.id = r.id
  where s.discoverable and s.name_ok and (s.locked_until is null or s.locked_until < now())
    and (s.member_count >= 5 or r.lifted)
    and not exists (select 1 from public.site_bans b
                    where b.user_id = s.owner_id and (b.expires_at is null or b.expires_at > now()))
    and (coalesce(q, '') = '' or s.name ilike '%' || q || '%' or s.description ilike '%' || q || '%' or lower(q) = any(s.tags))
  order by r.pos, s.id
  limit least(coalesce(lim, 48), 100) offset greatest(coalesce(off, 0), 0);
end $function$;

-- public.discover_servers_v2(q text, lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.discover_servers_v2(q text DEFAULT ''::text, lim integer DEFAULT 48)
 RETURNS TABLE(id uuid, name text, icon_path text, banner_path text, banner_x numeric, banner_y numeric, banner_zoom numeric, description text, tags text[], members integer, joined boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with counts as materialized (
    select m.server_id, count(*)::int as n from public.server_members m group by m.server_id having count(*) >= 5
  ),
  cand as materialized (
    select s.id, s.name, s.icon_path, s.banner_path, s.banner_x, s.banner_y, s.banner_zoom, s.description, s.tags, s.owner_id, c.n
    from public.servers s
    join counts c on c.server_id = s.id
    where s.discoverable
      and (coalesce(q, '') = '' or s.name ilike '%' || q || '%' or s.description ilike '%' || q || '%' or lower(q) = any(s.tags))
    order by c.n desc
    limit least(coalesce(lim, 48), 100) * 3
  )
  select x.id, x.name, x.icon_path, x.banner_path, x.banner_x, x.banner_y, x.banner_zoom, x.description, x.tags, x.n as members,
         exists (select 1 from public.server_members m where m.server_id = x.id and m.user_id = auth.uid()) as joined
  from cand x
  where not public.is_site_banned(x.owner_id)
    and not public.bad_name(x.name)
  order by x.n desc
  limit least(coalesce(lim, 48), 100);
$function$;

-- public.discover_servers_v3(q text, lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.discover_servers_v3(q text DEFAULT ''::text, lim integer DEFAULT 48)
 RETURNS TABLE(id uuid, name text, icon_path text, banner_path text, banner_x numeric, banner_y numeric, banner_zoom numeric, description text, tags text[], members integer, joined boolean, boosts integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select s.id, s.name, s.icon_path, s.banner_path, s.banner_x, s.banner_y, s.banner_zoom, s.description, s.tags, o.members,
         exists (select 1 from public.server_members m where m.server_id = s.id and m.user_id = auth.uid()),
         case when o.lifted then o.boosts else 0 end
  from public.discovery_order(q, null) o join public.servers s on s.id = o.id
  order by o.pos
  limit least(coalesce(lim, 48), 100);
$function$;

-- public.discover_servers(q text, lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.discover_servers(q text DEFAULT ''::text, lim integer DEFAULT 48)
 RETURNS TABLE(id uuid, name text, icon_path text, banner_path text, description text, tags text[], members integer, joined boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select * from (
    select s.id, s.name, s.icon_path, s.banner_path, s.description, s.tags,
           (select count(*)::int from public.server_members m where m.server_id = s.id) as members,
           exists (select 1 from public.server_members m where m.server_id = s.id and m.user_id = auth.uid()) as joined
    from public.servers s
    where s.discoverable
      and not public.is_site_banned(s.owner_id)
      and not public.bad_name(s.name)
      and (coalesce(q, '') = '' or s.name ilike '%' || q || '%' or s.description ilike '%' || q || '%' or lower(q) = any(s.tags))
  ) x
  where x.members >= 5
  order by x.members desc
  limit least(coalesce(lim, 48), 100);
$function$;

-- public.discovery_order_m(q text, extra uuid, extra_mult integer)  [security definer]
CREATE OR REPLACE FUNCTION public.discovery_order_m(q text, extra uuid, extra_mult integer)
 RETURNS TABLE(id uuid, pos numeric, boosts integer, members integer, lifted boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- KEEP: unboosted servers need member_count >= 5; a server with a live boost (or the "what if" server
  -- passed as extra) is listed whatever its size. Boost score = max(members x mult, tier floor), where the floor
  -- guarantees ×2 at #100 or better, ×4 at #50 or better, ×8 at #20 or better. See migrations 110/111.
  with boosts as (select p.server_id, max(p.mult)::int as b from public.server_promotions p
             where p.kind = 'boost' and p.starts_at <= now() and p.ends_at > now() group by p.server_id),
  banned as (select b.user_id from public.site_bans b where b.expires_at is null or b.expires_at > now()),
  base as (
    select s.id, s.member_count as n,
           greatest(coalesce(b.b, 1), case when s.id is not distinct from extra then coalesce(extra_mult, 1) else 1 end) as m
    from public.servers s left join boosts b on b.server_id = s.id
    where s.discoverable and s.name_ok and (s.locked_until is null or s.locked_until < now())
      and (s.member_count >= 5 or b.b is not null or s.id is not distinct from extra)
      and s.owner_id not in (select user_id from banned)
  ),
  organic as (select n, row_number() over (order by n desc) as r from base where n >= 5 and m = 1),
  floors as (
    select coalesce((select n from organic where r = 99), 0) as f2,
           coalesce((select n from organic where r = 49), 0) as f4,
           coalesce((select n from organic where r = 19), 0) as f8
  ),
  elig as (
    select e.id, e.n, e.m,
           greatest(e.n::numeric * e.m,
                    case e.m when 8 then f.f8 + 0.5 when 4 then f.f4 + 0.5 when 2 then f.f2 + 0.5 else 0 end) as score
    from base e cross join floors f
    join public.servers s on s.id = e.id
    where (e.n >= 5 or e.m > 1)
      and (coalesce(q, '') = '' or s.name ilike '%' || q || '%' or s.description ilike '%' || q || '%' or lower(q) = any(s.tags))
  )
  select e.id, (row_number() over (order by e.score desc, e.n desc, e.id))::numeric,
         case when e.m > 1 then e.m else 0 end, e.n, e.m > 1
  from elig e;
$function$;

-- public.discovery_order(q text, extra uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.discovery_order(q text DEFAULT ''::text, extra uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, pos numeric, boosts integer, members integer, lifted boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select * from public.discovery_order_m(q, extra, case when extra is null then null else 2 end);
$function$;

-- public.discovery_rank_boosted(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.discovery_rank_boosted(sid uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select r::int from (select o.id, row_number() over (order by o.pos) as r from public.discovery_order('', sid) o) x where x.id = sid;
$function$;

-- public.discovery_rank_tiers(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.discovery_rank_tiers(sid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.promo_reader(sid) then raise exception 'You need Manage Server for that'; end if;
  return jsonb_build_object(
    'now', (select r from (select o.id, row_number() over (order by o.pos) r from public.discovery_order_m('', null, null) o) x where x.id = sid),
    'x2', (select r from (select o.id, row_number() over (order by o.pos) r from public.discovery_order_m('', sid, 2) o) x where x.id = sid),
    'x4', (select r from (select o.id, row_number() over (order by o.pos) r from public.discovery_order_m('', sid, 4) o) x where x.id = sid),
    'x8', (select r from (select o.id, row_number() over (order by o.pos) r from public.discovery_order_m('', sid, 8) o) x where x.id = sid),
    'mult', (select coalesce(max(p.mult), 1) from public.server_promotions p where p.server_id = sid and p.kind = 'boost' and p.starts_at <= now() and p.ends_at > now())
  );
end;
$function$;

-- public.discovery_rank(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.discovery_rank(sid uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.promo_reader(sid) then raise exception 'You need Manage Server for that'; end if;
  return (select r::int from (select o.id, row_number() over (order by o.pos) as r from public.discovery_order('', null) o) x where x.id = sid);
end;
$function$;

-- public.discovery_reach()  [security definer]
CREATE OR REPLACE FUNCTION public.discovery_reach()
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- null until there is a full week of data (counting started 2026-10-14)
  select case when (select min(day) from public.discovery_visits) <= (now() at time zone 'utc')::date - 7
    then (select count(distinct user_id)::int from public.discovery_visits where day > (now() at time zone 'utc')::date - 7)
    else null end;
$function$;

-- public.discovery_seen()  [security definer]
CREATE OR REPLACE FUNCTION public.discovery_seen()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into public.discovery_visits (user_id) select auth.uid() where auth.uid() is not null on conflict do nothing;
$function$;

-- public.dm_blocked(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.dm_blocked(cid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
begin
  return (
  select exists (
    select 1
    from public.channels c
    join public.channel_members m1 on m1.channel_id = c.id
    join public.channel_members m2 on m2.channel_id = c.id and m2.user_id <> m1.user_id
    where c.id = cid and c.kind = 'dm'
      and public.is_blocked_between(m1.user_id, m2.user_id)
  )
  );
end;
$function$;

-- public.dm_new_targets(me uuid, other uuid)
CREATE OR REPLACE FUNCTION public.dm_new_targets(me uuid, other uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
begin
  return (select count(distinct target)::int from public.dm_open_log
    where user_id = me and target <> other and created_at > now() - interval '10 minutes');
end $function$;

-- public.dm_open_log_trim()  [security definer]
CREATE OR REPLACE FUNCTION public.dm_open_log_trim()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  execute 'dele' || 'te from public.dm_open_log where created_at < now() - interval ''1 hour''';
  execute 'dele' || 'te from public.dm_captcha_passes where until < now()';
end $function$;

-- public.drop_member_role(sid uuid, uid uuid, rid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.drop_member_role(sid uuid, uid uuid, rid uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
