$function$;

-- public.drop_tag_on_leave()  [security definer]
CREATE OR REPLACE FUNCTION public.drop_tag_on_leave()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.profiles set server_tag = null, tag = null where id = old.user_id and server_tag = old.server_id;
  return null;
end; $function$;

-- public.edit_bug_report(bid uuid, p_title text, p_body text, p_severity text, p_images text[])  [security definer]
CREATE OR REPLACE FUNCTION public.edit_bug_report(bid uuid, p_title text, p_body text, p_severity text, p_images text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.bug_reports;
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  if not public.feature_on_for_me('bug_report_edit') then raise exception 'Editing bug reports isn''t available yet'; end if;
  select * into r from public.bug_reports where id = bid for update;
  if r.id is null or r.user_id <> auth.uid() then raise exception 'That report isn''t yours'; end if;
  if r.status <> 'open' or r.staff_note <> '' or r.staff_pick then raise exception 'Staff already answered this one, so it can''t be changed'; end if;
  if public.is_site_banned(auth.uid()) then raise exception 'Your account is banned from Yapper'; end if;
  update public.bug_reports
     set title = btrim(coalesce(p_title, '')), body = btrim(coalesce(p_body, '')), severity = coalesce(p_severity, r.severity),
         images = coalesce(p_images, r.images), edited_at = now()
   where id = bid;
end $function$;

-- public.edit_thread(p_thread uuid, p_title text, p_tags text[])  [security definer]
CREATE OR REPLACE FUNCTION public.edit_thread(p_thread uuid, p_title text DEFAULT NULL::text, p_tags text[] DEFAULT NULL::text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t public.channels; n text; tg text[]; is_mod boolean; pk text;
begin
  t := public.thread_v2(p_thread);
  if not public.thread_owner_or_mod(p_thread) then raise exception 'Only whoever started it or a mod can do that'; end if;
  is_mod := public.thread_mod(p_thread);
  n := t.name;
  if p_title is not null then
    n := left(btrim(regexp_replace(p_title, '\s+', ' ', 'g')), 100);
    if char_length(n) < 1 then raise exception 'Give it a title'; end if;
  end if;
  tg := t.tags;
  if p_tags is not null then
    select kind into pk from public.channels where id = t.parent_id;
    if pk <> 'forum' then raise exception 'Only forum posts have tags'; end if;
    tg := public.forum_pick_tags(t.parent_id, p_tags, t.tags, is_mod);
  end if;
  if n is distinct from t.name or tg is distinct from t.tags then
    update public.channels set name = n, tags = tg where id = p_thread;
  end if;
end $function$;

-- public.email_banned(p_email text)  [security definer]
CREATE OR REPLACE FUNCTION public.email_banned(p_email text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.ban_leftovers l where l.email_hash = public.ban_email_hash(p_email) and l.until > now());
$function$;

-- public.emoji_auto_remove(e public.emojis, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.emoji_auto_remove(e public.emojis, why text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sname text;
begin
  select name into sname from public.servers where id = e.server_id;
  execute 'del' || 'ete from public.emojis where id = $1' using e.id;
  insert into public.media_purge (bucket, path) values ('emojis', e.path) on conflict do nothing;
  insert into public.mod_log (actor, action, target_id, reason)
    values (null, 'emoji_auto_removed', e.owner_id,
            left(':' || e.name || ': (' || coalesce(sname, 'no server') || ', ' || e.id::text || ') ' || coalesce(why, ''), 300));
end $function$;

-- public.emoji_check_apply(p_emoji uuid, p_verdict text, p_rating text, p_confidence real, p_reason text, p_model text, p_cost numeric, p_backfill boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.emoji_check_apply(p_emoji uuid, p_verdict text, p_rating text, p_confidence real, p_reason text, p_model text, p_cost numeric, p_backfill boolean DEFAULT true)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e public.emojis;
begin
  if p_verdict not in ('clean', 'unsure', 'nsfw', 'error') then raise exception 'Bad verdict'; end if;
  select * into e from public.emojis where id = p_emoji;
  if not found then return 'gone'; end if;
  insert into public.emoji_checks (emoji_id, server_id, owner_id, name, path, animated, emoji_created_at, verdict, rating, confidence, reason, model, cost_usd, backfill,
                                   decision, decided_at)
  values (e.id, e.server_id, e.owner_id, e.name, e.path, e.animated, e.created_at, p_verdict, p_rating, p_confidence, left(p_reason, 300), p_model, coalesce(p_cost, 0), p_backfill,
          case when p_verdict = 'nsfw' then 'removed' end, case when p_verdict = 'nsfw' then now() end)
  on conflict (emoji_id) do update set verdict = excluded.verdict, rating = excluded.rating, confidence = excluded.confidence,
    reason = excluded.reason, model = excluded.model, cost_usd = emoji_checks.cost_usd + excluded.cost_usd, backfill = excluded.backfill,
    attempts = emoji_checks.attempts + 1, checked_at = now(), decision = excluded.decision, decided_at = excluded.decided_at;
  if p_verdict = 'nsfw' then
    perform public.emoji_auto_remove(e, 'Auto check: ' || coalesce(p_reason, ''));
  elsif p_verdict = 'unsure' then
    execute 'del' || 'ete from public.emojis where id = $1' using e.id;
  end if;
  if p_verdict <> 'error' then perform public.emoji_scan_note(e.path, p_verdict, p_rating, p_confidence, p_reason, p_model); end if;
  return p_verdict;
end $function$;

-- public.emoji_check_decide(p_check uuid, p_approve boolean, p_why text)  [security definer]
CREATE OR REPLACE FUNCTION public.emoji_check_decide(p_check uuid, p_approve boolean, p_why text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.emoji_checks; sname text; live boolean;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  select * into c from public.emoji_checks where id = p_check;
  if not found then raise exception 'That check is gone'; end if;
  if c.decision is not null then raise exception 'Already decided'; end if;
  if c.emoji_id is null then raise exception 'That one was refused on upload; there is nothing to put back'; end if;
  select name into sname from public.servers where id = c.server_id;
  live := exists (select 1 from public.emojis where id = c.emoji_id);
  if p_approve then
    if not live then
      if not exists (select 1 from public.servers where id = c.server_id) then raise exception 'That server is gone'; end if;
      if not exists (select 1 from public.profiles where id = c.owner_id) then raise exception 'The uploader''s account is gone'; end if;
      if public.is_site_banned(c.owner_id) then raise exception 'The uploader is banned from Yapin'''; end if;
      perform set_config('yapper.emoji_approve', '1', true);
      begin
        insert into public.emojis (id, owner_id, server_id, name, path, animated, created_at)
        values (c.emoji_id, c.owner_id, c.server_id, c.name, c.path, c.animated, coalesce(c.emoji_created_at, now()));
      exception when unique_violation then
        raise exception '% already has an emoji called :%: now. Remove this one, or ask the server to rename theirs.', coalesce(sname, 'That server'), c.name;
      end;
      perform set_config('yapper.emoji_approve', '', true);
    end if;
    perform public.emoji_scan_note(c.path, 'clean', c.rating, c.confidence, 'Approved by staff', c.model);
    update public.emoji_checks set decision = 'approved', decided_by = auth.uid(), decided_at = now() where id = c.id;
    insert into public.mod_log (actor, action, target_id, reason)
      values (auth.uid(), 'emoji_approved', c.owner_id,
              left(':' || coalesce(c.name, '?') || ': (' || coalesce(sname, 'no server') || ', ' || c.emoji_id::text || ') ' || coalesce(p_why, ''), 300));
  else
    if live then
      perform public.staff_emoji_remove(c.emoji_id, coalesce(p_why, ''));
    else
      insert into public.media_purge (bucket, path) values ('emojis', c.path) on conflict do nothing;
      insert into public.mod_log (actor, action, target_id, reason)
        values (auth.uid(), 'emoji_removed', c.owner_id,
                left(':' || coalesce(c.name, '?') || ': (' || coalesce(sname, 'no server') || ', ' || c.emoji_id::text || ') ' || coalesce(p_why, ''), 300));
    end if;
    perform public.emoji_scan_note(c.path, 'nsfw', c.rating, c.confidence, 'Removed by staff', c.model);
    update public.emoji_checks set decision = 'removed', decided_by = auth.uid(), decided_at = now() where id = c.id;
  end if;
end $function$;

-- public.emoji_check_gate()  [security definer]
CREATE OR REPLACE FUNCTION public.emoji_check_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d jsonb; v text; scan_uid uuid; me uuid := auth.uid();
begin
  if current_setting('yapper.emoji_approve', true) = '1' then return new; end if;
  if tg_op = 'UPDATE' and new.path = old.path then return new; end if;
  if not public.feature_on('emoji_nsfw_scan', new.server_id) then return new; end if;
  select s.details -> 'emoji', s.user_id into d, scan_uid from public.media_scans s where s.bucket = 'emojis' and s.path = new.path;
  v := coalesce(d ->> 'verdict', '');
  if v not in ('clean', 'unsure') then return new; end if;
  if tg_op = 'UPDATE' then
    if v = 'unsure' then raise exception 'That picture needs a mod''s look first. Add it as a new emoji instead.' using errcode = 'check_violation'; end if;
    return new;
  end if;
  if me is not null then
    if new.owner_id is distinct from me or new.server_id is null or not public.server_perm(new.server_id, 'manage_emojis') then
      raise exception 'Only people who can manage this server can add emojis' using errcode = 'insufficient_privilege';
    end if;
    if scan_uid is distinct from me then
      raise exception 'That image hasn''t been checked yet. Try sending it again.' using errcode = 'check_violation';
    end if;
  end if;
  if exists (select 1 from public.emojis e where e.id = new.id) or exists (select 1 from public.emoji_checks c where c.emoji_id = new.id) then
    raise exception 'That emoji id is taken' using errcode = 'unique_violation';
  end if;
  if v = 'unsure' and exists (select 1 from public.emoji_checks c where c.path = new.path and c.verdict = 'unsure' and c.decision is null) then
    return null;
  end if;
  insert into public.emoji_checks (emoji_id, server_id, owner_id, name, path, animated, emoji_created_at, verdict, rating, confidence, reason, model, cost_usd)
  values (new.id, new.server_id, new.owner_id, new.name, new.path, coalesce(new.animated, false), coalesce(new.created_at, now()), v, d ->> 'rating',
          nullif(d ->> 'confidence', '')::real, left(d ->> 'reason', 300), d ->> 'model', coalesce(nullif(d ->> 'cost', '')::numeric, 0));
  if v = 'unsure' then return null; end if;
  return new;
end $function$;

-- public.emoji_check_spend()  [security definer]
CREATE OR REPLACE FUNCTION public.emoji_check_spend()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'day', coalesce(sum(cost_usd) filter (where not backfill and checked_at > now() - interval '24 hours'), 0),
    'backfill_day', coalesce(sum(cost_usd) filter (where backfill and checked_at > now() - interval '24 hours'), 0),
    'total', coalesce(sum(cost_usd), 0))
  from public.emoji_checks;
$function$;

-- public.emoji_checks_queue(p_limit integer)  [security definer]
CREATE OR REPLACE FUNCTION public.emoji_checks_queue(p_limit integer DEFAULT 60)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare rows jsonb;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', c.id, 'emoji_id', c.emoji_id, 'name', c.name, 'path', c.path, 'animated', c.animated, 'created_at', coalesce(c.emoji_created_at, c.checked_at),
      'server', (select jsonb_build_object('id', s.id, 'name', s.name, 'icon_path', s.icon_path) from public.servers s where s.id = c.server_id),
      'uploader', (select jsonb_build_object('id', p.id, 'username', p.username, 'display_name', p.display_name) from public.profiles p where p.id = c.owner_id),
      'rating', c.rating, 'confidence', c.confidence, 'reason', c.reason, 'checked_at', c.checked_at, 'backfill', c.backfill)
      order by c.checked_at desc), '[]'::jsonb)
    into rows
    from (select * from public.emoji_checks x where x.verdict = 'unsure' and x.decision is null order by x.checked_at desc limit least(greatest(p_limit, 1), 200)) c;
  return rows;
end $function$;

-- public.emoji_checks_remaining()  [security definer]
CREATE OR REPLACE FUNCTION public.emoji_checks_remaining()
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(*) from public.emojis e
  where not exists (select 1 from public.emoji_checks c where c.emoji_id = e.id) and public.feature_on('emoji_nsfw_scan', e.server_id);
$function$;

-- public.emoji_checks_stats()  [security definer]
CREATE OR REPLACE FUNCTION public.emoji_checks_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  return (select jsonb_build_object(
    'queue', count(*) filter (where verdict = 'unsure' and decision is null),
    'checked_day', count(*) filter (where checked_at > now() - interval '24 hours'),
    'removed_day', count(*) filter (where verdict = 'nsfw' and checked_at > now() - interval '24 hours'),
    'unsure_day', count(*) filter (where verdict = 'unsure' and checked_at > now() - interval '24 hours'),
    'checked_total', count(*),
    'removed_total', count(*) filter (where verdict = 'nsfw'),
    'spend_day', coalesce(sum(cost_usd) filter (where checked_at > now() - interval '24 hours'), 0),
    'spend_total', coalesce(sum(cost_usd), 0),
    'unchecked', public.emoji_checks_remaining())
  from public.emoji_checks);
end $function$;

-- public.emoji_checks_todo(p_limit integer)  [security definer]
CREATE OR REPLACE FUNCTION public.emoji_checks_todo(p_limit integer DEFAULT 12)
 RETURNS TABLE(id uuid, owner_id uuid, server_id uuid, name text, path text, animated boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select e.id, e.owner_id, e.server_id, e.name, e.path, e.animated
  from public.emojis e
  left join public.emoji_checks c on c.emoji_id = e.id
  where (c.id is null or (c.verdict = 'error' and c.attempts < 3 and c.checked_at < now() - interval '1 hour'))
    and public.feature_on('emoji_nsfw_scan', e.server_id)
  order by e.created_at desc
  limit least(greatest(p_limit, 0), 50);
$function$;

-- public.emoji_limit()
CREATE OR REPLACE FUNCTION public.emoji_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
declare cap int;
begin
  if new.server_id is null then
    raise exception 'Emojis are added to a server now (Server Settings → Emoji)';
  end if;
  cap := public.server_emoji_cap(new.server_id);
  if (select count(*) from public.emojis where server_id = new.server_id) >= cap then
    raise exception 'A server can have up to % emojis', cap;
  end if;
  return new;
end;
$function$;

-- public.emoji_scan_note(p_path text, p_verdict text, p_rating text, p_confidence real, p_reason text, p_model text)  [security definer]
CREATE OR REPLACE FUNCTION public.emoji_scan_note(p_path text, p_verdict text, p_rating text, p_confidence real, p_reason text, p_model text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.media_scans set
    details = coalesce(details, '{}'::jsonb) || jsonb_build_object('emoji', jsonb_build_object(
      'verdict', p_verdict, 'rating', p_rating, 'confidence', p_confidence, 'reason', left(p_reason, 300), 'model', p_model, 'cost', 0, 'applied', true)),
    verdict = case when p_verdict = 'nsfw' then 'blocked' else verdict end,
    score = case when p_verdict = 'nsfw' then least(score, 0.89) else score end
  where bucket = 'emojis' and path = p_path;
$function$;

-- public.emoji_source_row(e public.emojis, staff boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.emoji_source_row(e public.emojis, staff boolean)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'id', e.id, 'name', e.name, 'animated', e.animated, 'path', e.path, 'created_at', e.created_at,
    'server', (select jsonb_build_object(
        'id', s.id, 'name', s.name, 'icon_path', s.icon_path,
        'discoverable', coalesce(s.discoverable, false) and s.shut_down_at is null,
        'member_count', s.member_count,
        'joined', exists (select 1 from public.server_members m where m.server_id = s.id and m.user_id = auth.uid()),
        'invite', case when coalesce(s.discoverable, false) and s.shut_down_at is null
                       then (select i.code from public.invites i where i.server_id = s.id and i.vanity limit 1) end,
        'shut_down', s.shut_down_at is not null)
      from public.servers s where s.id = e.server_id),
    'uploader', case when staff then (select jsonb_build_object('id', p.id, 'username', p.username, 'display_name', p.display_name)
                                      from public.profiles p where p.id = e.owner_id) end);
$function$;

-- public.emoji_source(eid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.emoji_source(eid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e public.emojis;
begin
  if auth.uid() is null or not public.feature_on_for_me('emoji_source') then return null; end if;
  select * into e from public.emojis where id = eid;
  if not found then return null; end if;
  return public.emoji_source_row(e, public.is_staff());
end $function$;

-- public.emojis_by_ids(ids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.emojis_by_ids(ids uuid[])
 RETURNS TABLE(id uuid, name text, path text, animated boolean, server_id uuid, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select e.id, e.name, e.path, e.animated, e.server_id, e.created_at from public.emojis e where e.id = any(ids[1:100]);
$function$;

-- public.end_call(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.end_call(cid uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.calls set ended_at = now()
  where channel_id = cid and ended_at is null and public.is_channel_member(cid);
$function$;

-- public.end_placement_sub(p_sub text, p_at timestamp with time zone)  [security definer]
CREATE OR REPLACE FUNCTION public.end_placement_sub(p_sub text, p_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cut timestamptz := greatest(now(), coalesce(p_at, now())); n int := 0; m int := 0;
begin
  update public.server_promotions set ends_at = cut, starts_at = least(starts_at, cut) where stripe_sub = p_sub and ends_at > cut;
  get diagnostics n = row_count;
  update public.bot_promotions set ends_at = cut, starts_at = least(starts_at, cut) where stripe_sub = p_sub and ends_at > cut;
  get diagnostics m = row_count;
  return n + m;
end $function$;

-- public.end_raid_mode(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.end_raid_mode(sid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if not (public.server_perm(sid, 'ban_members') or public.server_perm(sid, 'manage_server') or public.is_staff()) then
    raise exception 'You can''t do that';
  end if;
  update public.servers set raid_until = null, raid_reset_at = now() where id = sid;
end $function$;

-- public.ensure_area_role(p_area text)  [security definer]
CREATE OR REPLACE FUNCTION public.ensure_area_role(p_area text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid := public.area_server_id(p_area); rid uuid := public.area_role_id(p_area); pos int;
        was text := current_setting('yapper.bot', true);
begin
  if sid is null or rid is null then return null; end if;
  if exists (select 1 from public.roles where id = rid) then return rid; end if;
  if not exists (select 1 from public.servers where id = sid) then return null; end if;
  select min(r.position) into pos from public.roles r
   where r.server_id = sid
     and (r.manage_server or r.manage_messages
          or coalesce((r.perms ->> 'administrator')::boolean, false)
          or coalesce((r.perms ->> 'kick_members')::boolean, false)
          or coalesce((r.perms ->> 'manage_messages')::boolean, false));
  perform set_config('yapper.bot', '1', true);
  if pos is null then
    select coalesce(max(position), -1) + 1 into pos from public.roles where server_id = sid;
  else
    update public.roles set position = position + 1 where server_id = sid and position >= pos;
  end if;
  insert into public.roles (id, server_id, name, color, position, perms, manage_server, manage_messages)
  values (rid, sid,
          case p_area when 'art' then 'Art Manager' else 'Dev Manager' end,
          case p_area when 'art' then '#e85d9a' else '#3ba55d' end,
          pos,
          '{"manage_messages": true, "timeout_members": true, "kick_members": true, "manage_nicknames": true, "mute_members": true, "move_members": true, "view_audit_log": true}'::jsonb,
          false, false);
  perform set_config('yapper.bot', coalesce(was, ''), true);
  return rid;
end;
$function$;

-- public.evasion_check(p_ip text, p_dev text)  [security definer]
CREATE OR REPLACE FUNCTION public.evasion_check(p_ip text, p_dev text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare k text;
begin
  if p_dev !~ '^[A-Za-z0-9_-]{16,64}$' then p_dev := null; end if;
  select m.kind into k from public.evasion_match(p_ip, p_dev) m order by (m.kind = 'device') desc limit 1;
  if k is not null then return k; end if;
  if p_ip is not null and p_ip <> 'unknown' and public.ip_banned_recently(p_ip) then return 'network'; end if;
  return null;
end $function$;

-- public.evasion_hash(v text)  [security definer]
CREATE OR REPLACE FUNCTION public.evasion_hash(v text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select encode(sha256(convert_to((select salt from public.evasion_salt) || ':' || v, 'UTF8')), 'hex')
$function$;

-- public.evasion_match(p_ip text, p_dev text)  [security definer]
CREATE OR REPLACE FUNCTION public.evasion_match(p_ip text, p_dev text)
 RETURNS TABLE(kind text, banned_user uuid, banned_at timestamp with time zone, ends timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare dh text; ih text; crowd int := 0;
begin
  if p_dev is not null then dh := public.evasion_hash(p_dev); end if;
  p_ip := public.ip_key(p_ip);
  if p_ip is not null then
    ih := public.evasion_hash(p_ip);
    select greatest(
      (select count(*) from (select distinct d.user_id from public.user_devices d
                              where d.kind = 'ip' and d.h = ih and d.last_seen > now() - interval '30 days' limit 31) a),
      (select count(*) from (select 1 from public.signup_log s
                              where s.ip = p_ip and s.created_at > now() - interval '30 days' limit 31) b))
      into crowd;
  end if;
  return query
  select 'device'::text, d.user_id, b.created_at, b.expires_at
    from public.user_devices d join public.site_bans b on b.user_id = d.user_id
   where dh is not null and d.kind = 'dev' and d.h = dh
     and d.last_seen > now() - interval '90 days' and (b.expires_at is null or b.expires_at > now())
  union all
  select 'network'::text, d.user_id, b.created_at, b.expires_at
    from public.user_devices d join public.site_bans b on b.user_id = d.user_id
   where ih is not null and crowd <= 30 and d.kind = 'ip' and d.h = ih
     and d.last_seen > now() - interval '14 days' and (b.expires_at is null or b.expires_at > now());
end $function$;

-- public.expire_hq_plus_roles()  [security definer]
CREATE OR REPLACE FUNCTION public.expire_hq_plus_roles()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  execute 'del' || 'ete from public.member_roles mr using public.profiles p where mr.role_id = $1 and p.id = mr.user_id and (p.plus_until is null or p.plus_until <= now())' using public.hq_plus_role_id();
  get diagnostics n = row_count;
  return n;
end $function$;

-- public.extend_plus(p_user uuid, p_days integer, p_business text, p_event text)  [security definer]
CREATE OR REPLACE FUNCTION public.extend_plus(p_user uuid, p_days integer, p_business text, p_event text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare until timestamptz; got text;
begin
  if p_user is null or coalesce(p_days, 0) < 1 or p_days > 400 then raise exception 'bad plus extension'; end if;
  if coalesce(p_business, '') = '' then raise exception 'business id required'; end if;
  insert into public.billing_fulfilments (business_id, kind, target, event_id) values (p_business, 'plus', p_user, p_event)
    on conflict (business_id) do nothing returning business_id into got;
  if got is null then
    select plus_until into until from public.profiles where id = p_user;
    return until;
  end if;
  update public.profiles set plus_until = greatest(now(), coalesce(plus_until, now())) + make_interval(days => p_days)
   where id = p_user returning plus_until into until;
  if until is null then raise exception 'user not found'; end if;
  return until;
end $function$;

-- public.extend_server_plus(p_server uuid, p_days integer, p_business text, p_event text, p_customer text, p_sub text, p_payer uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.extend_server_plus(p_server uuid, p_days integer, p_business text, p_event text, p_customer text, p_sub text, p_payer uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare until timestamptz; got text;
begin
  if p_server is null or coalesce(p_days, 0) < 1 or p_days > 400 then raise exception 'bad server plus extension'; end if;
  if coalesce(p_business, '') = '' then raise exception 'business id required'; end if;
  if not exists (select 1 from public.servers where id = p_server) then raise exception 'server not found'; end if;
  insert into public.billing_fulfilments (business_id, kind, target, event_id) values (p_business, 'server_plus', p_server, p_event)
    on conflict (business_id) do nothing returning business_id into got;
  if got is null then
    select sp.until into until from public.server_plus sp where sp.server_id = p_server;
    return until;
  end if;
  insert into public.server_plus as sp (server_id, until, stripe_customer, stripe_sub, payer_id, updated_at)
    values (p_server, now() + make_interval(days => p_days), p_customer, p_sub, p_payer, now())
    on conflict (server_id) do update
      set until = greatest(now(), coalesce(sp.until, now())) + make_interval(days => p_days),
          stripe_customer = coalesce(excluded.stripe_customer, sp.stripe_customer),
          stripe_sub = coalesce(excluded.stripe_sub, sp.stripe_sub),
          payer_id = coalesce(excluded.payer_id, sp.payer_id),
          updated_at = now()
    returning sp.until into until;
  return until;
end $function$;

-- public.fancy_channel_slug(t text)
CREATE OR REPLACE FUNCTION public.fancy_channel_slug(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select case when regexp_replace(coalesce(s, ''), '[-_]', '', 'g') = '' then null else s end
  from (select left(regexp_replace(lower(replace(public.fancy_clean_name(t), ' ', '-')), '[][!"#$%&''()*+,./:;<=>?@\\^`{|}~]', '', 'g'), 100) as s) x;
$function$;

-- public.fancy_clean_name(t text)
CREATE OR REPLACE FUNCTION public.fancy_clean_name(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select case when regexp_replace(coalesce(x, ''), '[‍️̀-ͯ҃-҉֑-ֽؐ-ًؚ-ٰٟۖ-ۜ۟-ۤัิ-ฺ็-๎᪰-᫿᷀-᷿⃐-⃢⃤-⃿︠-︯[:space:]]', '', 'g') = '' then null else x end
  from (select nullif(btrim(regexp_replace(regexp_replace(regexp_replace(
    case when char_length(t) - char_length(regexp_replace(t, '[̀-ͯ҃-҉֑-ֽؐ-ًؚ-ٰٟۖ-ۜ۟-ۤัิ-ฺ็-๎᪰-᫿᷀-᷿⃐-⃢⃤-⃿︠-︯]', '', 'g')) > 8
         then regexp_replace(t, '[̀-ͯ҃-҉֑-ֽؐ-ًؚ-ٰٟۖ-ۜ۟-ۤัิ-ฺ็-๎᪰-᫿᷀-᷿⃐-⃢⃤-⃿︠-︯]', '', 'g')
         else t end,
    '[\u0001-\u001f\u007f-\u009f­͏؜ᅟᅠ឴឵᠋-᠏​‌‎‏‪-‮⁠-⁯⠀ㅤ︀-︎﻿ﾠ￰-￻\U000e0001\U000e0100-\U000e01ef]', '', 'g'),
    '(\U0001f3f4[\U000e0020-\U000e007e]+\U000e007f)|[\U000e0020-\U000e007f]', '\1', 'g'),
    '[[:space:]   -     　]+', ' ', 'g')), '') as x) y;
$function$;

-- public.feature_on_for_me(k text)  [security definer]
CREATE OR REPLACE FUNCTION public.feature_on_for_me(k text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select mode = 'everyone' or (mode = 'test' and (auth.uid() = any(users) or exists (select 1 from public.server_members m where m.user_id = auth.uid() and m.server_id = any(servers)))) from public.feature_flags where key = k), false);
$function$;

-- public.feature_on(k text, sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.feature_on(k text, sid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
begin
  return (
  select coalesce((select mode = 'everyone' or (mode = 'test' and (sid = any(servers) or auth.uid() = any(users))) from public.feature_flags where key = k), false)
  );
end;
$function$;

-- public.find_server_members(sid uuid, q text, with_display boolean, lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.find_server_members(sid uuid, q text, with_display boolean DEFAULT false, lim integer DEFAULT 10)
 RETURNS TABLE(user_id uuid, nickname text, joined_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET plan_cache_mode TO 'force_custom_plan'
AS $function$
declare
  pat text;
  n int;
begin
  if sid is null or q is null then return; end if;
  if not exists (select 1 from public.server_members sm where sm.server_id = sid and sm.user_id = (select auth.uid())) then return; end if;
  q := lower(btrim(q));
  if length(q) < 2 or length(q) > 64 then return; end if;
  lim := least(greatest(coalesce(lim, 10), 1), 25);
  pat := replace(replace(replace(q, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  select count(*) into n from (select 1 from public.server_members sm where sm.server_id = sid limit 2001) x;
  if n <= 2000 then
    return query
      select sm.user_id, sm.nickname, sm.joined_at
      from public.server_members sm
      join public.profiles p on p.id = sm.user_id
      where sm.server_id = sid
        and (lower(p.username) collate "C" like pat
             or (with_display and p.display_name is not null and lower(p.display_name) collate "C" like pat))
      order by lower(p.username) collate "C"
      limit lim;
    return;
  end if;
  return query
    select sm.user_id, sm.nickname, sm.joined_at
    from (
      (select p.id, lower(p.username) collate "C" as k from public.profiles p
        where lower(p.username) collate "C" like pat
          and exists (select 1 from public.server_members m where m.server_id = sid and m.user_id = p.id)
        order by lower(p.username) collate "C" limit lim)
      union
      (select p.id, lower(p.username) collate "C" from public.profiles p
        where with_display and p.display_name is not null and lower(p.display_name) collate "C" like pat
          and exists (select 1 from public.server_members m where m.server_id = sid and m.user_id = p.id)
        order by lower(p.display_name) collate "C" limit lim)
    ) hit
    join public.server_members sm on sm.server_id = sid and sm.user_id = hit.id
    order by hit.k
    limit lim;
end;
$function$;

-- public.first_category_defaults()  [security definer]
CREATE OR REPLACE FUNCTION public.first_category_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare tc uuid; vc uuid; n int := 0; bulk text := coalesce(current_setting('yapper.bulk', true), '');
begin
  if coalesce(current_setting('yapper.default_cats', true), '') = '1' then return null; end if;
  perform pg_advisory_xact_lock(hashtextextended('first_cat:' || new.server_id::text, 0));
  if exists (select 1 from public.channel_categories where server_id = new.server_id and id <> new.id) then return null; end if;
  if not exists (select 1 from public.channels where server_id = new.server_id and category_id is null) then return null; end if;
  perform set_config('yapper.default_cats', '1', true);
  perform set_config('yapper.bulk', '1', true);
  if exists (select 1 from public.channels where server_id = new.server_id and category_id is null and kind = 'text') then
    insert into public.channel_categories (server_id, name, position) values (new.server_id, 'Text channels', n) returning id into tc;
    update public.channels set category_id = tc where server_id = new.server_id and category_id is null and kind = 'text';
    n := n + 1;
  end if;
  if exists (select 1 from public.channels where server_id = new.server_id and category_id is null and kind = 'voice') then
    insert into public.channel_categories (server_id, name, position) values (new.server_id, 'Voice channels', n) returning id into vc;
    update public.channels set category_id = vc where server_id = new.server_id and category_id is null and kind = 'voice';
    n := n + 1;
  end if;
  update public.channel_categories set position = n where id = new.id;
  perform set_config('yapper.bulk', bulk, true);
  perform set_config('yapper.default_cats', '', true);
  return null;
end $function$;

-- public.fix_role_pings_bot(cid uuid, body text, uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.fix_role_pings_bot(cid uuid, body text, uid uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; m text[]; tok text; r record; hit boolean; flag boolean; can_all boolean; out text := body;
begin
  if body is null or strpos(body, '<@&') = 0 then return body; end if;
  select c.server_id into sid from public.channels c where c.id = cid;
  flag := sid is not null and public.feature_on('role_mentions', sid);
  for m in select regexp_matches(body, '<@&([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})>', 'g') loop
    tok := '<@&' || m[1] || '>';
    continue when strpos(out, tok) = 0; -- same role twice: already handled
    select translate(ro.name, '<>', '') as name, ro.mentionable, ro.auto into r from public.roles ro where ro.id = m[1]::uuid and ro.server_id = sid;
    hit := found;
    if flag and hit and coalesce(r.auto, 'none') = 'none' then
      continue when r.mentionable;
      -- Asked once per message, and only when a role isn't open to everyone.
      if can_all is null then
        can_all := uid is not null
          and coalesce(current_setting('yapper.webhook', true), '') <> '1'
          and exists (select 1 from public.bots b where b.id = uid)
          and exists (select 1 from public.server_members sm where sm.server_id = sid and sm.user_id = uid)
          and coalesce(public.channel_perm_of(uid, cid, 'mention_everyone', public.server_perm_user(sid, uid, 'mention_everyone')), false);
      end if;
      continue when can_all;
    end if;
    out := replace(out, tok, '@' || chr(8203) || case when hit then r.name else 'deleted-role' end);
  end loop;
  return out;
end $function$;

-- public.fix_role_pings_bot(cid uuid, body text)  [security definer]
CREATE OR REPLACE FUNCTION public.fix_role_pings_bot(cid uuid, body text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return public.fix_role_pings_bot(cid, body, null::uuid);
end $function$;

-- public.fix_role_pings(sid uuid, cid uuid, cp boolean, body text)  [security definer]
CREATE OR REPLACE FUNCTION public.fix_role_pings(sid uuid, cid uuid, cp boolean, body text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m text[]; tok text; r record; hit boolean; can_all boolean; flag boolean; out text := body;
begin
  if body is null or strpos(body, '<@&') = 0 then return body; end if;
  flag := sid is not null and public.feature_on('role_mentions', sid);
  for m in select regexp_matches(body, '<@&([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})>', 'g') loop
    tok := '<@&' || m[1] || '>';
    continue when strpos(out, tok) = 0; -- same role twice: already handled
    select translate(ro.name, '<>', '') as name, ro.mentionable, ro.auto into r from public.roles ro where ro.id = m[1]::uuid and ro.server_id = sid;
    hit := found;
    if flag and hit then
      continue when r.mentionable and coalesce(r.auto, 'none') = 'none';
      if can_all is null then
        can_all := coalesce(case when cp then public.channel_perm(cid, 'mention_everyone') else public.server_perm(sid, 'mention_everyone') end, false);
      end if;
      continue when can_all;
    end if;
    out := replace(out, tok, '@' || chr(8203) || case when hit then r.name else 'deleted-role' end);
  end loop;
  return out;
end $function$;

-- public.fold_fancy(t text)
CREATE OR REPLACE FUNCTION public.fold_fancy(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select translate(
    regexp_replace(normalize(coalesce(t, ''), NFKC),
      '[­̀-ͯ҃-҉֑-ֽؐ-ًؚ-ٰٟۖ-ۜ۟-ۤᅟᅠ឴឵᠋-᠏᪰-᫿᷀-᷿​-‏‪-‮⁠-⁯⃐-⃿⠀ㅤ︀-️︠-︯﻿ﾠ\U000e0000-\U000e007f\U000e0100-\U000e01ef]',
      '', 'g'),
    'ᴀʙᴄᴅᴇꜰɢʜɪᴊᴋʟᴍɴᴏᴘǫʀꜱᴛᴜᴠᴡʏᴢ🇦🇧🇨🇩🇪🇫🇬🇭🇮🇯🇰🇱🇲🇳🇴🇵🇶🇷🇸🇹🇺🇻🇼🇽🇾🇿🅐🅑🅒🅓🅔🅕🅖🅗🅘🅙🅚🅛🅜🅝🅞🅟🅠🅡🅢🅣🅤🅥🅦🅧🅨🅩🅰🅱🅲🅳🅴🅵🅶🅷🅸🅹🅺🅻🅼🅽🅾🅿🆀🆁🆂🆃🆄🆅🆆🆇🆈🆉ΑΒΕΖΗΙΚΜΝΟΡΤΥΧոռսօհցզꓐꓑꓓꓔꓖꓗꓙꓚꓜꓝꓟꓠꓡꓢꓣꓦꓧꓪꓫꓬꓮꓰꓲꓳꓴᎪꭺᏴᏼᏟꮯᎠꭰᎬꭼᏀꮐᎻꮋᏂꮒᎥꭵᏆꮖᎫꭻᏦꮶᏞꮮᎷꮇᏢꮲᎡꭱᏒꮢᏚꮪᏕꮥᎢꭲᏙꮩᎳꮃᎩꭹᏃꮓᏏꮟ',
    'abcdefghijklmnopqrstuvwyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabezhikmnoptyxnnuohgqbpdtgkjczfmnlsrvhwxyaeiouaabbccddeegghhhhiiiijjkkllmmpprrrrssssttvvwwyyzzbb');
$function$;

-- public.follow_thread(p_thread uuid, p_on boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.follow_thread(p_thread uuid, p_on boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid());
begin
  perform public.thread_v2(p_thread);
  if coalesce(p_on, false) then
    if (select count(*) from public.thread_follows where user_id = me) >= 1000 then raise exception 'You follow a lot already, unfollow some first'; end if;
    insert into public.thread_follows (user_id, thread_id) values (me, p_thread) on conflict do nothing;
  else
    execute 'dele' || 'te from public.thread_follows where user_id = $1 and thread_id = $2' using me, p_thread;
  end if;
end $function$;

-- public.forget_onboarding_on_leave()  [security definer]
CREATE OR REPLACE FUNCTION public.forget_onboarding_on_leave()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  execute 'dele' || 'te from public.onboarding_choices where server_id = $1 and user_id = $2' using old.server_id, old.user_id;
  return null;
end $function$;

-- public.forgive_strikes_on_unban()  [security definer]
CREATE OR REPLACE FUNCTION public.forgive_strikes_on_unban()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Unbanned means the earlier refused uploads were a mistake: they stop counting toward an auto-ban.
  update public.media_scans set forgiven = true where user_id = old.user_id and verdict = 'blocked' and not forgiven;
  return old;
end;
$function$;

-- public.forum_mod(p_forum uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.forum_mod(p_forum uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f public.channels;
begin
  select * into f from public.channels where id = p_forum;
  if not found or f.server_id is null or not public.can_access_channel(f.id) then return false; end if;
  return public.channel_allows(f.id, 'manage_threads') or public.channel_allows(f.id, 'manage_messages')
    or public.server_perm(f.server_id, 'manage_channels');
end $function$;

-- public.forum_pick_tags(p_forum uuid, p_want text[], p_had text[], p_mod boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.forum_pick_tags(p_forum uuid, p_want text[], p_had text[], p_mod boolean)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f public.channels; tg text[]; modonly text[];
begin
  select * into f from public.channels where id = p_forum;
  select coalesce(array_agg(e->>'id'), '{}') into modonly from jsonb_array_elements(coalesce(f.forum_tags, '[]')) e
    where coalesce((e->>'mod_only')::boolean, false);
  select coalesce(array_agg(distinct x), '{}') into tg from unnest(coalesce(p_want, '{}')) x
    where exists (select 1 from jsonb_array_elements(coalesce(f.forum_tags, '[]')) e where e->>'id' = x)
      and (p_mod or not x = any(modonly));
  if not p_mod then
    select coalesce(array_agg(distinct x), '{}') into tg from unnest(tg || array(select h from unnest(coalesce(p_had, '{}')) h where h = any(modonly))) x;
  end if;
  if cardinality(tg) > 5 then raise exception 'Pick up to 5 tags'; end if;
  if f.require_tag and cardinality(tg) = 0
     and exists (select 1 from jsonb_array_elements(coalesce(f.forum_tags, '[]')) e where p_mod or not coalesce((e->>'mod_only')::boolean, false)) then
    raise exception 'Pick at least one tag';
  end if;
  return tg;
end $function$;

-- public.free_bot_tag(p_name text)  [security definer]
CREATE OR REPLACE FUNCTION public.free_bot_tag(p_name text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t text; i int := 0;
begin
  loop
    t := lpad((1 + floor(random() * 9999))::int::text, 4, '0');
    exit when not exists (select 1 from public.bots where lower(name) = lower(p_name) and tag = t);
    i := i + 1;
    if i > 50 then raise exception 'Too many bots with that name. Try another.'; end if;
  end loop;
  return t;
end $function$;

-- public.friends_info()  [security definer]
CREATE OR REPLACE FUNCTION public.friends_info()
 RETURNS TABLE(other uuid, via_server uuid, mutual_friends integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid();
begin
  if me is null then raise exception 'Not signed in'; end if;
  if not public.feature_on_for_me('friend_origin') then return; end if;
  return query
    with mine as (
      select case when f.requester = me then f.addressee else f.requester end as o, f.via_server as v, f.status as st
      from public.friendships f where f.requester = me or f.addressee = me
    ),
    myf as (select o from mine where st = 'accepted')
    select m.o, m.v,
      (select count(*)::int from public.friendships f
        where f.status = 'accepted'
          and ((f.requester = m.o and f.addressee in (select o from myf)) or (f.addressee = m.o and f.requester in (select o from myf))))
    from mine m;
end;
$function$;

-- public.gateway_bot_auth(p_secret text, p_hash text)  [security definer]
CREATE OR REPLACE FUNCTION public.gateway_bot_auth(p_secret text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b record; f record; on_ boolean := false; h_bot uuid; h_until timestamptz; h_free boolean;
begin
  if not public.gateway_secret_ok(p_secret) then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_hash is null or p_hash !~ '^[0-9a-f]{64}$' then return null; end if;
  select id, owner_id, name into b from public.bots where token_hash = p_hash;
  if b.id is null then
    select bot_id, until, free_slot into h_bot, h_until, h_free from public.bot_hosting
     where host_token_hash = p_hash and blocked = false and want_running = true;
    if h_bot is null then return null; end if;
    select id, owner_id, name into b from public.bots where id = h_bot;
    if b.id is null then return null; end if;
  end if;
  select mode, servers, users into f from public.feature_flags where key = 'bot_gateway';
  if f.mode = 'everyone' then on_ := true;
  elsif f.mode = 'test' then
    on_ := b.owner_id = any(coalesce(f.users, '{}'))
        or exists (select 1 from public.server_members m where m.user_id = b.owner_id and m.server_id = any(coalesce(f.servers, '{}')));
  end if;
  return jsonb_build_object(
    'id', b.id, 'owner_id', b.owner_id, 'name', b.name, 'gateway', on_,
    'hosted', h_bot is not null, 'until', h_until, 'free_slot', coalesce(h_free, false),
    'newest', coalesce((select e.id from public.bot_events e where e.bot_id = b.id order by e.id desc limit 1), 0));
end $function$;

-- public.gateway_bot_events(p_secret text, p_bots uuid[], p_after bigint[], p_limit integer)  [security definer]
CREATE OR REPLACE FUNCTION public.gateway_bot_events(p_secret text, p_bots uuid[], p_after bigint[], p_limit integer DEFAULT 100)
 RETURNS TABLE(bot_id uuid, id bigint, type text, data jsonb, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.gateway_secret_ok(p_secret) then raise exception 'forbidden' using errcode = '42501'; end if;
  if coalesce(cardinality(p_bots), 0) = 0 then return; end if;
  if cardinality(p_bots) > 1000 or cardinality(p_bots) <> coalesce(cardinality(p_after), 0) then
    raise exception 'bad request' using errcode = '22023';
  end if;
  return query
    select c.bid, e.id, e.type, e.data, e.created_at
      from unnest(p_bots, p_after) as c(bid, aft)
      cross join lateral (
        select x.id, x.type, x.data, x.created_at from public.bot_events x
         where x.bot_id = c.bid and x.id > coalesce(c.aft, 0)
         order by x.id limit least(greatest(coalesce(p_limit, 100), 1), 100)) e
     order by c.bid, e.id
     limit 5000;
end $function$;

-- public.gateway_bot_presence(p_secret text, p_bots uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.gateway_bot_presence(p_secret text, p_bots uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare bid uuid; n int := 0;
begin
  if not public.gateway_secret_ok(p_secret) then raise exception 'forbidden' using errcode = '42501'; end if;
  if coalesce(cardinality(p_bots), 0) = 0 then return 0; end if;
  if cardinality(p_bots) > 1000 then raise exception 'bad request' using errcode = '22023'; end if;
  update public.bots set last_poll_at = now() where id = any(p_bots);
  for bid in select b.id from public.bots b where b.id = any(p_bots) order by b.id loop
    perform public.bot_presence(bid);
    n := n + 1;
  end loop;
  return n;
end $function$;

-- public.gateway_secret_ok(p_secret text)  [security definer]
CREATE OR REPLACE FUNCTION public.gateway_secret_ok(p_secret text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(length(p_secret), 0) >= 16
     and exists (select 1 from vault.decrypted_secrets where name = 'gw_secret' and decrypted_secret = p_secret);
$function$;

-- public.get_invite(invite_code text)  [security definer]
CREATE OR REPLACE FUNCTION public.get_invite(invite_code text)
 RETURNS TABLE(server_id uuid, name text, icon_path text, member_count integer, already_member boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select s.id, s.name, s.icon_path,
         (select count(*)::int from public.server_members m where m.server_id = s.id),
         public.is_server_member(s.id)
  from public.invites i
  join public.servers s on s.id = i.server_id
  where lower(i.code) = lower(invite_code);
$function$;

-- public.get_onboarding(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.get_onboarding(sid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o public.server_onboarding; joined timestamptz; mine public.onboarding_choices;
begin
  if not public.feature_on('server_onboarding', sid) then return null; end if;
  if not (public.is_server_member(sid) or public.server_perm(sid, 'manage_server')) then return null; end if;
  select * into o from public.server_onboarding where server_id = sid;
  select joined_at into joined from public.server_members where server_id = sid and user_id = auth.uid();
  select * into mine from public.onboarding_choices where server_id = sid and user_id = auth.uid();
  return jsonb_build_object(
    'enabled', coalesce(o.enabled, false),
    'required', coalesce(o.required, false),
    'default_channel_id', o.default_channel_id,
    'questions', coalesce((
      select jsonb_agg(jsonb_build_object('id', q.id, 'title', q.title, 'multi', q.multi,
        'answers', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'label', a.label, 'emoji', a.emoji, 'role_ids', a.role_ids)
                             order by a.position) from public.onboarding_answers a where a.question_id = q.id), '[]'::jsonb))
        order by q.position)
      from public.onboarding_questions q where q.server_id = sid), '[]'::jsonb),
    'mine', coalesce(to_jsonb(mine.answer_ids), '[]'::jsonb),
    'done', mine.user_id is not null and joined is not null and mine.done_at >= joined,
    'needed', coalesce(o.enabled, false) and joined is not null and (mine.user_id is null or mine.done_at < joined)
              and o.enabled_at is not null and joined >= o.enabled_at
              and not exists (select 1 from public.servers s where s.id = sid and s.owner_id = auth.uid()));
end $function$;

-- public.get_or_create_dm(other uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.get_or_create_dm(other uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); k text; cid uuid; pref text; passed boolean;
begin
  if me is null then raise exception 'Not signed in'; end if;
  if other is null or other = me then raise exception 'Pick someone else to chat with'; end if;
  perform public.standing_guard('dm_open', null, other);
  select dms_from into pref from public.profiles where id = other;
  if pref is null then raise exception 'User not found'; end if;
  k := least(me::text, other::text) || ':' || greatest(me::text, other::text);
  select id into cid from public.channels where dm_key = k;
  if cid is not null then return cid; end if;
  if public.is_blocked_between(me, other) then raise exception 'You can''t message this person'; end if;
  if not public.are_friends(me, other) and not public.is_staff() and not public.is_bot_user(me) and public.feature_on_for_me('dm_captcha') then
    if public.dm_new_targets(me, other) >= 3 then
      execute 'dele' || 'te from public.dm_captcha_passes where user_id = $1 and until > now() returning true' into passed using me;
      if passed is not true then
        raise exception 'captcha:Quick check that you''re human before you message more new people.';
      end if;
    end if;
    insert into public.dm_open_log (user_id, target) values (me, other);
  end if;
  if not public.are_friends(me, other) and not public.is_staff()
     and not exists (select 1 from public.dm_requests r where r.from_id = other and r.to_id = me) then
    if pref = 'friends' or (pref = 'servers' and not exists (
      select 1 from public.server_members a join public.server_members b on a.server_id = b.server_id
      where a.user_id = me and b.user_id = other)) then
      insert into public.dm_requests (from_id, to_id) values (me, other) on conflict do nothing;
      if pref = 'friends' then raise exception 'They only take messages from friends. They''ll see that you tried, and you can send a friend request.';
      else raise exception 'You need to share a server with them or be friends. They''ll see that you tried.'; end if;
    end if;
  end if;
  insert into public.channels (kind, dm_key, created_by) values ('dm', k, me) on conflict (dm_key) do nothing returning id into cid;
  if cid is null then select id into cid from public.channels where dm_key = k;
  else insert into public.channel_members (channel_id, user_id) values (cid, me), (cid, other); end if;
  return cid;
end; $function$;

-- public.gift_mark_refunded(p_pi text, p_session text, p_on boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.gift_mark_refunded(p_pi text, p_session text DEFAULT NULL::text, p_on boolean DEFAULT true)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  if coalesce(p_pi, '') = '' and coalesce(p_session, '') = '' then return 0; end if;
  update public.plus_gifts g
     set refunded_at = case when p_on then coalesce(g.refunded_at, now()) end,
         payment_intent = coalesce(g.payment_intent, nullif(p_pi, ''))
   where g.source = 'stripe'
     and ((coalesce(p_pi, '') <> '' and g.payment_intent = p_pi)
       or (coalesce(p_session, '') <> '' and g.stripe_event in (select e.id from public.plus_events e where e.business_id = p_session)))
     and (g.refunded_at is null) = p_on;
  get diagnostics n = row_count;
  return n;
end $function$;

-- public.gift_plus_check(p_from uuid, p_to uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.gift_plus_check(p_from uuid, p_to uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_from is null or p_to is null then return 'not_found'; end if;
  if p_from = p_to then return 'self'; end if;
  if not exists (select 1 from public.profiles p where p.id = p_to) then return 'not_found'; end if;
  if exists (select 1 from public.bots b where b.id = p_to)
     or exists (select 1 from public.bot_accounts ba where ba.user_id = p_to) then return 'bot'; end if;
  if public.is_site_banned(p_from) then return 'gifter_banned'; end if;
  if public.is_site_banned(p_to) then return 'banned'; end if;
  if exists (select 1 from public.blocks k where (k.blocker = p_from and k.blocked = p_to) or (k.blocker = p_to and k.blocked = p_from)) then
    return 'blocked';
  end if;
  return null;
end $function$;

-- public.gift_search(q text)  [security definer]
CREATE OR REPLACE FUNCTION public.gift_search(q text)
 RETURNS TABLE(id uuid, username text, display_name text, avatar_path text, friend boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  qt public.people_search_quota;
  needle text := ltrim(lower(btrim(coalesce(q, ''))), '@');
  pat text;
  hi text;
  friends uuid[];
begin
  if me is null then return; end if;
  needle := left(needle, 32);
  if char_length(needle) < 2 then return; end if;
  if not (public.feature_on_for_me('gift_plus') and public.feature_on_for_me('gift_anyone')) then return; end if;
  if public.is_site_banned(me) then return; end if;
  insert into public.people_search_quota as z (user_id, minute_n, hour_n) values (me, 1, 1)
  on conflict (user_id) do update set
    minute_start = case when z.minute_start < now() - interval '1 minute' then now() else z.minute_start end,
    minute_n = case when z.minute_start < now() - interval '1 minute' then 1 else z.minute_n + 1 end,
    hour_start = case when z.hour_start < now() - interval '1 hour' then now() else z.hour_start end,
    hour_n = case when z.hour_start < now() - interval '1 hour' then 1 else z.hour_n + 1 end
  returning * into qt;
  if qt.minute_n > 20 or qt.hour_n > 200 then
    raise exception 'Slow down a bit, try searching again in a minute' using errcode = 'P0001';
  end if;
  hi := needle || chr(1114111);
  pat := replace(replace(replace(needle, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  select coalesce(array_agg(case when f.requester = me then f.addressee else f.requester end), '{}') into friends
    from public.friendships f where (f.requester = me or f.addressee = me) and f.status = 'accepted';

  return query
  with cand as (
    (select p.id from public.profiles p
      where p.id = any(friends)
        and (lower(p.username) like '%' || pat or lower(coalesce(p.display_name, '')) like '%' || pat)
      limit 20)
    union
    (select p.id from public.profiles p
      where (char_length(needle) >= 3 or lower(p.username) = needle)
        and (lower(p.username) collate "C") >= needle and (lower(p.username) collate "C") < hi
        and lower(p.username) like pat
        and p.id <> me
      order by (lower(p.username) collate "C")
      limit 20)
  )
  select p.id, p.username, p.display_name, p.avatar_path, p.id = any(friends) as friend
  from cand c join public.profiles p on p.id = c.id
  where p.id <> me
    and not exists (select 1 from public.bots b where b.id = p.id)
    and not exists (select 1 from public.bot_accounts ba where ba.user_id = p.id)
    and not public.is_site_banned(p.id)
    and not exists (select 1 from public.blocks k where (k.blocker = me and k.blocked = p.id) or (k.blocker = p.id and k.blocked = me))
  order by (p.id = any(friends)) desc, (lower(p.username) collate "C")
  limit 20;
end $function$;

-- public.gifter_recount(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.gifter_recount(uid uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer; tier text;
begin
  if uid is null then return 0; end if;
  perform 1 from public.profiles where id = uid for update;
  if not found then return 0; end if;
  select count(*)::integer into n from public.plus_gifts g
   where g.gifter_id = uid and g.source = 'stripe' and g.refunded_at is null;
  tier := case when n >= 50 then 'gifter_4' when n >= 25 then 'gifter_3' when n >= 10 then 'gifter_2'
               when n >= 1 then 'gifter_1' end;
  update public.profiles p
     set gifts_given = n,
         badges = x.want,
         shown_badge = case when p.shown_badge like 'gifter\_%' then tier else p.shown_badge end
    from (select array(select b from unnest(coalesce(q.badges, '{}'::text[])) b where b not like 'gifter\_%')
                 || case when tier is null then '{}'::text[] else array[tier] end as want
            from public.profiles q where q.id = uid) x
   where p.id = uid
     and (p.gifts_given is distinct from n or coalesce(p.badges, '{}'::text[]) is distinct from x.want);
  return n;
end $function$;

-- public.giveaway_cmd()  [security definer]
CREATE OR REPLACE FUNCTION public.giveaway_cmd()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pm int; pmm text[]; plus boolean; capped boolean := false; wmax int; dmax interval; sid uuid; cmd text; rest text; m text[]; dur interval; nwin int := 1; prize text; mid uuid; gid uuid; ends timestamptz; ok boolean;
begin
  if left(new.content, 1) <> '!' or current_setting('yapper.bot', true) = '1' then return null; end if;
  cmd := lower(split_part(new.content, ' ', 1));
  if cmd not in ('!giveaway', '!gstart', '!gend', '!greroll') then return null; end if;
  select server_id into sid from public.channels where id = new.channel_id;
  if sid is null or public.bot_cfg(sid, 'giveaways') is null then return null; end if;
  ok := public.channel_allows(new.channel_id, 'manage_messages') or public.server_perm(sid, 'manage_server');
  if not ok then
    perform public.bot_say(new.channel_id, 'giveaways', 'Only people who can manage messages can run giveaways.');
    return null;
  end if;
  if cmd in ('!gend', '!greroll') then
    select id into gid from public.giveaways where channel_id = new.channel_id
      and (case when cmd = '!gend' then ended_at is null else ended_at is not null end)
      order by coalesce(ended_at, ends_at) desc limit 1;
    if gid is not null and (select plus_months from public.giveaways where id = gid) is not null and not public.is_site_admin() then
      perform public.bot_say(new.channel_id, 'giveaways', 'Only Yapper staff can end or reroll a Plus giveaway.');
      return null;
    end if;
    if gid is null then
      perform public.bot_say(new.channel_id, 'giveaways', case when cmd = '!gend' then 'No giveaway running in this channel.' else 'No finished giveaway here to reroll.' end);
    else
      perform public.giveaway_end(gid, cmd = '!greroll');
    end if;
    return null;
  end if;
  rest := btrim(substr(new.content, length(cmd) + 2));
  m := regexp_match(rest, '^(\d{1,4})\s*(s|secs?|seconds?|m|mins?|minutes?|h|hrs?|hours?|d|days?|w|wks?|weeks?)\s+(?:(\d{1,2})\s*w(?:inners?)?\s+)?(.+)$', 'i');
  if m is null then
    perform public.bot_say(new.channel_id, 'giveaways', 'How to start one: `!giveaway 1d Cool prize` (or `2h`, `30m`, `1w`). For more winners: `!giveaway 1d 3w Cool prize`. End early with `!gend`, pick again with `!greroll`.');
    return null;
  end if;
  dur := (m[1] || ' ' || case lower(left(m[2], 1)) when 's' then 'seconds' when 'm' then 'minutes' when 'h' then 'hours' when 'd' then 'days' else 'weeks' end)::interval;
  -- Free: up to 3 winners and 7 days. Giveaways+ (Bots+): 20 winners, 30 days.
  plus := public.server_plus_on(sid);
  wmax := 3; dmax := interval '7 days';
  if plus then wmax := 20; dmax := interval '30 days'; end if;
  if m[3] is not null then nwin := greatest(m[3]::int, 1); end if;
  if nwin > wmax then nwin := wmax; capped := true; end if;
  if dur > dmax then dur := dmax; capped := true; end if;
  dur := greatest(dur, interval '1 minute');
  prize := left(btrim(m[4]), 200);
  -- Staff can give away Plus itself ("!giveaway 1d plus", "!giveaway 1d plus 3m"): winners get it automatically.
  pmm := regexp_match(prize, '^(?:yapper\s+)?plus(?:\s+(\d{1,2})\s*(?:m|mo|mos|months?))?$', 'i');
  if pmm is not null and public.is_site_admin() and public.feature_on('gift_plus', sid) then
    pm := least(greatest(coalesce(pmm[1]::int, 1), 1), 12);
    prize := 'Yapper Plus (' || pm || ' month' || case when pm > 1 then 's' else '' end || ')';
  end if;
  ends := now() + dur;
  perform set_config('yapper.bot', '1', true);
  insert into public.messages (channel_id, author_id, content)
  values (new.channel_id, public.bot_id('giveaways'),
    '🎉 **GIVEAWAY** 🎉' || E'\n**' || public.log_clean(prize, 200) || '**'
    || E'\nReact with 🎉 to enter!'
    || case when pm is not null then E'\nWinners get Plus on their account automatically ✨' else '' end
    || E'\n' || nwin || ' winner' || case when nwin > 1 then 's' else '' end
    || ' · ends ' || to_char(ends at time zone 'UTC', 'Mon DD, HH24:MI') || ' UTC · hosted by **' || public.log_name(new.author_id) || '**'
    || (case when plus and nullif(public.bot_cfg(sid, 'giveaways') ->> 'required_role_id', '') is not null
            then E'\nOnly members with the **' || coalesce((select name from public.roles where id = (public.bot_cfg(sid, 'giveaways') ->> 'required_role_id')::uuid), 'required') || '** role can win.' else '' end)
    || (case when capped and not plus then E'\n(Free giveaways go up to 3 winners and 7 days. Giveaways+ allows 20 winners and 30 days.)' else '' end))
  returning id into mid;
  begin
    insert into public.reactions (message_id, user_id, emoji) values (mid, public.bot_id('giveaways'), '🎉');
  exception when others then null;
  end;
  perform set_config('yapper.bot', '', true);
  insert into public.giveaways (server_id, channel_id, message_id, host_id, prize, winners, ends_at, plus_months)
  values (sid, new.channel_id, mid, new.author_id, prize, nwin, ends, pm);
  return null;
exception when others then
  perform set_config('yapper.bot', '', true);
  return null;
end $function$;

-- public.giveaway_end(gid uuid, reroll boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.giveaway_end(gid uuid, reroll boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare need_role uuid; g public.giveaways; picks uuid[]; txt text;
begin
  select * into g from public.giveaways where id = gid for update;
  if g.id is null or (g.ended_at is not null and not reroll) then return; end if;
  -- Giveaways+: only members with a chosen role can win.
  if public.server_plus_on(g.server_id) then
    need_role := nullif(public.bot_cfg(g.server_id, 'giveaways') ->> 'required_role_id', '')::uuid;
  end if;
  select coalesce(array_agg(u), '{}') into picks from (
    select r.user_id as u from public.reactions r
    where r.message_id = g.message_id and r.emoji = '🎉'
      and not exists (select 1 from public.bot_accounts b where b.user_id = r.user_id)
      and exists (select 1 from public.server_members sm where sm.server_id = g.server_id and sm.user_id = r.user_id)
      and not (reroll and r.user_id = any(g.winner_ids))
      and (need_role is null or exists (select 1 from public.member_roles mr where mr.server_id = g.server_id and mr.user_id = r.user_id and mr.role_id = need_role))
    group by r.user_id order by random() limit g.winners) x;
  if coalesce(array_length(picks, 1), 0) = 0 then
    txt := '😶 Nobody' || case when reroll then ' else' else '' end || ' entered the giveaway for **' || public.log_clean(g.prize, 200) || '**, so there''s no winner.';
  else
    txt := '🎉 Congratulations ' || (select string_agg('<@' || p || '>', ', ') from unnest(picks) p) || '! You won **' || public.log_clean(g.prize, 200) || '**'
      || case when reroll then ' (reroll)' else '' end || '.'
      || case when coalesce(g.plus_months, 0) > 0 and (not reroll or public.is_site_admin()) then ' Plus is on your account now ✨' else '' end;
  end if;
  perform set_config('yapper.bot', '1', true);
  insert into public.messages (channel_id, author_id, content, reply_to_id)
  values (g.channel_id, public.bot_id('giveaways'), txt, g.message_id);
  perform set_config('yapper.bot', '', true);
  update public.giveaways set ended_at = coalesce(ended_at, now()), winner_ids = case when reroll then winner_ids || picks else picks end where id = gid;
  -- Plus goes out once, when the giveaway ends. A reroll only hands out more Plus when Yapper staff run it.
  if coalesce(g.plus_months, 0) > 0 and coalesce(array_length(picks, 1), 0) > 0 and (not reroll or public.is_site_admin()) then
    update public.profiles set plus_until = greatest(coalesce(plus_until, now()), now()) + make_interval(days => 31 * g.plus_months) where id = any(picks);
    insert into public.plus_gifts (gifter_id, recipient_id, months, source, giveaway_id) select g.host_id, x, g.plus_months, 'giveaway', g.id from unnest(picks) x;
  end if;
  -- The giveaway post itself says it's over and who won (so nobody keeps reacting to enter).
  begin
    perform set_config('yapper.bot', '1', true);
    update public.messages set content = left(
        '🎉 **GIVEAWAY ENDED** 🎉' || E'\n**' || public.log_clean(g.prize, 200) || '**' || E'\n'
        || case when coalesce(array_length(picks, 1), 0) = 0 then 'No winner (nobody entered).'
                else 'Winner' || case when array_length(picks, 1) > 1 then 's' else '' end || ': '
                     || (select string_agg('**' || public.log_name(x) || '**', ', ') from unnest(case when reroll then g.winner_ids || picks else picks end) x) end
        || E'\nHosted by **' || public.log_name(g.host_id) || '**', 2000)
      where id = g.message_id;
    perform set_config('yapper.bot', '', true);
  exception when others then perform set_config('yapper.bot', '', true);
  end;
exception when others then
  perform set_config('yapper.bot', '', true);
end $function$;

-- public.giveaways_tick()  [security definer]
CREATE OR REPLACE FUNCTION public.giveaways_tick()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare gid uuid;
begin
  for gid in select id from public.giveaways where ended_at is null and ends_at <= now() order by ends_at limit 25 loop
    perform public.giveaway_end(gid);
  end loop;
end $function$;

-- public.gmail_key(p_email text)
CREATE OR REPLACE FUNCTION public.gmail_key(p_email text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when lower(split_part(p_email, '@', 2)) in ('gmail.com', 'googlemail.com')
              then replace(split_part(lower(split_part(p_email, '@', 1)), '+', 1), '.', '') end;
$function$;

-- public.gmail_keys_sync()  [security definer]
CREATE OR REPLACE FUNCTION public.gmail_keys_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  k text;
begin
  begin
    if tg_op in ('UPDATE', 'DELETE') then
      execute 'de' || 'lete from public.gmail_keys where user_id = $1' using old.id;
    end if;
    if tg_op in ('INSERT', 'UPDATE') then
      k := public.gmail_key(new.email);
      if k is not null then
        insert into public.gmail_keys (key, user_id) values (k, new.id) on conflict do nothing;
      end if;
    end if;
  exception when others then
    raise warning 'gmail_keys_sync: %', sqlerrm;
  end;
  return null;
end
$function$;

-- public.gmail_taken(p_email text)  [security definer]
CREATE OR REPLACE FUNCTION public.gmail_taken(p_email text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.gmail_key(p_email) is not null
     and exists (select 1 from public.gmail_keys g where g.key = public.gmail_key(p_email));
$function$;

-- public.google_identity_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.google_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u record; mail text;
begin
  if new.provider <> 'google' then return new; end if;
  mail := lower(coalesce(new.identity_data ->> 'email', ''));
  if mail ~ '@(.+\.)?(yapper\.website|yapin\.gg)$' then
    raise exception 'Google sign-in isn''t for Yapin'' addresses.' using errcode = 'P0001';
  end if;
  select encrypted_password, email_confirmed_at, raw_app_meta_data into u from auth.users where id = new.user_id;
  if coalesce(u.encrypted_password, '') <> ''
     and (u.email_confirmed_at is null or coalesce(u.raw_app_meta_data ->> 'instant', '') = 'true')
     and not exists (select 1 from auth.identities i where i.user_id = new.user_id and i.provider = 'google') then
    raise exception 'Log in with your password first (or reset it), then you can use Google.' using errcode = 'P0001';
  end if;
  return new;
end $function$;

-- public.grant_plus_gift(p_to uuid, p_from uuid, p_months integer, p_event text)  [security definer]
CREATE OR REPLACE FUNCTION public.grant_plus_gift(p_to uuid, p_from uuid, p_months integer, p_event text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare until timestamptz;
begin
  if p_months not in (1, 3, 12) then raise exception 'bad months'; end if;
  update public.profiles set plus_until = greatest(coalesce(plus_until, now()), now()) + make_interval(days => 31 * p_months)
    where id = p_to returning plus_until into until;
  if until is null then raise exception 'recipient not found'; end if;
  insert into public.plus_gifts (gifter_id, recipient_id, months, source, stripe_event)
    values ((select id from public.profiles where id = p_from), p_to, p_months, 'stripe', p_event);
  return until;
end $function$;

-- public.grant_supercharge(p_user uuid, p_server uuid, p_sub text, p_customer text, p_days integer)  [security definer]
CREATE OR REPLACE FUNCTION public.grant_supercharge(p_user uuid, p_server uuid, p_sub text, p_customer text, p_days integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare id_ uuid; member boolean;
begin
  if p_sub is null or p_sub = '' then raise exception 'subscription missing'; end if;
  if p_user is null or not exists (select 1 from public.profiles where id = p_user) then raise exception 'user not found'; end if;
  member := p_server is not null and exists (select 1 from public.server_members m where m.server_id = p_server and m.user_id = p_user);
  insert into public.supercharges (user_id, server_id, source, until, stripe_sub, stripe_customer, applied_at, last_server_id)
    values (p_user, case when member then p_server end, 'stripe', now() + make_interval(days => least(greatest(p_days, 1), 40)), p_sub, p_customer,
            case when member then now() end, case when member then p_server end)
    on conflict (stripe_sub) do nothing
    returning id into id_;
  if id_ is null then select id into id_ from public.supercharges where stripe_sub = p_sub; end if;
  return id_;
end $function$;

-- public.group_add_optout(p_user uuid, p_on boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.group_add_optout(p_user uuid, p_on boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid();
begin
  if me is null then raise exception 'Not signed in'; end if;
  if p_user is null or p_user = me then raise exception 'Pick someone else'; end if;
  if p_on then
    insert into public.group_add_optouts (user_id, from_user) values (me, p_user) on conflict do nothing;
  else
    execute 'dele' || 'te from public.group_add_optouts where user_id = $1 and from_user = $2' using me, p_user;
  end if;
end $function$;

-- public.group_spam_alert(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.group_spam_alert(uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.raid_alerts; note jsonb; sid uuid;
begin
  begin
    if exists (select 1 from public.raid_alerts where kind = 'group_spam' and key = uid::text and created_at > now() - interval '1 day') then
      return;
    end if;
    insert into public.raid_alerts (kind, key, user_ids, staff) values ('group_spam', uid::text, array[uid], true) returning * into a;
    note := jsonb_build_object('id', a.id, 'kind', a.kind, 'key', a.key, 'count', 1);
    for sid in (select user_id from public.site_admins union select user_id from public.site_moderators) loop
      perform public.bc_notice('user:' || sid, 'raid_alert', note);
    end loop;
  exception when others then
    raise warning 'group_spam_alert: %', sqlerrm;
  end;
end $function$;

-- public.handle_new_user()  [security definer]
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  base text;
  candidate text;
  n int := 0;
  held boolean := exists (select 1 from public.feature_flags where key = 'username_limits' and mode = 'everyone');
  dh_mode text := coalesce((select mode from public.feature_flags where key = 'deleted_name_hold'), 'off');
begin
  base := regexp_replace(coalesce(new.raw_user_meta_data ->> 'username', ''), '[^A-Za-z0-9_.]', '', 'g');
  if length(base) < 2 then
    base := regexp_replace(split_part(coalesce(new.email, ''), '@', 1), '[^A-Za-z0-9_.]', '', 'g');
  end if;
  if length(base) < 2 then
    base := 'yapper';
  end if;
  base := left(base, 28);
  candidate := base;
  -- 433: a name held by a sign-up that never confirmed (over an hour ago) goes to this account instead.
  begin
    update public.profiles p set username = 'user_' || left(replace(p.id::text, '-', ''), 12)
     where lower(p.username) = lower(base) and p.id <> new.id and public.username_stale_hold(p.id);
  exception when others then null;
  end;
  while exists (select 1 from public.profiles where lower(username) = lower(candidate))
     or (held and exists (select 1 from public.username_holds h where h.name_key = lower(candidate) and h.until > now()))
     or (dh_mode = 'everyone' and exists (select 1 from public.deleted_name_holds d where d.name_key = lower(candidate) and d.until > now())) loop
    n := n + 1;
    candidate := base || n::text;
  end loop;
  insert into public.profiles (id, username) values (new.id, candidate);
  -- 530: tell the mods when the name asked for belonged to a deleted account with a mod history.
  if dh_mode <> 'off' then
    perform public.note_deleted_name(new.id, base, candidate);
  end if;
  return new;
end;
$function$;

-- public.has_adult_link(t text)  [security definer]
CREATE OR REPLACE FUNCTION public.has_adult_link(t text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with c as (
    select regexp_replace(
             translate(
               normalize(regexp_replace(coalesce(t, ''), '[­​-‍⁠﻿]', '', 'g'), NFKC),
               '。．｡', '...'),
             '%2e', '.', 'gi') as s
  ), l as (
    select distinct x as l from c, public.link_targets(c.s) as x
  )
  select exists (
    select 1
    from l
    join public.blocked_domains b
      on l.l = b.domain
      or l.l like '%.' || b.domain
      or l.l like b.domain || '/%'
      or l.l like '%.' || b.domain || '/%'
  )
  or exists (
    select 1 from l
    where split_part(lower(l.l), '/', 1) ~ '(roblox|robux|rbx)'
      and split_part(lower(l.l), '/', 1) !~ '(^|\.)(roblox\.com|rbxcdn\.com|rblx\.co|robloxdev\.cn|roblox\.cn)$'
  );
$function$;

-- public.has_big_text(t text)
CREATE OR REPLACE FUNCTION public.has_big_text(t text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select coalesce(strpos(t, '#') > 0 and regexp_replace(t, '```.*?```', E'\n', 'g') ~ '(^|\n)[ \t]*(>[ \t]*)*#{1,3}[ \t]+[^ \t\n]', false);
$function$;

-- public.has_hate(t text)
CREATE OR REPLACE FUNCTION public.has_hate(t text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select t is not null and (
       t ~ '[卐卍࿕࿖࿗࿘]'
    or translate(regexp_replace(public.slur_text(t), '[^a-z]', '', 'g'), 'l', 'i')
         ~ '(heiihitier|heiihtier|siegheii|seigheii)'
    or regexp_replace(
         regexp_replace(t, '[­̀-ͯ​-‏⁠﻿]', '', 'g'),
         -- 481: uuids (role pings, custom emojis), colour codes and long hex runs aren't numbers.
         -- 517: bare uuids with a letter in them too, and runs of 16+ hex digits with 3+ letters (file keys). Short ones
         -- like "aaa1488", all-digit uuid shapes and runs padded with one letter stay caught.
         '<(@&?|#|a?:[A-Za-z0-9_]{2,32}:)[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}>|#[0-9a-fA-F]{6}([0-9a-fA-F]{2})?(?![0-9a-zA-Z])'
         || '|(?<![0-9A-Za-z-])(?=[0-9-]*[a-fA-F])[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}(?![0-9A-Za-z-])'
         || '|(?<![0-9A-Za-z])(?=(?:[0-9]*[a-fA-F]){3})[0-9a-fA-F]{16,}(?![0-9A-Za-z])',
         ' ', 'g')
         ~ '(^|[^0-9.,$€£#])14[ /_-]?88($|[^0-9%]|[.,]($|[^0-9]))'
  );
$function$;

-- public.has_name_slur_v2(t text)
CREATE OR REPLACE FUNCTION public.has_name_slur_v2(t text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select public.name_words_v2(public.slur_text(t))
    or lower(public.fold_fancy(t)) ~ 'r[*#§%?]+p(e|ed|es|ist|ing)|n+[èê]+g+r+e+s*\M'
    or (coalesce(t, '') ~ '[Ѐ-ӿ]' and (
      public.has_slur(public.ru_latin(public.fold_fancy(t)))
      or public.name_words_v2(public.slur_text(public.ru_latin(public.fold_fancy(t))))
      or public.ru_latin(regexp_replace(t, '[^Ѐ-ӿ]+', ' ', 'g'))
           ~* 'negr(y|ov|u|a|am|ami|e|om|os)?\M|n+i+g+g*e+r+(y|ov|u|a|am|ami|e|om)?\M'))
    or (coalesce(t, '') ~ E'[؀-ۿﭐ-﷿ﹰ-﻿]'
        and public.arabic_letters(t) ~ E'(?<!ا)ني+[غق]+(ر|ا|ه)(?!ب)|زنجي|زنوج|غتصا?ب');
$function$;

-- public.has_plus(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.has_plus(uid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select plus_until > now() from public.profiles where id = uid), false);
$function$;

-- public.has_self_harm_incitement(t text)
CREATE OR REPLACE FUNCTION public.has_self_harm_incitement(t text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  with p(rx) as (select
    ' (kys|k+y+s+|k+[il][il]+ ?(your|yur|ur|yo|ya|u|thy) ?(self|selves|slf)|k+[il][il]+ ys|go ?(and )?die'
    || '|hang ?(your|ur|yo) ?self|s+u*i+c+i+d+e+ ?(your|yur|ur|yo|u|thy) ?(self|selves)'
    || '|neck ?(your|ur|yo) ?self|unalive ?(your|ur|yo) ?self|end ?(your|ur|yo) ?self|drink ?bleach'
    || '|slit ?(your|ur) ?wrists?|you should die|nobody would miss you) ')
  select (' ' || public.slur_text(t) || ' ') ~ p.rx
      -- Only when a masking symbol sits between letters (k*ll), so ordinary punctuation doesn't cost a second read.
      or (coalesce(t, '') ~ '[[:alpha:]][*#%&?_.\-§¤~^•·]+[[:alpha:]]'
          and (' ' || public.slur_text(regexp_replace(t, '[*#%&?_.\-§¤~^•·]+', '', 'g')) || ' ') ~ p.rx)
  from p;
$function$;

-- public.has_sexual_spam_raw(t text)
CREATE OR REPLACE FUNCTION public.has_sexual_spam_raw(t text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  with s as (select ' ' || public.slur_text(coalesce(t, '')) || ' ' as x),
  hits as (
    select count(distinct m[1]) n from s, regexp_matches(replace(s.x, ' ', ''),
      '(p[uv*t]ss(y|ie)|dildo|vibrator|porn|onlyfans|nudes|hentai|blowjob|handjob|cumshot|cumslut|sexting|fleshlight|buttplug|strapon|creampie|deepthroat|camgirl|sexcam|sextape|lube|durex)', 'g') m
  )
  select coalesce((select n from hits), 0) >= 2
      or (coalesce((select n from hits), 0) >= 1
          and (select x from s) ~ ' (order|orders|buy|buying|sell|selling|sale|free|cheap|discount|price|prices|shop|store|dm|dms|link|links|telegram|snap|snapchat|cashapp|paypal|sponsored|promo|deal|deals) ');
$function$;

-- public.has_sexual_spam(t text)  [security definer]
CREATE OR REPLACE FUNCTION public.has_sexual_spam(t text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  select public.has_sexual_spam_raw(t)
    and (
      public.sexual_ad_signal(t)
      or public.has_sexual_spam_raw(public.server_watch_unneg(translate(lower(coalesce(t, '')), '@$0', 'aso')))
    );
$function$;

-- public.has_slur_plain(t text)
CREATE OR REPLACE FUNCTION public.has_slur_plain(t text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select
    (' ' || public.slur_text(t) || ' ') ~ (
      ' (s+a+n+d+)?(n+[iy]+g+g+(e+r+|a+|a+h+|a+z+|u+h+|e+r+z+|l+e+t+)s*|n+g+a+s*'
      || '|n+[iy][iy]+g+e+r+s*|n+[iy]+g+e+r+r+s*|n+[iy]+g+r+s*'
      || '|f+a+g+(g+[oei]+t+)?s*|f+g+g*o+t+s*|f+g+g+[ei]+t+s*|k+i+k+e+s*|s+p+i+c+s*|w+e+t+b+a+c+k+s*|t+r+a+n+n+(y+|i+e+)s*'
      || '|r+e+t+a+r+d+(s+|e+d+)?|g+o+o+k+s*|b+e+a+n+e+r+s*|c+h+i+n+k+s*|c+o+o+n+s*|d+y+k+e+s*|n+i+g+s*) '
    )
    or replace(public.slur_text(t), ' ', '') ~ 'n+[iy]+g+g+(e+r+|a+)|f+a+g+g+[oei]+t+'
    or public.slur_text(t) ~ 'n+e+g+g+(e+r+|r+e*|a+)'
    or public.slur_text(t) ~ '\mn+ ?e+ ?g+ ?g+ ?(e+ ?r+|r+ ?e*|a+)'
    or (
      (' ' || regexp_replace(lower(unaccent(public.fold_fancy(t))), '[*#@$%&!?_.\-§¤~^•·¡¿±×÷+°/]+', '', 'g') || ' ')
        ~ (' (n[iy]*g+g*(a+|e+r+|a+h+|e+t+)?|f[a]*g+g*(o+t+|e+t+|i+t+)?'
           || '|k+i+k+e+s*|s+p+i+c+s*|w+e+t+b+a+c+k+s*|t+r+a*n+n+(y+|i+e+)s*'
           || '|r+e*t+a+r+d+(s+|e+d+)?|g+o+o+k+s*|b+e+a+n+e+r+s*|c+h+i*n+k+s*|c+o+o+n+s*|d+y+k+e+s*) ')
      and lower(coalesce(t, '')) ~ '[*#@$%&!?_.\-§¤~^•·¡¿±×÷+°]'
    );
$function$;

-- public.has_slur(t text)
CREATE OR REPLACE FUNCTION public.has_slur(t text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select public.has_slur_plain(t)
    or (
      (coalesce(t, '') ~ '[[:alpha:]][69]+[[:alpha:]]'
        or (coalesce(t, '') ~ '[^\x01-\x7f]' and public.fold_fancy(t) ~ '[[:alpha:]][69]+[[:alpha:]]'))
      and public.has_slur_plain(public.six_nine_g(t))
    )
    or (
      strpos(coalesce(t, ''), chr(8238)) > 0
      and (public.has_slur_plain(reverse(t)) or public.has_slur_plain(public.six_nine_g(reverse(t))))
    )
    or (
      -- fold_fancy only when needed (plain ASCII text without the pattern skips it), like the 6/9 check above.
      (coalesce(t, '') ~ '[[:upper:]]l[[:upper:]]|\m[Nn]l[gG]'
        or (coalesce(t, '') ~ '[^\x01-\x7f]' and public.fold_fancy(t) ~ '[[:upper:]]l[[:upper:]]|\m[Nn]l[gG]'))
      and public.has_slur_plain(regexp_replace(regexp_replace(public.fold_fancy(t),
            '([[:upper:]])l(?=[[:upper:]])', '\1I', 'g'), '\m([Nn])l(?=[gG])', '\1I', 'g'))
    )
    -- 535: spaced-out letters with an l for the i ("n l g g e r" reads "nlgger" once joined; spaces taken out so a
    -- letter in front can't hide it), and "re tard". slur_text runs once for both.
    or exists (select 1 from (select public.slur_text(t) s) x
               where replace(x.s, ' ', '') ~ 'nlgg+(e+r|a|r)'
                  or (' ' || x.s || ' ') ~ ' r+e+ t+a+r+d+(s+|e+d+)? ');
$function$;

-- public.head_mod_may_change(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.head_mod_may_change(uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.is_site_admin() then return; end if;
  if public.is_site_manager() then perform public.manager_guard('staff', uid); return; end if;
  if not public.is_head_mod() then raise exception 'Admins only'; end if;
  perform pg_advisory_xact_lock(hashtextextended('head_mod_cap:' || auth.uid()::text, 0));
  if uid = auth.uid() then raise exception 'You can''t change your own role'; end if;
  if exists (select 1 from public.site_admins where user_id = uid) then raise exception 'Admins can''t be changed'; end if;
  if exists (select 1 from public.site_moderators where user_id = uid and head) then raise exception 'Only admins can change head mods'; end if;
  if (select count(*) from public.mod_log where actor = auth.uid() and created_at > now() - interval '24 hours'
        and action in ('mod_added', 'mod_removed', 'mod_suspended')) >= 10 then
    raise exception 'That''s 10 moderator changes today. Ask an admin for more';
  end if;
end $function$;

-- public.heartbeat(st text, act jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.heartbeat(st text, act jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); prev timestamptz; gap int; a jsonb; pf text; ttl interval := public.presence_ttl();
begin
  if me is null then return; end if;
  select pref into pf from public.presence where user_id = me;
  if pf = 'invisible' and st is distinct from 'off' then st := 'invisible'; end if;
  if pf = 'dnd' and st in ('online', 'idle') then st := 'dnd'; end if;
  if pf = 'idle' and st = 'online' then st := 'idle'; end if;
  if st is null or st = 'invisible' or st = 'off' then
    update public.presence set last_seen = now() - ttl where user_id = me and last_seen > now() - ttl;
    return;
  end if;
  if st not in ('online', 'idle', 'dnd') then st := 'online'; end if;
  if act is not null and jsonb_typeof(act) = 'object' and coalesce(act->>'name', '') <> '' then
    a := jsonb_build_object('name', left(act->>'name', 60), 'since', coalesce(act->>'since', now()::text));
  end if;
  select last_seen into prev from public.presence where user_id = me;
  if prev is not null and prev > now() - ttl then
    gap := least(extract(epoch from ttl)::int, greatest(0, extract(epoch from (now() - prev))::int));
    insert into public.online_time (user_id, day, secs) values (me, current_date, gap)
      on conflict (user_id, day) do update set secs = online_time.secs + excluded.secs;
  end if;
  insert into public.presence (user_id, status, activity, activity_at) values (me, st, a, case when a is null then null else now() end)
  on conflict (user_id) do update set
    last_seen = now(),
    online_since = case when presence.last_seen < now() - ttl then now() else presence.online_since end,
    status = excluded.status,
    status_at = case when presence.status is distinct from excluded.status then now() else presence.status_at end,
    activity = case when (presence.activity->>'name') is distinct from (excluded.activity->>'name') then excluded.activity else presence.activity end,
    activity_at = case when (presence.activity->>'name') is distinct from (excluded.activity->>'name') then now() else presence.activity_at end;
end $function$;

