$function$;

-- public.interest_ok(p_user uuid, p_source text)  [security definer]
CREATE OR REPLACE FUNCTION public.interest_ok(p_user uuid, p_source text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when p_source = 'steam'
    then exists (select 1 from public.steam_links s where s.user_id = p_user and s.games_public
                 and not coalesce((s.prefs ->> 'hidden')::boolean, false)
                 and coalesce((s.prefs ->> 'show_games')::boolean, true))
    else exists (select 1 from public.media_links l where l.user_id = p_user and l.source = p_source and l.is_public
                 and (l.source <> 'lastfm' or l.verified)
                 and not coalesce((l.prefs ->> 'hidden')::boolean, false))
  end;
$function$;

-- public.invite_apply_info(invite_code text)  [security definer]
CREATE OR REPLACE FUNCTION public.invite_apply_info(invite_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare i public.invites; r public.server_join_requests; apply boolean;
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  select * into i from public.invites where lower(code) = lower(invite_code);
  if i.code is null then return null; end if;
  apply := public.join_apply_on(i.server_id) and not i.skip_apply and not public.is_staff()
    and not exists (select 1 from public.servers where id = i.server_id and owner_id = auth.uid());
  select * into r from public.server_join_requests where server_id = i.server_id and user_id = auth.uid();
  return jsonb_build_object(
    'apply', apply,
    'questions', coalesce((select join_questions from public.servers where id = i.server_id), '{}'),
    'request', case when r.id is null then null else jsonb_build_object(
      'id', r.id, 'status', r.status, 'note', r.note, 'created_at', r.created_at, 'decided_at', r.decided_at,
      'retry_at', case when r.status = 'declined' then r.decided_at + interval '24 hours' end) end);
end $function$;

-- public.invite_card(invite_code text)  [security definer]
CREATE OR REPLACE FUNCTION public.invite_card(invite_code text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'server_id', s.id, 'name', s.name, 'icon_path', s.icon_path,
    'banner_path', s.banner_path, 'banner_x', s.banner_x, 'banner_y', s.banner_y, 'banner_zoom', s.banner_zoom,
    'created_at', s.created_at,
    'member_count', (select count(*) from public.server_members m where m.server_id = s.id),
    'online_count', (select count(*) from public.server_members m join public.presence p on p.user_id = m.user_id
                     where m.server_id = s.id and p.last_seen > now() - public.presence_ttl()),
    'already_member', exists (select 1 from public.server_members m where m.server_id = s.id and m.user_id = auth.uid()),
    'partner', s.partner_since is not null
  )
  from public.invites i join public.servers s on s.id = i.server_id
  where lower(i.code) = lower(invite_code);
$function$;

-- public.invite_random_code()
CREATE OR REPLACE FUNCTION public.invite_random_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  chars constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789';
  b bytea := uuid_send(gen_random_uuid()) || uuid_send(gen_random_uuid());
  c text := '';
  i int;
begin
  if coalesce(new.vanity, false) then return new; end if;
  for i in 0..9 loop
    c := c || substr(chars, 1 + get_byte(b, i * 3 + 1) % length(chars), 1);
  end loop;
  new.code := c;
  return new;
end;
$function$;

-- public.invites_only_in_promo()  [security definer]
CREATE OR REPLACE FUNCTION public.invites_only_in_promo()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ch record; last_at timestamptz; mark timestamptz; icode text; sid uuid; sids uuid[] := '{}'; nlinks int; ncodes int := 0;
begin
  if new.content !~* '((?:yapper\.website|yapin\.gg)/invite/|discord\.gg/|discord(app)?\.com/invite/|t\.me/|guilded\.gg/)' then return new; end if;
  -- An edit that keeps the same invite links (fixing the text around them) isn't a new invite post.
  if tg_op = 'UPDATE' and not exists (
       select 1 from regexp_matches(new.content, '(?:(?:yapper\.website|yapin\.gg)/invite/|discord\.gg/|discord(?:app)?\.com/invite/|t\.me/|guilded\.gg/)[^\s<>()]*', 'gi') n
       where lower(n[1]) not in (
         select lower(o[1]) from regexp_matches(coalesce(old.content, ''), '(?:(?:yapper\.website|yapin\.gg)/invite/|discord\.gg/|discord(?:app)?\.com/invite/|t\.me/|guilded\.gg/)[^\s<>()]*', 'gi') o)) then
    return new;
  end if;
  select c.name, c.server_id into ch from public.channels c where c.id = coalesce((select t.parent_id from public.channels t where t.id = new.channel_id), new.channel_id); /* 593: */
  if ch.server_id is null or ch.server_id <> (select default_server_id from public.app_settings limit 1) or public.is_staff() then return new; end if;
  if ch.name !~* 'promot' then
    raise exception 'Invite links only go in #promote-your-server.' using errcode = 'check_violation';
  end if;

  -- Each Yapper invite: a real one, for a live server you are in, not promoted in the last 6 hours.
  nlinks := (select count(*) from regexp_matches(new.content, '(?:yapper\.website|yapin\.gg)/invite/', 'gi'));
  for icode in select m[1] from regexp_matches(new.content, '(?:yapper\.website|yapin\.gg)/invite/([A-Za-z0-9_-]+)', 'gi') m loop
    ncodes := ncodes + 1;
    select i.server_id into sid from public.invites i where lower(i.code) = lower(icode) limit 1;
    if sid is null then
      raise exception 'That Yapper invite link doesn''t work. Copy a fresh one from your server.' using errcode = 'check_violation';
    end if;
    if exists (select 1 from public.servers s where s.id = sid and s.shut_down_at is not null) then
      raise exception 'That server can''t be promoted.' using errcode = 'check_violation';
    end if;
    if not exists (select 1 from public.server_members sm where sm.server_id = sid and sm.user_id = new.author_id) then
      raise exception 'You can only promote a server you are in.' using errcode = 'check_violation';
    end if;
    sids := sids || sid;
  end loop;
  -- A link whose code isn't plain letters, numbers, _ or - (a percent-encoded one, say) can't be checked: refuse it.
  if ncodes <> nlinks then
    raise exception 'That Yapper invite link doesn''t work. Copy a fresh one from your server.' using errcode = 'check_violation';
  end if;
  -- One server, once per 6 hours, whoever posts it. The lock (taken in a fixed order) makes two accounts posting the
  -- same server at the same moment wait for each other instead of both passing.
  for sid in select distinct s from unnest(sids) s order by 1 loop
    perform pg_advisory_xact_lock(hashtextextended('promo:' || sid::text, 0));
    if exists (select 1 from public.promo_invite_marks pm where pm.server_id = sid and pm.at > now() - interval '6 hours') then
      raise exception 'That server was already promoted in the last 6 hours. Try again later.' using errcode = 'check_violation';
    end if;
  end loop;

  select max(m.created_at) into last_at from public.messages m
    where m.channel_id = new.channel_id and m.author_id = new.author_id and m.id <> new.id
      and m.created_at > now() - interval '6 hours'
      and m.content ~* '((?:yapper\.website|yapin\.gg)/invite/|discord\.gg/|discord(app)?\.com/invite/|t\.me/|guilded\.gg/)';
  select at into mark from public.post_marks where channel_id = new.channel_id and author_id = new.author_id and kind = 'invite' and at > now() - interval '6 hours';
  last_at := greatest(last_at, mark);
  if last_at is not null then
    raise exception 'You can post an invite in #promote-your-server once every 6 hours. Next one in % min', greatest(1, ceil(extract(epoch from (last_at + interval '6 hours' - now())) / 60)) using errcode = 'check_violation';
  end if;
  insert into public.post_marks (channel_id, author_id, kind, at) values (new.channel_id, new.author_id, 'invite', now())
    on conflict (channel_id, author_id, kind) do update set at = excluded.at;
  if cardinality(sids) > 0 then
    insert into public.promo_invite_marks (server_id, at) select distinct s, now() from unnest(sids) s order by 1
      on conflict (server_id) do update set at = excluded.at;
  end if;
  return new;
end $function$;

-- public.invites_per_person_cap()  [security definer]
CREATE OR REPLACE FUNCTION public.invites_per_person_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(new.vanity, false) or auth.uid() is null then return new; end if;
  if public.server_perm(new.server_id, 'manage_server') or public.is_staff_user(auth.uid()) then return new; end if;
  -- One lock per person and server, so parallel inserts can't all pass the count.
  perform pg_advisory_xact_lock(hashtextextended('invite_cap:' || new.server_id::text || ':' || new.created_by::text, 0));
  if (select count(*) from public.invites
      where server_id = new.server_id and created_by = new.created_by and not coalesce(vanity, false)) >= 5 then
    raise exception 'You already have invite links for this server. Use the one from Invite people.'
      using errcode = 'check_violation';
  end if;
  return new;
end;
$function$;

-- public.ip_banned_recently(p_ip text)  [security definer]
CREATE OR REPLACE FUNCTION public.ip_banned_recently(p_ip text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.login_attempts la
    join public.profiles p on lower(p.username) = lower(la.username)
    join public.site_bans b on b.user_id = p.id
    where la.ip = p_ip and la.ok and la.at > now() - interval '7 days'
      and (b.expires_at is null or b.expires_at > now())
  )
  or exists (select 1 from public.ban_leftovers l where l.ip = p_ip and l.until > now());
$function$;

-- public.ip_key(v text)
CREATE OR REPLACE FUNCTION public.ip_key(v text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case when v is null or v = '' or v = 'unknown' or length(v) > 64 then null
              when position(':' in v) > 0 then lower(array_to_string((string_to_array(split_part(v, '%', 1), ':'))[1:4], ':')) || '::/64'
              else v end
$function$;

-- public.is_area_manager(p_area text)  [security definer]
CREATE OR REPLACE FUNCTION public.is_area_manager(p_area text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or not exists (select 1 from public.site_area_managers where user_id = auth.uid() and area = p_area) then
    return false;
  end if;
  if exists (select 1 from public.site_moderators where user_id = auth.uid() and suspended_at is not null) then return false; end if;
  return public.feature_on('area_managers', null) and public.staff_mfa_ok() and not public.is_site_banned(auth.uid());
end;
$function$;

