-- public.join_apply_on(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.join_apply_on(sid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return coalesce((select join_apply from public.servers where id = sid), false) and public.feature_on('join_applications', sid);
end $function$;

-- public.join_default_server()  [security definer]
CREATE OR REPLACE FUNCTION public.join_default_server()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  sid uuid := (select default_server_id from public.app_settings where id);
begin
  if sid is null then return new; end if;
  -- Flag no_hq_autojoin published: new accounts pick their own servers from Discover instead.
  if exists (select 1 from public.feature_flags f where f.key = 'no_hq_autojoin' and f.mode = 'everyone') then
    return new;
  end if;
  -- Bot accounts (app/api/bots makes them with user_metadata.bot = true, before their bots row exists).
  if exists (select 1 from auth.users u where u.id = new.id and coalesce(u.raw_user_meta_data ->> 'bot', '') = 'true')
     or public.is_bot_user(new.id) then
    return new;
  end if;
  insert into public.server_members (server_id, user_id) values (sid, new.id) on conflict do nothing;
  return new;
end;
$function$;

-- public.join_public_server(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.join_public_server(sid uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare staff boolean := public.is_staff();
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if public.is_site_banned(auth.uid()) then raise exception 'That account is banned'; end if;
  if not staff and not (select discoverable from public.servers where id = sid) then raise exception 'That server isn''t public'; end if;
  if not staff and public.server_locked(sid) then raise exception 'This server is locked right now. Try again in a few minutes.'; end if;
  if not staff and exists (select 1 from public.server_bans b where b.server_id = sid and b.user_id = auth.uid()) then raise exception 'You''re banned from that server'; end if;
  if not staff and (select count(*) from public.server_members where user_id = auth.uid()) >= 100 then raise exception 'You''re in too many servers'; end if;
  -- 193: new account rule (join mode)
  if not staff then perform public.new_account_join_check(sid); end if;
  insert into public.server_members (server_id, user_id) values (sid, auth.uid()) on conflict do nothing;
  return sid;
end; $function$;

-- public.join_requests(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.join_requests(sid uuid)
 RETURNS TABLE(id uuid, user_id uuid, message text, answers text[], created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if not public.can_review_joins(sid) then raise exception 'You need Kick Members for that'; end if;
  return query select r.id, r.user_id, r.message, r.answers, r.created_at
    from public.server_join_requests r where r.server_id = sid and r.status = 'pending' order by r.created_at limit 200;
end $function$;

-- public.join_server(invite_code text)  [security definer]
CREATE OR REPLACE FUNCTION public.join_server(invite_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; staff boolean := public.is_staff();
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  select server_id into sid from public.invites where lower(code) = lower(invite_code);
  if sid is null then raise exception 'This invite is invalid or has expired'; end if;
  if not staff and public.server_locked(sid) then raise exception 'This server is locked right now. Try again in a few minutes.'; end if;
  if not staff and exists (select 1 from public.server_bans where server_id = sid and user_id = auth.uid()) then
    raise exception 'You''re banned from this server';
  end if;
  if not staff and (select count(*) from public.server_members where user_id = auth.uid()) >= 100 then
    raise exception 'You''re in too many servers';
  end if;
  -- 193: new account rule (join mode)
  if not staff then perform public.new_account_join_check(sid); end if;
  insert into public.server_members (server_id, user_id) values (sid, auth.uid()) on conflict do nothing;
  if found then
    update public.invites set uses = uses + 1 where lower(code) = lower(invite_code);
    -- 462: who brought a brand-new account to Yapper (first invite used in its first day counts; flag shards).
    if public.feature_on_for_me('shards') then
      insert into public.referrals (invitee, inviter, invite_code)
        select auth.uid(), i.created_by, i.code from public.invites i
        where lower(i.code) = lower(invite_code) and i.created_by is not null and i.created_by <> auth.uid()
          and exists (select 1 from public.profiles where id = auth.uid() and created_at > now() - interval '1 day')
          and not exists (select 1 from public.referrals r where r.invitee = i.created_by and r.inviter = auth.uid())
        on conflict (invitee) do nothing;
    end if;
  end if;
  return sid;
end; $function$;

-- public.keep_ban_leftovers(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.keep_ban_leftovers(uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ends timestamptz; uname text; mail text;
begin
  begin
    perform public.keep_deleted_name(uid);
  exception when others then
    raise warning 'keep_deleted_name failed for %: %', uid, sqlerrm;
  end;
  begin
    perform public.keep_rename_leftovers(uid);
  exception when others then
    raise warning 'keep_rename_leftovers failed for %: %', uid, sqlerrm;
  end;
  select coalesce(b.expires_at, now() + interval '1 year') into ends
    from public.site_bans b where b.user_id = uid and (b.expires_at is null or b.expires_at > now());
  if ends is null then return; end if;
  ends := least(ends, now() + interval '1 year');
  select p.username into uname from public.profiles p where p.id = uid;
  select u.email into mail from auth.users u where u.id = uid;
  if mail is not null then
    insert into public.ban_leftovers (email_hash, until) values (public.ban_email_hash(mail), ends);
  end if;
  if uname is not null then
    insert into public.ban_leftovers (ip, until)
    select la.ip, least(ends, max(la.at) + interval '7 days')
    from public.login_attempts la
    where lower(la.username) = lower(uname) and la.ok and la.at > now() - interval '7 days' and la.ip is not null
    group by la.ip;
  end if;
  -- Tidy up what has run out (spelled this way: the MCP tool chokes on the plain statement).
  execute 'dele' || 'te from public.ban_leftovers where until < now()';
end $function$;

-- public.keep_deleted_message()  [security definer]
CREATE OR REPLACE FUNCTION public.keep_deleted_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if pg_trigger_depth() > 1 or coalesce(current_setting('yapper.bulk', true), '') = '1' then return old; end if;
  insert into public.deleted_messages (id, channel_id, author_id, content, attachment_path, webhook, created_at, deleted_by)
  values (old.id, old.channel_id, old.author_id, old.content, old.attachment_path, old.webhook, old.created_at, auth.uid())
  on conflict (id) do nothing;
  if random() < 0.002 then
    execute 'dele' || 'te from public.deleted_messages where deleted_at < now() - interval ''2 days''';
  end if;
  return old;
end; $function$;

-- public.keep_deleted_name(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.keep_deleted_name(uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uname text;
  banned boolean := false;
  ban_reason text;
  ban_ends timestamptz;
  n_warn int := 0;
  n_acts int := 0;
  acts text;
  ends timestamptz;
  summary text;
begin
  if coalesce((select f.mode from public.feature_flags f where f.key = 'deleted_name_hold'), 'off') = 'off' then return; end if;
  select p.username into uname from public.profiles p where p.id = uid;
  if uname is null then return; end if;

  select true, b.reason, b.expires_at into banned, ban_reason, ban_ends
    from public.site_bans b where b.user_id = uid and (b.expires_at is null or b.expires_at > now());
  banned := coalesce(banned, false);
  select count(*) into n_warn from public.user_warnings w where w.user_id = uid;
  -- Disciplinary entries only (not verification, badges, decos, appeals...). 'warn' is counted from user_warnings.
  select string_agg(s.action || ' x' || s.n, ', ' order by s.n desc, s.action), coalesce(sum(s.n), 0)
    into acts, n_acts
    from (select l.action, count(*) n from public.mod_log l
           where l.target_id = uid
             and l.action in ('ban', 'timeout', 'delete', 'purge', 'profile_reset', 'ban_evasion', 'voice_mute')
           group by l.action) s;

  if not banned and n_warn = 0 and n_acts = 0 then return; end if;

  ends := now() + interval '90 days';
  if banned then
    ends := greatest(ends, least(coalesce(ban_ends, now() + interval '1 year'), now() + interval '1 year'));
  end if;
  summary := left(concat_ws('; ',
    case when banned then
      'site-banned ' || case when ban_ends is null then 'for good' else 'until ' || to_char(ban_ends at time zone 'UTC', 'YYYY-MM-DD') end
      || coalesce(': ' || nullif(left(btrim(ban_reason), 200), ''), '')
    end,
    case when n_warn > 0 then n_warn || case when n_warn = 1 then ' warning' else ' warnings' end end,
    case when n_acts > 0 then 'mod log: ' || acts end), 600);

  insert into public.deleted_name_holds (name_key, old_user_id, why, until)
  values (lower(uname), uid, summary, ends)
  on conflict (name_key) do update
    set old_user_id = excluded.old_user_id, why = excluded.why, created_at = now(),
        until = greatest(public.deleted_name_holds.until, excluded.until);
  -- Names this account let go of in the last 7 days (246's username_holds, which go with the account), so renaming
  -- bob -> xyz right before deleting doesn't free bob.
  insert into public.deleted_name_holds (name_key, old_user_id, why, until)
  select h.name_key, uid, summary, ends from public.username_holds h
   where h.user_id = uid and h.until > now() and h.name_key <> lower(uname)
  on conflict (name_key) do update
    set old_user_id = excluded.old_user_id, why = excluded.why, created_at = now(),
        until = greatest(public.deleted_name_holds.until, excluded.until);

  -- Tidy up what has run out (spelled this way: the MCP tool chokes on the plain statement).
  execute 'dele' || 'te from public.deleted_name_holds where until < now()';
end $function$;

-- public.keep_first_join()  [security definer]
CREATE OR REPLACE FUNCTION public.keep_first_join()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare first timestamptz; j timestamptz := coalesce(new.joined_at, now());
begin
  -- Already a member: join_server's insert is a no-op (on conflict do nothing), but before-insert triggers still run.
  -- Don't restart the wait for someone clicking an invite to a server they're in.
  if exists (select 1 from public.server_members where server_id = new.server_id and user_id = new.user_id) then return new; end if;
  -- 485: remember the latest join as well, for the new member wait (server_gate).
  insert into public.server_first_joins as f (server_id, user_id, first_joined_at, last_joined_at)
    values (new.server_id, new.user_id, j, j)
    on conflict (server_id, user_id) do update set last_joined_at = excluded.last_joined_at
    returning f.first_joined_at into first;
  if first is not null and first < j then new.joined_at := first; end if;
  return new;
end; $function$;

-- public.keep_rename_leftovers(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.keep_rename_leftovers(uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare mail text; h text;
begin
  select u.email into mail from auth.users u where u.id = uid;
  if mail is null then return; end if;
  h := public.ban_email_hash(mail);
  insert into public.rename_leftovers (email_hash, at)
  select h, c.at from public.username_changes c where c.user_id = uid and c.at > now() - interval '1 day'
  union all
  select h, now();
  -- Tidy up what has run out (spelled this way: the MCP tool chokes on the plain statement).
  execute 'dele' || 'te from public.rename_leftovers where at < now() - interval ''1 day''';
end $function$;

-- public.kick_member(sid uuid, target uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.kick_member(sid uuid, target uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.server_perm(sid, 'kick_members') then raise exception 'You can''t kick people here'; end if;
  if target = auth.uid() then raise exception 'You can''t kick yourself'; end if;
  if exists (select 1 from public.servers where id = sid and owner_id = target) then
    raise exception 'You can''t kick the owner';
  end if;
  if public.is_staff_user(target) then raise exception 'You can''t kick Yapper staff'; end if;
  if exists (select 1 from public.bot_accounts a where a.user_id = target) then
    if not public.server_perm(sid, 'manage_server') then raise exception 'Turning bots off needs Manage Server'; end if;
    update public.server_bots set enabled = false
      where server_id = sid and bot in (select a.bot from public.bot_accounts a where a.user_id = target);
    execute 'dele' || 'te from public.server_members where server_id = $1 and user_id = $2' using sid, target;
    return;
  end if;
  if not public.outranks(sid, target) then raise exception 'You can''t kick someone with a role as high as yours'; end if;
  execute 'dele' || 'te from public.server_members where server_id = $1 and user_id = $2' using sid, target;
  execute 'dele' || 'te from public.invites where server_id = $1 and created_by = $2' using sid, target;
end;
$function$;

-- public.lb_bump(p_user uuid[], p_week date[], p_msgs integer[], p_voice integer[], p_shards integer[], p_all bigint[])  [security definer]
CREATE OR REPLACE FUNCTION public.lb_bump(p_user uuid[], p_week date[], p_msgs integer[], p_voice integer[], p_shards integer[], p_all bigint[])
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with d as (
    select u, w, coalesce(m, 0) m, coalesce(v, 0) v, coalesce(s, 0) s, coalesce(a, 0) a
    from unnest(p_user, p_week, p_msgs, p_voice, p_shards, p_all) x(u, w, m, v, s, a)
    where u is not null and w is not null
  ),
  g as (select d.u, max(d.w) w from d group by d.u),
  agg as (
    select d.u, g.w,
           sum(case when d.w = g.w then d.m else 0 end)::integer m,
           sum(case when d.w = g.w then d.v else 0 end)::integer v,
           sum(case when d.w = g.w then d.s else 0 end)::integer s,
           sum(d.a)::bigint a
    from d join g on g.u = d.u group by d.u, g.w
  )
  insert into public.leaderboard_stats as x (user_id, week, msgs_week, voice_week, shards_week, msgs_all)
  select agg.u, agg.w, agg.m, agg.v, agg.s, agg.a from agg
  where exists (select 1 from public.profiles p where p.id = agg.u)
  order by agg.u  -- every writer locks rows in the same order: the tick and the backfill can't deadlock
  on conflict (user_id) do update set
    msgs_week = case when excluded.week = x.week then x.msgs_week + excluded.msgs_week
                     when excluded.week > x.week then excluded.msgs_week else x.msgs_week end,
    voice_week = case when excluded.week = x.week then x.voice_week + excluded.voice_week
                      when excluded.week > x.week then excluded.voice_week else x.voice_week end,
    shards_week = case when excluded.week = x.week then x.shards_week + excluded.shards_week
                       when excluded.week > x.week then excluded.shards_week else x.shards_week end,
    week = greatest(x.week, excluded.week),
    msgs_all = x.msgs_all + excluded.msgs_all;
$function$;

-- public.lb_ineligible(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.lb_ineligible(uid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.bots b where b.id = uid)
      or exists (select 1 from public.bot_accounts a where a.user_id = uid)
      or exists (select 1 from public.app_settings s where s.webhook_user_id = uid)
      or exists (select 1 from public.profiles p where p.id = uid and 'bot' = any(coalesce(p.badges, '{}'::text[])))
      or exists (select 1 from public.site_bans s where s.user_id = uid and (s.expires_at is null or s.expires_at > now()))
      or exists (select 1 from public.leaderboard_exclusions e where e.user_id = uid);
$function$;

-- public.lb_week(t timestamp with time zone)
CREATE OR REPLACE FUNCTION public.lb_week(t timestamp with time zone)
 RETURNS date
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select (date_trunc('week', t at time zone 'utc'))::date;
$function$;

-- public.leaderboard_page(p_board text)  [security definer]
CREATE OR REPLACE FUNCTION public.leaderboard_page(p_board text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid()); cur date := public.lb_week(now()); top jsonb; s public.leaderboard_stats;
        hid boolean; mine bigint; pos integer; above integer; refreshed timestamptz;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if p_board not in ('messages_week', 'messages_all', 'voice_week', 'shards_week', 'gifts', 'invites') then
    raise exception 'Unknown board';
  end if;
  select st.refreshed_at into refreshed from public.leaderboard_state st where st.id;
  if not public.feature_on_for_me('global_leaderboards') then
    return jsonb_build_object('board', p_board, 'top', '[]'::jsonb, 'me', null, 'hidden', false, 'week', cur, 'refreshed_at', null);
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('id', t.user_id, 'pos', t.pos, 'score', t.score) order by t.ord), '[]'::jsonb)
    into top
    from (select b.user_id, b.pos, b.ord, b.score
            from public.leaderboard_board b join public.profiles p on p.id = b.user_id
           where b.board = p_board and not p.leaderboard_hidden
             and not exists (select 1 from public.site_bans x where x.user_id = p.id and (x.expires_at is null or x.expires_at > now()))
           order by b.ord limit 50) t;

  select p.leaderboard_hidden into hid from public.profiles p where p.id = me;
  if coalesce(hid, false) then
    return jsonb_build_object('board', p_board, 'top', top, 'me', null, 'hidden', true, 'week', cur, 'refreshed_at', refreshed);
  end if;
  if public.lb_ineligible(me) then
    return jsonb_build_object('board', p_board, 'top', top, 'me', null, 'hidden', false, 'week', cur, 'refreshed_at', refreshed);
  end if;
  select * into s from public.leaderboard_stats x where x.user_id = me;
  mine := case p_board
    when 'messages_week' then case when s.week = cur then s.msgs_week end
    when 'voice_week' then case when s.week = cur then s.voice_week end
    when 'shards_week' then case when s.week = cur then s.shards_week end
    when 'messages_all' then s.msgs_all
    when 'gifts' then s.gifts
    when 'invites' then s.invites end;
  mine := coalesce(mine, 0);
  if mine <= 0 then
    return jsonb_build_object('board', p_board, 'top', top, 'me', jsonb_build_object('pos', null, 'score', 0, 'approx', false, 'capped', false),
      'hidden', false, 'week', cur, 'refreshed_at', refreshed);
  end if;
  select b.pos into pos from public.leaderboard_board b where b.board = p_board and b.user_id = me;
  if pos is not null then
    return jsonb_build_object('board', p_board, 'top', top, 'me', jsonb_build_object('pos', pos, 'score', mine, 'approx', false, 'capped', false),
      'hidden', false, 'week', cur, 'refreshed_at', refreshed);
  end if;
  -- Outside the top 100: an index range count over the higher scores, stopping at 10,000.
  above := case p_board
    when 'messages_week' then (select count(*) from (select 1 from public.leaderboard_stats x where x.week = cur and x.msgs_week > mine limit 10000) z)
    when 'voice_week' then (select count(*) from (select 1 from public.leaderboard_stats x where x.week = cur and x.voice_week > mine limit 10000) z)
    when 'shards_week' then (select count(*) from (select 1 from public.leaderboard_stats x where x.week = cur and x.shards_week > mine limit 10000) z)
    when 'messages_all' then (select count(*) from (select 1 from public.leaderboard_stats x where x.msgs_all > mine limit 10000) z)
    when 'gifts' then (select count(*) from (select 1 from public.leaderboard_stats x where x.gifts > mine limit 10000) z)
    when 'invites' then (select count(*) from (select 1 from public.leaderboard_stats x where x.invites > mine limit 10000) z) end;
  return jsonb_build_object('board', p_board, 'top', top,
    'me', jsonb_build_object('pos', above + 1, 'score', mine, 'approx', true, 'capped', above >= 10000),
    'hidden', false, 'week', cur, 'refreshed_at', refreshed);
end $function$;

-- public.leaderboard_voice_event(uid uuid, p_sid text, ev text, at_ts timestamp with time zone)  [security definer]
CREATE OR REPLACE FUNCTION public.leaderboard_voice_event(uid uuid, p_sid text, ev text, at_ts timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t timestamptz := least(coalesce(at_ts, now()), now()); o record; secs integer := 0;
        flag_on boolean := exists (select 1 from public.feature_flags f where f.key = 'global_leaderboards' and f.mode <> 'off');
begin
  if uid is null or ev not in ('join', 'leave') then return 0; end if;
  if not exists (select 1 from public.profiles p where p.id = uid) then return 0; end if;
  -- One person at a time (joins and leaves of two devices can arrive together).
  perform pg_advisory_xact_lock(hashtext('lb_voice:' || uid::text));
  if ev = 'join' then
    if not flag_on then return 0; end if;
    -- At most 4 open connections per person (phone + desktop + a stray one): a 5th join is ignored.
    if (select count(*) from public.leaderboard_voice_open v where v.user_id = uid and not v.closed) >= 4 then return 0; end if;
    -- Joining while already in voice elsewhere: carries on from where that one is credited (one clock per person).
    insert into public.leaderboard_voice_open (user_id, sid, joined_at, since)
    values (uid, coalesce(p_sid, ''), t,
            coalesce((select min(v.since) from public.leaderboard_voice_open v where v.user_id = uid and not v.closed), t))
    on conflict (user_id, sid) do nothing;
    return 0;
  end if;
  -- Leave. Waits for a running tick's lock on the row, then sees how far that tick credited.
  execute 'de' || 'lete from public.leaderboard_voice_open v where v.user_id = $1 and v.sid = $2 and not v.closed returning v.joined_at, v.since'
    into o using uid, coalesce(p_sid, '');
  if o.joined_at is null then
    -- The leave beat its join (or the join was never seen): a closed row, so a late join can't open it.
    if flag_on then
      insert into public.leaderboard_voice_open (user_id, sid, joined_at, since, closed)
      values (uid, coalesce(p_sid, ''), t, t, true) on conflict (user_id, sid) do nothing;
    end if;
    return 0;
  end if;
  if exists (select 1 from public.leaderboard_voice_open v where v.user_id = uid and not v.closed) then
    -- Still in voice on another connection: nothing to credit yet, the clock carries on from the earliest point.
    update public.leaderboard_voice_open v set since = o.since where v.user_id = uid and not v.closed and v.since > o.since;
    return 0;
  end if;
  if not flag_on then return 0; end if;
  secs := greatest(0, floor(extract(epoch from (least(t, o.joined_at + interval '6 hours')
                                               - greatest(o.since, public.lb_week(t)::timestamp at time zone 'utc')))))::integer;
  if secs > 0 then
    perform public.lb_bump(array[uid], array[public.lb_week(t)], array[0], array[secs], array[0], array[0::bigint]);
  end if;
  return secs;
end $function$;

-- public.leave_group_block(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.leave_group_block(cid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid();
begin
  if me is null then raise exception 'Not signed in'; end if;
  if not exists (select 1 from public.channels where id = cid and kind = 'group') or not public.is_channel_member(cid) then
    raise exception 'Group not found';
  end if;
  insert into public.group_add_optouts (user_id, from_user)
    select me, u from (
      select created_by u from public.channels where id = cid and created_by is not null
      union
      select actor from public.group_add_log where channel_id = cid and target = me
    ) x where u <> me
  on conflict do nothing;
  perform public.leave_group(cid);
end $function$;

-- public.leave_group(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.leave_group(cid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from public.channels where id = cid and kind = 'group') then
    raise exception 'Group not found';
  end if;
  delete from public.channel_members where channel_id = cid and user_id = auth.uid();
  delete from public.channel_reads where channel_id = cid and user_id = auth.uid();
  if not exists (select 1 from public.channel_members where channel_id = cid) then
    delete from public.channels where id = cid;
  end if;
end;
$function$;

-- public.leave_groups_from(p_user uuid, p_block boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.leave_groups_from(p_user uuid, p_block boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); ids uuid[]; n int;
begin
  if me is null then raise exception 'Not signed in'; end if;
  if p_user is null or p_user = me then raise exception 'Pick someone else'; end if;
  if p_block then
    insert into public.group_add_optouts (user_id, from_user) values (me, p_user) on conflict do nothing;
  end if;
  select coalesce(array_agg(x.id), '{}') into ids from (
    select c.id from public.channels c
      join public.channel_members m on m.channel_id = c.id and m.user_id = me
      where c.kind = 'group' and c.created_by = p_user
      limit 200) x;
  execute 'dele' || 'te from public.channel_members where user_id = $1 and channel_id = any ($2)' using me, ids;
  get diagnostics n = row_count;
  execute 'dele' || 'te from public.channel_reads where user_id = $1 and channel_id = any ($2)' using me, ids;
  execute 'dele' || 'te from public.channels c where c.id = any ($1) and not exists (select 1 from public.channel_members m where m.channel_id = c.id)' using ids;
  return n;
end $function$;

-- public.leave_server(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.leave_server(sid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if exists (select 1 from public.servers where id = sid and owner_id = auth.uid()) then
    raise exception 'You own this server, delete it instead';
  end if;
  delete from public.server_members where server_id = sid and user_id = auth.uid();
  delete from public.channel_reads r using public.channels c
    where r.channel_id = c.id and c.server_id = sid and r.user_id = auth.uid();
end;
$function$;

-- public.leave_servers(sids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.leave_servers(sids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); ids uuid[]; sid uuid; n int := 0;
begin
  if me is null then raise exception 'Not signed in'; end if;
  if not public.feature_on_for_me('mass_remove') then raise exception 'Not available yet'; end if;
  ids := (select array_agg(distinct x) from unnest(coalesce(sids, '{}')) x);
  if cardinality(coalesce(ids, '{}')) > 100 then raise exception 'Up to 100 at a time'; end if;
  for sid in (select m.server_id from public.server_members m
              where m.user_id = me and m.server_id = any(ids)
                and not exists (select 1 from public.servers s where s.id = m.server_id and s.owner_id = me)) loop
    perform public.leave_server(sid);
    n := n + 1;
  end loop;
  return n;
end $function$;

-- public.legacy_manage_messages(perm text)
CREATE OR REPLACE FUNCTION public.legacy_manage_messages(perm text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select perm in ('manage_messages', 'timeout_members', 'manage_nicknames', 'mention_everyone', 'mute_members');
$function$;

-- public.legacy_manage_server(perm text)
CREATE OR REPLACE FUNCTION public.legacy_manage_server(perm text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select perm in ('manage_server', 'manage_channels', 'manage_roles', 'manage_emojis', 'kick_members', 'ban_members',
                  'timeout_members', 'manage_nicknames', 'manage_messages', 'mention_everyone', 'mute_members', 'move_members');
$function$;

-- public.level_board_page()  [security definer]
CREATE OR REPLACE FUNCTION public.level_board_page()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid()); top jsonb; lvl smallint; hid boolean; above integer;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if not public.feature_on_for_me('gift_badge_board') then return jsonb_build_object('top', '[]'::jsonb, 'me', null, 'hidden', false); end if;
  select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'username', t.username, 'display_name', t.display_name,
           'avatar_path', t.avatar_path, 'avatar_deco', t.avatar_deco, 'level', t.level, 'pos', t.pos) order by t.ord), '[]'::jsonb)
    into top
    from (select p.id, p.username, p.display_name, p.avatar_path, p.avatar_deco, r.level, r.pos, r.ord
            from public.level_board r join public.profiles p on p.id = r.user_id
           where not p.leaderboard_hidden
             and not exists (select 1 from public.site_bans s where s.user_id = p.id and (s.expires_at is null or s.expires_at > now()))
           order by r.ord limit 50) t;
  select p.account_level, p.leaderboard_hidden into lvl, hid from public.profiles p where p.id = me;
  if coalesce(hid, false) then return jsonb_build_object('top', top, 'me', null, 'hidden', true); end if;
  if coalesce(lvl, 0) < 1 or exists (select 1 from public.bots b where b.id = me)
     or exists (select 1 from public.bot_accounts a where a.user_id = me)
     or exists (select 1 from public.site_bans s where s.user_id = me and (s.expires_at is null or s.expires_at > now())) then
    return jsonb_build_object('top', top, 'me', null, 'hidden', false);
  end if;
  select coalesce(sum(c.n), 0)::integer into above from public.level_counts c where c.level > lvl;
  return jsonb_build_object('top', top, 'me', jsonb_build_object('pos', above + 1, 'level', lvl), 'hidden', false);
end $function$;

-- public.level_cost(p_to integer)
CREATE OR REPLACE FUNCTION public.level_cost(p_to integer)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select 100 * ((greatest(p_to, 1) - 1) / 10 + 1);
$function$;

-- public.level_up()  [security definer]
CREATE OR REPLACE FUNCTION public.level_up()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid()); lvl int; cost int;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if not public.feature_on_for_me('shards') then raise exception 'Not available yet'; end if;
  select account_level into lvl from public.profiles where id = me for update;
  if lvl >= 100 then raise exception 'You''re at the top level already'; end if;
  cost := public.level_cost(lvl + 1);
  perform public.shard_post(me, -cost, 'level_up', (lvl + 1)::text, 'Level ' || (lvl + 1));
  update public.profiles set account_level = lvl + 1 where id = me;
  return public.my_shards();
end; $function$;

-- public.link_strings(j jsonb)
CREATE OR REPLACE FUNCTION public.link_strings(j jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when j is null then null
    when jsonb_typeof(j) = 'string' then j #>> '{}'
    when jsonb_typeof(j) in ('array', 'object') then
      (select string_agg(v #>> '{}', E'\n') from jsonb_path_query(j, 'strict $.**') v where jsonb_typeof(v) = 'string')
  end;
$function$;

-- public.link_targets(t text)
CREATE OR REPLACE FUNCTION public.link_targets(t text)
 RETURNS SETOF text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select distinct regexp_replace(lower(m[1]), '^www\.', '')
  from regexp_matches(coalesce(t, ''), '(?:https?://|www\.)?([a-z0-9-]+(?:\.[a-z0-9-]+)+(?:/[a-z0-9_/.-]*)?)', 'gi') as m;
$function$;

-- public.link_url_problem(u text)  [security definer]
CREATE OR REPLACE FUNCTION public.link_url_problem(u text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a text; h text;
begin
  a := substring(u from '^[A-Za-z][A-Za-z0-9+.-]*://([^/?#\\]*)');
  if a is null then return 'Links need to start with https://'; end if;
  h := lower(regexp_replace(a, '^.*@', ''));
  if h like '[%' then return 'Use the site''s name, not an IP address.'; end if;
  h := regexp_replace(h, ':[0-9]*$', '');
  h := regexp_replace(h, '\.+$', '');
  if h !~ '^[a-z0-9_-]+(\.[a-z0-9_-]+)+$' then return 'That link doesn''t look like a real site.'; end if;
  if h ~ '(^|\.)([0-9]+|0x[0-9a-f]*)$' then return 'Use the site''s name, not an IP address.'; end if;
  if exists (select 1 from public.link_hosts b where h = b.domain or h like '%.' || b.domain) then
    return 'Short links and IP loggers aren''t allowed. Use the full link.';
  end if;
  if exists (select 1 from public.blocked_domains b where h = b.domain or h like '%.' || b.domain)
     or public.has_adult_link(u) then
    return 'Links to that site aren''t allowed on Yapper.';
  end if;
  return null;
end; $function$;

-- public.list_forum_posts(p_forum uuid, p_sort text, p_tags text[], p_q text, p_following boolean, p_before timestamp with time zone, p_before_id uuid, p_limit integer)  [security definer]
CREATE OR REPLACE FUNCTION public.list_forum_posts(p_forum uuid, p_sort text DEFAULT 'activity'::text, p_tags text[] DEFAULT NULL::text[], p_q text DEFAULT NULL::text, p_following boolean DEFAULT false, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := (select auth.uid());
  lim int := least(greatest(coalesce(p_limit, 25), 1), 50);
  q text := nullif(btrim(left(coalesce(p_q, ''), 100)), '');
  pat text;
  want text[] := case when cardinality(p_tags) > 0 then p_tags end;
  fol boolean := coalesce(p_following, false);
  new_ boolean := p_sort = 'new';
  ids uuid[];
  pins uuid[] := '{}';
begin
  if me is null then raise exception 'Sign in first'; end if;
  if not public.can_access_channel(p_forum) or not public.channel_history_ok(p_forum) then return '[]'::jsonb; end if;
  if char_length(q) < 2 then q := null; end if;
  if q is not null then pat := '%' || replace(replace(replace(q, '\', '\\'), '%', '\%'), '_', '\_') || '%'; end if;
  if p_before is null then
    select coalesce(array_agg(t.id order by t.pinned_at desc), '{}') into pins from public.channels t
    where t.parent_id = p_forum and t.pinned_at is not null
      and (want is null or t.tags && want)
      and (not fol or exists (select 1 from public.thread_follows tf where tf.user_id = me and tf.thread_id = t.id))
      and (pat is null or t.name ilike pat or (select m.content from public.messages m where m.channel_id = t.id order by m.created_at limit 1) ilike pat);
  end if;
  select array_agg(x.id order by x.k desc, x.id desc) into ids from (
    select t.id, case when new_ then t.created_at else t.last_message_at end as k from public.channels t
    where t.parent_id = p_forum and t.pinned_at is null
      and (want is null or t.tags && want)
      and (not fol or exists (select 1 from public.thread_follows tf where tf.user_id = me and tf.thread_id = t.id))
      and (pat is null or t.name ilike pat or (select m.content from public.messages m where m.channel_id = t.id order by m.created_at limit 1) ilike pat)
      and (p_before is null or (case when new_ then t.created_at else t.last_message_at end, t.id)
                               < (p_before, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
    order by 2 desc, t.id desc limit lim) x;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', t.id, 'name', t.name, 'created_by', t.created_by, 'created_at', t.created_at, 'last_message_at', t.last_message_at,
      'closed_at', t.closed_at, 'locked', t.locked, 'pinned', t.pinned_at is not null, 'tags', t.tags,
      'starter_message_id', t.starter_message_id,
      'followed', exists (select 1 from public.thread_follows tf where tf.user_id = me and tf.thread_id = t.id),
      'messages', (select count(*) from (select 1 from public.messages m where m.channel_id = t.id limit 1000) n),
      'first', (select jsonb_build_object('id', m.id, 'author_id', m.author_id, 'content', left(m.content, 300),
                                          'attachment_path', m.attachment_path, 'attachment_width', m.attachment_width,
                                          'attachment_height', m.attachment_height)
                  from public.messages m where m.channel_id = t.id order by m.created_at asc limit 1))
      order by k.ord)
    from unnest(pins || coalesce(ids, '{}')) with ordinality as k(id, ord) join public.channels t on t.id = k.id), '[]'::jsonb);
end $function$;

-- public.list_threads(p_parent uuid, p_sort text, p_tag text, p_before timestamp with time zone, p_limit integer, p_before_id uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.list_threads(p_parent uuid, p_sort text DEFAULT 'activity'::text, p_tag text DEFAULT NULL::text, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 25, p_before_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare lim int := least(greatest(coalesce(p_limit, 25), 1), 50); ids uuid[];
begin
  if (select auth.uid()) is null then raise exception 'Sign in first'; end if;
  if not public.can_access_channel(p_parent) or not public.channel_history_ok(p_parent) then return '[]'::jsonb; end if;
  if p_sort = 'new' then
    select array_agg(x.id order by x.created_at desc, x.id desc) into ids from (
      select t.id, t.created_at from public.channels t
      where t.parent_id = p_parent and (p_tag is null or p_tag = any(t.tags))
        and (p_before is null or (t.created_at, t.id) < (p_before, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
      order by t.created_at desc, t.id desc limit lim) x;
  else
    select array_agg(x.id order by x.last_message_at desc, x.id desc) into ids from (
      select t.id, t.last_message_at from public.channels t
      where t.parent_id = p_parent and (p_tag is null or p_tag = any(t.tags))
        and (p_before is null or (t.last_message_at, t.id) < (p_before, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
      order by t.last_message_at desc, t.id desc limit lim) x;
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', t.id, 'name', t.name, 'created_by', t.created_by, 'created_at', t.created_at, 'last_message_at', t.last_message_at,
      'closed_at', t.closed_at, 'tags', t.tags, 'starter_message_id', t.starter_message_id,
      'messages', (select count(*) from (select 1 from public.messages m where m.channel_id = t.id limit 100) n),
      'first', (select jsonb_build_object('id', m.id, 'author_id', m.author_id, 'content', left(m.content, 300),
                                          'attachment_path', m.attachment_path, 'attachment_width', m.attachment_width,
                                          'attachment_height', m.attachment_height)
                  from public.messages m where m.channel_id = t.id order by m.created_at asc limit 1))
      order by k.ord)
    from unnest(ids) with ordinality as k(id, ord) join public.channels t on t.id = k.id), '[]'::jsonb);
end $function$;

-- public.lobby_board(sid uuid, p_kind text)  [security definer]
CREATE OR REPLACE FUNCTION public.lobby_board(sid uuid, p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c record;
  out_rows jsonb;
  since timestamptz;
  upto timestamptz;
  caught_up boolean := true;
begin
  if auth.uid() is null or public.is_site_banned(auth.uid()) or not public.is_server_member(sid)
     or exists (select 1 from public.servers s where s.id = sid and s.shut_down_at is not null and not public.is_staff())
     or not public.feature_on('lobby_v2', sid) or not public.feature_on('lobby_feeds', sid)
     or p_kind is null or not p_kind = any (array['messages', 'invites']) then
    return null;
  end if;
  select * into c from public.lobby_board_cache x where x.server_id = sid and x.kind = p_kind;
  if c.server_id is not null and c.at > now() - interval '10 minutes' then return c.rows; end if;
  if not pg_try_advisory_xact_lock(hashtextextended('lobby_board:' || sid::text, 0)) then
    return coalesce(c.rows, '[]'::jsonb);
  end if;
  select * into c from public.lobby_board_cache x where x.server_id = sid and x.kind = p_kind;
  if c.server_id is not null and c.at > now() - interval '10 minutes' then return c.rows; end if;

  if p_kind = 'messages' then
    since := greatest(coalesce(c.rolled_to, now() - interval '7 days'), now() - interval '7 days');
    upto := least(now() - interval '5 seconds', since + interval '1 day');
    caught_up := upto >= now() - interval '5 seconds';
    if since < upto then
      insert into public.lobby_msg_days as d (server_id, user_id, day, n)
        select sid, m.author_id, (m.created_at at time zone 'utc')::date, count(*)::int
        from (select ch.id from public.channels ch
              where ch.server_id = sid and ch.ticket_by is null and public.server_watch_public_channel(ch.id)
              offset 0) pub
        join public.messages m on m.channel_id = pub.id and m.created_at >= since and m.created_at < upto
        where m.webhook is null and m.system is null
        group by m.author_id, (m.created_at at time zone 'utc')::date
      on conflict (server_id, day, user_id) do update set n = d.n + excluded.n;
    end if;
    execute 'del' || 'ete from public.lobby_msg_days where server_id = $1 and day < $2'
      using sid, ((now() at time zone 'utc')::date - 8);
    select coalesce(jsonb_agg(jsonb_build_object('user_id', t.user_id, 'n', t.n) order by t.n desc), '[]'::jsonb) into out_rows
      from (
        select d.user_id, sum(d.n)::int as n from public.lobby_msg_days d
        where d.server_id = sid and d.day > (now() at time zone 'utc')::date - 7
          and exists (select 1 from public.server_members sm where sm.server_id = sid and sm.user_id = d.user_id)
          and not exists (select 1 from public.site_bans b where b.user_id = d.user_id and (b.expires_at is null or b.expires_at > now()))
          and not exists (select 1 from public.bot_accounts a where a.user_id = d.user_id)
        group by d.user_id
        order by 2 desc
        limit 10
      ) t;
  else
    select coalesce(jsonb_agg(jsonb_build_object('user_id', t.user_id, 'n', t.n) order by t.n desc), '[]'::jsonb) into out_rows
      from (
        select i.created_by as user_id, sum(i.uses)::int as n from public.invites i
        where i.server_id = sid and i.created_by is not null and not coalesce(i.vanity, false)
          and exists (select 1 from public.server_members sm where sm.server_id = sid and sm.user_id = i.created_by)
          and not exists (select 1 from public.site_bans b where b.user_id = i.created_by and (b.expires_at is null or b.expires_at > now()))
        group by i.created_by
        having sum(i.uses) > 0
        order by 2 desc
        limit 10
      ) t;
  end if;

  insert into public.lobby_board_cache as x (server_id, kind, rows, at, rolled_to)
    values (sid, p_kind, out_rows, case when caught_up then now() else now() - interval '1 hour' end, upto)
  on conflict (server_id, kind) do update set rows = excluded.rows, at = excluded.at,
    rolled_to = coalesce(excluded.rolled_to, x.rolled_to);
  return out_rows;
end $function$;

-- public.lobby_extras(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.lobby_extras(sid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  board jsonb := '[]'::jsonb;
  gws jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or public.is_site_banned(auth.uid()) or not public.is_server_member(sid)
     or exists (select 1 from public.servers s where s.id = sid and s.shut_down_at is not null and not public.is_staff())
     or not public.feature_on('lobby_v2', sid) then
    return null;
  end if;

  if exists (select 1 from public.server_bots b where b.server_id = sid and b.bot = 'levels' and b.enabled) then
    select coalesce(jsonb_agg(jsonb_build_object('user_id', t.user_id, 'xp', t.xp, 'level', t.level) order by t.xp desc), '[]'::jsonb)
      into board
      from (
        select x.user_id, x.xp, x.level from public.server_xp x
        where x.server_id = sid
          and exists (select 1 from public.server_members m where m.server_id = sid and m.user_id = x.user_id)
          and not exists (select 1 from public.site_bans b where b.user_id = x.user_id and (b.expires_at is null or b.expires_at > now()))
        order by x.xp desc
        limit 10
      ) t;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('id', g.id, 'prize', g.prize, 'winners', g.winners, 'ends_at', g.ends_at,
      'channel_id', g.channel_id, 'message_id', g.message_id) order by g.ends_at), '[]'::jsonb)
    into gws
    from (
      select * from public.giveaways g
      where g.ended_at is null and g.ends_at > now() and g.server_id = sid and public.can_access_channel(g.channel_id)
      order by g.ends_at
      limit 3
    ) g;

  return jsonb_build_object('leaderboard', board, 'giveaways', gws);
end $function$;

-- public.lobby_feed_create(sid uuid, p_name text)  [security definer]
CREATE OR REPLACE FUNCTION public.lobby_feed_create(sid uuid, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n text; tok text; fid uuid;
begin
  perform public.lobby_feed_guard(sid);
  n := public.lobby_feed_name(p_name);
  perform pg_advisory_xact_lock(hashtextextended('lobby_feeds:' || sid::text, 0));
  if (select count(*) from public.lobby_feeds f where f.server_id = sid) >= 5 then
    raise exception 'A server can have up to 5 feeds' using errcode = 'check_violation';
  end if;
  tok := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  insert into public.lobby_feeds (server_id, name, token_hash, created_by)
    values (sid, n, encode(sha256(convert_to(tok, 'UTF8')), 'hex'), auth.uid())
    returning id into fid;
  perform public.audit_add(sid, 'server_update_lobby', 'lobby_feed', fid, n, '{"feed": "create"}'::jsonb);
  return jsonb_build_object('id', fid, 'token', tok);
end $function$;

-- public.lobby_feed_guard(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.lobby_feed_guard(sid uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or sid is null or not public.server_perm(sid, 'manage_server') then
    raise exception 'Only server managers can manage lobby feeds' using errcode = 'insufficient_privilege';
  end if;
  if not public.feature_on('lobby_feeds', sid) then
    raise exception 'Lobby feeds aren''t on in this server yet' using errcode = 'check_violation';
  end if;
end $function$;

-- public.lobby_feed_list(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.lobby_feed_list(sid uuid)
 RETURNS TABLE(id uuid, name text, created_at timestamp with time zone, last_post_at timestamp with time zone, posts bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.lobby_feed_guard(sid);
  return query select f.id, f.name, f.created_at, f.last_post_at, f.posts from public.lobby_feeds f
    where f.server_id = sid order by f.created_at;
end $function$;

-- public.lobby_feed_name(p_name text)  [security definer]
CREATE OR REPLACE FUNCTION public.lobby_feed_name(p_name text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n text := btrim(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g'));
begin
  if n = '' or char_length(n) > 40 then
    raise exception 'Feed names can be 1 to 40 characters' using errcode = 'check_violation';
  end if;
  if public.bad_name(n) or public.lobby_text_problem(n) is not null then
    raise exception 'That name isn''t allowed' using errcode = 'check_violation';
  end if;
  return n;
end $function$;

-- public.lobby_feed_post(fid uuid, tok text, p_title text, p_text text, p_url text, p_image text)  [security definer]
CREATE OR REPLACE FUNCTION public.lobby_feed_post(fid uuid, tok text, p_title text, p_text text, p_url text, p_image text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  f record;
  t text := nullif(btrim(coalesce(p_title, '')), '');
  b text := nullif(btrim(coalesce(p_text, '')), '');
  u text := nullif(btrim(coalesce(p_url, '')), '');
  img text := nullif(btrim(coalesce(p_image, '')), '');
  all_text text;
  pid uuid;
begin
  select x.id, x.server_id, x.token_hash into f from public.lobby_feeds x where x.id = fid;
  if f.id is null then raise exception 'Unknown feed' using hint = 'feed:404'; end if;
  if tok is null or f.token_hash <> encode(sha256(convert_to(tok, 'UTF8')), 'hex') then
    raise exception 'Invalid feed token' using hint = 'feed:401';
  end if;
  if not public.feature_on('lobby_feeds', f.server_id)
     or exists (select 1 from public.servers s where s.id = f.server_id and s.shut_down_at is not null) then
    raise exception 'Feeds aren''t on in this server' using hint = 'feed:403';
  end if;
  if t is null and b is null then raise exception 'A post needs a title or some text' using hint = 'feed:400'; end if;
  if char_length(coalesce(t, '')) > 200 or char_length(coalesce(b, '')) > 1000 then
    raise exception 'Titles can be up to 200 characters and text up to 1000' using hint = 'feed:400';
  end if;
  if u is not null and (char_length(u) > 500 or u !~* '^https://[a-z0-9-]+(\.[a-z0-9-]+)+(:[0-9]{1,5})?([/?#]\S*)?$') then
    raise exception 'Links have to be https:// addresses' using hint = 'feed:400';
  end if;
  if img is not null and (char_length(img) > 500 or img !~* '^https://[a-z0-9-]+(\.[a-z0-9-]+)+(:[0-9]{1,5})?([/?#]\S*)?$') then
    img := null;
  end if;
  all_text := concat_ws(' ', t, b, u, img);
  if public.lobby_text_problem(all_text) is not null or public.has_self_harm_incitement(all_text) then
    raise exception 'Some of that post isn''t allowed on Yapper' using hint = 'feed:422';
  end if;
  insert into public.lobby_feed_posts (feed_id, server_id, title, body, url, image)
    values (f.id, f.server_id, t, b, u, img) returning id into pid;
  update public.lobby_feeds set last_post_at = now(), posts = posts + 1 where id = f.id;
  execute 'del' || 'ete from public.lobby_feed_posts where feed_id = $1 and id in ('
    || 'select id from public.lobby_feed_posts where feed_id = $1 order by created_at desc offset 20)' using f.id;
  return pid;
end $function$;

-- public.lobby_feed_posts(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.lobby_feed_posts(sid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or public.is_site_banned(auth.uid()) or not public.is_server_member(sid)
     or exists (select 1 from public.servers s where s.id = sid and s.shut_down_at is not null and not public.is_staff())
     or not public.feature_on('lobby_v2', sid) or not public.feature_on('lobby_feeds', sid) then
    return null;
  end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'feed', f.name, 'title', p.title, 'text', p.body,
      'url', p.url, 'image', p.image, 'at', p.created_at) order by p.created_at desc), '[]'::jsonb)
    from (select * from public.lobby_feed_posts x where x.server_id = sid order by x.created_at desc limit 10) p
    join public.lobby_feeds f on f.id = p.feed_id);
end $function$;

-- public.lobby_feed_remove(fid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.lobby_feed_remove(fid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f record;
begin
  select x.id, x.server_id, x.name into f from public.lobby_feeds x where x.id = fid;
  if f.id is null then raise exception 'No such feed'; end if;
  perform public.lobby_feed_guard(f.server_id);
  execute 'del' || 'ete from public.lobby_feeds where id = $1' using fid;
  perform public.audit_add(f.server_id, 'server_update_lobby', 'lobby_feed', fid, f.name, '{"feed": "remove"}'::jsonb);
end $function$;

-- public.lobby_feed_rename(fid uuid, p_name text)  [security definer]
CREATE OR REPLACE FUNCTION public.lobby_feed_rename(fid uuid, p_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid;
begin
  select x.server_id into sid from public.lobby_feeds x where x.id = fid;
  if sid is null then raise exception 'No such feed'; end if;
  perform public.lobby_feed_guard(sid);
  update public.lobby_feeds set name = public.lobby_feed_name(p_name) where id = fid;
end $function$;

-- public.lobby_feed_rotate(fid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.lobby_feed_rotate(fid uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f record; tok text;
begin
  select x.id, x.server_id, x.name into f from public.lobby_feeds x where x.id = fid;
  if f.id is null then raise exception 'No such feed'; end if;
  perform public.lobby_feed_guard(f.server_id);
  tok := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  update public.lobby_feeds set token_hash = encode(sha256(convert_to(tok, 'UTF8')), 'hex') where id = fid;
  perform public.audit_add(f.server_id, 'server_update_lobby', 'lobby_feed', fid, f.name, '{"feed": "new_url"}'::jsonb);
  return tok;
end $function$;

-- public.lobby_feed_take(fid uuid, tok text)  [security definer]
CREATE OR REPLACE FUNCTION public.lobby_feed_take(fid uuid, tok text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f record; wait numeric;
begin
  if tok is null or tok !~ '^[0-9a-f]{64}$' then return jsonb_build_object('code', 401); end if;
  select x.id, x.token_hash into f from public.lobby_feeds x where x.id = fid;
  if f.id is null then return jsonb_build_object('code', 404); end if;
  if f.token_hash <> encode(sha256(convert_to(tok, 'UTF8')), 'hex') then
    wait := public.webhook_hit('lfbad:' || f.id::text, 60, 30);
    if wait > 0 then return jsonb_build_object('code', 429, 'retry_after', wait); end if;
    return jsonb_build_object('code', 401);
  end if;
  wait := public.webhook_hit('lf:' || f.id::text, 60, 5);
  if wait = 0 then wait := public.webhook_hit('lfh:' || f.id::text, 3600, 30); end if;
  if random() < 0.01 then
    execute 'del' || 'ete from public.webhook_rate where at < now() - interval ''2 hours''';
  end if;
  if wait > 0 then return jsonb_build_object('code', 429, 'retry_after', wait); end if;
  return jsonb_build_object('ok', true);
end $function$;

-- public.lobby_text_problem(t text)
CREATE OR REPLACE FUNCTION public.lobby_text_problem(t text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(t, '') = '' then return null; end if;
  if public.has_adult_link(t) then return 'Links to that site aren''t allowed on Yapper.'; end if;
  if public.has_slur(t) or public.has_sexual_spam(t) then return 'Some of that text isn''t allowed'; end if;
  return null;
end $function$;

-- public.log_clean(t text, maxlen integer)  [security definer]
CREATE OR REPLACE FUNCTION public.log_clean(t text, maxlen integer DEFAULT 600)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m text[]; out text := coalesce(t, '');
begin
  for m in select regexp_matches(out, '<@([0-9a-f-]{36})>', 'g') loop
    out := replace(out, '<@' || m[1] || '>', '@' || public.log_name(m[1]::uuid));
  end loop;
  out := regexp_replace(out, '@(everyone|here)', '@​\1', 'gi');
  out := replace(out, E'\n', ' ');
  if length(out) > maxlen then out := left(out, maxlen) || '…'; end if;
  return out;
end $function$;

-- public.log_mod_delete()  [security definer]
CREATE OR REPLACE FUNCTION public.log_mod_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(current_setting('yapper.bulk', true), '') = '1' then return old; end if;
  if auth.uid() is not null and old.author_id <> auth.uid() and public.is_site_mod() and not public.is_site_admin() then
    -- Removed because its whole channel (or server) was deleted, e.g. a ticket closed: still logged, but not refused
    -- as "moderating another moderator" (only single messages are).
    if pg_trigger_depth() <= 1 then perform public.mod_guard('delete', old.author_id, ''); end if;
    insert into public.mod_log (actor, action, target_id, message_id, reason) values (auth.uid(), 'delete', old.author_id, old.id, left(coalesce(old.content, ''), 120));
  end if;
  return old;
end;
$function$;

-- public.log_name(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.log_name(uid uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select coalesce(display_name, username) from public.profiles where id = uid), 'someone')
$function$;

-- public.log_perm_name(k text)
CREATE OR REPLACE FUNCTION public.log_perm_name(k text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select initcap(replace(k, '_', ' '))
$function$;

-- public.logger_bans()  [security definer]
CREATE OR REPLACE FUNCTION public.logger_bans()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    perform public.bot_log_kind('members', new.server_id, '🔨 **' || public.log_name(new.user_id) || '** was banned'
      || case when new.banned_by is not null then ' by **' || public.log_name(new.banned_by) || '**' else '' end);
  else
    perform public.bot_log_kind('members', old.server_id, '✅ **' || public.log_name(old.user_id) || '** was unbanned'
      || case when auth.uid() is not null then ' by **' || public.log_name(auth.uid()) || '**' else '' end);
  end if;
  return null;
exception when others then return null;
end $function$;

-- public.logger_members()  [security definer]
CREATE OR REPLACE FUNCTION public.logger_members()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare actor uuid := auth.uid(); age interval; txt text;
begin
  if current_setting('yapper.bulk', true) = '1' then return null; end if;
  if public.bot_cfg(coalesce(new.server_id, old.server_id), 'logger') is null then return null; end if;
  if tg_op = 'INSERT' then
    select now() - created_at into age from public.profiles where id = new.user_id;
    txt := '📥 **' || public.log_name(new.user_id) || '** joined'
      || case when age < interval '1 day' then ' · ⚠️ account made today'
              when age < interval '7 days' then ' · account made ' || extract(day from age)::int || ' days ago' else '' end;
    perform public.bot_log_kind('members', new.server_id, txt);
  else
    txt := '📤 **' || public.log_name(old.user_id) || '** '
      || case when actor is not null and actor <> old.user_id then 'was kicked by **' || public.log_name(actor) || '**' else 'left' end;
    perform public.bot_log_kind('members', old.server_id, txt);
  end if;
  return null;
exception when others then return null;
end $function$;

-- public.logger_messages()  [security definer]
CREATE OR REPLACE FUNCTION public.logger_messages()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare srcpriv boolean; sid uuid; cname text; cfg jsonb; actor uuid := auth.uid(); txt text;
begin
  if current_setting('yapper.bulk', true) = '1' or current_setting('yapper.bot', true) = '1' then return null; end if;
  select server_id, name, private into sid, cname, srcpriv from public.channels where id = old.channel_id;
  if sid is null then return null; end if;
  cfg := public.bot_cfg(sid, 'logger');
  if cfg is null or (cfg ->> 'channel_id') = old.channel_id::text then return null; end if;
  -- Private channels (staff rooms, tickets) only go to a private log, never to one everyone can read.
  if srcpriv and not coalesce((select private from public.channels where id = nullif(cfg ->> 'channel_id', '')::uuid), false) then return null; end if;
  if exists (select 1 from public.bot_accounts where user_id = old.author_id) then return null; end if;
  -- Logger+: channels to leave out of the log.
  if jsonb_typeof(cfg -> 'ignore') = 'array' and (cfg -> 'ignore') ? old.channel_id::text and public.server_plus_on(sid) then return null; end if;
  if tg_op = 'UPDATE' then
    if new.content is not distinct from old.content then return null; end if;
    txt := '✏️ **' || public.log_name(old.author_id) || '** edited a message in **#' || cname || '**'
      || E'\nBefore: ' || public.log_clean(old.content, 500) || E'\nAfter: ' || public.log_clean(new.content, 500);
  else
    txt := '🗑️ A message by **' || public.log_name(old.author_id) || '** in **#' || cname || '** was deleted'
      || case when actor is not null and actor <> old.author_id then ' by **' || public.log_name(actor) || '**' else '' end
      || case when coalesce(old.content, '') <> '' then E'\n' || public.log_clean(old.content, 800) else '' end
      || case when old.attachment_path is not null then E'\n(it had an attachment)' else '' end;
  end if;
  perform public.bot_log(sid, txt);
  return null;
exception when others then return null;
end $function$;

-- public.logger_pins()  [security definer]
CREATE OR REPLACE FUNCTION public.logger_pins()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; cname text; srcpriv boolean; cfg jsonb; actor uuid := coalesce(new.pinned_by, auth.uid()); txt text;
begin
  if current_setting('yapper.bulk', true) = '1' or current_setting('yapper.bot', true) = '1' then return null; end if;
  select server_id, name, private into sid, cname, srcpriv from public.channels where id = new.channel_id;
  srcpriv := coalesce(srcpriv, false) or public.channel_overrides_live(new.channel_id);
  if sid is null then return null; end if;
  cfg := public.bot_cfg(sid, 'logger');
  if cfg is null or (cfg ->> 'channel_id') = new.channel_id::text then return null; end if;
  if srcpriv and not coalesce((select private from public.channels where id = nullif(cfg ->> 'channel_id', '')::uuid), false) then return null; end if;
  if jsonb_typeof(cfg -> 'ignore') = 'array' and (cfg -> 'ignore') ? new.channel_id::text and public.server_plus_on(sid) then return null; end if;
  if new.pinned_at is not null then
    txt := '📌 **' || public.log_name(actor) || '** pinned a message by **' || public.log_name(new.author_id) || '** in **#' || cname || '**';
  else
    txt := '📌 ' || case when auth.uid() is not null then '**' || public.log_name(auth.uid()) || '** unpinned' else 'Unpinned' end
      || ' a message by **' || public.log_name(new.author_id) || '** in **#' || cname || '**';
  end if;
  if coalesce(new.content, '') <> '' then txt := txt || E'\n' || public.log_clean(new.content, 300); end if;
  perform public.bot_log(sid, txt);
  return null;
exception when others then return null;
end $function$;

-- public.logger_role_edits()  [security definer]
CREATE OR REPLACE FUNCTION public.logger_role_edits()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare actor uuid := auth.uid(); sid uuid := coalesce(new.server_id, old.server_id); txt text; on_list text[]; off_list text[];
  op jsonb; np jsonb;
begin
  if actor is null or current_setting('yapper.bot', true) = '1' or current_setting('yapper.bulk', true) = '1' then return null; end if;
  if public.bot_cfg(sid, 'logger') is null then return null; end if;
  if tg_op = 'INSERT' then
    txt := '🏷️ **' || public.log_name(actor) || '** made the **' || public.log_clean(new.name, 100) || '** role';
  elsif tg_op = 'DELETE' then
    if not exists (select 1 from public.servers where id = old.server_id) then return null; end if;
    txt := '🏷️ **' || public.log_name(actor) || '** deleted the **' || public.log_clean(old.name, 100) || '** role';
  else
    op := coalesce(old.perms, '{}'::jsonb) || jsonb_build_object('manage_server_legacy', old.manage_server, 'manage_messages_legacy', old.manage_messages);
    np := coalesce(new.perms, '{}'::jsonb) || jsonb_build_object('manage_server_legacy', new.manage_server, 'manage_messages_legacy', new.manage_messages);
    select array_agg(distinct public.log_perm_name(replace(k, '_legacy', ''))) into on_list
      from jsonb_object_keys(np) k where coalesce((np ->> k)::boolean, false) and not coalesce((op ->> k)::boolean, false);
    select array_agg(distinct public.log_perm_name(replace(k, '_legacy', ''))) into off_list
      from jsonb_object_keys(op) k where coalesce((op ->> k)::boolean, false) and not coalesce((np ->> k)::boolean, false);
    if on_list is null and off_list is null and new.name is not distinct from old.name then return null; end if;
    txt := '🛡️ **' || public.log_name(actor) || '** changed the **' || public.log_clean(new.name, 100) || '** role'
      || case when new.name is distinct from old.name then E'\n' || 'Renamed from **' || public.log_clean(old.name, 100) || '**' else '' end
      || case when on_list is not null then E'\n' || 'Turned on: ' || array_to_string(on_list, ', ') else '' end
      || case when off_list is not null then E'\n' || 'Turned off: ' || array_to_string(off_list, ', ') else '' end;
  end if;
  perform public.bot_log_kind('members', sid, txt);
  return null;
exception when others then return null;
end $function$;

-- public.logger_roles()  [security definer]
CREATE OR REPLACE FUNCTION public.logger_roles()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare actor uuid := auth.uid(); rname text; r record;
begin
  if actor is null or current_setting('yapper.bot', true) = '1' or current_setting('yapper.bulk', true) = '1' then return null; end if;
  if tg_op = 'INSERT' then r := new; else r := old; end if;
  select name into rname from public.roles where id = r.role_id;
  if rname is null then return null; end if;
  if tg_op = 'DELETE' and not exists (select 1 from public.server_members where server_id = r.server_id and user_id = r.user_id) then return null; end if;
  perform public.bot_log_kind('members', r.server_id, '🏷️ **' || public.log_name(actor) || '** '
    || case when tg_op = 'INSERT' then 'gave **' || public.log_name(r.user_id) || '** the **' || rname || '** role'
            else 'took the **' || rname || '** role from **' || public.log_name(r.user_id) || '**' end);
  return null;
exception when others then return null;
end $function$;

-- public.logger_timeouts()  [security definer]
CREATE OR REPLACE FUNCTION public.logger_timeouts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.until <= now() then
    perform public.bot_log_kind('members', new.server_id, '🔈 **' || public.log_name(new.user_id) || '**''s timeout was lifted'
      || case when auth.uid() is not null then ' by **' || public.log_name(auth.uid()) || '**' else '' end);
  else
    perform public.bot_log_kind('members', new.server_id, '⏳ **' || public.log_name(new.user_id) || '** was timed out until '
      || to_char(new.until at time zone 'UTC', 'Mon DD HH24:MI') || ' UTC'
      || case when new.set_by is not null then ' by **' || public.log_name(new.set_by) || '**' else '' end
      || case when coalesce(new.reason, '') <> '' then ': ' || public.log_clean(new.reason, 200) else '' end);
  end if;
  return null;
exception when others then return null;
end $function$;

-- public.login_risk(p_ip text, p_dev text, p_uname text)  [security definer]
CREATE OR REPLACE FUNCTION public.login_risk(p_ip text, p_dev text, p_uname text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  raw_ip text := nullif(nullif(coalesce(p_ip, ''), ''), 'unknown');
  dh text; ih text; crowd int := 0; ip_attempts int := 0; ip_fails int := 0; user_fails int := 0; banned boolean := false;
begin
  p_ip := public.ip_key(coalesce(p_ip, ''));
  if p_dev ~ '^[A-Za-z0-9_-]{16,64}$' then dh := public.evasion_hash(p_dev); end if;

  if p_ip is not null then
    ih := public.evasion_hash(p_ip);
    select greatest(
      (select count(*) from (select distinct d.user_id from public.user_devices d
                              where d.kind = 'ip' and d.h = ih and d.last_seen > now() - interval '30 days' limit 31) a),
      (select count(*) from (select 1 from public.signup_log s
                              where s.ip = p_ip and s.created_at > now() - interval '30 days' limit 31) b))
      into crowd;
    select count(*) into ip_attempts
      from (select 1 from public.login_attempts a
             where a.ip = raw_ip and a.at > now() - interval '45 minutes' limit 11) x;
    select count(*) into ip_fails
      from (select 1 from public.login_attempts a
             where a.ip = raw_ip and a.ok = false and a.at > now() - interval '45 minutes' limit 26) x;
  end if;
  select count(*) into user_fails
    from (select 1 from public.login_attempts a
           where lower(a.username) = lower(nullif(p_uname, '')) and a.ok = false
             and a.at > now() - interval '45 minutes' limit 11) x;

  if dh is not null or ih is not null then
    select exists (
      select 1 from public.user_devices d join public.site_bans b on b.user_id = d.user_id
       where (b.expires_at is null or b.expires_at > now())
         and ((dh is not null and d.kind = 'dev' and d.h = dh and d.last_seen > now() - interval '90 days')
           or (ih is not null and crowd <= 30 and d.kind = 'ip' and d.h = ih and d.last_seen > now() - interval '14 days'))
       limit 1)
      into banned;
  end if;
  if banned then return 'block'; end if;
  if ip_fails >= 25 then return 'block'; end if;
  if user_fails >= 10 then return 'captcha'; end if;
  if dh is not null and exists (
       select 1 from public.user_devices where kind = 'dev' and h = dh and last_seen > now() - interval '90 days')
  then
    return case when ip_fails < 10 and (crowd > 30 or ip_attempts < 10) then 'clear' else 'captcha' end;
  end if;
  if p_ip is not null and ip_attempts >= 10 and crowd <= 30 then return 'limit'; end if;
  return 'captcha';
end $function$;

-- public.logout_everywhere_signal()  [security definer]
CREATE OR REPLACE FUNCTION public.logout_everywhere_signal()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); r record;
begin
  if uid is null then return; end if;
  select uid as user_id, now() as at into r;
  perform public.bc('user:' || uid::text, 'logout_all', 'INSERT', 'sessions', 'auth', r, null::record);
end $function$;

-- public.lookalike_key(t text)
CREATE OR REPLACE FUNCTION public.lookalike_key(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select translate(lower(coalesce(t, '')), '013457$@!|l', 'oieastsailli');
$function$;

-- public.make_server_template(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.make_server_template(sid uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare d jsonb; c text; nm text;
begin
  if not public.server_perm(sid, 'manage_server') then raise exception 'Only server managers can share a template'; end if;
  select name into nm from public.servers where id = sid;
  with cats as (
    select id, name, position, (row_number() over (order by position, created_at, id))::int - 1 as i
    from public.channel_categories where server_id = sid
    order by position, created_at, id
    limit 50
  )
  select jsonb_build_object(
    'categories', coalesce((select jsonb_agg(jsonb_build_object('name', k.name, 'position', k.position) order by k.i) from cats k), '[]'::jsonb),
    'channels', coalesce((select jsonb_agg(jsonb_build_object('kind', ch.kind, 'name', ch.name, 'position', ch.position, 'read_only', coalesce(ch.read_only, false),
                                                              'slowmode', coalesce(ch.slowmode, 0), 'category', (select k.i from cats k where k.id = ch.category_id)) order by ch.position)
                          from public.channels ch where ch.server_id = sid and ch.kind in ('text', 'voice') and ch.ticket_by is null), '[]'::jsonb),
    'roles', coalesce((select jsonb_agg(jsonb_build_object('name', name, 'color', color, 'position', position, 'manage_server', manage_server, 'manage_messages', manage_messages, 'perms', coalesce(perms, '{}'::jsonb)) order by position)
                       from public.roles where server_id = sid), '[]'::jsonb),
    'everyone_perms', coalesce((select everyone_perms from public.servers where id = sid), '{}'::jsonb)
  ) into d;
  select code into c from public.server_templates where server_id = sid;
  if c is null then
    c := lower(substr(encode(gen_random_bytes(6), 'hex'), 1, 10));
    insert into public.server_templates (code, server_id, created_by, name, data) values (c, sid, auth.uid(), nm, d);
  else
    update public.server_templates set data = d, name = nm, updated_at = now() where code = c;
  end if;
  return c;
end; $function$;

-- public.manager_guard(action text, target uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.manager_guard(action text, target uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if public.is_site_admin() then return; end if;
  if not public.is_site_manager() then raise exception 'Admins only'; end if;
  perform pg_advisory_xact_lock(hashtextextended('manager_cap:' || auth.uid()::text, 0));
  if target is null then raise exception 'Pick someone'; end if;
  if target = auth.uid() then raise exception 'You can''t change your own account'; end if;
  if exists (select 1 from public.site_admins where user_id = target) then raise exception 'Admins can''t be changed'; end if;
  if exists (select 1 from public.site_managers where user_id = target) then raise exception 'Only an admin can change Management'; end if;
  if action = 'badge' then
    select count(*) into n from public.mod_log where actor = auth.uid() and created_at > now() - interval '1 hour'
       and mod_log.action in ('badge_given', 'badge_removed');
    if n >= 30 then raise exception 'That''s 30 badges this hour. Wait a bit or ask an admin'; end if;
  elsif action = 'creator' then
    select count(*) into n from public.mod_log where actor = auth.uid() and created_at > now() - interval '24 hours'
       and mod_log.action in ('creator_approved', 'content_approved');
    if n >= 10 then raise exception 'That''s 10 Creator approvals today. Ask an admin for more'; end if;
  elsif action = 'creator_other' then
    null;
  elsif action = 'ban' then
    select count(*) into n from public.mod_log where actor = auth.uid() and created_at > now() - interval '24 hours'
       and mod_log.action = 'ban';
    if n >= 25 then raise exception 'That''s 25 bans today. Ask an admin for more'; end if;
  else
    select count(*) into n from public.mod_log where actor = auth.uid() and created_at > now() - interval '24 hours'
       and mod_log.action in ('mod_added', 'mod_removed', 'mod_suspended', 'head_mod_added', 'head_mod_removed',
                              'dev_added', 'dev_removed', 'cm_added', 'cm_removed');
    if n >= 25 then raise exception 'That''s 25 staff changes today. Ask an admin for more'; end if;
  end if;
end;
$function$;

-- public.manual_auto_roles(sids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.manual_auto_roles(sids uuid[])
 RETURNS TABLE(server_id uuid, user_id uuid, role_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select mr.server_id, mr.user_id, mr.role_id
  from public.member_roles mr
  where mr.manual and mr.server_id = any(sids)
    and exists (select 1 from public.server_members sm where sm.server_id = mr.server_id and sm.user_id = auth.uid());
$function$;

-- public.mark_manual_role()  [security definer]
CREATE OR REPLACE FUNCTION public.mark_manual_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- A "joined before X" role given by hand to someone who joined after X: remembered so the app can fetch just these.
  new.manual := exists (
    select 1 from public.roles r join public.server_members m on m.server_id = r.server_id and m.user_id = new.user_id
    where r.id = new.role_id and r.auto = 'before' and (r.auto_before is null or m.joined_at >= r.auto_before));
  return new;
end; $function$;

-- public.mark_read(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.mark_read(cid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.can_access_channel(cid) then return; end if;
  insert into public.channel_reads (user_id, channel_id, last_read_at)
    values (auth.uid(), cid, now())
    on conflict (user_id, channel_id) do update set last_read_at = now();
end;
$function$;

-- public.match_cache_forget(p_users uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.match_cache_forget(p_users uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_users is null or cardinality(p_users) = 0 then return; end if;
  if cardinality(p_users) > 50 then
    -- A server removed or a mass kick: cheaper to rebuild every fresh list than to look for each person.
    update public.match_cache set computed_at = '-infinity' where computed_at > now() - interval '6 hours';
    return;
  end if;
  -- Only lists that still count (under 6 hours old): older ones are rebuilt on open and ignored by sees_user anyway.
  update public.match_cache c set computed_at = '-infinity'
   where c.computed_at > now() - interval '6 hours'
     and (c.user_id = any (p_users)
          or exists (select 1 from jsonb_array_elements(c.results) e where e ->> 'user_id' = any (p_users::text[])));
end $function$;

-- public.match_cache_left_server()  [security definer]
CREATE OR REPLACE FUNCTION public.match_cache_left_server()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ids uuid[];
begin
  select array_agg(distinct o.user_id) into ids from gone o;
  perform public.match_cache_forget(ids);
  return null;
end $function$;

-- public.match_cache_link_changed()  [security definer]
CREATE OR REPLACE FUNCTION public.match_cache_link_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.match_cache_forget(array[coalesce(old.user_id, new.user_id)]);
  return null;
end $function$;

-- public.match_compute(p_user uuid, p_limit integer)  [security definer]
CREATE OR REPLACE FUNCTION public.match_compute(p_user uuid, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  bot_ids uuid[] := '{}';
  res jsonb;
begin
  if p_user is null then return '[]'::jsonb; end if;
  p_limit := least(greatest(coalesce(p_limit, 20), 1), 50);
  if to_regclass('public.bots') is not null then
    execute 'select coalesce(array_agg(id), ''{}'') from public.bots' into bot_ids;
  end if;

  with mine as materialized (
    select i.source, i.kind, i.item_id, i.title, i.weight
    from public.media_interests i
    where i.user_id = p_user and public.interest_ok(p_user, i.source)
  ),
  pop as materialized (
    select m.source, m.kind, m.item_id,
           (select count(*) from (select 1 from public.media_interests i
                                  where i.source = m.source and i.kind = m.kind and i.item_id = m.item_id limit 2001) z) as n
    from mine m
  ),
  vis as materialized (
    select l.user_id, l.source from public.media_links l
    where l.is_public and (l.source <> 'lastfm' or l.verified) /* 467: typed-in Last.fm names count for nobody */ and not coalesce((l.prefs ->> 'hidden')::boolean, false)
    union all
    select s.user_id, 'steam' from public.steam_links s
    where s.games_public and not coalesce((s.prefs ->> 'hidden')::boolean, false)
      and coalesce((s.prefs ->> 'show_games')::boolean, true)
  ),
  shared as (
    select o.user_id, m.kind, m.title, (m.weight * o.weight) / ln(1 + p.n) as pts
    from mine m
    join pop p on p.source = m.source and p.kind = m.kind and p.item_id = m.item_id
    join public.media_interests o on o.source = m.source and o.kind = m.kind and o.item_id = m.item_id and o.user_id <> p_user
    join vis v on v.user_id = o.user_id and v.source = o.source
    where p.n <= 2000
  ),
  shared_u as (
    select s.user_id, sum(s.pts) as pts, count(*) as n,
           (array_agg(jsonb_build_object('kind', s.kind, 'title', s.title) order by s.pts desc))[1:3] as top
    from shared s group by s.user_id
  ),
  srv as (
    select sm.user_id, s.name, 0.5 / ln(1 + greatest(s.member_count, 2)) as pts
    from public.server_members ms
    join public.servers s on s.id = ms.server_id
    cross join lateral (
      select m.user_id from public.server_members m
      where m.server_id = s.id and m.user_id <> p_user
      order by m.joined_at desc
      limit 500
    ) sm
    where ms.user_id = p_user
  ),
  srv_u as (
    select z.user_id, sum(z.pts) as pts, count(*) as n, (array_agg(z.name order by z.pts desc))[1:2] as top
    from srv z group by z.user_id
  ),
  cand as (
    select coalesce(a.user_id, b.user_id) as user_id, coalesce(a.pts, 0) + coalesce(b.pts, 0) as score,
           coalesce(a.n, 0) as items_n, coalesce(a.top, '{}'::jsonb[]) as items,
           coalesce(b.n, 0) as servers_n, coalesce(b.top, '{}'::text[]) as servers
    from shared_u a full join srv_u b on b.user_id = a.user_id
  ),
  best as (
    select c.* from cand c where c.user_id <> all (bot_ids)
    order by c.score desc, c.user_id limit 200
  ),
  ok as (
    select c.*
    from best c
    where not exists (select 1 from public.blocks b where (b.blocker = p_user and b.blocked = c.user_id) or (b.blocker = c.user_id and b.blocked = p_user))
      and not exists (select 1 from public.site_bans sb where sb.user_id = c.user_id)
      and not exists (select 1 from public.friendships f
                      where least(f.requester, f.addressee) = least(p_user, c.user_id)
                        and greatest(f.requester, f.addressee) = greatest(p_user, c.user_id))
      and coalesce((select ms.suggest_me from public.match_settings ms where ms.user_id = c.user_id), true)
    order by c.score desc, c.user_id
    limit p_limit
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'user_id', o.user_id,
      'score', round(o.score::numeric, 3),
      'items', to_jsonb(o.items),
      'items_n', o.items_n,
      'servers', to_jsonb(o.servers),
      'servers_n', o.servers_n
    ) order by o.score desc, o.user_id), '[]'::jsonb)
  into res
  from ok o;
  return res;
end $function$;

-- public.media_claim_refresh(p_user uuid, p_source text, p_gap_sec integer)  [security definer]
CREATE OR REPLACE FUNCTION public.media_claim_refresh(p_user uuid, p_source text, p_gap_sec integer)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with t as (
    insert into public.media_refresh_log as l (user_id, source, at) values (p_user, p_source, now())
    on conflict (user_id, source) do update set at = now()
      where l.at < now() - make_interval(secs => greatest(p_gap_sec, 60))
    returning 1
  )
  select exists (select 1 from t);
$function$;

-- public.media_interests_unlink()  [security definer]
CREATE OR REPLACE FUNCTION public.media_interests_unlink()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_table_name = 'steam_links' then
    execute 'de' || 'lete from public.media_interests where user_id = $1 and source = ''steam''' using old.user_id;
  else
    execute 'de' || 'lete from public.media_interests where user_id = $1 and source = $2' using old.user_id, old.source;
  end if;
  return old;
end $function$;

-- public.media_ok(b text, p text)  [security definer]
CREATE OR REPLACE FUNCTION public.media_ok(b text, p text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.media_scans where bucket = b and path = p and verdict = 'ok');
$function$;

-- public.media_save_refresh(p_user uuid, p_source text, p_account text, p_row jsonb, p_items jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.media_save_refresh(p_user uuid, p_source text, p_account text, p_row jsonb, p_items jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) > 150 then
    raise exception 'bad items';
  end if;
  update public.media_links set
    account_name = coalesce(p_row ->> 'account_name', account_name),
    handle = coalesce(p_row ->> 'handle', handle),
    avatar_url = case when p_row ? 'avatar_url' then p_row ->> 'avatar_url' else avatar_url end,
    profile_url = case when p_row ? 'profile_url' then p_row ->> 'profile_url' else profile_url end,
    is_public = coalesce((p_row ->> 'is_public')::boolean, is_public),
    data = coalesce(p_row -> 'data', data),
    refreshed_at = now(),
    next_refresh_at = now() + interval '1 day'
  where user_id = p_user and source = p_source and account_id = p_account;
  if not found then return false; end if;
  -- A private profile keeps the interests it had (p_items is then empty and means "nothing new").
  if coalesce((p_row ->> 'is_public')::boolean, true) then
    -- Written as execute so the Supabase MCP (which hangs on that keyword pair) can apply this file as is.
    execute 'de' || 'lete from public.media_interests where user_id = $1 and source = $2' using p_user, p_source;
    insert into public.media_interests (user_id, source, kind, item_id, title, weight)
    select p_user, p_source, i ->> 'kind', i ->> 'item_id', left(coalesce(i ->> 'title', ''), 200),
           least(1, greatest(0, coalesce((i ->> 'weight')::real, 0)))
    from jsonb_array_elements(p_items) i
    on conflict do nothing;
  end if;
  return true;
end $function$;

-- public.member_roles_by_person()
CREATE OR REPLACE FUNCTION public.member_roles_by_person()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.by_person := current_user = 'authenticated' and auth.uid() is not null and auth.uid() is distinct from new.user_id
    and coalesce(current_setting('yapper.bot', true), '') <> '1' and not public.is_bot_user(auth.uid());
  return new;
end $function$;

-- public.mention_keys(cid uuid, content text)
CREATE OR REPLACE FUNCTION public.mention_keys(cid uuid, content text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO ''
AS $function$
  select coalesce(array_agg(k), '{}'::text[])
  from (
    select distinct x[1] as u
    from regexp_matches(coalesce(content, ''), '<@([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})>', 'g') as x
  ) m
  cross join lateral (values (m.u), (cid::text || ':' || m.u)) as v(k);
$function$;

-- public.message_automod()  [security definer]
CREATE OR REPLACE FUNCTION public.message_automod()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare mu timestamptz; dup int; joined timestamptz;
begin
  if current_setting('yapper.bot', true) = '1' then return new; end if;
  if public.is_site_admin() then return new; end if;
  select muted_until into mu from public.profiles where id = new.author_id;
  if mu is not null and mu > now() then
    raise exception 'You''re timed out until % (%).', to_char(mu at time zone 'UTC', 'YYYY-MM-DD HH24:MI "UTC"'), coalesce((select muted_reason from public.profiles where id = new.author_id), 'moderation') using errcode = 'check_violation';
  end if;
  if public.has_sexual_spam(new.content) then
    raise exception 'Sexual content and selling it aren''t allowed on Yapper.' using errcode = 'check_violation';
  end if;
  if public.has_self_harm_incitement(new.content) then
    raise exception 'Telling someone to hurt themselves isn''t allowed on Yapper.' using errcode = 'check_violation';
  end if;
  -- Yapper HQ: keyboard mash / spaced-out letters / one character over and over (216), new messages and edits.
  -- Cheapest test first: only HQ messages ever run spam_shape. Staff skip it.
  if length(new.content) >= 26
     and (select c.server_id from public.channels c where c.id = new.channel_id) = (select default_server_id from public.app_settings limit 1)
     and public.spam_shape(new.content) is not null
     and not public.is_staff() then
    raise exception 'That looks like spam. Type it like a normal message.' using errcode = 'check_violation';
  end if;
  if tg_op = 'INSERT' then
    if length(new.content) > 3 then
      select count(*) into dup from public.messages where author_id = new.author_id and content = new.content and created_at > now() - interval '60 seconds';
      if dup >= 3 then raise exception 'You already sent that. Slow down.' using errcode = 'check_violation'; end if;
    end if;
    if (length(new.content) - length(replace(new.content, '@', ''))) >= 8 then
      select created_at into joined from auth.users where id = new.author_id;
      if joined > now() - interval '7 days' then
        raise exception 'New accounts can''t mention that many people at once.' using errcode = 'check_violation';
      end if;
    end if;
  end if;
  return new;
end; $function$;

-- public.message_channel(mid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.message_channel(mid uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select channel_id from public.messages where id = mid;
$function$;

-- public.message_defaults()  [security definer]
CREATE OR REPLACE FUNCTION public.message_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare other uuid;
begin
  new.created_at := clock_timestamp();
  -- "Only friends can message me" also covers DMs opened before it was switched on,
  -- until they reply (a conversation they took part in stays open).
  if auth.uid() = new.author_id and coalesce(current_setting('yapper.bot', true), '') <> '1' and exists (select 1 from public.channels c where c.id = new.channel_id and c.kind = 'dm') then
    select m.user_id into other from public.channel_members m where m.channel_id = new.channel_id and m.user_id <> new.author_id limit 1;
    if other is not null and (select p.dms_from from public.profiles p where p.id = other) = 'friends'
       and not public.are_friends(new.author_id, other) and not public.is_staff()
       and not exists (select 1 from public.messages x where x.channel_id = new.channel_id and x.author_id = other) then
      raise exception 'They only take messages from friends. Send them a friend request.' using errcode = 'check_violation';
    end if;
  end if;
  new.edited_at := null;
  new.pinned_at := null;
  new.pinned_by := null;
  -- Embeds come only from bots (the bot API sets yapper.bot).
  if coalesce(current_setting('yapper.bot', true), '') <> '1' then new.embeds := null; new.components := null; end if;
  if new.reply_to_id is not null and not exists (
    select 1 from public.messages where id = new.reply_to_id and channel_id = new.channel_id
  ) then
    new.reply_to_id := null;
  end if;
  return new;
end;
$function$;

-- public.message_edit_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.message_edit_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; cp boolean;
begin
  new.id := old.id;
  new.channel_id := old.channel_id;
  new.author_id := old.author_id;
  new.created_at := old.created_at;
  new.attachment_path := old.attachment_path;
  new.attachment_width := old.attachment_width;
  new.attachment_height := old.attachment_height;
  new.attachment_name := old.attachment_name;
  new.attachment_size := old.attachment_size;
  if coalesce(current_setting('yapper.bot', true), '') <> '1' then new.embeds := old.embeds; new.components := old.components; end if;
  -- Only the author can hide link previews on their message.
  if new.suppress_embeds is distinct from old.suppress_embeds and auth.uid() is not null and auth.uid() <> old.author_id then new.suppress_embeds := old.suppress_embeds; end if;
  new.reply_to_id := case when new.reply_to_id is null then null else old.reply_to_id end;
  if session_user = 'authenticated' or current_setting('request.jwt.claim.role', true) = 'authenticated' or (current_setting('request.jwt.claims', true)::jsonb ->> 'role') = 'authenticated' then
    if coalesce(current_setting('yapper.pin', true), '') <> '1' then
      new.pinned_at := old.pinned_at;
      new.pinned_by := old.pinned_by;
    end if;
    if new.content is distinct from old.content then
      if exists (select 1 from public.profiles p where p.id = old.author_id and p.muted_until > now()) then
        raise exception 'You''re timed out, so you can''t edit messages right now.' using errcode = 'check_violation';
      end if;
      select server_id into sid from public.channels where id = old.channel_id;
      if sid is not null and public.server_timed_out(sid, old.author_id) is not null then
        raise exception 'You''re timed out in this server, so you can''t edit messages right now.' using errcode = 'check_violation';
      end if;
    end if;
  end if;
  if new.content is distinct from old.content and coalesce(current_setting('yapper.bot', true), '') = '1' then
    new.content := public.fix_role_pings_bot(old.channel_id, new.content, old.author_id);
  end if;
  -- Edits follow the same rules as sending: no @everyone without the permission, no links without Embed Links.
  if new.content is distinct from old.content and auth.uid() is not null and coalesce(current_setting('yapper.bot', true), '') <> '1' then
    if sid is null then select server_id into sid from public.channels where id = old.channel_id; end if;
    if sid is null then new.content := public.fix_role_pings(null, old.channel_id, false, new.content); end if;
    if sid is not null then
      select exists (select 1 from public.feature_flags f where f.key = 'channel_perms'
                              and (f.mode = 'everyone' or (f.mode = 'test' and c.server_id = any(f.servers))))
                  and exists (select 1 from public.channel_overrides o where o.channel_id = c.id or o.category_id = c.category_id) into cp
        from public.channels c where c.id = old.channel_id;
      -- 593: a thread uses its parent's overrides.
      if exists (select 1 from public.channels t where t.id = old.channel_id and t.kind = 'thread') then cp := public.channel_overrides_live(old.channel_id); end if;
      if exists (select 1 from public.servers s where s.id = sid and s.rules_channel_id = old.channel_id)
         and public.feature_on('rules_channel', sid)
         and not public.server_perm(sid, 'manage_server') then
        raise exception 'Only server managers can edit messages in the rules channel' using errcode = 'check_violation';
      end if;
      new.content := public.fix_role_pings(sid, old.channel_id, cp, new.content);
      if strpos(new.content, '#') > 0 and public.feature_on('big_text_perm', sid)
         and public.has_big_text(new.content) and not public.has_big_text(old.content)
         and not (case when cp then public.channel_perm(old.channel_id, 'use_headings') else public.server_perm(sid, 'use_headings') end) then
        raise exception 'You can''t use big text (# headings) here' using errcode = 'check_violation';
      end if;
      if new.content ~ '(^|[^A-Za-z0-9_@])@(everyone|here)\M'
         and not (case when cp then public.channel_perm(old.channel_id, 'mention_everyone') else public.server_perm(sid, 'mention_everyone') end) then
        new.content := regexp_replace(new.content, '(^|[^A-Za-z0-9_@])@(everyone|here)\M', '\1@' || chr(8203) || '\2', 'g');
      end if;
      if new.content ~* 'https?://' and coalesce(old.content, '') !~* 'https?://'
         and not (case when cp then public.channel_perm(old.channel_id, 'embed_links') else public.server_perm(sid, 'embed_links') end) then
        raise exception 'You can''t post links here';
      end if;
    end if;
  end if;
  if new.content is distinct from old.content or new.embeds is distinct from old.embeds then new.edited_at := now(); else new.edited_at := old.edited_at; end if;
  return new;
end $function$;

-- public.message_edit_slowmode()  [security definer]
CREATE OR REPLACE FUNCTION public.message_edit_slowmode()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.channels; me uuid := auth.uid(); slow int; mark timestamptz; wait int;
begin
  if new.content is not distinct from old.content then return new; end if;
  if coalesce(current_setting('yapper.bot', true), '') = '1' or me is null then return new; end if;
  select * into c from public.channels where id = old.channel_id;
  if c.server_id is null then return new; end if;
  slow := least(greatest(coalesce(c.slowmode, 0), case when c.auto_slow_until > now() then 5 else 0 end), 900);
  if slow <= 0 then return new; end if;
  -- A quick fix right after posting is free.
  if old.edited_at is null and old.created_at > now() - interval '2 minutes' then return new; end if;
  if public.channel_allows(c.id, 'manage_messages') then return new; end if;
  perform pg_advisory_xact_lock(hashtext('slowedit:' || me::text || ':' || c.id::text));
  select at into mark from public.post_marks where channel_id = c.id and author_id = me and kind = 'edit';
  if mark is not null and mark > now() - make_interval(secs => slow) then
    wait := greatest(1, ceil(extract(epoch from (mark + make_interval(secs => slow) - now()))));
    raise exception 'Slowmode is on. You can edit again in %s', wait using errcode = 'P0001';
  end if;
  insert into public.post_marks (channel_id, author_id, kind, at) values (c.id, me, 'edit', now())
    on conflict (channel_id, author_id, kind) do update set at = excluded.at;
  return new;
end $function$;

-- public.message_hate_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.message_hate_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare txt text; joined timestamptz; hq uuid; emb jsonb := to_jsonb(new) -> 'embeds';
begin
  if exists (select 1 from public.bot_accounts where user_id = new.author_id) then return new; end if;
  if tg_op = 'UPDATE' and new.content is not distinct from old.content
     and emb is not distinct from (to_jsonb(old) -> 'embeds') then return new; end if;

  txt := coalesce(new.content, '');
  if emb is not null and jsonb_typeof(emb) in ('array', 'object') then
    txt := txt || ' ' || coalesce((select string_agg(v #>> '{}', ' ')
      from jsonb_path_query(emb, 'strict $.**') v where jsonb_typeof(v) = 'string'), '');
  end if;
  if btrim(txt) = '' then return new; end if;

  if public.has_hate(txt) then
    raise exception 'Hate symbols and Nazi slogans aren''t allowed on Yapper.' using errcode = 'check_violation';
  end if;

  if public.art_count(txt) >= 40 then
    select created_at into joined from public.profiles where id = new.author_id;
    if joined is null or joined > now() - interval '7 days' then
      raise exception 'Big text-art messages are off for new accounts. Try again in a few days.' using errcode = 'check_violation';
    end if;
    select default_server_id into hq from public.app_settings where id;
    if hq is not null and exists (select 1 from public.channels c where c.id = new.channel_id and c.server_id = hq) then
      raise exception 'Text-art messages aren''t allowed in Yapper HQ.' using errcode = 'check_violation';
    end if;
  end if;
  return new;
end; $function$;

-- public.message_length()  [security definer]
CREATE OR REPLACE FUNCTION public.message_length()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int; lim int := 2000;
begin
  n := char_length(regexp_replace(new.content, '<a?:([A-Za-z0-9_]{2,32}):[0-9a-f-]{36}>', ':\1:', 'g'));
  -- The stored form of a custom emoji (<:name:uuid>) is far longer than what was typed; the table's hard cap is on
  -- the stored text, so say so before it fails as a bare constraint error.
  if char_length(new.content) > 4000 then
    raise exception 'That message is too long with those custom emojis in it. Trim it a bit' using errcode = 'check_violation';
  end if;
  -- An edit that doesn't make the message longer always goes through: a 3000-character message sent on Plus can
  -- still have a typo fixed after Plus runs out.
  if tg_op = 'UPDATE' and n <= char_length(regexp_replace(old.content, '<a?:([A-Za-z0-9_]{2,32}):[0-9a-f-]{36}>', ':\1:', 'g')) then
    return new;
  end if;
  if n > 2000 and public.feature_on_for_me('plus_4000')
     and exists (select 1 from public.profiles p where p.id = new.author_id and p.plus_until > now()) then
    lim := 4000;
  end if;
  if n > lim then
    raise exception 'Messages can be up to % characters', lim using errcode = 'check_violation';
  end if;
  return new;
end;
$function$;

-- public.message_onboarding_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.message_onboarding_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; o public.server_onboarding;
begin
  if current_setting('yapper.bot', true) = '1' or new.author_id is null then return new; end if;
  select c.server_id into sid from public.channels c where c.id = new.channel_id;
  if sid is null then return new; end if;
  select * into o from public.server_onboarding where server_id = sid;
  if o.server_id is null or not o.enabled or not o.required or o.enabled_at is null then return new; end if;
  if not public.feature_on('server_onboarding', sid) then return new; end if;
  if exists (select 1 from public.onboarding_choices c join public.server_members m on m.server_id = c.server_id and m.user_id = c.user_id
             where c.server_id = sid and c.user_id = new.author_id and c.done_at >= m.joined_at) then return new; end if;
  if not exists (select 1 from public.server_members m where m.server_id = sid and m.user_id = new.author_id and m.joined_at >= o.enabled_at) then
    return new;
  end if;
  if public.server_perm(sid, 'manage_messages') then return new; end if;
  raise exception 'Finish onboarding to chat in this server' using errcode = 'check_violation';
end $function$;

-- public.message_perm_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.message_perm_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; cp boolean; vk text;
begin
  if current_setting('yapper.bot', true) = '1' then new.content := public.fix_role_pings_bot(new.channel_id, new.content, new.author_id); return new; end if;
  select c.server_id, sid_live, c.kind into sid, cp, vk from (
    select c.server_id, c.kind, exists (select 1 from public.feature_flags f where f.key = 'channel_perms'
                              and (f.mode = 'everyone' or (f.mode = 'test' and c.server_id = any(f.servers))))
                  and exists (select 1 from public.channel_overrides o where o.channel_id = c.id or o.category_id = c.category_id) as sid_live
    from public.channels c where c.id = new.channel_id) c;
  -- 593: a thread uses its parent's overrides.
  if vk = 'thread' then cp := public.channel_overrides_live(new.channel_id); end if;
  if new.attachment_path is not null and exists (select 1 from public.media_scans ms where ms.bucket = 'attachments' and ms.path = new.attachment_path
       and ms.for_server is not null and ms.for_server is distinct from sid) then
    raise exception 'That file is over your upload limit, so it can only be sent in the supercharged server it was uploaded for' using errcode = 'check_violation';
  end if;
  if sid is null then new.content := public.fix_role_pings(null, new.channel_id, false, new.content); return new; end if;
  if exists (select 1 from public.servers s where s.id = sid and s.rules_channel_id = new.channel_id)
     and public.feature_on('rules_channel', sid)
     and not public.server_perm(sid, 'manage_server') then
    raise exception 'Only server managers can post in the rules channel' using errcode = 'check_violation';
  end if;
  if vk = 'voice' and not public.feature_on('voice_chat', sid) then
    raise exception 'Chat in voice channels isn''t on in this server' using errcode = 'check_violation';
  end if;
  if vk = 'voice' and cp and not public.channel_perm(new.channel_id, 'connect') then
    raise exception 'You need to be able to join this voice channel to chat in it' using errcode = 'check_violation';
  end if;
  if new.attachment_path is not null then
    if new.attachment_path ~ '(^|/)(r2-)?voice-[^/]*$' then
      if not (case when cp then public.channel_perm(new.channel_id, 'send_voice_messages') else public.server_perm(sid, 'send_voice_messages') end) then
        raise exception 'You can''t send voice messages here';
      end if;
    elsif not (case when cp then public.channel_perm(new.channel_id, 'attach_files') else public.server_perm(sid, 'attach_files') end) then
      raise exception 'You can''t attach files here';
    end if;
  end if;
  new.content := public.fix_role_pings(sid, new.channel_id, cp, new.content);
  if auth.uid() is not null and strpos(new.content, '#') > 0 and coalesce(current_setting('yapper.sys_post', true), '') <> '1'
     and public.feature_on('big_text_perm', sid) and public.has_big_text(new.content)
     and not (case when cp then public.channel_perm(new.channel_id, 'use_headings') else public.server_perm(sid, 'use_headings') end) then
    raise exception 'You can''t use big text (# headings) here' using errcode = 'check_violation';
  end if;
  if new.content ~ '(^|[^A-Za-z0-9_@])@everyone\M'
     and not (case when cp then public.channel_perm(new.channel_id, 'mention_everyone') else public.server_perm(sid, 'mention_everyone') end) then
    new.content := regexp_replace(new.content, '(^|[^A-Za-z0-9_@])@everyone\M', '\1@' || chr(8203) || 'everyone', 'g');
  end if;
  if new.content ~* 'https?://'
     and not (case when cp then public.channel_perm(new.channel_id, 'embed_links') else public.server_perm(sid, 'embed_links') end) then
    raise exception 'You can''t post links here';
  end if;
  return new;
end; $function$;

-- public.message_raid_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.message_raid_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare joined timestamptz; wait interval; def uuid; last_at timestamptz; recent int;
begin
  if current_setting('yapper.bot', true) = '1' then return new; end if;
  perform pg_advisory_xact_lock(hashtext('send:' || new.author_id::text));
  select count(*) into recent from public.messages
    where author_id = new.author_id and created_at > now() - interval '5 seconds' and id <> new.id;
  if recent >= 8 then
    raise exception 'You’re sending messages too fast. Wait a few seconds.' using errcode = 'check_violation';
  end if;
  select created_at into joined from public.profiles where id = new.author_id;
  -- 193: new account rule (chat mode). Only accounts younger than the longest option pay for the lookup.
  if joined > now() - interval '7 days' then
    perform public.new_account_chat_check(new.channel_id, new.author_id, joined);
  end if;
  select default_server_id, new_account_wait into def, wait from public.app_settings where id;
  if joined > now() - interval '1 hour' then
    select max(created_at) into last_at from public.messages where author_id = new.author_id and id <> new.id;
    if last_at > now() - interval '2 seconds' then
      raise exception 'Slow down a little. New accounts can send one message every 2 seconds' using errcode = 'check_violation';
    end if;
    if def is not null and joined > now() - wait
       and exists (select 1 from public.channels c where c.id = new.channel_id and c.server_id = def) then
      raise exception 'Welcome! New accounts can post here % after signing up.', trim(to_char(wait, 'MI "minutes"')) using errcode = 'check_violation';
    end if;
  end if;
  if new.content ~ '(^|[^A-Za-z0-9_@])@everyone\M' then
    if not exists (
      select 1 from public.channels c
      where c.id = new.channel_id
        and ((c.server_id is not null and (public.server_perm(c.server_id, 'manage_messages') or public.server_perm(c.server_id, 'mention_everyone')))
          or (c.server_id is null and c.kind = 'group'))
    ) then
      new.content := regexp_replace(new.content, '@everyone', '@​everyone', 'g');
    end if;
  end if;
  return new;
end; $function$;

-- public.message_slowmode()  [security definer]
CREATE OR REPLACE FUNCTION public.message_slowmode()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.channels; last_at timestamptz; mark timestamptz; wait int; slow int; bumped boolean;
begin
  if current_setting('yapper.bot', true) = '1' then return new; end if;
  select * into c from public.channels where id = new.channel_id;
  if c.server_id is null then return new; end if;
  -- 593: mods of a thread's parent skip its slowmode.
  if c.kind = 'thread' and public.channel_allows(c.id, 'manage_messages') then return new; end if;
  if (case when exists (select 1 from public.feature_flags f where f.key = 'channel_perms'
                              and (f.mode = 'everyone' or (f.mode = 'test' and c.server_id = any(f.servers))))
                  and exists (select 1 from public.channel_overrides o where o.channel_id = c.id or o.category_id = c.category_id)
       then public.channel_perm(c.id, 'manage_messages')
       else public.server_perm(c.server_id, 'manage_messages') end) then
    return new;
  end if;
  if public.server_locked(c.server_id) then
    raise exception 'This server is locked by its mods right now. Only mods can post.' using errcode = 'P0001';
  end if;
  slow := greatest(coalesce(c.slowmode, 0), case when c.auto_slow_until > now() then 5 else 0 end);
  if slow <= 0 then return new; end if;
  perform pg_advisory_xact_lock(hashtext('slow:' || new.author_id::text || ':' || new.channel_id::text));
  select at into mark from public.post_marks where channel_id = new.channel_id and author_id = new.author_id and kind = 'msg';
  if mark is not null and mark > now() - interval '15 seconds'
     and coalesce(new.content, '') = '' and new.reply_to_id is null and new.voice_secs is null
     and new.attachment_path ~* '\.(png|jpe?g|gif|webp|avif)$' then
    update public.post_marks set album_n = album_n + 1
      where channel_id = new.channel_id and author_id = new.author_id and kind = 'msg' and at = mark and album_n < 9
      returning true into bumped;
    if bumped then return new; end if;
  end if;
  select max(created_at) into last_at from public.messages
    where channel_id = new.channel_id and author_id = new.author_id and id <> new.id;
  last_at := greatest(last_at, mark);
  if last_at is not null and last_at > now() - make_interval(secs => slow) then
    wait := ceil(extract(epoch from (last_at + make_interval(secs => slow) - now())));
    raise exception 'Slowmode is on. You can send another message in %s', wait using errcode = 'P0001';
  end if;
  insert into public.post_marks (channel_id, author_id, kind, at, album_n) values (new.channel_id, new.author_id, 'msg', now(), 0)
    on conflict (channel_id, author_id, kind) do update set at = excluded.at, album_n = 0;
  return new;
end $function$;

-- public.message_system_guard()
CREATE OR REPLACE FUNCTION public.message_system_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    if coalesce(current_setting('yapper.system', true), '') <> '1' then new.system := null; end if;
  else
    new.system := old.system;
  end if;
  return new;
end $function$;

-- public.message_verification_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.message_verification_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; why text;
begin
  -- Webhook posts run with yapper.bot = '1' too (webhook_send). Not new.webhook: a client can send that field, and
  -- 155's guard only clears it after this trigger has run.
  if current_setting('yapper.bot', true) = '1' or current_setting('yapper.webhook', true) = '1' then return new; end if;
  if new.author_id is null or auth.uid() is distinct from new.author_id then return new; end if;
  select server_id into sid from public.channels where id = new.channel_id;
  if sid is null then return new; end if;
  why := public.server_gate(sid, new.author_id, true);
  if why is not null then raise exception '%', why using errcode = 'check_violation'; end if;
  return new;
end $function$;

-- public.message_voice_lock()
CREATE OR REPLACE FUNCTION public.message_voice_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.voice_secs := old.voice_secs;
  new.voice_wave := old.voice_wave;
  return new;
end $function$;

-- public.message_webhook_guard()
CREATE OR REPLACE FUNCTION public.message_webhook_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    if coalesce(current_setting('yapper.webhook', true), '') <> '1' then new.webhook := null; end if;
  else
    new.webhook := old.webhook;
  end if;
  return new;
end $function$;

-- public.messages_not_blank()
CREATE OR REPLACE FUNCTION public.messages_not_blank()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.attachment_path is null and new.embeds is null and new.components is null
     and coalesce(new.content, '') !~ '[^[:space:]   -     　­͏؜ᅟᅠ឴឵᠋-᠏​-‏‪-‮⁠-⁯⠀ㅤ︀-️﻿ﾠ\U000e0000-\U000e007f]' then
    raise exception 'Type something first.' using errcode = 'check_violation';
  end if;
  return new;
end $function$;

-- public.messages_strip_zalgo()
CREATE OR REPLACE FUNCTION public.messages_strip_zalgo()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.content := public.strip_zalgo(new.content);
  return new;
end; $function$;

-- public.mfa_backup_code_unuse(p_id uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.mfa_backup_code_unuse(p_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.mfa_backup_codes set used_at = null where id = p_id and revoked_at is null;
$function$;

-- public.mfa_backup_code_use(p_user uuid, p_code text, p_ip text, p_since timestamp with time zone)  [security definer]
CREATE OR REPLACE FUNCTION public.mfa_backup_code_use(p_user uuid, p_code text, p_ip text, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c text := lower(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g')); hit uuid;
begin
  if p_user is null then raise exception 'No user'; end if;
  perform pg_advisory_xact_lock(hashtextextended('mfa:' || p_user::text, 0));
  if (select count(*) from public.security_log where user_id = p_user and event = 'backup_code_fail' and created_at > now() - interval '15 minutes') >= 5
     or (select count(*) from public.security_log where user_id = p_user and event = 'backup_code_fail' and created_at > now() - interval '1 day') >= 20
     or (p_ip is not null and (select count(*) from public.security_log where ip = left(p_ip, 64) and event = 'backup_code_fail' and created_at > now() - interval '1 hour') >= 30) then
    perform public.mfa_log(p_user, 'backup_code_limited', p_ip);
    return jsonb_build_object('error', 'Too many wrong codes. Wait a bit and try again.');
  end if;
  if length(c) = 10 then
    update public.mfa_backup_codes set used_at = now()
     where id = (select id from public.mfa_backup_codes where user_id = p_user and code_hash = public.mfa_hash(p_user::text, c)
                  and used_at is null and revoked_at is null and (p_since is null or created_at >= p_since) limit 1)
    returning id into hit;
  end if;
  if hit is null then
    perform public.mfa_log(p_user, 'backup_code_fail', p_ip);
    return jsonb_build_object('error', 'That code didn’t work. Each code works once.');
  end if;
  perform public.mfa_log(p_user, 'backup_code_used', p_ip, jsonb_build_object('code_id', hit));
  return jsonb_build_object('ok', true, 'id', hit);
end;
$function$;

-- public.mfa_backup_codes_new(p_user uuid, p_ip text)  [security definer]
CREATE OR REPLACE FUNCTION public.mfa_backup_codes_new(p_user uuid, p_ip text)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare codes text[] := '{}'; c text; n int;
begin
  if p_user is null then raise exception 'No user'; end if;
  perform pg_advisory_xact_lock(hashtextextended('mfa:' || p_user::text, 0));
  select count(*) into n from public.security_log where user_id = p_user and event = 'backup_codes_new' and created_at > now() - interval '1 day';
  if n >= 10 then raise exception 'You made new codes a lot today. Try again tomorrow'; end if;
  update public.mfa_backup_codes set revoked_at = now() where user_id = p_user and used_at is null and revoked_at is null;
  for i in 1..10 loop
    c := public.mfa_new_code();
    codes := codes || c;
    insert into public.mfa_backup_codes (user_id, code_hash) values (p_user, public.mfa_hash(p_user::text, c));
  end loop;
  perform public.mfa_log(p_user, 'backup_codes_new', p_ip);
  return codes;
end;
$function$;

-- public.mfa_bad_links(p_ip text)  [security definer]
CREATE OR REPLACE FUNCTION public.mfa_bad_links(p_ip text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select p_ip is not null and (select count(*) from public.security_log where ip = left(p_ip, 64) and event = 'recovery_bad_link' and created_at > now() - interval '1 hour') >= 30;
$function$;

-- public.mfa_cleared(p_user uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.mfa_cleared(p_user uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.mfa_backup_codes set revoked_at = now() where user_id = p_user and used_at is null and revoked_at is null;
  update public.mfa_recovery_requests set status = 'cancelled', closed_at = now() where user_id = p_user and status = 'pending';
$function$;

-- public.mfa_hash(p_salt text, p_secret text)
CREATE OR REPLACE FUNCTION public.mfa_hash(p_salt text, p_secret text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select encode(sha256(convert_to(p_salt || ':' || p_secret, 'UTF8')), 'hex');
$function$;

-- public.mfa_log(p_user uuid, p_event text, p_ip text, p_detail jsonb, p_actor uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.mfa_log(p_user uuid, p_event text, p_ip text, p_detail jsonb DEFAULT '{}'::jsonb, p_actor uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into public.security_log (user_id, actor, event, ip, detail) values (p_user, p_actor, left(p_event, 60), left(p_ip, 64), coalesce(p_detail, '{}'));
$function$;

-- public.mfa_new_code()
CREATE OR REPLACE FUNCTION public.mfa_new_code()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  abc constant text := '23456789abcdefghijkmnpqrstuvwxyz';
  b bytea := decode(replace(gen_random_uuid()::text, '-', ''), 'hex');
  idx int[] := array[0, 1, 2, 3, 4, 5, 9, 10, 11, 12];
  out text := '';
  i int;
begin
  foreach i in array idx loop
    out := out || substr(abc, (get_byte(b, i) & 31) + 1, 1);
  end loop;
  return out;
end;
$function$;

-- public.mfa_recovery_cancel(p_token text, p_user uuid, p_ip text)  [security definer]
CREATE OR REPLACE FUNCTION public.mfa_recovery_cancel(p_token text, p_user uuid, p_ip text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid; st text; n int;
begin
  if p_user is not null then
    uid := p_user;
  else
    if coalesce(p_token, '') !~ '^[0-9a-f]{64}$' then return jsonb_build_object('error', 'That link isn’t right. Open it straight from the email.'); end if;
    if public.mfa_bad_links(p_ip) then return jsonb_build_object('error', 'Too many tries. Wait an hour.'); end if;
    select user_id, status into uid, st from public.mfa_recovery_requests where cancel_hash = public.mfa_hash('cancel', p_token);
    if uid is null then
      perform public.mfa_log(null, 'recovery_bad_link', p_ip);
      return jsonb_build_object('error', 'That link isn’t right. Open it straight from the email.');
    end if;
    if st <> 'pending' then
      perform public.mfa_log(uid, 'recovery_cancel_stale', p_ip);
      return jsonb_build_object('error', case st when 'done' then 'Too late to cancel, this reset was already used. Log in, check 2FA in Settings and change your password.' else 'Already cancelled. 2FA stays on.' end);
    end if;
  end if;
  update public.mfa_recovery_requests set status = 'cancelled', closed_at = now() where user_id = uid and status = 'pending';
  get diagnostics n = row_count;
  perform public.mfa_log(uid, 'recovery_cancel', p_ip, jsonb_build_object('cancelled', n, 'by', case when p_user is null then 'email' else 'settings' end));
  return jsonb_build_object('ok', true, 'cancelled', n, 'user_id', uid);
end;
$function$;

-- public.mfa_recovery_confirm(p_token text, p_ip text)  [security definer]
CREATE OR REPLACE FUNCTION public.mfa_recovery_confirm(p_token text, p_ip text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.mfa_recovery_requests;
begin
  if coalesce(p_token, '') !~ '^[0-9a-f]{64}$' then return jsonb_build_object('error', 'That link isn’t right. Open it straight from the email.'); end if;
  if public.mfa_bad_links(p_ip) then return jsonb_build_object('error', 'Too many tries. Wait an hour.'); end if;
  select * into r from public.mfa_recovery_requests where confirm_hash = public.mfa_hash('confirm', p_token) for update;
  if not found then
    perform public.mfa_log(null, 'recovery_bad_link', p_ip);
    return jsonb_build_object('error', 'That link isn’t right. Open it straight from the email.');
  end if;
  if r.status = 'cancelled' then return jsonb_build_object('error', 'This reset was cancelled. 2FA is still on.'); end if;
  if r.status = 'done' then return jsonb_build_object('error', 'Already done. 2FA is off, just log in with your password.'); end if;
  if r.expires_at <= now() then return jsonb_build_object('error', 'This link expired. Start again from the 2FA screen.'); end if;
  if r.ready_at > now() then return jsonb_build_object('wait', true, 'ready_at', r.ready_at); end if;
  update public.mfa_recovery_requests set status = 'done', closed_at = now() where id = r.id;
  perform public.mfa_log(r.user_id, 'recovery_confirm', p_ip, jsonb_build_object('request', r.id));
  return jsonb_build_object('ok', true, 'user_id', r.user_id, 'id', r.id, 'created_at', r.created_at);
end;
$function$;

-- public.mfa_recovery_reopen(p_id uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.mfa_recovery_reopen(p_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.mfa_recovery_requests r set status = 'pending', closed_at = null
   where r.id = p_id and r.status = 'done'
     and not exists (select 1 from public.security_log l where l.user_id = r.user_id and l.event in ('recovery_cancel', 'recovery_cancel_stale') and l.created_at >= r.closed_at);
$function$;

-- public.mfa_recovery_start(p_user uuid, p_ip text, p_wait interval)  [security definer]
CREATE OR REPLACE FUNCTION public.mfa_recovery_start(p_user uuid, p_ip text, p_wait interval DEFAULT '24:00:00'::interval)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t1 text; t2 text; r public.mfa_recovery_requests;
begin
  if p_user is null then raise exception 'No user'; end if;
  perform pg_advisory_xact_lock(hashtextextended('mfa:' || p_user::text, 0));
  if exists (select 1 from public.mfa_recovery_requests where user_id = p_user and status = 'pending' and expires_at > now()) then
    return jsonb_build_object('error', 'We already sent you a link. Check your inbox and spam folder.');
  end if;
  if (select count(*) from public.security_log where user_id = p_user and event = 'recovery_start' and created_at > now() - interval '1 day') >= 3 then
    perform public.mfa_log(p_user, 'recovery_limited', p_ip);
    return jsonb_build_object('error', 'Too many tries today. Try again tomorrow.');
  end if;
  t1 := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  t2 := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  insert into public.mfa_recovery_requests (user_id, confirm_hash, cancel_hash, ready_at, expires_at)
  values (p_user, public.mfa_hash('confirm', t1), public.mfa_hash('cancel', t2), now() + p_wait, now() + p_wait + interval '7 days')
  returning * into r;
  perform public.mfa_log(p_user, 'recovery_start', p_ip, jsonb_build_object('request', r.id));
  return jsonb_build_object('confirm', t1, 'cancel', t2, 'ready_at', r.ready_at, 'id', r.id);
end;
$function$;

-- public.mfa_recovery_status(p_user uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.mfa_recovery_status(p_user uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'codes_left', (select count(*) from public.mfa_backup_codes where user_id = p_user and used_at is null and revoked_at is null),
    'pending', (select jsonb_build_object('created_at', created_at, 'ready_at', ready_at) from public.mfa_recovery_requests
                 where user_id = p_user and status = 'pending' and expires_at > now() order by created_at desc limit 1));
$function$;

-- public.mod_assignments_head_changed()  [security definer]
CREATE OR REPLACE FUNCTION public.mod_assignments_head_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.head and not old.head then
    execute 'del' || 'ete from public.mod_assignments where user_id = $1' using new.user_id;
  elsif (old.head and not new.head) or (new.suspended_at is not null and old.suspended_at is null) then
    execute 'del' || 'ete from public.mod_assignments where head_id = $1' using new.user_id;
  end if;
  return null;
end $function$;

-- public.mod_ban_many(uids uuid[], why text)  [security definer]
CREATE OR REPLACE FUNCTION public.mod_ban_many(uids uuid[], why text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u uuid; n int := 0;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  if coalesce(array_length(uids, 1), 0) = 0 then return 0; end if;
  if array_length(uids, 1) > 25 then raise exception 'Up to 25 at a time'; end if;
  perform public.require_staff_reauth();
  foreach u in array uids loop
    if public.is_staff_user(u) or u = auth.uid() or public.is_site_banned(u) then continue; end if;
    if public.is_site_admin() then perform public.site_ban(u, why, false); else perform public.mod_ban(u, why); end if;
    n := n + 1;
  end loop;
  return n;
end $function$;

-- public.mod_ban_with_proof(uid uuid, why text, wipe boolean, rid uuid, with_message boolean, note text, images text[], forever boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.mod_ban_with_proof(uid uuid, why text, wipe boolean DEFAULT false, rid uuid DEFAULT NULL::uuid, with_message boolean DEFAULT true, note text DEFAULT NULL::text, images text[] DEFAULT NULL::text[], forever boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pr jsonb;
begin
  if not public.is_staff() then raise exception 'Moderators only'; end if;
  if not public.feature_on_for_me('standing_proof') then raise exception 'Proof isn''t on for you yet'; end if;
  pr := public.standing_proof_build(uid, rid, with_message, note, images);
  if public.is_site_admin() then
    perform public.site_ban(uid, why, coalesce(wipe, false));
  else
    if coalesce(wipe, false) then raise exception 'Only an admin can delete all their messages'; end if;
    if coalesce(forever, false) then
      if not public.is_site_manager() then raise exception 'Only an admin or Management can ban for good'; end if;
      perform public.site_ban(uid, why, false);
    else
      perform public.mod_ban(uid, why);
    end if;
  end if;
  if pr is not null then
    update public.site_bans set proof = pr where user_id = uid and created_at = now();
  end if;
end $function$;

-- public.mod_ban(uid uuid, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.mod_ban(uid uuid, why text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.mod_guard('ban', uid, why);
  insert into public.site_bans (user_id, reason, banned_by, expires_at)
  values (uid, left(why, 500), auth.uid(), case when public.is_site_admin() then null else now() + interval '7 days' end)
  on conflict (user_id) do update
    set reason = excluded.reason, banned_by = excluded.banned_by, created_at = now(), expires_at = excluded.expires_at
    -- 157: a lifted (expired) ban is replaced; a running one only by a ban at least as long (null = permanent).
    where site_bans.expires_at <= now() or excluded.expires_at is null
       or (site_bans.expires_at is not null and excluded.expires_at >= site_bans.expires_at);
  if not found then raise exception 'Already banned for longer'; end if;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'ban', uid, left(why, 300));
  update public.reports set status = 'actioned', resolved_by = auth.uid(), resolved_at = now() where target_id = uid and status = 'open';
end;
$function$;

-- public.mod_burst_alert_check()  [security definer]
CREATE OR REPLACE FUNCTION public.mod_burst_alert_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  n int;
  ids uuid[];
  acts text[];
  since timestamptz;
  a public.mod_burst_alerts;
  who text;
  note jsonb;
  uid uuid;
begin
  if new.actor is null then return null; end if;
  if not exists (select 1 from public.feature_flags where key = 'mod_burst_alerts' and mode in ('test', 'everyone')) then
    return null;
  end if;
  if exists (select 1 from public.site_admins where user_id = new.actor) then return null; end if;

  for r in select * from public.mod_burst_rules where enabled and new.action = any(actions) loop
    since := now() - make_interval(mins => r.window_minutes);
    if not pg_try_advisory_xact_lock(hashtext('mod_burst_alert:' || new.actor::text)) then return null; end if;
    if exists (select 1 from public.mod_burst_alerts where actor = new.actor and created_at > now() - interval '1 hour') then
      return null;
    end if;
    select count(*), array_agg(id order by created_at desc), array_agg(distinct action)
      into n, ids, acts
      from (select id, action, created_at from public.mod_log
             where actor = new.actor and action = any(r.actions) and created_at > since
             order by created_at desc limit 500) m;
    if coalesce(n, 0) < r.threshold then continue; end if;

    insert into public.mod_burst_alerts (actor, kind, action_count, window_start, window_end, actions, log_ids)
    values (new.actor, r.kind, n, since, now(), acts, ids[1:200])
    returning * into a;

    select username into who from public.profiles where id = new.actor;
    note := jsonb_build_object('id', a.id, 'actor', a.actor, 'actor_name', who, 'kind', a.kind,
      'count', a.action_count, 'window_minutes', r.window_minutes, 'actions', to_jsonb(a.actions));
    begin
      for uid in select public.mod_burst_recipients(new.actor) loop
        perform public.bc_notice('user:' || uid::text, 'mod_burst', note);
      end loop;
    exception when others then
      raise warning 'mod_burst_alert_check notify: %', sqlerrm;
    end;
    return null;
  end loop;
  return null;
exception when others then
  raise warning 'mod_burst_alert_check: %', sqlerrm;
  return null;
end $function$;

-- public.mod_burst_check()  [security definer]
CREATE OR REPLACE FUNCTION public.mod_burst_check()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); n10 int; n60 int; why text;
begin
  if me is null or public.is_site_admin() then return; end if;
  if not public.feature_on('mod_burst_guard', null) then return; end if;
  if exists (select 1 from public.site_moderators where user_id = me and suspended_at is not null) then
    -- Paused by this very statement (mod_guard ran a moment ago, then the table trigger asks again): let the action
    -- finish, so the pause commits with it. now() is fixed per transaction, so only a pause set here matches.
    if exists (select 1 from public.site_moderators where user_id = me and suspended_at = now()) then return; end if;
    raise exception 'Your moderator powers are paused. An admin can lift that in the Mod Center.';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('mod_burst:' || me::text, 0));
  -- The budget restarts at the last pause: once an admin lifts it, the old rows don't trip it again at once.
  select count(*) filter (where created_at > now() - interval '10 minutes'), count(*)
    into n10, n60
    from public.mod_log
   where actor = me and created_at > now() - interval '1 hour'
     and created_at > coalesce((select max(l.created_at) from public.mod_log l where l.actor = me and l.action = 'auto_suspended' and l.created_at > now() - interval '1 hour'), '-infinity')
     -- badge_auto rides along with an approval (two rows for one decision): not counted, so the line is always hit exactly.
     and action not in ('auto_suspended', 'mod_limit_boost', 'badge_auto')
     -- 577: removals on accounts under 3 days old (spam-bot cleanups) don't count; mod_guard's hourly caps still do.
     and not (action in ('delete', 'ban', 'timeout', 'purge', 'warn')
              and exists (select 1 from public.profiles p where p.id = mod_log.target_id and p.created_at > now() - interval '3 days'));
  if n10 >= 60 or n60 >= 200 then
    raise exception 'Slow down: that''s a lot of actions in a short time (60 in 10 minutes or 200 an hour). Ask an admin if this is real work.';
  end if;
  if n10 = 59 or n60 = 199 then
    why := 'Automatic: ' || case when n10 = 59 then '60 actions in 10 minutes' else '200 actions in an hour' end;
    update public.site_moderators set suspended_at = now(), suspended_reason = why where user_id = me and suspended_at is null;
    -- 634: no moderator row to pause (an area manager): refuse here instead of logging auto_suspended, which restarts the budget.
    if not found then raise exception 'Slow down: that''s a lot of actions in a short time (60 in 10 minutes or 200 an hour). Ask an admin if this is real work.'; end if;
    insert into public.mod_log (actor, action, reason) values (me, 'auto_suspended', why);
  end if;
end $function$;

-- public.mod_burst_dismiss(aid uuid, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.mod_burst_dismiss(aid uuid, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.mod_burst_alerts;
begin
  if not public.feature_on('mod_burst_alerts', null) then raise exception 'Not available yet'; end if;
  if not (public.is_site_admin() or public.is_head_mod()) then raise exception 'Head mods only'; end if;
  select * into a from public.mod_burst_alerts where id = aid for update;
  if a.id is null then raise exception 'No such alert'; end if;
  if a.actor = auth.uid() then raise exception 'Someone else has to look at your own alert'; end if;
  if a.dismissed_at is not null then return; end if;
  update public.mod_burst_alerts
     set dismissed_at = now(), dismissed_by = auth.uid(), note = left(coalesce(p_note, ''), 300)
   where id = aid;
  insert into public.mod_log (actor, action, target_id, reason)
  values (auth.uid(), 'burst_reviewed', a.actor, left(a.kind || ' x' || a.action_count || case when coalesce(p_note, '') = '' then '' else ': ' || p_note end, 300));
end $function$;

-- public.mod_burst_recipients(skip uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.mod_burst_recipients(skip uuid)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select r.user_id from (
    select user_id from public.site_admins
    union
    select user_id from public.site_moderators where head and suspended_at is null
  ) r
  join public.feature_flags f on f.key = 'mod_burst_alerts'
  where r.user_id <> skip and (f.mode = 'everyone' or r.user_id = any(f.users));
$function$;

-- public.mod_guard(action text, target uuid, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.mod_guard(action text, target uuid, why text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int; lim int; logged text[];
begin
  if public.is_site_admin() then return; end if;
  if not (public.is_site_mod() or public.area_manager_may(action)) then
    if public.feature_on('mod_burst_guard', null) and exists (select 1 from public.site_moderators where user_id = auth.uid() and suspended_at is not null) then
      raise exception 'Your moderator powers are paused. An admin can lift that in the Mod Center.';
    end if;
    raise exception 'Moderators only';
  end if;
  -- After the mod check: the pause the budget sets has to let this one action finish (see the top).
  perform public.mod_burst_check();
  if target is not null and public.is_staff_user(target) then raise exception 'You can''t moderate an admin or another moderator'; end if;
  if target = auth.uid() then raise exception 'Not yourself'; end if;
  if action in ('ban', 'timeout', 'takedown', 'purge') and length(trim(coalesce(why, ''))) < 5 then raise exception 'Give a reason (at least 5 characters)'; end if;
  lim := case action
    when 'ban' then 80 when 'takedown' then 5 when 'purge' then 20 when 'timeout' then 60 when 'reset' then 20
    when 'unban' then 60 when 'badge' then 10 when 'untimeout' then 30 when 'verify' then 60
    when 'unwarn' then 30 when 'mark_bot' then 20 when 'server_hide' then 10
    when 'deco_takedown' then 10 when 'deco_review' then 60 when 'bot_review' then 20 when 'copyright' then 10
    when 'suspension_lift' then 10 when 'bot_promo' then 10 when 'vote' then 10 when 'image_removal' then 30
    else 60 end;
  logged := case action
    when 'badge' then array['badge_given', 'badge_removed']
    when 'takedown' then array['server_takedown']
    when 'untimeout' then array['timeout_cleared']
    when 'verify' then array['verify', 'verify_reject', 'verify_ask_proof']
    when 'mark_bot' then array['marked_bot', 'unmarked_bot']
    when 'reset' then array['reset', 'profile_reset']
    when 'deco_takedown' then array['deco_removed']
    when 'deco_review' then array['deco_approved', 'deco_rejected', 'deco_check_cleared']
    when 'bot_review' then array['bot_verified', 'bot_rejected']
    when 'copyright' then array['copyright_strike', 'copyright_strike_removed']
    when 'suspension_lift' then array['suspension_lifted']
    when 'bot_promo' then array['bot_promo_ended']
    when 'vote' then array['vote_opened']
    when 'image_removal' then array['image_removal_removed', 'image_removal_need_info', 'image_removal_rejected']
    else array[action] end;
  select count(*) into n from public.mod_log where actor = auth.uid() and mod_log.action = any(logged) and created_at > now() - interval '1 hour';
  -- 577: deletes and purges of brand-new accounts (spam waves) get 4x room; bans, timeouts and warns don't.
  if action in ('delete', 'purge') and target is not null
     and exists (select 1 from public.profiles p where p.id = target and p.created_at > now() - interval '3 days') then
    lim := lim * 4;
  end if;
  lim := ceil(lim * public.mod_limit_boost())::int;
  if n >= lim then
    raise exception 'You''ve hit the hourly limit for that (% an hour). Wait a bit or ask an admin to do it.', lim;
  end if;
end; $function$;

-- public.mod_limit_boost()  [security definer]
CREATE OR REPLACE FUNCTION public.mod_limit_boost()
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b numeric;
begin
  select mod_limit_boost into b from public.app_settings where id limit 1;
  return coalesce(b, 1);
end;
$function$;

-- public.mod_mark_bot(uid uuid, on_off boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.mod_mark_bot(uid uuid, on_off boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  if exists (select 1 from public.bot_accounts where user_id = uid) then raise exception 'That is one of Yapper''s own bots'; end if;
  perform public.mod_guard('mark_bot', uid, null);
  update public.profiles set badges = case when on_off then array(select distinct unnest(coalesce(badges, '{}'::text[]) || array['bot']))
                                           else array_remove(coalesce(badges, '{}'::text[]), 'bot') end where id = uid;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), case when on_off then 'marked_bot' else 'unmarked_bot' end, uid, '');
end $function$;

-- public.mod_purge_messages(uid uuid, hours integer, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.mod_purge_messages(uid uuid, hours integer, why text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int; r text := left(btrim(coalesce(why, '')), 500);
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  if uid = (select a.webhook_user_id from public.app_settings a limit 1) then
    raise exception 'That''s the shared webhook account. Purge whoever made the webhook instead.';
  end if;
  if public.is_frozen(uid) then raise exception 'This account is frozen to keep evidence, so its messages can''t be cleaned up'; end if;
  perform public.mod_guard('purge', uid, r);
  perform public.require_staff_reauth();
  hours := least(greatest(coalesce(hours, 24), 1), 24 * 30);
  execute 'with gone as (del' || 'ete from public.messages where author_id = $1 and created_at > now() - make_interval(hours => $2) returning 1) select count(*) from gone'
    into n using uid, hours;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'purge', uid, r || ' (' || n || ' messages, last ' || hours || 'h)');
  return n;
end $function$;

-- public.mod_remove_warning(wid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.mod_remove_warning(wid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare w public.user_warnings;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  select * into w from public.user_warnings where id = wid;
  if w.id is null or w.removed_at is not null then raise exception 'That warning is already gone'; end if;
  perform public.mod_guard('unwarn', w.user_id, null);
  update public.user_warnings set removed_at = now(), removed_by = auth.uid(), seen_at = coalesce(seen_at, now()) where id = wid;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'unwarn', w.user_id, left('Removed warning: ' || w.reason, 300));
end $function$;

-- public.mod_reset_profile(uid uuid, parts text[], why text)  [security definer]
CREATE OR REPLACE FUNCTION public.mod_reset_profile(uid uuid, parts text[], why text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  k_old text;
begin
  if length(trim(coalesce(why, ''))) < 3 then raise exception 'Give a reason'; end if;
  if parts is null or cardinality(parts) = 0 then raise exception 'Pick what to reset'; end if;
  perform public.mod_guard('reset', uid, why);
  if 'username' = any(parts) then
    -- Row first, then the name lock: the same order as a user's own rename (row lock, then the holds trigger's
    -- advisory lock), so the two can't deadlock, and FOR UPDATE waits out a rename in progress so we hold the
    -- name actually being reset, not one they just left.
    select lower(username) into k_old from public.profiles where id = uid for update;
    if k_old is not null then
      -- Same lock the holds trigger takes, so a rename grabbing this name at the same moment waits for us.
      perform pg_advisory_xact_lock(hashtext('username:' || k_old));
      -- mod_guard above guarantees a signed-in staff member, so auth.uid() is set.
      insert into public.username_holds (name_key, user_id, until)
        values (k_old, auth.uid(), now() + interval '30 days')
        on conflict (name_key) do update set user_id = excluded.user_id, until = excluded.until;
    end if;
  end if;
  update public.profiles set
    avatar_path  = case when 'avatar' = any(parts) then null else avatar_path end,
    banner_path  = case when 'banner' = any(parts) then null else banner_path end,
    bio          = case when 'bio' = any(parts) then '' else bio end,
    display_name = case when 'display_name' = any(parts) then null else display_name end,
    pronouns     = case when 'pronouns' = any(parts) then null else pronouns end,
    links        = case when 'links' = any(parts) then '[]'::jsonb else links end,
    username     = case when 'username' = any(parts) then 'user' || substr(md5(random()::text || uid::text), 1, 8) else username end
  where id = uid;
  insert into public.mod_log (actor, action, target_id, reason)
    values (auth.uid(), 'profile_reset', uid, array_to_string(parts, ', ') || ': ' || left(trim(why), 250));
  -- Realtime: forget the cached row and tell the tabs showing this person (pg_net queues it, sent after commit).
  perform public.rt_profile_changed(array[uid]);
end;
$function$;

-- public.mod_reset_standing(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.mod_reset_standing(uid uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  perform public.mod_guard('unwarn', uid, null);
  with gone as (
    update public.user_warnings set removed_at = now(), removed_by = auth.uid(), seen_at = coalesce(seen_at, now())
    where user_id = uid and removed_at is null returning 1)
  select count(*) into n from gone;
  if n > 0 then
    insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'unwarn', uid, 'Reset standing: removed ' || n || ' warning' || case when n = 1 then '' else 's' end);
  end if;
  return n;
end $function$;

-- public.mod_timeout(uid uuid, minutes integer, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.mod_timeout(uid uuid, minutes integer, why text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.mod_guard('timeout', uid, why);
  if minutes < 1 or (minutes > 1440 and not public.is_site_admin()) then raise exception 'Timeouts are 1 minute to 24 hours'; end if;
  update public.profiles set muted_until = now() + make_interval(mins => minutes), muted_reason = left(why, 200) where id = uid;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'timeout', uid, minutes || ' min: ' || left(why, 300));
  update public.reports set status = 'actioned', resolved_by = auth.uid(), resolved_at = now() where target_id = uid and status = 'open';
end;
$function$;

-- public.mod_user_alts(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.mod_user_alts(uid uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- Other accounts that signed in from the same network as this person in the last 30 days.
  -- Networks shared by more than 60 accounts (mobile carriers, big schools) are skipped: not a signal.
  -- For scale: the typical network has 1 account, 95% have 5 or fewer, an alt farm has 30+.
  select case when public.is_staff() then coalesce((
    with mine as (
      select distinct la.ip from public.login_attempts la
      join public.profiles p on p.id = uid and lower(la.username) = lower(p.username)
      where la.ok and la.at > now() - interval '30 days'
    ), shared as (
      select la.ip, count(distinct lower(la.username)) as accounts from public.login_attempts la
      where la.ip in (select ip from mine) and la.ok and la.at > now() - interval '30 days'
      group by la.ip having count(distinct lower(la.username)) <= 60
    )
    select jsonb_agg(jsonb_build_object('id', p.id, 'username', p.username, 'ips', x.ips, 'banned', exists (select 1 from public.site_bans b where b.user_id = p.id and (b.expires_at is null or b.expires_at > now()))) order by x.ips desc, p.username)
    from (
      select lower(la.username) as uname, count(distinct la.ip) as ips from public.login_attempts la
      where la.ip in (select ip from shared) and la.ok and la.at > now() - interval '30 days'
      group by lower(la.username)
    ) x join public.profiles p on lower(p.username) = x.uname
    where p.id <> uid
  ), '[]'::jsonb) else '[]'::jsonb end;
$function$;

-- public.mod_user_case(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.mod_user_case(uid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare out jsonb;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  select jsonb_build_object(
    'joined', p.created_at,
    'muted_until', p.muted_until,
    'muted_reason', p.muted_reason,
    'voice_muted_until', p.voice_muted_until,
    'ban', (select to_jsonb(b) from public.site_bans b where b.user_id = uid),
    'is_admin', exists (select 1 from public.site_admins where user_id = uid),
    'is_mod', exists (select 1 from public.site_moderators where user_id = uid and suspended_at is null),
    'servers', (select count(*) from public.server_members where user_id = uid),
    'messages_7d', (select count(*) from public.messages where author_id = uid and created_at > now() - interval '7 days'),
    'reports_total', (select count(*) from public.reports where target_id = uid),
    'reports_open', (select count(*) from public.reports where target_id = uid and status = 'open'),
    'reporters', (select count(distinct reporter_id) from public.reports where target_id = uid),
    'reports_made', (select count(*) from public.reports where reporter_id = uid),
    'refused_uploads', (select count(*) from public.media_scans where user_id = uid and verdict = 'blocked'),
    'warnings', coalesce((select jsonb_agg(to_jsonb(w) order by w.created_at desc) from public.user_warnings w where w.user_id = uid and w.removed_at is null), '[]'::jsonb),
    'history', coalesce((select jsonb_agg(to_jsonb(l) order by l.created_at desc)
                         from (select * from public.mod_log where target_id = uid order by created_at desc limit 60) l), '[]'::jsonb)
  ) into out from public.profiles p where p.id = uid;
  return out;
end $function$;

-- public.mod_user_messages(uid uuid, lim integer, before timestamp with time zone)  [security definer]
CREATE OR REPLACE FUNCTION public.mod_user_messages(uid uuid, lim integer DEFAULT 50, before timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(id uuid, channel_id uuid, content text, attachment_path text, created_at timestamp with time zone, channel_name text, server_id uuid, server_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  return query
    select m.id, m.channel_id, m.content, m.attachment_path, m.created_at, c.name, s.id, s.name
      from public.messages m
      join public.channels c on c.id = m.channel_id
      join public.servers s on s.id = c.server_id
     where m.author_id = uid and (before is null or m.created_at < before) and (public.is_site_admin() or public.staff_peek_ok(s.id) or public.can_access_channel(c.id))
     order by m.created_at desc
     limit least(greatest(coalesce(lim, 50), 1), 100);
end;
$function$;

-- public.mod_warn_with_proof(uid uuid, why text, rid uuid, with_message boolean, note text, images text[])  [security definer]
CREATE OR REPLACE FUNCTION public.mod_warn_with_proof(uid uuid, why text, rid uuid DEFAULT NULL::uuid, with_message boolean DEFAULT true, note text DEFAULT NULL::text, images text[] DEFAULT NULL::text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pr jsonb;
begin
  if not public.is_staff() then raise exception 'Moderators only'; end if;
  if not public.feature_on_for_me('standing_proof') then raise exception 'Proof isn''t on for you yet'; end if;
  pr := public.standing_proof_build(uid, rid, with_message, note, images);
  perform public.mod_warn(uid, why);
  if pr is not null then
    update public.user_warnings set proof = pr
     where id = (select w.id from public.user_warnings w where w.user_id = uid and w."by" = auth.uid() and w.created_at = now() limit 1);
  end if;
end $function$;

-- public.mod_warn(uid uuid, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.mod_warn(uid uuid, why text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if length(trim(coalesce(why, ''))) < 3 then raise exception 'Say what the warning is for'; end if;
  if uid = auth.uid() then raise exception 'Not yourself'; end if;
  perform public.mod_guard('warn', uid, why);
  insert into public.user_warnings (user_id, by, reason) values (uid, auth.uid(), left(trim(why), 500));
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'warn', uid, left(trim(why), 300));
  update public.reports set status = 'actioned', resolved_by = auth.uid(), resolved_at = now() where target_id = uid and status = 'open';
end;
$function$;

-- public.modserver_management_role_id()
CREATE OR REPLACE FUNCTION public.modserver_management_role_id()
 RETURNS uuid
 LANGUAGE sql
 IMMUTABLE
AS $function$ select 'f7d69cb5-8e0c-4fd8-aa62-2f04c76dcc4a'::uuid $function$;

-- public.move_thread(p_thread uuid, p_forum uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.move_thread(p_thread uuid, p_forum uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t public.channels; f public.channels; tg text[];
begin
  t := public.thread_v2(p_thread);
  if not exists (select 1 from public.channels c where c.id = t.parent_id and c.kind = 'forum') then raise exception 'Only forum posts can be moved'; end if;
  select * into f from public.channels where id = p_forum and kind = 'forum';
  if not found or f.server_id is distinct from t.server_id then raise exception 'Pick a forum in this server'; end if;
  if f.id = t.parent_id then return; end if;
  if not public.thread_mod(p_thread) or not public.forum_mod(f.id) then raise exception 'Only mods of both forums can move posts'; end if;
  select coalesce(array_agg(distinct ne->>'id'), '{}') into tg
    from jsonb_array_elements(coalesce((select c.forum_tags from public.channels c where c.id = t.parent_id), '[]')) oe
    join jsonb_array_elements(coalesce(f.forum_tags, '[]')) ne on lower(ne->>'name') = lower(oe->>'name')
    where oe->>'id' = any(t.tags);
  update public.channels set parent_id = f.id, tags = tg[1:5], pinned_at = null,
    slowmode = coalesce(f.slowmode, 0), no_images = coalesce(f.no_images, false), no_gifs = coalesce(f.no_gifs, false)
    where id = p_thread;
end $function$;

-- public.mutuals(other uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.mutuals(other uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with mine as (
    select case when requester = auth.uid() then addressee else requester end as f from public.friendships where status = 'accepted' and auth.uid() in (requester, addressee)
  ), theirs as (
    select case when requester = other then addressee else requester end as f from public.friendships where status = 'accepted' and other in (requester, addressee)
  )
  select jsonb_build_object(
    'friends', coalesce((select jsonb_agg(f) from (select f from mine intersect select f from theirs) x), '[]'::jsonb),
    'servers', coalesce((select jsonb_agg(s.id) from public.servers s where exists (select 1 from public.server_members a where a.server_id = s.id and a.user_id = auth.uid()) and exists (select 1 from public.server_members b where b.server_id = s.id and b.user_id = other)), '[]'::jsonb)
  );
$function$;

-- public.my_appeal_news()  [security definer]
CREATE OR REPLACE FUNCTION public.my_appeal_news()
 RETURNS TABLE(id uuid, status text, bucket text, allowed boolean, decided_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select a.id, a.status, a.bucket, a.allowed, a.decided_at from public.upload_appeals a
  where a.user_id = auth.uid() and a.status <> 'pending' and a.seen_at is null
  order by a.decided_at
  limit 5;
$function$;

-- public.my_area_application(p_area text)  [security definer]
CREATE OR REPLACE FUNCTION public.my_area_application(p_area text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.area_applications;
begin
  if auth.uid() is null or p_area not in ('art', 'dev') or not public.feature_on('area_managers', null) then return jsonb_build_object('on', false); end if;
  select * into a from public.area_applications where user_id = auth.uid() and area = p_area order by created_at desc limit 1;
  return jsonb_build_object(
    'on', true,
    'block', public.area_apply_block(p_area),
    'app', case when a.id is null then null else jsonb_build_object(
      'id', a.id, 'status', a.status, 'why', a.why, 'links', a.links, 'experience', a.experience, 'note', a.note,
      'created_at', a.created_at, 'decided_at', a.decided_at) end);
end $function$;

-- public.my_area_decision()  [security definer]
CREATE OR REPLACE FUNCTION public.my_area_decision()
 RETURNS TABLE(id uuid, area text, status text, note text, decided_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then return; end if;
  return query select a.id, a.area, a.status, a.note, a.decided_at from public.area_applications a
    where a.user_id = auth.uid() and a.status in ('accepted', 'declined') and a.seen_at is null
    order by a.decided_at desc limit 1;
end $function$;

-- public.my_area_desk()  [security definer]
CREATE OR REPLACE FUNCTION public.my_area_desk()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare out jsonb;
begin
  if auth.uid() is null then return '[]'::jsonb; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'area', m.area,
      'server_id', public.area_server_id(m.area),
      'server_name', s.name,
      'role_name', r.name,
      'in_server', exists (select 1 from public.server_members sm where sm.server_id = public.area_server_id(m.area) and sm.user_id = m.user_id),
      'has_role', exists (select 1 from public.member_roles mr where mr.user_id = m.user_id and mr.role_id = public.area_role_id(m.area)),
      'channel_id', case m.area when 'art' then public.art_apply_channel_id() else public.dev_apply_channel_id() end
    ) order by m.area), '[]'::jsonb)
  into out
  from public.site_area_managers m
  left join public.servers s on s.id = public.area_server_id(m.area)
  left join public.roles r on r.id = public.area_role_id(m.area)
  where m.user_id = auth.uid();
  return out;
end;
$function$;

