-- public.my_channel_ids()  [security definer]
CREATE OR REPLACE FUNCTION public.my_channel_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select channel_id from public.channel_members where user_id = auth.uid() $function$;

-- public.my_deco_wearers()  [security definer]
CREATE OR REPLACE FUNCTION public.my_deco_wearers()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with mine as (select (select auth.uid())::text || '/' as pre),
  worn as (
    select substr(p.avatar_deco, 3) as path from public.profiles p, mine
      where p.avatar_deco like 'c:%' and starts_with(p.avatar_deco, 'c:' || mine.pre)
    union all
    select substr(p.profile_effect, 3) from public.profiles p, mine
      where p.profile_effect like 'p:%' and starts_with(p.profile_effect, 'p:' || mine.pre)
    union all
    select substr(p.name_banner, 3) from public.profiles p, mine
      where p.name_banner like 'c:%' and starts_with(p.name_banner, 'c:' || mine.pre)
  )
  select coalesce(jsonb_object_agg(path, n), '{}'::jsonb) from (select path, count(*) as n from worn group by path) x;
$function$;

-- public.my_flags()  [security definer]
CREATE OR REPLACE FUNCTION public.my_flags()
 RETURNS TABLE(key text, label text, description text, mode text, servers uuid[], users uuid[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with me as materialized (select auth.uid() as uid, public.is_site_admin() as adm),
  mine as materialized (select coalesce(array_agg(sm.server_id), '{}'::uuid[]) as s from public.server_members sm where sm.user_id = (select uid from me))
  select f.key, f.label, f.description, f.mode::text,
    -- Only admins see the full test groups; others see their own part of it.
    case when me.adm then f.servers
         else array(select s from unnest(coalesce(f.servers, '{}'::uuid[])) s where s = any(mine.s)) end,
    case when me.adm then f.users
         when me.uid = any(coalesce(f.users, '{}'::uuid[])) then array[me.uid]
         else '{}'::uuid[] end
  from public.feature_flags f cross join me cross join mine
  where me.adm
     or f.mode = 'everyone'
     or (f.mode = 'test' and me.uid is not null
         and (me.uid = any(coalesce(f.users, '{}'::uuid[])) or coalesce(f.servers, '{}'::uuid[]) && mine.s))
     or f.key = 'age_screen';
$function$;

-- public.my_join_decisions()  [security definer]
CREATE OR REPLACE FUNCTION public.my_join_decisions()
 RETURNS TABLE(id uuid, server_id uuid, name text, status text, note text, decided_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then return; end if;
  return query select r.id, r.server_id, s.name, r.status, r.note, r.decided_at
    from public.server_join_requests r join public.servers s on s.id = r.server_id
    where r.user_id = auth.uid() and r.status in ('accepted', 'declined') and r.seen_at is null
    order by r.decided_at limit 20;
end $function$;

-- public.my_leaderboard_hidden()  [security definer]
CREATE OR REPLACE FUNCTION public.my_leaderboard_hidden()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select p.leaderboard_hidden from public.profiles p where p.id = (select auth.uid())), false);
$function$;

-- public.my_matches(p_refresh boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.my_matches(p_refresh boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  row public.match_cache;
  res jsonb;
begin
  if me is null then return '[]'::jsonb; end if;
  if not public.feature_on_for_me('interest_matches') then
    raise exception 'Not available yet' using errcode = 'P0001';
  end if;
  select * into row from public.match_cache c where c.user_id = me;
  if row.user_id is null or row.computed_at < now() - (case when p_refresh then interval '5 minutes' else interval '6 hours' end) then
    res := public.match_compute(me, 20);
    insert into public.match_cache as c (user_id, computed_at, results) values (me, now(), res)
    on conflict (user_id) do update set computed_at = now(), results = excluded.results;
  else
    res := row.results;
  end if;
  select coalesce(jsonb_agg(r), '[]'::jsonb) into res
  from jsonb_array_elements(res) r
  where coalesce((select ms.suggest_me from public.match_settings ms where ms.user_id = (r ->> 'user_id')::uuid), true)
    and not public.is_blocked_between(me, (r ->> 'user_id')::uuid)
    and not exists (select 1 from public.site_bans sb where sb.user_id = (r ->> 'user_id')::uuid)
    and not exists (select 1 from public.friendships f
                    where (f.requester = me and f.addressee = (r ->> 'user_id')::uuid) or (f.addressee = me and f.requester = (r ->> 'user_id')::uuid));
  return res;
end $function$;

-- public.my_mentions(lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.my_mentions(lim integer DEFAULT 40)
 RETURNS SETOF public.messages
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with pings as materialized (select * from public.my_role_pings()),
  chans as materialized (
    select cm.channel_id, null::uuid as sid, cm.joined_at as since
    from public.channel_members cm
    join public.channels c on c.id = cm.channel_id and c.server_id is null
    where cm.user_id = (select auth.uid()) and not public.is_site_banned((select auth.uid()))
    union all
    select v.id, v.server_id, sm.joined_at
    from public.my_visible_server_channels() v
    join public.server_members sm on sm.server_id = v.server_id and sm.user_id = (select auth.uid())
    where not exists (select 1 from public.servers sd where sd.id = v.server_id and sd.shut_down_at is not null and not public.is_staff())
      and public.channel_history_ok(v.id)
  ),
  ment as (
    select m.*
    from chans
    left join pings p on p.sid = chans.sid
    cross join lateral (
      select x.* from public.messages x
      where x.channel_id = chans.channel_id
        and (strpos(x.content, '<@') > 0 or strpos(x.content, '@everyone') > 0)
        and x.created_at > greatest(now() - interval '30 days', coalesce(chans.since, now() - interval '30 days'))
        and x.author_id <> (select auth.uid())
        and (x.content like '%<@' || (select auth.uid())::text || '>%'
             or x.content ~ '(^|[^\w])@everyone([^\w]|$)'
             or (p.pats is not null and strpos(x.content, '<@&') > 0 and x.content like any (p.pats)))
      order by x.created_at desc
      limit least(greatest(coalesce(lim, 40), 1), 100)
    ) m
    order by m.created_at desc
    limit least(greatest(coalesce(lim, 40), 1), 100)
  ),
  mine as materialized (
    select array(
      select pm.id from public.messages pm
      where pm.author_id = (select auth.uid()) and pm.created_at > now() - interval '30 days'
      order by pm.created_at desc
      limit 500
    ) as ids
  ),
  rep as (
    select x.*
    from public.messages x
    join chans on chans.channel_id = x.channel_id
    where x.reply_to_id = any ((select ids from mine)::uuid[])
      and x.author_id <> (select auth.uid())
      and x.created_at > greatest(now() - interval '30 days', coalesce(chans.since, now() - interval '30 days'))
    order by x.created_at desc
    limit least(greatest(coalesce(lim, 40), 1), 100)
  )
  select m.*
  from (
    select * from ment
    union all
    select * from rep r where not exists (select 1 from ment a where a.id = r.id)
  ) m
  order by m.created_at desc
  limit least(greatest(coalesce(lim, 40), 1), 100);
$function$;

-- public.my_notify_settings()  [security definer]
CREATE OR REPLACE FUNCTION public.my_notify_settings()
 RETURNS TABLE(server_id uuid, channel_id uuid, level text, muted_until timestamp with time zone, lifted boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); gone uuid[] := '{}';
begin
  if me is null then return; end if;
  if exists (select 1 from public.notify_settings n where n.user_id = me and n.muted_until <= now()) then
    with ended as (
      update public.notify_settings n set muted_until = null, updated_at = now()
        where n.user_id = me and n.muted_until <= now()
        returning n.channel_id
    )
    select coalesce(array_agg(e.channel_id), '{}') into gone from ended e;
    update public.channel_reads r set muted = false where r.user_id = me and r.channel_id = any (gone);
  end if;
  return query select n.server_id, n.channel_id, n.level, n.muted_until, n.channel_id = any (gone) from public.notify_settings n
    where n.user_id = me and (n.level is not null or n.muted_until is not null or n.channel_id = any (gone));
end; $function$;

-- public.my_partner_decisions()  [security definer]
CREATE OR REPLACE FUNCTION public.my_partner_decisions()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'server_id', a.server_id, 'name', s.name, 'status', a.status,
                                               'note', a.staff_note) order by a.reviewed_at desc), '[]'::jsonb)
  from public.partner_applications a join public.servers s on s.id = a.server_id
  where a.owner_id = auth.uid() and a.seen_at is null and a.status <> 'pending'
$function$;

-- public.my_passkeys()  [security definer]
CREATE OR REPLACE FUNCTION public.my_passkeys()
 RETURNS TABLE(id uuid, name text, created_at timestamp with time zone, last_used_at timestamp with time zone, backed_up boolean, device_type text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select p.id, p.name, p.created_at, p.last_used_at, p.backed_up, p.device_type
    from public.user_passkeys p
   where p.user_id = (select auth.uid())
   order by p.created_at
$function$;

-- public.my_role_pings()  [security definer]
CREATE OR REPLACE FUNCTION public.my_role_pings()
 RETURNS TABLE(sid uuid, pats text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select sm.server_id, array_agg('%<@&' || r.id::text || '>%')
  from public.feature_flags f
  join public.server_members sm on sm.user_id = (select auth.uid())
  join public.roles r on r.server_id = sm.server_id
  where f.key = 'role_mentions'
    and (f.mode = 'everyone' or (f.mode = 'test' and (sm.server_id = any(f.servers) or (select auth.uid()) = any(f.users))))
    and (r.auto = 'all'
         or (r.auto = 'before' and r.auto_before is not null and sm.joined_at < r.auto_before)
         or exists (select 1 from public.member_roles mr where mr.user_id = (select auth.uid()) and mr.role_id = r.id))
  group by sm.server_id;
$function$;

