-- public.my_shards()  [security definer]
CREATE OR REPLACE FUNCTION public.my_shards()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'balance', coalesce(w.balance, 0),
    'earned', coalesce(w.earned_total, 0),
    'streak', case when w.last_day >= (now() at time zone 'utc')::date - 1 then coalesce(w.streak, 0) else 0 end,
    'frozen', coalesce(w.frozen, false) or public.is_site_banned(me.id),
    'level', p.account_level,
    'next_cost', case when p.account_level >= 100 then null else public.level_cost(p.account_level + 1) end,
    'today', jsonb_build_object('minutes', coalesce(d.minutes, 0), 'paid', coalesce(d.paid, 0),
                                'daily', w.last_day = (now() at time zone 'utc')::date),
    'invites', jsonb_build_object(
      'pending', (select count(*) from public.referrals r where r.inviter = me.id and r.status = 'pending'),
      'paid', (select count(*) from public.referrals r where r.inviter = me.id and r.status = 'paid')),
    'boost', public.shard_boost(me.id),
    'event', public.shard_event(),
    'config', public.shard_config())
  from (select (select auth.uid()) as id) me
  join public.profiles p on p.id = me.id
  left join public.shard_wallets w on w.user_id = me.id
  left join public.shard_days d on d.user_id = me.id and d.day = (now() at time zone 'utc')::date;
$function$;

-- public.my_slowmode_mark(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.my_slowmode_mark(cid uuid)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select at from public.post_marks where channel_id = cid and author_id = (select auth.uid()) and kind = 'msg';
$function$;

-- public.my_slowmode_wait(chid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.my_slowmode_wait(chid uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(greatest(0, ceil(extract(epoch from (
      greatest(
        (select pm.at from public.post_marks pm where pm.channel_id = chid and pm.author_id = auth.uid() and pm.kind = 'msg'),
        (select max(m.created_at) from public.messages m where m.channel_id = chid and m.author_id = auth.uid())
      ) + make_interval(secs => greatest(coalesce(c.slowmode, 0), case when c.auto_slow_until > now() then 5 else 0 end)) - now()
    )))), 0)::int
  from public.channels c
  where c.id = chid and auth.uid() is not null and c.server_id is not null and public.can_access_channel(chid);
$function$;

-- public.my_staff_application()  [security definer]
CREATE OR REPLACE FUNCTION public.my_staff_application()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.staff_applications;
begin
  if auth.uid() is null or not public.staff_apps_on() then return jsonb_build_object('on', false); end if;
  select * into a from public.staff_applications where user_id = auth.uid() order by created_at desc limit 1;
  return jsonb_build_object(
    'on', true,
    'block', public.staff_apply_block(),
    'app', case when a.id is null then null else jsonb_build_object(
      'id', a.id, 'status', a.status, 'why', a.why, 'hours', a.hours, 'experience', a.experience, 'note', a.note,
      'created_at', a.created_at, 'decided_at', a.decided_at) end);
end $function$;

-- public.my_staff_decision()  [security definer]
CREATE OR REPLACE FUNCTION public.my_staff_decision()
 RETURNS TABLE(id uuid, status text, note text, decided_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then return; end if;
  return query select a.id, a.status, a.note, a.decided_at from public.staff_applications a
    where a.user_id = auth.uid() and a.status in ('accepted', 'declined') and a.seen_at is null
    order by a.decided_at desc limit 1;
end $function$;

-- public.my_staff_security()  [security definer]
CREATE OR REPLACE FUNCTION public.my_staff_security()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return (select jsonb_build_object(
    'staff', exists (select 1 from public.site_admins where user_id = auth.uid())
          or exists (select 1 from public.site_moderators where user_id = auth.uid() and suspended_at is null)
          or exists (select 1 from public.site_area_managers where user_id = auth.uid()),
    'need_2fa', public.feature_on('staff_2fa', null),
    'has_2fa', exists (select 1 from auth.mfa_factors f where f.user_id = auth.uid() and f.status = 'verified'),
    'aal', coalesce(auth.jwt() ->> 'aal', 'aal1'),
    'reauth', public.feature_on('staff_reauth', null),
    'has_password', exists (select 1 from auth.users u where u.id = auth.uid() and coalesce(u.encrypted_password, '') <> '')
  ));
end;
$function$;

-- public.my_standing_proof_images()  [security definer]
CREATE OR REPLACE FUNCTION public.my_standing_proof_images()
 RETURNS SETOF text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select x from (
    select jsonb_array_elements_text(w.proof -> 'images') x
      from public.user_warnings w
     where w.user_id = auth.uid() and w.removed_at is null and w.created_at > now() - interval '3 days'
       and jsonb_typeof(w.proof -> 'images') = 'array'
    union
    select jsonb_array_elements_text(b.proof -> 'images')
      from public.site_bans b
     where b.user_id = auth.uid() and (b.expires_at is null or b.expires_at > now())
       and jsonb_typeof(b.proof -> 'images') = 'array'
  ) s
  where public.feature_on_for_me('standing_proof');
$function$;

-- public.my_standing_proof()  [security definer]
CREATE OR REPLACE FUNCTION public.my_standing_proof()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid();
begin
  if me is null then return null; end if;
  if not public.feature_on_for_me('standing_proof') then
    return jsonb_build_object('on', false, 'warnings', '[]'::jsonb, 'ban', null);
  end if;
  return jsonb_build_object(
    'on', true,
    'warnings', coalesce((
      select jsonb_agg(jsonb_build_object('id', w.id, 'at', w.created_at, 'proof', public.standing_proof_public(w.proof)) order by w.created_at desc)
        from public.user_warnings w
       where w.user_id = me and w.removed_at is null and w.created_at > now() - interval '3 days' and w.proof is not null), '[]'::jsonb),
    'ban', (select public.standing_proof_public(b.proof) from public.site_bans b
             where b.user_id = me and (b.expires_at is null or b.expires_at > now()) and b.proof is not null));
end $function$;

-- public.my_standing()  [security definer]
CREATE OR REPLACE FUNCTION public.my_standing()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); tier text; n int; s public.account_suspensions; oldest timestamptz; improves timestamptz;
begin
  if me is null then return null; end if;
  tier := public.standing_tier(me);
  select count(*), min(created_at) into n, oldest from public.user_warnings
    where user_id = me and removed_at is null and created_at > now() - interval '3 days';
  select * into s from public.account_suspensions where user_id = me and (until is null or until > now());
  improves := case when s.user_id is not null then s.until when n > 0 then oldest + interval '3 days' else null end;
  return jsonb_build_object(
    'on', public.feature_on('account_standing', null),
    'tier', tier,
    'active_warnings', n,
    'warnings', coalesce((select jsonb_agg(jsonb_build_object('reason', w.reason, 'at', w.created_at, 'expires', w.created_at + interval '3 days') order by w.created_at desc)
                 from public.user_warnings w where w.user_id = me and w.removed_at is null and w.created_at > now() - interval '3 days'), '[]'::jsonb),
    'suspended', case when s.user_id is null then null else jsonb_build_object('reason', s.reason, 'until', s.until, 'at', s.created_at) end,
    'improves_at', improves);
end $function$;

-- public.my_status_pref()  [security definer]
