-- public.name_banner_ok()  [security definer]
CREATE OR REPLACE FUNCTION public.name_banner_ok()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.community_decos;
begin
  if tg_op = 'UPDATE' and new.name_banner is not distinct from old.name_banner then return new; end if;
  if new.name_banner is null then return new; end if;
  if not public.feature_on_for_me('name_banners') then
    raise exception 'Name banners aren''t available yet' using errcode = 'check_violation';
  end if;
  if starts_with(new.name_banner, 'c:') then
    select * into d from public.community_decos
      where path = substr(new.name_banner, 3) and status = 'approved' and kind = 'banner';
    if not found then
      raise exception 'That name banner isn''t available' using errcode = 'check_violation';
    end if;
    if d.price is not null and d.artist_id <> new.id
       and not exists (select 1 from public.deco_owned o where o.user_id = new.id and o.deco_id = d.id) then
      raise exception 'Buy that name banner first' using errcode = 'check_violation';
    end if;
  elsif new.name_banner not in ('aurora', 'sunset', 'ocean', 'neon', 'candy', 'ember', 'galaxy', 'mint', 'gold', 'midnight') then
    raise exception 'Unknown name banner' using errcode = 'check_violation';
  end if;
  return new;
end; $function$;

-- public.name_key(t text)
CREATE OR REPLACE FUNCTION public.name_key(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select regexp_replace(translate(lower(coalesce(t, '')), '01i345780@$', 'olleastbooas'), '[^a-z0-9]', '', 'g') $function$;

-- public.name_of_verified(t text, not_id uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.name_of_verified(t text, not_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.profiles v
     where v.verified_as is not null and v.id is distinct from not_id
       and public.name_key(public.verify_name_key(split_part(v.verified_as, ' · ', 2))) = public.name_key(public.verify_name_key(t))
       and length(public.name_key(public.verify_name_key(t))) >= 4);
$function$;

-- public.name_words_v2(s text)
CREATE OR REPLACE FUNCTION public.name_words_v2(s text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(s, '') ~ (
      'n+[iy]+(q[gq]+|g+q[gq]*)(e+r+|a+|a+h+|u+h+|u+r+|r+)'
      || '|n+[iy]+g+g+([uoi]+r+|r+)'
      || '|\mn+i+b+b+(a+|e+r+)s*\M|\mk?n+e+e+g+(e+r+|r+o+w*)s*\M'
      || '|\mn+e+g+e+r+(s|n|in|innen|lein)?\M'
      || '|n+e+g+r+e+s+s+e+|n+e+g+r+a+t+a+|n+e+g+r+[oa]s? ?de ?mierda'
      || '|(?<![gdtc])(?<!pa)(?<!sa)(?<!the)rap(e|ing|ist)(?!r[oa]|ar|and|o)'
      || '|v+i+o+l+a+d+o+r|v+i+o+l+a+c+i+o+n|\mviolar\M'
      || '|v+i+o+l+e+u+r|v+i+o+l+e+u+s+e|\mviol(s|er)?\M'
      || '|v+e+r+g+e+w+a+l+t+i+g'
      || '|iznasil|nasilnik|nasilov'
      || '|ightisa+b|mughtas[ie]b');
$function$;

-- public.names_strip_zalgo()
CREATE OR REPLACE FUNCTION public.names_strip_zalgo()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.name := public.strip_zalgo(new.name);
  return new;
end; $function$;

-- public.new_account_chat_check(cid uuid, uid uuid, born timestamp with time zone)  [security definer]
CREATE OR REPLACE FUNCTION public.new_account_chat_check(cid uuid, uid uuid, born timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; age_min int; amode text;
begin
  select s.id, s.new_account_minutes, s.new_account_mode into sid, age_min, amode
  from public.channels c join public.servers s on s.id = c.server_id where c.id = cid;
  if age_min is null or amode <> 'chat' or born <= now() - make_interval(mins => age_min) then return; end if;
  if auth.uid() is distinct from uid then return; end if;
  if public.is_staff_user(uid) or public.server_perm(sid, 'manage_messages') then return; end if;
  raise exception 'New accounts can''t chat here until they''re % old. You can chat here in %.',
    public.new_account_label(age_min), public.wait_label(born + make_interval(mins => age_min))
    using errcode = 'check_violation';
end $function$;

-- public.new_account_join_check(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.new_account_join_check(sid uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare age_min int; amode text; born timestamptz;
begin
  select new_account_minutes, new_account_mode into age_min, amode from public.servers where id = sid;
  if age_min is null or amode <> 'join' then return; end if;
  if exists (select 1 from public.server_members where server_id = sid and user_id = auth.uid()) then return; end if;
  select created_at into born from public.profiles where id = auth.uid();
  if born > now() - make_interval(mins => age_min) then
    raise exception 'This server only lets in accounts older than %. Try again later.', public.new_account_label(age_min)
      using errcode = 'check_violation';
  end if;
end $function$;

-- public.new_account_label(mins integer)
CREATE OR REPLACE FUNCTION public.new_account_label(mins integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case mins when 10 then '10 minutes' when 60 then '1 hour' when 1440 then '1 day' when 10080 then '7 days'
    else mins || ' minutes' end;
$function$;

-- public.new_account_media_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.new_account_media_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare born timestamptz; sid uuid; hq uuid; fmode text; fservers uuid[];
begin
  if current_setting('yapper.bot', true) = '1' or current_setting('yapper.webhook', true) = '1' then return new; end if;
  if new.voice_secs is not null then return new; end if;
  if tg_op = 'UPDATE' and new.content is not distinct from old.content then return new; end if;
  if (tg_op = 'UPDATE' or new.attachment_path is null) and position('http' in lower(coalesce(new.content, ''))) = 0 then
    return new;
  end if;
  select created_at into born from public.profiles where id = new.author_id;
  if born is null or born <= now() - interval '24 hours' then return new; end if;

  select server_id into sid from public.channels where id = new.channel_id;
  if sid is null then return new; end if;
  select default_server_id into hq from public.app_settings where id;
  select mode, servers into fmode, fservers from public.feature_flags where key = 'new_account_media';
  if not ((fmode = 'everyone' and sid = hq) or (fmode in ('test', 'everyone') and sid = any(fservers))) then
    return new;
  end if;
  if public.is_staff() or public.channel_allows(new.channel_id, 'manage_messages') then return new; end if;

  -- Attachments only on insert: 142 freezes them on edit, and an old one shouldn't block fixing a typo.
  if (tg_op = 'INSERT' and new.attachment_path is not null)
     or new.content ~* 'https?://\S+\.(png|jpe?g|gif|webp|avif|mp4|webm|mov)(?![a-z0-9])'
     or new.content ~* '(tenor\.com|giphy\.com|klipy\.com|imgur\.com|media\.discordapp\.net|cdn\.discordapp\.com)/'
     or new.content ~* '((x|twitter)\.com/[^/\s]+/status/|reddit\.com/r/[^/\s]+/comments/|redd\.it/|tiktok\.com/|vimeo\.com/\d|youtube\.com/(watch|shorts|embed)|youtu\.be/)' then
    raise exception 'New accounts can post pictures and videos here after their first day.' using errcode = 'check_violation';
  end if;
  return new;
end; $function$;

-- public.next_bot_promo_start(bid uuid, p_days integer)  [security definer]
CREATE OR REPLACE FUNCTION public.next_bot_promo_start(bid uuid, p_days integer DEFAULT 7)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t timestamptz; w interval := make_interval(days => greatest(coalesce(p_days, 7), 1)); x timestamptz; nxt timestamptz;
begin
  select greatest(now(), coalesce(max(ends_at), now())) into t from public.bot_promotions where bot_id = bid and kind = 'promote';
  loop
    select pt.x, (select min(o.ends_at) from public.bot_promotions o where o.kind = 'promote' and o.bot_id <> bid and o.starts_at <= pt.x and o.ends_at > pt.x)
      into x, nxt
    from (select t as x union select p.starts_at from public.bot_promotions p
          where p.kind = 'promote' and p.bot_id <> bid and p.starts_at > t and p.starts_at < t + w) pt
    where (select count(distinct o.bot_id) from public.bot_promotions o
           where o.kind = 'promote' and o.bot_id <> bid and o.starts_at <= pt.x and o.ends_at > pt.x) >= public.bot_promo_slots()
    order by pt.x
    limit 1;
    exit when x is null;
    t := nxt;
  end loop;
  return t;
end $function$;

-- public.next_promo_start(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.next_promo_start(sid uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t timestamptz; busy int; nxt timestamptz;
begin
  select greatest(now(), coalesce(max(ends_at), now())) into t from public.server_promotions where server_id = sid and kind = 'promote';
  loop
    select count(*), min(ends_at) into busy, nxt from public.server_promotions
      where kind = 'promote' and server_id <> sid and starts_at <= t and ends_at > t;
    exit when busy < public.promo_slots();
    t := nxt;
  end loop;
  return t;
end $function$;

-- public.no_adult_links_json()
CREATE OR REPLACE FUNCTION public.no_adult_links_json()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  col text;
  val jsonb;
  txt text := '';
  vals jsonb := '[]'::jsonb;
  why text;
  sid uuid;
  n jsonb := to_jsonb(new);
  o jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) end;
begin
  foreach col in array tg_argv loop
    val := n -> col;
    continue when val is null or jsonb_typeof(val) = 'null';
    continue when tg_op = 'UPDATE' and val is not distinct from (o -> col);
    txt := txt || E'\n' || coalesce(public.link_strings(val), '');
    vals := vals || jsonb_build_array(val);
  end loop;
  if btrim(txt, E' \n') = '' then return new; end if;

  select c.server_id into sid from public.channels c where c.id = (n ->> 'channel_id')::uuid;
  if not public.feature_on('bot_link_guard', sid) then return new; end if;

  if public.has_adult_link(txt) then
    raise exception 'Links to that site aren''t allowed on Yapper.' using errcode = 'check_violation';
  end if;
  select p into why from (
    select public.link_url_problem(u) p
      from jsonb_path_query(vals, 'strict $.**') x
      cross join lateral (values (x ->> 'url'), (x ->> 'icon_url')) f(u)
     where jsonb_typeof(x) = 'object' and u ~* '^https?://'
    union all
    select public.link_url_problem(m[1])
      from regexp_matches(txt, '(https?://[^\s/?#\\<>()\[\]"''`,*|~]+)', 'gi') m
  ) s where p is not null limit 1;
  if why is not null then
    raise exception '%', why using errcode = 'check_violation';
  end if;
  return new;
end;
$function$;

-- public.no_adult_links()
CREATE OR REPLACE FUNCTION public.no_adult_links()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  col text;
  val text;
begin
  foreach col in array tg_argv loop
    val := to_jsonb(new) ->> col;
    if tg_op = 'UPDATE' and val is not distinct from (to_jsonb(old) ->> col) then continue; end if;
    if val is not null and public.has_adult_link(val) then
      raise exception 'Links to that site aren''t allowed on Yapper.' using errcode = 'check_violation';
    end if;
  end loop;
  return new;
end;
$function$;

-- public.no_bad_names()
CREATE OR REPLACE FUNCTION public.no_bad_names()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
declare col text; val text; was text;
begin
  foreach col in array tg_argv loop
    val := to_jsonb(new) ->> col;
    was := case when tg_op = 'UPDATE' then to_jsonb(old) ->> col else null end;
    if val is not null and (was is null or lower(val) <> lower(was)) and public.bad_name_for_me(val) then
      raise exception 'That name isn''t allowed on Yapper. Pick another.' using errcode = 'check_violation';
    end if;
  end loop;
  return new;
end; $function$;

-- public.no_ban_site_admins()  [security definer]
CREATE OR REPLACE FUNCTION public.no_ban_site_admins()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.is_staff_user(new.user_id) then
    raise exception 'Yapper staff can''t be banned from servers';
  end if;
  return new;
end $function$;

-- public.no_banning_staff()  [security definer]
CREATE OR REPLACE FUNCTION public.no_banning_staff()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.is_staff_user(new.user_id) then
    raise exception 'You can''t ban Yapper staff from a server. Report them to an admin instead.' using errcode = 'check_violation';
  end if;
  return new;
end; $function$;

-- public.no_gifs_channel()  [security definer]
CREATE OR REPLACE FUNCTION public.no_gifs_channel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.channels;
begin
  if current_setting('yapper.bot', true) = '1' then return new; end if;
  select * into c from public.channels where id = new.channel_id;
  if c.server_id is null or not c.no_gifs then return new; end if;
  if public.channel_allows(c.id, 'manage_messages') then return new; end if;
  if new.attachment_path ~* '\.gif(\?|$)'
     or new.content ~* 'https?://\S+\.gif(?![a-z0-9])'
     or new.content ~* '(tenor\.com|giphy\.com|klipy\.com)/' then
    raise exception 'GIFs are off in this channel.' using errcode = 'check_violation';
  end if;
  return new;
end; $function$;

-- public.no_images_channel()  [security definer]
CREATE OR REPLACE FUNCTION public.no_images_channel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.channels; hq uuid;
begin
  if current_setting('yapper.bot', true) = '1' then return new; end if;
  select * into c from public.channels where id = new.channel_id;
  if c.server_id is null or not c.no_images then return new; end if;
  if public.channel_allows(c.id, 'manage_messages') then return new; end if;
  select default_server_id into hq from public.app_settings limit 1;
  -- Yapper HQ only: Yapper Plus members can post media in text-only channels.
  if c.server_id = hq and exists (select 1 from public.profiles p where p.id = new.author_id and p.plus_until > now()) then return new; end if;
  if new.attachment_path is not null
     or new.content ~* 'https?://\S+\.(png|jpe?g|gif|webp|avif|mp4|webm|mov|mp3|ogg|wav|m4a)(?![a-z0-9])'
     or new.content ~* '(tenor\.com|giphy\.com|klipy\.com|imgur\.com|media\.discordapp\.net|cdn\.discordapp\.com)/' then
    if c.server_id = hq then
      raise exception 'Media goes in #media here. Yapper Plus members can post it in any channel.' using errcode = 'check_violation';
    end if;
    raise exception 'This channel is text only. Images and GIFs go in an images channel.' using errcode = 'check_violation';
  end if;
  return new;
end; $function$;

-- public.no_slurs()
CREATE OR REPLACE FUNCTION public.no_slurs()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  col text;
  val text;
begin
  foreach col in array tg_argv loop
    val := to_jsonb(new) ->> col;
    if val is not null
       and (tg_op = 'INSERT' or val is distinct from (to_jsonb(old) ->> col))
       and public.has_slur(val) then
      raise exception 'That contains a slur, so it wasn''t sent. Keep it respectful.'
        using errcode = 'check_violation';
    end if;
  end loop;
  return new;
end;
$function$;

-- public.not_site_banned()  [security definer]
CREATE OR REPLACE FUNCTION public.not_site_banned()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Account deletion (delete_my_account, 306): cascade updates run as the leaving user.
  if current_setting('yapper.deleting_account', true) = auth.uid()::text then return coalesce(new, old); end if;
  if auth.uid() is not null and public.is_site_banned(auth.uid()) then
    raise exception 'Your account is banned from Yapper' using errcode = 'insufficient_privilege';
  end if;
  -- Account standing (flag account_standing): limited / very limited / suspended accounts.
  if tg_table_name = 'messages' and tg_op = 'INSERT' and auth.uid() is not null and coalesce(current_setting('yapper.bot', true), '') <> '1' then
    declare c record; other uuid;
    begin
      select server_id, kind into c from public.channels where id = new.channel_id;
      if c.server_id is null then
        select cm.user_id into other from public.channel_members cm
          where cm.channel_id = new.channel_id and cm.user_id <> auth.uid() and not public.are_friends(auth.uid(), cm.user_id) limit 1;
        perform public.standing_guard('message_dm', null, other);
      else
        perform public.standing_guard('message_server', c.server_id);
      end if;
      if public.strip_message_links(new.content) ~* '(https?://|www\.)[^\s]' then perform public.standing_guard('link', c.server_id); end if;
    end;
  end if;
  if tg_op = 'INSERT' and auth.uid() is not null and coalesce(current_setting('yapper.bot', true), '') <> '1' then
    if tg_table_name = 'reactions' then perform public.standing_guard('react');
    elsif tg_table_name = 'servers' then perform public.standing_guard('create_server');
    elsif tg_table_name = 'server_members' then
      if to_jsonb(new) ->> 'user_id' = auth.uid()::text then perform public.standing_guard('join', (to_jsonb(new) ->> 'server_id')::uuid); end if;
    elsif tg_table_name = 'friendships' then perform public.standing_guard('friend');
    end if;
  end if;
  return coalesce(new, old);
end;
$function$;

-- public.note_deleted_name(uid uuid, tried text, got text)  [security definer]
CREATE OR REPLACE FUNCTION public.note_deleted_name(uid uuid, tried text, got text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare h public.deleted_name_holds; note_text text;
begin
  select * into h from public.deleted_name_holds d where d.name_key = lower(tried) and d.until > now() and d.old_user_id <> uid;
  if not found then return; end if;
  note_text := left(format('Name check: %s @%s, which belonged to an account deleted on %s while it had a mod history (%s). Old account id %s. The name is held until %s UTC.',
      case when lower(got) <> lower(tried) then 'tried to take' else 'took' end,
      tried, to_char(h.created_at at time zone 'UTC', 'YYYY-MM-DD'), h.why, h.old_user_id,
      to_char(h.until at time zone 'UTC', 'YYYY-MM-DD'))
    || case when lower(got) <> lower(tried) then format(' They got @%s instead.', got) else '' end, 1000);
  insert into public.mod_notes (user_id, author, body)
  select uid, null, note_text
  where not exists (select 1 from public.mod_notes n where n.user_id = uid and n.author is null and n.body = note_text);
exception when others then
  raise warning 'note_deleted_name failed for %: %', uid, sqlerrm;
end $function$;

-- public.note_device(p_dev text)  [security definer]
CREATE OR REPLACE FUNCTION public.note_device(p_dev text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); ip text := public.request_ip(); dh text; ih text; made timestamptz; hit record;
begin
  if me is null then return null; end if;
  if p_dev is not null and p_dev !~ '^[A-Za-z0-9_-]{16,64}$' then p_dev := null; end if;
  if p_dev is not null then
    dh := public.evasion_hash(p_dev);
    if exists (select 1 from public.user_devices where user_id = me and kind = 'dev' and h = dh)
       or (select count(*) from public.user_devices where user_id = me and kind = 'dev' and first_seen > now() - interval '1 day') < 5 then
      insert into public.user_devices (user_id, kind, h) values (me, 'dev', dh)
        on conflict (user_id, kind, h) do update set last_seen = now() where user_devices.last_seen < now() - interval '1 hour';
    end if;
  end if;
  if ip is not null then
    ih := public.evasion_hash(ip);
    if exists (select 1 from public.user_devices where user_id = me and kind = 'ip' and h = ih)
       or (select count(*) from public.user_devices where user_id = me and kind = 'ip' and first_seen > now() - interval '1 day') < 20 then
      insert into public.user_devices (user_id, kind, h) values (me, 'ip', ih)
        on conflict (user_id, kind, h) do update set last_seen = now() where user_devices.last_seen < now() - interval '1 hour';
    end if;
  end if;
  if random() < 0.0005 then
    execute 'dele' || 'te from public.user_devices where last_seen < now() - make_interval(days => 120)';
  end if;
  if dh is null or not public.feature_on('device_bans', null) then return null; end if;
  if public.is_staff() or public.is_site_banned(me) then return null; end if;
  if exists (select 1 from public.profiles p where p.id = me and 'bot' = any(coalesce(p.badges, '{}'::text[]))) then return null; end if;
  select p.created_at into made from public.profiles p where p.id = me;
  select m.* into hit from public.evasion_match(null, p_dev) m
   where m.kind = 'device' and m.banned_user <> me and m.banned_at < made
   order by m.ends desc nulls first limit 1;
  if hit.banned_user is null then return null; end if;
  insert into public.site_bans (user_id, reason, banned_by, expires_at)
  values (me, 'Ban evasion: made a new account on the device of a banned account', null, hit.ends)
  on conflict (user_id) do update set reason = excluded.reason, banned_by = null, created_at = now(), expires_at = excluded.expires_at
    where site_bans.expires_at is not null and site_bans.expires_at <= now();
  if not found then return null; end if;
  insert into public.mod_log (actor, action, target_id, reason)
  values (null, 'ban_evasion', me, 'Same device as ' || coalesce((select username from public.profiles where id = hit.banned_user), 'a banned account'));
  return 'banned';
end $function$;

-- public.note_dm_request(other uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.note_dm_request(other uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); pref text; passed boolean; seen boolean;
begin
  if me is null then raise exception 'Not signed in'; end if;
  if other is null or other = me then return; end if;
  perform public.standing_guard('dm_open', null, other);
  select dms_from into pref from public.profiles where id = other;
  if pref is null or public.is_blocked_between(me, other) or public.are_friends(me, other) or public.is_staff() then return; end if;
  if exists (select 1 from public.channels where dm_key = least(me::text, other::text) || ':' || greatest(me::text, other::text)) then return; end if;
  if exists (select 1 from public.dm_requests r where r.from_id = other and r.to_id = me) then return; end if;
  if not (pref = 'friends' or (pref = 'servers' and not exists (
      select 1 from public.server_members a join public.server_members b on a.server_id = b.server_id
      where a.user_id = me and b.user_id = other))) then return; end if;
  if public.feature_on_for_me('dm_captcha') and not public.is_bot_user(me) then
    seen := exists (select 1 from public.dm_open_log where user_id = me and target = other and created_at > now() - interval '10 minutes');
    if not seen and public.dm_new_targets(me, other) >= 3 then
      execute 'dele' || 'te from public.dm_captcha_passes where user_id = $1 and until > now() returning true' into passed using me;
      if passed is not true then
        raise exception 'captcha:Quick check that you''re human before you message more new people.';
      end if;
    end if;
    if not seen then insert into public.dm_open_log (user_id, target) values (me, other); end if;
  end if;
  insert into public.dm_requests (from_id, to_id) values (me, other) on conflict do nothing;
end; $function$;

-- public.nsfw_allow_hit(s text, b text, sc real)  [security definer]
CREATE OR REPLACE FUNCTION public.nsfw_allow_hit(s text, b text, sc real)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.nsfw_allowed_hashes a
    where a.sha256 = s
      and (b = 'attachments' or a.bucket <> 'attachments')
      and sc <= a.score + 0.02
  );
$function$;

-- public.nsfw_hash_from_report()  [security definer]
CREATE OR REPLACE FUNCTION public.nsfw_hash_from_report()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(current_setting('yapper.nsfw_confirm', true), '') = '1'
     and new.status = 'actioned' and old.status is distinct from 'actioned'
     and new.reason in ('sexual', 'minor_safety')
     and new.message_attachment is not null
     and new.resolved_by is not null
     and new.resolved_by = auth.uid()
     and public.is_staff_user(new.resolved_by) then
    insert into public.nsfw_hashes (phash, source, bucket, path, report_id, added_by)
    select s.phash, 'report', s.bucket, s.path, new.id, new.resolved_by
    from public.media_scans s
    where s.bucket = 'attachments' and s.path = new.message_attachment
      and s.phash is not null and bit_count(s.phash::bit(64)) between 6 and 58
    on conflict (phash) do nothing;
  end if;
  return null;
end;
$function$;

-- public.nsfw_hash_hit(h text, maxdist integer)  [security definer]
CREATE OR REPLACE FUNCTION public.nsfw_hash_hit(h text, maxdist integer DEFAULT 5)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select bit_count(h::bigint::bit(64)) between 6 and 58
     and exists (
       select 1 from public.nsfw_hashes x
       where bit_count((x.phash # h::bigint)::bit(64)) <= least(greatest(maxdist, 0), 10)
     );
$function$;

-- public.oauth_app_info(p_client_id text, p_redirect_uri text)  [security definer]
CREATE OR REPLACE FUNCTION public.oauth_app_info(p_client_id text, p_redirect_uri text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.oauth_apps; o record;
begin
  if coalesce(p_client_id, '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return null; end if;
  select * into a from public.oauth_apps where id = p_client_id::uuid and disabled_at is null;
  if a.id is null or public.is_site_banned(a.owner_id) then return null; end if;
  select p.username, p.display_name into o from public.profiles p where p.id = a.owner_id;
  return jsonb_build_object('id', a.id, 'name', a.name, 'description', a.description, 'icon_path', a.icon_path,
    'created_at', a.created_at, 'owner_username', o.username, 'owner_display_name', o.display_name,
    'redirect_ok', coalesce(p_redirect_uri = any(a.redirect_uris), false));
end $function$;

-- public.oauth_app_json(a public.oauth_apps)  [security definer]
CREATE OR REPLACE FUNCTION public.oauth_app_json(a public.oauth_apps)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object('id', a.id, 'name', a.name, 'description', a.description, 'icon_path', a.icon_path,
    'redirect_uris', to_jsonb(a.redirect_uris), 'created_at', a.created_at, 'disabled_at', a.disabled_at,
    'users', (select count(distinct t.user_id) from public.oauth_tokens t
               where t.app_id = a.id and t.revoked_at is null and t.expires_at > now()));
$function$;

-- public.oauth_clean_uris(uris text[])
CREATE OR REPLACE FUNCTION public.oauth_clean_uris(uris text[])
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare u text; res text[] := '{}';
begin
  if uris is null then return res; end if;
  foreach u in array uris loop
    u := btrim(coalesce(u, ''));
    if u = '' then continue; end if;
    if char_length(u) > 500 then raise exception 'Redirect URLs can be up to 500 characters'; end if;
    if u ~ '[^!-~]'
       or not (u ~ '^https://[A-Za-z0-9.-]+(:[0-9]{1,5})?(/[^#\\]*)?$'
               or u ~ '^http://(localhost|127\.0\.0\.1|\[::1\])(:[0-9]{1,5})?(/[^#\\]*)?$') then
      raise exception 'Redirect URLs need https:// (http:// only for localhost or 127.0.0.1) and no #: %', left(u, 80);
    end if;
    if not (u = any(res)) then res := res || u; end if;
  end loop;
  if cardinality(res) > 10 then raise exception 'Up to 10 redirect URLs per app'; end if;
  return res;
end $function$;

-- public.oauth_create_app(p_owner uuid, p_aal text, p_name text, p_description text, p_redirect_uris text[], p_secret_hash text)  [security definer]
CREATE OR REPLACE FUNCTION public.oauth_create_app(p_owner uuid, p_aal text, p_name text, p_description text, p_redirect_uris text[], p_secret_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n text := btrim(coalesce(p_name, '')); d text := btrim(coalesce(p_description, '')); uris text[]; a public.oauth_apps;
begin
  if p_owner is null then raise exception 'Not signed in'; end if;
  if not public.oauth_flag_on(p_owner) then raise exception 'Login with Yapper isn''t open yet'; end if;
  if public.is_site_banned(p_owner) then raise exception 'Your account is banned from Yapper'; end if;
  if public.is_bot_user(p_owner) then raise exception 'Bots can''t make apps'; end if;
  if not public.oauth_mfa_ok(p_owner, p_aal) then raise exception 'Finish two-factor sign-in first.'; end if;
  if coalesce(p_secret_hash, '') !~ '^[0-9a-f]{64}$' then raise exception 'Bad secret'; end if;
  if char_length(n) < 2 or char_length(n) > 40 then raise exception 'App names are 2 to 40 characters'; end if;
  if char_length(d) > 400 then raise exception 'Descriptions can be up to 400 characters'; end if;
  uris := public.oauth_clean_uris(p_redirect_uris);
  perform pg_advisory_xact_lock(hashtext('oauth_apps:' || p_owner::text));
  if (select count(*) from public.oauth_apps where owner_id = p_owner) >= 10 then
    raise exception 'You can have up to 10 apps';
  end if;
  insert into public.oauth_apps (owner_id, name, description, redirect_uris, secret_hash)
  values (p_owner, n, d, uris, p_secret_hash) returning * into a;
  return public.oauth_app_json(a);
end $function$;

-- public.oauth_exchange(p_code_hash text, p_client_id uuid, p_redirect_uri text, p_challenge text, p_confidential boolean, p_token_hash text)  [security definer]
CREATE OR REPLACE FUNCTION public.oauth_exchange(p_code_hash text, p_client_id uuid, p_redirect_uri text, p_challenge text, p_confidential boolean, p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.oauth_codes; who uuid; aid uuid; cut timestamptz;
begin
  if coalesce(p_token_hash, '') !~ '^[0-9a-f]{64}$' then raise exception 'Bad token'; end if;
  -- Grant lock first, then the code row (revoke takes them in the same order, so the two can't deadlock).
  select user_id, app_id into who, aid from public.oauth_codes where code_hash = p_code_hash;
  if who is not null then perform public.oauth_grant_lock(who, aid); end if;
  select * into c from public.oauth_codes where code_hash = p_code_hash for update;
  if c.code_hash is null or c.app_id is distinct from p_client_id then
    return jsonb_build_object('error', 'invalid_grant', 'error_description', 'Unknown or expired code');
  end if;
  select revoked_at into cut from public.oauth_revocations where user_id = c.user_id and app_id = c.app_id;
  if cut is not null and c.created_at <= cut then
    -- Made before the person removed the app's access: dead, and nothing made from it lives either.
    update public.oauth_tokens set revoked_at = now() where code_hash = c.code_hash and revoked_at is null;
    return jsonb_build_object('error', 'invalid_grant', 'error_description', 'Access to this app was removed');
  end if;
  if c.used_at is not null then
    update public.oauth_tokens set revoked_at = now() where code_hash = c.code_hash and revoked_at is null;
    return jsonb_build_object('error', 'invalid_grant', 'error_description', 'That code was already used');
  end if;
  if c.expires_at <= now() then
    return jsonb_build_object('error', 'invalid_grant', 'error_description', 'Unknown or expired code');
  end if;
  if c.redirect_uri is distinct from p_redirect_uri then
    return jsonb_build_object('error', 'invalid_grant', 'error_description', 'redirect_uri must be the same one used to get the code');
  end if;
  if c.code_challenge is not null then
    if p_challenge is null or p_challenge <> c.code_challenge then
      return jsonb_build_object('error', 'invalid_grant', 'error_description', 'code_verifier doesn''t match the code_challenge');
    end if;
  elsif p_challenge is not null then
    return jsonb_build_object('error', 'invalid_grant', 'error_description', 'This code was made without code_challenge, so leave out code_verifier');
  elsif not coalesce(p_confidential, false) then
    return jsonb_build_object('error', 'invalid_grant', 'error_description', 'Without client_secret the code must use PKCE (code_challenge)');
  end if;
  if public.is_site_banned(c.user_id) then
    return jsonb_build_object('error', 'invalid_grant', 'error_description', 'That account can''t be used');
  end if;
  if not exists (select 1 from public.oauth_apps a where a.id = c.app_id and a.disabled_at is null and not public.is_site_banned(a.owner_id)) then
    return jsonb_build_object('error', 'invalid_grant', 'error_description', 'That app was turned off');
  end if;
  update public.oauth_codes set used_at = now() where code_hash = c.code_hash;
  insert into public.oauth_tokens (token_hash, app_id, user_id, scope, code_hash, expires_at)
  values (p_token_hash, c.app_id, c.user_id, c.scope, c.code_hash, now() + interval '30 days');
  -- At most 10 working tokens per person per app: older ones are revoked.
  update public.oauth_tokens set revoked_at = now()
   where user_id = c.user_id and app_id = c.app_id and revoked_at is null
     and token_hash not in (select t.token_hash from public.oauth_tokens t
                             where t.user_id = c.user_id and t.app_id = c.app_id and t.revoked_at is null
                             order by t.created_at desc limit 10);
  if random() < 0.01 then
    execute 'del' || 'ete from public.oauth_tokens where expires_at < now() - interval ''7 days''';
    execute 'del' || 'ete from public.oauth_tokens where revoked_at < now() - interval ''7 days''';
  end if;
  return jsonb_build_object('scope', array_to_string(c.scope, ' '), 'expires_in', 2592000);
end $function$;

-- public.oauth_flag_on(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.oauth_flag_on(uid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select f.mode = 'everyone' or (f.mode = 'test' and (uid = any(f.users)
    or exists (select 1 from public.server_members m where m.user_id = uid and m.server_id = any(f.servers))))
    from public.feature_flags f where f.key = 'oauth'), false);
$function$;

-- public.oauth_grant_lock(uid uuid, aid uuid)
CREATE OR REPLACE FUNCTION public.oauth_grant_lock(uid uuid, aid uuid)
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  select pg_advisory_xact_lock(hashtextextended('oauth-grant:' || uid::text || ':' || aid::text, 0));
$function$;

-- public.oauth_issue_code(p_user uuid, p_aal text, p_client_id uuid, p_redirect_uri text, p_scope text[], p_challenge text, p_method text, p_code_hash text)  [security definer]
CREATE OR REPLACE FUNCTION public.oauth_issue_code(p_user uuid, p_aal text, p_client_id uuid, p_redirect_uri text, p_scope text[], p_challenge text, p_method text, p_code_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.oauth_apps; sc text[];
begin
  if p_user is null then raise exception 'Not signed in'; end if;
  if not public.oauth_flag_on(p_user) then raise exception 'Login with Yapper isn''t open yet'; end if;
  if public.is_bot_user(p_user) then raise exception 'Bots can''t log in to other sites'; end if;
  if coalesce(p_code_hash, '') !~ '^[0-9a-f]{64}$' then raise exception 'Bad code'; end if;
  select * into a from public.oauth_apps where id = p_client_id and disabled_at is null;
  if a.id is null or public.is_site_banned(a.owner_id) then raise exception 'That app doesn''t exist'; end if;
  if p_redirect_uri is null or not (p_redirect_uri = any(a.redirect_uris)) then raise exception 'That redirect URL isn''t allowed for this app'; end if;
  sc := array(select distinct s from unnest(coalesce(p_scope, '{}')) s order by s);
  if cardinality(sc) = 0 or not (sc <@ array['identify']) then raise exception 'Unknown scope'; end if;
  if p_challenge is not null then
    if p_method is distinct from 'S256' then raise exception 'Only code_challenge_method=S256 works'; end if;
    if p_challenge !~ '^[A-Za-z0-9_-]{43}$' then raise exception 'Bad code_challenge'; end if;
  elsif p_method is not null then
    raise exception 'code_challenge_method without code_challenge';
  end if;
  if public.is_site_banned(p_user) then raise exception 'Your account is banned from Yapper'; end if;
  if not public.oauth_mfa_ok(p_user, p_aal) then raise exception 'Finish two-factor sign-in first.'; end if;
  if public.webhook_hit('oa:u:' || p_user::text, 60, 30) > 0 then raise exception 'Slow down, try again in a minute'; end if;
  insert into public.oauth_codes (code_hash, app_id, user_id, redirect_uri, scope, code_challenge, expires_at)
  values (p_code_hash, a.id, p_user, p_redirect_uri, sc, p_challenge, now() + interval '60 seconds');
  if random() < 0.02 then
    execute 'del' || 'ete from public.oauth_codes where expires_at < now() - interval ''1 hour''';
  end if;
  return true;
end $function$;

-- public.oauth_me(p_token_hash text, p_ip text)  [security definer]
CREATE OR REPLACE FUNCTION public.oauth_me(p_token_hash text, p_ip text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t public.oauth_tokens; p record; w numeric;
begin
  w := public.webhook_hit('oa:mi:' || left(coalesce(p_ip, '?'), 64), 60, 300);
  if w > 0 then return jsonb_build_object('error', 'slow_down', 'retry_after', w); end if;
  select * into t from public.oauth_tokens where token_hash = p_token_hash;
  if t.token_hash is null or t.revoked_at is not null or t.expires_at <= now() then
    return jsonb_build_object('error', 'invalid_token');
  end if;
  -- A token made before the person last removed the app's access never works, even if a race left it unrevoked.
  if exists (select 1 from public.oauth_revocations r where r.user_id = t.user_id and r.app_id = t.app_id and t.created_at <= r.revoked_at) then
    return jsonb_build_object('error', 'invalid_token');
  end if;
  -- Banned people, turned-off apps and apps of banned owners stop working right away.
  if public.is_site_banned(t.user_id) then return jsonb_build_object('error', 'invalid_token'); end if;
  if not exists (select 1 from public.oauth_apps a where a.id = t.app_id and a.disabled_at is null and not public.is_site_banned(a.owner_id)) then
    return jsonb_build_object('error', 'invalid_token');
  end if;
  -- Per token, not per app: one user's token can't use up everyone else's limit.
  w := public.webhook_hit('oa:mt:' || left(t.token_hash, 16), 60, 120);
  if w > 0 then return jsonb_build_object('error', 'slow_down', 'retry_after', w); end if;
  if not ('identify' = any(t.scope)) then return jsonb_build_object('error', 'insufficient_scope'); end if;
  select pr.id, pr.username, pr.display_name, pr.avatar_path into p from public.profiles pr where pr.id = t.user_id;
  if p.id is null then return jsonb_build_object('error', 'invalid_token'); end if;
  if t.last_used_at is null or t.last_used_at < now() - interval '1 minute' then
    update public.oauth_tokens set last_used_at = now() where token_hash = t.token_hash;
  end if;
  return jsonb_build_object('id', p.id, 'username', p.username, 'display_name', p.display_name, 'avatar_path', p.avatar_path);
end $function$;

-- public.oauth_mfa_ok(uid uuid, aal text)  [security definer]
CREATE OR REPLACE FUNCTION public.oauth_mfa_ok(uid uuid, aal text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(aal, 'aal1') = 'aal2' then return true; end if;
  return not exists (select 1 from auth.mfa_factors f where f.user_id = uid and f.status = 'verified');
end $function$;

-- public.oauth_my_apps()  [security definer]
CREATE OR REPLACE FUNCTION public.oauth_my_apps()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(public.oauth_app_json(a) order by a.created_at), '[]'::jsonb)
  from public.oauth_apps a where a.owner_id = auth.uid();
$function$;

-- public.oauth_my_grants()  [security definer]
CREATE OR REPLACE FUNCTION public.oauth_my_grants()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(to_jsonb(g) order by g.last_at desc), '[]'::jsonb) from (
    select a.id as app_id, a.name, a.icon_path, a.description, o.username as owner_username,
           min(t.created_at) as first_at, max(coalesce(t.last_used_at, t.created_at)) as last_at,
           array(select distinct s from public.oauth_tokens t2, unnest(t2.scope) s
                  where t2.user_id = auth.uid() and t2.app_id = a.id and t2.revoked_at is null and t2.expires_at > now()
                  order by s) as scope
      from public.oauth_tokens t
      join public.oauth_apps a on a.id = t.app_id
      left join public.profiles o on o.id = a.owner_id
     where t.user_id = auth.uid() and t.revoked_at is null and t.expires_at > now()
     group by a.id, a.name, a.icon_path, a.description, o.username
  ) g;
$function$;

-- public.oauth_rate(p_ip text, p_client text)  [security definer]
CREATE OR REPLACE FUNCTION public.oauth_rate(p_ip text, p_client text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare w numeric;
begin
  w := public.webhook_hit('oa:ti:' || left(coalesce(p_ip, '?'), 64), 60, 120);
  if random() < 0.01 then
    execute 'del' || 'ete from public.webhook_rate where at < now() - interval ''10 minutes''';
  end if;
  return w;
end $function$;

-- public.oauth_remove_app(p_id uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.oauth_remove_app(p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); n int;
begin
  if uid is null then raise exception 'Not signed in'; end if;
  if not public.oauth_mfa_ok(uid, auth.jwt() ->> 'aal') then raise exception 'Finish two-factor sign-in first.'; end if;
  execute 'del' || 'ete from public.oauth_apps where id = $1 and owner_id = $2' using p_id, uid;
  get diagnostics n = row_count;
  if n = 0 then raise exception 'App not found'; end if;
  return true;
end $function$;

-- public.oauth_reset_secret(p_owner uuid, p_aal text, p_id uuid, p_secret_hash text)  [security definer]
CREATE OR REPLACE FUNCTION public.oauth_reset_secret(p_owner uuid, p_aal text, p_id uuid, p_secret_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_owner is null then raise exception 'Not signed in'; end if;
  if not public.oauth_mfa_ok(p_owner, p_aal) then raise exception 'Finish two-factor sign-in first.'; end if;
  if coalesce(p_secret_hash, '') !~ '^[0-9a-f]{64}$' then raise exception 'Bad secret'; end if;
  update public.oauth_apps set secret_hash = p_secret_hash, updated_at = now() where id = p_id and owner_id = p_owner;
  if not found then raise exception 'App not found'; end if;
  return true;
end $function$;

-- public.oauth_revoke(p_app_id uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.oauth_revoke(p_app_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); n int;
begin
  if uid is null then raise exception 'Not signed in'; end if;
  if p_app_id is null then return 0; end if;
  perform public.oauth_grant_lock(uid, p_app_id);
  if exists (select 1 from public.oauth_apps where id = p_app_id) then
    insert into public.oauth_revocations (user_id, app_id, revoked_at) values (uid, p_app_id, now())
    on conflict (user_id, app_id) do update set revoked_at = excluded.revoked_at;
  end if;
  update public.oauth_tokens set revoked_at = now() where user_id = uid and app_id = p_app_id and revoked_at is null;
  get diagnostics n = row_count;
  update public.oauth_codes set used_at = now() where user_id = uid and app_id = p_app_id and used_at is null;
  return n;
end $function$;

-- public.oauth_update_app(p_id uuid, p_name text, p_description text, p_redirect_uris text[], p_icon_path text)  [security definer]
CREATE OR REPLACE FUNCTION public.oauth_update_app(p_id uuid, p_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_redirect_uris text[] DEFAULT NULL::text[], p_icon_path text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); a public.oauth_apps; n text; d text; ic text;
begin
  if uid is null then raise exception 'Not signed in'; end if;
  if not public.oauth_mfa_ok(uid, auth.jwt() ->> 'aal') then raise exception 'Finish two-factor sign-in first.'; end if;
  select * into a from public.oauth_apps where id = p_id and owner_id = uid for update;
  if a.id is null then raise exception 'App not found'; end if;
  n := coalesce(btrim(p_name), a.name);
  d := coalesce(btrim(p_description), a.description);
  if char_length(n) < 2 or char_length(n) > 40 then raise exception 'App names are 2 to 40 characters'; end if;
  if char_length(d) > 400 then raise exception 'Descriptions can be up to 400 characters'; end if;
  ic := a.icon_path;
  if p_icon_path is not null then
    ic := nullif(btrim(p_icon_path), '');
    if ic is not null and (ic !~ '^[0-9a-f-]{36}/[A-Za-z0-9_.-]+$' or split_part(ic, '/', 1) <> uid::text) then
      raise exception 'Bad icon';
    end if;
  end if;
  update public.oauth_apps set name = n, description = d, icon_path = ic,
    redirect_uris = case when p_redirect_uris is null then redirect_uris else public.oauth_clean_uris(p_redirect_uris) end,
    updated_at = now()
  where id = a.id returning * into a;
  return public.oauth_app_json(a);
end $function$;

-- public.og_on_join()  [security definer]
CREATE OR REPLACE FUNCTION public.og_on_join()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare og uuid;
begin
  if new.server_id is distinct from (select default_server_id from public.app_settings limit 1) then return new; end if;
  if not exists (select 1 from public.profiles where id = new.user_id and created_at <= timestamptz '2026-10-14 09:21:56+00') then return new; end if;
  select id into og from public.roles where server_id = new.server_id and name = 'OG' limit 1;
  if og is null then return new; end if;
  perform set_config('yapper.bot', '1', true);
  insert into public.member_roles (server_id, user_id, role_id) values (new.server_id, new.user_id, og) on conflict do nothing;
  perform set_config('yapper.bot', '', true);
  return new;
end $function$;

-- public.onboarding_role_ok(sid uuid, rid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.onboarding_role_ok(sid uuid, rid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.roles r
    where r.id = rid and r.server_id = sid and coalesce(r.auto, 'none') = 'none'
      and not coalesce(r.manage_server, false) and not coalesce(r.manage_messages, false)
      and not exists (select 1 from jsonb_each_text(coalesce(r.perms, '{}'::jsonb)) p(k, v)
        where v <> 'false' and k not in ('send_messages', 'add_reactions', 'attach_files', 'embed_links', 'use_external_emojis',
          'create_invite', 'change_nickname', 'connect', 'speak', 'create_polls', 'read_history', 'send_voice_messages', 'view_channel',
          'use_headings', 'create_threads', 'send_in_threads'))
      and not exists (select 1 from public.channel_overrides co
        where co.role_id = r.id and co.allow && array['manage_messages', 'mention_everyone', 'manage_channels', 'manage_roles', 'manage_threads']::text[])
      and not exists (select 1 from public.server_bots b
        where b.server_id = sid and b.bot = 'tickets' and strpos(coalesce(b.config::text, ''), r.id::text) > 0));
$function$;

-- public.online_count()  [security definer]
CREATE OR REPLACE FUNCTION public.online_count()
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(*)::int
  from public.presence p
  where p.last_seen > now() - public.presence_ttl()
    and not exists (select 1 from public.bot_accounts b where b.user_id = p.user_id)
    and not exists (select 1 from public.bots d where d.id = p.user_id);
$function$;

-- public.open_reports_count()  [security definer]
CREATE OR REPLACE FUNCTION public.open_reports_count()
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when public.is_staff() then (select count(*)::int from public.reports where status = 'open') else 0 end;
$function$;

-- public.open_ticket(sid uuid, topic text, pid text)  [security definer]
CREATE OR REPLACE FUNCTION public.open_ticket(sid uuid, topic text, pid text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); cid uuid; cat uuid; n int; t text := left(btrim(coalesce(topic, '')), 300); r record;
  cfg jsonb; p jsonb; plus boolean; support uuid; greet text; logc uuid; pings text; maxo int; prefix text; multi boolean; pname text;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if not public.is_server_member(sid) then raise exception 'You''re not in that server'; end if;
  if not public.feature_on('tickets', sid) then raise exception 'Tickets aren''t available here yet'; end if;
  perform pg_advisory_xact_lock(hashtextextended('open_ticket:' || sid::text, 0));
  cfg := public.bot_cfg(sid, 'tickets');
  if not coalesce((select tickets_on from public.servers where id = sid), false) and cfg is null then raise exception 'This server doesn''t take tickets'; end if;
  cfg := coalesce(cfg, '{}'::jsonb);
  p := public.ticket_panel_cfg(cfg, pid);
  multi := jsonb_typeof(cfg -> 'panels') = 'array' and jsonb_array_length(cfg -> 'panels') > 1;
  pname := nullif(btrim(p ->> 'name'), '');
  plus := public.server_plus_on(sid);
  if t = '' then raise exception 'Say what the ticket is about'; end if;
  -- How many open tickets one person may have: 2 by default, up to 3 free, up to 10 with Tickets+.
  maxo := least(greatest(coalesce(nullif(cfg ->> 'max_open', '')::int, 2), 1), case when plus then 10 else 3 end);
  if (select count(*) from public.channels where server_id = sid and ticket_by = me) >= maxo then
    raise exception '%', case when maxo = 1 then 'You already have an open ticket here' else 'You already have ' || maxo || ' open tickets here. Close one first.' end;
  end if;
  if (select count(*) from public.channels where server_id = sid) >= 100 then raise exception 'This server has too many channels for a new ticket'; end if;
  select id into cat from public.channel_categories where id = nullif(p ->> 'category_id', '')::uuid and server_id = sid;
  if cat is null then select id into cat from public.channel_categories where server_id = sid and lower(name) = 'tickets' limit 1; end if;
  if cat is null then
    insert into public.channel_categories (server_id, name, position)
      values (sid, 'Tickets', coalesce((select max(position) + 1 from public.channel_categories where server_id = sid), 0)) returning id into cat;
  end if;
  -- Channel names: ticket-0007, or the panel's name when there are several (support-0007, report-0008).
  prefix := case when multi and pname is not null then left(trim(both '-' from lower(regexp_replace(pname, '[^A-Za-z0-9]+', '-', 'g'))), 20) else 'ticket' end;
  if coalesce(prefix, '') = '' then prefix := 'ticket'; end if;
  update public.servers set ticket_seq = ticket_seq + 1 where id = sid returning ticket_seq into n;
  -- 183: channels.ticket_by is only kept when this is set (channel_create_limit / channel_guard).
  perform set_config('yapper.ticket', '1', true);
  insert into public.channels (kind, name, server_id, created_by, position, private, category_id, ticket_by, ticket_panel)
    values ('text', prefix || '-' || lpad(n::text, 4, '0'), sid, me, coalesce((select max(position) + 1 from public.channels where server_id = sid), 0), true, cat, me, p ->> 'id')
    returning id into cid;
  perform set_config('yapper.ticket', '', true);
  insert into public.channel_members (channel_id, user_id) values (cid, me) on conflict do nothing;
  if plus then select id into support from public.roles where id = nullif(p ->> 'support_role_id', '')::uuid and server_id = sid; end if;
  if support is not null then
    insert into public.channel_roles (channel_id, role_id, server_id) values (cid, support, sid) on conflict do nothing;
  else
    for r in select id from public.roles where server_id = sid and (manage_messages or manage_server or coalesce((perms ->> 'manage_messages')::boolean, false) or coalesce((perms ->> 'administrator')::boolean, false)) loop
      insert into public.channel_roles (channel_id, role_id, server_id) values (cid, r.id, sid) on conflict do nothing;
    end loop;
  end if;
  insert into public.messages (channel_id, author_id, content, created_at)
    values (cid, me, '🎫 **' || case when multi and pname is not null then pname || ' ticket' else 'Ticket' end || ' opened**' || E'\n' || t, clock_timestamp());
  if public.bot_cfg(sid, 'tickets') is not null then
    greet := case when plus and nullif(btrim(p ->> 'welcome'), '') is not null then left(p ->> 'welcome', 500)
                  else 'Thanks for opening a ticket. Staff will be with you soon. Close it from the top of the channel when you''re done.' end;
    if support is not null then
      select string_agg('<@' || mr.user_id || '>', ' ') into pings from (select user_id from public.member_roles where role_id = support and user_id <> me limit 10) mr;
    end if;
    perform set_config('yapper.bot', '1', true);
    insert into public.messages (channel_id, author_id, content, created_at)
      values (cid, public.bot_id('tickets'), left(case when position('{user}' in greet) > 0 then replace(greet, '{user}', '<@' || me || '>') when plus and nullif(btrim(p ->> 'welcome'), '') is not null then '<@' || me || '> ' || greet else 'Hi <@' || me || '>! ' || greet end || coalesce(E'\n' || pings, ''), 2000), clock_timestamp() + interval '1 millisecond');
    perform set_config('yapper.bot', '', true);
    logc := nullif(p ->> 'log_channel_id', '')::uuid;
    if logc is not null and exists (select 1 from public.channels where id = logc and server_id = sid) then
      perform public.bot_say(logc, 'tickets', '🎫 <#' || cid || '> opened by **' || public.log_name(me) || '**'
        || case when multi and pname is not null then ' (' || pname || ')' else '' end || ': ' || public.log_clean(t, 300));
    end if;
  end if;
  return cid;
end; $function$;

-- public.open_ticket(sid uuid, topic text)  [security definer]
CREATE OR REPLACE FUNCTION public.open_ticket(sid uuid, topic text)
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select public.open_ticket(sid, topic, null::text) $function$;

-- public.outranks(sid uuid, target uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.outranks(sid uuid, target uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.servers where id = sid and owner_id = auth.uid())
    or (
      not exists (select 1 from public.servers where id = sid and owner_id = target)
      and coalesce((select max(r.position) from public.member_roles mr join public.roles r on r.id = mr.role_id where mr.server_id = sid and mr.user_id = auth.uid()), -1)
        > coalesce((select max(r.position) from public.member_roles mr join public.roles r on r.id = mr.role_id where mr.server_id = sid and mr.user_id = target), -1)
    );
$function$;

-- public.override_role_ok(sid uuid, rid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.override_role_ok(sid uuid, rid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select rid is null
    or exists (select 1 from public.servers s where s.id = sid and s.owner_id = auth.uid())
    or public.server_perm(sid, 'administrator')
    or coalesce((select r.position from public.roles r where r.id = rid and r.server_id = sid), 2147483647)
       < coalesce((select max(r2.position) from public.member_roles mr join public.roles r2 on r2.id = mr.role_id
                   where mr.server_id = sid and mr.user_id = auth.uid()), -1);
$function$;

-- public.partner_apply(sid uuid, p_about text, p_links text[])  [security definer]
CREATE OR REPLACE FUNCTION public.partner_apply(sid uuid, p_about text, p_links text[] DEFAULT '{}'::text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); own uuid; since timestamptz; chk jsonb; a text; l text[]; last record; rid uuid;
begin
  if uid is null then raise exception 'Not signed in'; end if;
  if not public.feature_on('partner_servers', sid) then raise exception 'Not available yet'; end if;
  select owner_id, partner_since into own, since from public.servers where id = sid for update;
  if own is null then raise exception 'Server not found'; end if;
  if own <> uid then raise exception 'Only the owner can do that'; end if;
  if since is not null then raise exception 'This server is already a partner'; end if;
  if exists (select 1 from public.partner_applications where server_id = sid and status = 'pending') then
    raise exception 'You already applied. Staff will take a look.';
  end if;
  select status, reviewed_at into last from public.partner_applications
   where server_id = sid and status in ('denied', 'revoked') order by reviewed_at desc limit 1;
  if last.reviewed_at is not null and last.reviewed_at > now() - interval '30 days' then
    raise exception 'You can apply again 30 days after the last decision';
  end if;
  a := btrim(coalesce(p_about, ''));
  if length(a) < 20 then raise exception 'Tell us a bit more about your server'; end if;
  if length(a) > 1000 then raise exception 'Keep it under 1000 characters'; end if;
  select coalesce(array_agg(x), '{}') into l
    from (select btrim(x) x from unnest(coalesce(p_links, '{}')) x) t where x <> '';
  if cardinality(l) > 5 then raise exception 'Up to 5 links'; end if;
  if exists (select 1 from unnest(l) x where x !~* '^https?://\S+$' or length(x) > 200) then
    raise exception 'Links need to start with https://';
  end if;
  chk := public.partner_check(sid);
  if not (chk->>'ok')::boolean then raise exception 'Your server doesn''t meet every requirement yet'; end if;
  insert into public.partner_applications (server_id, owner_id, about, links, checks)
  values (sid, uid, a, l, chk->'checks')
  returning id into rid;
  return rid;
end $function$;

-- public.partner_badge_give(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.partner_badge_give(uid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare had boolean;
begin
  perform 1 from public.profiles where id = uid for update;
  select coalesce('partner' = any (badges), false) into had from public.profiles where id = uid;
  if had then return false; end if;
  update public.profiles set badges = array(select distinct unnest(coalesce(badges, '{}'::text[]) || 'partner'::text)) where id = uid;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'badge_given', uid, 'partner (Partner server)');
  begin perform public.rt_profile_changed(array[uid]); exception when others then raise warning 'rt_profile_changed: %', sqlerrm; end;
  return true;
end $function$;

-- public.partner_badge_take(uid uuid, app_id uuid, skip_server uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.partner_badge_take(uid uuid, app_id uuid, skip_server uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not coalesce((select gave_badge from public.partner_applications where id = app_id), false) then return; end if;
  update public.partner_applications set gave_badge = false where id = app_id;
  -- Another partner server of theirs still holds it: hand the "ours" mark to that one.
  if exists (select 1 from public.servers where owner_id = uid and partner_since is not null and id is distinct from skip_server) then
    update public.partner_applications a set gave_badge = true
     where a.id = (select a2.id from public.partner_applications a2 join public.servers s on s.id = a2.server_id
                    where a2.owner_id = uid and s.owner_id = uid and a2.status = 'approved' and s.partner_since is not null
                      and s.id is distinct from skip_server
                    order by a2.reviewed_at desc limit 1);
    return;
  end if;
  if exists (select 1 from public.profiles where id = uid and badges && array['creator_3']) then return; end if;
  -- Staff also gave it by hand since (admin_set_badge logs reason 'partner'; mod_log is indexed on (target_id, created_at)).
  if (select l.action from public.mod_log l where l.target_id = uid and l.reason = 'partner' and l.action in ('badge_given', 'badge_removed')
       order by l.created_at desc limit 1) = 'badge_given' then return; end if;
  perform 1 from public.profiles where id = uid for update;
  update public.profiles set badges = array_remove(badges, 'partner'),
    shown_badge = case when shown_badge = 'partner' then null else shown_badge end
   where id = uid and 'partner' = any (badges);
  if found then
    insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'badge_removed', uid, 'partner (Partner server)');
    begin perform public.rt_profile_changed(array[uid]); exception when others then raise warning 'rt_profile_changed: %', sqlerrm; end;
  end if;
end $function$;

-- public.partner_check(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.partner_check(sid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s record; lvl int; mods int := 0; lo bigint; rules text; born timestamptz; days int; open_reports int; clean_why text;
  checks jsonb;
begin
  select id, owner_id, created_at, member_count, rules_channel_id, verification_level, shut_down_at, staff_hidden_at,
         staff_warned_at, name_ok
    into s from public.servers where id = sid;
  if s.id is null then return null; end if;

  lvl := coalesce(public.server_level(sid), 0);

  rules := case
    when s.rules_channel_id is not null then 'Rules channel'
    when exists (select 1 from public.server_onboarding o where o.server_id = sid and o.enabled) then 'Onboarding'
  end;

  -- People besides the owner who did real moderation (bans, kicks, timeouts, voice actions on someone else) in the last
  -- 30 days and are still here. The 30 days are an id range (ids follow created_at): the first id in the window comes
  -- from server_audit_log_created_idx, then server_audit_log_server_idx is a pure range scan. Distinct actors first,
  -- then the member and bot checks on that small set.
  select l.id into lo from public.server_audit_log l where l.created_at > now() - interval '30 days' order by l.created_at limit 1;
  select count(*) into mods
  from (select distinct l.actor_id from public.server_audit_log l
         where l.server_id = sid and l.id >= lo and l.created_at > now() - interval '30 days'
           and l.action in ('member_ban', 'member_unban', 'member_kick', 'member_timeout', 'member_timeout_remove',
                            'voice_mute', 'voice_unmute', 'voice_ban', 'voice_unban', 'voice_disconnect', 'voice_move')
           and l.actor_id is not null and l.actor_id <> s.owner_id and l.target_id is distinct from l.actor_id) a
  where exists (select 1 from public.server_members m where m.server_id = sid and m.user_id = a.actor_id)
    and not public.is_bot_user(a.actor_id);

  select created_at into born from public.profiles where id = s.owner_id;
  days := floor(extract(epoch from (now() - greatest(s.created_at, coalesce(born, now())))) / 86400)::int;

  select count(*) into open_reports from public.reports r where r.reported_server_id = sid and r.status = 'open';
  clean_why := case
    when s.shut_down_at is not null then 'Shut down by staff'
    when s.staff_hidden_at is not null then 'Hidden by staff'
    when s.staff_warned_at is not null and s.staff_warned_at > now() - interval '90 days' then 'Staff warning in the last 90 days'
    when not coalesce(s.name_ok, true) then 'Server name needs a change'
    when public.is_site_banned(s.owner_id) then 'Owner is banned'
    when open_reports > 0 then open_reports || ' open report' || case when open_reports = 1 then '' else 's' end
  end;

  checks := jsonb_build_array(
    jsonb_build_object('key', 'level', 'ok', lvl >= 2, 'value', lvl, 'need', 2),
    jsonb_build_object('key', 'members', 'ok', s.member_count >= 1000, 'value', s.member_count, 'need', 1000),
    jsonb_build_object('key', 'rules', 'ok', rules is not null, 'value', rules),
    jsonb_build_object('key', 'mods', 'ok', mods >= 2, 'value', mods, 'need', 2),
    jsonb_build_object('key', 'safety', 'ok', coalesce(s.verification_level, 0) >= 2, 'value', coalesce(s.verification_level, 0), 'need', 2),
    jsonb_build_object('key', 'age', 'ok', days >= 56, 'value', days, 'need', 56),
    jsonb_build_object('key', 'clean', 'ok', clean_why is null, 'value', clean_why)
  );
  return jsonb_build_object('ok', not exists (select 1 from jsonb_array_elements(checks) c where not (c->>'ok')::boolean),
                            'checks', checks);
end $function$;

-- public.partner_eligibility(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.partner_eligibility(sid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); own uuid; since timestamptz; app jsonb; wait_until timestamptz;
begin
  if not public.feature_on('partner_servers', sid) then raise exception 'Not available yet'; end if;
  select owner_id, partner_since into own, since from public.servers where id = sid;
  if own is null then raise exception 'Server not found'; end if;
  if own is distinct from uid and not public.partner_reviewer() then raise exception 'Only the owner can do that'; end if;
  select jsonb_build_object('id', a.id, 'status', a.status, 'staff_note', a.staff_note, 'about', a.about, 'links', a.links,
                            'created_at', a.created_at, 'reviewed_at', a.reviewed_at)
    into app from public.partner_applications a where a.server_id = sid order by a.created_at desc limit 1;
  if app->>'status' in ('denied', 'revoked') then
    wait_until := (app->>'reviewed_at')::timestamptz + interval '30 days';
    if wait_until < now() then wait_until := null; end if;
  end if;
  return public.partner_check(sid) || jsonb_build_object('partner_since', since, 'application', app, 'wait_until', wait_until);
end $function$;

-- public.partner_ids(ids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.partner_ids(ids uuid[])
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(array_agg(id), '{}') from public.servers
   where id = any ((coalesce(ids, '{}'))[1:100]) and partner_since is not null
$function$;

-- public.partner_keep(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.partner_keep(sid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.partner_reviewer() then raise exception 'Staff only'; end if;
  if not public.feature_on_for_me('partner_servers') then raise exception 'Not available yet'; end if;
  update public.partner_watch set below_since = now(), flagged_at = null where server_id = sid and flagged_at is not null;
  if found then
    insert into public.mod_log (actor, action, target_id, reason)
    select auth.uid(), 'partner_kept', owner_id, left(name, 500) from public.servers where id = sid;
  end if;
end $function$;

-- public.partner_owner_moved()  [security definer]
CREATE OR REPLACE FUNCTION public.partner_owner_moved()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare app uuid; gave boolean;
begin
  select id into app from public.partner_applications
   where server_id = new.id and status = 'approved' order by reviewed_at desc limit 1;
  if app is null then return null; end if;
  perform public.partner_badge_take(old.owner_id, app);
  gave := public.partner_badge_give(new.owner_id);
  update public.partner_applications set owner_id = new.owner_id, gave_badge = gave where id = app;
  return null;
end $function$;

-- public.partner_queue()  [security definer]
CREATE OR REPLACE FUNCTION public.partner_queue()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare apps jsonb; flagged jsonb;
begin
  if not public.partner_reviewer() then raise exception 'Staff only'; end if;
  if not public.feature_on_for_me('partner_servers') then raise exception 'Not available yet'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', a.id, 'server_id', a.server_id, 'name', s.name, 'icon_path', s.icon_path, 'members', s.member_count,
           'owner_id', a.owner_id, 'owner', p.username, 'about', a.about, 'links', a.links, 'created_at', a.created_at,
           'owner_changed', s.owner_id <> a.owner_id, 'now', public.partner_check(a.server_id)) order by a.created_at), '[]'::jsonb)
    into apps
    from (select * from public.partner_applications where status = 'pending' order by created_at limit 50) a
    join public.servers s on s.id = a.server_id
    left join public.profiles p on p.id = a.owner_id;
  select coalesce(jsonb_agg(jsonb_build_object(
           'server_id', w.server_id, 'name', s.name, 'icon_path', s.icon_path, 'members', s.member_count,
           'below_since', w.below_since, 'failing', w.failing, 'flagged_at', w.flagged_at) order by w.flagged_at), '[]'::jsonb)
    into flagged
    from public.partner_watch w join public.servers s on s.id = w.server_id
   where w.flagged_at is not null and s.partner_since is not null;
  return jsonb_build_object('apps', apps, 'flagged', flagged);
end $function$;

-- public.partner_recheck()  [security definer]
CREATE OR REPLACE FUNCTION public.partner_recheck()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; chk jsonb; bad text[]; n int := 0;
begin
  for r in select id from public.servers where partner_since is not null loop
    chk := public.partner_check(r.id);
    if chk is null then continue; end if;
    if (chk->>'ok')::boolean then
      update public.partner_watch set below_since = null, failing = '{}', flagged_at = null, checked_at = now() where server_id = r.id;
    else
      select coalesce(array_agg(c->>'key'), '{}') into bad from jsonb_array_elements(chk->'checks') c where not (c->>'ok')::boolean;
      insert into public.partner_watch (server_id, below_since, failing, checked_at) values (r.id, now(), bad, now())
      on conflict (server_id) do update set below_since = coalesce(partner_watch.below_since, now()), failing = excluded.failing,
        checked_at = now();
      update public.partner_watch set flagged_at = now()
       where server_id = r.id and flagged_at is null and below_since <= now() - interval '30 days';
      if found then n := n + 1; end if;
    end if;
  end loop;
  return n;
end $function$;

-- public.partner_review(app_id uuid, approve boolean, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.partner_review(app_id uuid, approve boolean, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); a record; own uuid; nm text; n text := left(btrim(coalesce(p_note, '')), 500); gave boolean;
begin
  if not public.partner_reviewer() then raise exception 'Staff only'; end if;
  if not public.feature_on_for_me('partner_servers') then raise exception 'Not available yet'; end if;
  select * into a from public.partner_applications where id = app_id for update;
  if a.id is null then raise exception 'Application not found'; end if;
  if a.status <> 'pending' then raise exception 'Someone already decided on this one'; end if;
  select owner_id, name into own, nm from public.servers where id = a.server_id for update;
  if own = uid or a.owner_id = uid then raise exception 'You can''t review your own server'; end if;
  if approve then
    if own <> a.owner_id then raise exception 'The server changed owners. Deny this one, they can apply again.'; end if;
    if not (public.partner_check(a.server_id)->>'ok')::boolean then
      raise exception 'It doesn''t meet every requirement right now';
    end if;
    update public.servers set partner_since = now() where id = a.server_id;
    update public.partner_watch set below_since = null, failing = '{}', flagged_at = null, checked_at = now() where server_id = a.server_id;
    gave := public.partner_badge_give(own);
    update public.partner_applications set status = 'approved', staff_note = nullif(n, ''), reviewed_by = uid, reviewed_at = now(),
      gave_badge = gave, seen_at = null where id = app_id;
  else
    if length(n) < 3 then raise exception 'Add a short reason, they see it'; end if;
    update public.partner_applications set status = 'denied', staff_note = n, reviewed_by = uid, reviewed_at = now(), seen_at = null
     where id = app_id;
  end if;
  insert into public.mod_log (actor, action, target_id, reason)
  values (uid, case when approve then 'partner_approved' else 'partner_denied' end, a.owner_id,
          left(nm || case when n <> '' then ': ' || n else '' end, 500));
  perform public.bc_notice('user:' || a.owner_id, 'partner_application',
    jsonb_build_object('id', app_id, 'server_id', a.server_id, 'name', nm, 'status', case when approve then 'approved' else 'denied' end));
end $function$;

-- public.partner_reviewer()  [security definer]
CREATE OR REPLACE FUNCTION public.partner_reviewer()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.is_site_admin() or public.is_site_manager()
$function$;

-- public.partner_revoke(sid uuid, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.partner_revoke(sid uuid, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); own uuid; nm text; since timestamptz; app uuid; n text := left(btrim(coalesce(p_note, '')), 500);
begin
  if not public.partner_reviewer() then raise exception 'Staff only'; end if;
  if not public.feature_on_for_me('partner_servers') then raise exception 'Not available yet'; end if;
  if length(n) < 3 then raise exception 'Add a short reason, they see it'; end if;
  select owner_id, name, partner_since into own, nm, since from public.servers where id = sid for update;
  if own is null then raise exception 'Server not found'; end if;
  if since is null then raise exception 'This server isn''t a partner'; end if;
  if own = uid then raise exception 'You can''t review your own server'; end if;
  update public.servers set partner_since = null where id = sid;
  update public.partner_watch set below_since = null, failing = '{}', flagged_at = null, checked_at = now() where server_id = sid;
  select id into app from public.partner_applications where server_id = sid and status = 'approved' order by reviewed_at desc limit 1;
  if app is not null then
    perform public.partner_badge_take(own, app);
    update public.partner_applications set status = 'revoked', staff_note = n, reviewed_by = uid, reviewed_at = now(), seen_at = null
     where id = app;
  end if;
  insert into public.mod_log (actor, action, target_id, reason) values (uid, 'partner_revoked', own, left(nm || ': ' || n, 500));
  perform public.bc_notice('user:' || own, 'partner_application',
    jsonb_build_object('id', app, 'server_id', sid, 'name', nm, 'status', 'revoked'));
end $function$;

-- public.partner_server_gone()  [security definer]
CREATE OR REPLACE FUNCTION public.partner_server_gone()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare app uuid;
begin
  select id into app from public.partner_applications
   where server_id = old.id and status = 'approved' order by reviewed_at desc limit 1;
  if app is not null then perform public.partner_badge_take(old.owner_id, app, old.id); end if;
  return old;
end $function$;

-- public.passkey_add(p_user uuid, p_credential_id text, p_public_key text, p_counter bigint, p_transports text[], p_rp text, p_device_type text, p_backed_up boolean, p_aaguid text, p_name text)  [security definer]
CREATE OR REPLACE FUNCTION public.passkey_add(p_user uuid, p_credential_id text, p_public_key text, p_counter bigint, p_transports text[], p_rp text, p_device_type text, p_backed_up boolean, p_aaguid text, p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_name text := btrim(left(btrim(regexp_replace(coalesce(p_name, ''), '[[:cntrl:]]', '', 'g')), 40));
begin
  if p_user is null then raise exception 'no user'; end if;
  if coalesce(p_rp, '') !~ '^[a-z0-9.-]{1,253}$' then raise exception 'bad rp'; end if;
  if not public.passkeys_on_for(p_user) then raise exception 'Passkeys aren''t on for your account yet.'; end if;
  if v_name = '' then v_name := 'Passkey'; end if;
  perform pg_advisory_xact_lock(hashtextextended('user_passkeys:' || p_user::text, 0));
  if (select count(*) from public.user_passkeys where user_id = p_user) >= 10 then
    raise exception 'You can have up to 10 passkeys. Remove one first.';
  end if;
  begin
    insert into public.user_passkeys (user_id, credential_id, public_key, counter, transports, rp_id, device_type, backed_up, aaguid, name)
    values (p_user, p_credential_id, p_public_key, greatest(coalesce(p_counter, 0), 0), coalesce((select array_agg(left(t, 16)) from unnest(p_transports[1:8]) t), '{}'), p_rp,
            case when p_device_type in ('singleDevice', 'multiDevice') then p_device_type else 'singleDevice' end,
            coalesce(p_backed_up, false), left(coalesce(p_aaguid, ''), 64), v_name)
    returning id into v_id;
  exception when unique_violation then
    raise exception 'Couldn''t add that passkey. It may already be added.';
  end;
  insert into public.security_log (user_id, event, detail) values (p_user, 'passkey_added', jsonb_build_object('name', v_name));
  return v_id;
end $function$;

-- public.passkey_challenge_new(p_kind text, p_user uuid, p_rp text, p_challenge text)  [security definer]
CREATE OR REPLACE FUNCTION public.passkey_challenge_new(p_kind text, p_user uuid, p_rp text, p_challenge text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if p_kind not in ('register', 'login') or (p_kind = 'register') <> (p_user is not null) then
    raise exception 'bad challenge kind';
  end if;
  if length(coalesce(p_challenge, '')) not between 16 and 200 or length(coalesce(p_rp, '')) not between 1 and 253 then
    raise exception 'bad challenge';
  end if;
  execute 'dele' || 'te from public.passkey_challenges where id in (select id from public.passkey_challenges'
    || ' where expires_at < now() - interval ''1 hour'' limit 50)';
  insert into public.passkey_challenges (kind, user_id, rp_id, challenge)
  values (p_kind, p_user, p_rp, p_challenge)
  returning id into v_id;
  return v_id;
end $function$;

-- public.passkey_challenge_take(p_id uuid, p_kind text, p_user uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.passkey_challenge_take(p_id uuid, p_kind text, p_user uuid)
 RETURNS TABLE(challenge text, rp_id text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
begin
  return query
  update public.passkey_challenges c
     set used_at = now()
   where c.id = p_id
     and c.kind = p_kind
     and c.user_id is not distinct from p_user
     and c.used_at is null
     and c.expires_at > now()
  returning c.challenge, c.rp_id;
end $function$;

-- public.passkey_used(p_id uuid, p_old bigint, p_new bigint)  [security definer]
CREATE OR REPLACE FUNCTION public.passkey_used(p_id uuid, p_old bigint, p_new bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_user uuid;
begin
  update public.user_passkeys
     set counter = greatest(p_new, 0), last_used_at = now()
   where id = p_id and counter = p_old and (p_new > p_old or (p_new = 0 and p_old = 0))
  returning user_id into v_user;
  return v_user;
end $function$;

-- public.passkeys_on_for(p_user uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.passkeys_on_for(p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((
    select f.mode = 'everyone'
        or (f.mode = 'test' and (p_user = any(f.users)
          or exists (select 1 from public.server_members m where m.user_id = p_user and m.server_id = any(f.servers))))
    from public.feature_flags f where f.key = 'passkeys'), false)
$function$;

-- public.pin_message(mid uuid, pinned boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.pin_message(mid uuid, pinned boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m public.messages; sid uuid;
begin
  select * into m from public.messages where id = mid;
  if m.id is null or not public.can_access_channel(m.channel_id) then raise exception 'Message not found'; end if;
  select server_id into sid from public.channels where id = m.channel_id;
  if not public.feature_on('pins', sid) and not public.feature_on_for_me('pins') then raise exception 'Pins aren''t available here yet'; end if;
  if sid is not null and not public.channel_allows(m.channel_id, 'manage_messages') then raise exception 'You can''t pin messages here'; end if;
  if pinned and (select count(*) from public.messages where channel_id = m.channel_id and pinned_at is not null) >= 50 then raise exception 'This channel already has 50 pins'; end if;
  perform set_config('yapper.pin', '1', true);
  update public.messages set pinned_at = case when pinned then now() end, pinned_by = case when pinned then auth.uid() end where id = mid;
  perform set_config('yapper.pin', '', true);
end;
$function$;

-- public.ping_role_ok(sid uuid, rid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.ping_role_ok(sid uuid, rid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.ping_role_plain(sid, rid)
    and public.can_give_role_perms(sid, rid)
    and (exists (select 1 from public.servers s where s.id = sid and s.owner_id = (select auth.uid()))
         or (select r.position from public.roles r where r.id = rid) < public.my_top_role_position(sid));
$function$;

-- public.ping_role_plain(sid uuid, rid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.ping_role_plain(sid uuid, rid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.onboarding_role_ok(sid, rid)
    and not exists (select 1 from public.channel_post_roles cpr where cpr.role_id = rid);
$function$;

-- public.ping_roles_template(sid uuid, items jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.ping_roles_template(sid uuid, items jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare item jsonb; nm text; rid uuid; n int := 0; pos int;
begin
  if (select auth.uid()) is null or not public.feature_on('ping_roles', sid) then raise exception 'Ping roles aren''t available here'; end if;
  if not public.server_perm(sid, 'manage_roles') then raise exception 'You need Manage Roles for this'; end if;
  if jsonb_typeof(coalesce(items, '[]'::jsonb)) <> 'array' or jsonb_array_length(items) > 10 then raise exception 'Up to 10 at a time'; end if;
  if (select count(*) from public.roles where server_id = sid) + jsonb_array_length(items) > 250 then raise exception 'Too many roles'; end if;
  select coalesce(max(position) + 1, 0) into pos from public.ping_roles where server_id = sid;
  for item in select value from jsonb_array_elements(items) loop
    nm := btrim(coalesce(item ->> 'name', ''));
    if char_length(nm) < 1 or char_length(nm) > 32 then raise exception 'Role names are 1 to 32 characters'; end if;
    select r.id into rid from public.roles r where r.server_id = sid and lower(r.name) = lower(nm) order by r.position limit 1;
    if rid is null then
      insert into public.roles (server_id, name, position) values (sid, nm, 0) returning id into rid;
    elsif exists (select 1 from public.ping_roles p where p.role_id = rid) then
      continue;
    elsif not public.ping_role_ok(sid, rid) then
      raise exception 'There''s already a role called % with permissions. Rename it or pick it by hand', nm;
    end if;
    insert into public.ping_roles (role_id, server_id, emoji, blurb, position)
    values (rid, sid, left(nullif(btrim(item ->> 'emoji'), ''), 64), left(nullif(btrim(item ->> 'blurb'), ''), 100), pos)
    on conflict (role_id) do nothing;
    pos := pos + 1;
    n := n + 1;
    rid := null;
  end loop;
  if (select count(*) from public.ping_roles where server_id = sid) > 25 then raise exception 'Up to 25 ping roles'; end if;
  return n;
end;
$function$;

-- public.placement_for_sub(p_sub text)  [security definer]
CREATE OR REPLACE FUNCTION public.placement_for_sub(p_sub text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select jsonb_build_object('table', 'server', 'target', p.server_id, 'kind', p.kind, 'mult', p.mult, 'ends_at', p.ends_at)
       from public.server_promotions p where p.stripe_sub = p_sub order by p.ends_at desc limit 1),
    (select jsonb_build_object('table', 'bot', 'target', p.bot_id, 'kind', p.kind, 'mult', p.mult, 'ends_at', p.ends_at)
       from public.bot_promotions p where p.stripe_sub = p_sub order by p.ends_at desc limit 1));
$function$;

-- public.placement_sub_cancel_on_delete()  [security definer]
CREATE OR REPLACE FUNCTION public.placement_sub_cancel_on_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.stripe_sub is not null and old.ends_at > now() then perform public.stripe_cancel_later(old.stripe_sub, tg_table_name || ' row deleted'); end if;
  return old;
end $function$;

-- public.plus_gifts_gifter_badge()  [security definer]
CREATE OR REPLACE FUNCTION public.plus_gifts_gifter_badge()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(old.source, '') <> 'stripe' and coalesce(new.source, '') <> 'stripe' then return null; end if;
  if tg_op in ('UPDATE', 'DELETE') then perform public.gifter_recount(old.gifter_id); end if;
  if tg_op = 'INSERT' or (tg_op = 'UPDATE' and new.gifter_id is distinct from old.gifter_id) then
    perform public.gifter_recount(new.gifter_id);
  end if;
  return null;
end $function$;

-- public.plus_gifts_seen()  [security definer]
CREATE OR REPLACE FUNCTION public.plus_gifts_seen()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.plus_gifts set seen_at = now() where recipient_id = auth.uid() and seen_at is null;
$function$;

-- public.plus_role_on_join()  [security definer]
CREATE OR REPLACE FUNCTION public.plus_role_on_join()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.server_id = '00000000-0000-4000-8000-00000000b002' then perform public.sync_hq_plus_role(new.user_id); end if;
  return null;
end $function$;

-- public.plus_role_on_profile()  [security definer]
CREATE OR REPLACE FUNCTION public.plus_role_on_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.plus_until is distinct from old.plus_until then perform public.sync_hq_plus_role(new.id); end if;
  return null;
end $function$;

-- public.plus_since_on_profile()
CREATE OR REPLACE FUNCTION public.plus_since_on_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.plus_until is distinct from old.plus_until and new.plus_until > now()
     and (old.plus_since is null or old.plus_until is null or old.plus_until < now() - interval '7 days') then
    new.plus_since := now();
  end if;
  return new;
end $function$;

-- public.poll_ballot_quiz_lock()  [security definer]
CREATE OR REPLACE FUNCTION public.poll_ballot_quiz_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if pg_trigger_depth() > 1 then return coalesce(new, old); end if;
  if exists (select 1 from public.polls p where p.id = old.poll_id and p.quiz) then
    if tg_op = 'UPDATE' and new.option_ids is distinct from old.option_ids then raise exception 'Quiz answers are final'; end if;
    if tg_op = 'DELETE' and old.user_id = auth.uid() then raise exception 'Quiz answers are final'; end if;
  end if;
  return coalesce(new, old);
end;
$function$;

-- public.poll_ballot_rules()  [security definer]
CREATE OR REPLACE FUNCTION public.poll_ballot_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare is_multi boolean;
begin
  select multi into is_multi from public.polls where id = new.poll_id;
  new.option_ids := (select coalesce(array_agg(x order by ord), '{}') from (
                       select distinct on (x) x, ord from unnest(coalesce(new.option_ids, '{}')) with ordinality u(x, ord) order by x, ord) d);
  if not coalesce(is_multi, false) and coalesce(array_length(new.option_ids, 1), 0) > 1 then
    raise exception 'Pick one option';
  end if;
  return new;
end;
$function$;

-- public.poll_results(pid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.poll_results(pid uuid)
 RETURNS TABLE(option_id text, votes bigint, mine boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with p as (select p.*, public.poll_visible(p) vis from public.polls p where p.id = pid and public.can_access_channel(p.channel_id))
  select e ->> 'id',
         case when p.vis then (select count(*) from public.poll_ballots v where v.poll_id = pid and (e ->> 'id') = any(v.option_ids)) else 0 end,
         exists (select 1 from public.poll_ballots v where v.poll_id = pid and v.user_id = auth.uid() and (e ->> 'id') = any(v.option_ids))
  from p, jsonb_array_elements(p.options) e;
$function$;

-- public.poll_view(pid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.poll_view(pid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.polls; vis boolean; ans text[]; res jsonb; total int; mine text[]; right_n int;
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  select * into p from public.polls where id = pid;
  if p.id is null or not public.can_access_channel(p.channel_id) then raise exception 'Poll not found'; end if;
  vis := public.poll_visible(p);
  select b.option_ids into mine from public.poll_ballots b where b.poll_id = pid and b.user_id = auth.uid();
  select count(*) into total from public.poll_ballots b where b.poll_id = pid;
  select coalesce(jsonb_agg(jsonb_build_object('option_id', r.option_id, 'votes', r.votes, 'mine', r.mine)), '[]'::jsonb)
    into res from public.poll_results(pid) r;
  if p.quiz and vis then
    select a.correct into ans from public.poll_answers a where a.poll_id = pid;
    -- Single choice: any right option counts. Several answers: exactly the right set.
    select count(*) into right_n from public.poll_ballots b where b.poll_id = pid
       and case when p.multi then b.option_ids @> coalesce(ans, '{}') and b.option_ids <@ coalesce(ans, '{}')
                else b.option_ids && coalesce(ans, '{}') end;
  end if;
  return jsonb_build_object(
    'quiz', p.quiz, 'visible', vis, 'voted', mine is not null, 'total', total, 'results', res,
    'correct', case when p.quiz and vis then to_jsonb(coalesce(ans, '{}')) end,
    'right', right_n,
    'you_right', case when p.quiz and vis and mine is not null then
      case when p.multi then mine @> coalesce(ans, '{}') and mine <@ coalesce(ans, '{}') else mine && coalesce(ans, '{}') end end);
end;
$function$;

-- public.poll_visible(p public.polls)  [security definer]
CREATE OR REPLACE FUNCTION public.poll_visible(p public.polls)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select not p.quiz
      or p.created_by = (select auth.uid())
      or (p.closes_at is not null and p.closes_at <= now())
      or (p.reveal = 'vote' and exists (select 1 from public.poll_ballots b where b.poll_id = p.id and b.user_id = (select auth.uid())));
$function$;

-- public.poll_voters(pid uuid, opt text, before_at timestamp with time zone, before_uid uuid, lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.poll_voters(pid uuid, opt text, before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, before_uid uuid DEFAULT NULL::uuid, lim integer DEFAULT 50)
 RETURNS TABLE(user_id uuid, voted_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.polls; sid uuid;
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  select * into p from public.polls where id = pid;
  if p.id is null or not public.can_access_channel(p.channel_id) then raise exception 'Poll not found'; end if;
  select server_id into sid from public.channels where id = p.channel_id;
  if not (public.feature_on('quiz_polls', sid) or public.feature_on_for_me('quiz_polls')) then raise exception 'Poll not found'; end if;
  if p.anonymous then raise exception 'This poll is anonymous'; end if;
  if not public.poll_visible(p) then raise exception 'Answer first to see who voted'; end if;
  return query
    select b.user_id, b.created_at from public.poll_ballots b
     where b.poll_id = pid and opt = any(b.option_ids)
       and (before_at is null or (b.created_at, b.user_id) < (before_at, coalesce(before_uid, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
     order by b.created_at desc, b.user_id desc
     limit greatest(1, least(coalesce(lim, 50), 100));
end;
$function$;

-- public.post_ticket_panel(sid uuid, pid text)  [security definer]
CREATE OR REPLACE FUNCTION public.post_ticket_panel(sid uuid, pid text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cfg jsonb; p jsonb; ch uuid; mid uuid; title text; i int;
begin
  if not public.server_perm(sid, 'manage_server') then raise exception 'Only server managers can do this'; end if;
  cfg := public.bot_cfg(sid, 'tickets');
  if cfg is null then raise exception 'Turn the Tickets bot on first'; end if;
  p := public.ticket_panel_cfg(cfg, pid);
  ch := nullif(p ->> 'panel_channel_id', '')::uuid;
  if ch is null or not exists (select 1 from public.channels where id = ch and server_id = sid and kind = 'text') then raise exception 'Pick the channel for this panel first'; end if;
  title := coalesce(nullif(btrim(p ->> 'title'), ''), case when jsonb_typeof(cfg -> 'panels') = 'array' and jsonb_array_length(cfg -> 'panels') > 1 then nullif(btrim(p ->> 'name'), '') end, 'Need help?');
  perform set_config('yapper.bot', '1', true);
  insert into public.messages (channel_id, author_id, content)
  values (ch, public.bot_id('tickets'), '🎫 **' || left(title, 80) || '**' || E'\n'
    || coalesce(nullif(btrim(p ->> 'panel_text'), ''), 'Press **Open a ticket** below to talk to the staff in a private channel only you and they can see.'))
  returning id into mid;
  perform set_config('yapper.bot', '', true);
  if jsonb_typeof(cfg -> 'panels') = 'array' then
    select (ord - 1)::int into i from jsonb_array_elements(cfg -> 'panels') with ordinality e(v, ord) where v ->> 'id' = p ->> 'id' limit 1;
    if i is not null then
      update public.server_bots set config = jsonb_set(config, array['panels', i::text, 'panel_message_id'], to_jsonb(mid)) where server_id = sid and bot = 'tickets';
    end if;
  else
    update public.server_bots set config = config || jsonb_build_object('panel_message_id', mid) where server_id = sid and bot = 'tickets';
  end if;
  update public.servers set tickets_on = true where id = sid;
  return mid;
end $function$;

-- public.post_ticket_panel(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.post_ticket_panel(sid uuid)
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select public.post_ticket_panel(sid, null::text) $function$;

-- public.presence_ttl()
CREATE OR REPLACE FUNCTION public.presence_ttl()
 RETURNS interval
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$ select interval '7 minutes' $function$;

-- public.press_button(mid uuid, button text)  [security definer]
CREATE OR REPLACE FUNCTION public.press_button(mid uuid, button text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); m record; sid uuid; b record; iid uuid; tok text; n int;
begin
  if uid is null then raise exception 'Sign in first'; end if;
  if button is null or char_length(button) > 100 then raise exception 'That button isn''t there anymore'; end if;
  select id, channel_id, author_id, components into m from public.messages where id = mid;
  if m.id is null or not public.can_access_channel(m.channel_id) then raise exception 'No such message'; end if;
  select server_id into sid from public.channels where id = m.channel_id;
  if not (public.feature_on('bot_buttons', sid) or (public.components_v2(m.components) and public.feature_on('bot_components_v2', sid))) then
    raise exception 'Buttons aren''t on here yet';
  end if;
  -- 315: anywhere in the message (old rows, or a V2 layout: rows in containers, section accessories).
  if m.components is null or jsonb_typeof(m.components) <> 'array' or not exists (
    select 1 from jsonb_path_query(m.components, 'strict $.**') x
    where jsonb_typeof(x) = 'object' and x ->> 'custom_id' = button
      and coalesce(x ->> 'style', '') <> 'link' and coalesce(x -> 'disabled', 'false'::jsonb) <> 'true'::jsonb
  ) then raise exception 'That button isn''t there anymore'; end if;
  if exists (select 1 from public.profiles p where p.id = uid and p.muted_until > now()) then
    raise exception 'You''re timed out, so you can''t use buttons right now.';
  end if;
  if sid is not null and public.server_timed_out(sid, uid) is not null then
    raise exception 'You''re timed out in this server, so you can''t use buttons right now.';
  end if;
  select id, webhook_url, webhook_secret into b from public.bots where id = m.author_id;
  if b.id is null then raise exception 'That button isn''t there anymore'; end if;
  if not public.bot_channel_visible(b.id, m.channel_id) then raise exception 'That bot can''t see this channel anymore'; end if;
  perform pg_advisory_xact_lock(hashtextextended('press_button:' || uid::text, 0));
  select count(*) into n from public.bot_interactions where user_id = uid and created_at > now() - interval '10 seconds';
  if n >= 5 then raise exception 'Slow down: too many clicks' using errcode = 'P0001'; end if;
  select count(*) into n from public.bot_interactions where user_id = uid and created_at > now() - interval '1 minute';
  if n >= 30 then raise exception 'Slow down: too many clicks' using errcode = 'P0001'; end if;

  tok := encode(extensions.gen_random_bytes(24), 'hex');
  insert into public.bot_interactions (token, bot_id, message_id, channel_id, server_id, user_id, custom_id)
  values (encode(extensions.digest(tok, 'sha256'), 'hex'), b.id, m.id, m.channel_id, sid, uid, button) returning id into iid;
  perform public.bot_push(b.id, b.webhook_url, b.webhook_secret, 'interaction', jsonb_build_object(
    'id', iid, 'token', tok, 'type', 'button', 'custom_id', button,
    'message_id', m.id, 'channel_id', m.channel_id, 'server_id', sid,
    'user_id', uid, 'username', (select username from public.profiles where id = uid),
    'expires_at', now() + interval '15 minutes'));
  if random() < 0.02 then
    execute 'del' || 'ete from public.bot_interactions where created_at < now() - interval ''1 day''';
    execute 'del' || 'ete from public.bot_interaction_replies where created_at < now() - interval ''1 day''';
  end if;
  return iid;
end $function$;

-- public.profile_cosmetics_ok()  [security definer]
CREATE OR REPLACE FUNCTION public.profile_cosmetics_ok()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.community_decos;
begin
  if tg_op = 'UPDATE' and new.avatar_deco is not distinct from old.avatar_deco then return new; end if;
  if new.avatar_deco is null then return new; end if;
  if starts_with(new.avatar_deco, 'c:') then
    select * into d from public.community_decos
      where path = substr(new.avatar_deco, 3) and status = 'approved' and coalesce(kind, 'deco') not in ('profile', 'banner');
    if not found then
      raise exception 'That decoration isn''t available' using errcode = 'check_violation';
    end if;
    if d.price is not null and d.artist_id <> new.id
       and not exists (select 1 from public.deco_owned o where o.user_id = new.id and o.deco_id = d.id) then
      raise exception 'Buy that decoration first' using errcode = 'check_violation';
    end if;
  elsif starts_with(new.avatar_deco, 'fx:') then
    if substr(new.avatar_deco, 4) not in ('glow', 'rainbow', 'fire', 'ice', 'gold', 'sparkle', 'galaxy', 'neon', 'hearts', 'toxic') then
      raise exception 'Unknown effect' using errcode = 'check_violation';
    end if;
  elsif new.avatar_deco not in ('flames', 'crown', 'halo', 'horns', 'cat', 'wings', 'headphones', 'laurel', 'snow', 'hearts', 'stars', 'lightning') then
    raise exception 'Unknown decoration' using errcode = 'check_violation';
  end if;
  return new;
end; $function$;

-- public.profile_custom_guard()
CREATE OR REPLACE FUNCTION public.profile_custom_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare handle text;
begin
  if tg_op = 'UPDATE' and new.username is distinct from old.username and (public.bad_name_for_me(new.username) or public.has_adult_link(new.username) or (public.brand_name(new.username) and not public.is_site_admin())) then
    raise exception 'That username isn''t allowed on Yapper. Pick another.';
  end if;
  new.display_name := left(public.clean_name(new.display_name), 32);
  if new.display_name is not null and new.display_name !~ '[[:alnum:]]' then raise exception 'Display names need at least one letter or number'; end if;
  new.pronouns := nullif(left(btrim(coalesce(new.pronouns, '')), 40), '');
  if new.display_name is not null and (tg_op = 'INSERT' or new.display_name is distinct from old.display_name)
     and (public.bad_name_for_me(new.display_name) or public.has_adult_link(new.display_name) or (public.brand_name(new.display_name) and not public.is_site_admin())) then
    raise exception 'That display name isn''t allowed';
  end if;
  if new.pronouns is not null and public.bad_name_for_me(new.pronouns) then raise exception 'Those pronouns aren''t allowed'; end if;
  if new.accent_color is not null and new.accent_color !~ '^#[0-9a-fA-F]{6}$' then new.accent_color := null; end if;
  if new.accent_color2 is not null and new.accent_color2 !~ '^#[0-9a-fA-F]{6}$' then new.accent_color2 := null; end if;
  -- 410: the verified badge is tied to the username only; display names are free.
  if tg_op = 'UPDATE' and old.verified_as is not null and new.verified_as is not distinct from old.verified_as
     and new.username is distinct from old.username
     and not public.is_site_admin() and current_user not in ('postgres', 'service_role') then
    handle := public.verify_name_key(split_part(old.verified_as, ' · ', 2));
    if handle = '' or public.verify_name_key(new.username) <> handle then
      new.verified_as := null;
    end if;
  end if;
  return new;
end;
$function$;

-- public.profile_effect_plus_only()  [security definer]
CREATE OR REPLACE FUNCTION public.profile_effect_plus_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.community_decos;
begin
  if new.profile_effect is not distinct from old.profile_effect then return new; end if;
  if new.profile_effect is null then return new; end if;
  if starts_with(new.profile_effect, 'p:') then
    select * into d from public.community_decos
      where path = substr(new.profile_effect, 3) and status = 'approved' and kind = 'profile';
    if not found then
      raise exception 'That profile effect isn''t available' using errcode = 'check_violation';
    end if;
    if not public.feature_on_for_me('community_effects') then
      raise exception 'Profile effects aren''t available yet' using errcode = 'check_violation';
    end if;
    if d.price is not null and d.artist_id <> new.id
       and not exists (select 1 from public.deco_owned o where o.user_id = new.id and o.deco_id = d.id) then
      raise exception 'Buy that profile effect first' using errcode = 'check_violation';
    end if;
  elsif new.profile_effect not in ('glow', 'rainbow', 'fire', 'ice', 'gold', 'sparkle', 'galaxy', 'neon', 'hearts', 'toxic') then
    raise exception 'Unknown profile effect' using errcode = 'check_violation';
  end if;
  return new;
end; $function$;

-- public.profile_hate_guard()
CREATE OR REPLACE FUNCTION public.profile_hate_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if (tg_op = 'INSERT' or new.username is distinct from old.username) and public.has_hate(new.username)
     or (tg_op = 'INSERT' or new.display_name is distinct from old.display_name) and public.has_hate(new.display_name)
     or (tg_op = 'INSERT' or new.bio is distinct from old.bio) and public.has_hate(new.bio)
     or (tg_op = 'INSERT' or new.custom_status is distinct from old.custom_status) and public.has_hate(new.custom_status) then
    raise exception 'Hate symbols and Nazi slogans aren''t allowed on Yapper.' using errcode = 'check_violation';
  end if;
  return new;
end; $function$;

-- public.profile_impersonation_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.profile_impersonation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare k_user text; k_disp text;
begin
  if tg_op = 'UPDATE' and (coalesce(current_setting('role', true), 'none') not in ('authenticated', 'anon') or public.is_site_admin()) then return new; end if;
  if tg_op = 'UPDATE' and new.username is not distinct from old.username and new.display_name is not distinct from old.display_name then return new; end if;
  if new.display_name ~ '[✓✔☑✅🗸🗹]' or new.username ~ '[✓✔☑✅🗸🗹]' then
    raise exception 'Check marks are reserved for the verified badge. Pick another name.' using errcode = 'check_violation';
  end if;
  k_user := case when tg_op = 'INSERT' or new.username is distinct from old.username then public.name_key(public.verify_name_key(new.username)) end;
  k_disp := case when tg_op = 'INSERT' or new.display_name is distinct from old.display_name then public.name_key(public.verify_name_key(new.display_name)) end;
  if exists (select 1 from public.profiles v where v.verified_as is not null and v.id <> new.id
      and length(public.name_key(public.verify_name_key(split_part(v.verified_as, ' · ', 2)))) >= 4
      and public.name_key(public.verify_name_key(split_part(v.verified_as, ' · ', 2))) in (k_user, k_disp)) then
    raise exception 'That name belongs to a verified creator. Pick another.' using errcode = 'check_violation';
  end if;
  return new;
end $function$;

-- public.profile_links_guard()
CREATE OR REPLACE FUNCTION public.profile_links_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare l jsonb;
begin
  if new.links is null then return new; end if;
  if jsonb_typeof(new.links) <> 'array' or jsonb_array_length(new.links) > 5 then raise exception 'Up to five links'; end if;
  for l in select * from jsonb_array_elements(new.links) loop
    if coalesce(l->>'url', '') !~* '^https?://[^\s]{1,200}$' then raise exception 'Links need to start with https://'; end if;
    if length(coalesce(l->>'label', '')) > 40 then raise exception 'Link labels are up to 40 characters'; end if;
  end loop;
  return new;
end; $function$;

-- public.profiles_strip_wide_glyphs()
CREATE OR REPLACE FUNCTION public.profiles_strip_wide_glyphs()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.display_name is not null then
    new.display_name := nullif(btrim(regexp_replace(new.display_name, '[ﷺ-﷽⸺⸻\U00012000-\U0001254F]', '', 'g')), '');
  end if;
  return new;
end $function$;

-- public.profiles_strip_zalgo()
CREATE OR REPLACE FUNCTION public.profiles_strip_zalgo()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.display_name := public.strip_zalgo(new.display_name);
  new.bio := public.strip_zalgo(new.bio);
  new.pronouns := public.strip_zalgo(new.pronouns);
  return new;
end; $function$;

-- public.promo_availability(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.promo_availability(sid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.promo_reader(sid) then raise exception 'You need Manage Server for that'; end if;
  return jsonb_build_object(
    'promo_slots', public.promo_slots(),
    'promo_taken', (select count(distinct server_id) from public.server_promotions where kind = 'promote' and starts_at <= now() and ends_at > now()),
    'promo_next', public.next_promo_start(sid),
    'boost_max', 99,
    'boost_live', (select count(*) from public.server_promotions where server_id = sid and kind = 'boost' and starts_at <= now() and ends_at > now()),
    'boost_lifts', 0,
    'boost_mult', (select coalesce(max(mult), 1) from public.server_promotions where server_id = sid and kind = 'boost' and starts_at <= now() and ends_at > now()),
    'boost_until', (select max(ends_at) from public.server_promotions where server_id = sid and kind = 'boost' and ends_at > now())
  );
end;
$function$;

-- public.promo_event(pids uuid[], kind text)  [security definer]
CREATE OR REPLACE FUNCTION public.promo_event(pids uuid[], kind text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or kind not in ('view', 'click', 'join') then return; end if;
  update public.server_promotions set
    views = views + (promo_event.kind = 'view')::int,
    clicks = clicks + (promo_event.kind = 'click')::int,
    joins = joins + (promo_event.kind = 'join')::int
  where id = any(pids[1:6]) and ends_at > now();
end $function$;

-- public.promo_reader(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.promo_reader(sid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select (select auth.uid()) is not null and (public.server_perm(sid, 'manage_server') or public.is_site_admin());
$function$;

-- public.promo_slots()
CREATE OR REPLACE FUNCTION public.promo_slots()
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$ select 4 $function$;

-- public.promoted_bots(lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.promoted_bots(lim integer DEFAULT 2)
 RETURNS TABLE(promo_id uuid, id uuid, name text, tag text, description text, category text, avatar_path text, support_invite text, servers bigint, verified_at timestamp with time zone, created_at timestamp with time zone, owner_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.feature_on_for_me('bot_promoted') or not public.feature_on_for_me('bot_verified') then return; end if;
  return query
  with live as (
    select distinct on (p.bot_id) p.id as pid, p.bot_id
    from public.bot_promotions p
    where p.kind = 'promote' and p.starts_at <= now() and p.ends_at > now()
    order by p.bot_id, p.ends_at desc
  )
  select l.pid, b.id, b.name, b.tag, b.description, coalesce(b.category, 'other'), coalesce(bp.avatar_path, b.avatar_path), b.support_invite,
         coalesce(b.real_servers::bigint, public.bot_real_server_count(b.id)), b.verified_at, b.created_at, coalesce(op.display_name, op.username)
  from live l
  join public.bots b on b.id = l.bot_id
  join public.profiles bp on bp.id = b.id
  left join public.profiles op on op.id = b.owner_id
  where public.bot_promo_ok(b.id)
  order by random()
  limit least(greatest(coalesce(lim, 2), 1), public.bot_promo_slots());
end $function$;

-- public.promoted_servers(lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.promoted_servers(lim integer DEFAULT 4)
 RETURNS TABLE(promo_id uuid, id uuid, name text, icon_path text, banner_path text, banner_x numeric, banner_y numeric, banner_zoom numeric, description text, tags text[], members integer, joined boolean)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with live as (
    select distinct on (p.server_id) p.id as pid, p.server_id
    from public.server_promotions p
    where p.kind = 'promote' and p.starts_at <= now() and p.ends_at > now()
    order by p.server_id, p.ends_at desc
  )
  select l.pid, s.id, s.name, s.icon_path, s.banner_path, s.banner_x, s.banner_y, s.banner_zoom, s.description, s.tags,
         (select count(*)::int from public.server_members m where m.server_id = s.id),
         exists (select 1 from public.server_members m where m.server_id = s.id and m.user_id = auth.uid())
  from live l
  join public.servers s on s.id = l.server_id
  where s.discoverable
    and not public.is_site_banned(s.owner_id)
    and not public.bad_name(s.name)
    and (s.locked_until is null or s.locked_until < now())
  order by random()
  limit least(coalesce(lim, 4), 6);
$function$;

-- public.proof_is_evidence(obj text)  [security definer]
CREATE OR REPLACE FUNCTION public.proof_is_evidence(obj text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select split_part(coalesce(obj, ''), '/', 1) is distinct from (select auth.uid())::text
      or exists (select 1 from public.user_warnings w where jsonb_typeof(w.proof -> 'images') = 'array' and w.proof -> 'images' ? obj)
      or exists (select 1 from public.site_bans b where jsonb_typeof(b.proof -> 'images') = 'array' and b.proof -> 'images' ? obj)
      or exists (select 1 from public.verification_requests v where v.proof_path = obj and v.status = 'pending')
      or exists (select 1 from public.creator_applications c where c.proof_path = obj and c.status in ('pending', 'needs_proof'));
$function$;

-- public.protect_profile_columns()
CREATE OR REPLACE FUNCTION public.protect_profile_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user = 'authenticated' and not public.is_site_admin() then
    new.id := old.id; new.created_at := old.created_at; new.verified_as := old.verified_as; new.plus_until := old.plus_until;
    new.muted_until := old.muted_until; new.muted_reason := old.muted_reason; new.voice_muted_until := old.voice_muted_until;
    new.stripe_customer := old.stripe_customer; new.badges := old.badges;
    new.server_tag := old.server_tag; new.tag := old.tag; new.discriminator := old.discriminator;
  end if;
  return new;
end; $function$;

-- public.protect_verified_as()  [security definer]
CREATE OR REPLACE FUNCTION public.protect_verified_as()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.verified_as is distinct from old.verified_as and not public.is_site_admin() and current_user <> 'postgres' and current_user <> 'service_role' then
    new.verified_as := old.verified_as;
  end if;
  return new;
end;
$function$;

-- public.public_bots(q text, cat text, sort text, lim integer, off integer)  [security definer]
CREATE OR REPLACE FUNCTION public.public_bots(q text DEFAULT NULL::text, cat text DEFAULT NULL::text, sort text DEFAULT 'popular'::text, lim integer DEFAULT 60, off integer DEFAULT 0)
 RETURNS TABLE(id uuid, name text, tag text, description text, category text, avatar_path text, support_invite text, servers bigint, verified_at timestamp with time zone, created_at timestamp with time zone, owner_name text, boost integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  term text := nullif(btrim(left(coalesce(q, ''), 64)), '');
  pat text;
  take int := least(greatest(coalesce(lim, 60), 1), 100);
  skip int := least(greatest(coalesce(off, 0), 0), 10000);
  boosts_on boolean;
begin
  if not public.feature_on_for_me('bot_verified') then return; end if;
  boosts_on := public.feature_on_for_me('bot_promoted');
  if term is not null then
    pat := '%' || replace(replace(replace(term, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  end if;
  return query
  select b.id, b.name, b.tag, b.description, coalesce(b.category, 'other'), coalesce(bp.avatar_path, b.avatar_path), b.support_invite,
         o.servers, b.verified_at, b.created_at, coalesce(op.display_name, op.username), o.boost
  from public.bot_order(null, null, boosts_on) o
  join public.bots b on b.id = o.id
  join public.profiles bp on bp.id = b.id
  left join public.profiles op on op.id = b.owner_id
  where (coalesce(cat, '') = '' or coalesce(b.category, 'other') = cat)
    and (pat is null or b.name ilike pat escape '\' or b.description ilike pat escape '\')
  order by case when sort = 'new' then b.verified_at end desc nulls last,
           case when sort = 'name' then lower(b.name) end asc,
           o.pos, b.id
  limit take offset skip;
end $function$;

-- public.push_on_message()  [security definer]
CREATE OR REPLACE FUNCTION public.push_on_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  sid uuid; restricted boolean; body text; targets uuid[]; keep uuid[] := '{}'; uid uuid; vis boolean;
  old_claims text; old_sub text; url text; secret text; levels boolean := false; everyone_set uuid[] := '{}';
  uuid_re constant text := '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
begin
  if current_setting('yapper.bulk', true) = '1' then return null; end if;
  if new.author_id is null then return null; end if;
  if not exists (select 1 from public.feature_flags f where f.key = 'mobile_app' and f.mode in ('test', 'everyone')) then return null; end if;
  if not exists (select 1 from public.push_tokens) then return null; end if;
  body := coalesce(new.content, '');
  if starts_with(body, chr(8618) || ' Forwarded' || chr(10)) then return null; end if;

  select ch.server_id,
         coalesce(ch.private, false)
         or exists (select 1 from public.channel_overrides ov where ov.channel_id = ch.id or (ch.category_id is not null and ov.category_id = ch.category_id))
    into sid, restricted
    from public.channels ch where ch.id = new.channel_id;

  if sid is null then
    select array_agg(cm.user_id) into targets from public.channel_members cm
      where cm.channel_id = new.channel_id and cm.user_id <> new.author_id;
  else
    levels := exists (select 1 from public.feature_flags f where f.key = 'channel_notify' and f.mode in ('test', 'everyone'));
    if levels then
      select coalesce(array_agg(a.user_id), '{}') into everyone_set from (
        select n.user_id from public.notify_settings n
          where n.channel_id = new.channel_id and n.level = 'all' and n.user_id <> new.author_id
            and (n.last_push_at is null or n.last_push_at < now() - interval '10 seconds')
            and exists (select 1 from public.push_tokens t where t.user_id = n.user_id)
        union all
        select d.user_id from public.notify_settings d
          where d.server_id = sid and d.channel_id is null and d.level = 'all' and d.user_id <> new.author_id
            and (d.last_push_at is null or d.last_push_at < now() - interval '10 seconds')
            and exists (select 1 from public.push_tokens t where t.user_id = d.user_id)
            and not exists (select 1 from public.notify_settings c where c.user_id = d.user_id and c.channel_id = new.channel_id and c.level is not null)
        limit 50
      ) a
      where not exists (select 1 from public.channel_reads r where r.user_id = a.user_id and r.channel_id = new.channel_id and r.muted
                          and not exists (select 1 from public.notify_settings m where m.user_id = a.user_id and m.channel_id = new.channel_id and m.muted_until <= now()));
    end if;
    if (strpos(body, '<@') = 0 and new.reply_to_id is null) and cardinality(everyone_set) = 0 then return null; end if;
    select array_agg(distinct t.x) into targets from (
      (select m[1]::uuid as x from regexp_matches(body, '<@(' || uuid_re || ')>', 'g') m limit 20)
      union all
      (select mr.user_id from public.member_roles mr
        where mr.server_id = sid
          and mr.role_id in (select m[1]::uuid from regexp_matches(body, '<@&(' || uuid_re || ')>', 'g') m limit 10)
        limit 50)
      union all
      (select pm.author_id from public.messages pm where new.reply_to_id is not null and pm.id = new.reply_to_id and pm.channel_id = new.channel_id)
    ) t where t.x is not null and t.x <> new.author_id;
    if levels and targets is not null then
      select array_agg(x) into targets from unnest(targets) x
        where coalesce((select c.level from public.notify_settings c where c.user_id = x and c.channel_id = new.channel_id),
                       (select d.level from public.notify_settings d where d.user_id = x and d.server_id = sid and d.channel_id is null),
                       'mentions') <> 'none';
    end if;
    targets := (select array_agg(distinct x) from unnest(coalesce(targets, '{}') || everyone_set) x);
  end if;
  if targets is null then return null; end if;

  old_claims := current_setting('request.jwt.claims', true);
  old_sub := current_setting('request.jwt.claim.sub', true);
  foreach uid in array targets loop
    if not exists (select 1 from public.push_tokens t where t.user_id = uid) then continue; end if;
    if public.is_site_banned(uid) then continue; end if;
    if exists (select 1 from public.blocks b where b.blocker = uid and b.blocked = new.author_id) then continue; end if;
    if exists (select 1 from public.presence p where p.user_id = uid and p.pref = 'dnd') then continue; end if;
    if sid is null then
      if exists (select 1 from public.channel_reads r where r.user_id = uid and r.channel_id = new.channel_id and r.muted) then continue; end if;
    else
      if not exists (select 1 from public.server_members sm where sm.server_id = sid and sm.user_id = uid) then continue; end if;
      if exists (select 1 from public.server_mutes m where m.user_id = uid and m.server_id = sid) then continue; end if;
      if coalesce(restricted, false) then
        perform set_config('request.jwt.claims', jsonb_build_object('sub', uid::text, 'role', 'authenticated')::text, true);
        perform set_config('request.jwt.claim.sub', uid::text, true);
        vis := public.can_access_channel(new.channel_id);
        perform set_config('request.jwt.claims', coalesce(nullif(old_claims, ''), '{}'), true);
        perform set_config('request.jwt.claim.sub', coalesce(old_sub, ''), true);
        if not coalesce(vis, false) then continue; end if;
      end if;
    end if;
    keep := keep || uid;
    exit when cardinality(keep) >= 50;
  end loop;
  if cardinality(keep) = 0 then return null; end if;

  begin
    select decrypted_secret into url from vault.decrypted_secrets where name = 'push_url';
    select decrypted_secret into secret from vault.decrypted_secrets where name = 'push_secret';
    if url is null or secret is null then return null; end if;
    if cardinality(everyone_set) > 0 then
      update public.notify_settings n set last_push_at = now()
        where n.ctid in (
          select r.ctid from public.notify_settings r
            where r.user_id = any (keep) and r.user_id = any (everyone_set) and r.level = 'all'
              and (r.channel_id = new.channel_id
                   or (r.channel_id is null and r.server_id = sid
                       and not exists (select 1 from public.notify_settings c where c.user_id = r.user_id and c.channel_id = new.channel_id and c.level is not null)))
            for update skip locked);
    end if;
    perform net.http_post(
      url := rtrim(url, '/') || '/api/push/send',
      headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || secret),
      body := jsonb_build_object('id', new.id, 'channel_id', new.channel_id, 'server_id', sid, 'author_id', new.author_id,
                                 'content', left(body, 300), 'attachment', new.attachment_path is not null, 'to', to_jsonb(keep)),
      timeout_milliseconds := 5000);
  exception when others then
    return null;
  end;
  return null;
end; $function$;

-- public.queue_banned_media()  [security definer]
CREATE OR REPLACE FUNCTION public.queue_banned_media()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.is_frozen(new.user_id) then return new; end if;
  insert into public.media_purge (bucket, path)
  select bucket_id, name from storage.objects
  where (storage.foldername(name))[1] = new.user_id::text
    and bucket_id <> 'report_clips'
  on conflict do nothing;
  return new;
end;
$function$;

-- public.raid_alert_done(aid uuid, p_banned integer)  [security definer]
CREATE OR REPLACE FUNCTION public.raid_alert_done(aid uuid, p_banned integer DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.raid_alerts;
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  select * into a from public.raid_alerts where id = aid;
  if a.id is null then raise exception 'That alert is gone'; end if;
  if not (public.is_staff() or (a.server_id is not null and public.server_perm(a.server_id, 'ban_members'))) then
    raise exception 'You can''t do that';
  end if;
  update public.raid_alerts set resolved_at = coalesce(resolved_at, now()), resolved_by = coalesce(resolved_by, auth.uid()),
    banned = banned + greatest(0, least(coalesce(p_banned, 0), cardinality(user_ids)))
    where id = aid;
end $function$;

-- public.raid_ban_all(aid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.raid_ban_all(aid uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.raid_alerts; u uuid; n int := 0;
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  select * into a from public.raid_alerts where id = aid;
  if a.id is null or a.server_id is null then raise exception 'That alert is gone'; end if;
  if not public.server_perm(a.server_id, 'ban_members') then raise exception 'You need Ban Members for that'; end if;
  foreach u in array a.user_ids loop
    if u = auth.uid() or public.raid_exempt(a.server_id, u) then continue; end if;
    if exists (select 1 from public.server_bans where server_id = a.server_id and user_id = u) then continue; end if;
    begin
      perform public.ban_member(a.server_id, u);
      n := n + 1;
    exception when others then null;  -- outranks us, already gone: skip
    end;
  end loop;
  update public.raid_alerts set resolved_at = now(), resolved_by = auth.uid(), banned = banned + n where id = aid;
  return n;
end $function$;

-- public.raid_exempt(sid uuid, uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.raid_exempt(sid uuid, uid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.is_staff_user(uid)
    or public.is_bot_user(uid)
    or uid = (select webhook_user_id from public.app_settings limit 1)
    or public.server_perm_user(sid, uid, 'manage_messages')
    or exists (
      select 1 from public.member_roles mr join public.roles r on r.id = mr.role_id
      where mr.server_id = sid and mr.user_id = uid and mr.by_person and r.auto = 'none'
        and not exists (select 1 from public.reaction_roles rr where rr.server_id = sid and rr.role_id = r.id)
        and not exists (select 1 from public.onboarding_answers a where a.server_id = sid and r.id = any (a.role_ids))
    );
$function$;

-- public.raid_fire(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.raid_fire(sid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare mc int; a public.raid_alerts; uid uuid; note jsonb; prev timestamptz; staff_ boolean; since timestamptz;
begin
  select greatest(now() - interval '60 seconds', coalesce(raid_reset_at, '-infinity')) into since from public.servers where id = sid;
  update public.servers set raid_until = now() + interval '10 minutes', raid_reset_at = now()
    where id = sid and (raid_until is null or raid_until <= now())
    returning member_count, (select max(created_at) from public.raid_alerts x where x.server_id = sid and x.staff) into mc, prev;
  if not found then return; end if;  -- already in raid mode (or someone else just turned it on)
  -- Big servers go to staff too, at most once an hour per server.
  staff_ := coalesce(mc, 0) >= 100 and (prev is null or prev < now() - interval '1 hour');
  insert into public.raid_alerts (kind, server_id, user_ids, staff, until)
    select 'server', sid, coalesce((array_agg(h.user_id order by h.at))[1:200], '{}'), staff_, now() + interval '10 minutes'
    from public.raid_hits h where h.server_id = sid and h.at > since
    returning * into a;
  note := jsonb_build_object('id', a.id, 'kind', a.kind, 'server_id', sid, 'until', a.until, 'count', cardinality(a.user_ids));
  -- Every member's tab gets the server row change (servers_bc). Mods' tabs pick this up and fetch the list,
  -- which only they (and staff) can read.
  perform public.bc_notice('server:' || sid, 'raid_alert', note);
  if a.staff then
    for uid in (select user_id from public.site_admins union select user_id from public.site_moderators) loop
      perform public.bc_notice('user:' || uid, 'raid_alert', note);
    end loop;
  end if;
end $function$;

-- public.raid_threshold(members integer)
CREATE OR REPLACE FUNCTION public.raid_threshold(members integer)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select least(50, greatest(8, coalesce(members, 0) / 2000));
$function$;

-- public.reaction_emoji_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.reaction_emoji_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m text[]; e record; rre text;
begin
  m := regexp_match(new.emoji, '^<a?:[A-Za-z0-9_]{2,32}:([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})>$');
  if m is not null then
    select id, name, animated into e from public.emojis where id = m[1]::uuid;
    if not found then raise exception 'That emoji doesn''t exist anymore'; end if;
    select rr.emoji into rre from public.reaction_roles rr
     where rr.message_id = new.message_id and rr.emoji like '%:' || e.id::text || '>' limit 1;
    if rre is not null then new.emoji := rre; return new; end if;
    new.emoji := '<' || case when coalesce(e.animated, false) then 'a' else '' end || ':' || e.name || ':' || e.id || '>';
    return new;
  end if;
  if public.reaction_emoji_ok(new.emoji) then return new; end if;
  if exists (select 1 from public.reaction_roles where message_id = new.message_id and emoji = new.emoji) then return new; end if;
  raise exception 'You can only react with an emoji';
end;
$function$;

-- public.reaction_emoji_ok(e text)
CREATE OR REPLACE FUNCTION public.reaction_emoji_ok(e text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select e is not null and char_length(e) <= 80 and (
    e ~ '^<a?:[A-Za-z0-9_]{2,32}:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}>$'
    or e ~ (
      '^(?:[\U0001F1E6-\U0001F1FF]{2}|[0-9#*]️?⃣|'
      || '[©®‼⁉℀-⯿〰〽㊗㊙\U0001F000-\U0001FAFF]'
      || '[︎️\U0001F3FB-\U0001F3FF\U000E0020-\U000E007F⃣]*)'
      || '(?:‍[©®‼⁉℀-⯿〰〽㊗㊙\U0001F000-\U0001FAFF]'
      || '[︎️\U0001F3FB-\U0001F3FF\U000E0020-\U000E007F⃣]*){0,9}$'
    )
  );
$function$;

-- public.reaction_exists(mid uuid, e text)  [security definer]
CREATE OR REPLACE FUNCTION public.reaction_exists(mid uuid, e text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.can_access_channel(public.message_channel(mid))
     and exists (select 1 from public.reactions where message_id = mid and emoji = e);
$function$;

-- public.reaction_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.reaction_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid;
begin
  -- The system and the paths that set yapper.bot skip it; staff skip it too (checked only when a refusal is coming).
  if auth.uid() is null or coalesce(current_setting('yapper.bot', true), '') = '1' then return new; end if;
  -- Site timeout (profiles.muted_until), the same one message_automod enforces for messages.
  if exists (select 1 from public.profiles p where p.id = new.user_id and p.muted_until > now()) then
    if public.is_staff() then return new; end if;
    raise exception 'You are timed out, so you can''t react right now.' using errcode = 'insufficient_privilege';
  end if;
  -- Server timeout, the same one block_server_timeouts enforces for messages in that server.
  select c.server_id into sid from public.messages m join public.channels c on c.id = m.channel_id where m.id = new.message_id;
  if sid is not null and exists (select 1 from public.server_timeouts t where t.server_id = sid and t.user_id = new.user_id and t.until > now()) then
    if public.is_staff() then return new; end if;
    raise exception 'You are timed out in this server, so you can''t react right now.' using errcode = 'insufficient_privilege';
  end if;
  return new;
end $function$;

-- public.reaction_limit()  [security definer]
CREATE OR REPLACE FUNCTION public.reaction_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from public.reactions where message_id = new.message_id and emoji = new.emoji)
     and (select count(distinct emoji) from public.reactions where message_id = new.message_id) >= 20 then
    raise exception 'This message has enough reactions';
  end if;
  return new;
end;
$function$;

-- public.reaction_new_account_check(sid uuid, uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.reaction_new_account_check(sid uuid, uid uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare born timestamptz; age_min int; amode text; def uuid; wait interval;
begin
  select created_at into born from public.profiles where id = uid;
  -- Older than the longest rule (7 days): nothing more to read.
  if born is null or born <= now() - interval '7 days' then return null; end if;
  -- HQ: brand-new accounts wait (message_raid_guard). Nobody but bots skips it there either.
  select default_server_id, new_account_wait into def, wait from public.app_settings limit 1;
  if def is not null and sid = def and wait is not null and born > now() - wait then
    return 'Welcome! New accounts can react here ' || public.wait_label(born + wait) || ' from now.';
  end if;
  -- A server's new account rule, chat mode (193).
  select new_account_minutes, new_account_mode into age_min, amode from public.servers where id = sid;
  if age_min is null or amode <> 'chat' or born <= now() - make_interval(mins => age_min) then return null; end if;
  if public.is_staff_user(uid) or public.server_perm_user(sid, uid, 'manage_messages') then return null; end if;
  return 'New accounts can''t react here until they''re ' || public.new_account_label(age_min) || ' old. You can react here in '
    || public.wait_label(born + make_interval(mins => age_min)) || '.';
end $function$;

-- public.reaction_rate_limit()  [security definer]
CREATE OR REPLACE FUNCTION public.reaction_rate_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or auth.uid() is distinct from new.user_id
     or coalesce(current_setting('yapper.bot', true), '') = '1' then
    return new;
  end if;
  new.created_at := now();
  perform pg_advisory_xact_lock(hashtextextended('react:' || new.user_id::text, 0));
  if (select count(*) from (select 1 from public.reactions r
        where r.user_id = new.user_id and r.created_at > now() - interval '10 seconds' limit 20) x) >= 20
     or (select count(*) from (select 1 from public.reactions r
        where r.user_id = new.user_id and r.created_at > now() - interval '5 minutes' limit 100) y) >= 100 then
    raise exception 'Slow down, you''re reacting too fast. Try again in a bit.' using errcode = 'check_violation';
  end if;
  return new;
end $function$;

-- public.reaction_role_apply()  [security definer]
CREATE OR REPLACE FUNCTION public.reaction_role_apply()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare rr record; uid uuid := coalesce(new.user_id, old.user_id);
begin
  select * into rr from public.reaction_roles where message_id = coalesce(new.message_id, old.message_id) and emoji = coalesce(new.emoji, old.emoji);
  if rr.role_id is null then return null; end if;
  if not exists (select 1 from public.server_members where server_id = rr.server_id and user_id = uid) then return null; end if;
  perform set_config('yapper.bot', '1', true);
  if tg_op = 'INSERT' then
    insert into public.member_roles (server_id, user_id, role_id) values (rr.server_id, uid, rr.role_id) on conflict do nothing;
  else
    perform public.drop_member_role(rr.server_id, uid, rr.role_id);
  end if;
  perform set_config('yapper.bot', '', true);
  return null;
end; $function$;

-- public.reaction_verification_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.reaction_verification_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; why text;
begin
  if current_setting('yapper.bot', true) = '1' then return new; end if;
  if auth.uid() is distinct from new.user_id then return new; end if;
  select c.server_id into sid from public.messages m join public.channels c on c.id = m.channel_id where m.id = new.message_id;
  if sid is null then return new; end if;
  why := public.server_gate(sid, new.user_id, false);
  -- 485: the account-age waits messages already have (HQ's, and a server's new account rule in chat mode).
  if why is null then why := public.reaction_new_account_check(sid, new.user_id); end if;
  if why is not null then raise exception '%', why using errcode = 'check_violation'; end if;
  return new;
end $function$;

-- public.reauth_check(p_password text)  [security definer]
CREATE OR REPLACE FUNCTION public.reauth_check(p_password text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare uid uuid := auth.uid(); h text; mfa boolean;
begin
  if uid is null then raise exception 'You need to be logged in'; end if;
  perform pg_advisory_xact_lock(hashtextextended('reauth:' || uid::text, 0));
  if (select count(*) from public.reauth_attempts where user_id = uid and at > now() - interval '15 minutes') >= 5
     or (select count(*) from public.reauth_attempts where user_id = uid and at > now() - interval '1 day') >= 20 then
    return 'Too many wrong passwords. Try again later';
  end if;
  select encrypted_password into h from auth.users where id = uid;
  if p_password is null or p_password = '' or char_length(p_password) > 200 or h is null or h = ''
     or extensions.crypt(p_password, h) <> h then
    insert into public.reauth_attempts (user_id) values (uid);
    return 'That password isn''t right';
  end if;
  if to_regclass('auth.mfa_factors') is not null then
    execute 'select exists (select 1 from auth.mfa_factors where user_id = $1 and status = ''verified'')' into mfa using uid;
    if mfa and coalesce(auth.jwt() ->> 'aal', 'aal1') <> 'aal2' then
      return 'Enter your 2FA code first';
    end if;
  end if;
  return null;
end;
$function$;

-- public.record_creator_referral(p_code text, p_user uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.record_creator_referral(p_code text, p_user uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ref_id uuid;
begin
  if p_user is null or p_code is null or btrim(p_code) = '' then return false; end if;
  select l.user_id into ref_id from public.creator_links l
    join public.profiles p on p.id = l.user_id and p.badges && array['creator_1', 'creator_2', 'creator_3']
    where l.code = lower(btrim(p_code));
  if ref_id is null or ref_id = p_user then return false; end if;
  if public.is_site_banned(ref_id) then return false; end if;
  if not exists (select 1 from public.profiles where id = p_user) then return false; end if;
  insert into public.creator_referrals (user_id, referrer) values (p_user, ref_id) on conflict (user_id) do nothing;
  return found;
end; $function$;

-- public.refresh_bot_real_servers()  [security definer]
CREATE OR REPLACE FUNCTION public.refresh_bot_real_servers()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  with c as (
    select b.id, public.bot_real_server_count(b.id)::integer as real
    from public.bots b
    where b.public or b.unlisted or b.verified_at is not null
  )
  update public.bots b set real_servers = c.real from c where c.id = b.id and b.real_servers is distinct from c.real;
  get diagnostics n = row_count;
  update public.bots set real_servers = null
  where real_servers is not null and not (public or unlisted or verified_at is not null);
  return n;
end $function$;

-- public.refresh_discover_rank()  [security definer]
CREATE OR REPLACE FUNCTION public.refresh_discover_rank()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  if not pg_try_advisory_xact_lock(hashtext('public.refresh_discover_rank')) then return 0; end if;
  execute $a$
    with fresh as materialized (
      select o.id, o.pos::integer as pos, case when o.lifted then o.boosts else 0 end as boosts, o.lifted
      from public.discovery_order_m('', null, null) o
    ),
    up as (
      insert into public.discover_rank as r (id, pos, boosts, lifted)
      select f.id, f.pos, f.boosts, f.lifted from fresh f
      on conflict (id) do update set pos = excluded.pos, boosts = excluded.boosts, lifted = excluded.lifted
        where (r.pos, r.boosts, r.lifted) is distinct from (excluded.pos, excluded.boosts, excluded.lifted)
      returning 1
    ),
    gone as (
      de$a$ || $b$lete from public.discover_rank r where not exists (select 1 from fresh f where f.id = r.id)
      returning 1
    )
    select ((select count(*) from up) + (select count(*) from gone))::integer
  $b$ into n;
  return n;
end $function$;

-- public.refresh_leaderboards_backfill()  [security definer]
CREATE OR REPLACE FUNCTION public.refresh_leaderboards_backfill()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare st public.leaderboard_state; cur date := public.lb_week(now()); wk timestamptz;
        started timestamptz := clock_timestamp(); ids uuid[]; last uuid; done integer := 0;
begin
  if not pg_try_advisory_xact_lock(hashtext('public.refresh_leaderboards_backfill')) then return 0; end if;
  select * into st from public.leaderboard_state where id;
  if st.backfill_done or st.backfill_before is null then return 0; end if;
  wk := cur::timestamp at time zone 'utc';
  last := st.backfill_cursor;
  loop
    select array_agg(p.id order by p.id) into ids
      from (select p.id from public.profiles p where last is null or p.id > last order by p.id limit 100) p;
    if ids is null then
      update public.leaderboard_state set backfill_done = true, backfill_cursor = null where id;
      exit;
    end if;
    perform public.lb_bump(array_agg(c.id), array_agg(cur), array_agg(c.wk), array_agg(0), array_agg(0), array_agg(c.n))
      from (select x.id, m.n, m.wk
              from unnest(ids) x(id)
              cross join lateral (select count(*)::bigint n, (count(*) filter (where mm.created_at >= wk))::integer wk
                                    from public.messages mm
                                   where mm.author_id = x.id and mm.created_at < st.backfill_before) m
             where m.n > 0
               and not exists (select 1 from public.bots b where b.id = x.id)
               and not exists (select 1 from public.bot_accounts a where a.user_id = x.id)
               and not exists (select 1 from public.app_settings s where s.webhook_user_id = x.id)) c;
    done := done + array_length(ids, 1);
    last := ids[array_length(ids, 1)];
    update public.leaderboard_state set backfill_cursor = last where id;
    exit when clock_timestamp() - started > interval '3 seconds';
  end loop;
  return done;
end $function$;

-- public.refresh_leaderboards()  [security definer]
CREATE OR REPLACE FUNCTION public.refresh_leaderboards()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare st public.leaderboard_state; cur date := public.lb_week(now()); wk timestamptz;
        upto timestamptz; lo bigint; hi bigint; n integer := 0; k integer;
begin
  if not pg_try_advisory_xact_lock(hashtext('public.refresh_leaderboards')) then return 0; end if;
  wk := cur::timestamp at time zone 'utc';
  select * into st from public.leaderboard_state where id for update;

  -- 1. messages since the last pass (messages_created_idx). At most 6 hours per tick, so a long pause catches up in steps.
  if st.msgs_upto is null then
    -- First pass: start here; the backfill job counts everything before.
    update public.leaderboard_state set msgs_upto = now() - interval '2 minutes', backfill_before = now() - interval '2 minutes'
     where id returning * into st;
  else
    upto := least(now() - interval '2 minutes', st.msgs_upto + interval '6 hours');
    if upto > st.msgs_upto then
      perform public.lb_bump(array_agg(c.author_id), array_agg(c.w), array_agg(c.n), array_agg(0), array_agg(0), array_agg(c.n::bigint))
        from (select m.author_id, public.lb_week(m.created_at) w, count(*)::integer n
                from public.messages m
               where m.created_at >= st.msgs_upto and m.created_at < upto
                 and m.author_id is not null and m.webhook is null and m.system is null
               group by 1, 2) c
       where not exists (select 1 from public.bots b where b.id = c.author_id)
         and not exists (select 1 from public.bot_accounts a where a.user_id = c.author_id)
         and not exists (select 1 from public.profiles p where p.id = c.author_id and 'bot' = any(coalesce(p.badges, '{}'::text[])));
      update public.leaderboard_state set msgs_upto = upto where id;
    end if;
  end if;

  -- 2. Shards earned (shard_ledger ids are in order). First pass: from this week's first row (one scan of a small table).
  lo := st.shards_upto;
  if lo is null then
    lo := coalesce((select min(l.id) from public.shard_ledger l where l.created_at >= wk),
                   (select coalesce(max(l.id), 0) + 1 from public.shard_ledger l)) - 1;
  end if;
  -- Only rows older than 2 minutes: an id handed out earlier can commit after a later one.
  select max(l.id) into hi from public.shard_ledger l where l.id > lo and l.id <= lo + 50000 and l.created_at < now() - interval '2 minutes';
  if hi is not null then
    perform public.lb_bump(array_agg(c.user_id), array_agg(c.w), array_agg(0), array_agg(0), array_agg(c.n), array_agg(0::bigint))
      from (select l.user_id, public.lb_week(l.created_at) w, sum(l.amount)::integer n
              from public.shard_ledger l
             where l.id > lo and l.id <= hi and l.amount > 0 and l.kind in ('daily', 'activity', 'streak', 'invite', 'quest')
             group by 1, 2) c;
    lo := hi;
  end if;
  update public.leaderboard_state set shards_upto = lo where id and shards_upto is distinct from lo;

  -- 3. Gifts and invites from their small tables (only changed rows written). An invite counts once the invitee came
  --    back and was active on a later day than the one they joined (shard_days), so a pile of fresh alts doesn't.
  with g as (select q.gifter_id u, count(*)::integer n from public.plus_gifts q
              where q.gifter_id is not null and q.source = 'stripe' and q.refunded_at is null group by 1),
       r as (select q.inviter u, count(*)::integer n from public.referrals q
              where q.inviter is not null and q.status <> 'refused'
                and exists (select 1 from public.shard_days d where d.user_id = q.invitee and d.day > q.created_at::date and d.minutes >= 5)
              group by 1),
       want as (select coalesce(g.u, r.u) u, coalesce(g.n, 0) gifts, coalesce(r.n, 0) invites
                  from g full join r on r.u = g.u
                union all
                select s.user_id, 0, 0 from public.leaderboard_stats s
                 where (s.gifts > 0 or s.invites > 0)
                   and not exists (select 1 from g where g.u = s.user_id) and not exists (select 1 from r where r.u = s.user_id))
  insert into public.leaderboard_stats as x (user_id, gifts, invites)
  select w.u, w.gifts, w.invites from want w where exists (select 1 from public.profiles p where p.id = w.u)
  on conflict (user_id) do update set gifts = excluded.gifts, invites = excluded.invites
    where (x.gifts, x.invites) is distinct from (excluded.gifts, excluded.invites);

  -- 4. Voice still going: credit each person up to now, once however many connections they have (capped at 6 hours
  --    after their latest join), then close what has run out. Late in the tick, so the rows stay locked only briefly.
  --    Someone with a join or leave in flight is skipped (their per-person lock is taken): they're credited next tick,
  --    and that event waits for this tick to commit, so it sees the new since. Flag off: nothing is tracked.
  if exists (select 1 from public.feature_flags f where f.key = 'global_leaderboards' and f.mode <> 'off') then
    with locked as materialized (
           select v.user_id, v.sid, v.joined_at, v.since from public.leaderboard_voice_open v
            where not v.closed and pg_try_advisory_xact_lock(hashtext('lb_voice:' || v.user_id::text))
            for update skip locked),
         per as (select l.user_id,
                        greatest(0, floor(extract(epoch from (least(now(), max(l.joined_at) + interval '6 hours')
                                                              - greatest(min(l.since), wk)))))::integer secs
                   from locked l group by 1),
         moved as (update public.leaderboard_voice_open v set since = now() from locked l
                    where v.user_id = l.user_id and v.sid = l.sid returning 1)
    select (select count(*) from moved)::integer into k
      from (select public.lb_bump(array_agg(p.user_id), array_agg(cur), array_agg(0), array_agg(p.secs), array_agg(0), array_agg(0::bigint))
              from per p where p.secs > 0) b;
    execute 'de' || 'lete from public.leaderboard_voice_open where (not closed and joined_at < now() - interval ''6 hours'')'
      || ' or (closed and joined_at < now() - interval ''1 hour'')';
  else
    execute 'de' || 'lete from public.leaderboard_voice_open';
  end if;

  -- 5. The boards: top 100 each, one statement, only changed rows written.
  execute $a$
    with cand as materialized (
      (select 'messages_week'::text b, s.user_id, s.msgs_week::bigint score from public.leaderboard_stats s
        where s.week = $1 and s.msgs_week > 0 order by s.msgs_week desc limit 300)
      union all
      (select 'voice_week', s.user_id, s.voice_week from public.leaderboard_stats s
        where s.week = $1 and s.voice_week > 0 order by s.voice_week desc limit 300)
      union all
      (select 'shards_week', s.user_id, s.shards_week from public.leaderboard_stats s
        where s.week = $1 and s.shards_week > 0 order by s.shards_week desc limit 300)
      union all
      (select 'messages_all', s.user_id, s.msgs_all from public.leaderboard_stats s
        where s.msgs_all > 0 order by s.msgs_all desc limit 300)
      union all
      (select 'gifts', s.user_id, s.gifts from public.leaderboard_stats s
        where s.gifts > 0 order by s.gifts desc limit 300)
      union all
      (select 'invites', s.user_id, s.invites from public.leaderboard_stats s
        where s.invites > 0 order by s.invites desc limit 300)
    ),
    top as materialized (
      select t.* from (
        select c.b, c.user_id, c.score,
               (rank() over (partition by c.b order by c.score desc))::integer pos,
               (row_number() over (partition by c.b order by c.score desc, c.user_id))::integer ord
          from cand c join public.profiles p on p.id = c.user_id
         where not p.leaderboard_hidden and not public.lb_ineligible(c.user_id)) t
      where t.ord <= 100
    ),
    up as (
      insert into public.leaderboard_board as x (board, user_id, pos, ord, score)
      select t.b, t.user_id, t.pos, t.ord, t.score from top t
      on conflict (board, user_id) do update set pos = excluded.pos, ord = excluded.ord, score = excluded.score
        where (x.pos, x.ord, x.score) is distinct from (excluded.pos, excluded.ord, excluded.score)
      returning 1
    ),
    gone as (
      de$a$ || $b$lete from public.leaderboard_board x where not exists (select 1 from top t where t.b = x.board and t.user_id = x.user_id)
      returning 1
    )
    select ((select count(*) from up) + (select count(*) from gone))::integer
  $b$ into n using cur;

  update public.leaderboard_state set refreshed_at = now() where id;
  return n;
end $function$;

-- public.refresh_level_board()  [security definer]
CREATE OR REPLACE FUNCTION public.refresh_level_board()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  if not pg_try_advisory_xact_lock(hashtext('public.refresh_level_board')) then return 0; end if;
  execute $a$
    with ranked as materialized (
      select p.id, p.account_level as level, p.created_at
      from public.profiles p
      where p.account_level >= 1 and not p.leaderboard_hidden
        and not ('bot' = any(coalesce(p.badges, '{}'::text[])))
        and not exists (select 1 from public.bots b where b.id = p.id)
        and not exists (select 1 from public.bot_accounts a where a.user_id = p.id)
        and not exists (select 1 from public.site_bans s where s.user_id = p.id and (s.expires_at is null or s.expires_at > now()))
    ),
    top as materialized (
      select t.* from (
        select r.id, r.level,
               (rank() over (order by r.level desc))::integer as pos,
               (row_number() over (order by r.level desc, r.created_at, r.id))::integer as ord
        from ranked r) t
      where t.ord <= 100
    ),
    counts as materialized (select r.level, count(*)::integer as n from ranked r group by r.level),
    up as (
      insert into public.level_board as b (user_id, pos, ord, level)
      select t.id, t.pos, t.ord, t.level from top t
      on conflict (user_id) do update set pos = excluded.pos, ord = excluded.ord, level = excluded.level
        where (b.pos, b.ord, b.level) is distinct from (excluded.pos, excluded.ord, excluded.level)
      returning 1
    ),
    gone as (
      de$a$ || $b$lete from public.level_board b where not exists (select 1 from top t where t.id = b.user_id)
      returning 1
    ),
    up_n as (
      insert into public.level_counts as c (level, n)
      select k.level, k.n from counts k
      on conflict (level) do update set n = excluded.n where c.n is distinct from excluded.n
      returning 1
    ),
    gone_n as (
      de$b$ || $c$lete from public.level_counts c where not exists (select 1 from counts k where k.level = c.level)
      returning 1
    )
    select ((select count(*) from up) + (select count(*) from gone) + (select count(*) from up_n) + (select count(*) from gone_n))::integer
  $c$ into n;
  return n;
end $function$;

-- public.release_case(k text)  [security definer]
CREATE OR REPLACE FUNCTION public.release_case(k text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.mod_case_claims set claimed_at = now() - interval '1 hour'
  where case_key = k and user_id = auth.uid() and public.is_staff();
$function$;

-- public.remove_friend(other uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.remove_friend(other uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  delete from public.friendships
  where least(requester, addressee) = least(auth.uid(), other)
    and greatest(requester, addressee) = greatest(auth.uid(), other);
$function$;

-- public.remove_friends(others uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.remove_friends(others uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); ids uuid[]; n int;
begin
  if me is null then raise exception 'Not signed in'; end if;
  if not public.feature_on_for_me('mass_remove') then raise exception 'Not available yet'; end if;
  ids := (select array_agg(distinct x) from unnest(coalesce(others, '{}')) x where x <> me);
  if cardinality(coalesce(ids, '{}')) > 200 then raise exception 'Up to 200 at a time'; end if;
  execute 'del' || 'ete from public.friendships where (requester = $1 and addressee = any($2)) or (addressee = $1 and requester = any($2))'
    using me, ids;
  get diagnostics n = row_count;
  return n;
end $function$;

-- public.remove_group_member(cid uuid, uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.remove_group_member(cid uuid, uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if auth.uid() is null or not exists (
    select 1 from public.channels c
     where c.id = cid and c.kind = 'group' and c.created_by = auth.uid()
       and exists (select 1 from public.channel_members m where m.channel_id = cid and m.user_id = auth.uid())
  ) then
    raise exception 'Only the person who made the group can remove people';
  end if;
  if uid = auth.uid() then raise exception 'Use Leave group instead'; end if;
  execute 'dele' || 'te from public.channel_members where channel_id = $1 and user_id = $2' using cid, uid;
  get diagnostics n = row_count;
  if n = 0 then raise exception 'They''re not in this group'; end if;
  execute 'dele' || 'te from public.channel_reads where channel_id = $1 and user_id = $2' using cid, uid;
end;
$function$;

-- public.remove_passkey(p_id uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.remove_passkey(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_name text;
begin
  if (select auth.uid()) is null then raise exception 'Sign in first'; end if;
  execute 'dele' || 'te from public.user_passkeys where id = $1 and user_id = $2 returning name' into v_name using p_id, (select auth.uid());
  if v_name is null then raise exception 'That passkey isn''t there anymore.'; end if;
  insert into public.security_log (user_id, event, detail) values ((select auth.uid()), 'passkey_removed', jsonb_build_object('name', v_name));
end $function$;

-- public.remove_supercharge(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.remove_supercharge(cid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  update public.supercharges set server_id = null where id = cid and user_id = auth.uid();
  if not found then raise exception 'That supercharge isn''t yours'; end if;
end $function$;

-- public.rename_category(cid uuid, p_name text)  [security definer]
CREATE OR REPLACE FUNCTION public.rename_category(cid uuid, p_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; n text := btrim(coalesce(p_name, ''));
begin
  select server_id into sid from public.channel_categories where id = cid;
  if sid is null or not public.server_perm(sid, 'manage_channels') then raise exception 'You can''t manage channels here'; end if;
  if char_length(n) not between 1 and 40 then raise exception 'Category names are 1 to 40 characters'; end if;
  update public.channel_categories set name = n where id = cid;
end; $function$;

-- public.rename_passkey(p_id uuid, p_name text)  [security definer]
CREATE OR REPLACE FUNCTION public.rename_passkey(p_id uuid, p_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_name text := btrim(left(btrim(regexp_replace(coalesce(p_name, ''), '[[:cntrl:]]', '', 'g')), 40)); v_old text;
begin
  if (select auth.uid()) is null then raise exception 'Sign in first'; end if;
  if v_name = '' then raise exception 'Give it a name'; end if;
  select name into v_old from public.user_passkeys where id = p_id and user_id = (select auth.uid()) for update;
  if v_old is null then raise exception 'That passkey isn''t there anymore.'; end if;
  if v_old = v_name then return; end if;
  update public.user_passkeys set name = v_name where id = p_id;
  insert into public.security_log (user_id, event, detail) values ((select auth.uid()), 'passkey_renamed', jsonb_build_object('from', v_old, 'to', v_name));
end $function$;

-- public.renew_placement_once(p_sub text, p_days integer, p_business text, p_event text)  [security definer]
CREATE OR REPLACE FUNCTION public.renew_placement_once(p_sub text, p_days integer, p_business text, p_event text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare got text; v_end timestamptz;
begin
  if coalesce(p_business, '') = '' then raise exception 'business id required'; end if;
  if p_days is null or p_days < 1 or p_days > 60 then raise exception 'bad renewal'; end if;
  if public.placement_for_sub(p_sub) is null then raise exception 'subscription unknown'; end if;
  insert into public.billing_fulfilments (business_id, kind, event_id) values (p_business, 'placement', p_event)
    on conflict (business_id) do nothing returning business_id into got;
  if got is null or exists (select 1 from public.stripe_cancel_jobs where sub = p_sub) then
    return (public.placement_for_sub(p_sub) ->> 'ends_at')::timestamptz;
  end if;
  update public.server_promotions set starts_at = case when ends_at < now() then now() else starts_at end,
         ends_at = greatest(now(), ends_at) + make_interval(days => p_days)
   where stripe_sub = p_sub returning ends_at into v_end;
  if v_end is null then
    update public.bot_promotions set starts_at = case when ends_at < now() then now() else starts_at end,
           ends_at = greatest(now(), ends_at) + make_interval(days => p_days)
     where stripe_sub = p_sub returning ends_at into v_end;
  end if;
  return v_end;
end $function$;

-- public.renew_supercharge_once(p_sub text, p_days integer, p_business text, p_event text)  [security definer]
CREATE OR REPLACE FUNCTION public.renew_supercharge_once(p_sub text, p_days integer, p_business text, p_event text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare got text; id_ uuid;
begin
  if coalesce(p_business, '') = '' then raise exception 'business id required'; end if;
  insert into public.billing_fulfilments (business_id, kind, event_id) values (p_business, 'supercharge', p_event)
    on conflict (business_id) do nothing returning business_id into got;
  if got is null then
    select s.id into id_ from public.supercharges s where s.stripe_sub = p_sub;
    return id_;
  end if;
  return public.renew_supercharge(p_sub, p_days);
end $function$;

-- public.renew_supercharge(p_sub text, p_days integer)  [security definer]
CREATE OR REPLACE FUNCTION public.renew_supercharge(p_sub text, p_days integer)
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.supercharges set until = greatest(until, now()) + make_interval(days => least(greatest(p_days, 1), 40))
  where stripe_sub = p_sub and p_sub is not null
  returning id;
$function$;

-- public.reopen_verification(rid uuid, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.reopen_verification(rid uuid, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.verification_requests;
begin
  if not public.is_staff() then raise exception 'Moderators only'; end if;
  select * into r from public.verification_requests where id = rid for update;
  if r.id is null then raise exception 'Not found'; end if;
  if r.user_id = auth.uid() and not public.is_site_admin() then
    raise exception 'You can''t review your own verification. Ask another moderator.';
  end if;
  if r.status <> 'rejected' then raise exception 'Only rejected requests can be reopened'; end if;
  if r.reviewed_at is null or r.reviewed_at < now() - interval '7 days' then
    raise exception 'That rejection is older than 7 days. They can apply again themselves';
  end if;
  -- Target = the applicant: a mod can't reopen their own rejection or a staff member's. Own action name, so
  -- reopens have their own hourly limit in mod_guard (default 60) and don't eat the 'verify' one.
  perform public.mod_guard('verify_reopen', r.user_id, null);
  if public.is_site_banned(r.user_id) then raise exception 'That account is banned'; end if;
  if exists (select 1 from public.profiles where id = r.user_id and verified_as is not null) then
    raise exception 'They are already verified';
  end if;
  if exists (select 1 from public.verification_requests
             where user_id = r.user_id and id <> r.id and (status in ('pending', 'needs_proof') or created_at > r.created_at)) then
    raise exception 'They have a newer request. Review that one instead';
  end if;
  update public.verification_requests
    set status = 'pending', reviewed_by = null, reviewed_at = null, review_note = ''
    where id = rid;
  insert into public.mod_log (actor, action, target_id, reason)
  values (auth.uid(), 'verify_reopen', r.user_id,
          left(coalesce(nullif(btrim(p_note), ''), 'Rejected by mistake'), 300) || ' (' || r.platform || ' ' || r.handle || ')');
  perform public.bc('user:' || r.user_id, 'verification', 'UPDATE', 'verification_requests', 'public', null, null);
end; $function$;

-- public.reorder_categories(sid uuid, ids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.reorder_categories(sid uuid, ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare i int;
begin
  if not public.server_perm(sid, 'manage_channels') then raise exception 'You can''t manage channels here'; end if;
  for i in 1 .. coalesce(array_length(ids, 1), 0) loop
    update public.channel_categories set position = i - 1 where id = ids[i] and server_id = sid;
  end loop;
end; $function$;

-- public.reorder_channels(sid uuid, ids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.reorder_channels(sid uuid, ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.server_perm(sid, 'manage_channels') then raise exception 'You can''t rearrange channels here'; end if;
  if not public.feature_on('reorder', sid) then raise exception 'Rearranging isn''t available here yet'; end if;
  if cardinality(ids) > 500 or cardinality(ids) <> (select count(distinct x) from unnest(ids) x) then
    raise exception 'Bad channel list';
  end if;
  update public.channels c set position = u.o - 1
  from unnest(ids) with ordinality as u(id, o)
  where c.id = u.id and c.server_id = sid and c.position is distinct from (u.o - 1)::int;
end;
$function$;

-- public.reorder_roles(sid uuid, ids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.reorder_roles(sid uuid, ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int; i int; k int; tp int; off int; want uuid[]; below uuid[]; f int;
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  n := coalesce(array_length(ids, 1), 0);
  -- One reorder per server at a time: two managers at once could interleave their writes.
  perform pg_advisory_xact_lock(hashtextextended('reorder_roles:' || sid::text, 0));
  if exists (select 1 from public.servers where id = sid and owner_id = auth.uid()) then
    for i in 1 .. n loop
      update public.roles set position = n - i where id = ids[i] and server_id = sid;
    end loop;
    return;
  end if;
  if not (public.server_perm(sid, 'manage_roles') or public.server_perm(sid, 'administrator')) then
    raise exception 'You need Manage Roles to rearrange roles';
  end if;
  select coalesce(max(r.position), -1) into tp from public.roles r join public.member_roles mr on mr.role_id = r.id
    where r.server_id = sid and mr.server_id = sid and mr.user_id = auth.uid();
  -- The roles asked about: this server's only, each once, in the order given (first mention wins).
  select array_agg(x.id order by x.ord) into want from (
    select r.id, min(u.ord) ord from unnest(ids) with ordinality u(id, ord) join public.roles r on r.id = u.id
    where r.server_id = sid group by r.id) x;
  select array_agg(w.id order by w.ord) into below from unnest(want) with ordinality w(id, ord)
    join public.roles r on r.id = w.id where r.position < tp;
  select count(*) into f from public.roles r where r.id = any(want) and r.position >= tp;
  -- Roles at or above your highest role must stay put, at the top of the list in their own order (equal positions can
  -- come in any order). Anything else would be skipped below, so say so instead of ignoring it quietly.
  if f > 0 and exists (
    select 1 from (
      select r.position, lag(r.position) over (order by w.ord) as prev
      from unnest(want[1:f]) with ordinality w(id, ord) join public.roles r on r.id = w.id) z
    where z.position < tp or z.position > z.prev
  ) then
    raise exception 'You can only move roles below your own top role';
  end if;
  if below is null then raise exception 'You can only move roles below your own top role'; end if;
  -- 517: distinct places, so roles that shared one can be told apart.
  k := array_length(below, 1);
  off := greatest(0, k - tp);
  if off > 0 then
    update public.roles set position = position + off where server_id = sid and position >= tp;
  end if;
  for i in 1 .. k loop
    update public.roles set position = k - i where id = below[i];
  end loop;
end;
$function$;

-- public.report_claim_clear()
CREATE OR REPLACE FUNCTION public.report_claim_clear()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.status <> 'open' then
    new.claimed_by := null;
    new.claimed_at := null;
  end if;
  return new;
end $function$;

-- public.report_claim_may_override(holder uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.report_claim_may_override(holder uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.is_site_admin() or public.is_site_manager()
      or (public.is_head_mod() and not exists (select 1 from public.site_admins where user_id = holder))
$function$;

-- public.report_claim_window()
CREATE OR REPLACE FUNCTION public.report_claim_window()
 RETURNS interval
 LANGUAGE sql
 IMMUTABLE
AS $function$ select interval '30 minutes' $function$;

-- public.report_clips_cleared(paths text[])  [security definer]
CREATE OR REPLACE FUNCTION public.report_clips_cleared(paths text[])
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.reports set voice_clip_path = null where voice_clip_path = any(paths);
$function$;

-- public.report_clips_due(lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.report_clips_due(lim integer DEFAULT 200)
 RETURNS TABLE(path text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  (select r.voice_clip_path from public.reports r
    where r.voice_clip_path is not null and r.resolved_at is not null and r.resolved_at < now() - interval '30 days'
    limit lim)
  union all
  (select o.name from storage.objects o
    where o.bucket_id = 'report_clips' and o.created_at < now() - interval '1 day'
      and not exists (select 1 from public.reports r where r.voice_clip_path = o.name)
    limit lim);
$function$;

-- public.report_clips_kick()  [security definer]
CREATE OR REPLACE FUNCTION public.report_clips_kick()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare secret text;
begin
  if not exists (select 1 from storage.objects where bucket_id = 'report_clips') then return; end if;
  select decrypted_secret into secret from vault.decrypted_secrets where name = 'request_limits_secret' limit 1;
  if coalesce(secret, '') = '' then return; end if;
  perform net.http_post(
    url := 'https://www.yapper.website/api/cron/report-clips',
    body := '{}'::jsonb,
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || secret),
    timeout_milliseconds := 30000);
end $function$;

-- public.report_guard(reporter uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.report_guard(reporter uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if reporter is null then raise exception 'You need to be logged in'; end if;
  if (select count(*) from public.reports where reporter_id = reporter and created_at > now() - interval '1 hour') >= 20 then
    raise exception 'You''ve sent a lot of reports. Try again later.';
  end if;
end;
$function$;

-- public.report_message_gone()
CREATE OR REPLACE FUNCTION public.report_message_gone()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.message_deleted_at := now();
  new.message_deleted_by := case
    when auth.uid() is null then 'system'
    when auth.uid() = new.target_id then 'author'
    when public.is_staff_user(auth.uid()) then 'staff'
    else 'server_mod' end;
  return new;
end $function$;

-- public.report_message(mid uuid, why text, more text)  [security definer]
CREATE OR REPLACE FUNCTION public.report_message(mid uuid, why text, more text DEFAULT ''::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m public.messages; rid uuid; ev jsonb; k text; gone timestamptz; gone_by uuid; with_gone boolean;
begin
  perform public.report_guard(auth.uid());
  select * into m from public.messages where id = mid;
  if m.id is null then
    select d.id, d.channel_id, d.author_id, d.content, d.attachment_path, d.webhook, d.created_at, d.deleted_at, d.deleted_by
      into m.id, m.channel_id, m.author_id, m.content, m.attachment_path, m.webhook, m.created_at, gone, gone_by
      from public.deleted_messages d where d.id = mid and d.deleted_at > now() - interval '2 days';
  end if;
  if m.id is null or not public.can_access_channel(m.channel_id) then raise exception 'Message not found'; end if;
  if m.author_id = auth.uid() then raise exception 'You can''t report your own message'; end if;
  select kind into k from public.channels where id = m.channel_id;
  with_gone := public.feature_on('report_context_deleted', null) and k in ('dm', 'group');
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', x.id, 'channel_id', x.channel_id, 'content', x.content, 'attachment', x.attachment_path, 'created_at', x.created_at,
      'author_id', x.author_id, 'kind', k) || case when x.deleted then '{"deleted": true}'::jsonb else '{}'::jsonb end
      order by x.created_at), '[]'::jsonb)
    into ev
  from (
    (select * from (
       (select id, channel_id, content, attachment_path, created_at, author_id, false deleted from public.messages
         where channel_id = m.channel_id and created_at <= m.created_at and id <> m.id order by created_at desc limit 8)
       union all
       (select d.id, d.channel_id, d.content, null::text, d.created_at, d.author_id, true from public.deleted_messages d
         where with_gone and d.channel_id = m.channel_id and d.created_at <= m.created_at and d.id <> m.id
           and d.deleted_at > now() - interval '2 days' and d.deleted_by is not distinct from d.author_id
           and not exists (select 1 from public.messages mm where mm.id = d.id)
         order by d.created_at desc limit 8)
     ) b order by created_at desc limit 8)
    union all
    (select * from (
       (select id, channel_id, content, attachment_path, created_at, author_id, false from public.messages
         where channel_id = m.channel_id and created_at > m.created_at order by created_at limit 4)
       union all
       (select d.id, d.channel_id, d.content, null::text, d.created_at, d.author_id, true from public.deleted_messages d
         where with_gone and d.channel_id = m.channel_id and d.created_at > m.created_at
           and d.deleted_at > now() - interval '2 days' and d.deleted_by is not distinct from d.author_id
           and not exists (select 1 from public.messages mm where mm.id = d.id)
         order by d.created_at limit 4)
     ) a order by created_at limit 4)
  ) x;
  insert into public.reports (reporter_id, target_id, message_id, channel_id, message_content, message_attachment, reason, details, evidence, server_id, webhook_id,
                              message_deleted_at, message_deleted_by)
  values (auth.uid(), coalesce((select w.created_by from public.webhooks w where m.webhook is not null and w.id = (m.webhook ->> 'id')::uuid), m.author_id),
          case when gone is null then m.id end, m.channel_id, m.content, m.attachment_path, why, left(coalesce(more, ''), 1000), ev,
          (select server_id from public.channels where id = m.channel_id), (m.webhook ->> 'id')::uuid,
          gone, case when gone is null then null when gone_by is null then 'system' when gone_by = m.author_id then 'author'
                     when public.is_staff_user(gone_by) then 'staff' else 'server_mod' end)
  returning id into rid;
  return rid;
end;
$function$;

-- public.report_release_attachment()  [security definer]
CREATE OR REPLACE FUNCTION public.report_release_attachment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.reports;
begin
  if tg_op = 'DELETE' then
    if old.status <> 'open' or old.message_attachment is null
       or split_part(old.message_attachment, '/', 1) is distinct from old.target_id::text then
      return null;
    end if;
    r := old;
  else
    r := new;
  end if;
  if not exists (select 1 from public.reports x where x.id <> r.id and x.status = 'open' and x.message_attachment = r.message_attachment) then
    insert into public.media_purge (bucket, path) values ('attachments', r.message_attachment) on conflict do nothing;
  end if;
  return null;
end $function$;

-- public.report_server(sid uuid, why text, more text)  [security definer]
CREATE OR REPLACE FUNCTION public.report_server(sid uuid, why text, more text DEFAULT ''::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); own uuid; nm text; born timestamptz; d text; rid uuid;
begin
  perform public.report_guard(uid);
  if not public.feature_on('server_reports', sid) then raise exception 'Not available yet'; end if;
  select owner_id, name into own, nm from public.servers where id = sid;
  if nm is null then raise exception 'Server not found'; end if;
  if own = uid then raise exception 'You can''t report your own server'; end if;
  if public.is_site_banned(uid) then raise exception 'You can''t send reports right now'; end if;
  select created_at into born from public.profiles where id = uid;
  if born is null or born > now() - interval '1 day' then
    raise exception 'Your account is too new to report servers. Try again tomorrow.';
  end if;
  if why is null or why not in ('harassment', 'hate', 'sexual', 'minor_safety', 'violence', 'spam', 'self_harm', 'illegal', 'other') then
    raise exception 'Pick what''s wrong';
  end if;
  perform pg_advisory_xact_lock(hashtext('report_server:' || uid::text));
  if exists (select 1 from public.reports where reporter_id = uid and reported_server_id = sid and created_at > now() - interval '24 hours') then
    raise exception 'You already reported this server today. Staff will take a look.';
  end if;
  if (select count(*) from public.reports where reporter_id = uid and reported_server_id is not null and created_at > now() - interval '24 hours') >= 5 then
    raise exception 'That''s a lot of server reports today. Try again tomorrow.';
  end if;
  d := left(regexp_replace(btrim(coalesce(more, '')), '^(\s*\[voice\]\s*)+', '', 'i'), 1000);
  insert into public.reports (reporter_id, reason, details, reported_server_id, reported_server_name)
  values (uid, why, d, sid, left(nm, 100))
  returning id into rid;
  return rid;
end $function$;

-- public.report_user(uid uuid, why text, more text)  [security definer]
CREATE OR REPLACE FUNCTION public.report_user(uid uuid, why text, more text DEFAULT ''::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare rid uuid; ev jsonb;
begin
  perform public.report_guard(auth.uid());
  if uid = auth.uid() then raise exception 'You can''t report yourself'; end if;
  if not exists (select 1 from public.profiles where id = uid) then raise exception 'User not found'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', m.id, 'channel_id', m.channel_id, 'content', m.content, 'attachment', m.attachment_path, 'created_at', m.created_at,
      'author_id', m.author_id, 'kind', (select kind from public.channels c where c.id = m.channel_id)) order by m.created_at desc), '[]'::jsonb)
    into ev
  from (
    select * from public.messages where author_id = uid and public.can_access_channel(channel_id) order by created_at desc limit 15
  ) m;
  insert into public.reports (reporter_id, target_id, reason, details, evidence)
  values (auth.uid(), uid, why, left(coalesce(more, ''), 1000), ev)
  returning id into rid;
  return rid;
end;
$function$;

-- public.report_voice(uid uuid, vchannel uuid, why text, more text)  [security definer]
CREATE OR REPLACE FUNCTION public.report_voice(uid uuid, vchannel uuid, why text, more text DEFAULT ''::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare rid uuid; sid uuid; present jsonb;
begin
  perform public.report_guard(auth.uid());
  if uid = auth.uid() then raise exception 'You can''t report yourself'; end if;
  select server_id into sid from public.channels where id = vchannel and kind = 'voice';
  if sid is null or not public.can_access_channel(vchannel) then raise exception 'Voice channel not found'; end if;
  insert into public.reports (reporter_id, target_id, channel_id, server_id, reason, details)
  values (auth.uid(), uid, vchannel, sid, why, '[voice] ' || left(coalesce(more, ''), 980))
  returning id into rid;
  return rid;
end;
$function$;

-- public.request_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.request_guard()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  claims text := nullif(current_setting('request.jwt.claims', true), '');
  sub text;
  aal text;
  uid uuid;
  till timestamptz;
  enf boolean;
begin
  if claims is not null then
    sub := claims::jsonb ->> 'sub';
    aal := claims::jsonb ->> 'aal';
  else
    sub := nullif(current_setting('request.jwt.claim.sub', true), '');
    aal := nullif(current_setting('request.jwt.claim.aal', true), '');
  end if;
  if sub is null then return; end if;
  if sub !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return; end if;
  uid := sub::uuid;

  perform set_config('response.headers', '[{"X-Yapper-Uid": "' || uid::text || '"}]', true);

  if coalesce(aal, 'aal1') <> 'aal2'
     and exists (select 1 from auth.mfa_factors f where f.user_id = uid and f.status = 'verified') then
    raise sqlstate 'PT403' using
      message = 'Finish signing in with your 2FA code.',
      hint = 'This account has 2FA on. A session that has not passed the code can''t read or change anything.';
  end if;

  select t.until, t.enforced into till, enf from public.request_throttle t where t.user_id = uid;
  if not found or not enf or till <= now() then return; end if;

  if not exists (
    select 1 from public.feature_flags f
    where f.key = 'request_limits' and (f.mode = 'everyone' or (f.mode = 'test' and uid = any(f.users)))
  ) then return; end if;

  raise sqlstate 'PT429' using
    message = 'Too many requests from your account. Try again after ' || to_char(till at time zone 'UTC', 'YYYY-MM-DD HH24:MI') || ' UTC.',
    hint = 'Yapper limits how often one account can call the API. Slow your script down.';
end $function$;

-- public.request_ip()
CREATE OR REPLACE FUNCTION public.request_ip()
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare h json;
begin
  begin
    h := nullif(current_setting('request.headers', true), '')::json;
  exception when others then return null;
  end;
  return public.ip_key(nullif(h ->> 'cf-connecting-ip', ''));
end $function$;

-- public.request_limits_apply(hits jsonb, threshold integer, window_min integer)  [security definer]
CREATE OR REPLACE FUNCTION public.request_limits_apply(hits jsonb, threshold integer DEFAULT 6000, window_min integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  f public.feature_flags;
  h jsonb;
  uid uuid;
  n int;
  enf boolean;
  was public.request_throttle;
  had boolean;
  top text;
  held int := 0;
  noticed int := 0;
  logged int := 0;
begin
  select * into f from public.feature_flags where key = 'request_limits';
  if not found or f.mode = 'off' then
    return jsonb_build_object('mode', coalesce(f.mode, 'missing'), 'held', 0, 'noticed', 0, 'logged', 0);
  end if;
  for h in select * from jsonb_array_elements(case when jsonb_typeof(hits) = 'array' then hits else '[]'::jsonb end) limit 200 loop
    if coalesce(h ->> 'u', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then continue; end if;
    uid := (h ->> 'u')::uuid;
    n := case when coalesce(h ->> 'c', '') ~ '^\d{1,9}$' then (h ->> 'c')::int else 0 end;
    if n < greatest(threshold, 1000) then continue; end if;
    if not exists (select 1 from public.profiles where id = uid) then continue; end if;
    top := left(coalesce(h ->> 'top', ''), 120);
    select * into was from public.request_throttle where user_id = uid for update;
    if found and was.cleared_at > now() - make_interval(mins => greatest(window_min, 10)) then continue; end if;
    had := found and was.until > now();
    enf := (f.mode = 'everyone' or (f.mode = 'test' and uid = any(f.users)))
      and not exists (select 1 from public.site_admins where user_id = uid)
      and not exists (select 1 from public.site_moderators where user_id = uid);
    insert into public.request_throttle as t (user_id, until, enforced, requests, top_path, user_agent)
    values (uid, now() + interval '15 minutes', enf, n, top, left(coalesce(h ->> 'ua', ''), 200))
    on conflict (user_id) do update set
      until = greatest(t.until, excluded.until),
      enforced = excluded.enforced,
      requests = excluded.requests,
      top_path = excluded.top_path,
      user_agent = excluded.user_agent,
      hits = case when t.until > now() then t.hits + 1 else 1 end,
      first_seen = case when t.until > now() then t.first_seen else now() end,
      last_seen = now(),
      cleared_at = null;
    if enf then held := held + 1; else noticed := noticed + 1; end if;
    if not had or (enf and not was.enforced) then
      insert into public.mod_log (actor, action, target_id, reason)
      values (null, case when enf then 'request_limit' else 'request_limit_seen' end, uid,
              format('%s API requests in %s min%s', n, window_min, case when top <> '' then ', mostly ' || top else '' end));
      logged := logged + 1;
    end if;
  end loop;
  execute 'del' || 'ete from public.request_throttle where until < now() - interval ''1 day''';
  return jsonb_build_object('mode', f.mode, 'held', held, 'noticed', noticed, 'logged', logged);
end $function$;

-- public.request_limits_kick()  [security definer]
CREATE OR REPLACE FUNCTION public.request_limits_kick()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  secret text;
  url text;
begin
  if not exists (select 1 from public.feature_flags where key = 'request_limits' and mode <> 'off') then return; end if;
  select decrypted_secret into secret from vault.decrypted_secrets where name = 'request_limits_secret' limit 1;
  if coalesce(secret, '') = '' then return; end if;
  select decrypted_secret into url from vault.decrypted_secrets where name = 'request_limits_url' limit 1;
  perform net.http_post(
    url := coalesce(nullif(url, ''), 'https://www.yapper.website/api/cron/request-limits'),
    body := '{}'::jsonb,
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || secret),
    timeout_milliseconds := 30000);
end $function$;

-- public.require_mfa()  [security definer]
CREATE OR REPLACE FUNCTION public.require_mfa()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is not null
     and coalesce(auth.jwt() ->> 'aal', 'aal1') <> 'aal2'
     and exists (select 1 from auth.mfa_factors f where f.user_id = auth.uid() and f.status = 'verified') then
    raise exception 'Finish two-factor sign-in first.' using errcode = 'insufficient_privilege';
  end if;
  return coalesce(new, old);
end;
$function$;

-- public.require_scanned_media()  [security definer]
CREATE OR REPLACE FUNCTION public.require_scanned_media()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  i int; col text; b text; val text; old_val text; sid uuid; strict_server boolean := false; cid uuid;
  gore_rule boolean := null;
begin
  -- This trigger also guards avatars, banners and server icons, whose rows have no channel.
  cid := (to_jsonb(new) ->> 'channel_id')::uuid;
  if cid is not null then
    select c.server_id into sid from public.channels c where c.id = cid;
    strict_server := sid is not null and sid = (select default_server_id from public.app_settings limit 1)
                     and not public.channel_allows(cid, 'manage_messages');
  end if;
  for i in 0 .. (tg_nargs / 2) - 1 loop
    col := tg_argv[i * 2];
    b := tg_argv[i * 2 + 1];
    val := to_jsonb(new) ->> col;
    old_val := case when tg_op = 'UPDATE' then to_jsonb(old) ->> col else null end;
    if val is not null and val is distinct from old_val then
      if not public.media_ok(b, val) then
        raise exception 'That image hasn''t been checked yet. Try sending it again.' using errcode = 'check_violation';
      end if;
      if strict_server and exists (select 1 from public.media_scans s where s.bucket = b and s.path = val and s.score >= 0.6) then
        raise exception 'That picture is too close to the line for Yapper HQ. It is fine in smaller servers.' using errcode = 'check_violation';
      end if;
      -- Gore check (484): a person's picture in HQ must have been through it. Worked out once per row, only here.
      -- Videos too (a new account's are refused at upload; anyone else's carry details.gore.skipped). KLIPY GIFs are
      -- picked from our own PG-13 search and stored by the server (gifs/attach), not uploaded: left out.
      if strict_server and b = 'attachments' and val ~* '\.(png|jpe?g|webp|gif|mp4|webm|mov)$' then
        gore_rule := coalesce(gore_rule, (select auth.uid()) is not null and public.feature_on_for_me('gore_check'));
        if gore_rule and not exists (select 1 from public.media_scans s where s.bucket = b and s.path = val
                                     and (s.details ? 'gore' or s.details ->> 'source' = 'klipy')) then
          raise exception 'Send that picture again so it can be checked for Yapin'' HQ.' using errcode = 'check_violation';
        end if;
      end if;
    end if;
  end loop;
  return new;
end;
$function$;

-- public.require_staff_reauth()  [security definer]
CREATE OR REPLACE FUNCTION public.require_staff_reauth()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.feature_on('staff_reauth', null) then return; end if;
  if not exists (select 1 from public.staff_reauth where user_id = auth.uid() and ok_at > now() - interval '5 minutes') then
    raise exception 'REAUTH: Enter your password to confirm this.';
  end if;
end $function$;

-- public.require_verified_email()  [security definer]
CREATE OR REPLACE FUNCTION public.require_verified_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if current_setting('yapper.bot', true) = '1' then return new; end if;
  if exists (select 1 from public.profiles p where p.id = new.author_id and p.verify_required) then
    raise exception 'Check your email and click the link we sent you, then you can post.' using errcode = 'check_violation';
  end if;
  return new;
end; $function$;

-- public.resolve_report(rid uuid, new_status text)  [security definer]
CREATE OR REPLACE FUNCTION public.resolve_report(rid uuid, new_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; old_status text; old_by uuid; tgt uuid;
begin
  select server_id, status, resolved_by, target_id into sid, old_status, old_by, tgt from public.reports where id = rid;
  if not (public.is_staff() or (sid is not null and public.server_perm(sid, 'manage_server'))) then raise exception 'Not allowed'; end if;
  if new_status not in ('open', 'actioned', 'dismissed') then raise exception 'Bad status'; end if;
  if new_status = 'actioned' and public.is_staff() then
    perform set_config('yapper.nsfw_confirm', '1', true);
  end if;
  update public.reports
     set status = new_status,
         resolved_by = case when new_status = 'open' then null else auth.uid() end,
         resolved_at = case when new_status = 'open' then null else now() end
   where id = rid;
  perform set_config('yapper.nsfw_confirm', '', true);
  if new_status = 'open' and old_status in ('actioned', 'dismissed') and public.is_staff() then
    insert into public.mod_log (actor, action, target_id, reason)
    values (auth.uid(), 'report_reopened', tgt,
            'Was ' || old_status || coalesce(' by ' || (select username from public.profiles where id = old_by), ''));
  end if;
end;
$function$;

-- public.resolve_reports(rids uuid[], new_status text)  [security definer]
CREATE OR REPLACE FUNCTION public.resolve_reports(rids uuid[], new_status text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r uuid; n int := 0;
begin
  if rids is null or array_length(rids, 1) is null then return 0; end if;
  if array_length(rids, 1) > 200 then raise exception 'Too many at once'; end if;
  foreach r in array rids loop
    perform public.resolve_report(r, new_status);
    n := n + 1;
  end loop;
  return n;
end; $function$;

-- public.respond_friend_request(other uuid, accept boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.respond_friend_request(other uuid, accept boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if accept then
    update public.friendships set status = 'accepted', accepted_at = now()
    where requester = other and addressee = auth.uid() and status = 'pending';
  else
    execute 'del' || 'ete from public.friendships where requester = $1 and addressee = $2 and status = ''pending'''
      using other, auth.uid();
    get diagnostics n = row_count;
    if n > 0 then
      insert into public.friend_request_declines (requester, addressee, declined_at) values (other, auth.uid(), now())
      on conflict (requester, addressee) do update set declined_at = excluded.declined_at;
    end if;
  end if;
end;
$function$;

-- public.revert_temp_avatars()  [security definer]
CREATE OR REPLACE FUNCTION public.revert_temp_avatars()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; n int := 0;
begin
  for r in
    select id, avatar_prev from public.profiles
    where avatar_revert_at is not null and avatar_revert_at <= now()
    order by avatar_revert_at limit 500
  loop
    begin
      if r.avatar_prev is null or exists (
        select 1 from public.media_scans s
        where s.bucket = 'avatars' and s.path = r.avatar_prev ->> 'path' and s.verdict <> 'ok'
      ) then
        update public.profiles set avatar_revert_at = null, avatar_prev = null where id = r.id;
      else
        update public.profiles set
          avatar_path = r.avatar_prev ->> 'path',
          avatar_x = coalesce((r.avatar_prev ->> 'x')::real, 50),
          avatar_y = coalesce((r.avatar_prev ->> 'y')::real, 50),
          avatar_zoom = coalesce((r.avatar_prev ->> 'zoom')::real, 1),
          avatar_rot = coalesce((r.avatar_prev ->> 'rot')::smallint, 0),
          avatar_revert_at = null,
          avatar_prev = null
        where id = r.id;
        n := n + 1;
      end if;
    exception when others then
      begin
        update public.profiles set avatar_revert_at = null, avatar_prev = null where id = r.id;
      exception when others then
        raise warning 'revert_temp_avatars: % stuck: %', r.id, sqlerrm;
      end;
    end;
  end loop;
  return n;
end $function$;

-- public.review_community_deco(p_id uuid, p_status text, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.review_community_deco(p_id uuid, p_status text, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.community_decos; got int; c_sub text; c_claims text; c_claim text;
begin
  if not (public.is_site_admin() or public.is_site_mod() or public.is_art_manager()) then raise exception 'Staff only'; end if;
  perform public.mod_guard(case when p_status = 'removed' then 'deco_takedown' else 'deco_review' end, null, p_note);
  if p_status not in ('approved', 'rejected', 'removed') then raise exception 'Bad status'; end if;
  p_note := left(btrim(coalesce(p_note, '')), 300);
  if p_status <> 'approved' and length(p_note) < 3 then raise exception 'Say why, so they know what to change'; end if;
  select * into d from public.community_decos where id = p_id for update;
  if not found then raise exception 'Not found'; end if;
  if d.artist_id = (select auth.uid()) then raise exception 'Someone else has to review your own'; end if;
  if d.status = 'removed' then raise exception 'That one was taken down'; end if;
  if p_status = 'approved' and not public.media_ok('avatars', d.path) then raise exception 'Its picture didn''t pass the check'; end if;
  if p_status = 'approved' and exists (select 1 from public.community_deco_checks c
      where c.deco_id = p_id and c.verdict in ('suspect', 'stolen') and c.cleared_at is null) then
    raise exception 'The auto-check flagged this one. Say why it''s fine first';
  end if;
  update public.community_decos set status = p_status, review_note = p_note, reviewed_by = (select auth.uid()), reviewed_at = now()
    where id = p_id;
  if d.status = 'approved' and p_status <> 'approved' then perform public.community_deco_unwear(d.path); end if;
  insert into public.mod_log (actor, action, target_id, reason)
    values ((select auth.uid()), 'deco_' || p_status, d.artist_id, left(d.name || case when p_note <> '' then ': ' || p_note else '' end, 300));
  if p_status = 'approved' and d.status <> 'approved' and not public.is_site_banned(d.artist_id) then
    begin
      -- 426: without the reviewer's JWT, so their own 2FA state (require_mfa) can't refuse the artist's badge.
      c_sub := current_setting('request.jwt.claim.sub', true);
      c_claims := current_setting('request.jwt.claims', true);
      c_claim := current_setting('request.jwt.claim', true);
      perform set_config('request.jwt.claim.sub', '', true);
      perform set_config('request.jwt.claims', '', true);
      perform set_config('request.jwt.claim', '', true);
      update public.profiles set badges = array_append(coalesce(badges, '{}'), 'artist')
        where id = d.artist_id and not ('artist' = any(coalesce(badges, '{}')));
      get diagnostics got = row_count;
      perform set_config('request.jwt.claim.sub', coalesce(c_sub, ''), true);
      perform set_config('request.jwt.claims', coalesce(c_claims, ''), true);
      perform set_config('request.jwt.claim', coalesce(c_claim, ''), true);
      if got > 0 then
        insert into public.mod_log (actor, action, target_id, reason) values ((select auth.uid()), 'badge_auto', d.artist_id, 'artist');
        perform public.rt_profile_changed(array[d.artist_id]);
      end if;
    exception when others then
      raise warning 'review_community_deco: artist badge for % not given: %', d.artist_id, sqlerrm;
    end;
  end if;
end; $function$;

-- public.review_creator_content(cid uuid, approve boolean, p_note text, p_views integer, p_format text, p_checks jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.review_creator_content(cid uuid, approve boolean, p_note text DEFAULT ''::text, p_views integer DEFAULT NULL::integer, p_format text DEFAULT NULL::text, p_checks jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c public.creator_content; until_at timestamptz; seen int; months int; total bigint; cur int; want int; badge text; fmt text;
  tiers constant text[] := array['creator_1', 'creator_2', 'creator_3'];
begin
  if not public.is_site_admin() then perform public.manager_guard(case when approve then 'creator' else 'creator_other' end, (select x.user_id from public.creator_content x where x.id = cid)); end if;
  p_note := left(btrim(coalesce(p_note, '')), 300);
  if p_checks is not null and (jsonb_typeof(p_checks) <> 'object' or length(p_checks::text) > 2000) then p_checks := null; end if;
  select * into c from public.creator_content where id = cid for update;
  if c.id is null then raise exception 'Not found'; end if;
  if c.status <> 'pending' then raise exception 'Already reviewed'; end if;
  if c.user_id = (select auth.uid()) then raise exception 'Someone else has to review your own'; end if;
  if approve then
    if public.is_site_banned(c.user_id) then raise exception 'That account is banned'; end if;
    if not exists (select 1 from public.profiles where id = c.user_id and badges && tiers) then raise exception 'Not in the Creator Program any more'; end if;
    if p_views is null then raise exception 'Type the views you see on the link'; end if;
    if p_views < 0 then raise exception 'Views can''t be negative'; end if;
    if p_format is not null and p_format not in ('long', 'short') then raise exception 'Format is long or short'; end if;
    fmt := coalesce(p_format, c.format);
    seen := least(p_views, 2000000000);
    months := public.creator_reward_months(fmt, seen);
    update public.creator_content set status = 'approved', format = fmt, views_checked = seen, reward_months = months, review_checks = p_checks,
      reviewed_by = (select auth.uid()), reviewed_at = now(), review_note = p_note where id = cid;
    insert into public.mod_log (actor, action, target_id, reason) values
      ((select auth.uid()), 'content_approved', c.user_id, left(c.link, 200) || ' (' || seen || ' views, ' || fmt || ', ' || months || ' months)' || case when p_note <> '' then ': ' || p_note else '' end);
    if months > 0 then
      update public.profiles set plus_until = greatest(coalesce(plus_until, now()), now()) + make_interval(days => 31 * months)
        where id = c.user_id returning plus_until into until_at;
      insert into public.mod_log (actor, action, target_id, reason) values
        ((select auth.uid()), 'plus_gift', c.user_id, 'Until ' || to_char(until_at, 'YYYY-MM-DD') || ': Creator Program content, ' || months || ' months');
    end if;
    total := public.creator_total_views(c.user_id);
    select coalesce(max(case b when 'creator_3' then 3 when 'creator_2' then 2 when 'creator_1' then 1 end), 0) into cur
      from public.profiles p, unnest(coalesce(p.badges, '{}'::text[])) b where p.id = c.user_id;
    want := case when total >= 500000 then 3 when total >= 100000 then 2 else 1 end;
    if want > cur and cur > 0 then
      badge := 'creator_' || want;
      update public.profiles set
        badges = array(select distinct unnest(
          array(select b from unnest(coalesce(badges, '{}'::text[])) b where not (b = any(tiers) and b <> badge))
          || badge || case when want = 3 then array['partner'] else '{}'::text[] end)),
        shown_badge = case when shown_badge = any(tiers) then badge else shown_badge end
        where id = c.user_id;
      insert into public.mod_log (actor, action, target_id, reason) values
        ((select auth.uid()), 'badge_given', c.user_id, badge || ' (Creator Program: ' || total || ' views)');
      if want = 3 then
        insert into public.mod_log (actor, action, target_id, reason) values ((select auth.uid()), 'badge_given', c.user_id, 'partner (Elite Creator)');
      end if;
    end if;
    begin
      perform public.rt_profile_changed(array[c.user_id]);
    exception when others then
      raise warning 'review_creator_content: profile cache ping for % failed: %', c.user_id, sqlerrm;
    end;
  else
    if length(p_note) < 3 then raise exception 'Say why, so they know what to change'; end if;
    update public.creator_content set status = 'rejected', review_checks = coalesce(p_checks, review_checks),
      reviewed_by = (select auth.uid()), reviewed_at = now(), review_note = p_note where id = cid;
    insert into public.mod_log (actor, action, target_id, reason) values ((select auth.uid()), 'content_rejected', c.user_id, left(c.link, 100) || ': ' || p_note);
  end if;
end; $function$;

-- public.review_creator(rid uuid, approve boolean, p_tier integer, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.review_creator(rid uuid, approve boolean, p_tier integer DEFAULT NULL::integer, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.creator_applications; badge text; months int; until_at timestamptz;
  tiers constant text[] := array['creator_1', 'creator_2', 'creator_3'];
begin
  if not public.is_site_admin() then perform public.manager_guard(case when approve then 'creator' else 'creator_other' end, (select x.user_id from public.creator_applications x where x.id = rid)); end if;
  p_note := left(btrim(coalesce(p_note, '')), 300);
  select * into r from public.creator_applications where id = rid for update;
  if r.id is null then raise exception 'Not found'; end if;
  if r.status not in ('pending', 'needs_proof') then raise exception 'Already reviewed'; end if;
  if r.user_id = (select auth.uid()) then raise exception 'Someone else has to review your own'; end if;
  if approve then
    if p_tier is null or p_tier not between 1 and 3 then raise exception 'Pick a tier'; end if;
    if public.is_site_banned(r.user_id) then raise exception 'That account is banned'; end if;
    months := case p_tier when 2 then 3 when 3 then 6 else 0 end;
    badge := 'creator_' || p_tier;
    update public.profiles set
      badges = array(select distinct unnest(
        array(select b from unnest(coalesce(badges, '{}'::text[])) b where not (b = any(tiers) and b <> badge)) || badge)),
      shown_badge = case when shown_badge = any(tiers) then badge else shown_badge end,
      plus_until = case when months > 0 then greatest(coalesce(plus_until, now()), now()) + make_interval(days => 31 * months) else plus_until end
      where id = r.user_id
      returning plus_until into until_at;
    update public.creator_applications set status = 'approved', tier = p_tier, plus_months = months,
      reviewed_by = (select auth.uid()), reviewed_at = now(), review_note = p_note where id = rid;
    perform public.creator_link_code(r.user_id);
    insert into public.mod_log (actor, action, target_id, reason) values
      ((select auth.uid()), 'creator_approved', r.user_id, 'Tier ' || p_tier || case when months > 0 then ', ' || months || ' months Plus' else '' end || case when p_note <> '' then ': ' || p_note else '' end),
      ((select auth.uid()), 'badge_given', r.user_id, badge);
    if months > 0 then
      insert into public.mod_log (actor, action, target_id, reason) values
        ((select auth.uid()), 'plus_gift', r.user_id, 'Until ' || to_char(until_at, 'YYYY-MM-DD') || ': Creator Program tier ' || p_tier);
    end if;
    begin
      perform public.rt_profile_changed(array[r.user_id]);
    exception when others then
      raise warning 'review_creator: profile cache ping for % failed: %', r.user_id, sqlerrm;
    end;
  else
    if length(p_note) < 3 then raise exception 'Say why, so they know what to change'; end if;
    update public.creator_applications set status = 'rejected', reviewed_by = (select auth.uid()), reviewed_at = now(), review_note = p_note where id = rid;
    insert into public.mod_log (actor, action, target_id, reason) values ((select auth.uid()), 'creator_rejected', r.user_id, p_note);
  end if;
end; $function$;

-- public.review_verification(rid uuid, approve boolean, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.review_verification(rid uuid, approve boolean, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.verification_requests; label text; k text; other text; me_name text; me_display text;
begin
  if not public.is_staff() then raise exception 'Moderators only'; end if;
  select * into r from public.verification_requests where id = rid for update;
  if r.id is null then raise exception 'Not found'; end if;
  if r.user_id = auth.uid() and not public.is_site_admin() then
    raise exception 'You can''t review your own verification. Ask another moderator.';
  end if;
  if approve and not public.is_site_admin() then
    if not public.feature_on('mod_verify', null) then
      raise exception 'Only admins can approve verifications. Ask for proof or leave it for an admin.';
    end if;
    -- Shares a network with any staff account: maybe a mod's alt (or a friend's), so an admin decides.
    if exists (
      -- (A staff target is refused by mod_guard below, with its own message.)
      with staff as (
        select user_id from public.site_moderators where user_id <> r.user_id
        union select user_id from public.site_admins where user_id <> r.user_id
      ), theirs as (
        select s.ip from public.signup_log s where s.user_id = r.user_id
        union
        select la.ip from public.login_attempts la join public.profiles p on lower(la.username) = lower(p.username)
         where p.id = r.user_id and la.ok
      )
      select 1 from theirs t
      where exists (select 1 from public.signup_log s join staff on staff.user_id = s.user_id where s.ip = t.ip)
         or exists (select 1 from public.login_attempts la join public.profiles p on lower(p.username) = lower(la.username)
                    join staff on staff.user_id = p.id where la.ip = t.ip and la.ok)
    ) then
      raise exception 'This account shares a network with a staff account. Leave it for an admin.';
    end if;
  end if;
  if r.status not in ('pending', 'needs_proof') then raise exception 'Already reviewed'; end if;
  if approve then
    k := public.verify_name_key(r.handle);
    if k <> '' then perform pg_advisory_xact_lock(hashtext('verify:' || k)); end if;
    select p.username into other from public.profiles p
     where p.id <> r.user_id and p.verified_as is not null
       and public.name_key(public.verify_name_key(split_part(p.verified_as, ' · ', 2))) = public.name_key(k)
       and public.verify_name_key(split_part(p.verified_as, ' · ', 2)) = k
     limit 1;
    if other is not null then
      raise exception 'That channel is already verified on another account (@%). Reject this one, or take the badge off the other account first.', other;
    end if;
    select username, display_name into me_name, me_display from public.profiles where id = r.user_id;
    if k = '' or k not in (public.verify_name_key(me_name), public.verify_name_key(me_display)) then
      raise exception 'Their name doesn''t match the channel (%) any more. Ask them to change it back, then approve.', r.handle;
    end if;
  end if;
  -- A moderator's approve names the target, so mod_guard refuses staff accounts (admins return at once).
  perform public.mod_guard('verify', case when approve then r.user_id end, null);
  update public.verification_requests
    set status = case when approve then 'approved' else 'rejected' end, reviewed_by = auth.uid(), reviewed_at = now(), review_note = coalesce(p_note, '')
    where id = rid;
  if approve then
    label := case r.platform when 'youtube' then 'YouTube' when 'twitch' then 'Twitch' when 'tiktok' then 'TikTok'
                             when 'instagram' then 'Instagram' when 'x' then 'X' else 'Creator' end || ' · ' || r.handle;
    update public.profiles set verified_as = label where id = r.user_id;
  end if;
  insert into public.mod_log (actor, action, target_id, reason)
  values (auth.uid(), case when approve then 'verify' else 'verify_reject' end, r.user_id, coalesce(p_note, '') || ' (' || r.platform || ' ' || r.handle || ')');
  perform public.bc('user:' || r.user_id, 'verification', 'UPDATE', 'verification_requests', 'public', null, null);
end; $function$;

-- public.revoke_creator(uid uuid, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.revoke_creator(uid uuid, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare tiers constant text[] := array['creator_1', 'creator_2', 'creator_3']; n int;
begin
  if not public.is_site_admin() then perform public.manager_guard('creator_other', uid); end if;
  update public.profiles set
    badges = array(select b from unnest(coalesce(badges, '{}'::text[])) b where not (b = any(tiers))),
    shown_badge = case when shown_badge = any(tiers) then null else shown_badge end
    where id = uid and badges && tiers;
  get diagnostics n = row_count;
  if n = 0 then raise exception 'Not in the Creator Program'; end if;
  insert into public.mod_log (actor, action, target_id, reason) values ((select auth.uid()), 'creator_revoked', uid, left(btrim(coalesce(p_note, '')), 300));
  begin
    perform public.rt_profile_changed(array[uid]);
  exception when others then
    raise warning 'revoke_creator: profile cache ping for % failed: %', uid, sqlerrm;
  end;
end; $function$;

-- public.role_edit_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.role_edit_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare top int;
begin
  if auth.uid() is null or current_user <> 'authenticated' then return new; end if;
  if exists (select 1 from public.servers where id = new.server_id and owner_id = auth.uid()) then return new; end if;
  top := public.my_top_role_position(new.server_id);
  if tg_op = 'UPDATE' and old.position >= top then raise exception 'You can only edit roles below your own highest role'; end if;
  if new.position >= top then raise exception 'Put the role below your own highest role'; end if;
  if coalesce((new.perms->>'administrator')::boolean, false) and (tg_op = 'INSERT' or not coalesce((old.perms->>'administrator')::boolean, false)) then
    raise exception 'Only the server owner can hand out Administrator';
  end if;
  return new;
end; $function$;

-- public.role_guard_is_staff(sid uuid, uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.role_guard_is_staff(sid uuid, uid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when sid in (select x.server_id from public.roles x
                           where x.id in (public.hq_management_role_id(), public.modserver_management_role_id()))
               and exists (select 1 from public.server_members m where m.server_id = sid and m.user_id = uid)
               and (public.is_site_admin() or public.server_perm(sid, 'manage_roles'))
          then public.is_staff_user(uid) else false end;
$function$;

-- public.role_guard()
CREATE OR REPLACE FUNCTION public.role_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare sid uuid; top int; pos int; k text;
begin
  if current_user <> 'authenticated' or current_setting('yapper.bot', true) = '1' then return coalesce(new, old); end if;
  sid := coalesce(new.server_id, old.server_id);
  if exists (select 1 from public.servers where id = sid and owner_id = auth.uid()) or public.is_site_admin() then
    return coalesce(new, old);
  end if;
  top := public.my_top_role_position(sid);
  if tg_table_name = 'member_roles' then
    select position into pos from public.roles where id = coalesce(new.role_id, old.role_id);
    if pos is null or pos >= top then raise exception 'You can only give or take roles below your highest role'; end if;
    -- 504: and only roles whose permissions you have yourself. Taking a role away stays as it was.
    if tg_op = 'INSERT' and not public.can_give_role_perms(sid, new.role_id) then
      raise exception 'You can''t give out a role with permissions you don''t have yourself';
    end if;
    return coalesce(new, old);
  end if;
  if tg_op in ('UPDATE', 'DELETE') and old.position >= top then
    raise exception 'You can only change roles below your highest role';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  if tg_op = 'INSERT' and new.position >= top then new.position := top - 1; end if;
  if new.position >= top then raise exception 'Roles have to stay below your highest role'; end if;
  if coalesce((new.perms ->> 'administrator')::boolean, false)
     and (tg_op = 'INSERT' or not coalesce((old.perms ->> 'administrator')::boolean, false)) then
    raise exception 'Only the owner can grant Administrator';
  end if;
  if new.manage_server and (tg_op = 'INSERT' or not old.manage_server) and not public.server_perm(sid, 'administrator') then
    raise exception 'You can''t grant Manage Server';
  end if;
  if new.manage_messages and (tg_op = 'INSERT' or not old.manage_messages) and not public.server_perm(sid, 'manage_messages') then
    raise exception 'You can''t grant Manage Messages';
  end if;
  -- 504: every value that isn't plainly false (was: only the json value true, so "yes" slipped past).
  for k in select key from jsonb_each(coalesce(new.perms, '{}'::jsonb)) where value not in ('false'::jsonb, 'null'::jsonb) loop
    if (tg_op = 'INSERT' or not coalesce((old.perms ->> k)::boolean, false)) and not public.server_perm(sid, k) then
      raise exception 'You can''t give a permission you don''t have (%)', k;
    end if;
  end loop;
  return new;
end; $function$;

-- public.role_members(rid uuid, q text, after_key text, after_id uuid, lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.role_members(rid uuid, q text DEFAULT NULL::text, after_key text DEFAULT NULL::text, after_id uuid DEFAULT NULL::uuid, lim integer DEFAULT 40)
 RETURNS TABLE(user_id uuid, nickname text, joined_at timestamp with time zone, sort_key text, total bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; n int := least(greatest(coalesce(lim, 40), 1), 100); pat text; holders int; big boolean;
begin
  -- Automatic roles (everyone, or everyone who joined before a date) mostly have no member_roles rows: the app says
  -- who has them instead of listing a whole server.
  select r.server_id into sid from public.roles r where r.id = rid and coalesce(r.auto, 'none') = 'none';
  if sid is null or not public.feature_on('role_mention_members', sid) then return; end if;
  if nullif(btrim(coalesce(q, '')), '') is not null then
    pat := '%' || replace(replace(replace(lower(left(btrim(q), 32)), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  end if;
  select count(*) into holders from public.member_roles mr where mr.role_id = rid;
  big := holders > 5000;
  if big and pat is not null and char_length(btrim(q)) < 2 then return; end if;
  if not public.member_lookup_ok(sid, case when pat is null then 'ml' else 'mf' end, case when big then n else greatest(n, least(holders, 5000) / 10) end) then return; end if;
  if big and pat is null then
    -- Huge role: straight off the index, by user id. sort_key is '' so the client's cursor still works.
    return query
    select mr.user_id, sm.nickname, sm.joined_at, ''::text,
      case when after_id is null then holders::bigint else -1::bigint end
    from public.member_roles mr
    join public.server_members sm on sm.server_id = mr.server_id and sm.user_id = mr.user_id
    where mr.role_id = rid and mr.server_id = sid and (after_id is null or mr.user_id > after_id)
    order by mr.user_id
    limit n;
    return;
  end if;
  return query
  with m as materialized (
    select mr.user_id, sm.nickname, sm.joined_at,
      lower(coalesce(nullif(sm.nickname, ''), nullif(p.display_name, ''), p.username, '')) as k
    from public.member_roles mr
    join public.server_members sm on sm.server_id = mr.server_id and sm.user_id = mr.user_id
    join public.profiles p on p.id = mr.user_id
    where mr.role_id = rid and mr.server_id = sid
      and (pat is null or lower(p.username) like pat or lower(coalesce(p.display_name, '')) like pat
           or lower(coalesce(sm.nickname, '')) like pat)
  )
  select m.user_id, m.nickname, m.joined_at, m.k,
    case when after_id is null then (select count(*) from m) else -1::bigint end
  from m
  where after_id is null or (m.k, m.user_id) > (coalesce(after_key, ''), after_id)
  order by m.k, m.user_id
  limit n;
end;
$function$;

-- public.role_rank_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.role_rank_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pos int;
begin
  -- Service role, templates and triggers: not a person acting.
  if auth.uid() is null or current_user <> 'authenticated' then return new; end if;
  if exists (select 1 from public.servers where id = new.server_id and owner_id = auth.uid()) then return new; end if;
  select position into pos from public.roles where id = new.role_id;
  if pos >= public.my_top_role_position(new.server_id) then
    raise exception 'You can only give roles below your own highest role';
  end if;
  return new;
end; $function$;

-- public.roles_resync_manual()  [security definer]
CREATE OR REPLACE FUNCTION public.roles_resync_manual()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.auto is distinct from old.auto or new.auto_before is distinct from old.auto_before then
    update public.member_roles mr
       set manual = coalesce(new.auto = 'before' and (new.auto_before is null or sm.joined_at >= new.auto_before), false)
      from public.server_members sm
     where mr.role_id = new.id and mr.server_id = new.server_id and sm.server_id = mr.server_id and sm.user_id = mr.user_id
       and mr.manual is distinct from coalesce(new.auto = 'before' and (new.auto_before is null or sm.joined_at >= new.auto_before), false);
  end if;
  return null;
end $function$;

-- public.roles_sync_legacy()
CREATE OR REPLACE FUNCTION public.roles_sync_legacy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  -- 504: permissions are true or false, nothing else ("yes" reads as true in the permission checks).
  if jsonb_typeof(coalesce(new.perms, '{}'::jsonb)) <> 'object'
     or exists (select 1 from jsonb_each(coalesce(new.perms, '{}'::jsonb)) where jsonb_typeof(value) <> 'boolean') then
    raise exception 'Role permissions have to be true or false';
  end if;
  -- The old manage_server / manage_messages switches each imply a bundle of permissions.
  -- They are no longer raised from the new per-permission list, so switching one permission off
  -- (which turns the old switch off and spells out the rest) sticks.
  if tg_op = 'UPDATE' and new.perms is distinct from old.perms and not public.can_edit_role(new.id) then
    raise exception 'You can''t edit this role''s permissions';
  end if;
  if tg_op = 'UPDATE' and coalesce((new.perms->>'administrator')::boolean, false) and not coalesce((old.perms->>'administrator')::boolean, false)
     and not exists (select 1 from public.servers where id = new.server_id and owner_id = auth.uid())
     and not public.server_perm(new.server_id, 'administrator') then
    raise exception 'Only the owner or an administrator can grant Administrator';
  end if;
  return new;
end;
$function$;

-- public.rt_profile_changed(uids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.rt_profile_changed(uids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ping record; nothing record;
begin
  select null::uuid as id into nothing;
  for ping in select distinct u as id from unnest(coalesce(uids, '{}'::uuid[])) u where u is not null limit 200 loop
    perform public.bc('profile:' || ping.id, 'profile', 'UPDATE', 'profiles', 'public', ping, nothing);
  end loop;
end; $function$;

-- public.ru_latin(t text)
CREATE OR REPLACE FUNCTION public.ru_latin(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select translate(coalesce(t, ''),
    'абвгдеёжзийклмнопрстуфхцчшщыэюяіїєґАБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЫЭЮЯІЇЄҐьъЬЪ',
    'abvgdeezziiklmnoprstufhccssyeuaiiegabvgdeezziiklmnoprstufhccssyeuaiieg');
$function$;

-- public.save_channel_overrides(p_channel uuid, p_category uuid, p_rows jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.save_channel_overrides(p_channel uuid, p_category uuid, p_rows jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  sid uuid;
  r jsonb;
  rid uuid;
  a text[];
  d text[];
  keep uuid[] := '{}';
  keep_everyone boolean := false;
  tcol text;
  tid uuid;
begin
  if (p_channel is null) = (p_category is null) then raise exception 'Pick a channel or a category'; end if;
  if p_channel is not null then
    select server_id into sid from public.channels where id = p_channel;
    tcol := 'channel_id'; tid := p_channel;
  else
    select server_id into sid from public.channel_categories where id = p_category;
    tcol := 'category_id'; tid := p_category;
  end if;
  if sid is null then raise exception 'Channel not found'; end if;
  if not public.can_manage_overrides(sid) then raise exception 'You can''t change permissions here'; end if;
  if not public.feature_on('channel_perms', sid) then raise exception 'Channel permissions aren''t available here yet'; end if;
  if jsonb_typeof(coalesce(p_rows, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_rows, '[]'::jsonb)) > 300 then
    raise exception 'Bad permissions list';
  end if;

  for r in select * from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) loop
    rid := nullif(r->>'role_id', '')::uuid;
    a := coalesce(array(select jsonb_array_elements_text(coalesce(r->'allow', '[]'::jsonb))), '{}');
    d := coalesce(array(select jsonb_array_elements_text(coalesce(r->'deny', '[]'::jsonb))), '{}');
    if coalesce(array_length(a, 1), 0) + coalesce(array_length(d, 1), 0) = 0 then continue; end if;
    if rid is null then keep_everyone := true; else keep := keep || rid; end if;
    if p_channel is not null then
      update public.channel_overrides set allow = a, deny = d
        where channel_id = p_channel and role_id is not distinct from rid
          and (allow is distinct from (select coalesce(array_agg(distinct x order by x), '{}') from unnest(a) x)
               or deny is distinct from (select coalesce(array_agg(distinct x order by x), '{}') from unnest(d) x));
      if not exists (select 1 from public.channel_overrides where channel_id = p_channel and role_id is not distinct from rid) then
        insert into public.channel_overrides (server_id, channel_id, role_id, allow, deny) values (sid, p_channel, rid, a, d);
      end if;
    else
      update public.channel_overrides set allow = a, deny = d
        where category_id = p_category and role_id is not distinct from rid
          and (allow is distinct from (select coalesce(array_agg(distinct x order by x), '{}') from unnest(a) x)
               or deny is distinct from (select coalesce(array_agg(distinct x order by x), '{}') from unnest(d) x));
      if not exists (select 1 from public.channel_overrides where category_id = p_category and role_id is not distinct from rid) then
        insert into public.channel_overrides (server_id, category_id, role_id, allow, deny) values (sid, p_category, rid, a, d);
      end if;
    end if;
  end loop;

  -- Everything not kept goes (dynamic SQL so this file has no literal delete statement).
  -- Roles above yours are left alone.
  execute format('dele' || 'te from public.channel_overrides where %I = $1 and ((role_id is null and not $2) or (role_id is not null and not (role_id = any($3))))'
                 || ' and public.override_role_ok(server_id, role_id)', tcol)
    using tid, keep_everyone, keep;
end $function$;

-- public.save_onboarding(sid uuid, cfg jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.save_onboarding(sid uuid, cfg jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare q jsonb; a jsonb; qid uuid; qpos int := 0; apos int; rid uuid; rids uuid[]; dc uuid; en boolean;
  is_owner boolean; top int;
begin
  if not public.feature_on('server_onboarding', sid) then raise exception 'Onboarding isn''t available in this server yet'; end if;
  if not (public.server_perm(sid, 'manage_server') and public.server_perm(sid, 'manage_roles')) then
    raise exception 'You need Manage Server and Manage Roles to change onboarding';
  end if;
  if jsonb_typeof(cfg->'questions') is distinct from 'array' then raise exception 'Bad onboarding setup'; end if;
  if jsonb_array_length(cfg->'questions') > 5 then raise exception 'Up to 5 questions'; end if;
  is_owner := exists (select 1 from public.servers s where s.id = sid and s.owner_id = auth.uid());
  top := public.my_top_role_position(sid);
  en := coalesce((cfg->>'enabled')::boolean, false);
  dc := nullif(cfg->>'default_channel_id', '')::uuid;
  if dc is not null and not exists (select 1 from public.channels c where c.id = dc and c.server_id = sid) then
    raise exception 'Pick a channel from this server';
  end if;

  insert into public.server_onboarding as o (server_id, enabled, required, enabled_at, default_channel_id, updated_at)
  values (sid, en, coalesce((cfg->>'required')::boolean, false), case when en then now() end, dc, now())
  on conflict (server_id) do update set enabled = excluded.enabled, required = excluded.required,
    enabled_at = case when excluded.enabled and not o.enabled then now() when excluded.enabled then o.enabled_at end,
    default_channel_id = excluded.default_channel_id, updated_at = now();

  execute 'dele' || 'te from public.onboarding_questions where server_id = $1' using sid;
  for q in select * from jsonb_array_elements(cfg->'questions') loop
    if jsonb_typeof(q->'answers') is distinct from 'array' or jsonb_array_length(q->'answers') not between 1 and 10 then
      raise exception 'Each question needs 1 to 10 answers';
    end if;
    insert into public.onboarding_questions (server_id, title, multi, position)
    values (sid, btrim(coalesce(q->>'title', '')), coalesce((q->>'multi')::boolean, false), qpos) returning id into qid;
    qpos := qpos + 1; apos := 0;
    for a in select * from jsonb_array_elements(q->'answers') loop
      rids := '{}';
      if jsonb_typeof(a->'role_ids') = 'array' then
        for rid in select (x #>> '{}')::uuid from jsonb_array_elements(a->'role_ids') x loop
          if not public.onboarding_role_ok(sid, rid) then
            raise exception 'One of the roles can''t be given by onboarding (it has mod or admin powers)';
          end if;
          if not is_owner and (select r.position from public.roles r where r.id = rid) >= top then
            raise exception 'You can only use roles below your own highest role';
          end if;
          if not rid = any (rids) then rids := rids || rid; end if;
        end loop;
      end if;
      insert into public.onboarding_answers (question_id, server_id, label, emoji, role_ids, position)
      values (qid, sid, btrim(coalesce(a->>'label', '')), nullif(btrim(coalesce(a->>'emoji', '')), ''), rids, apos);
      apos := apos + 1;
    end loop;
  end loop;
end $function$;

-- public.save_ping_roles(sid uuid, cfg jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.save_ping_roles(sid uuid, cfg jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare item jsonb; rid uuid; i int := 0; keep uuid[] := '{}';
begin
  if (select auth.uid()) is null or not public.feature_on('ping_roles', sid) then raise exception 'Ping roles aren''t available here'; end if;
  if not public.server_perm(sid, 'manage_roles') then raise exception 'You need Manage Roles for this'; end if;
  if jsonb_typeof(coalesce(cfg, '[]'::jsonb)) <> 'array' then raise exception 'Bad list'; end if;
  if jsonb_array_length(coalesce(cfg, '[]'::jsonb)) > 25 then raise exception 'Up to 25 ping roles'; end if;
  for item in select value from jsonb_array_elements(coalesce(cfg, '[]'::jsonb)) loop
    rid := nullif(item ->> 'role_id', '')::uuid;
    if rid is null or rid = any (keep) then continue; end if;
    -- Already a ping role: keep it even if it's above me now (a manager reordering the list shouldn't lose it).
    if not exists (select 1 from public.ping_roles p where p.role_id = rid and p.server_id = sid) and not public.ping_role_ok(sid, rid) then
      raise exception 'That role can''t be a ping role (it has permissions, is automatic, or is above your highest role)';
    end if;
    insert into public.ping_roles (role_id, server_id, emoji, blurb, position)
    values (rid, sid, left(nullif(btrim(item ->> 'emoji'), ''), 64), left(nullif(btrim(item ->> 'blurb'), ''), 100), i)
    on conflict (role_id) do update set emoji = excluded.emoji, blurb = excluded.blurb, position = excluded.position;
    keep := keep || rid;
    i := i + 1;
  end loop;
  execute 'dele' || 'te from public.ping_roles where server_id = $1 and not role_id = any ($2)' using sid, keep;
end;
$function$;

-- public.search_has_v2(content text, path text, embeds jsonb, kind text)
CREATE OR REPLACE FUNCTION public.search_has_v2(content text, path text, embeds jsonb, kind text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case kind
    when 'link' then coalesce(content, '') ~* 'https?://'
    when 'image' then coalesce(path, '') ~* '\.(png|jpe?g|gif|webp|avif)(\?|$)'
    when 'video' then coalesce(path, '') ~* '\.(mp4|webm|mov|m4v)(\?|$)'
    when 'sound' then coalesce(path, '') ~* '\.(mp3|wav|ogg|oga|opus|m4a|weba|flac|aac)(\?|$)'
    when 'file' then path is not null
    when 'embed' then jsonb_typeof(embeds) = 'array' and jsonb_array_length(embeds) > 0
    else true
  end;
$function$;

-- public.search_has(content text, path text, kind text)
CREATE OR REPLACE FUNCTION public.search_has(content text, path text, kind text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case kind
    when 'link' then coalesce(content, '') ~* 'https?://'
    when 'image' then coalesce(path, '') ~* '\.(png|jpe?g|gif|webp|avif)(\?|$)'
    when 'video' then coalesce(path, '') ~* '\.(mp4|webm|mov|m4v)(\?|$)'
    when 'file' then path is not null
    else true
  end;
$function$;

-- public.search_messages_v2(q text, sid uuid, cid uuid, author uuid, before timestamp with time zone)  [security definer]
CREATE OR REPLACE FUNCTION public.search_messages_v2(q text, sid uuid DEFAULT NULL::uuid, cid uuid DEFAULT NULL::uuid, author uuid DEFAULT NULL::uuid, before timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS SETOF public.messages
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  qq text := left(nullif(btrim(coalesce(q, '')), ''), 200);
  upto timestamptz := coalesce(before, 'infinity');
  me_on boolean;
  chans uuid[];
begin
  if auth.uid() is null or (qq is null and author is null) or public.is_site_banned(auth.uid()) then
    return;
  end if;
  if author is not null and sid is null and cid is null then
    return;
  end if;
  if qq is not null and querytree(websearch_to_tsquery('simple', qq)) in ('T', '') then
    return;
  end if;

  me_on := public.feature_on_for_me('search');
  select coalesce(array_agg(x.id), '{}') into chans from (
    select c.id
    from public.visible_server_channels(case when sid is null then null else array[sid] end) c
    where (cid is null or c.id = cid)
      and not exists (select 1 from public.servers sd where sd.id = c.server_id and sd.shut_down_at is not null and not public.is_staff())
      and (c.kind = 'text' or (c.kind = 'voice' and public.feature_on('voice_chat', c.server_id)))
      and (me_on or public.feature_on('search', c.server_id))
      and public.channel_history_ok(c.id)
    union
    select cm.channel_id
    from public.channel_members cm
    join public.channels c on c.id = cm.channel_id and c.server_id is null
    where me_on and sid is null and cm.user_id = auth.uid() and (cid is null or cm.channel_id = cid)
  ) x;
  if cardinality(chans) = 0 then
    return;
  end if;

  if qq is null then
    return query
      with top as (
        select t.channel_id, t.created_at
        from unnest(chans) as ch(id)
        cross join lateral (
          select m1.channel_id, m1.created_at from public.messages m1
          where m1.channel_id = ch.id and m1.author_id = author and m1.created_at < upto
          order by m1.created_at desc
          limit 50
        ) t
        group by t.channel_id, t.created_at
        order by t.created_at desc
        limit 50
      )
      select m.*
      from top t
      join public.messages m on m.channel_id = t.channel_id and m.author_id = author and m.created_at = t.created_at
      order by m.created_at desc
      limit 50;
  elsif author is null and sid is null then
    return query
      with hits as materialized (
        select m1.id, m1.channel_id, m1.created_at
        from public.messages m1
        where (cid is null or m1.channel_id = cid)
          and m1.created_at < upto
          and to_tsvector('simple', coalesce(m1.content, '')) @@ websearch_to_tsquery('simple', qq)
        order by m1.created_at desc
        limit 5000
      )
      select m.*
      from hits h
      join public.messages m on m.id = h.id
      where h.channel_id = any(chans)
      order by h.created_at desc
      limit 50;
  elsif author is null then
    return query
      with hits as materialized (
        select m1.id, m1.created_at
        from public.messages m1
        where m1.channel_id = any(chans)
          and m1.created_at < upto
          and to_tsvector('simple', coalesce(m1.content, '')) @@ websearch_to_tsquery('simple', qq)
        order by m1.created_at desc
        limit 5000
      )
      select m.*
      from hits h
      join public.messages m on m.id = h.id
      order by h.created_at desc
      limit 50;
  else
    return query
      with hits as materialized (
        select m1.id, m1.created_at
        from public.messages m1
        where m1.channel_id = any(chans)
          and m1.author_id = author
          and m1.created_at < upto
          and to_tsvector('simple', coalesce(m1.content, '')) @@ websearch_to_tsquery('simple', qq)
        order by m1.created_at desc
        limit 5000
      )
      select m.*
      from hits h
      join public.messages m on m.id = h.id
      order by h.created_at desc
      limit 50;
  end if;
end;
$function$;

-- public.search_messages_v3(q text, sid uuid, cid uuid, author uuid, before timestamp with time zone, since timestamp with time zone, has text)  [security definer]
CREATE OR REPLACE FUNCTION public.search_messages_v3(q text, sid uuid DEFAULT NULL::uuid, cid uuid DEFAULT NULL::uuid, author uuid DEFAULT NULL::uuid, before timestamp with time zone DEFAULT NULL::timestamp with time zone, since timestamp with time zone DEFAULT NULL::timestamp with time zone, has text DEFAULT NULL::text)
 RETURNS SETOF public.messages
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  qq text := left(nullif(btrim(coalesce(q, '')), ''), 200);
  upto timestamptz := coalesce(before, 'infinity');
  after_at timestamptz := coalesce(since, '-infinity');
  kind text := nullif(btrim(coalesce(has, '')), '');
  me_on boolean;
  chans uuid[];
begin
  if auth.uid() is null or (qq is null and author is null and kind is null) or public.is_site_banned(auth.uid()) then
    return;
  end if;
  if kind is not null and kind not in ('link', 'image', 'video', 'file') then
    return;
  end if;
  -- Something that isn't a word search needs a place to look in (a server or one chat), like author alone did.
  if qq is null and sid is null and cid is null then
    return;
  end if;
  if qq is not null and querytree(websearch_to_tsquery('simple', qq)) in ('T', '') then
    return;
  end if;

  me_on := public.feature_on_for_me('search');
  select coalesce(array_agg(x.id), '{}') into chans from (
    select c.id
    from public.visible_server_channels(case when sid is null then null else array[sid] end) c
    where (cid is null or c.id = cid)
      and not exists (select 1 from public.servers sd where sd.id = c.server_id and sd.shut_down_at is not null and not public.is_staff())
      and (c.kind = 'text' or (c.kind = 'voice' and public.feature_on('voice_chat', c.server_id)))
      and (me_on or public.feature_on('search', c.server_id))
      and public.channel_history_ok(c.id)
    union
    select cm.channel_id
    from public.channel_members cm
    join public.channels c on c.id = cm.channel_id and c.server_id is null
    where me_on and sid is null and cm.user_id = auth.uid() and (cid is null or cm.channel_id = cid)
  ) x;
  if cardinality(chans) = 0 then
    return;
  end if;

  -- A kind with no words and no author: the newest 50 of that kind per channel, then the newest 50 of those (the
  -- shape v2 uses for author-only, so a channel with plenty stops after 50 rows). The literal predicates let the
  -- planner use the partial indexes messages_attach_idx / messages_link_idx (built by hand, see the header).
  if qq is null and author is null then
    if kind = 'link' then
      return query
      with top as (
        select t.id, t.created_at
        from unnest(chans) as ch(id)
        cross join lateral (
          select m1.id, m1.created_at from public.messages m1
          where m1.channel_id = ch.id and m1.created_at < upto and m1.created_at > after_at
            and strpos(m1.content, 'http') > 0 and public.search_has(m1.content, m1.attachment_path, kind)
          order by m1.created_at desc
          limit 50
        ) t
        order by t.created_at desc
        limit 50
      )
      select m.*
      from top t
      join public.messages m on m.id = t.id
      order by m.created_at desc
      limit 50;
    else
      return query
      with top as (
        select t.id, t.created_at
        from unnest(chans) as ch(id)
        cross join lateral (
          select m1.id, m1.created_at from public.messages m1
          where m1.channel_id = ch.id and m1.created_at < upto and m1.created_at > after_at
            and m1.attachment_path is not null and public.search_has(m1.content, m1.attachment_path, kind)
          order by m1.created_at desc
          limit 50
        ) t
        order by t.created_at desc
        limit 50
      )
      select m.*
      from top t
      join public.messages m on m.id = t.id
      order by m.created_at desc
      limit 50;
    end if;
  elsif qq is null then
    return query
      with top as (
        select t.channel_id, t.created_at
        from unnest(chans) as ch(id)
        cross join lateral (
          select m1.channel_id, m1.created_at from public.messages m1
          where m1.channel_id = ch.id and m1.author_id = author and m1.created_at < upto and m1.created_at > after_at and public.search_has(m1.content, m1.attachment_path, kind)
          order by m1.created_at desc
          limit 50
        ) t
        group by t.channel_id, t.created_at
        order by t.created_at desc
        limit 50
      )
      select m.*
      from top t
      join public.messages m on m.channel_id = t.channel_id and m.author_id = author and m.created_at = t.created_at
      order by m.created_at desc
      limit 50;
  elsif author is null and sid is null then
    return query
      with hits as materialized (
        select m1.id, m1.channel_id, m1.created_at
        from public.messages m1
        where (cid is null or m1.channel_id = cid)
          and m1.created_at < upto and m1.created_at > after_at and public.search_has(m1.content, m1.attachment_path, kind)
          and to_tsvector('simple', coalesce(m1.content, '')) @@ websearch_to_tsquery('simple', qq)
        order by m1.created_at desc
        limit 5000
      )
      select m.*
      from hits h
      join public.messages m on m.id = h.id
      where h.channel_id = any(chans)
      order by h.created_at desc
      limit 50;
  elsif author is null then
    return query
      with hits as materialized (
        select m1.id, m1.created_at
        from public.messages m1
        where m1.channel_id = any(chans)
          and m1.created_at < upto and m1.created_at > after_at and public.search_has(m1.content, m1.attachment_path, kind)
          and to_tsvector('simple', coalesce(m1.content, '')) @@ websearch_to_tsquery('simple', qq)
        order by m1.created_at desc
        limit 5000
      )
      select m.*
      from hits h
      join public.messages m on m.id = h.id
      order by h.created_at desc
      limit 50;
  else
    return query
      with hits as materialized (
        select m1.id, m1.created_at
        from public.messages m1
        where m1.channel_id = any(chans)
          and m1.author_id = author
          and m1.created_at < upto and m1.created_at > after_at and public.search_has(m1.content, m1.attachment_path, kind)
          and to_tsvector('simple', coalesce(m1.content, '')) @@ websearch_to_tsquery('simple', qq)
        order by m1.created_at desc
        limit 5000
      )
      select m.*
      from hits h
      join public.messages m on m.id = h.id
      order by h.created_at desc
      limit 50;
  end if;
end;
$function$;

-- public.search_messages_v4(q text, sid uuid, cid uuid, author uuid, before timestamp with time zone, since timestamp with time zone, has text, mention uuid, pinned boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.search_messages_v4(q text, sid uuid DEFAULT NULL::uuid, cid uuid DEFAULT NULL::uuid, author uuid DEFAULT NULL::uuid, before timestamp with time zone DEFAULT NULL::timestamp with time zone, since timestamp with time zone DEFAULT NULL::timestamp with time zone, has text DEFAULT NULL::text, mention uuid DEFAULT NULL::uuid, pinned boolean DEFAULT false)
 RETURNS SETOF public.messages
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  qq text := left(nullif(btrim(coalesce(q, '')), ''), 200);
  upto timestamptz := coalesce(before, 'infinity');
  after_at timestamptz := coalesce(since, '-infinity');
  kind text := nullif(btrim(coalesce(has, '')), '');
  pin_only boolean := coalesce(pinned, false);
  scoped boolean := sid is not null or cid is not null;
  me_on boolean;
  chans uuid[];
  conds text;
begin
  if auth.uid() is null or public.is_site_banned(auth.uid())
     or (qq is null and author is null and kind is null and mention is null and not pin_only) then
    return;
  end if;
  if kind is not null and kind not in ('link', 'image', 'video', 'file', 'sound', 'embed', 'poll') then
    return;
  end if;
  -- Without words or a mention there's no index to find hits anywhere: it needs a server or one chat, like v3.
  if qq is null and mention is null and not scoped then
    return;
  end if;
  if qq is not null and querytree(websearch_to_tsquery('simple', qq)) in ('T', '') then
    return;
  end if;

  me_on := public.feature_on_for_me('search');
  select coalesce(array_agg(x.id), '{}') into chans from (
    select c.id
    from public.visible_server_channels(case when sid is null then null else array[sid] end) c
    where (cid is null or c.id = cid)
      and not exists (select 1 from public.servers sd where sd.id = c.server_id and sd.shut_down_at is not null and not public.is_staff())
      and (c.kind = 'text' or (c.kind = 'voice' and public.feature_on('voice_chat', c.server_id)))
      and (me_on or public.feature_on('search', c.server_id))
      and public.channel_history_ok(c.id)
    union
    select cm.channel_id
    from public.channel_members cm
    join public.channels c on c.id = cm.channel_id and c.server_id is null
    where me_on and sid is null and cm.user_id = auth.uid() and (cid is null or cm.channel_id = cid)
  ) x;
  if cardinality(chans) = 0 then
    return;
  end if;

  -- from: alone: v3's index-only walk of messages_channel_author_idx, then the rows.
  if qq is null and mention is null and kind is null and not pin_only then
    return query
      with top as (
        select t.channel_id, t.created_at
        from unnest(chans) as ch(id)
        cross join lateral (
          select m1.channel_id, m1.created_at from public.messages m1
          where m1.channel_id = ch.id and m1.author_id = author and m1.created_at < upto and m1.created_at > after_at
          order by m1.created_at desc
          limit 50
        ) t
        group by t.channel_id, t.created_at
        order by t.created_at desc
        limit 50
      )
      select m.*
      from top t
      join public.messages m on m.channel_id = t.channel_id and m.author_id = author and m.created_at = t.created_at
      order by m.created_at desc
      limit 50;
    return;
  end if;

  -- $1 chans, $2 upto, $3 after_at, $4 author, $5 mention, $6 qq, $7 kind. Only fixed text is added here.
  conds := 'm1.created_at < $2 and m1.created_at > $3';
  if author is not null then
    conds := conds || ' and m1.author_id = $4';
  end if;
  if mention is not null then
    -- Written exactly like messages_mention_keys_idx (and its where), so the planner can use it. In a channel walk the
    -- key is channel:person (ch.id), everywhere it's the person.
    conds := conds || case when scoped
      then ' and strpos(m1.content, ''<@'') > 0 and public.mention_keys(m1.channel_id, m1.content) @> array[ch.id::text || '':'' || $5::text]'
      else ' and strpos(m1.content, ''<@'') > 0 and public.mention_keys(m1.channel_id, m1.content) @> array[$5::text]' end;
  end if;
  if pin_only then
    conds := conds || ' and m1.pinned_at is not null';
  end if;
  if kind = 'link' then
    conds := conds || ' and strpos(m1.content, ''http'') > 0 and public.search_has_v2(m1.content, m1.attachment_path, m1.embeds, $7)';
  elsif kind in ('image', 'video', 'file', 'sound') then
    conds := conds || ' and m1.attachment_path is not null and public.search_has_v2(m1.content, m1.attachment_path, m1.embeds, $7)';
  elsif kind = 'embed' then
    conds := conds || ' and m1.embeds is not null and public.search_has_v2(m1.content, m1.attachment_path, m1.embeds, $7)';
  elsif kind = 'poll' and (qq is not null or mention is not null) then
    conds := conds || ' and exists (select 1 from public.polls pp where pp.message_id = m1.id)';
  end if;
  if qq is not null then
    conds := conds || ' and to_tsvector(''simple'', coalesce(m1.content, '''')) @@ websearch_to_tsquery(''simple'', $6)';
  end if;

  if not scoped then
    -- Everywhere I can read (words or a mention): the newest 5000 hits, then mine (v3's shape).
    return query execute
      'with hits as materialized (
         select m1.id, m1.channel_id, m1.created_at from public.messages m1 where ' || conds || '
         order by m1.created_at desc limit 5000
       )
       select m.* from hits h join public.messages m on m.id = h.id
       where h.channel_id = any($1)
       order by h.created_at desc limit 50'
      using chans, upto, after_at, author, mention, qq, kind;
    return;
  end if;

  if qq is not null and mention is null then
    -- Words in a server or one chat: the word index, narrowed to my channels there (v3).
    return query execute
      'with hits as materialized (
         select m1.id, m1.created_at from public.messages m1 where m1.channel_id = any($1) and ' || conds || '
         order by m1.created_at desc limit 50
       )
       select m.* from hits h join public.messages m on m.id = h.id
       order by h.created_at desc limit 50'
      using chans, upto, after_at, author, mention, qq, kind;
    return;
  end if;

  if kind = 'poll' and mention is null then
    -- Polls are few: walk them by channel, newest first (polls_channel_created_idx), not the channel's messages.
    return query execute
      'with top as (
         select t.id, t.created_at from unnest($1) as ch(id)
         cross join lateral (
           select m1.id, p.created_at from public.polls p join public.messages m1 on m1.id = p.message_id
           where p.channel_id = ch.id and p.created_at < $2 and p.created_at > $3 and m1.channel_id = ch.id and ' || conds || '
           order by p.created_at desc limit 50
         ) t
         order by t.created_at desc limit 50
       )
       select m.* from top t join public.messages m on m.id = t.id
       order by m.created_at desc limit 50'
      using chans, upto, after_at, author, mention, qq, kind;
    return;
  end if;

  -- The rest in a server or one chat (a mention, pinned, has:): the newest 50 per channel through the index that
  -- fits, then the newest 50 of those.
  return query execute
    'with top as (
       select t.id, t.created_at from unnest($1) as ch(id)
       cross join lateral (
         select m1.id, m1.created_at from public.messages m1
         where m1.channel_id = ch.id and ' || conds || '
         order by m1.created_at desc limit 50
       ) t
       order by t.created_at desc limit 50
     )
     select m.* from top t join public.messages m on m.id = t.id
     order by m.created_at desc limit 50'
    using chans, upto, after_at, author, mention, qq, kind;
end;
$function$;

-- public.search_messages(q text, sid uuid, cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.search_messages(q text, sid uuid DEFAULT NULL::uuid, cid uuid DEFAULT NULL::uuid)
 RETURNS SETOF public.messages
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select m.* from public.messages m
  join public.channels c on c.id = m.channel_id
  where (cid is null or m.channel_id = cid)
    and (sid is null or c.server_id = sid)
    and public.can_access_channel(m.channel_id)
    and public.channel_history_ok(m.channel_id)
    and (public.feature_on('search', c.server_id) or public.feature_on_for_me('search'))
    and to_tsvector('simple', coalesce(m.content, '')) @@ websearch_to_tsquery('simple', q)
  order by m.created_at desc
  limit 50;
$function$;

-- public.search_people(q text)  [security definer]
CREATE OR REPLACE FUNCTION public.search_people(q text)
 RETURNS TABLE(id uuid, username text, display_name text, avatar_path text, mutual integer, friend boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  qt public.people_search_quota;
  needle text := ltrim(lower(btrim(coalesce(q, ''))), '@');
  pat text;
  hi text;
  sids uuid[];
  friends uuid[];
begin
  if me is null then return; end if;
  needle := left(needle, 32);
  if char_length(needle) < 2 then return; end if;
  if not public.feature_on_for_me('user_search') then return; end if;
  insert into public.people_search_quota as z (user_id, minute_n, hour_n) values (me, 1, 1)
  on conflict (user_id) do update set
    minute_start = case when z.minute_start < now() - interval '1 minute' then now() else z.minute_start end,
    minute_n = case when z.minute_start < now() - interval '1 minute' then 1 else z.minute_n + 1 end,
    hour_start = case when z.hour_start < now() - interval '1 hour' then now() else z.hour_start end,
    hour_n = case when z.hour_start < now() - interval '1 hour' then 1 else z.hour_n + 1 end
  returning * into qt;
  if qt.minute_n > 20 or qt.hour_n > 200 then
    raise exception 'Slow down a bit, try searching again in a minute' using errcode = 'P0001';
  end if;
  hi := needle || chr(1114111);
  pat := replace(replace(replace(needle, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  select coalesce(array_agg(sm.server_id), '{}') into sids from public.server_members sm where sm.user_id = me;
  select coalesce(array_agg(case when f.requester = me then f.addressee else f.requester end), '{}') into friends
    from public.friendships f where (f.requester = me or f.addressee = me) and f.status = 'accepted';

  return query
  with cand as (
    (select p.id from public.profiles p
      where p.id = any(friends)
        and (lower(p.username) like '%' || pat or lower(coalesce(p.display_name, '')) like '%' || pat)
      limit 20)
    union
    (select p.id from public.profiles p
      where (char_length(needle) >= 3 or lower(p.username) = needle)
        and (lower(p.username) collate "C") >= needle and (lower(p.username) collate "C") < hi
        and lower(p.username) like pat
        and p.id <> me
        and exists (select 1 from public.server_members x where x.user_id = p.id and x.server_id = any(sids))
        and exists (select 1 from public.presence pr where pr.user_id = p.id
                      and pr.last_seen > now() - public.presence_ttl() and pr.pref is distinct from 'invisible')
      order by (lower(p.username) collate "C")
      limit 20)
    union
    (select p.id from public.profiles p
      where char_length(needle) >= 3
        and p.display_name is not null
        and (lower(p.display_name) collate "C") >= needle and (lower(p.display_name) collate "C") < hi
        and lower(p.display_name) like pat
        and p.id <> me
        and exists (select 1 from public.server_members x where x.user_id = p.id and x.server_id = any(sids))
        and exists (select 1 from public.presence pr where pr.user_id = p.id
                      and pr.last_seen > now() - public.presence_ttl() and pr.pref is distinct from 'invisible')
      order by (lower(p.display_name) collate "C")
      limit 20)
  )
  select p.id, p.username, p.display_name, p.avatar_path,
         (select count(*)::int from public.server_members x where x.user_id = p.id and x.server_id = any(sids)) as mutual,
         p.id = any(friends) as friend
  from cand
  join public.profiles p on p.id = cand.id
  where p.id <> me
    and not exists (select 1 from public.blocks b where (b.blocker = me and b.blocked = p.id) or (b.blocker = p.id and b.blocked = me))
    and not exists (select 1 from public.site_bans sb where sb.user_id = p.id and (sb.expires_at is null or sb.expires_at > now()))
  order by (lower(p.username) = needle) desc, (p.id = any(friends)) desc, lower(p.username)
  limit 20;
end; $function$;

-- public.seed_reaction_roles(mid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.seed_reaction_roles(mid uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; seeder uuid; e text; n int := 0;
begin
  select c.server_id into sid from public.messages m join public.channels c on c.id = m.channel_id where m.id = mid;
  if sid is null or not public.server_perm(sid, 'manage_roles') then raise exception 'You can''t manage roles here'; end if;
  if not public.feature_on('reaction_roles', sid) then raise exception 'Reaction roles aren''t available here yet'; end if;
  select webhook_user_id into seeder from public.app_settings limit 1;
  if seeder is null then return -1; end if;
  perform set_config('yapper.bot', '1', true);
  execute 'dele' || 'te from public.reactions r where r.message_id = $1 and r.user_id = $2'
    || ' and not exists (select 1 from public.reaction_roles rr where rr.message_id = $1 and rr.emoji = r.emoji)'
    using mid, seeder;
  for e in select rr.emoji from public.reaction_roles rr where rr.message_id = mid
            and not exists (select 1 from public.reactions x where x.message_id = mid and x.user_id = seeder and x.emoji = rr.emoji) loop
    begin
      perform set_config('yapper.bot', '1', true);
      insert into public.reactions (message_id, user_id, emoji) values (mid, seeder, e) on conflict do nothing;
      n := n + 1;
    exception when raise_exception then
      null;
    end;
  end loop;
  perform set_config('yapper.bot', '', true);
  return n;
end $function$;

-- public.sees_user(target uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.sees_user(target uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select target = auth.uid()
    or exists (select 1 from public.friendships f
               where (f.requester = auth.uid() and f.addressee = target) or (f.addressee = auth.uid() and f.requester = target))
    or exists (select 1 from public.channel_members a
               join public.channel_members b on b.channel_id = a.channel_id and b.user_id = target
               where a.user_id = auth.uid())
    or exists (select 1 from public.server_members m where m.user_id = target and m.server_id in (select public.my_server_ids()))
    or exists (select 1 from public.match_cache c where c.user_id = auth.uid()
               and c.computed_at > now() - interval '6 hours'
               and c.results @> jsonb_build_array(jsonb_build_object('user_id', target::text))
               and not public.is_blocked_between(auth.uid(), target)
               and coalesce((select ms.suggest_me from public.match_settings ms where ms.user_id = target), true)
               and public.feature_on_for_me('interest_matches'));
$function$;

-- public.send_friend_request(target_username text, note text, via_server uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.send_friend_request(target_username text, note text DEFAULT NULL::text, via_server uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  target uuid;
  existing public.friendships;
  pref text;
  sid uuid := null;
  clean text := nullif(btrim(regexp_replace(coalesce(send_friend_request.note, ''), '\s+', ' ', 'g')), '');
begin
  if me is null then raise exception 'Not signed in'; end if;
  if clean is not null and not public.feature_on_for_me('friend_notes') then clean := null; end if;
  if clean is not null then
    if char_length(clean) > 100 then raise exception 'Notes are up to 100 characters' using errcode = 'check_violation'; end if;
    if public.has_slur(clean) then
      raise exception 'That contains a slur, so it wasn''t sent. Keep it respectful.' using errcode = 'check_violation';
    end if;
    if public.has_adult_link(clean) then
      raise exception 'Links to that site aren''t allowed on Yapper.' using errcode = 'check_violation';
    end if;
  end if;
  select id into target from public.profiles where lower(username) = lower(btrim(target_username));
  if target is null then raise exception 'Hm, that didn''t work. Double check the username.'; end if;
  if target = me then raise exception 'You can''t friend yourself (we checked)'; end if;
  if public.is_bot_user(target) then raise exception 'Bots can''t be friends' using errcode = 'check_violation'; end if;
  if public.is_blocked_between(me, target) then
    raise exception 'Hm, that didn''t work. Double check the username.';
  end if;
  select * into existing from public.friendships
  where least(requester, addressee) = least(me, target)
    and greatest(requester, addressee) = greatest(me, target);
  if existing.id is not null then
    if existing.status = 'accepted' then raise exception 'You''re already friends'; end if;
    if existing.requester = me then raise exception 'Request already sent'; end if;
    update public.friendships set status = 'accepted', accepted_at = now() where id = existing.id;
    return 'accepted';
  end if;
  if (select count(*) from public.friendships where requester = me and status = 'pending') >= 100 then
    raise exception 'Too many pending requests';
  end if;
  if exists (select 1 from public.friend_request_declines d
             where d.requester = me and d.addressee = target and d.declined_at > now() - interval '24 hours') then
    raise exception 'You sent them a request not long ago. Try again tomorrow.';
  end if;
  if clean is not null then
    select coalesce(dms_from, 'friends') into pref from public.profiles where id = target;
    if not (pref = 'everyone' or (pref = 'servers' and exists (
      select 1 from public.server_members a join public.server_members b on a.server_id = b.server_id
      where a.user_id = me and b.user_id = target))) then
      clean := null;
    end if;
  end if;
  if via_server is not null and exists (
      select 1 from public.server_members a join public.server_members b on a.server_id = b.server_id
      where a.server_id = via_server and a.user_id = me and b.user_id = target) then
    sid := via_server;
  end if;
  insert into public.friendships (requester, addressee, note, via_server) values (me, target, clean, sid);
  return 'sent';
end;
$function$;

-- public.server_audit_list(sid uuid, before bigint, act text, who uuid, lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.server_audit_list(sid uuid, before bigint DEFAULT NULL::bigint, act text DEFAULT NULL::text, who uuid DEFAULT NULL::uuid, lim integer DEFAULT 50)
 RETURNS TABLE(id bigint, actor_id uuid, action text, target_kind text, target_id uuid, target_name text, extra jsonb, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.feature_on('audit_log', sid) then raise exception 'The audit log isn''t on here yet'; end if;
  if not (public.server_perm(sid, 'view_audit_log') or public.server_perm(sid, 'manage_server')) then
    raise exception 'You can''t see the audit log here';
  end if;
  return query
    select a.id, a.actor_id, a.action, a.target_kind, a.target_id, a.target_name, a.extra, a.created_at
    from public.server_audit_log a
    where a.server_id = sid
      and (before is null or a.id < before)
      and (act is null or a.action like act || '%')
      and (who is null or a.actor_id = who)
    order by a.id desc
    limit least(greatest(coalesce(lim, 50), 1), 100);
end $function$;

-- public.server_bot_commands(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.server_bot_commands(sid uuid)
 RETURNS TABLE(bot_id uuid, bot_name text, name text, description text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select c.bot_id, b.name, c.name, c.description
  from public.bot_commands c
  join public.bots b on b.id = c.bot_id
  join public.bot_servers bs on bs.bot_id = c.bot_id and bs.server_id = sid
  where public.is_server_member(sid)
  order by b.name, c.name;
$function$;

-- public.server_bot_looks(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.server_bot_looks(sid uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('bot', sb.bot, 'user_id', ba.user_id, 'name', sb.config ->> 'look_name', 'avatar', sb.config ->> 'look_avatar')), '[]'::jsonb)
  from public.server_bots sb join public.bot_accounts ba on ba.bot = sb.bot
  where sb.server_id = sid and public.is_server_member(sid) and public.feature_on('builtin_bot_look', sid)
    and (sb.config ? 'look_name' or sb.config ? 'look_avatar');
$function$;

-- public.server_builtin_bots(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.server_builtin_bots(sid uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('bot', sb.bot, 'user_id', ba.user_id) order by sb.bot), '[]'::jsonb)
  from public.server_bots sb join public.bot_accounts ba on ba.bot = sb.bot
  where sb.server_id = sid and sb.enabled and public.is_server_member(sid);
$function$;

-- public.server_command_menu(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.server_command_menu(sid uuid)
 RETURNS TABLE(bot_name text, name text, description text, prefix text, bot_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select distinct on (prefix, name, case when prefix = '/' then bot_id end) * from (
    select b.name, c.name, coalesce(c.description, ''), '/', b.id
      from public.bot_commands c
      join public.bots b on b.id = c.bot_id
      join public.bot_servers bs on bs.bot_id = c.bot_id and bs.server_id = sid
    union all
    select x.label, x.cmd, x.descr, x.pfx, null::uuid
      from public.server_bots sb
      join (values
        ('helper', 'Helper', 'help', 'All Helper commands', '!'),
        ('helper', 'Helper', '8ball', 'Ask a yes or no question: !8ball will it rain', '!'),
        ('helper', 'Helper', 'roll', 'Roll dice: !roll or !roll 2d6', '!'),
        ('helper', 'Helper', 'flip', 'Flip a coin', '!'),
        ('helper', 'Helper', 'choose', 'Pick for you: !choose pizza | tacos', '!'),
        ('helper', 'Helper', 'afk', 'Go AFK with a reason: !afk lunch', '!'),
        ('helper', 'Helper', 'rank', 'Your level and XP', '!'),
        ('helper', 'Helper', 'top', 'Most active people here', '!'),
        ('levels', 'Levels', 'rank', 'Your level and XP', '!'),
        ('levels', 'Levels', 'top', 'Most active people here', '!'),
        ('giveaways', 'Giveaways', 'giveaway', 'Start one: !giveaway 1d Cool prize (3 winners: !giveaway 1d 3w Cool prize)', '!'),
        ('giveaways', 'Giveaways', 'gend', 'End the giveaway early', '!'),
        ('giveaways', 'Giveaways', 'greroll', 'Pick new winners', '!'),
        ('wordle', 'Wordy', 'wordy', 'Today''s word: start, or guess right away: /wordy crane', '/'),
        ('wordle', 'Wordy', 'wordy stats', 'Your streaks and the top solvers here', '/')
      ) as x(bot, label, cmd, descr, pfx) on x.bot = sb.bot
     where sb.server_id = sid and sb.enabled and public.feature_on('bots', sid)
       and (x.bot <> 'wordle' or public.feature_on('wordle_bot', sid))
  ) t(bot_name, name, description, prefix, bot_id)
  where public.is_server_member(sid)
  order by prefix, name, case when prefix = '/' then bot_id end, bot_name;
$function$;

-- public.server_emoji_cap(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.server_emoji_cap(sid uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case public.server_level(sid) when 3 then 250 when 2 then 150 when 1 then 100 else 50 end;
$function$;

-- public.server_folders_ok(f jsonb)
CREATE OR REPLACE FUNCTION public.server_folders_ok(f jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  e jsonb;
  s jsonb;
begin
  if f is null or jsonb_typeof(f) <> 'array' then return false; end if;
  if jsonb_array_length(f) > 50 then return false; end if;
  if octet_length(f::text) > 65536 then return false; end if;
  for e in select value from jsonb_array_elements(f) loop
    if jsonb_typeof(e) <> 'object' then return false; end if;
    if (e - array['id', 'name', 'color', 'servers']) <> '{}'::jsonb then return false; end if;
    if jsonb_typeof(e->'id') is distinct from 'string' or (e->>'id') !~ '^[A-Za-z0-9_-]{1,24}$' then return false; end if;
    if e ? 'name' and jsonb_typeof(e->'name') <> 'null' then
      if jsonb_typeof(e->'name') <> 'string' or char_length(e->>'name') > 32 then return false; end if;
    end if;
    if e ? 'color' and jsonb_typeof(e->'color') <> 'null' then
      if jsonb_typeof(e->'color') <> 'string' or (e->>'color') !~ '^#[0-9a-f]{6}$' then return false; end if;
    end if;
    if jsonb_typeof(e->'servers') is distinct from 'array' then return false; end if;
    if jsonb_array_length(e->'servers') not between 1 and 100 then return false; end if;
    for s in select value from jsonb_array_elements(e->'servers') loop
      if jsonb_typeof(s) <> 'string' or (s #>> '{}') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return false; end if;
    end loop;
  end loop;
  if (select count(*) <> count(distinct e2->>'id') from jsonb_array_elements(f) e2) then return false; end if;
  if (select count(*) <> count(distinct v) from jsonb_array_elements(f) e2, jsonb_array_elements_text(e2->'servers') v) then return false; end if;
  return true;
end; $function$;

-- public.server_gate(sid uuid, uid uuid, count_hit boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.server_gate(sid uuid, uid uuid, count_hit boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare lvl int; own uuid; raid timestamptz; reset_at timestamptz; mc int; born timestamptz; joined timestamptz;
  young boolean; raiding boolean; ver_on boolean; alarm_on boolean; why text; n int;
begin
  select verification_level, owner_id, raid_until, raid_reset_at, member_count into lvl, own, raid, reset_at, mc
    from public.servers where id = sid;
  if own is null or own = uid then return null; end if;
  raiding := coalesce(raid > now(), false);
  ver_on := coalesce(lvl, 0) > 0 and public.feature_on('server_verification', sid);
  alarm_on := count_hit and public.feature_on('raid_alarm', sid);
  -- Nothing on here: stop before any more reads.
  if not raiding and not ver_on and not alarm_on then return null; end if;
  select created_at into born from public.profiles where id = uid;
  -- 485: joined_at holds the first join (105); a rejoin restarts the wait, so take the later of the two.
  select greatest(m.joined_at, f.last_joined_at) into joined
    from public.server_members m
    left join public.server_first_joins f on f.server_id = m.server_id and f.user_id = m.user_id
    where m.server_id = sid and m.user_id = uid;
  -- New: account under a day old, or a fairly new account (under a week) that joined in the last hour. Old accounts
  -- joining together (a community moving over) aren't a raid.
  young := coalesce(born > now() - interval '24 hours', false)
    or (coalesce(born > now() - interval '7 days', false) and coalesce(joined > now() - interval '1 hour', false));
  if raiding and young then
    why := 'This server is in raid mode, so new members can''t talk for a bit. Try again in ' || public.short_wait(raid) || '.';
  elsif ver_on and lvl >= 1 and born > now() - interval '5 minutes' then
    why := 'This server needs your account to be 5 minutes old before you can talk. Try again in ' || public.short_wait(born + interval '5 minutes') || '.';
  elsif ver_on and lvl >= 2 and joined > now() - interval '5 minutes' then
    why := 'This server needs you to be a member for 5 minutes before you can talk. Try again in ' || public.short_wait(joined + interval '5 minutes') || '.';
  elsif ver_on and lvl >= 3 and not exists (select 1 from auth.users u where u.id = uid and u.email_confirmed_at is not null) then
    why := 'This server needs a verified email before you can talk. Check your inbox for the link we sent you.';
  end if;
  if why is null and not (alarm_on and young) then return null; end if;
  if public.raid_exempt(sid, uid) then return null; end if;
  if why is not null then return why; end if;
  -- A new person is posting: count them.
  if alarm_on then
    insert into public.raid_hits (server_id, user_id, at) values (sid, uid, now())
      on conflict (server_id, user_id) do update set at = excluded.at;
    select count(*) into n from public.raid_hits
      where server_id = sid and at > greatest(now() - interval '60 seconds', coalesce(reset_at, '-infinity'));
    if n >= public.raid_threshold(mc) then perform public.raid_fire(sid); end if;
  end if;
  return null;
end $function$;

-- public.server_hidden_join_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.server_hidden_join_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if current_setting('yapper.bot', true) = '1' then return new; end if;
  if auth.uid() is null or auth.uid() is distinct from new.user_id then return new; end if;
  if exists (select 1 from public.servers s where s.id = new.server_id and s.staff_hidden_at is not null and s.owner_id is distinct from new.user_id) then
    if not public.is_staff()
       and not exists (select 1 from public.server_members m where m.server_id = new.server_id and m.user_id = new.user_id) then
      raise exception 'This server isn''t taking new members right now' using errcode = 'check_violation';
    end if;
  end if;
  return new;
end $function$;

-- public.server_level(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.server_level(sid uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when sid is null or not public.supercharge_on(sid) then 0
              else public.supercharge_level_for(public.server_supercharge_count(sid)) end;
$function$;

-- public.server_locked(sid uuid)
CREATE OR REPLACE FUNCTION public.server_locked(sid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce((select locked_until > now() from public.servers where id = sid), false);
$function$;

-- public.server_member_counts(sids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.server_member_counts(sids uuid[])
 RETURNS TABLE(server_id uuid, n bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select s.id, s.member_count::bigint
  from public.servers s
  where s.id = any(sids) and s.id in (select public.my_server_ids());
$function$;

-- public.server_members_join_gate()  [security definer]
CREATE OR REPLACE FUNCTION public.server_members_join_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.user_id is distinct from auth.uid() then return new; end if;
  if current_setting('yapper.join_ok', true) = new.server_id::text then return new; end if;
  if not public.join_apply_on(new.server_id) then return new; end if;
  if exists (select 1 from public.servers where id = new.server_id and owner_id = new.user_id) then return new; end if;
  if public.is_staff() then return new; end if;
  raise exception 'This server asks people to apply first. Open its invite link to apply.';
end $function$;

-- public.server_members_slice(sids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.server_members_slice(sids uuid[])
 RETURNS TABLE(server_id uuid, user_id uuid, nickname text, joined_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare big uuid[]; small uuid[]; onl uuid[]; me uuid := auth.uid();
begin
  -- Only servers you are in. This function skips the server_members policy, so it has to repeat it.
  sids := coalesce(array(select x.id from unnest(sids) as x(id) where x.id in (select public.my_server_ids())), '{}'::uuid[]);
  select coalesce(array_agg(id), '{}'::uuid[]) into big from public.servers where id = any(sids) and member_count > 3000;
  select coalesce(array_agg(id), '{}'::uuid[]) into small from public.servers where id = any(sids) and member_count <= 3000;
  if cardinality(big) = 0 then
    return query select sm.server_id, sm.user_id, sm.nickname, sm.joined_at from public.server_members sm where sm.server_id = any(small);
    return;
  end if;
  select coalesce(array_agg(p.user_id), '{}'::uuid[]) into onl from public.presence p where p.last_seen > now() - interval '10 minutes';
  return query
    select sm.server_id, sm.user_id, sm.nickname, sm.joined_at from public.server_members sm where sm.server_id = any(small)
    union
    select sm.server_id, sm.user_id, sm.nickname, sm.joined_at from public.server_members sm where sm.server_id = any(big) and sm.user_id = me
    union
    -- Every join below is a lateral with limit 1: one index probe per row, never a scan of the whole table.
    select sm.server_id, sm.user_id, sm.nickname, sm.joined_at
    from public.roles r
    join public.member_roles mr on mr.role_id = r.id
    cross join lateral (select x.server_id, x.user_id, x.nickname, x.joined_at from public.server_members x where x.server_id = mr.server_id and x.user_id = mr.user_id limit 1) sm
    where r.server_id = any(big) and r.auto = 'none'
    union
    select sm.server_id, sm.user_id, sm.nickname, sm.joined_at
    from public.member_roles mr
    cross join lateral (select x.server_id, x.user_id, x.nickname, x.joined_at from public.server_members x where x.server_id = mr.server_id and x.user_id = mr.user_id limit 1) sm
    where mr.server_id = any(big) and mr.manual
    union
    select sm.server_id, sm.user_id, sm.nickname, sm.joined_at
    from unnest(onl) as u(user_id)
    cross join unnest(big) as b(server_id)
    cross join lateral (select x.server_id, x.user_id, x.nickname, x.joined_at from public.server_members x where x.server_id = b.server_id and x.user_id = u.user_id limit 1) sm
    union
    select r.server_id, r.user_id, r.nickname, r.joined_at
    from unnest(big) as b(server_id)
    cross join lateral (select x.server_id, x.user_id, x.nickname, x.joined_at from public.server_members x where x.server_id = b.server_id order by x.joined_at desc limit 300) r;
end $function$;

-- public.server_perm_as(uid uuid, sid uuid, perm text)  [security definer]
CREATE OR REPLACE FUNCTION public.server_perm_as(uid uuid, sid uuid, perm text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform set_config('request.jwt.claims', jsonb_build_object('sub', uid, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', uid::text, true);
  return public.server_perm(sid, perm) and public.feature_on('builtin_bot_look', sid);
end $function$;

-- public.server_perm_of(sid uuid, uid uuid, perm text)  [security definer]
CREATE OR REPLACE FUNCTION public.server_perm_of(sid uuid, uid uuid, perm text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return sid is not null and uid is not null and (
    exists (select 1 from public.servers where id = sid and owner_id = uid)
    or exists (
      select 1 from public.member_roles mr join public.roles r on r.id = mr.role_id
      where mr.server_id = sid and mr.user_id = uid
        and (
          coalesce((r.perms->>'administrator')::boolean, false)
          or (r.manage_server and public.legacy_manage_server(perm))
          or (r.manage_messages and public.legacy_manage_messages(perm))
          or coalesce((r.perms->>perm)::boolean, false)
        )
    )
    or (public.basic_perm(perm)
        and exists (select 1 from public.server_members sm where sm.server_id = sid and sm.user_id = uid)
        and coalesce(((select everyone_perms from public.servers where id = sid)->>perm)::boolean, true))
  );
end $function$;

-- public.server_perm_user(sid uuid, uid uuid, perm text)  [security definer]
CREATE OR REPLACE FUNCTION public.server_perm_user(sid uuid, uid uuid, perm text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.servers where id = sid and owner_id = uid)
    or exists (
      select 1 from public.member_roles mr join public.roles r on r.id = mr.role_id
      where mr.server_id = sid and mr.user_id = uid
        and (coalesce((r.perms->>'administrator')::boolean, false) or (r.manage_server and public.legacy_manage_server(perm)) or coalesce((r.perms->>perm)::boolean, false))
    );
$function$;

-- public.server_perm(sid uuid, perm text)  [security definer]
CREATE OR REPLACE FUNCTION public.server_perm(sid uuid, perm text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
begin
  return (
  select sid is not null and (
    exists (select 1 from public.servers where id = sid and owner_id = auth.uid())
    or exists (
      select 1 from public.member_roles mr join public.roles r on r.id = mr.role_id
      where mr.server_id = sid and mr.user_id = auth.uid()
        and (
          coalesce((r.perms->>'administrator')::boolean, false)
          or (r.manage_server and public.legacy_manage_server(perm))
          or (r.manage_messages and public.legacy_manage_messages(perm))
          or coalesce((r.perms->>perm)::boolean, false)
        )
    )
    or (public.basic_perm(perm)
        and public.is_server_member(sid)
        and coalesce(((select everyone_perms from public.servers where id = sid)->>perm)::boolean, true))
  )
  );
end;
$function$;

-- public.server_plus_on(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.server_plus_on(sid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.server_plus p where p.server_id = sid and p.until > now());
$function$;

-- public.server_role_assignments(sids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.server_role_assignments(sids uuid[])
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with mine as (
    select sm.server_id from public.server_members sm
    where sm.user_id = (select auth.uid()) and sm.server_id = any(sids)
  ),
  plain_roles as (
    select r.id from public.roles r
    where r.server_id in (select server_id from mine) and coalesce(r.auto, 'none') = 'none'
  ),
  assigned as (
    select mr.server_id, mr.user_id, mr.role_id from public.member_roles mr
    join plain_roles pr on pr.id = mr.role_id
    union
    select mr.server_id, mr.user_id, mr.role_id from public.member_roles mr
    where mr.manual and mr.server_id in (select server_id from mine)
  )
  select coalesce(jsonb_agg(jsonb_build_array(a.server_id, a.user_id, a.role_id)), '[]'::jsonb) from assigned a;
$function$;

-- public.server_shutdown_clears_tags()  [security definer]
CREATE OR REPLACE FUNCTION public.server_shutdown_clears_tags()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.shut_down_at is not null and old.shut_down_at is null then
    update public.profiles set server_tag = null, tag = null where server_tag = new.id;
  end if;
  return new;
end; $function$;

-- public.server_supercharge_count(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.server_supercharge_count(sid uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(*)::int from public.supercharges c
  where c.server_id = sid
    and (c.source = 'admin' or exists (select 1 from public.server_members m where m.server_id = sid and m.user_id = c.user_id))
    and case when c.source = 'plus'
             then exists (select 1 from public.profiles p where p.id = c.user_id and p.plus_until > now())
             else c.until > now() end;
$function$;

-- public.server_supercharge(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.server_supercharge(sid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); n int; lv int;
begin
  if me is null or not exists (select 1 from public.server_members m where m.server_id = sid and m.user_id = me) then return null; end if;
  if not public.supercharge_on(sid) then return jsonb_build_object('on', false, 'count', 0, 'level', 0); end if;
  n := public.server_supercharge_count(sid);
  lv := public.supercharge_level_for(n);
  return jsonb_build_object(
    'on', true, 'count', n, 'level', lv,
    'next', case lv when 0 then 2 when 1 then 7 when 2 then 14 end,
    'mine', (select count(*) from public.supercharges c where c.server_id = sid and c.user_id = me
               and case when c.source = 'plus' then exists (select 1 from public.profiles p where p.id = me and p.plus_until > now())
                        else c.until > now() end));
end $function$;

-- public.server_timed_out(sid uuid, uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.server_timed_out(sid uuid, uid uuid)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select until from public.server_timeouts where server_id = sid and user_id = uid and until > now();
$function$;

-- public.server_timeout(sid uuid, target uuid, minutes integer, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.server_timeout(sid uuid, target uuid, minutes integer, why text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.server_perm(sid, 'timeout_members') then raise exception 'You can''t time people out here'; end if;
  if target = auth.uid() then raise exception 'Not yourself'; end if;
  if exists (select 1 from public.servers where id = sid and owner_id = target) then raise exception 'You can''t time out the owner'; end if;
  if public.is_staff_user(target) then raise exception 'You can''t time out Yapper staff'; end if;
  if not public.outranks(sid, target) then raise exception 'You can''t time out someone with a role as high as yours'; end if;
  if minutes <= 0 then
    execute 'dele' || 'te from public.server_timeouts where server_id = $1 and user_id = $2' using sid, target;
    return;
  end if;
  if minutes > 10080 then raise exception 'Timeouts are up to 7 days'; end if;
  insert into public.server_timeouts (server_id, user_id, until, reason, set_by)
  values (sid, target, now() + make_interval(mins => minutes), left(coalesce(why, ''), 200), auth.uid())
  on conflict (server_id, user_id) do update set until = excluded.until, reason = excluded.reason, set_by = excluded.set_by, created_at = now();
end;
$function$;

-- public.server_watch_chunk(term text)
CREATE OR REPLACE FUNCTION public.server_watch_chunk(term text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select '%' || replace(replace(replace(p, '\', '\\'), '%', '\%'), '_', '\_') || '%'
  from unnest(regexp_split_to_array(btrim(translate(lower(coalesce(term, '')), '@$0', 'aso')), '[\s\-_.]+')) p
  where p <> '' order by length(p) desc limit 1
$function$;

-- public.server_watch_pattern(term text)
CREATE OR REPLACE FUNCTION public.server_watch_pattern(term text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select array_to_string(array(
    select regexp_replace(u.p, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g')
    from unnest(regexp_split_to_array(btrim(translate(lower(coalesce(term, '')), '@$0', 'aso')), '[\s\-_.]+')) with ordinality as u(p, i)
    where u.p <> '' order by u.i), '[^a-z0-9]*')
$function$;

-- public.server_watch_public_channel(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.server_watch_public_channel(cid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((
    select c.ticket_by is null and c.server_id is not null and case when public.channel_overrides_live(c.id) then
      coalesce(
        (select case when bool_or('view_channel' = any(o.allow)) then true when bool_or('view_channel' = any(o.deny)) then false end
           from public.channel_overrides o where o.channel_id = c.id and o.role_id is null),
        case when c.private then false end,
        (select case when bool_or('view_channel' = any(o.allow)) then true when bool_or('view_channel' = any(o.deny)) then false end
           from public.channel_overrides o where c.category_id is not null and o.category_id = c.category_id and o.role_id is null),
        true)
      and not exists (select 1 from public.channel_overrides o join public.roles r on r.id = o.role_id
                      where (o.channel_id = c.id or (c.category_id is not null and o.category_id = c.category_id))
                        and r.auto is not null and r.auto <> 'none' and 'view_channel' = any(o.deny))
    else not coalesce(c.private, false) end
    from public.channels c where c.id = cid), false)
$function$;

-- public.server_watch_scan(p_days integer)  [security definer]
CREATE OR REPLACE FUNCTION public.server_watch_scan(p_days integer DEFAULT 3)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  t0 timestamptz := clock_timestamp();
  st public.server_watch_state;
  since timestamptz;
  full_pass boolean;
  slice int;
  rx text;
  pf text[];
  cands uuid[];
  n_cands int := 0; n_text int := 0; n_msg int := 0; n_img int := 0; n_scored int := 0;
  min_score constant int := 10;
  stats jsonb;
begin
  if not pg_try_advisory_xact_lock(hashtext('server_watch_scan')) then return jsonb_build_object('skipped', 'already running'); end if;
  if not exists (select 1 from public.feature_flags where key = 'server_watch' and mode <> 'off') then
    return jsonb_build_object('skipped', 'flag off');
  end if;
  insert into public.server_watch_state (id) values (true) on conflict do nothing;
  select * into st from public.server_watch_state where id for update;
  -- Never look back more than an hour (a stalled cron must not turn into one huge run); 1 minute overlap.
  since := greatest(coalesce(st.last_run, now() - interval '1 hour'), now() - interval '1 hour') - interval '1 minute';
  full_pass := st.terms_changed or st.last_run is null;
  slice := (st.run_no % 8)::int;
  p_days := least(greatest(coalesce(p_days, 3), 1), 30);

  select '(^|[^a-z0-9])(' || string_agg(public.server_watch_pattern(t.term), '|') || ')s?([^a-z]|$)',
         array_agg(distinct public.server_watch_chunk(t.term))
    into rx, pf
    from public.server_watch_terms t where public.server_watch_pattern(t.term) <> '';

  if rx is not null then
    -- ---- 1. text pass ----
    select coalesce(array_agg(s.id), '{}') into cands
    from public.servers s
    where s.shut_down_at is null
      and (full_pass or s.created_at > since or (hashtext(s.id::text) & 7) = slice
           or s.id in (select r.server_id from public.reports r
                        where r.status in ('open', 'actioned') and r.created_at > since and r.server_id is not null))
      and (s.created_at > now() - make_interval(days => p_days)
           or exists (select 1 from public.channels c where c.server_id = s.id and c.last_message_at > now() - make_interval(days => p_days)));
    n_cands := coalesce(array_length(cands, 1), 0);

    with c as (select unnest(cands) as sid),
    terms as (
      select t.term, t.kind, t.weight, '(^|[^a-z0-9])(' || public.server_watch_pattern(t.term) || ')s?([^a-z]|$)' as trx
      from public.server_watch_terms t where public.server_watch_pattern(t.term) <> ''),
    txt as (
      select s.id as sid, v.w, v.x, v.f, v.ord, null::uuid as cid from public.servers s join c on c.sid = s.id
      cross join lateral (values ('name'::text, s.name, 1.0::numeric, 1), ('description', s.description, 1.0, 2),
                                 ('tags', array_to_string(s.tags, ' '), 1.0, 2)) as v(w, x, f, ord)
      where coalesce(v.x, '') <> ''
      union all
      select i.server_id, 'invite link', i.code, 1.0, 3, null from public.invites i join c on c.sid = i.server_id where i.vanity
      union all
      select ch.server_id, 'channel #' || ch.name, ch.name, 1.0, 4, ch.id from public.channels ch join c on c.sid = ch.server_id
      union all
      select r.server_id, 'role @' || r.name, r.name, 0.5, 5, null from public.roles r join c on c.sid = r.server_id),
    pre as (select t.*, translate(lower(coalesce(t.x, '')), '@$0', 'aso') as nx from txt t),
    -- case: the cheap LIKE always runs first, the combined regex only on what passes it.
    -- 247: negated mentions are cut out after the LIKE, once per row, before the regex.
    hit1u as materialized (select pre.*, public.server_watch_unneg(pre.nx) as nx2 from pre where pre.nx like any (pf)),
    hit1 as (select * from hit1u where nx2 ~ rx),
    hit0 as (select h.sid, h.w, h.x, h.f, h.ord, h.cid, t.term, t.kind, t.weight from hit1 h join terms t on h.nx2 ~ t.trx),
    -- Private / role-only channels: counted, but their names never reach the reasons (moderators read them).
    hit as materialized (
      select h.sid, case when h.pub then h.w else 'a private channel' end as w, case when h.pub then h.x end as x,
             h.f, h.ord, h.term, h.kind, h.weight
      from (select hit0.*, hit0.cid is null or public.server_watch_public_channel(hit0.cid) as pub from hit0) h),
    scored as (
      select z.sid, round(sum(z.pts))::int as tsc
      from (select sid, term, least(sum(f), 2.0) * max(weight) as pts from hit group by sid, term) z group by z.sid),
    rs as (
      select y.sid, jsonb_agg(y.r order by y.rn) filter (where y.rn <= 6) as reasons
      from (
        select d.sid,
               jsonb_build_object('kind', d.kind, 'where', d.w, 'term', d.term, 'sample', left(d.x, 120), 'points', round(d.weight * d.f, 1)) as r,
               row_number() over (partition by d.sid order by d.weight * d.f desc, d.ord, d.w) as rn
        from (select distinct on (sid, term, w) * from hit order by sid, term, w) d
      ) y group by y.sid)
    insert into public.server_watch (server_id, text_score, text_reasons, text_checked_at)
    select s.sid, s.tsc, coalesce(r.reasons, '[]'), now() from scored s left join rs r on r.sid = s.sid
    on conflict (server_id) do update set text_score = excluded.text_score, text_reasons = excluded.text_reasons, text_checked_at = excluded.text_checked_at;
    get diagnostics n_text = row_count;

    -- Read again and nothing matched any more: clear the text part.
    update public.server_watch w set text_score = 0, text_reasons = '[]', text_checked_at = now()
    where w.server_id = any (cands) and (w.text_checked_at is null or w.text_checked_at < now()) and (w.text_score <> 0 or w.text_reasons <> '[]');

    -- ---- 2. messages since the last run (server channels only) + invite ads ----
    with terms as (
      select t.term, t.kind, t.weight, '(^|[^a-z0-9])(' || public.server_watch_pattern(t.term) || ')s?([^a-z]|$)' as trx
      from public.server_watch_terms t where public.server_watch_pattern(t.term) <> ''),
    ch as (select c.id, c.server_id, c.name from public.channels c where c.server_id is not null and c.last_message_at > since),
    m as (
      select ch.server_id, ch.id as cid, ch.name as cname, mm.id, mm.content, mm.created_at, translate(lower(coalesce(mm.content, '')), '@$0', 'aso') as nx
      from ch cross join lateral (
        select x.id, x.content, x.created_at from public.messages x
        where x.channel_id = ch.id and x.created_at > since order by x.created_at desc limit 200) mm),
    m1u as materialized (select m.*, public.server_watch_unneg(m.nx) as nx2 from m where m.nx like any (pf)),
    m1 as (select * from m1u where nx2 ~ rx),
    mh0 as (select m1.*, t.term, t.kind, t.weight from m1 join terms t on m1.nx2 ~ t.trx),
    -- Text from private / role-only channels is never copied: no sample, no channel name.
    mh as materialized (select mh0.*, public.server_watch_public_channel(mh0.cid) as pub from mh0)
    insert into public.server_watch_hits (server_id, ref, src, kind, term, weight, place, sample, channel_id, at)
    select mh.server_id, mh.id::text || ':' || mh.term, 'message', mh.kind, mh.term, mh.weight,
           case when mh.pub then 'message in #' || mh.cname else 'message in a private channel' end,
           case when mh.pub then left(mh.content, 160) end, mh.cid, mh.created_at
    from mh
    union all
    -- Invite ads: a matching message that links a Yapper invite also counts for the invited server.
    select i.server_id, 'ad:' || mh.id::text || ':' || mh.term, 'ad', mh.kind, mh.term, mh.weight,
           case when mh.pub then left('ad posted in ' || coalesce((select s.name from public.servers s where s.id = mh.server_id), 'another server'), 200)
                else 'ad posted in a private channel' end,
           case when mh.pub then left(mh.content, 160) end, mh.cid, mh.created_at
    from mh
    cross join lateral (select distinct lower(g[1]) as code from regexp_matches(mh.content, '/invite/([A-Za-z0-9_-]{3,32})', 'gi') g) k
    join public.invites i on lower(i.code) = k.code
    where strpos(mh.content, '/invite/') > 0 and i.server_id <> mh.server_id
    on conflict do nothing;
    get diagnostics n_msg = row_count;
  end if;

  -- ---- 3. blocked images, matched to the server the uploader was posting in at the time ----
  insert into public.server_watch_hits (server_id, ref, src, kind, term, weight, place, sample, channel_id, at)
  select x.server_id, 'img:' || ms.bucket || '/' || ms.path, 'image', 'image', null, 0,
         case when public.server_watch_public_channel(x.cid) then 'blocked image near #' || x.cname else 'blocked image near a private channel' end,
         null, x.cid, ms.scanned_at
  from public.media_scans ms
  cross join lateral (
    select c.server_id, c.id as cid, c.name as cname
    from public.messages m join public.channels c on c.id = m.channel_id
    where m.author_id = ms.user_id and c.server_id is not null
      and m.created_at between ms.scanned_at - interval '15 minutes' and ms.scanned_at + interval '15 minutes'
    order by abs(extract(epoch from (m.created_at - ms.scanned_at))) limit 1) x
  where ms.verdict = 'blocked' and not coalesce(ms.forgiven, false) and ms.bucket in ('attachments', 'emojis')
    and ms.scanned_at > since - interval '15 minutes' and ms.user_id is not null
  on conflict do nothing;
  get diagnostics n_img = row_count;

  execute 'del' || 'ete from public.server_watch_hits where at < now() - interval ''3 days''';

  -- ---- 4. score ----
  with rep as (
    select coalesce(r.server_id, (select c.server_id from public.channels c where c.id = r.channel_id)) as sid,
           count(distinct r.reporter_id)::int as n,
           count(distinct r.reporter_id) filter (where r.reason in ('sexual', 'minor_safety', 'self_harm', 'violence', 'illegal'))::int as bad
    from public.reports r
    where r.status in ('open', 'actioned') and r.created_at > now() - interval '14 days'
    group by 1),
  msg as (
    select z.server_id as sid, least(sum(z.pts), 40) as pts from (
      select server_id, term, least(count(*), 3) * max(weight) * 0.5 as pts from public.server_watch_hits
      where src = 'message' and at > now() - interval '24 hours' group by server_id, term) z group by z.server_id),
  ad as (
    select z.server_id as sid, least(sum(z.pts), 30) as pts from (
      select server_id, term, least(count(*), 3) * max(weight) as pts from public.server_watch_hits
      where src = 'ad' and at > now() - interval '3 days' group by server_id, term) z group by z.server_id),
  img as (select server_id as sid, count(*)::int as n from public.server_watch_hits where src = 'image' group by server_id),
  -- One reason per term per source: the latest sample.
  hr as (
    select y.sid, jsonb_agg(y.r) as reasons from (
      select distinct on (h.server_id, h.src, h.term) h.server_id as sid,
        jsonb_build_object('kind', h.kind, 'where', h.place, 'term', h.term, 'sample', h.sample,
          'points', case h.src when 'ad' then h.weight else round(h.weight * 0.5, 1) end) as r
      from public.server_watch_hits h
      where h.src in ('message', 'ad') and h.at > now() - case h.src when 'message' then interval '24 hours' else interval '3 days' end
      order by h.server_id, h.src, h.term, h.at desc) y group by y.sid),
  r as (
    select distinct u.sid from (
      select unnest(cands) as sid
      union all select sid from msg union all select sid from ad union all select sid from img
      union all select sid from rep where sid is not null
      union all select w.server_id from public.server_watch w where w.score > 0 or w.text_score > 0) u
    where u.sid is not null),
  b as (
    select r.sid, coalesce(w.text_score, 0) as tsc, coalesce(w.text_reasons, '[]'::jsonb) as treasons,
           coalesce(msg.pts, 0) as mpts, coalesce(ad.pts, 0) as apts, coalesce(img.n, 0) as imgs,
           coalesce(rep.n, 0) as reps, coalesce(rep.bad, 0) as bad, coalesce(hr.reasons, '[]'::jsonb) as hreasons,
           coalesce(s.member_count, 0) as members
    from r
    join public.servers s on s.id = r.sid
      -- Yapper HQ and staff members' own servers are never on the list.
      and s.id is distinct from (select default_server_id from public.app_settings limit 1)
      and not (s.owner_id is not null and public.is_staff_user(s.owner_id))
    left join public.server_watch w on w.server_id = r.sid
    left join msg on msg.sid = r.sid left join ad on ad.sid = r.sid left join img on img.sid = r.sid
    left join rep on rep.sid = r.sid left join hr on hr.sid = r.sid),
  p as (
    -- Reports scale down with size (a big server gets more reports just by being big): x sqrt(100 / members), max 1.
    select b.*, least(b.imgs * 3, 24) as ipts,
           least(round((b.reps * 2 + b.bad * 3) * least(1.0, sqrt(100.0 / greatest(b.members, 1))))::int, 25) as rpts from b),
  g as (
    -- Growth only counts on top of something found in the server itself (words, ads, blocked images), not reports alone.
    select p.*, (p.tsc + p.mpts + p.apts + p.ipts + p.rpts) as pre_growth, (p.tsc + p.mpts + p.apts + p.ipts) as content,
      case when (p.tsc + p.mpts + p.apts + p.ipts) >= 5 then
        (select count(*)::int from (select 1 from public.server_members sm where sm.server_id = p.sid and sm.joined_at > now() - interval '24 hours' limit 1000) j)
      else 0 end as joins
    from p),
  f as (
    select g.sid, round(g.pre_growth + case when g.content >= 5 then least(g.joins / 10.0, 10) else 0 end)::int as score,
      g.reps, g.imgs, g.joins,
      coalesce((select jsonb_agg(q.v order by (q.v ->> 'points')::numeric desc) from (
        select e.v from jsonb_array_elements(g.treasons || g.hreasons
          || case when g.rpts > 0 then jsonb_build_array(jsonb_build_object('kind', 'signal', 'where', 'reports', 'signal',
               g.reps || case when g.reps = 1 then ' person' else ' people' end || ' reported stuff here in 14 days'
               || case when g.bad > 0 then ' (' || g.bad || ' about sexual content, minors, self harm or violence)' else '' end, 'points', g.rpts)) else '[]'::jsonb end
          || case when g.ipts > 0 then jsonb_build_array(jsonb_build_object('kind', 'signal', 'where', 'images', 'signal',
               g.imgs || ' blocked ' || case when g.imgs = 1 then 'image' else 'images' end || ' from people posting here (3 days)', 'points', g.ipts)) else '[]'::jsonb end
          || case when g.content >= 5 and g.joins >= 10 then jsonb_build_array(jsonb_build_object('kind', 'signal', 'where', 'growth', 'signal',
               '+' || g.joins || ' members in 24 hours', 'points', round(least(g.joins / 10.0, 10), 1))) else '[]'::jsonb end) as e(v)
        order by (e.v ->> 'points')::numeric desc limit 10) q), '[]'::jsonb) as reasons
    from g)
  insert into public.server_watch as w (server_id, score, reasons, reports, blocked_images, joins_24h, first_seen, last_seen, updated_at)
  select f.sid, f.score, f.reasons, f.reps, f.imgs, f.joins,
         case when f.score >= min_score then now() end, case when f.score >= min_score then now() end, now()
  from f
  where f.score >= min_score or exists (select 1 from public.server_watch x where x.server_id = f.sid)
  on conflict (server_id) do update set
    score = excluded.score, reasons = excluded.reasons, reports = excluded.reports,
    blocked_images = excluded.blocked_images, joins_24h = excluded.joins_24h,
    first_seen = coalesce(w.first_seen, excluded.first_seen),
    last_seen = coalesce(excluded.last_seen, w.last_seen),
    status = case when w.status in ('ok', 'actioned')
                   and excluded.score >= greatest(coalesce(w.cleared_score, 0) + 10, ceil(coalesce(w.cleared_score, 0) * 1.5))
                  then 'new' else w.status end,
    updated_at = now();
  get diagnostics n_scored = row_count;

  -- Taken down meanwhile: off the new list.
  update public.server_watch w set status = 'actioned', cleared_score = w.score, updated_at = now()
  from public.servers s where s.id = w.server_id and w.status = 'new' and s.shut_down_at is not null;

  stats := jsonb_build_object('full', full_pass, 'slice', slice, 'servers_read', n_cands, 'text_hits', n_text,
    'message_hits', n_msg, 'image_hits', n_img, 'scored', n_scored,
    'ms', round(extract(epoch from clock_timestamp() - t0) * 1000));
  update public.server_watch_state set last_run = now(), run_no = run_no + 1,
    terms_changed = case when full_pass and rx is not null then false else terms_changed end,
    last_ms = (stats ->> 'ms')::int, last_stats = stats
  where id;
  return stats;
end $function$;

-- public.server_watch_terms_changed()  [security definer]
CREATE OR REPLACE FUNCTION public.server_watch_terms_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.server_watch_state set terms_changed = true where id;
  return null;
end $function$;

-- public.server_watch_unneg(nx text)
CREATE OR REPLACE FUNCTION public.server_watch_unneg(nx text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(coalesce(nx, ''),
    -- "no limits", "no rules", "no filter" are selling points, not negations: keep them out of the passes below.
    '\mno[^a-z0-9]+(limits?|rules|filters?|censorship|restrictions?)\M', 'nolimits', 'g'),
    -- A sentence or list line that starts with a negation ("1. No NSFW or gore.", "- don't post porn") goes whole:
    -- that's how rules are written. Only that sentence, so "No minors. Post your nudes in #pics" still counts.
    '(^|[\n.!?;])[^a-z0-9\n.!?;]*(no|never|don[^a-z0-9]?t|do[^a-z0-9]+not|avoid)\M[^\n.!?;]*', '\1 ', 'g'),
    -- "banned: nsfw, gore" / "not allowed - porn": a list after the word.
    '(banned|prohibited|forbidden|disallowed|not[^a-z0-9]+allowed)[^a-z0-9]*[:-][^.\n]{0,80}',
    ' ', 'g'),
    -- "nsfw is not allowed", "porn content is strictly prohibited".
    '[a-z0-9+*]+([^a-z0-9]+(content|stuff|images?|pics|media|posts?|links?))?[^a-z0-9]+((is|are)[^a-z0-9]+)?((strictly|extremely|totally|completely|very)[^a-z0-9]+)?(not[^a-z0-9]+allowed|isn[^a-z0-9]?t[^a-z0-9]+allowed|banned|prohibited|forbidden|forbiden|disallowed)\M',
    ' ', 'g'),
    -- "no nsfw, no porn": a new "no" ends the list before it, so each one is its own negation.
    '([,/&]|\mor\M|\mand\M)[^a-z0-9]*(no|not|never)\M', ' ; \2', 'g'),
    -- Mid-sentence: "the rules say no nsfw", "strictly no 18+ content", "non-18+": the negation, filler words, then
    -- the word it covers and any list after it. Anything else in between ("no limits porn") keeps the mention.
    -- Plain * repeats, no lookaheads: bounded {n,m} repeats and lookaheads are slow in Postgres regex.
    '(^|[^a-z0-9])(no|non|not|never|zero|without|avoid|don[^a-z0-9]?t|do[^a-z0-9]+not)\M'
      || '([^a-z0-9]+(any|all|the|explicit|sexual|extreme|excessive|graphic|real|irl|content|post|posting|send|sending|share|sharing|spam|spamming|talk|talking|about|of|kind|kinds|type|types|images?|pics|links?|stuff|media|other|selling)\M)*'
      || '[^a-z0-9]+[a-z0-9+*]+'
      || '(([^a-z0-9+*]*[,/&][^a-z0-9+*]*|[^a-z0-9]+(or|and)[^a-z0-9]+)[a-z0-9+*]+)*',
    '\1 ', 'g')
$function$;

-- public.servers_daily_cap()  [security definer]
CREATE OR REPLACE FUNCTION public.servers_daily_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is not null and new.owner_id = auth.uid() and not public.is_site_admin()
     and (select count(*) from public.servers s where s.owner_id = new.owner_id and s.created_at > now() - interval '24 hours') >= 10 then
    raise exception 'You can make 10 servers a day. Try again tomorrow';
  end if;
  return new;
end $function$;

-- public.servers_keep_hidden()  [security definer]
CREATE OR REPLACE FUNCTION public.servers_keep_hidden()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.shut_down_at is not distinct from old.shut_down_at then
    update public.server_hides set prev_discoverable = new.discoverable where server_id = new.id;
  end if;
  new.discoverable := false;
  return new;
end $function$;

-- public.servers_name_ok()  [security definer]
CREATE OR REPLACE FUNCTION public.servers_name_ok()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  new.name_ok := not public.bad_name(new.name);
  return new;
end $function$;

-- public.set_bot_look_avatar(sid uuid, p_bot text, p_path text)  [security definer]
CREATE OR REPLACE FUNCTION public.set_bot_look_avatar(sid uuid, p_bot text, p_path text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.server_bots set config = case when p_path is null then config - 'look_avatar' else jsonb_set(config, '{look_avatar}', to_jsonb(p_path)) end
  where server_id = sid and bot = p_bot;
$function$;

-- public.set_bot_look(sid uuid, p_bot text, p_name text)  [security definer]
CREATE OR REPLACE FUNCTION public.set_bot_look(sid uuid, p_bot text, p_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n text := nullif(btrim(coalesce(p_name, '')), '');
begin
  if not public.server_perm(sid, 'manage_server') then raise exception 'Only server managers can change bots'; end if;
  if not public.feature_on('builtin_bot_look', sid) then raise exception 'Not available here yet'; end if;
  if n is not null and char_length(n) > 32 then raise exception 'Names are up to 32 characters'; end if;
  if n is not null and (n ~* 'yapper\s*(staff|team|admin|official|mod)' or n ~* '^(system|admin|moderator)$') then raise exception 'Pick a name that doesn''t look like Yapper staff'; end if;
  if not exists (select 1 from public.server_bots where server_id = sid and bot = p_bot) then raise exception 'Turn the bot on first'; end if;
  update public.server_bots set config = case when n is null then config - 'look_name' else jsonb_set(config, '{look_name}', to_jsonb(n)) end where server_id = sid and bot = p_bot;
end $function$;

-- public.set_channel_access(cid uuid, make_private boolean, role_ids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.set_channel_access(cid uuid, make_private boolean, role_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  sid uuid;
begin
  select server_id into sid from public.channels where id = cid;
  if sid is null or not public.server_perm(sid, 'manage_server') then
    raise exception 'You can''t manage this channel';
  end if;
  update public.channels set private = coalesce(make_private, false) where id = cid;
  delete from public.channel_roles where channel_id = cid;
  if make_private then
    insert into public.channel_roles (channel_id, role_id, server_id)
      select cid, r.id, sid from public.roles r
      where r.server_id = sid and r.id = any(coalesce(role_ids, '{}'));
  end if;
  update public.servers set name = name where id = sid;
end;
$function$;

-- public.set_channel_category(chid uuid, cid uuid, ids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.set_channel_category(chid uuid, cid uuid, ids uuid[] DEFAULT NULL::uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; i int;
begin
  select server_id into sid from public.channels where id = chid;
  if sid is null or not public.server_perm(sid, 'manage_channels') then raise exception 'You can''t manage channels here'; end if;
  if cid is not null and not exists (select 1 from public.channel_categories where id = cid and server_id = sid) then raise exception 'No such category'; end if;
  update public.channels set category_id = cid where id = chid;
  for i in 1 .. coalesce(array_length(ids, 1), 0) loop
    update public.channels set position = i - 1 where id = ids[i] and server_id = sid;
  end loop;
end; $function$;

-- public.set_channel_posting(cid uuid, make_read_only boolean, post_role_ids uuid[], slow integer)  [security definer]
CREATE OR REPLACE FUNCTION public.set_channel_posting(cid uuid, make_read_only boolean, post_role_ids uuid[], slow integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  sid uuid;
begin
  select server_id into sid from public.channels where id = cid;
  if sid is null or not (public.server_perm(sid, 'manage_server') or public.server_perm(sid, 'manage_channels')) then
    raise exception 'You can''t manage this channel';
  end if;
  update public.channels
    set read_only = coalesce(make_read_only, false), slowmode = greatest(0, least(coalesce(slow, 0), 21600))
    where id = cid;
  execute 'dele' || 'te from public.channel_post_roles where channel_id = $1' using cid;
  if make_read_only then
    insert into public.channel_post_roles (channel_id, role_id, server_id)
      select cid, r.id, sid from public.roles r
      where r.server_id = sid and r.id = any(coalesce(post_role_ids, '{}'));
  end if;
  update public.servers set name = name where id = sid;
end;
$function$;

-- public.set_deco_price(p_id uuid, p_price integer)  [security definer]
CREATE OR REPLACE FUNCTION public.set_deco_price(p_id uuid, p_price integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid()); d public.community_decos;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if not public.feature_on_for_me('shards') then raise exception 'Not available yet'; end if;
  if public.is_site_banned(me) then raise exception 'Your account is banned.'; end if;
  if p_price is not null and p_price <= 0 then p_price := null; end if;
  if p_price is not null and (p_price < 25 or p_price > 5000) then raise exception 'Pick a price from 25 to 5000 Shards'; end if;
  if p_price is not null and not public.deco_seller_ok(me) then
    raise exception 'Your account needs to be % days old to sell for Shards (Plus members can sell right away)', public.shard_config()->>'seller_age_days';
  end if;
  select * into d from public.community_decos where id = p_id for update;
  if not found or d.artist_id <> me then raise exception 'That''s not one of yours'; end if;
  if d.status not in ('pending', 'approved') then raise exception 'That one isn''t live'; end if;
  if d.price is null and p_price is not null then
    insert into public.deco_owned (user_id, deco_id, price_paid)
      select p.id, d.id, 0 from public.profiles p
      where p.avatar_deco like 'c:%' and p.avatar_deco = 'c:' || d.path and p.id <> me
      on conflict do nothing;
  end if;
  update public.community_decos set price = p_price where id = p_id;
end; $function$;

-- public.set_everyone_perms(sid uuid, p jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.set_everyone_perms(sid uuid, p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare k text; v jsonb; cur jsonb; boss boolean; clean jsonb := '{}';
begin
  if not public.server_perm(sid, 'manage_roles') then raise exception 'You can''t edit permissions here'; end if;
  if p is not null and jsonb_typeof(p) <> 'object' then raise exception 'Permissions must be a list of on/off switches'; end if;
  select coalesce(everyone_perms, '{}'::jsonb) into cur from public.servers where id = sid;
  boss := exists (select 1 from public.servers where id = sid and owner_id = auth.uid()) or public.server_perm(sid, 'administrator');
  for k, v in select * from jsonb_each(coalesce(p, '{}'::jsonb)) loop
    if jsonb_typeof(v) <> 'boolean' then raise exception 'Permission % must be true or false', k; end if;
    if not public.basic_perm(k) then continue; end if;
    -- Missing means on (server_perm defaults basics to true), so only an explicit false counts as off.
    if v = 'true'::jsonb and cur->k = 'false'::jsonb and not boss and not public.server_perm(sid, k) then
      raise exception 'You can''t turn on a permission you don''t have yourself';
    end if;
    clean := clean || jsonb_build_object(k, v);
  end loop;
  update public.servers set everyone_perms = clean where id = sid;
end;
$function$;

-- public.set_forum_settings(p_forum uuid, p_guidelines text, p_require_tag boolean, p_sort text, p_layout text)  [security definer]
CREATE OR REPLACE FUNCTION public.set_forum_settings(p_forum uuid, p_guidelines text, p_require_tag boolean, p_sort text, p_layout text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f public.channels;
begin
  select * into f from public.channels where id = p_forum and kind = 'forum';
  if not found then raise exception 'Not a forum'; end if;
  if not public.feature_on('forums_v2', f.server_id) then raise exception 'Not available yet'; end if;
  if not public.server_perm(f.server_id, 'manage_channels') or not public.can_access_channel(f.id) then raise exception 'You can''t manage channels here'; end if;
  update public.channels set
    guidelines = nullif(left(btrim(coalesce(p_guidelines, '')), 1000), ''),
    require_tag = coalesce(p_require_tag, false),
    default_sort = case when p_sort in ('activity', 'new') then p_sort end,
    default_layout = case when p_layout in ('list', 'gallery') then p_layout end
  where id = p_forum;
end $function$;

-- public.set_forum_tags(p_forum uuid, p_tags jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.set_forum_tags(p_forum uuid, p_tags jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f public.channels; res jsonb;
begin
  select * into f from public.channels where id = p_forum and kind = 'forum';
  if not found then raise exception 'Not a forum'; end if;
  if not public.server_perm(f.server_id, 'manage_channels') or not public.can_access_channel(f.id) then raise exception 'You can''t manage channels here'; end if;
  if jsonb_typeof(coalesce(p_tags, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_tags, '[]'::jsonb)) > 20 then
    raise exception 'Up to 20 tags';
  end if;
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id', x.id, 'name', x.name, 'emoji', x.emoji,
                                                                 'mod_only', case when x.mod_only then true end)) order by x.n), '[]'::jsonb) into res
  from (
    select a.n, left(btrim(a.e->>'name'), 20) as name,
           nullif(left(btrim(coalesce(a.e->>'emoji', '')), 16), '') as emoji,
           coalesce(case when jsonb_typeof(a.e->'mod_only') = 'boolean' then (a.e->>'mod_only')::boolean end, false) as mod_only,
           case when a.e->>'id' is not null
                     and exists (select 1 from jsonb_array_elements(f.forum_tags) o where o->>'id' = a.e->>'id')
                     and a.n = min(a.n) over (partition by a.e->>'id')
                then a.e->>'id' else left(replace(gen_random_uuid()::text, '-', ''), 10) end as id
    from jsonb_array_elements(coalesce(p_tags, '[]'::jsonb)) with ordinality as a(e, n)
    where jsonb_typeof(a.e) = 'object' and char_length(btrim(coalesce(a.e->>'name', ''))) between 1 and 20
  ) x;
  update public.channels set forum_tags = res where id = p_forum;
  return res;
end $function$;

-- public.set_join_apply(sid uuid, p_on boolean, p_questions text[])  [security definer]
CREATE OR REPLACE FUNCTION public.set_join_apply(sid uuid, p_on boolean, p_questions text[] DEFAULT '{}'::text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare qs text[] := '{}'; q text;
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if not public.server_perm(sid, 'manage_server') then raise exception 'You need Manage Server for that'; end if;
  if p_on and not public.feature_on('join_applications', sid) then raise exception 'Join applications aren''t available here yet'; end if;
  foreach q in array coalesce(p_questions, '{}') loop
    q := btrim(coalesce(q, ''));
    if q = '' then continue; end if;
    if length(q) > 200 then raise exception 'Keep each question under 200 characters'; end if;
    qs := qs || q;
  end loop;
  if cardinality(qs) > 3 then raise exception 'Up to 3 questions'; end if;
  update public.servers set join_apply = coalesce(p_on, false), join_questions = qs where id = sid;
end $function$;

-- public.set_mod_limit_boost(boost numeric)  [security definer]
CREATE OR REPLACE FUNCTION public.set_mod_limit_boost(boost numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare was numeric;
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  if not public.is_site_admin() then
    if not (public.is_head_mod() or public.is_site_manager()) then raise exception 'Head mods and Management only'; end if;
    if not public.feature_on('mod_limit_boost', null) then raise exception 'Not available yet'; end if;
  end if;
  if boost is null or boost not in (1, 1.5, 2, 2.5) then raise exception 'Pick 1x, 1.5x, 2x or 2.5x'; end if;
  perform pg_advisory_xact_lock(hashtextextended('mod_limit_boost', 0));
  if not public.is_site_admin() and (select count(*) from public.mod_log where actor = auth.uid() and action = 'mod_limit_boost'
      and created_at > now() - interval '1 hour') >= 10 then
    raise exception 'You''ve changed the limits 10 times this hour. Wait a bit';
  end if;
  select mod_limit_boost into was from public.app_settings where id;
  if was = boost then return; end if;
  update public.app_settings set mod_limit_boost = boost where id;
  insert into public.mod_log (actor, action, reason)
  values (auth.uid(), 'mod_limit_boost', rtrim(rtrim(coalesce(was, 1)::text, '0'), '.') || 'x -> ' || rtrim(rtrim(boost::text, '0'), '.') || 'x');
end;
$function$;

-- public.set_muted(cid uuid, mute boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.set_muted(cid uuid, mute boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.can_access_channel(cid) then raise exception 'Chat not found'; end if;
  insert into public.channel_reads (user_id, channel_id, muted)
    values (auth.uid(), cid, mute)
    on conflict (user_id, channel_id) do update set muted = excluded.muted;
  update public.notify_settings n set muted_until = null, updated_at = now()
    where n.user_id = auth.uid() and n.channel_id = cid and n.muted_until is not null;
end;
$function$;

-- public.set_my_ping_roles(sid uuid, picks uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.set_my_ping_roles(sid uuid, picks uuid[])
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid()); allowed uuid[]; want uuid[];
begin
  if me is null or not public.feature_on('ping_roles', sid) then raise exception 'Ping roles aren''t available here'; end if;
  if not exists (select 1 from public.server_members m where m.server_id = sid and m.user_id = me) then raise exception 'Join the server first'; end if;
  if cardinality(coalesce(picks, '{}')) > 25 then raise exception 'Too many roles'; end if;
  if public.webhook_hit('pr:' || me::text, 60, 30) > 0 then raise exception 'Slow down a sec, then try again'; end if;
  -- Only ping roles that are still plain roles (one could have been given permissions or posting rights since).
  select coalesce(array_agg(p.role_id), '{}') into allowed from public.ping_roles p
    where p.server_id = sid and public.ping_role_plain(sid, p.role_id);
  select coalesce(array_agg(r), '{}') into want from unnest(coalesce(picks, '{}')) r where r = any (allowed);
  perform set_config('yapper.bot', '1', true);
  execute 'dele' || 'te from public.member_roles where server_id = $1 and user_id = $2 and role_id = any ($3) and not role_id = any ($4)'
    using sid, me, allowed, want;
  insert into public.member_roles (server_id, user_id, role_id)
  select sid, me, r from unnest(want) r on conflict do nothing;
  perform set_config('yapper.bot', '', true);
  return want;
end;
$function$;

-- public.set_new_account_rule(sid uuid, p_minutes integer, p_mode text)  [security definer]
CREATE OR REPLACE FUNCTION public.set_new_account_rule(sid uuid, p_minutes integer, p_mode text DEFAULT 'join'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if not public.server_perm(sid, 'manage_server') then raise exception 'You need Manage Server for that'; end if;
  if coalesce(p_minutes, 0) = 0 then
    update public.servers set new_account_minutes = null where id = sid;
    return;
  end if;
  if not public.feature_on('raid_protection', sid) then raise exception 'The new account rule isn''t available here yet'; end if;
  if p_minutes not in (10, 60, 1440, 10080) then raise exception 'Pick 10 minutes, 1 hour, 1 day or 7 days'; end if;
  if p_mode is null or p_mode not in ('join', 'chat') then raise exception 'Pick who it applies to'; end if;
  update public.servers set new_account_minutes = p_minutes, new_account_mode = p_mode where id = sid;
end $function$;

-- public.set_nickname(sid uuid, target uuid, nick text)  [security definer]
CREATE OR REPLACE FUNCTION public.set_nickname(sid uuid, target uuid, nick text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n text := left(public.clean_name(nick), 32);
begin
  if not public.feature_on('nicknames', sid) then
    raise exception 'Nicknames aren''t available here yet';
  end if;
  if target = auth.uid() then
    if not public.server_perm(sid, 'change_nickname') then
      raise exception 'You can''t change your nickname here';
    end if;
  elsif not public.server_perm(sid, 'manage_nicknames') then
    raise exception 'You can''t change other people''s nicknames';
  elsif not public.outranks(sid, target) then
    raise exception 'You can only change nicknames of people below your top role';
  end if;
  if n is not null and n !~ '[[:alnum:]]' then
    raise exception 'Nicknames need at least one letter or number';
  end if;
  if n is not null and (public.bad_name(n) or public.has_adult_link(n) or (public.brand_name(n) and not public.is_site_admin())) then
    raise exception 'That nickname isn''t allowed.';
  end if;
  update public.server_members set nickname = n where server_id = sid and user_id = target;
end;
$function$;

-- public.set_notify_level(sid uuid, cid uuid, lvl text)  [security definer]
CREATE OR REPLACE FUNCTION public.set_notify_level(sid uuid, cid uuid, lvl text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid();
begin
  if me is null then raise exception 'Sign in first'; end if;
  if lvl is not null and lvl not in ('all', 'mentions', 'none') then raise exception 'Unknown setting'; end if;
  if not public.feature_on('channel_notify', sid) then raise exception 'Not available yet'; end if;
  if not exists (select 1 from public.server_members sm where sm.server_id = sid and sm.user_id = me) then raise exception 'Server not found'; end if;
  if cid is null then
    insert into public.notify_settings as n (user_id, server_id, channel_id, level) values (me, sid, null, lvl)
      on conflict (user_id, server_id) where channel_id is null do update set level = excluded.level, updated_at = now();
  else
    if not exists (select 1 from public.channels c where c.id = cid and c.server_id = sid) or not public.can_access_channel(cid) then
      raise exception 'Channel not found';
    end if;
    insert into public.notify_settings as n (user_id, server_id, channel_id, level) values (me, sid, cid, lvl)
      on conflict (user_id, channel_id) where channel_id is not null do update set level = excluded.level, updated_at = now();
  end if;
end; $function$;

-- public.set_notify_mute(cid uuid, mins integer)  [security definer]
CREATE OR REPLACE FUNCTION public.set_notify_mute(cid uuid, mins integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); sid uuid; until timestamptz;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if mins is not null and (mins < 0 or mins > 1440) then raise exception 'Pick a shorter mute'; end if;
  select c.server_id into sid from public.channels c where c.id = cid;
  if sid is null or not public.can_access_channel(cid) then raise exception 'Channel not found'; end if;
  if not public.feature_on('channel_notify', sid) then raise exception 'Not available yet'; end if;
  if mins is not null and mins > 0 then until := now() + make_interval(mins => mins); end if;
  insert into public.channel_reads (user_id, channel_id, muted) values (me, cid, coalesce(mins, 1) <> 0)
    on conflict (user_id, channel_id) do update set muted = excluded.muted;
  insert into public.notify_settings as n (user_id, server_id, channel_id, muted_until) values (me, sid, cid, until)
    on conflict (user_id, channel_id) where channel_id is not null do update set muted_until = excluded.muted_until, updated_at = now();
  return until;
end; $function$;

-- public.set_reaction_roles(mid uuid, pairs jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.set_reaction_roles(mid uuid, pairs jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; p jsonb; top int; e text;
begin
  select c.server_id into sid from public.messages m join public.channels c on c.id = m.channel_id where m.id = mid;
  if sid is null or not public.server_perm(sid, 'manage_roles') then raise exception 'You can''t manage roles here'; end if;
  if not public.feature_on('reaction_roles', sid) then raise exception 'Reaction roles aren''t available here yet'; end if;
  if jsonb_typeof(pairs) <> 'array' or jsonb_array_length(pairs) > 20 then raise exception 'Up to 20 reaction roles per message'; end if;
  top := public.my_top_role_position(sid);
  -- (Emoji up to 80 characters now, was left(p ->> 'emoji', 80) in an older patch: keep that text here so it skips.)
  for p in select * from jsonb_array_elements(pairs) loop
    e := btrim(coalesce(p ->> 'emoji', ''));
    if not public.reaction_emoji_ok(e)
       and not exists (select 1 from public.reaction_roles rr where rr.message_id = mid and rr.emoji = e) then
      raise exception 'Each reaction role needs a single emoji';
    end if;
  end loop;
  perform public.clear_reaction_roles(mid);
  for p in select * from jsonb_array_elements(pairs) loop
    -- 504: below your top role AND only permissions you have (the reaction hands it out with yapper.bot set).
    if not exists (select 1 from public.roles r where r.id = (p ->> 'role_id')::uuid and r.server_id = sid
                   and ((r.position < top and public.can_give_role_perms(sid, r.id))
                        or exists (select 1 from public.servers s where s.id = sid and s.owner_id = auth.uid()) or public.is_site_admin())) then
      raise exception 'You can only hand out roles below your highest role, with permissions you have yourself';
    end if;
    insert into public.reaction_roles (message_id, emoji, role_id, server_id) values (mid, btrim(p ->> 'emoji'), (p ->> 'role_id')::uuid, sid)
      on conflict (message_id, emoji) do update set role_id = excluded.role_id;
  end loop;
end; $function$;

-- public.set_rules_channel(sid uuid, cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.set_rules_channel(sid uuid, cid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or not public.server_perm(sid, 'manage_server') then
    raise exception 'Only server managers can change this' using errcode = 'insufficient_privilege';
  end if;
  if not public.feature_on('rules_channel', sid) then
    raise exception 'Rules channels aren''t on in this server yet' using errcode = 'check_violation';
  end if;
  if cid is not null and not exists (
    select 1 from public.channels c
    where c.id = cid and c.server_id = sid and c.kind = 'text' and c.ticket_by is null
  ) then
    raise exception 'Pick a text channel in this server' using errcode = 'check_violation';
  end if;
  update public.servers set rules_channel_id = cid where id = sid;
end $function$;

-- public.set_server_banner(sid uuid, p text, bx numeric, by numeric, bz numeric)  [security definer]
CREATE OR REPLACE FUNCTION public.set_server_banner(sid uuid, p text, bx numeric DEFAULT 50, by numeric DEFAULT 50, bz numeric DEFAULT 1)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.server_perm(sid, 'manage_server') then raise exception 'You can''t manage this server'; end if;
  if p is not null then
    if p !~ ('^' || auth.uid()::text || '/') then raise exception 'Bad banner'; end if;
    if not public.media_ok('banners', p) then raise exception 'That image hasn''t been checked yet'; end if;
  end if;
  update public.servers set banner_path = p, banner_x = least(100, greatest(0, coalesce(bx, 50))), banner_y = least(100, greatest(0, coalesce(by, 50))), banner_zoom = least(3, greatest(1, coalesce(bz, 1))) where id = sid;
end;
$function$;

-- public.set_server_banner(sid uuid, p text)  [security definer]
CREATE OR REPLACE FUNCTION public.set_server_banner(sid uuid, p text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.server_perm(sid, 'manage_server') then raise exception 'You can''t manage this server'; end if;
  if p is not null then
    if p !~ ('^' || auth.uid()::text || '/') then raise exception 'Bad banner'; end if;
    if not public.media_ok('banners', p) then raise exception 'That image hasn''t been checked yet'; end if;
  end if;
  update public.servers set banner_path = p where id = sid;
end;
$function$;

-- public.set_server_bot(sid uuid, p_bot text, p_enabled boolean, p_config jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.set_server_bot(sid uuid, p_bot text, p_enabled boolean, p_config jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cfg jsonb := coalesce(p_config, '{}'::jsonb);
begin
  if not public.server_perm(sid, 'manage_server') then raise exception 'Only server managers can set up bots'; end if;
  if not public.feature_on('bots', sid) then raise exception 'Bots aren''t available here yet'; end if;
  -- The per-server look (name, picture) is set by set_bot_look and the upload route; keep what's stored.
  cfg := cfg - 'look_name' - 'look_avatar';
  cfg := cfg || coalesce((select jsonb_strip_nulls(jsonb_build_object('look_name', config -> 'look_name', 'look_avatar', config -> 'look_avatar')) from public.server_bots where server_id = sid and bot = p_bot), '{}'::jsonb);
  if not public.server_plus_on(sid) then
    cfg := cfg - 'xp_mult' - 'rewards' - 'lines' - 'leave_channel_id' - 'leave_message' - 'commands'
      - 'member_channel_id' - 'ignore' - 'emoji' - 'self_star' - 'required_role_id' - 'support_role_id' - 'welcome' - 'transcript';
    if p_bot = 'levels' then cfg := cfg - 'message'; end if;
  end if;
  if jsonb_typeof(cfg -> 'rewards') = 'array' and jsonb_array_length(cfg -> 'rewards') > 20 then raise exception 'Up to 20 role rewards'; end if;
  -- 504: reward roles also need permissions the setter has (Levels hands them out with yapper.bot set).
  if jsonb_typeof(cfg -> 'rewards') = 'array'
     and not exists (select 1 from public.servers s where s.id = sid and s.owner_id = auth.uid())
     and not public.is_site_admin()
     and exists (
       select 1 from jsonb_array_elements(cfg -> 'rewards') rw
       left join public.roles r on r.id = case when (rw ->> 'role_id') ~ '^[0-9a-f-]{36}$' then (rw ->> 'role_id')::uuid end
       where rw ? 'role_id' and (r.id is null or r.server_id <> sid
              or r.position >= public.my_top_role_position(sid)
              or coalesce((r.perms ->> 'administrator')::boolean, false)
              or not public.can_give_role_perms(sid, r.id))) then
    raise exception 'Role rewards have to be roles below your highest role, with permissions you have yourself';
  end if;
  if jsonb_typeof(cfg -> 'commands') = 'array' and jsonb_array_length(cfg -> 'commands') > 25 then raise exception 'Up to 25 custom commands'; end if;
  if jsonb_typeof(cfg -> 'lines') = 'array' and jsonb_array_length(cfg -> 'lines') > 10 then raise exception 'Up to 10 welcome lines'; end if;
  if jsonb_typeof(cfg -> 'ignore') = 'array' and jsonb_array_length(cfg -> 'ignore') > 25 then raise exception 'Up to 25 ignored channels'; end if;
  if cfg ? 'emoji' and char_length(cfg ->> 'emoji') > 16 then raise exception 'Pick one emoji'; end if;
  if p_bot = 'tickets' and jsonb_typeof(cfg -> 'panels') = 'array' and jsonb_array_length(cfg -> 'panels') > (case when public.server_plus_on(sid) then 10 else 2 end) then
    raise exception '%', (case when public.server_plus_on(sid) then 'Up to 10 ticket panels' else 'Free servers get 2 ticket panels. Tickets+ gets 10.' end);
  end if;
  insert into public.server_bots (server_id, bot, enabled, config) values (sid, p_bot, p_enabled, cfg)
  on conflict (server_id, bot) do update set enabled = excluded.enabled, config = excluded.config;
end $function$;

-- public.set_server_discovery(sid uuid, p_on boolean, p_description text, p_tags text[])  [security definer]
CREATE OR REPLACE FUNCTION public.set_server_discovery(sid uuid, p_on boolean, p_description text, p_tags text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t text; clean text[] := '{}';
begin
  if not public.server_perm(sid, 'manage_server') then raise exception 'You can''t manage this server'; end if;
  if public.bad_name(coalesce(p_description, '')) then raise exception 'That description isn''t allowed'; end if;
  foreach t in array coalesce(p_tags, '{}') loop
    t := lower(regexp_replace(btrim(t), '[^a-z0-9 ]', '', 'gi'));
    if t <> '' and char_length(t) <= 20 and not (t = any(clean)) then clean := clean || t; end if;
    exit when array_length(clean, 1) >= 5;
  end loop;
  update public.servers set discoverable = p_on, description = left(btrim(coalesce(p_description, '')), 300), tags = clean where id = sid;
end;
$function$;

-- public.set_server_links(sid uuid, p_links jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.set_server_links(sid uuid, p_links jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.server_perm(sid, 'manage_server') then raise exception 'Only server managers can edit links'; end if;
  if jsonb_typeof(p_links) <> 'array' or jsonb_array_length(p_links) > 10 then raise exception 'Up to 10 links'; end if;
  update public.servers set links = p_links where id = sid;
end;
$function$;

-- public.set_server_lobby_on(sid uuid, p_on boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.set_server_lobby_on(sid uuid, p_on boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or not public.server_perm(sid, 'manage_server') then
    raise exception 'Only server managers can change the lobby' using errcode = 'insufficient_privilege';
  end if;
  if not public.feature_on('lobby_v2', sid) then
    raise exception 'Lobby customizing isn''t on in this server yet' using errcode = 'check_violation';
  end if;
  update public.servers set lobby_on = coalesce(p_on, false) where id = sid and lobby_on is distinct from coalesce(p_on, false);
  if found then
    perform public.audit_add(sid, 'server_update_lobby', 'server', sid, (select s.name from public.servers s where s.id = sid),
      jsonb_build_object('lobby_on', coalesce(p_on, false)));
  end if;
end $function$;

-- public.set_server_lobby_v2(sid uuid, p_about text, p_faq jsonb, p_featured uuid[], p_show_staff boolean, p_style jsonb, p_sections jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.set_server_lobby_v2(sid uuid, p_about text, p_faq jsonb, p_featured uuid[], p_show_staff boolean, p_style jsonb, p_sections jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  st jsonb := coalesce(p_style, '{}'::jsonb);
  out_style jsonb := '{}'::jsonb;
  out_sections jsonb := '[]'::jsonb;
  seen text[] := '{}';
  k text;
  v text;
  item jsonb;
  label text;
  url text;
  ch uuid;
  btns jsonb := '[]'::jsonb;
  problem text;
  kinds text[];
  kv text;
  sec jsonb;
begin
  if auth.uid() is null or not public.server_perm(sid, 'manage_server') then
    raise exception 'Only server managers can change the lobby' using errcode = 'insufficient_privilege';
  end if;
  if not public.feature_on('lobby_v2', sid) then
    raise exception 'Lobby customizing isn''t on in this server yet' using errcode = 'check_violation';
  end if;
  if jsonb_typeof(st) <> 'object' then
    raise exception 'The lobby look has to be an object' using errcode = 'check_violation';
  end if;
  if p_sections is not null and (jsonb_typeof(p_sections) <> 'array' or jsonb_array_length(p_sections) > 20) then
    raise exception 'That''s too many lobby sections' using errcode = 'check_violation';
  end if;
  if st ? 'buttons' and (jsonb_typeof(st -> 'buttons') <> 'array' or jsonb_array_length(st -> 'buttons') > 4) then
    raise exception 'Up to 4 lobby buttons' using errcode = 'check_violation';
  end if;

  for k, v in select key, value #>> '{}' from jsonb_each(st) where key in ('preset', 'bg', 'cards', 'font', 'hero', 'align') loop
    if v is null or not v = any (case k
        when 'preset' then array['classic', 'spotlight', 'magazine', 'compact']
        when 'bg' then array['plain', 'glow', 'banner', 'mesh']
        when 'cards' then array['filled', 'outline', 'glass']
        when 'font' then array['default', 'rounded', 'serif', 'mono', 'display']
        when 'hero' then array['tall', 'normal', 'short']
        when 'align' then array['left', 'center'] end) then
      raise exception 'Unknown lobby % "%"', k, coalesce(v, '') using errcode = 'check_violation';
    end if;
    out_style := out_style || jsonb_build_object(k, v);
  end loop;

  if st ? 'accent' and jsonb_typeof(st -> 'accent') <> 'null' then
    v := st ->> 'accent';
    if v is null or v !~ '^#[0-9a-fA-F]{6}$' then
      raise exception 'The accent has to be a colour like #ff8800' using errcode = 'check_violation';
    end if;
    out_style := out_style || jsonb_build_object('accent', lower(v));
  end if;

  v := btrim(coalesce(st ->> 'tagline', ''));
  if char_length(v) > 120 then
    raise exception 'The tagline can be up to 120 characters' using errcode = 'check_violation';
  end if;
  problem := public.lobby_text_problem(v);
  if problem is not null then
    raise exception '%', problem using errcode = 'check_violation';
  end if;
  if v <> '' then out_style := out_style || jsonb_build_object('tagline', v); end if;

  for item in select value from jsonb_array_elements(coalesce(st -> 'buttons', '[]'::jsonb)) loop
    if jsonb_typeof(item) <> 'object' then
      raise exception 'Each lobby button needs a label and a link or channel' using errcode = 'check_violation';
    end if;
    label := btrim(coalesce(item ->> 'label', ''));
    url := nullif(btrim(coalesce(item ->> 'url', '')), '');
    continue when label = '' and url is null and coalesce(item ->> 'channel', '') = '';
    if label = '' or char_length(label) > 24 then
      raise exception 'Button labels can be 1 to 24 characters' using errcode = 'check_violation';
    end if;
    problem := public.lobby_text_problem(label);
    if problem is not null then
      raise exception '%', problem using errcode = 'check_violation';
    end if;
    if url is not null then
      if char_length(url) > 500 or url !~* '^https://[a-z0-9-]+(\.[a-z0-9-]+)+(:[0-9]{1,5})?([/?#]\S*)?$' then
        raise exception 'Button links have to be https:// addresses' using errcode = 'check_violation';
      end if;
      if public.has_adult_link(url) then
        raise exception 'Links to that site aren''t allowed on Yapper.' using errcode = 'check_violation';
      end if;
      btns := btns || jsonb_build_array(jsonb_build_object('label', label, 'url', url));
    else
      begin
        ch := (item ->> 'channel')::uuid;
      exception when others then
        ch := null;
      end;
      if ch is null or not exists (select 1 from public.channels c where c.id = ch and c.server_id = sid and c.ticket_by is null) then
        raise exception 'Button channels have to be channels in this server' using errcode = 'check_violation';
      end if;
      btns := btns || jsonb_build_array(jsonb_build_object('label', label, 'channel', ch));
    end if;
  end loop;
  if jsonb_array_length(btns) > 0 then out_style := out_style || jsonb_build_object('buttons', btns); end if;

  for item in select value from jsonb_array_elements(coalesce(p_sections, '[]'::jsonb)) loop
    k := item ->> 'id';
    if jsonb_typeof(item) <> 'object' or k is null
       or not k = any (array['about', 'channels', 'live', 'faq', 'roles', 'rules', 'staff', 'links', 'leaderboard', 'giveaways', 'feed']) then
      raise exception 'Unknown lobby section' using errcode = 'check_violation';
    end if;
    continue when k = any(seen);
    seen := seen || k;
    continue when k = 'feed' and not public.feature_on('lobby_feeds', sid);
    sec := jsonb_build_object('id', k, 'on', coalesce(case when jsonb_typeof(item -> 'on') = 'boolean' then (item -> 'on')::boolean end, true));
    if jsonb_typeof(item -> 'side') = 'boolean' then sec := sec || jsonb_build_object('side', (item -> 'side')::boolean); end if;
    if k = 'leaderboard' and item ? 'kinds' and public.feature_on('lobby_feeds', sid) then
      if jsonb_typeof(item -> 'kinds') <> 'array' or jsonb_array_length(item -> 'kinds') > 3 then
        raise exception 'Pick up to 3 leaderboards' using errcode = 'check_violation';
      end if;
      kinds := '{}';
      for kv in select value #>> '{}' from jsonb_array_elements(item -> 'kinds') loop
        if kv is null or not kv = any (array['levels', 'messages', 'invites']) then
          raise exception 'Unknown leaderboard "%"', coalesce(kv, '') using errcode = 'check_violation';
        end if;
        if not kv = any(kinds) then kinds := kinds || kv; end if;
      end loop;
      if cardinality(kinds) > 0 then sec := sec || jsonb_build_object('kinds', to_jsonb(kinds)); end if;
    end if;
    out_sections := out_sections || jsonb_build_array(sec);
  end loop;

  perform public.set_server_lobby(sid, p_about, p_faq, p_featured, p_show_staff);

  update public.server_lobby set style = out_style, sections = out_sections where server_id = sid;
end $function$;

-- public.set_server_lobby(sid uuid, p_about text, p_faq jsonb, p_featured uuid[], p_show_staff boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.set_server_lobby(sid uuid, p_about text, p_faq jsonb, p_featured uuid[], p_show_staff boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  about text := btrim(coalesce(p_about, ''));
  item jsonb;
  q text;
  a text;
  faq jsonb := '[]'::jsonb;
  feat uuid[] := '{}';
  f uuid;
  problem text;
begin
  if auth.uid() is null or not public.server_perm(sid, 'manage_server') then
    raise exception 'Only server managers can change the lobby' using errcode = 'insufficient_privilege';
  end if;
  if not public.feature_on('server_lobby', sid) then
    raise exception 'Lobbies aren''t on in this server yet' using errcode = 'check_violation';
  end if;

  -- Size first, before any per-item work (blank and repeated entries are skipped below, so a little slack).
  if p_faq is not null and jsonb_typeof(p_faq) <> 'array' then
    raise exception 'The FAQ has to be a list' using errcode = 'check_violation';
  end if;
  if jsonb_array_length(coalesce(p_faq, '[]'::jsonb)) > 20 or coalesce(cardinality(p_featured), 0) > 12 then
    raise exception 'That''s too much for a lobby' using errcode = 'check_violation';
  end if;
  if char_length(about) > 2000 then
    raise exception 'The about text can be up to 2000 characters' using errcode = 'check_violation';
  end if;
  problem := public.lobby_text_problem(about);
  if problem is not null then
    raise exception '%', problem using errcode = 'check_violation';
  end if;
  for item in select value from jsonb_array_elements(coalesce(p_faq, '[]'::jsonb)) loop
    if jsonb_typeof(item) <> 'object' then
      raise exception 'Each FAQ entry needs a question and an answer' using errcode = 'check_violation';
    end if;
    q := btrim(coalesce(item ->> 'q', ''));
    a := btrim(coalesce(item ->> 'a', ''));
    continue when q = '' and a = '';
    if q = '' or a = '' then
      raise exception 'Each FAQ entry needs a question and an answer' using errcode = 'check_violation';
    end if;
    if char_length(q) > 200 or char_length(a) > 1000 then
      raise exception 'FAQ questions can be up to 200 characters and answers up to 1000' using errcode = 'check_violation';
    end if;
    problem := coalesce(public.lobby_text_problem(q), public.lobby_text_problem(a));
    if problem is not null then
      raise exception '%', problem using errcode = 'check_violation';
    end if;
    faq := faq || jsonb_build_array(jsonb_build_object('q', q, 'a', a));
  end loop;
  if jsonb_array_length(faq) > 10 then
    raise exception 'The FAQ can have up to 10 questions' using errcode = 'check_violation';
  end if;

  foreach f in array coalesce(p_featured, '{}') loop
    continue when f is null or f = any(feat);
    if not exists (select 1 from public.channels c where c.id = f and c.server_id = sid and c.ticket_by is null) then
      raise exception 'Main channels have to be channels in this server' using errcode = 'check_violation';
    end if;
    feat := feat || f;
  end loop;
  if cardinality(feat) > 6 then
    raise exception 'Pick up to 6 main channels' using errcode = 'check_violation';
  end if;

  insert into public.server_lobby (server_id, about, faq, featured, show_staff, updated_at)
  values (sid, about, faq, feat, coalesce(p_show_staff, true), now())
  on conflict (server_id) do update
    set about = excluded.about, faq = excluded.faq, featured = excluded.featured,
        show_staff = excluded.show_staff, updated_at = excluded.updated_at;

  perform public.audit_add(sid, 'server_update_lobby', 'server', sid, (select s.name from public.servers s where s.id = sid),
    jsonb_build_object('faq', jsonb_array_length(faq), 'featured', cardinality(feat)));
end $function$;

-- public.set_server_lock(sid uuid, p_minutes integer)  [security definer]
CREATE OR REPLACE FUNCTION public.set_server_lock(sid uuid, p_minutes integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.server_perm(sid, 'manage_server') then raise exception 'Only server managers can lock the server'; end if;
  if coalesce(p_minutes, 0) <= 0 then
    update public.servers set locked_until = null, lock_reason = null where id = sid;
  else
    update public.servers set locked_until = now() + make_interval(mins => least(p_minutes, 1440)), lock_reason = 'by a manager' where id = sid;
  end if;
end; $function$;

-- public.set_server_tag_text(sid uuid, p_tag text)  [security definer]
CREATE OR REPLACE FUNCTION public.set_server_tag_text(sid uuid, p_tag text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t text := nullif(trim(coalesce(p_tag, '')), '');
begin
  if not public.server_perm(sid, 'manage_server') then raise exception 'Only server managers can set the tag'; end if;
  if t is not null and t !~ '^[A-Za-z0-9]{2,4}$' then raise exception 'Tags are 2 to 4 letters or numbers'; end if;
  if t is not null and public.bad_name(t) then raise exception 'That tag isn’t allowed'; end if;
  update public.servers set tag = t where id = sid;
end; $function$;

-- public.set_server_tag(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.set_server_tag(sid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); t text;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if sid is null then
    update public.profiles set server_tag = null, tag = null where id = me;
    return;
  end if;
  if not exists (select 1 from public.server_members where server_id = sid and user_id = me) then raise exception 'You’re not in that server'; end if;
  select tag into t from public.servers where id = sid and shut_down_at is null;
  if t is null then raise exception 'That server has no tag'; end if;
  update public.profiles set server_tag = sid, tag = t where id = me;
end; $function$;

-- public.set_server_theme(sid uuid, p_accent text, p_tint text)  [security definer]
CREATE OR REPLACE FUNCTION public.set_server_theme(sid uuid, p_accent text, p_tint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a text := nullif(lower(btrim(coalesce(p_accent, ''))), ''); t text := nullif(lower(btrim(coalesce(p_tint, ''))), ''); th jsonb;
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if not public.server_perm(sid, 'manage_server') then raise exception 'Only people who can manage the server can change its theme'; end if;
  if a is not null and a !~ '^#[0-9a-f]{6}$' then raise exception 'Colours look like #ff6b4a'; end if;
  if t is not null and t !~ '^#[0-9a-f]{6}$' then raise exception 'Colours look like #ff6b4a'; end if;
  th := jsonb_strip_nulls(jsonb_build_object('accent', a, 'tint', t));
  if th = '{}'::jsonb then th := null; end if;
  update public.servers set theme = th where id = sid;
  return th;
end; $function$;

-- public.set_signups_paused(minutes integer)  [security definer]
CREATE OR REPLACE FUNCTION public.set_signups_paused(minutes integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare until timestamptz;
begin
  if not public.is_site_admin() then raise exception 'Only Yapper admins can pause sign-ups'; end if;
  if minutes is null or minutes < 0 or minutes > 10080 then raise exception 'Pick 0 (open) to 10080 minutes'; end if;
  until := case when minutes = 0 then null else now() + make_interval(mins => minutes) end;
  update public.app_settings set signups_paused_until = until where id returning signups_paused_until into until;
  if not found then raise exception 'app_settings row missing'; end if;
  return until;
end $function$;

-- public.set_status_pref(p text)  [security definer]
CREATE OR REPLACE FUNCTION public.set_status_pref(p text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or p not in ('online', 'idle', 'dnd', 'invisible') then return; end if;
  insert into public.presence (user_id, status, pref, last_seen)
    values (auth.uid(), case when p = 'invisible' then 'online' else p end, p, case when p = 'invisible' then now() - interval '101 seconds' else now() end)
  on conflict (user_id) do update set pref = excluded.pref,
    last_seen = case when excluded.pref = 'invisible' then least(presence.last_seen, now() - interval '100 seconds') else presence.last_seen end;
end $function$;

-- public.set_thread_state(p_thread uuid, p_state text, p_on boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.set_thread_state(p_thread uuid, p_state text, p_on boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t public.channels; is_mod boolean; me uuid := (select auth.uid()); on_ boolean := coalesce(p_on, false);
begin
  t := public.thread_v2(p_thread);
  is_mod := public.thread_mod(p_thread);
  if p_state = 'close' then
    if not public.thread_owner_or_mod(p_thread) then raise exception 'Only whoever started it or a mod can do that'; end if;
    if on_ then
      if t.closed_at is null then update public.channels set closed_at = now(), closed_by = me where id = p_thread; end if;
    else
      if t.locked and not is_mod then raise exception 'A mod locked this one'; end if;
      if t.closed_at is not null then update public.channels set closed_at = null, closed_by = null where id = p_thread; end if;
    end if;
  elsif p_state = 'lock' then
    if not is_mod then raise exception 'Only mods can lock posts'; end if;
    if t.locked is distinct from on_ then update public.channels set locked = on_ where id = p_thread; end if;
  elsif p_state = 'pin' then
    if not is_mod then raise exception 'Only mods can pin posts'; end if;
    if not exists (select 1 from public.channels f where f.id = t.parent_id and f.kind = 'forum') then raise exception 'Only forum posts can be pinned'; end if;
    if on_ and t.pinned_at is null then
      perform 1 from public.channels f where f.id = t.parent_id for update;
      if (select count(*) from public.channels c where c.parent_id = t.parent_id and c.pinned_at is not null) >= 5 then
        raise exception 'Up to 5 pinned posts';
      end if;
      update public.channels set pinned_at = now() where id = p_thread;
    elsif not on_ and t.pinned_at is not null then
      update public.channels set pinned_at = null where id = p_thread;
    end if;
  else
    raise exception 'Unknown option';
  end if;
end $function$;

-- public.set_thread_tags(p_thread uuid, p_tags text[])  [security definer]
CREATE OR REPLACE FUNCTION public.set_thread_tags(p_thread uuid, p_tags text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t public.channels;
begin
  if not public.thread_owner_or_mod(p_thread) then raise exception 'Only whoever started it or a mod can do that'; end if;
  select * into t from public.channels where id = p_thread;
  if not exists (select 1 from public.channels pf where pf.id = t.parent_id and pf.kind = 'forum') then raise exception 'Only forum posts have tags'; end if;
  update public.channels set tags = public.forum_pick_tags(t.parent_id, p_tags, t.tags, public.thread_mod(p_thread)) where id = p_thread;
end $function$;

-- public.set_tickets(sid uuid, p_on boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.set_tickets(sid uuid, p_on boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.server_perm(sid, 'manage_server') then raise exception 'Only server managers can change this'; end if;
  update public.servers set tickets_on = p_on where id = sid;
end; $function$;

-- public.set_vanity_invite(sid uuid, p_code text)  [security definer]
CREATE OR REPLACE FUNCTION public.set_vanity_invite(sid uuid, p_code text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c text := btrim(coalesce(p_code, '')); k text; uid uuid := auth.uid();
begin
  if uid is null then raise exception 'Sign in first'; end if;
  if not public.server_perm(sid, 'manage_server') then raise exception 'You can''t manage this server'; end if;
  if c !~ '^[A-Za-z0-9_-]{3,32}$' then raise exception 'Links are 3 to 32 letters, numbers, dashes or underscores'; end if;
  k := public.lookalike_key(c);
  if public.bad_name(c) or public.brand_name(c) or public.bad_name(k) or public.brand_name(k)
     or public.bad_name(public.vanity_key(c)) or public.brand_name(public.vanity_key(c))
     or public.vanity_reserved(c) then
    raise exception 'That link isn''t allowed';
  end if;
  if (select count(*) from (
        select 1 from public.server_members m
        where m.server_id = sid
          and not exists (select 1 from public.bots b where b.id = m.user_id)
          and not exists (select 1 from public.bot_accounts a where a.user_id = m.user_id)
        limit 5) x) < 5 then
    raise exception 'Custom links unlock at 5 members (bots don''t count)';
  end if;
  if exists (select 1 from public.invites where server_id = sid and vanity and code = c) then return c; end if;
  perform pg_advisory_xact_lock(hashtextextended('vanity:' || uid::text, 0));
  if (select count(*) from public.vanity_changes where server_id = sid and at > now() - interval '1 hour') >= 5
     or (select count(*) from public.vanity_changes where user_id = uid and at > now() - interval '1 day') >= 15 then
    raise exception 'You''re changing links too fast. Try again later';
  end if;
  if exists (select 1 from public.invites where lower(code) = lower(c) and server_id <> sid) then raise exception 'That link is taken'; end if;
  if exists (select 1 from public.invites where server_id = sid and vanity) then
    update public.invites set code = c where server_id = sid and vanity;
  else
    insert into public.invites (code, server_id, created_by, vanity) values (c, sid, uid, true);
  end if;
  insert into public.vanity_changes (server_id, user_id) values (sid, uid);
  if random() < 0.02 then
    execute 'dele' || 'te from public.vanity_changes where at < now() - interval ''2 days''';
  end if;
  return c;
end;
$function$;

-- public.set_verification_level(sid uuid, p_level integer)  [security definer]
CREATE OR REPLACE FUNCTION public.set_verification_level(sid uuid, p_level integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if not public.server_perm(sid, 'manage_server') then raise exception 'You need Manage Server for that'; end if;
  if p_level is null or p_level not between 0 and 3 then raise exception 'Pick None, Low, Medium or High'; end if;
  -- Lowering it always works; raising it needs the feature.
  if p_level > (select verification_level from public.servers where id = sid) and not public.feature_on('server_verification', sid) then
    raise exception 'Verification levels aren''t available here yet';
  end if;
  update public.servers set verification_level = p_level where id = sid;
end $function$;

-- public.sexual_ad_signal(t text)
CREATE OR REPLACE FUNCTION public.sexual_ad_signal(t text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select
    regexp_replace(coalesce(t, ''), '<[@#&][^>]*>|@everyone|@here', ' ', 'g')
      ~* '(https?://|www\.|t\.me/|@[a-z0-9_.]{3,}|[$€£] ?[0-9]|[0-9] ?[$€£]|[0-9] ?(usd|eur|gbp|bucks|dollars?|euros?|quid|pounds?|btc|pesos)|telegram|snapchat|cashapp|whatsapp|paypal|venmo|zelle|instagram|tiktok|twitter|(insta|ig|kik|discord|tg|wickr|signal|tele|snap) ?:|discord ?\. ?gg)'
    or coalesce(t, '') ~* '[a-z0-9-]+\.(gg|com|net|org|io|xyz|ly|ru|cc|tv|ee|xxx|ai|sex|porn|wtf|ws|fm|sh)\M'
    or coalesce(t, '') ~ '[a-z0-9-]+\.(me|to|co|us|link|app|club|site|online|shop|top|store|ink|adult|fun|lol|vip|live|cam|chat|bio)\M'
    or coalesce(t, '') ~ '[A-Z0-9-]+\.(ME|TO|CO|US|LINK|APP|CLUB|SITE|ONLINE|SHOP|TOP|STORE|INK|ADULT|FUN|LOL|VIP|LIVE|CAM|CHAT|BIO)\M'
    or (' ' || public.slur_text(t) || ' ') ~ ' (buy|buying|order|orders|ordering|cheap|discount|price|prices|deal|deals|sale|shop|store|snap|sponsored|hmu|(dm|pm|msg|message|text|add|inbox|contact|whisper|kik|ping|friend|tele|tg|insta|ig) (me|us|for)|hit me up|dms open|friend request|cash ?app|apple ?pay|google ?pay|revolut|usdc|crypto|gift ?cards?|robux|(five|ten|twenty|fifty|hundred) (bucks|dollars)|links? (in|on) (my )?(bio|profile|page|description)|(in|on|check|see|look at) my (bio|profile|page|status|server|insta|snap|tele)|click (here|the link)) '
    or regexp_replace(
         regexp_replace(' ' || public.slur_text(t) || ' ',
           ' dm (a|an|the|any|our|your|one of the)( one of the)? (mods?|admins?|staff|moderators?) ', ' ', 'g'),
         ' ((no|dont|don t|do not|never|without|report|stop) (unsolicited |unwanted |random |mass |spam |advertising |ads )*(dm|dms|dming)|report(ing)? ([a-z]+ ){0,3}via (dm|dms)|(dm|dms|dming) (advertising|ads|spam|spamming)) ', ' ', 'g') ~ ' (dm|dms) '
    or public.sexual_soft_word(lower(coalesce(t, '')))
    or public.sexual_soft_word(' ' || public.slur_text(t) || ' ');
$function$;

-- public.sexual_soft_word(x text)
CREATE OR REPLACE FUNCTION public.sexual_soft_word(x text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select regexp_replace(
           regexp_replace(
             regexp_replace(coalesce(x, ''),
               '\m(no|not|never|dont|don[’'' ]?t|do not|without|zero)\M[ \t]+(((any|all|the|more|kind of|kinds of|type of|types of|spam|spamming|ads?|advertising|advertisements?|advertise|scams?|scamming|self|begging|beg|asking|ask|trading|trades?|buying|for|of)[ \t]+((or|and)[ \t]+)?)*(self[ \t-]*)?(selling|sell|free|promo|promotions?)\M(([ \t]*[,/&][ \t]*((or|and)[ \t]+)?|[ \t]+(or|and)[ \t]+|[ \t]+)(self[ \t-]*)?(selling|sell|promo|promotions?|ads?|advertising|spam|spamming|trading|scamming|buying)\M)*|((any|all|the|more|kind of|kinds of|type of|types of|spam|spamming|ads?|advertising|advertisements?|advertise|scams?|scamming|self|begging|beg|asking|ask|trading|trades?|buying|for|of)([ \t]*[,/&][ \t]*((or|and)[ \t]+)?|[ \t]+(or|and)[ \t]+))+(self[ \t-]*)?(selling|sell|promo|promotions?)\M(([ \t]*[,/&][ \t]*((or|and)[ \t]+)?|[ \t]+(or|and)[ \t]+|[ \t]+)(self[ \t-]*)?(selling|sell|promo|promotions?|ads?|advertising|spam|spamming|trading|scamming|buying)\M)*(?=[ \t]*([.!?;\n]|$)))',
               ' ', 'g'),
             '\m(sell|selling|free|promo|promotions?)\M[^.!?\n]{0,15}\m(not allowed|not permitted|banned|prohibited|forbidden)\M', ' ', 'g'),
           '\m(feel free|free to|free of|free speech)\M', ' ', 'g')
         ~ '\m(sell|selling|free|promo|promotions?)\M';
$function$;

-- public.shard_boost(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.shard_boost(uid uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare plus numeric := 1;
begin
  if exists (select 1 from public.profiles p where p.id = uid and p.plus_until > now())
    and exists (select 1 from public.feature_flags f where f.key = 'shard_quests'
                and (f.mode = 'everyone' or (f.mode = 'test' and (uid = any(f.users)
                     or exists (select 1 from public.server_members m where m.user_id = uid and m.server_id = any(f.servers))))))
  then plus := 1.5; end if;
  return plus * coalesce((public.shard_event()->>'mult')::numeric, 1);
end; $function$;

-- public.shard_config()
CREATE OR REPLACE FUNCTION public.shard_config()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'daily', 5, 'per_block', 5, 'block_minutes', 5, 'activity_cap', 25, 'streak_days', 7, 'streak_bonus', 30,
    'min_age_days', 1, 'invite', 100, 'invite_age_days', 7, 'invite_active_days', 3, 'invite_cap_30d', 10,
    'artist_share', 70, 'seller_age_days', 5, 'price_min', 25, 'price_max', 5000, 'buyer_age_days', 7, 'level_step', 100, 'level_max', 100);
$function$;

-- public.shard_earn(p_user uuid, p_base integer, p_kind text, p_ref text, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.shard_earn(p_user uuid, p_base integer, p_kind text, p_ref text, p_note text DEFAULT ''::text)
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.shard_post(p_user, ceil(p_base * public.shard_boost(p_user))::int, p_kind, p_ref, p_note);
$function$;

-- public.shard_event()
CREATE OR REPLACE FUNCTION public.shard_event()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
begin
  if now() >= timestamptz '2026-10-26 10:00:00+00' and now() < timestamptz '2026-10-28 11:00:00+00' then
    return jsonb_build_object('mult', 2, 'label', '100K users', 'ends_at', '2026-10-28T11:00:00Z');
  end if;
  return null;
end; $function$;

-- public.shard_is_bot(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.shard_is_bot(uid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.bots b where b.id = uid)
      or exists (select 1 from public.bot_accounts a where a.user_id = uid)
      or exists (select 1 from public.profiles p where p.id = uid and 'bot' = any(coalesce(p.badges, '{}')));
$function$;

-- public.shard_post(p_user uuid, p_amount integer, p_kind text, p_ref text, p_note text, p_actor uuid, p_staff boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.shard_post(p_user uuid, p_amount integer, p_kind text, p_ref text, p_note text DEFAULT ''::text, p_actor uuid DEFAULT NULL::uuid, p_staff boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare w public.shard_wallets; nb int;
begin
  if p_amount is null or p_amount = 0 then raise exception 'Nothing to post'; end if;
  insert into public.shard_wallets (user_id) values (p_user) on conflict (user_id) do nothing;
  select * into w from public.shard_wallets where user_id = p_user for update;
  if not p_staff then
    if w.frozen or public.is_site_banned(p_user) then raise exception 'Your Shards are frozen'; end if;
  end if;
  if p_ref is not null and p_kind in ('daily', 'streak', 'invite', 'deco_buy', 'deco_sale', 'level_up', 'quest')
     and exists (select 1 from public.shard_ledger where user_id = p_user and kind = p_kind and ref = p_ref) then
    if p_amount < 0 then raise exception 'Already done'; end if;
    return null;
  end if;
  nb := w.balance + p_amount;
  if nb < 0 then raise exception 'Not enough Shards'; end if;
  insert into public.shard_ledger (user_id, amount, kind, ref, note, actor, balance_after)
    values (p_user, p_amount, p_kind, p_ref, left(coalesce(p_note, ''), 300), p_actor, nb);
  update public.shard_wallets set balance = nb,
      earned_total = earned_total + greatest(p_amount, 0),
      spent_total = spent_total + greatest(-p_amount, 0),
      updated_at = now()
    where user_id = p_user;
  return nb;
end; $function$;

