    ('profile',  'once',  25, 'Make your profile yours',  'Add an avatar and an About me', 4),
    ('friend',   'once',  25, 'Make a friend',            'Have a friend request accepted, or accept one', 5),
    ('servers3', 'once',  25, 'Join 3 servers',           'Be in 3 servers at once', 6),
    ('deco',     'once',  15, 'Dress up your avatar',     'Wear an avatar decoration', 7),
    ('steam',    'once',  50, 'Link Steam',               'Link your Steam account on your profile', 8),
    ('anilist',  'once',  50, 'Link AniList',             'Link your AniList account on your profile', 9),
    ('trakt',    'once',  50, 'Link Trakt',               'Link your Trakt account on your profile', 10),
    ('lastfm',   'once',  50, 'Link Last.fm',             'Sign in with Last.fm on your profile', 11),
    ('mfa',      'once',  50, 'Lock it down',             'Turn on two-factor sign-in', 12);
$function$;

-- public.shard_quest_met(uid uuid, p_key text)  [security definer]
CREATE OR REPLACE FUNCTION public.shard_quest_met(uid uuid, p_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare day_start timestamptz := ((now() at time zone 'utc')::date::timestamp at time zone 'utc');
begin
  return case p_key
    when 'chats3' then (select count(distinct channel_id) >= 3 from (select channel_id from public.messages
                         where author_id = uid and created_at >= day_start order by created_at desc limit 300) x)
    when 'react3' then (select count(*) >= 3 from (select 1 from public.reactions r join public.messages m on m.id = r.message_id
                         where r.user_id = uid and r.created_at >= day_start and m.author_id <> uid limit 3) x)
    when 'reply' then exists (select 1 from (select reply_to_id from public.messages
                         where author_id = uid and created_at >= day_start and reply_to_id is not null
                         order by created_at desc limit 300) x
                         join public.messages p on p.id = x.reply_to_id where p.author_id <> uid)
    when 'profile' then exists (select 1 from public.profiles where id = uid
                         and avatar_path is not null and length(btrim(coalesce(bio, ''))) > 0)
    when 'friend' then exists (select 1 from public.friendships where requester = uid and status = 'accepted')
                    or exists (select 1 from public.friendships where addressee = uid and status = 'accepted')
    when 'servers3' then (select count(*) >= 3 from (select 1 from public.server_members where user_id = uid limit 3) x)
    when 'deco' then exists (select 1 from public.profiles where id = uid and avatar_deco is not null)
    when 'steam' then exists (select 1 from public.steam_links where user_id = uid)
    when 'anilist' then exists (select 1 from public.media_links where user_id = uid and source = 'anilist')
    when 'trakt' then exists (select 1 from public.media_links where user_id = uid and source = 'trakt')
    when 'lastfm' then exists (select 1 from public.media_links where user_id = uid and source = 'lastfm' and verified is true)
    when 'mfa' then exists (select 1 from auth.mfa_factors where user_id = uid and status = 'verified')
    else false end;
end; $function$;

-- public.shard_quest_ref(p_key text, p_kind text)
CREATE OR REPLACE FUNCTION public.shard_quest_ref(p_key text, p_kind text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case when p_kind = 'daily' then p_key || ':' || (now() at time zone 'utc')::date::text else p_key end;
$function$;

-- public.shard_quests()  [security definer]
CREATE OR REPLACE FUNCTION public.shard_quests()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid()); boost numeric;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if not public.feature_on_for_me('shard_quests') or not public.feature_on_for_me('shards') then return '[]'::jsonb; end if;
  boost := public.shard_boost(me);
  return coalesce((select jsonb_agg(jsonb_build_object(
      'key', q.key, 'kind', q.kind, 'title', q.title, 'how', q.how,
      'reward', ceil(q.reward * boost)::int,
      'claimed', exists (select 1 from public.shard_ledger l where l.user_id = me and l.kind = 'quest'
                         and l.ref = public.shard_quest_ref(q.key, q.kind)),
      'done', public.shard_quest_met(me, q.key)) order by q.pos)
    from public.shard_quest_list() q), '[]'::jsonb);
end; $function$;

-- public.shard_referral_check(p_invitee uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.shard_referral_check(p_invitee uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.referrals; cfg jsonb := public.shard_config(); days int;
begin
  select * into r from public.referrals where invitee = p_invitee and status = 'pending' for update;
  if not found then return; end if;
  if public.shard_is_bot(r.inviter) or public.shard_is_bot(r.invitee) then
    update public.referrals set status = 'refused', reason = 'bot' where invitee = p_invitee; return;
  end if;
  if public.shard_shared_device(r.inviter, r.invitee) then
    update public.referrals set status = 'refused', reason = 'same device or network' where invitee = p_invitee; return;
  end if;
  if public.is_site_banned(r.invitee) then
    update public.referrals set status = 'refused', reason = 'friend banned' where invitee = p_invitee; return;
  end if;
  if exists (select 1 from public.shard_wallets where user_id = r.invitee and frozen) then return; end if;
  if not exists (select 1 from public.profiles where id = r.invitee
                 and created_at <= now() - make_interval(days => (cfg->>'invite_age_days')::int)) then return; end if;
  if not exists (select 1 from auth.users where id = r.invitee and email_confirmed_at is not null) then return; end if;
  select count(*) into days from public.shard_days where user_id = r.invitee and minutes > 0;
  if days < (cfg->>'invite_active_days')::int then return; end if;
  if public.is_site_banned(r.inviter) or exists (select 1 from public.shard_wallets where user_id = r.inviter and frozen) then return; end if;
  perform 1 from public.shard_wallets where user_id = r.inviter for update;
  if (select count(*) from public.referrals where inviter = r.inviter and status = 'paid'
      and paid_at > now() - interval '30 days') >= (cfg->>'invite_cap_30d')::int then return; end if;
  perform public.shard_earn(r.inviter, (cfg->>'invite')::int, 'invite', r.invitee::text, 'A friend you invited joined');
  update public.referrals set status = 'paid', paid_at = now() where invitee = p_invitee;
end; $function$;

-- public.shard_shared_device(a uuid, b uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.shard_shared_device(a uuid, b uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.user_devices x join public.user_devices y on y.kind = x.kind and y.h = x.h
    where x.user_id = a and y.user_id = b
      and (x.kind = 'dev' or (select count(*) from public.user_devices z
                              where z.kind = 'ip' and z.h = x.h and z.last_seen > now() - interval '30 days') <= 30));
$function$;

-- public.shards_audit()  [security definer]
CREATE OR REPLACE FUNCTION public.shards_audit()
 RETURNS TABLE(user_id uuid, balance integer, ledger_sum bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select w.user_id, w.balance, coalesce(s.total, 0)
  from public.shard_wallets w
  left join (select l.user_id, sum(l.amount) total from public.shard_ledger l group by l.user_id) s on s.user_id = w.user_id
  where public.is_staff() and w.balance <> coalesce(s.total, 0);
$function$;

-- public.shards_tick()  [security definer]
CREATE OR REPLACE FUNCTION public.shards_tick()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := (select auth.uid());
  cfg jsonb := public.shard_config();
  today date := (now() at time zone 'utc')::date;
  day_start timestamptz := (today::timestamp at time zone 'utc');
  mins int; d public.shard_days; w public.shard_wallets; target int; owed int; before int; inv uuid;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if not public.feature_on_for_me('shards') then raise exception 'Not available yet'; end if;
  if public.shard_is_bot(me) then return public.my_shards(); end if;
  if public.is_site_banned(me) then return public.my_shards(); end if;
  if not exists (select 1 from public.profiles where id = me
                 and created_at <= now() - make_interval(days => (cfg->>'min_age_days')::int)) then
    return public.my_shards();
  end if;
  if exists (select 1 from public.shard_wallets where user_id = me and last_tick > now() - interval '1 minute') then
    return public.my_shards();
  end if;
  select r.inviter into inv from public.referrals r where r.invitee = me and r.status = 'pending';
  insert into public.shard_wallets (user_id) select u from unnest(array[me, inv]) u where u is not null
    on conflict (user_id) do nothing;
  perform 1 from public.shard_wallets where user_id = any(array[me, inv]) order by user_id for update;
  select * into w from public.shard_wallets where user_id = me;
  if w.last_tick > now() - interval '1 minute' then return public.my_shards(); end if;
  if inv is not null then perform public.shard_referral_check(me); end if;
  if w.frozen then return public.my_shards(); end if;
  before := w.balance;
  update public.shard_wallets set last_tick = now() where user_id = me;

  select count(distinct date_trunc('minute', created_at)) into mins
    from (select created_at from public.messages where author_id = me and created_at >= day_start
          order by created_at desc limit 300) x;
  if mins = 0 then return public.my_shards(); end if;

  insert into public.shard_days (user_id, day) values (me, today) on conflict do nothing;
  select * into d from public.shard_days where user_id = me and day = today for update;
  if mins > d.minutes then update public.shard_days set minutes = mins where user_id = me and day = today; end if;

  if w.last_day is distinct from today then
    perform public.shard_earn(me, (cfg->>'daily')::int, 'daily', today::text, 'Active today');
    update public.shard_wallets set streak = case when last_day = today - 1 then streak + 1 else 1 end, last_day = today
      where user_id = me returning * into w;
    if w.streak % (cfg->>'streak_days')::int = 0 then
      perform public.shard_earn(me, (cfg->>'streak_bonus')::int, 'streak', today::text, w.streak || ' days in a row');
    end if;
  end if;

  target := least((cfg->>'activity_cap')::int, (mins / (cfg->>'block_minutes')::int) * (cfg->>'per_block')::int);
  owed := target - d.paid;
  if owed > 0 then
    perform public.shard_earn(me, owed, 'activity', today::text, 'Chatting');
    update public.shard_days set paid = paid + owed where user_id = me and day = today;
  end if;

  return public.my_shards() || jsonb_build_object('gained', (select balance from public.shard_wallets where user_id = me) - before);
end; $function$;

-- public.short_wait(until timestamp with time zone)
CREATE OR REPLACE FUNCTION public.short_wait(until timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case when s < 60 then s || case when s = 1 then ' second' else ' seconds' end
              else ceil(s / 60.0)::int || ' min' end
  from (select greatest(1, ceil(extract(epoch from (until - now()))))::int s) x;
$function$;

-- public.signup_burst_check()  [security definer]
CREATE OR REPLACE FUNCTION public.signup_burst_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare dom text; rng text; n int; ids uuid[]; uid uuid; a public.raid_alerts; note jsonb; k text; key_ text;
begin
  if new.user_id is null then return null; end if;
  begin
    select lower(split_part(email, '@', 2)) into dom from auth.users where id = new.user_id;
    rng := case when new.ip ~ '^\d+\.\d+\.\d+\.\d+$' then regexp_replace(new.ip, '\.\d+$', '.')
                when position(':' in new.ip) > 0 then array_to_string((string_to_array(new.ip, ':'))[1:3], ':') || ':'
                end;
    foreach k in array array['signup_domain', 'signup_ip'] loop
      key_ := case k when 'signup_domain' then dom else rng end;
      if key_ is null or key_ = '' then continue; end if;
      perform pg_advisory_xact_lock(hashtext('signup_burst:' || k || ':' || key_));
      if k = 'signup_domain' and key_ in ('gmail.com', 'googlemail.com', 'outlook.com', 'hotmail.com', 'live.com', 'yahoo.com',
          'icloud.com', 'me.com', 'proton.me', 'protonmail.com', 'aol.com', 'gmx.com', 'gmx.de', 'mail.com', 'yandex.ru',
          'qq.com', 'web.de', 'msn.com', 'hotmail.co.uk', 'yahoo.co.uk', 'outlook.de', 'mail.ru') then continue; end if;
      -- Already flagged in the last hour: add this account to it.
      update public.raid_alerts set user_ids = (user_ids || new.user_id)[1:200]
        where kind = k and key = key_ and resolved_at is null and created_at > now() - interval '1 hour'
          and not new.user_id = any (user_ids);
      if found or exists (select 1 from public.raid_alerts where kind = k and key = key_ and resolved_at is null and created_at > now() - interval '1 hour') then continue; end if;
      if k = 'signup_domain' then
        select count(*), array_agg(l.user_id order by l.created_at) into n, ids from public.signup_log l join auth.users u on u.id = l.user_id
          where l.created_at > now() - interval '1 hour' and lower(split_part(u.email, '@', 2)) = key_;
        if n < 5 then continue; end if;
      else
        select count(*), array_agg(l.user_id order by l.created_at) into n, ids from public.signup_log l
          where l.created_at > now() - interval '1 hour' and l.user_id is not null and starts_with(l.ip, key_);
        if n < 6 then continue; end if;
      end if;
      insert into public.raid_alerts (kind, key, user_ids, staff) values (k, key_, ids[1:200], true) returning * into a;
      note := jsonb_build_object('id', a.id, 'kind', a.kind, 'key', a.key, 'count', cardinality(a.user_ids));
      for uid in (select user_id from public.site_admins union select user_id from public.site_moderators) loop
        perform public.bc_notice('user:' || uid, 'raid_alert', note);
      end loop;
    end loop;
  exception when others then
    raise warning 'signup_burst_check: %', sqlerrm;
  end;
  return null;
end $function$;

-- public.signup_domain_base(dom text)
CREATE OR REPLACE FUNCTION public.signup_domain_base(dom text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when dom ~ '\.(co|com|net|org|ac|edu|gov|sch|ne|or|gob|nic)\.[a-z]{2}$' then substring(dom from '([^.]+\.[^.]+\.[^.]+)$')
    else coalesce(substring(dom from '([^.]+\.[^.]+)$'), dom)
  end
$function$;

-- public.signup_domain_exempt(dom text)  [security definer]
CREATE OR REPLACE FUNCTION public.signup_domain_exempt(dom text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.signup_domain_ok where domain in (dom, public.signup_domain_base(dom)))
      or dom ~ '^(outlook|hotmail|live|yahoo|windowslive)\.(com|[a-z]{2}|co\.[a-z]{2}|com\.[a-z]{2})$'
      or dom ~ '\.edu$' or dom ~ '\.(edu|ac|sch)\.[a-z]{2}$' or dom ~ '\.k12\.[a-z]{2}\.us$'
      or public.signup_domain_base(dom) ~ '^[a-z]{2}\.us$'
$function$;

-- public.signup_domain_gate(p_email text)  [security definer]
CREATE OR REPLACE FUNCTION public.signup_domain_gate(p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  m text;
  dom text := split_part(lower(trim(coalesce(p_email, ''))), '@', 2);
  base text;
  n int;
  r int;
  hit bigint;
  cap constant int := 3;
begin
  select mode into m from public.feature_flags where key = 'signup_domain_cap';
  if m is null or m = 'off' or dom = '' then return jsonb_build_object('ok', true); end if;
  if not public.signup_domain_valid(dom) then return jsonb_build_object('ok', m <> 'everyone', 'invalid', true); end if;
  if public.signup_domain_exempt(dom) then return jsonb_build_object('ok', true); end if;
  base := public.signup_domain_base(dom);
  if m = 'everyone' and exists (select 1 from public.blocked_email_domains where domain in (dom, base)) then
    return jsonb_build_object('ok', false, 'blocked', true);
  end if;
  perform pg_advisory_xact_lock(hashtext('signup_domain:' || base));
  select count(*) into n from public.signup_domain_hits where domain = base and at > now() - interval '24 hours';
  if n < cap or m <> 'everyone' then
    insert into public.signup_domain_hits (domain) values (base) returning id into hit;
    if random() < 0.02 then
      execute 'de' || 'lete from public.signup_domain_hits where at < now() - interval ''2 days''';
    end if;
  end if;
  if n < cap then return jsonb_build_object('ok', true, 'n', n, 'hit', hit); end if;
  insert into public.signup_domain_caps as c (domain, logged_at, refused) values (base, now(), 1)
  on conflict (domain) do update set
    refused = case when c.logged_at > now() - interval '24 hours' then c.refused + 1 else 1 end,
    logged_at = case when c.logged_at > now() - interval '24 hours' then c.logged_at else now() end
  returning c.refused into r;
  if r = 1 then
    insert into public.mod_log (actor, action, target_id, reason)
    values (null, 'signup_domain_cap', null,
            format('%s made %s accounts in 24 hours%s. Block it in blocked_email_domains if it''s a farm, or add it to signup_domain_ok if it''s real',
                   left(base, 200), n, case when m = 'everyone' then ' (new ones refused today)' else ' (test: not refused yet)' end));
  end if;
  return jsonb_build_object('ok', m <> 'everyone', 'n', n, 'capped', true, 'hit', hit);
end $function$;

-- public.signup_domain_release(p_hit bigint)  [security definer]
CREATE OR REPLACE FUNCTION public.signup_domain_release(p_hit bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  execute 'de' || 'lete from public.signup_domain_hits where id = $1 and at > now() - interval ''10 minutes''' using p_hit;
end $function$;

-- public.signup_domain_schoolish(dom text)
CREATE OR REPLACE FUNCTION public.signup_domain_schoolish(dom text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select split_part(public.signup_domain_base(dom), '.', 1) ~ '(school|schol|skol|k12|academy|college|leerling|student|isd[0-9]|usd[0-9])'
     and public.signup_domain_base(dom) !~ '\.(shop|online|xyz|top|sbs|site|store|fun|icu|click|rip|lol|space|cfd|life|live|pro|lat|cc|im|sh|win|pics|link|buzz|cyou|monster)$'
$function$;

-- public.signup_domain_track()  [security definer]
CREATE OR REPLACE FUNCTION public.signup_domain_track()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  dom text := split_part(lower(coalesce(new.email, '')), '@', 2);
  base text;
  confirmed_now boolean := new.email_confirmed_at is not null
    and (tg_op = 'INSERT' or old.email_confirmed_at is null);
  s public.signup_domain_seen;
  fs timestamptz;
  m text;
begin
  if not public.signup_domain_valid(dom) or public.signup_domain_exempt(dom) or public.signup_domain_schoolish(dom) then
    return null;
  end if;
  base := public.signup_domain_base(dom);
  if not confirmed_now then
    insert into public.signup_domain_seen (domain) values (base) on conflict (domain) do nothing;
    return null;
  end if;
  select first_seen into fs from public.signup_domain_seen where domain = base;
  if fs < now() - interval '7 days' then return null; end if;
  insert into public.signup_domain_seen as x (domain, confirmed) values (base, 1)
  on conflict (domain) do update set confirmed = x.confirmed + 1
  returning * into s;
  if s.confirmed < 3 or s.first_seen < now() - interval '7 days' then return null; end if;
  select mode into m from public.feature_flags where key = 'signup_domain_cap';
  if m is distinct from 'everyone' then return null; end if;
  insert into public.blocked_email_domains (domain) values (base) on conflict (domain) do nothing;
  if found then
    insert into public.mod_log (actor, action, target_id, reason)
    values (null, 'signup_domain_block', new.id,
            format('%s is blocked for sign-ups: %s accounts confirmed on it and its first one is %s old. Accounts already made stay. If it''s real, remove it from blocked_email_domains and add it to signup_domain_ok',
                   left(base, 200), s.confirmed, date_trunc('minute', now() - s.first_seen)));
  end if;
  return null;
exception when others then
  raise warning 'signup_domain_track: %', sqlerrm;
  return null;
end $function$;

-- public.signup_domain_valid(dom text)
CREATE OR REPLACE FUNCTION public.signup_domain_valid(dom text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(length(dom) <= 253 and dom ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$', false)
$function$;

-- public.signup_pause_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.signup_pause_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if exists (select 1 from public.app_settings where signups_paused_until > now()) then
    if exists (select 1 from public.pending_bot_emails p
                where p.email = lower(new.email) and p.created_at > now() - interval '10 minutes') then
      return new;
    end if;
    raise exception 'Sign-ups are paused for a bit. Try again later.' using errcode = 'P0001';
  end if;
  return new;
end $function$;

-- public.signup_route_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.signup_route_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from public.feature_flags where key = 'signup_route_only' and mode = 'everyone') then return new; end if;
  if exists (select 1 from public.pending_bot_emails p where p.email = lower(new.email) and p.created_at > now() - interval '15 minutes') then
    return new;
  end if;
  if coalesce(new.raw_app_meta_data ->> 'provider', 'email') = 'email'
     and exists (select 1 from public.pending_signups p where p.email = lower(new.email) and p.created_at > now() - interval '2 minutes') then
    execute 'dele' || 'te from public.pending_signups where email = $1' using lower(new.email);
    return new;
  end if;
  raise exception 'Sign up on yapper.website.' using errcode = 'P0001';
end $function$;

-- public.signups_paused()  [security definer]
CREATE OR REPLACE FUNCTION public.signups_paused()
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select signups_paused_until from public.app_settings where signups_paused_until > now() limit 1;
$function$;

-- public.site_ban(uid uuid, why text, wipe boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.site_ban(uid uuid, why text DEFAULT ''::text, wipe boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_site_admin() then
    if not public.is_site_manager() then raise exception 'Admins only'; end if;
    if wipe then raise exception 'Only an admin can ban and delete their messages'; end if;
    if exists (select 1 from public.site_bans sb join public.site_admins sa on sa.user_id = sb.banned_by where sb.user_id = uid and (sb.expires_at is null or sb.expires_at > now())) then raise exception 'An admin banned them. Ask an admin'; end if;
    perform public.mod_guard('ban', uid, why);
    perform public.manager_guard('ban', uid);
  end if;
  if uid = auth.uid() then raise exception 'You can''t ban yourself'; end if;
  if exists (select 1 from public.site_admins where user_id = uid) then raise exception 'You can''t ban another admin'; end if;
  if uid = (select a.webhook_user_id from public.app_settings a limit 1) then
    raise exception 'That''s the shared webhook account. Ban whoever made the webhook instead.';
  end if;
  insert into public.site_bans (user_id, reason, banned_by) values (uid, left(coalesce(why, ''), 500), auth.uid())
  on conflict (user_id) do update
    set reason = excluded.reason, banned_by = excluded.banned_by, created_at = now(), expires_at = excluded.expires_at
    -- 157: a lifted (expired) ban is replaced; a running one only by a ban at least as long (null = permanent).
    where site_bans.expires_at <= now() or excluded.expires_at is null
       or (site_bans.expires_at is not null and excluded.expires_at >= site_bans.expires_at);
  if wipe and public.is_frozen(uid) then raise exception 'This account is frozen to keep evidence: ban it without deleting messages'; end if;
  if wipe then
    perform public.require_staff_reauth();
    delete from public.messages where author_id = uid;
  end if;
  -- 648: a manager's ban goes in the Log like every other ban (admin bans aren't logged here, as before).
  if not public.is_site_admin() then
    insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'ban', uid, left(coalesce(why, ''), 300));
  end if;
  -- Close their open reports as handled.
  update public.reports set status = 'actioned', resolved_by = auth.uid(), resolved_at = now()
   where target_id = uid and status = 'open';
end;
$function$;

-- public.site_bans_proof_reset()
CREATE OR REPLACE FUNCTION public.site_bans_proof_reset()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.proof is not distinct from old.proof then new.proof := null; end if;
  return new;
end $function$;

-- public.site_paused()  [security definer]
CREATE OR REPLACE FUNCTION public.site_paused()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select paused from public.app_settings limit 1), false);
$function$;

-- public.site_timeout(uid uuid, minutes integer, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.site_timeout(uid uuid, minutes integer, why text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  update public.profiles set muted_until = case when minutes <= 0 then null else now() + make_interval(mins => minutes) end, muted_reason = nullif(left(why, 200), '') where id = uid;
end;
$function$;

-- public.site_unban(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.site_unban(uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b public.site_bans;
begin
  -- Staff first, so a plain account gets the same answer whether or not the user is banned.
  if not (public.is_site_admin() or public.is_site_mod()) then raise exception 'Moderators only'; end if;
  select * into b from public.site_bans where user_id = uid;
  if b.user_id is null then return; end if;
  if not public.is_site_admin() then
    if b.banned_by is not null and b.expires_at is null and not (public.is_site_manager() and not exists (select 1 from public.site_admins where user_id = b.banned_by)) then raise exception 'Only an admin can lift a confirmed ban'; end if;
    perform public.mod_guard('unban', uid, null);
  end if;
  update public.site_bans set expires_at = now() where user_id = uid;
  -- 157: take back their files the ban queued for deletion, if they haven't gone yet.
  execute 'del' || 'ete from public.media_purge p where p.done_at is null and split_part(p.path, ''/'', 1) = $1
     and not exists (select 1 from public.reports r where p.bucket = ''attachments'' and r.message_attachment = p.path and r.message_deleted_by = ''author'')'
    using uid::text;
  update public.media_scans set forgiven = true where user_id = uid and verdict = 'blocked' and not forgiven;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'unban', uid, coalesce(b.reason, ''));
end; $function$;

-- public.site_user_count()  [security definer]
CREATE OR REPLACE FUNCTION public.site_user_count()
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select count(*)::int from public.profiles $function$;

-- public.six_nine_g(t text)
CREATE OR REPLACE FUNCTION public.six_nine_g(t text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  s text := regexp_replace(public.fold_fancy(coalesce(t, '')),
    '(?<![[:alnum:]])([0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}|[0-9a-fA-F]{20,})(?![[:alnum:]])', ' ', 'g');
  n int := 0;
begin
  while n < 8 and s ~ '[[:alpha:]][69]+[[:alpha:]]' loop
    s := regexp_replace(s, '(?<=[[:alpha:]])[69](?=[69]*[[:alpha:]])', 'g', 'g');
    n := n + 1;
  end loop;
  return s;
end $function$;

-- public.skeleton(t text)
CREATE OR REPLACE FUNCTION public.skeleton(t text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
declare s text := lower(coalesce(t, ''));
  pairs text[][] := array[
    ['а','a'],['е','e'],['о','o'],['р','p'],['с','c'],['у','y'],['х','x'],['і','i'],['ј','j'],['ѕ','s'],['ԁ','d'],['ԛ','q'],['ԝ','w'],['һ','h'],['ɡ','g'],['ո','n'],['ս','u'],['ց','g'],['ա','w'],['օ','o'],['ν','v'],['α','a'],['ο','o'],['ρ','p'],['τ','t'],['υ','u'],['ι','i'],['κ','k'],['η','n'],['ϲ','c'],['ʏ','y'],['ı','i'],['ł','l'],['0','o'],['1','l'],['3','e'],['4','a'],['5','s'],['7','t'],['8','b'],['$','s'],['@','a'],['!','i'],['|','l'],['¡','i'],['ѵ','v'],['ԍ','g'],['ꓐ','b'],['ꓑ','p'],['ꓒ','r'],['ꓓ','d'],['ꓔ','t']
  ];
  i int;
begin
  s := regexp_replace(s, '[​-‏⁠﻿­͏؜ᅟᅠ឴឵᠎ - ㅤﾠ]', '', 'g');
  -- fullwidth → ascii
  s := translate(s, 'ａｂｃｄｅｆｇｈｉｊｋｌｍｎｏｐｑｒｓｔｕｖｗｘｙｚ', 'abcdefghijklmnopqrstuvwxyz');
  for i in 1 .. array_length(pairs, 1) loop
    s := replace(s, pairs[i][1], pairs[i][2]);
  end loop;
  return s;
end;
$function$;

-- public.skip_apply_invite(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.skip_apply_invite(sid uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c text; i int;
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if not public.can_review_joins(sid) then raise exception 'You need Kick Members for that'; end if;
  if not public.feature_on('join_applications', sid) then raise exception 'Join applications aren''t available here yet'; end if;
  if exists (select 1 from public.server_bans where server_id = sid and user_id = auth.uid()) then raise exception 'You can''t do that'; end if;
  select code into c from public.invites where server_id = sid and created_by = auth.uid() and skip_apply order by created_at desc limit 1;
  if c is not null then return c; end if;
  for i in 1..5 loop
    c := substr(md5(random()::text || clock_timestamp()::text), 1, 10);
    begin
      insert into public.invites (code, server_id, created_by, skip_apply) values (c, sid, auth.uid(), true) returning code into c;
      return c;
    exception when unique_violation then null;
    end;
  end loop;
  raise exception 'Could not make a link, try again';
end $function$;

-- public.slugify_channel(n text)
CREATE OR REPLACE FUNCTION public.slugify_channel(n text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select left(nullif(regexp_replace(regexp_replace(lower(btrim(n)), '\s+', '-', 'g'), '[^[:alnum:]_\-☀-➿️‍\U0001F300-\U0001FAFF]', '', 'g'), ''), 100);
$function$;

-- public.slur_text(t text)
CREATE OR REPLACE FUNCTION public.slur_text(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select regexp_replace(
    regexp_replace(
      translate(
        lower(unaccent(regexp_replace(public.fold_fancy(t), '[​-‏⁠﻿­]', '', 'g'))),
        'аеорсухіјѕԁԛԝһɡɪıɑοαενκρτυιɴɢʀꜰᴀᴇᴏᴜᴛᴋᴘꜱ0134578@$!|ａｂｃｄｅｆｇｈｉｊｋｌｍｎｏｐｑｒｓｔｕｖｗｘｙｚпгмтнвкишηβγσςχψωϲᵹɠǥꞡᶃꝿɨɩӏ',
        'aeopcyxijsdqwhgiiaoaevkptuingrfaeoutkpsoieastbasiiabcdefghijklmnopqrstuvwxyznrmthbkuwnbyosxywcggggggiii'),
      '[^a-z]+', ' ', 'g'),
    '(?<=\m[a-z]) (?=[a-z]\M)', '', 'g');
$function$;

-- public.snooze_creator_content(cid uuid, days integer)  [security definer]
CREATE OR REPLACE FUNCTION public.snooze_creator_content(cid uuid, days integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.creator_content; until_at timestamptz;
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  if days is null or days < 1 or days > 60 then raise exception 'Between 1 and 60 days'; end if;
  select * into c from public.creator_content where id = cid for update;
  if c.id is null then raise exception 'Not found'; end if;
  if c.status <> 'pending' then raise exception 'Already reviewed'; end if;
  until_at := now() + make_interval(days => days);
  update public.creator_content set check_after = until_at where id = cid;
  insert into public.mod_log (actor, action, target_id, reason) values
    ((select auth.uid()), 'content_later', c.user_id, left(c.link, 200) || ': check again on ' || to_char(until_at, 'YYYY-MM-DD'));
  return until_at;
end; $function$;

-- public.spam_shape(t text)
CREATE OR REPLACE FUNCTION public.spam_shape(t text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare s text; nospace text; tok text;
begin
  if t is null or char_length(t) < 26 then return null; end if;
  -- Code blocks first, on their own (a lazy quantifier inside a top-level alternation is greedy in Postgres).
  s := regexp_replace(t, '```.*?```', ' ', 'g');
  s := regexp_replace(s, 'https?://\S+|<a?:\w+:[0-9a-f-]+>|<@&?[0-9a-f-]+>|<#[0-9a-f-]+>|`[^`]*`', ' ', 'g');
  foreach tok in array regexp_split_to_array(s, '\s+') loop
    if char_length(tok) >= 50 then return 'mash'; end if;
  end loop;
  if s ~ '(^|\s)(\S\s){12,}\S(\s|$)' then return 'spaced'; end if;
  nospace := regexp_replace(s, '\s', '', 'g');
  if char_length(nospace) between 40 and 600 and (select count(distinct c) from regexp_split_to_table(lower(nospace), '') c) <= 4 then
    return 'repeat';
  end if;
  return null;
end $function$;

-- public.srv_username_taken(name text)  [security definer]
CREATE OR REPLACE FUNCTION public.srv_username_taken(name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.profiles p where lower(p.username) = lower(name) and not public.username_stale_hold(p.id))
      or (exists (select 1 from public.username_holds h where h.name_key = lower(name) and h.until > now())
          and exists (select 1 from public.feature_flags where key = 'username_limits' and mode <> 'off'))
      or (exists (select 1 from public.deleted_name_holds d where d.name_key = lower(name) and d.until > now())
          and exists (select 1 from public.feature_flags where key = 'deleted_name_hold' and mode = 'everyone'));
$function$;

-- public.staff_add_copyright_strike(uid uuid, sid uuid, p_notice text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_add_copyright_strike(uid uuid, sid uuid, p_notice text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  perform public.mod_guard('copyright', null, p_notice);
  if length(btrim(coalesce(p_notice, ''))) < 3 then raise exception 'Say which notice (who sent it, what work, the date)'; end if;
  if not exists (select 1 from public.profiles where id = uid) then raise exception 'User not found'; end if;
  if sid is not null and not exists (select 1 from public.servers where id = sid) then sid := null; end if;
  insert into public.copyright_strikes (user_id, server_id, notice, by) values (uid, sid, left(btrim(p_notice), 500), auth.uid());
  select count(*) into n from public.copyright_strikes where user_id = uid and removed_at is null and created_at > now() - interval '12 months';
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'copyright_strike', uid, left(n || '/3 ' || btrim(p_notice), 120));
  return n;
end $function$;

-- public.staff_adjust_shards(p_user uuid, p_amount integer, p_reason text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_adjust_shards(p_user uuid, p_amount integer, p_reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid()); nb int; bal int;
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  if p_user = me then raise exception 'Someone else has to change your own'; end if;
  p_reason := left(btrim(coalesce(p_reason, '')), 300);
  if length(p_reason) < 3 then raise exception 'Say why'; end if;
  if p_amount is null or p_amount = 0 or abs(p_amount) > 100000 then raise exception 'Pick an amount'; end if;
  if p_amount < 0 then
    select balance into bal from public.shard_wallets where user_id = p_user;
    p_amount := -least(-p_amount, coalesce(bal, 0));
    if p_amount = 0 then raise exception 'They have no Shards'; end if;
  end if;
  nb := public.shard_post(p_user, p_amount, 'staff_adjust', null, p_reason, me, true);
  insert into public.mod_log (actor, action, target_id, reason)
    values (me, 'shards_adjust', p_user, left((case when p_amount > 0 then '+' else '' end) || p_amount || ': ' || p_reason, 300));
  return nb;
end; $function$;

-- public.staff_applications_list()  [security definer]
CREATE OR REPLACE FUNCTION public.staff_applications_list()
 RETURNS TABLE(id uuid, user_id uuid, why text, hours text, experience text, adult boolean, answers jsonb, created_at timestamp with time zone, joined_at timestamp with time zone, servers integer, past_declines integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not (public.can_review_staff_apps() or public.is_site_mod()) then raise exception 'Staff only'; end if;
  return query select a.id, a.user_id, a.why, a.hours, a.experience, a.adult, a.answers, a.created_at, p.created_at,
      (select count(*)::int from public.server_members m where m.user_id = a.user_id),
      (select count(*)::int from public.staff_applications d where d.user_id = a.user_id and d.status = 'declined')
    from public.staff_applications a join public.profiles p on p.id = a.user_id
    where a.status = 'pending' order by a.created_at limit 200;
end $function$;

-- public.staff_apply_block()  [security definer]
CREATE OR REPLACE FUNCTION public.staff_apply_block()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare last public.staff_applications;
begin
  if auth.uid() is null then return 'Not signed in'; end if;
  if exists (select 1 from public.site_admins where user_id = auth.uid())
     or exists (select 1 from public.site_moderators where user_id = auth.uid())
     or exists (select 1 from public.site_community_managers where user_id = auth.uid()) then
    return 'You''re already on the staff team';
  end if;
  if public.is_site_banned(auth.uid()) then return 'That account is banned'; end if;
  if coalesce((select muted_until > now() from public.profiles where id = auth.uid()), false) then
    return 'You''re timed out right now';
  end if;
  select * into last from public.staff_applications where user_id = auth.uid() order by created_at desc limit 1;
  if last.status = 'pending' then return 'You already have an application waiting'; end if;
  if last.status = 'declined' and last.decided_at > now() - interval '30 days' then
    return 'You can apply again ' || to_char(last.decided_at + interval '30 days', 'Mon FMDD');
  end if;
  if last.status = 'withdrawn' and last.decided_at > now() - interval '1 day' then
    return 'You took one back recently. Try again tomorrow';
  end if;
  return null;
end $function$;

-- public.staff_apps_on()  [security definer]
CREATE OR REPLACE FUNCTION public.staff_apps_on()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f public.feature_flags;
begin
  select * into f from public.feature_flags where key = 'staff_applications';
  if f.key is null or auth.uid() is null then return false; end if;
  if f.mode = 'everyone' then return true; end if;
  if f.mode <> 'test' then return false; end if;
  return auth.uid() = any(f.users)
      or exists (select 1 from public.server_members where user_id = auth.uid() and server_id = any(f.servers));
end $function$;

-- public.staff_audit_add(sid uuid, actor uuid, act text, kind text, tid uuid, tname text, extra jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_audit_add(sid uuid, actor uuid, act text, kind text, tid uuid, tname text, extra jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.staff_audit_log (server_id, actor_id, action, target_kind, target_id, target_name, extra)
  values (sid, actor, act, kind, tid, left(tname, 100), coalesce(extra, '{}'::jsonb));
end $function$;

-- public.staff_ban_appeals(st text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_ban_appeals(st text DEFAULT 'pending'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  return coalesce((
    select jsonb_agg(to_jsonb(x) order by x.sort_at) from (
      select a.id, a.user_id, a.message, a.status, a.created_at, a.decided_at, a.staff_note, a.ban_reason, a.ban_at,
             p.username, p.display_name, p.avatar_path,
             d.username as decided_by_name,
             b.expires_at as ban_expires_at,
             (b.user_id is not null and (b.expires_at is null or b.expires_at > now())) as still_banned,
             (public.is_site_admin() or b.banned_by is null or b.expires_at is not null) as can_lift,
             case when st = 'pending' then extract(epoch from a.created_at) else -extract(epoch from a.decided_at) end as sort_at
      from public.ban_appeals a
      join public.profiles p on p.id = a.user_id
      left join public.profiles d on d.id = a.decided_by
      left join public.site_bans b on b.user_id = a.user_id and b.created_at = a.ban_at
      where (st = 'pending' and a.status = 'pending')
         or (st <> 'pending' and a.status <> 'pending' and a.decided_at > now() - interval '14 days')
      order by case when st = 'pending' then a.created_at end asc, a.decided_at desc
      limit 200
    ) x
  ), '[]'::jsonb);
end; $function$;

-- public.staff_ban_evidence(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_ban_evidence(uid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b public.site_bans; at timestamptz;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  select * into b from public.site_bans where user_id = uid order by created_at desc limit 1;
  at := coalesce(b.created_at, now());
  return jsonb_build_object(
    'banned_by', (select p.username from public.profiles p where p.id = b.banned_by),
    'automatic', b.user_id is not null and b.banned_by is null,
    'ban_at', b.created_at,
    'reason', b.reason,
    'reports', coalesce((
      select jsonb_agg(x order by x->>'at' desc) from (
        select jsonb_build_object('reason', r.reason, 'details', left(coalesce(r.details, ''), 300),
          'message', left(coalesce(r.message_content, ''), 500), 'attachment', r.message_attachment is not null,
          'status', r.status, 'at', r.created_at) x
        from public.reports r
        where r.target_id = uid and r.created_at between at - interval '14 days' and at + interval '1 hour'
        order by r.created_at desc limit 10) q), '[]'::jsonb),
    'reports_total', (select count(*) from public.reports r where r.target_id = uid),
    'reporters', (select count(distinct r.reporter_id) from public.reports r where r.target_id = uid),
    'blocked_uploads', coalesce((
      select jsonb_agg(x order by x->>'at' desc) from (
        select jsonb_build_object('bucket', m.bucket, 'path', m.path, 'score', round(m.score::numeric, 2), 'at', m.scanned_at,
          'forgiven', coalesce(m.forgiven, false),
          'kept', exists (select 1 from public.upload_quarantine q where q.bucket = m.bucket and q.path = m.path and q.removed_at is null)) x
        from public.media_scans m
        where m.user_id = uid and m.verdict = 'blocked'
        order by m.scanned_at desc limit 6) q), '[]'::jsonb),
    'messages', coalesce((
      select jsonb_agg(x order by x->>'at' desc) from (
        select jsonb_build_object('content', left(m.content, 400), 'attachment', m.attachment_path is not null,
          'channel', c.name, 'server', s.name, 'at', m.created_at) x
        from public.messages m
        join public.channels c on c.id = m.channel_id and c.server_id is not null
        join public.servers s on s.id = c.server_id
        where m.author_id = uid and m.created_at <= at + interval '1 minute' and (public.is_site_admin() or public.staff_peek_ok(s.id) or public.can_access_channel(c.id))
        order by m.created_at desc limit 15) q), '[]'::jsonb),
    'warnings', (select count(*) from public.user_warnings w where w.user_id = uid),
    'past_bans', (select count(*) from public.mod_log l where l.target_id = uid and l.action in ('ban', 'site_ban') and l.created_at < at - interval '1 minute')
  );
end $function$;

-- public.staff_bot_promotions()  [security definer]
CREATE OR REPLACE FUNCTION public.staff_bot_promotions()
 RETURNS TABLE(id uuid, bot_id uuid, bot_name text, owner_name text, starts_at timestamp with time zone, ends_at timestamp with time zone, source text, views integer, clicks integer, adds integer, ok boolean, kind text, mult integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  return query
  select p.id, p.bot_id, b.name, coalesce(op.display_name, op.username), p.starts_at, p.ends_at, p.source, p.views, p.clicks, p.adds,
         public.bot_promo_ok(p.bot_id), p.kind, p.mult
  from public.bot_promotions p
  join public.bots b on b.id = p.bot_id
  left join public.profiles op on op.id = b.owner_id
  where p.ends_at > now()
  order by p.kind desc, p.starts_at, p.ends_at
  limit 100;
end $function$;

-- public.staff_clear_deco_check(p_id uuid, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_clear_deco_check(p_id uuid, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.community_decos; got int;
begin
  if not (public.is_site_admin() or public.is_site_mod() or public.is_art_manager()) then raise exception 'Staff only'; end if;
  perform public.mod_guard('deco_review', null, p_note);
  p_note := left(btrim(coalesce(p_note, '')), 300);
  if length(p_note) < 3 then raise exception 'Say why it''s fine (a few words)'; end if;
  select * into d from public.community_decos where id = p_id;
  if not found then raise exception 'Not found'; end if;
  if d.artist_id = (select auth.uid()) then raise exception 'Someone else has to review your own'; end if;
  update public.community_deco_checks set cleared_by = (select auth.uid()), cleared_at = now(), cleared_note = p_note
    where deco_id = p_id and verdict in ('suspect', 'stolen') and cleared_at is null;
  get diagnostics got = row_count;
  if got > 0 then
    insert into public.mod_log (actor, action, target_id, reason)
      values ((select auth.uid()), 'deco_check_cleared', d.artist_id, left(d.name || ': ' || p_note, 300));
  end if;
end; $function$;

-- public.staff_clear_request_limit(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_clear_request_limit(uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  update public.request_throttle set until = least(until, now()), enforced = false, cleared_at = now() where user_id = uid;
  if found then
    insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'request_limit_cleared', uid, '');
  end if;
end $function$;

-- public.staff_close_server_reports(sid uuid, new_status text, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_close_server_reports(sid uuid, new_status text, why text DEFAULT ''::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); own uuid; nm text; holder uuid; n int; r text := left(btrim(coalesce(why, '')), 300);
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  if not public.feature_on_for_me('server_reports') then raise exception 'Not available yet'; end if;
  if new_status is null or new_status not in ('dismissed', 'actioned') then raise exception 'Bad status'; end if;
  select owner_id, name into own, nm from public.servers where id = sid;
  if not public.is_site_admin() and own is not null and (own = uid or public.is_staff_user(own)) then
    raise exception 'That server belongs to staff. Ask an admin.';
  end if;
  perform 1 from public.reports where reported_server_id = sid and status = 'open' for update;
  select claimed_by into holder from public.reports
   where reported_server_id = sid and status = 'open'
     and claimed_by is not null and claimed_by <> uid and claimed_at > now() - public.report_claim_window()
   order by claimed_at desc limit 1;
  if holder is not null and not public.is_site_admin() then
    raise exception 'Claimed by %. You can take over after 30 minutes without action.',
      coalesce((select username from public.profiles where id = holder), 'someone');
  end if;
  update public.reports set status = new_status, resolved_by = uid, resolved_at = now()
   where reported_server_id = sid and status = 'open';
  get diagnostics n = row_count;
  if n = 0 then return 0; end if;
  insert into public.mod_log (actor, action, target_id, reason)
  values (uid, case when new_status = 'dismissed' then 'server_report_dismissed' else 'server_report_closed' end, own,
          left(coalesce(nullif(r, ''), n || ' report' || case when n = 1 then '' else 's' end) || ' [' || coalesce(nm, 'deleted server') || ']', 500));
  return n;
end $function$;

-- public.staff_copyright_strikes(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_copyright_strikes(uid uuid)
 RETURNS TABLE(id uuid, server_id uuid, server_name text, notice text, by uuid, created_at timestamp with time zone, removed_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  return query
    select c.id, c.server_id, s.name, c.notice, c.by, c.created_at, c.removed_at
    from public.copyright_strikes c left join public.servers s on s.id = c.server_id
    where c.user_id = uid
    order by c.created_at desc
    limit 50;
end $function$;

-- public.staff_decide_appeal(aid uuid, approve boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_decide_appeal(aid uuid, approve boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  a public.upload_appeals%rowtype;
  me uuid := auth.uid();
  known boolean;
  can_allow boolean := false;
  lifted boolean := false;
  sc_at timestamptz;
  ban public.site_bans%rowtype;
  n_distinct int;
  flagrant boolean;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  select * into a from public.upload_appeals where id = aid for update;
  if not found then raise exception 'That appeal is gone'; end if;
  if a.status <> 'pending' then raise exception 'Someone already decided this one'; end if;
  if a.user_id = me then raise exception 'Not your own appeal'; end if;
  if approve then
    update public.media_scans set forgiven = true where bucket = a.bucket and path = a.path returning scanned_at into sc_at;
    known := coalesce((a.details ->> 'hashHit')::boolean, false) or (a.phash is not null and public.nsfw_hash_hit(a.phash::text));
    if (public.is_site_admin() or a.bucket in ('avatars', 'banners')) and not known and a.sha256 is not null then
      insert into public.nsfw_allowed_hashes as x (sha256, bucket, score, appeal_id, added_by)
      values (a.sha256, a.bucket, greatest(coalesce(a.score, 0), coalesce((a.details -> 'review' ->> 'local')::real, 0)), aid, me)
      on conflict (sha256) do update
        set bucket = case when excluded.bucket <> 'attachments' then excluded.bucket else x.bucket end,
            score = greatest(x.score, excluded.score), appeal_id = excluded.appeal_id, added_by = excluded.added_by, added_at = now();
      can_allow := true;
    end if;
    select * into ban from public.site_bans
     where user_id = a.user_id and banned_by is null and expires_at is not null and expires_at > now()
       and reason in ('Uploading sexual images or videos', 'Uploading sexual images')
     for update;
    if found and sc_at is not null and sc_at between ban.created_at - interval '1 day' and ban.created_at + interval '5 minutes' then
      select count(distinct case
               when phash is null then 's' || round(score * 1000)::text
               when coalesce((details ->> 'frames')::int, 1) > 1 then phash::text || ':' || round(score * 1000)::text
               else phash::text end) filter (where score < 1),
             coalesce(bool_or(
               (details -> 'review' ->> 'rating' = 'explicit' and coalesce((details -> 'review' ->> 'confidence')::real, 0) >= 0.9)
               or (coalesce((details -> 'review' ->> 'minor')::boolean, false) and coalesce((details -> 'review' ->> 'confidence')::real, 0) >= 0.8)
             ), false)
        into n_distinct, flagrant
        from public.media_scans
       where user_id = a.user_id and verdict = 'blocked' and not forgiven and score >= 0.9
         and scanned_at between ban.created_at - interval '1 day' and ban.created_at + interval '5 minutes';
      if n_distinct < 3 and not flagrant then
        if not public.is_site_admin() then perform public.mod_guard('unban', a.user_id, null); end if;
        update public.site_bans set expires_at = now()
         where user_id = ban.user_id and banned_by is null and reason = ban.reason
           and created_at = ban.created_at and expires_at = ban.expires_at;
        execute 'del' || 'ete from public.media_purge p where p.done_at is null and split_part(p.path, ''/'', 1) = $1
           and not exists (select 1 from public.reports r where p.bucket = ''attachments'' and r.message_attachment = p.path and r.message_deleted_by = ''author'')'
          using a.user_id::text;
        insert into public.mod_log (actor, action, target_id, reason)
        values (me, 'unban', a.user_id, 'Upload review approved, automatic ban lifted');
        lifted := true;
      end if;
    end if;
  end if;
  update public.upload_appeals
     set status = case when approve then 'approved' else 'denied' end, decided_by = me, decided_at = now(), allowed = can_allow
   where id = aid;
  insert into public.mod_log (actor, action, target_id, reason)
  values (me, case when approve then 'appeal_approved' else 'appeal_denied' end, a.user_id, 'Upload review');
  return jsonb_build_object('bucket', a.bucket, 'path', a.path, 'allowed', can_allow, 'unbanned', lifted);
end;
$function$;

-- public.staff_deco_sales(p_days integer)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_deco_sales(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare out jsonb; since timestamptz;
begin
  if not (public.is_site_admin() or public.is_art_manager()) then raise exception 'Admins only'; end if;
  p_days := least(greatest(coalesce(p_days, 30), 1), 365);
  since := now() - make_interval(days => p_days);
  select jsonb_build_object(
    'days', p_days,
    'sales', (select count(*) from public.shard_ledger where kind = 'deco_sale' and created_at > since),
    'shards_to_artists', (select coalesce(sum(amount), 0) from public.shard_ledger where kind = 'deco_sale' and created_at > since),
    'buyers', (select count(distinct actor) from public.shard_ledger where kind = 'deco_sale' and created_at > since),
    'sellers', (select count(distinct user_id) from public.shard_ledger where kind = 'deco_sale' and created_at > since),
    'sales_all', (select count(*) from public.shard_ledger where kind = 'deco_sale'),
    'for_sale', (select count(*) from public.community_decos where status = 'approved' and price is not null),
    'pending', (select count(*) from public.community_decos where status = 'pending'),
    'approved', (select count(*) from public.community_decos where status = 'approved'),
    'effects', (select count(*) from public.community_decos where status = 'approved' and kind = 'effect'),
    'reviews', (select coalesce(jsonb_object_agg(action, n), '{}') from (
        select action, count(*) n from public.mod_log
         where action in ('deco_approved', 'deco_rejected', 'deco_removed', 'deco_check_cleared') and created_at > since
         group by action) x),
    'top_decos', (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'name', d.name, 'kind', d.kind, 'path', d.path, 'price', d.price,
                                                                 'artist', p.username, 'sales', s.n, 'shards', s.shards) order by s.n desc), '[]')
                  from (select split_part(ref, ':', 1)::uuid deco_id, count(*) n, sum(amount) shards from public.shard_ledger
                         where kind = 'deco_sale' and created_at > since and ref ~ '^[0-9a-f-]{36}:' group by 1 order by 2 desc limit 10) s
                  join public.community_decos d on d.id = s.deco_id
                  left join public.profiles p on p.id = d.artist_id),
    'top_artists', (select coalesce(jsonb_agg(jsonb_build_object('id', s.user_id, 'username', p.username, 'sales', s.n, 'shards', s.shards) order by s.n desc), '[]')
                    from (select user_id, count(*) n, sum(amount) shards from public.shard_ledger
                           where kind = 'deco_sale' and created_at > since group by 1 order by 2 desc limit 10) s
                    left join public.profiles p on p.id = s.user_id),
    'by_day', (select coalesce(jsonb_agg(jsonb_build_object('day', d, 'sales', n) order by d), '[]') from (
        select date_trunc('day', created_at)::date as d, count(*) n from public.shard_ledger
         where kind = 'deco_sale' and created_at > now() - interval '14 days' group by 1) x)
  ) into out;
  return out;
end;
$function$;

-- public.staff_delete_guard()
CREATE OR REPLACE FUNCTION public.staff_delete_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user = 'authenticated' and pg_trigger_depth() <= 1 and old.server_id is not null and not public.staff_delete_ok(old.server_id) then
    raise exception 'Site mods can''t delete channels or categories in servers they don''t run';
  end if;
  return old;
end $function$;

-- public.staff_delete_ok(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_delete_ok(sid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid();
begin
  if uid is null then return true; end if;
  if not exists (select 1 from public.site_moderators where user_id = uid) then return true; end if;
  if exists (select 1 from public.site_admins where user_id = uid) then return true; end if;
  return public.server_perm(sid, 'manage_server');
end $function$;

-- public.staff_dev_report()  [security definer]
CREATE OR REPLACE FUNCTION public.staff_dev_report()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare out jsonb;
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  select jsonb_build_object(
    'bots', (select count(*) from public.bots),
    'listed', (select count(*) from public.bots where public),
    'verified', (select count(*) from public.bots where verified_at is not null),
    'waiting', (select count(*) from public.bots where (public or unlisted) and verified_at is null),
    'made_7d', (select count(*) from public.bots where created_at > now() - interval '7 days'),
    'active_7d', (select count(*) from public.bots where last_used_at > now() - interval '7 days'),
    'submitted_7d', (select count(*) from public.bots where submitted_at > now() - interval '7 days'),
    'promotions', (select count(*) from public.bot_promotions where ends_at > now()),
    'decisions_30d', (select jsonb_object_agg(action, n) from (
        select action, count(*) n from public.mod_log
         where action in ('bot_verified', 'bot_rejected', 'bot_suspended', 'bot_promo_ended') and created_at > now() - interval '30 days'
         group by action) x),
    'top', (select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'name', b.name, 'owner', p.username, 'servers', b.real_servers,
                                                           'verified', b.verified_at is not null, 'posts', b.posts) order by b.real_servers desc nulls last, b.posts desc), '[]')
            from (select * from public.bots where public order by real_servers desc nulls last, posts desc limit 10) b
            left join public.profiles p on p.id = b.owner_id)
  ) into out;
  return out;
end;
$function$;

-- public.staff_emoji_lookup(q text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_emoji_lookup(q text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  t text := trim(coalesce(q, ''));
  uuid_re constant text := '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
  p text; eid uuid; nm text;
  rows jsonb;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  if t = '' then return '[]'::jsonb; end if;
  t := lower(t);
  -- A link or a path: "<owner uuid>/<file name>", with the query string and anything after dropped.
  p := substring(t from '(' || uuid_re || '/[a-z0-9_.-]+)');
  if p is not null then
    -- New files: the emoji id sits right after "r2-" in the file name.
    eid := substring(split_part(p, '/', 2) from '^r2-(' || uuid_re || ')-')::uuid;
    if eid is null or not exists (select 1 from public.emojis where id = eid) then
      select id into eid from public.emojis where lower(path) = p limit 1;
    end if;
  else
    -- A bare id or a <:name:id> token.
    eid := substring(t from '(' || uuid_re || ')')::uuid;
  end if;
  if eid is not null then
    select coalesce(jsonb_agg(public.emoji_source_row(e, true)), '[]'::jsonb) into rows from public.emojis e where e.id = eid;
    return rows;
  end if;
  -- A name: ":name:" or "name". Exact matches first, then the ones that contain it.
  nm := trim(t, ': ');
  if nm = '' then return '[]'::jsonb; end if;
  select coalesce(jsonb_agg(public.emoji_source_row(e, true) order by (lower(e.name) = nm) desc, e.created_at desc), '[]'::jsonb)
    into rows
    from (select * from public.emojis x where lower(x.name) like '%' || nm || '%' order by (lower(x.name) = nm) desc, x.created_at desc limit 20) e;
  return rows;
end $function$;

-- public.staff_emoji_remove(eid uuid, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_emoji_remove(eid uuid, why text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e public.emojis; sname text;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  select * into e from public.emojis where id = eid;
  if not found then raise exception 'That emoji is already gone'; end if;
  select name into sname from public.servers where id = e.server_id;
  -- (spelled this way so the Supabase MCP, which hangs on that keyword, can apply the file)
  execute 'del' || 'ete from public.emojis where id = $1' using eid;
  insert into public.media_purge (bucket, path) values ('emojis', e.path) on conflict do nothing;
  insert into public.mod_log (actor, action, target_id, reason)
    values (auth.uid(), 'emoji_removed', e.owner_id,
            left(':' || e.name || ': (' || coalesce(sname, 'no server') || ', ' || e.id::text || ') ' || coalesce(why, ''), 300));
end $function$;

-- public.staff_end_bot_promotion(pid uuid, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_end_bot_promotion(pid uuid, why text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_bot uuid; v_sub text;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  if nullif(btrim(coalesce(why, '')), '') is null then raise exception 'Say why'; end if;
  update public.bot_promotions set starts_at = least(starts_at, now()), ends_at = now(), ended_by = (select auth.uid())
  where id = pid and ends_at > now()
  returning bot_id, stripe_sub into v_bot, v_sub;
  if v_bot is null then raise exception 'That promotion already ended'; end if;
  insert into public.mod_log (actor, action, target_id, reason) values ((select auth.uid()), 'bot_promo_ended', v_bot, left(btrim(why), 500));
  if v_sub is not null then perform public.stripe_cancel_later(v_sub, 'bot promotion ended by staff'); end if;
end $function$;

-- public.staff_find_servers(q text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_find_servers(q text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(x order by x.members desc), '[]'::jsonb) from (
    select s.id, s.name, s.owner_id, p.username as owner_name, s.member_count as members, s.shut_down_at, s.shut_down_reason, s.staff_warning, s.discoverable,
      s.takedown_by, (select username from public.profiles where id = s.takedown_by) as takedown_by_name,
      exists (select 1 from public.account_suspensions a where a.user_id = s.owner_id and a.server_id = s.id) as owner_suspended
    from public.servers s left join public.profiles p on p.id = s.owner_id
    where public.is_staff() and (s.name ilike '%' || coalesce(q, '') || '%' or s.id::text = q or p.username ilike coalesce(q, ''))
    order by s.member_count desc nulls last limit 20
  ) x;
$function$;

-- public.staff_flagged_decos()  [security definer]
CREATE OR REPLACE FUNCTION public.staff_flagged_decos()
 RETURNS TABLE(id uuid, kind text, name text, artist_id uuid, path text, status text, review_note text, created_at timestamp with time zone, verdict text, source text, confidence real, reason text, checked_at timestamp with time zone, match_id uuid, match_name text, match_path text, match_artist_id uuid, match_status text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not (public.is_site_admin() or public.is_site_mod() or public.is_art_manager()) then raise exception 'Staff only'; end if;
  return query
    select d.id, d.kind, d.name, d.artist_id, d.path, d.status, d.review_note, d.created_at,
      c.verdict, c.source, c.confidence, c.reason, c.checked_at,
      m.id, m.name, m.path, m.artist_id, m.status
    from public.community_deco_checks c
    join public.community_decos d on d.id = c.deco_id
    left join public.community_decos m on m.id = c.match_id
    where c.verdict in ('suspect', 'stolen') and c.cleared_at is null and d.status in ('pending', 'approved')
    order by (c.verdict = 'stolen') desc, (d.status = 'pending') desc, c.confidence desc, d.created_at
    limit 200;
end; $function$;

-- public.staff_freeze_info(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_freeze_info(uid uuid)
 RETURNS TABLE(reason text, by uuid, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  return query select f.reason, f.by, f.created_at from public.account_freezes f where f.user_id = uid;
end $function$;

-- public.staff_freeze_shards(p_user uuid, p_frozen boolean, p_reason text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_freeze_shards(p_user uuid, p_frozen boolean, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid());
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  p_reason := left(btrim(coalesce(p_reason, '')), 300);
  if length(p_reason) < 3 then raise exception 'Say why'; end if;
  insert into public.shard_wallets (user_id, frozen) values (p_user, p_frozen)
    on conflict (user_id) do update set frozen = excluded.frozen, updated_at = now();
  insert into public.mod_log (actor, action, target_id, reason)
    values (me, case when p_frozen then 'shards_freeze' else 'shards_unfreeze' end, p_user, p_reason);
end; $function$;

-- public.staff_handle_image_removal(rid uuid, st text, note text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_handle_image_removal(rid uuid, st text, note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare who uuid;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  perform public.mod_guard('image_removal', null, note);
  if st not in ('removed', 'need_info', 'rejected') then raise exception 'Bad status'; end if;
  if st <> 'removed' and length(btrim(coalesce(note, ''))) < 3 then raise exception 'Say why (the person gets this by email)'; end if;
  update public.image_removal_requests
     set status = st, staff_note = left(btrim(coalesce(note, '')), 1000), handled_by = auth.uid(), handled_at = now()
   where id = rid
  returning reporter_id into who;
  if not found then raise exception 'Request not found'; end if;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'image_removal_' || st, who, left(rid::text || ' ' || coalesce(note, ''), 120));
end $function$;

-- public.staff_image_removals(st text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_image_removals(st text DEFAULT 'open'::text)
 RETURNS SETOF public.image_removal_requests
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  return query
    select * from public.image_removal_requests r
    where (st = 'open' and r.status in ('open', 'need_info')) or (st <> 'open' and r.status in ('removed', 'rejected'))
    order by case when st = 'open' then extract(epoch from r.due_at) else -extract(epoch from r.handled_at) end
    limit 200;
end $function$;

-- public.staff_lift_suspension(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_lift_suspension(uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  perform public.mod_guard('suspension_lift', null, null);
  execute 'del' || 'ete from public.account_suspensions where user_id = $1' using uid;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'suspension_lifted', uid, 'Suspension lifted');
end $function$;

-- public.staff_mfa_ok()  [security definer]
CREATE OR REPLACE FUNCTION public.staff_mfa_ok()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
begin
  return (
  select not public.feature_on('staff_2fa', null) or coalesce(auth.jwt() ->> 'aal', 'aal1') = 'aal2'
  );
end;
$function$;

-- public.staff_mod_stats(p_days integer)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_mod_stats(p_days integer DEFAULT 7)
 RETURNS TABLE(user_id uuid, head boolean, suspended boolean, since timestamp with time zone, total bigint, deletes bigint, warns bigint, timeouts bigint, bans bigint, unbans bigint, verifies bigint, appeals bigint, other bigint, last_action timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not (public.is_site_admin() or public.is_head_mod()) then raise exception 'Admins only'; end if;
  p_days := least(greatest(coalesce(p_days, 7), 1), 90);
  return query
  select m.user_id, m.head, m.suspended_at is not null, m.created_at,
         count(l.*), count(*) filter (where l.action in ('delete', 'purge')),
         count(*) filter (where l.action = 'warn'),
         count(*) filter (where l.action in ('timeout', 'voice_mute')),
         count(*) filter (where l.action = 'ban'),
         count(*) filter (where l.action = 'unban'),
         count(*) filter (where l.action in ('verify', 'verify_reject', 'verify_ask_proof')),
         count(*) filter (where l.action in ('appeal_approved', 'appeal_denied', 'ban_appeal_approved', 'ban_appeal_denied')),
         count(*) filter (where l.action is not null and l.action not in ('delete', 'purge', 'warn', 'timeout', 'voice_mute', 'ban', 'unban',
           'verify', 'verify_reject', 'verify_ask_proof', 'appeal_approved', 'appeal_denied', 'ban_appeal_approved', 'ban_appeal_denied')),
         (select max(x.created_at) from public.mod_log x where x.actor = m.user_id)
    from public.site_moderators m
    left join public.mod_log l on l.actor = m.user_id and l.created_at > now() - make_interval(days => p_days)
   group by m.user_id, m.head, m.suspended_at, m.created_at;
end $function$;

-- public.staff_peek_ok(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_peek_ok(sid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select not exists (select 1 from public.servers s join public.site_admins a on a.user_id = s.owner_id where s.id = sid);
$function$;

-- public.staff_reauth(pw text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_reauth(pw text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare me uuid := auth.uid(); hash text; r public.staff_reauth;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if not public.is_staff() then raise exception 'Staff only'; end if;
  select * into r from public.staff_reauth where user_id = me;
  if r.fails >= 5 and r.fail_at > now() - interval '10 minutes' then raise exception 'Too many wrong passwords. Try again in 10 minutes.'; end if;
  select encrypted_password into hash from auth.users where id = me;
  if coalesce(hash, '') = '' then raise exception 'Your account has no password. Set one in Settings → My Account first.'; end if;
  if extensions.crypt(coalesce(pw, ''), hash) = hash then
    insert into public.staff_reauth (user_id, ok_at, fails) values (me, now(), 0)
      on conflict (user_id) do update set ok_at = now(), fails = 0, fail_at = null;
    return true;
  end if;
  insert into public.staff_reauth (user_id, fails, fail_at) values (me, 1, now())
    on conflict (user_id) do update set fails = case when staff_reauth.fail_at > now() - interval '10 minutes' then staff_reauth.fails + 1 else 1 end, fail_at = now();
  return false;
end $function$;

-- public.staff_remove_copyright_strike(cid uuid, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_remove_copyright_strike(cid uuid, why text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare who uuid;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  perform public.mod_guard('copyright', null, why);
  update public.copyright_strikes set removed_at = now(), removed_by = auth.uid()
   where id = cid and removed_at is null returning user_id into who;
  if who is null then raise exception 'Strike not found'; end if;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'copyright_strike_removed', who, left(coalesce(why, ''), 120));
end $function$;

-- public.staff_review_auto_ban(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_review_auto_ban(uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  perform public.mod_guard('auto_ban_reviewed', null, null);
  update public.site_bans set reviewed_at = now(), reviewed_by = auth.uid()
  where user_id = uid and banned_by is null and reviewed_at is null;
  if not found then raise exception 'Nothing to review for that one'; end if;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'auto_ban_reviewed', uid, 'kept');
end $function$;

-- public.staff_role_guard()
CREATE OR REPLACE FUNCTION public.staff_role_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare rid uuid; staff_server boolean; admin_role boolean;
begin
  if tg_table_name = 'roles' then rid := old.id;
  elsif tg_op = 'INSERT' then rid := new.role_id;
  else rid := old.role_id;
  end if;
  if auth.uid() is not null and not public.is_site_admin() then
    if rid in (public.area_role_id('art'), public.area_role_id('dev')) then
      if tg_op = 'INSERT' and current_setting('yapper.staff_sync', true) is distinct from '1' then
        raise exception 'This role follows the Yapin'' staff list. Ask an admin';
      end if;
      if tg_op <> 'INSERT' and current_user = 'authenticated' then
        raise exception 'This role follows the Yapin'' staff list. Ask an admin';
      end if;
    elsif current_user = 'authenticated'
       and rid in (public.hq_head_mod_role_id(), public.hq_management_role_id(), public.modserver_management_role_id()) then
      raise exception 'This role follows the Yapin'' staff list. Ask an admin';
    end if;
    if tg_table_name = 'roles' and tg_op = 'UPDATE' and current_user = 'authenticated' then
      if new.server_id is distinct from old.server_id then
        raise exception 'A role can''t move to another server';
      end if;
    end if;
    select r.server_id in (select x.server_id from public.roles x
                           where x.id in (public.hq_management_role_id(), public.modserver_management_role_id()))
      into staff_server
      from public.roles r where r.id = rid;
    if coalesce(staff_server, false) then
      if tg_table_name = 'member_roles' then
        select coalesce((r.perms ->> 'administrator')::boolean, false) into admin_role from public.roles r where r.id = rid;
        if tg_op = 'INSERT' and coalesce(admin_role, false) then
          raise exception 'Only a Yapin'' admin can give a role with Administrator here';
        end if;
        if tg_op = 'DELETE' and old.user_id is distinct from auth.uid()
           and current_user = 'authenticated'
           and (coalesce(admin_role, false) or public.role_guard_is_staff(old.server_id, old.user_id)) then
          raise exception 'Only a Yapin'' admin can take roles from Yapin'' staff here';
        end if;
      end if;
      if tg_table_name = 'roles' and current_user = 'authenticated' then
        if tg_op = 'DELETE' then
          if coalesce((old.perms ->> 'administrator')::boolean, false) then
            raise exception 'Only a Yapin'' admin can delete a role with Administrator here';
          end if;
          if exists (select 1 from public.member_roles mr where mr.role_id = old.id and public.role_guard_is_staff(old.server_id, mr.user_id)) then
            raise exception 'Only a Yapin'' admin can delete a role Yapin'' staff hold here';
          end if;
        elsif (coalesce((new.perms ->> 'administrator')::boolean, false) or coalesce((old.perms ->> 'administrator')::boolean, false))
              and new.perms is distinct from old.perms then
          raise exception 'Only a Yapin'' admin can change a role with Administrator here';
        end if;
      end if;
    end if;
  end if;
  return coalesce(new, old);
end;
$function$;

-- public.staff_role_held_by_staff(rid uuid, uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_role_held_by_staff(rid uuid, uid uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- Does Yapin' staff hold this role (uid: that person; null: anyone)? Only for roles of the two staff servers.
  select exists (
    select 1
      from public.member_roles mr
      join public.roles r on r.id = mr.role_id
     where mr.role_id = rid
       and (uid is null or mr.user_id = uid)
       and r.server_id in (select x.server_id from public.roles x
                            where x.id in (public.hq_management_role_id(), public.modserver_management_role_id()))
       and public.is_staff_user(mr.user_id))
$function$;

-- public.staff_server_limit(sid uuid, mode text, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_server_limit(sid uuid, mode text, why text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare own uuid; nm text; hid timestamptz; hby uuid; prev boolean; r text := left(btrim(coalesce(why, '')), 300);
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  if not public.feature_on('server_watch', null) then raise exception 'Not available yet'; end if;
  if mode is null or mode not in ('hide', 'unhide') then raise exception 'Unknown action'; end if;
  select owner_id, name, staff_hidden_at, discoverable into own, nm, hid, prev from public.servers where id = sid;
  if nm is null then raise exception 'Server not found'; end if;
  if sid = (select default_server_id from public.app_settings limit 1) then raise exception 'Yapper HQ can''t be hidden'; end if;
  select hidden_by into hby from public.server_hides where server_id = sid;
  if mode = 'hide' then
    if hid is not null then return; end if;
    if char_length(r) < 5 then raise exception 'Give a reason (at least 5 characters)'; end if;
    perform public.mod_guard('server_hide', own, r);
    insert into public.server_hides (server_id, hidden_by, prev_discoverable, reason) values (sid, auth.uid(), prev, nullif(r, ''))
      on conflict (server_id) do update set hidden_by = excluded.hidden_by, prev_discoverable = excluded.prev_discoverable,
        reason = excluded.reason, created_at = now();
    update public.servers set staff_hidden_at = now(), discoverable = false where id = sid;
    insert into public.mod_log (actor, action, target_id, reason)
      values (auth.uid(), 'server_hide', own, left(r || ' [' || nm || ']', 500));
    update public.server_watch set status = 'actioned', cleared_score = score, reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
    where server_id = sid;
  else
    if hid is null then return; end if;
    if not public.is_site_admin() and hby is distinct from auth.uid() then
      raise exception 'Only an admin or the moderator who hid it can undo that';
    end if;
    perform public.mod_guard('server_unhide', null, r);
    update public.servers set staff_hidden_at = null,
      discoverable = case when shut_down_at is null
        then coalesce((select h.prev_discoverable from public.server_hides h where h.server_id = sid), discoverable) else discoverable end
    where id = sid;
    execute 'del' || 'ete from public.server_hides where server_id = $1' using sid;
    insert into public.mod_log (actor, action, target_id, reason)
      values (auth.uid(), 'server_unhide', own, left(coalesce(nullif(r, ''), 'Back in Discover') || ' [' || nm || ']', 500));
  end if;
end $function$;

-- public.staff_server_report_info(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_server_report_info(sid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s record; res jsonb; adm boolean;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  if not public.feature_on_for_me('server_reports') then raise exception 'Not available yet'; end if;
  adm := public.is_site_admin();
  if not adm and not exists (select 1 from public.reports where reported_server_id = sid) then
    raise exception 'That server wasn''t reported';
  end if;
  select id, name, icon_path, owner_id, member_count, created_at, discoverable, name_ok, locked_until, staff_hidden_at,
         shut_down_at, shut_down_reason, tag
    into s from public.servers where id = sid;
  if s.id is null then return null; end if;
  select jsonb_build_object(
    'id', s.id, 'name', s.name, 'icon_path', s.icon_path, 'tag', s.tag, 'member_count', s.member_count, 'created_at', s.created_at,
    'discoverable', s.discoverable,
    'listed', coalesce(s.discoverable and s.name_ok and (s.locked_until is null or s.locked_until < now()), false),
    'hidden_at', s.staff_hidden_at, 'shut_down_at', s.shut_down_at, 'shut_down_reason', s.shut_down_reason,
    'owner', (select jsonb_build_object('id', p.id, 'username', p.username, 'display_name', p.display_name, 'created_at', p.created_at,
                                        'banned', public.is_site_banned(p.id), 'staff', public.is_staff_user(p.id))
                from public.profiles p where p.id = s.owner_id),
    'open_inside', (select count(*) from public.reports r where r.server_id = sid and r.status = 'open'),
    'recent_inside', coalesce((select jsonb_agg(x order by x.created_at desc) from (
        select r.id, r.reason, r.target_id, r.created_at, (select username from public.profiles where id = r.target_id) as target_name
          from public.reports r where r.server_id = sid and r.status = 'open' order by r.created_at desc limit 5) x), '[]'::jsonb),
    'past_reports', (select count(*) from public.reports r where r.reported_server_id = sid and r.status <> 'open'),
    'past_actioned', (select count(*) from public.reports r where r.reported_server_id = sid and r.status = 'actioned'),
    'watch', (select jsonb_build_object('score', w.score, 'status', w.status) from public.server_watch w where w.server_id = sid),
    'hits', coalesce((select jsonb_agg(x order by x.at desc) from (
        select h.src, h.kind, h.term, case when adm then left(h.sample, 140) end as sample, h.at
          from public.server_watch_hits h where h.server_id = sid order by h.at desc limit 5) x), '[]'::jsonb)
  ) into res;
  return res;
end $function$;

-- public.staff_shards(p_user uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_shards(p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  return jsonb_build_object(
    'wallet', (select to_jsonb(w) from public.shard_wallets w where w.user_id = p_user),
    'level', (select account_level from public.profiles where id = p_user),
    'ledger', coalesce((select jsonb_agg(to_jsonb(l) order by l.id desc) from (
        select id, amount, kind, ref, note, actor, balance_after, created_at from public.shard_ledger
        where user_id = p_user order by id desc limit 100) l), '[]'::jsonb),
    'referrals', coalesce((select jsonb_agg(jsonb_build_object('invitee', r.invitee, 'username', p.username,
        'status', r.status, 'reason', r.reason, 'created_at', r.created_at, 'paid_at', r.paid_at) order by r.created_at desc)
      from public.referrals r join public.profiles p on p.id = r.invitee where r.inviter = p_user), '[]'::jsonb),
    'invited_by', (select jsonb_build_object('id', r.inviter, 'username', p.username, 'status', r.status)
      from public.referrals r join public.profiles p on p.id = r.inviter where r.invitee = p_user));
end; $function$;

-- public.staff_suspend_bot(bid uuid, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_suspend_bot(bid uuid, why text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b public.bots; n int;
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  why := left(btrim(coalesce(why, '')), 300);
  if length(why) < 5 then raise exception 'Give a reason (at least 5 characters)'; end if;
  if not public.is_site_admin() then
    perform pg_advisory_xact_lock(hashtextextended('bot_suspend_cap:' || auth.uid()::text, 0));
    select count(*) into n from public.mod_log where actor = auth.uid() and action = 'bot_suspended' and created_at > now() - interval '1 hour';
    if n >= 10 then raise exception 'That''s 10 bot suspensions this hour. Wait a bit or ask an admin'; end if;
  end if;
  select * into b from public.bots where id = bid for update;
  if b.id is null then raise exception 'No such bot'; end if;
  if b.owner_id = auth.uid() and not public.is_site_admin() then raise exception 'You can''t suspend your own bot'; end if;
  if exists (select 1 from public.site_admins where user_id = b.owner_id) and not public.is_site_admin() then raise exception 'That bot belongs to an admin'; end if;
  if not (b.public or b.unlisted or b.verified_at is not null) then raise exception 'That bot isn''t listed or verified'; end if;
  update public.bots set public = false, unlisted = false, verified_at = null, review_note = left('Suspended: ' || why, 300) where id = bid;
  update public.bot_promotions set starts_at = least(starts_at, now()), ends_at = now(), ended_by = auth.uid() where bot_id = bid and ends_at > now();
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'bot_suspended', bid, left(why || ' [' || b.name || ']', 500));
end;
$function$;

-- public.staff_takedown_server(sid uuid, why text, suspend_owner boolean, p_on boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_takedown_server(sid uuid, why text, suspend_owner boolean DEFAULT false, p_on boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare own uuid; nm text; was boolean; r text := left(btrim(coalesce(why, '')), 500);
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  select owner_id, name, discoverable into own, nm, was from public.servers where id = sid;
  if own is null then raise exception 'Server not found'; end if;
  if p_on then
    if length(r) < 5 then raise exception 'Give a reason (at least 5 characters). Members will see it.'; end if;
    perform public.mod_guard('takedown', case when public.is_staff_user(own) then null else own end, r);
    perform public.require_staff_reauth();
    if public.is_staff_user(own) and suspend_owner then raise exception 'You can''t suspend a staff account'; end if;
    update public.servers set shut_down_at = now(), shut_down_reason = r, takedown_by = auth.uid(),
      takedown_prev_discoverable = coalesce(takedown_prev_discoverable, discoverable),
      locked_until = timestamptz '2999-01-01', lock_reason = 'taken down by Yapper', discoverable = false where id = sid;
    if suspend_owner then
      insert into public.account_suspensions (user_id, reason, until, by, server_id)
        values (own, 'Your server "' || nm || '" was taken down: ' || r, null, auth.uid(), sid)
        on conflict (user_id) do update set reason = excluded.reason, until = null, by = excluded.by, server_id = excluded.server_id, created_at = now();
    end if;
    insert into public.mod_log (actor, action, target_id, reason)
      values (auth.uid(), 'server_takedown', own, r || ' [' || nm || ']' || case when suspend_owner then ' (owner suspended)' else '' end);
  else
    if not public.is_site_admin() and (select takedown_by from public.servers where id = sid) is distinct from auth.uid() then
      raise exception 'Only an admin or the moderator who took it down can bring it back';
    end if;
    update public.servers set shut_down_at = null, shut_down_reason = null, locked_until = null, lock_reason = null,
      discoverable = coalesce(takedown_prev_discoverable, discoverable), takedown_prev_discoverable = null, takedown_by = null where id = sid;
    execute 'del' || 'ete from public.account_suspensions where server_id = $1' using sid;
    insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'server_restored', own, coalesce(nullif(r, ''), 'Restored') || ' [' || nm || ']');
  end if;
end $function$;

-- public.staff_upload_appeals(st text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_upload_appeals(st text DEFAULT 'pending'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  return coalesce((
    select jsonb_agg(row_to_json(r)::jsonb order by r.created_at)
    from (
      select a.id, a.user_id, pr.username, a.bucket, a.score, a.note, a.status, a.created_at, a.decided_at,
             a.decided_by, a.details, a.allowed,
             coalesce((a.details ->> 'hashHit')::boolean, false) as known,
             (q.key is not null and q.removed_at is null) as has_file,
             q.content_type,
             exists (select 1 from public.site_bans b
                      where b.user_id = a.user_id and b.banned_by is null and b.expires_at > now()
                        and b.reason in ('Uploading sexual images or videos', 'Uploading sexual images')
                        and s.scanned_at between b.created_at - interval '1 day' and b.created_at + interval '5 minutes') as auto_banned,
             (select count(*) from public.media_scans x
               where x.user_id = a.user_id and x.verdict = 'blocked' and x.score > 0
                 and x.scanned_at > now() - interval '30 days') as blocked_30d
      from public.upload_appeals a
      left join public.profiles pr on pr.id = a.user_id
      left join public.upload_quarantine q on q.bucket = a.bucket and q.path = a.path
      left join public.media_scans s on s.bucket = a.bucket and s.path = a.path
      where (st = 'pending' and a.status = 'pending')
         or (st <> 'pending' and a.status <> 'pending' and a.decided_at > now() - interval '14 days')
      order by a.created_at
      limit 100
    ) r
  ), '[]'::jsonb);
end;
$function$;

-- public.staff_voice_timeout(uid uuid, minutes integer)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_voice_timeout(uid uuid, minutes integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  if uid = auth.uid() then raise exception 'Not yourself'; end if;
  if public.is_staff_user(uid) then raise exception 'You can''t mute Yapper staff'; end if;
  minutes := least(greatest(coalesce(minutes, 0), 0), 1440);
  update public.profiles set voice_muted_until = case when minutes <= 0 then null else now() + make_interval(mins => minutes) end where id = uid;
end;
$function$;

-- public.staff_vote_cast(vid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_vote_cast(vid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.staff_votes;
begin
  if not public.is_staff() then raise exception 'Moderators only'; end if;
  select * into v from public.staff_votes where id = vid;
  if v.id is null or v.closed_at is not null or v.created_at < now() - interval '24 hours' then raise exception 'That vote is closed'; end if;
  if v.target = auth.uid() then raise exception 'You can''t vote about yourself'; end if;
  insert into public.staff_vote_ballots (vote_id, voter) values (vid, auth.uid()) on conflict do nothing;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'vote_cast', v.target, v.reason);
  perform public.staff_vote_tally(vid);
end; $function$;

-- public.staff_vote_close(vid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_vote_close(vid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.staff_votes;
begin
  select * into v from public.staff_votes where id = vid;
  if v.id is null or v.closed_at is not null then return; end if;
  if not (v.opened_by = auth.uid() or public.is_site_admin()) then raise exception 'Only whoever started the vote (or an admin) can withdraw it'; end if;
  update public.staff_votes set closed_at = now(), outcome = 'withdrawn' where id = vid;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'vote_withdrawn', v.target, v.reason);
end; $function$;

-- public.staff_vote_eligible(target uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_vote_eligible(target uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(*)::int from (
    select user_id from public.site_admins
    union
    select user_id from public.site_moderators where suspended_at is null
  ) s where s.user_id <> target;
$function$;

-- public.staff_vote_needed(target uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_vote_needed(target uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select greatest(1, least(e, floor(p * e / 100.0)::int + 1))
  from (select public.staff_vote_eligible(target) as e, (select staff_vote_pct from public.app_settings limit 1) as p) x;
$function$;

-- public.staff_vote_open(uid uuid, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_vote_open(uid uuid, why text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare vid uuid;
begin
  if not public.is_staff() then raise exception 'Moderators only'; end if;
  perform public.mod_guard('vote', null, why);
  if uid = auth.uid() then raise exception 'Not yourself'; end if;
  if exists (select 1 from public.site_admins where user_id = uid) then raise exception 'Admins can''t be voted out'; end if;
  if not exists (select 1 from public.site_moderators where user_id = uid and suspended_at is null) then raise exception 'They aren''t an active moderator'; end if;
  if length(trim(coalesce(why, ''))) < 5 then raise exception 'Give a reason (at least 5 characters)'; end if;
  if exists (select 1 from public.staff_votes where target = uid and closed_at is null and created_at > now() - interval '24 hours') then
    raise exception 'There''s already an open vote about them';
  end if;
  insert into public.staff_votes (target, opened_by, reason) values (uid, auth.uid(), left(trim(why), 500)) returning id into vid;
  insert into public.staff_vote_ballots (vote_id, voter) values (vid, auth.uid());
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'vote_opened', uid, left(trim(why), 500));
  perform public.staff_vote_tally(vid);
  return vid;
end; $function$;

-- public.staff_vote_tally(vid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_vote_tally(vid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.staff_votes; n int; needed int;
begin
  select * into v from public.staff_votes where id = vid;
  if v.id is null or v.closed_at is not null then return; end if;
  select count(*) into n from public.staff_vote_ballots b
    where b.vote_id = vid and b.voter <> v.target
      and (exists (select 1 from public.site_admins a where a.user_id = b.voter)
        or exists (select 1 from public.site_moderators m where m.user_id = b.voter and m.suspended_at is null));
  needed := public.staff_vote_needed(v.target);
  if n < needed then return; end if;
  -- Paused rather than removed: powers and badge go at once, and admins still see who it was and why.
  update public.site_moderators set suspended_at = now(), suspended_reason = left('Removed by staff vote: ' || v.reason, 500) where user_id = v.target;
  insert into public.site_bans (user_id, reason, banned_by) values (v.target, left('Staff vote: ' || v.reason, 500), v.opened_by)
    on conflict (user_id) do update
    set reason = excluded.reason, banned_by = excluded.banned_by, created_at = now(), expires_at = excluded.expires_at
    -- 157: a lifted (expired) ban is replaced; a running one only by a ban at least as long (null = permanent).
    where site_bans.expires_at <= now() or excluded.expires_at is null
       or (site_bans.expires_at is not null and excluded.expires_at >= site_bans.expires_at);
  update public.staff_votes set closed_at = now(), outcome = 'passed' where id = vid;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'vote_ban', v.target, v.reason || ' (' || n || ' of ' || needed || ' votes)');
end; $function$;

-- public.staff_votes_open()  [security definer]
CREATE OR REPLACE FUNCTION public.staff_votes_open()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when public.is_staff() then jsonb_build_object(
    'pct', (select staff_vote_pct from public.app_settings limit 1),
    'votes', coalesce((select jsonb_agg(jsonb_build_object(
      'id', v.id, 'target', v.target, 'opened_by', v.opened_by, 'reason', v.reason, 'created_at', v.created_at,
      'voters', coalesce((select jsonb_agg(b.voter order by b.created_at) from public.staff_vote_ballots b where b.vote_id = v.id), '[]'::jsonb),
      'eligible', public.staff_vote_eligible(v.target),
      'needed', public.staff_vote_needed(v.target)
    ) order by v.created_at desc)
    from public.staff_votes v where v.closed_at is null and v.created_at > now() - interval '24 hours'), '[]'::jsonb)
  ) else '{}'::jsonb end;
$function$;

-- public.staff_warn_server_owner(sid uuid, reason text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_warn_server_owner(sid uuid, reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare own uuid; nm text; r text := left(btrim(coalesce(reason, '')), 300);
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  if not public.feature_on('server_watch', null) then raise exception 'Not available yet'; end if;
  select owner_id, name into own, nm from public.servers where id = sid;
  if nm is null then raise exception 'Server not found'; end if;
  if own is null then raise exception 'This server has no owner to warn'; end if;
  if char_length(r) < 3 then raise exception 'Say what the warning is for'; end if;
  if own = auth.uid() then raise exception 'Not yourself'; end if;
  perform public.mod_guard('server_warn', own, r);
  if exists (select 1 from public.user_warnings where user_id = own and server_id = sid and removed_at is null and created_at > now() - interval '24 hours') then
    raise exception 'The owner already got a warning for this server today';
  end if;
  insert into public.user_warnings (user_id, by, reason, server_id)
    values (own, auth.uid(), left('Your server "' || nm || '": ' || r, 500), sid);
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'server_warn', own, left(r || ' [' || nm || ']', 500));
  update public.server_watch set status = 'actioned', cleared_score = score, reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
  where server_id = sid;
end $function$;

-- public.staff_watch_list(p_status text, lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_watch_list(p_status text DEFAULT 'new'::text, lim integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare st text := coalesce(p_status, 'new');
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  if not public.feature_on('server_watch', null) then raise exception 'Not available yet'; end if;
  if st not in ('new', 'ok', 'actioned') then raise exception 'Unknown list'; end if;
  return jsonb_build_object(
    'last_run', (select last_run from public.server_watch_state where id),
    'items', coalesce((select jsonb_agg(x order by x.score desc) from (
      select w.server_id as id, s.name, s.owner_id, p.username as owner_name, s.member_count as members, s.created_at,
             s.discoverable, s.staff_hidden_at as hidden_at, (select hidden_by from public.server_hides where server_id = s.id) as hidden_by,
             s.shut_down_at, s.takedown_by,
             w.score, w.reasons, w.reports, w.blocked_images, w.joins_24h, w.first_seen, w.last_seen, w.status,
             w.reviewed_at, (select username from public.profiles where id = w.reviewed_by) as reviewed_by_name,
             (select count(*)::int from public.user_warnings uw where uw.server_id = w.server_id) as owner_warnings
      from public.server_watch w
      join public.servers s on s.id = w.server_id
      left join public.profiles p on p.id = s.owner_id
      where w.status = st and (st <> 'new' or w.score >= 10)
      order by w.score desc
      limit least(greatest(coalesce(lim, 50), 1), 200)) x), '[]'::jsonb));
end $function$;

-- public.staff_watch_peek(sid uuid, cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_watch_peek(sid uuid, cid uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s public.servers; ch uuid; chname text; note text; adm boolean := public.is_site_admin();
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  if not public.feature_on('server_watch', null) then raise exception 'Not available yet'; end if;
  perform public.mod_guard('server_peek', null, '');
  select * into s from public.servers where id = sid;
  if not found then raise exception 'Server not found'; end if;
  if not adm then
    if not exists (select 1 from public.server_watch w where w.server_id = sid and (w.score >= 10 or w.status = 'actioned'))
       and not exists (select 1 from public.reports r where r.server_id = sid and r.status = 'open') then
      raise exception 'You can only open servers that were flagged or reported';
    end if;
    if s.owner_id is not null and public.is_staff_user(s.owner_id) then raise exception 'That server belongs to staff'; end if;
  end if;
  if cid is not null then
    select id, name into ch, chname from public.channels where id = cid and server_id = sid;
    if ch is null then raise exception 'That channel isn''t in this server'; end if;
    if not adm and not public.server_watch_public_channel(ch) then raise exception 'That channel is private. Ask an admin.'; end if;
  else
    select c.id, c.name into ch, chname from public.channels c where c.server_id = sid and c.kind = 'text'
      and (adm or public.server_watch_public_channel(c.id))
    order by c.last_message_at desc nulls last limit 1;
  end if;
  if ch is not null then
    note := left('Read #' || chname || ' [' || s.name || ']', 500);
    if not exists (select 1 from public.mod_log where actor = auth.uid() and action = 'server_peek' and reason = note and created_at > now() - interval '10 minutes') then
      insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'server_peek', s.owner_id, note);
    end if;
  end if;
  return jsonb_build_object(
    'server', jsonb_build_object('id', s.id, 'name', s.name, 'description', s.description, 'created_at', s.created_at,
      'members', s.member_count, 'discoverable', s.discoverable, 'hidden_at', s.staff_hidden_at, 'shut_down_at', s.shut_down_at,
      'owner_id', s.owner_id, 'owner_name', (select username from public.profiles where id = s.owner_id),
      'owner_created_at', (select created_at from public.profiles where id = s.owner_id)),
    'owner_warnings', coalesce((select jsonb_agg(jsonb_build_object('reason', w.reason, 'at', w.created_at, 'server_id', w.server_id) order by w.created_at desc)
      from (select * from public.user_warnings where user_id = s.owner_id order by created_at desc limit 5) w), '[]'::jsonb),
    'channels', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'kind', c.kind, 'last_message_at', c.last_message_at,
        'private', not c.pub, 'readable', c.kind = 'text')
      order by c.position, c.name) from (select x.*, public.server_watch_public_channel(x.id) as pub from public.channels x
                                         where x.server_id = sid order by x.position, x.name limit 100) c
      where adm or c.pub), '[]'::jsonb),
    'private_channels', case when adm then 0 else (select count(*)::int from public.channels x
                                                     where x.server_id = sid and not public.server_watch_public_channel(x.id)) end,
    'channel_id', ch,
    'messages', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'author_id', m.author_id, 'author_name', pr.username,
        'content', left(m.content, 1000), 'attachment_path', m.attachment_path, 'created_at', m.created_at) order by m.created_at)
      from (select * from public.messages where channel_id = ch order by created_at desc limit 40) m
      left join public.profiles pr on pr.id = m.author_id), '[]'::jsonb));
end $function$;

-- public.staff_watch_review(sid uuid, status text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_watch_review(sid uuid, status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare st text := staff_watch_review.status; sc int; own uuid; nm text;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  if not public.feature_on('server_watch', null) then raise exception 'Not available yet'; end if;
  if st is null or st not in ('new', 'ok', 'actioned') then raise exception 'Unknown status'; end if;
  perform public.mod_guard('watch_review', null, '');
  update public.server_watch w set status = st,
    cleared_score = case when st = 'new' then null else w.score end,
    reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
  where w.server_id = sid
  returning w.score into sc;
  if not found then raise exception 'That server isn''t on the watch list'; end if;
  select owner_id, name into own, nm from public.servers where id = sid;
  insert into public.mod_log (actor, action, target_id, reason)
    values (auth.uid(), 'watch_review', own, left(case st when 'ok' then 'Looks fine' when 'actioned' then 'Handled' else 'Back on the list' end
      || ' (score ' || sc || ') [' || coalesce(nm, '?') || ']', 500));
end $function$;

-- public.staff_withdrawal_done(p_id uuid, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_withdrawal_done(p_id uuid, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  w public.withdrawals;
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  update public.withdrawals set status = 'manual_done', note = nullif(left(trim(coalesce(p_note, '')), 500), ''),
    handled_by = auth.uid(), handled_at = now()
  where id = p_id and status = 'refund_failed'
  returning * into w;
  if not found then raise exception 'Nothing to do for that one'; end if;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'withdrawal_refunded', w.user_id, left(w.stripe_sub || ' ' || coalesce(p_note, ''), 120));
end $function$;

-- public.staff_withdrawals(p_open boolean)  [security definer]
CREATE OR REPLACE FUNCTION public.staff_withdrawals(p_open boolean DEFAULT true)
 RETURNS TABLE(id uuid, user_id uuid, username text, stripe_sub text, label text, paid_cents integer, refund_cents integer, currency text, stripe_refund text, status text, error text, note text, created_at timestamp with time zone, handled_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_site_admin() then raise exception 'Admins only'; end if;
  return query
  select w.id, w.user_id, p.username, w.stripe_sub, w.label, w.paid_cents, w.refund_cents, w.currency, w.stripe_refund,
    w.status, w.error, w.note, w.created_at, w.handled_at
  from public.withdrawals w
  left join public.profiles p on p.id = w.user_id
  where not p_open or w.status = 'refund_failed'
  order by w.created_at desc
  limit 200;
end $function$;

-- public.stage_role_for(uid uuid, cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.stage_role_for(uid uuid, cid uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  old_claims text := current_setting('request.jwt.claims', true);
  old_sub text := current_setting('request.jwt.claim.sub', true);
  res text;
begin
  if uid is null or cid is null then return null; end if;
  perform set_config('request.jwt.claims', jsonb_build_object('sub', uid::text, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', uid::text, true);
  res := public.stage_role(cid);
  perform set_config('request.jwt.claims', coalesce(old_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(old_sub, ''), true);
  if res is null and exists (
    select 1 from public.channels ch join public.feature_flags f on f.key = 'stage_channels'
     where ch.id = cid and ch.kind = 'voice' and ch.stage and ch.server_id is not null
       and (f.mode = 'everyone' or (f.mode = 'test' and ch.server_id = any(f.servers)))) then
    res := 'listener';
  end if;
  return res;
end $function$;

-- public.stage_role(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.stage_role(cid uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c record;
begin
  if auth.uid() is null or cid is null then return null; end if;
  select ch.id, ch.server_id, ch.stage into c from public.channels ch where ch.id = cid and ch.kind = 'voice';
  if not found or not c.stage or c.server_id is null then return null; end if;
  if not exists (select 1 from public.feature_flags f where f.key = 'stage_channels'
                  and (f.mode = 'everyone' or (f.mode = 'test' and c.server_id = any(f.servers)))) then
    return null;
  end if;
  if not public.can_access_channel(cid) then return null; end if;
  if public.is_staff() or public.server_perm(c.server_id, 'mute_members') then return 'mod'; end if;
  return 'listener';
end $function$;

-- public.standing_guard(action text, sid uuid, other uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.standing_guard(action text, sid uuid DEFAULT NULL::uuid, other uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); tier text; why text;
begin
  if me is null then return; end if;
  -- First day (flag new_account_limits, 303): no links, DMs only to friends, 5 friend requests. Staff and bots skip it.
  if public.feature_on('new_account_limits', sid) and not public.is_staff() and exists (
       select 1 from public.profiles np where np.id = me and np.created_at > now() - interval '24 hours'
         and not ('bot' = any(coalesce(np.badges, '{}'::text[])))) then
    if action = 'link' then
      raise exception 'New accounts can post links after their first day.' using errcode = 'insufficient_privilege';
    end if;
    if action in ('message_dm', 'dm_open') and other is not null and not public.are_friends(me, other) then
      raise exception 'New accounts can only DM friends on their first day.' using errcode = 'insufficient_privilege';
    end if;
    if action = 'friend' and (select count(*) from public.friendships fr where fr.requester = me and fr.created_at > now() - interval '24 hours') >= 5 then
      raise exception 'New accounts can send 5 friend requests on their first day.' using errcode = 'insufficient_privilege';
    end if;
  end if;
  if not public.feature_on('account_standing', sid) then return; end if;
  if public.is_staff() then return; end if;
  tier := public.standing_tier(me);
  if tier = 'good' then return; end if;
  why := ' See Settings → My Account → Account standing.';
  if tier = 'suspended' then
    raise exception 'Your account is suspended: you can read but not post or join.%', why using errcode = 'insufficient_privilege';
  end if;
  if tier = 'very_limited' and action in ('message_dm', 'dm_open', 'friend', 'join', 'create_server', 'react') then
    raise exception 'Your account is very limited: you can only read and reply in servers you are already in.%', why using errcode = 'insufficient_privilege';
  end if;
  if action = 'link' then
    raise exception 'Your account is limited: links are turned off for now.%', why using errcode = 'insufficient_privilege';
  end if;
  if action in ('message_dm', 'dm_open') and other is not null and not public.are_friends(me, other) then
    raise exception 'Your account is limited: you can only DM friends for now.%', why using errcode = 'insufficient_privilege';
  end if;
end $function$;

-- public.standing_proof_build(uid uuid, rid uuid, with_message boolean, note text, images text[])  [security definer]
CREATE OR REPLACE FUNCTION public.standing_proof_build(uid uuid, rid uuid, with_message boolean, note text, images text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  r public.reports;
  ch_kind text;
  ch_name text;
  sv_name text;
  msg jsonb;
  ctx jsonb;
  msg_at timestamptz;
  n text := nullif(left(btrim(coalesce(note, '')), 500), '');
  imgs text[];
  p text;
begin
  select coalesce(array_agg(x order by i), '{}') into imgs
    from (select distinct on (btrim(x)) btrim(x) x, i from unnest(coalesce(images, '{}')) with ordinality u(x, i)
          where x is not null and btrim(x) <> '' order by btrim(x), i) d;
  if cardinality(imgs) > 4 then raise exception 'Up to 4 screenshots'; end if;
  foreach p in array imgs loop
    if p !~ ('^' || me::text || '/[A-Za-z0-9_-][A-Za-z0-9._-]{0,99}\.(png|jpe?g|webp)$') then raise exception 'That screenshot can''t be used'; end if;
    if not exists (select 1 from storage.objects o where o.bucket_id = 'proofs' and o.name = p) then
      raise exception 'A screenshot didn''t finish uploading. Add it again.';
    end if;
  end loop;
  if rid is not null and coalesce(with_message, true) then
    select * into r from public.reports where id = rid;
    if r.id is null or r.target_id is distinct from uid then raise exception 'That report isn''t about them'; end if;
    if r.message_content is not null or r.message_attachment is not null or r.channel_id is not null then
      select c.kind, c.name, s.name into ch_kind, ch_name, sv_name
        from public.channels c left join public.servers s on s.id = r.server_id where c.id = r.channel_id;
      ch_kind := coalesce(ch_kind, case when r.server_id is null then 'dm' end);
      if ch_kind in ('dm', 'group') then
        raise exception 'Messages from DMs can''t be attached, it would show who reported. Add a note instead.';
      end if;
    end if;
    if r.message_content is not null or r.message_attachment is not null then
      msg_at := coalesce((select m.created_at from public.messages m where m.id = r.message_id), r.created_at);
      msg := jsonb_build_object(
        'content', left(r.message_content, 4000),
        'attachment', left(r.message_attachment, 300),
        'kind', ch_kind,
        'channel_name', left(ch_name, 100),
        'server_name', left(sv_name, 100),
        'created_at', msg_at,
        'author_id', r.target_id);
    end if;
    select jsonb_agg(jsonb_build_object('content', x.content, 'created_at', x.created_at) order by x.created_at)
      into ctx
      from (
        select left(e ->> 'content', 300) as content, (e ->> 'created_at')::timestamptz as created_at
          from jsonb_array_elements(case when jsonb_typeof(r.evidence) = 'array' then r.evidence else '[]'::jsonb end) e
         where e ->> 'author_id' = uid::text
           and btrim(coalesce(e ->> 'content', '')) <> ''
           and exists (select 1 from public.channels c
                        where c.id = case when e ->> 'channel_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                                          then (e ->> 'channel_id')::uuid end
                          and c.kind not in ('dm', 'group'))
         order by abs(extract(epoch from ((e ->> 'created_at')::timestamptz - coalesce(msg_at, r.created_at))))
         limit 5
      ) x;
  elsif rid is not null then
    if not exists (select 1 from public.reports where id = rid and target_id = uid) then raise exception 'That report isn''t about them'; end if;
  end if;
  if msg is null and ctx is null and n is null and cardinality(imgs) = 0 then return null; end if;
  return jsonb_strip_nulls(jsonb_build_object(
    'message', msg,
    'context', ctx,
    'note', n,
    'images', case when cardinality(imgs) > 0 then to_jsonb(imgs) end));
end $function$;

-- public.standing_proof_ok(p jsonb)
CREATE OR REPLACE FUNCTION public.standing_proof_ok(p jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare m jsonb; e jsonb; k text;
begin
  if p is null then return true; end if;
  if jsonb_typeof(p) <> 'object' or octet_length(p::text) > 32768 then return false; end if;
  for k in select jsonb_object_keys(p) loop
    if k not in ('message', 'context', 'note', 'images') then return false; end if;
  end loop;
  m := p -> 'message';
  if m is not null and jsonb_typeof(m) <> 'null' then
    if jsonb_typeof(m) <> 'object' then return false; end if;
    for k in select jsonb_object_keys(m) loop
      if k not in ('content', 'attachment', 'channel_name', 'server_name', 'kind', 'created_at', 'author_id') then return false; end if;
      if jsonb_typeof(m -> k) not in ('string', 'null') then return false; end if;
    end loop;
    if char_length(coalesce(m ->> 'content', '')) > 4000 or char_length(coalesce(m ->> 'attachment', '')) > 300
       or char_length(coalesce(m ->> 'channel_name', '')) > 100 or char_length(coalesce(m ->> 'server_name', '')) > 100 then
      return false;
    end if;
  end if;
  if p ? 'context' then
    if jsonb_typeof(p -> 'context') <> 'array' or jsonb_array_length(p -> 'context') > 5 then return false; end if;
    for e in select jsonb_array_elements(p -> 'context') loop
      if jsonb_typeof(e) <> 'object' or jsonb_typeof(e -> 'content') is distinct from 'string' or char_length(e ->> 'content') > 300 then return false; end if;
      for k in select jsonb_object_keys(e) loop
        if k not in ('content', 'created_at') then return false; end if;
      end loop;
    end loop;
  end if;
  if p ? 'note' and (jsonb_typeof(p -> 'note') <> 'string' or char_length(p ->> 'note') > 500) then return false; end if;
  if p ? 'images' then
    if jsonb_typeof(p -> 'images') <> 'array' or jsonb_array_length(p -> 'images') > 4 then return false; end if;
    for e in select jsonb_array_elements(p -> 'images') loop
      if jsonb_typeof(e) <> 'string' or (e #>> '{}') !~ '^[0-9a-f-]{36}/[A-Za-z0-9_-][A-Za-z0-9._-]{0,99}\.(png|jpe?g|webp)$' then return false; end if;
    end loop;
  end if;
  return true;
end $function$;

-- public.standing_proof_public(p jsonb)
CREATE OR REPLACE FUNCTION public.standing_proof_public(p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case when p is null then null else p #- '{message,author_id}' end;
$function$;

-- public.standing_tier(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.standing_tier(uid uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when exists (select 1 from public.account_suspensions s where s.user_id = uid and (s.until is null or s.until > now())) then 'suspended'
    else case least((select count(*) from public.user_warnings w where w.user_id = uid and w.removed_at is null and w.created_at > now() - interval '3 days'), 3)
      when 0 then 'good' when 1 then 'limited' when 2 then 'very_limited' else 'suspended' end
  end;
$function$;

-- public.starboard_react()  [security definer]
CREATE OR REPLACE FUNCTION public.starboard_react()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m public.messages; ch public.channels; cfg jsonb; target uuid; need int; n int; pid uuid; plus boolean; star text; selfs boolean;
begin
  -- Fast exit for the usual stars; Starboard+ servers can pick another emoji.
  if new.emoji not in ('⭐', '🌟') and not exists (select 1 from public.server_bots where bot = 'starboard' and enabled and config ->> 'emoji' = new.emoji) then return null; end if;
  select * into m from public.messages where id = new.message_id;
  if m.id is null then return null; end if;
  select * into ch from public.channels where id = m.channel_id;
  if ch.server_id is null or ch.private then return null; end if;
  if public.channel_overrides_live(ch.id) and exists (select 1 from public.channel_overrides o
       where (o.channel_id = ch.id or o.category_id = ch.category_id) and 'view_channel' = any(o.deny)) then return null; end if;
  cfg := public.bot_cfg(ch.server_id, 'starboard');
  if cfg is null then return null; end if;
  plus := public.server_plus_on(ch.server_id);
  star := case when plus and nullif(cfg ->> 'emoji', '') is not null then cfg ->> 'emoji' else '⭐' end;
  if not (new.emoji = star or (star = '⭐' and new.emoji = '🌟')) then return null; end if;
  selfs := plus and coalesce((cfg ->> 'self_star')::boolean, false);
  if plus and jsonb_typeof(cfg -> 'ignore') = 'array' and (cfg -> 'ignore') ? ch.id::text then return null; end if;
  target := nullif(cfg ->> 'channel_id', '')::uuid;
  if target is null or target = ch.id or not exists (select 1 from public.channels where id = target and server_id = ch.server_id) then return null; end if;
  if exists (select 1 from public.starboard_posts where message_id = m.id) then return null; end if;
  need := least(greatest(coalesce(nullif(cfg ->> 'threshold', '')::int, 5), 1), 50);
  select count(distinct user_id) into n from public.reactions
   where message_id = m.id and (emoji = star or (star = '⭐' and emoji = '🌟')) and (selfs or user_id <> m.author_id);
  if n < need then return null; end if;
  insert into public.starboard_posts (message_id, server_id) values (m.id, ch.server_id) on conflict do nothing;
  if not found then return null; end if;
  perform set_config('yapper.bot', '1', true);
  insert into public.messages (channel_id, author_id, content, attachment_path, attachment_width, attachment_height, attachment_name, attachment_size)
  values (target, public.bot_id('starboard'),
          star || ' **' || n || '** · **#' || ch.name || '** · **' || public.log_name(m.author_id) || '**'
            || case when coalesce(m.content, '') <> '' then E'\n' || public.log_clean(m.content, 1500) else '' end,
          m.attachment_path, m.attachment_width, m.attachment_height, m.attachment_name, m.attachment_size)
  returning id into pid;
  perform set_config('yapper.bot', '', true);
  update public.starboard_posts set post_id = pid where message_id = m.id;
  return null;
exception when others then
  perform set_config('yapper.bot', '', true);
  return null;
end $function$;

-- public.start_call(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.start_call(cid uuid)
 RETURNS public.calls
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); c public.channels; row public.calls;
begin
  if me is null then raise exception 'Sign in first'; end if;
  select * into c from public.channels where id = cid;
  if c.id is null or c.server_id is not null or c.kind not in ('dm', 'group') then raise exception 'Calls only work in DMs and groups'; end if;
  if not public.is_channel_member(cid) then raise exception 'You’re not in this chat'; end if;
  if public.is_site_banned(me) then raise exception 'Your account is banned from Yapper'; end if;
  if c.kind = 'dm' and exists (
    select 1 from public.channel_members m join public.blocks b
      on (b.blocker = m.user_id and b.blocked = me) or (b.blocker = me and b.blocked = m.user_id)
    where m.channel_id = cid and m.user_id <> me
  ) then raise exception 'You can’t call this person'; end if;
  insert into public.calls (channel_id, started_by) values (cid, me)
  on conflict (channel_id) do update set started_by = excluded.started_by, started_at = now(), ended_at = null, answered_at = null
  returning * into row;
  return row;
end;
$function$;

-- public.steam_claim_refresh(p_user uuid, p_gap_sec integer)  [security definer]
CREATE OR REPLACE FUNCTION public.steam_claim_refresh(p_user uuid, p_gap_sec integer)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with t as (
    insert into public.steam_refresh_log as l (user_id, at) values (p_user, now())
    on conflict (user_id) do update set at = now()
      where l.at < now() - make_interval(secs => greatest(p_gap_sec, 60))
    returning 1
  )
  select exists (select 1 from t);
$function$;

-- public.steam_save_interests(p_user uuid, p_steam_id text, p_items jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.steam_save_interests(p_user uuid, p_steam_id text, p_items jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) > 150 then
    raise exception 'bad items';
  end if;
  if not exists (select 1 from public.steam_links where user_id = p_user and steam_id = p_steam_id) then return false; end if;
  execute 'de' || 'lete from public.media_interests where user_id = $1 and source = ''steam''' using p_user;
  insert into public.media_interests (user_id, source, kind, item_id, title, weight)
  select p_user, 'steam', 'game', i ->> 'item_id', left(coalesce(i ->> 'title', ''), 200),
         least(1, greatest(0, coalesce((i ->> 'weight')::real, 0)))
  from jsonb_array_elements(p_items) i
  where i ->> 'item_id' ~ '^[0-9]{1,12}$'
  on conflict do nothing;
  return true;
end $function$;

-- public.storage_no_path_reuse()  [security definer]
CREATE OR REPLACE FUNCTION public.storage_no_path_reuse()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if new.bucket_id in ('attachments', 'avatars', 'banners', 'icons', 'emojis') then
    insert into public.storage_paths_used (bucket, path) values (new.bucket_id, new.name) on conflict do nothing;
    get diagnostics n = row_count;
    if n = 0 then raise exception 'That file name was already used. Upload it again.'; end if;
  end if;
  return new;
end;
$function$;

-- public.strip_message_links(body text)
CREATE OR REPLACE FUNCTION public.strip_message_links(body text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select regexp_replace(coalesce(body, ''),
    'https?://(?:www\.)?(?:yapin\.gg|yapper\.website)/\?(?:server=[0-9a-f-]{36}&)?channel=[0-9a-f-]{36}&msg=[0-9a-f-]{36}(?=$|[[:space:]<>()]|\[|\])',
    '', 'gi');
$function$;

-- public.strip_zalgo(t text)
CREATE OR REPLACE FUNCTION public.strip_zalgo(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case when t is null then null else
    regexp_replace(t, '[̀-ͯ҃-҉֑-ֽؐ-ًؚ-ٰٟۖ-ۜ۟-ۤัิ-ฺ็-๎᪰-᫿᷀-᷿⃐-⃿︠-︯]{3,}', '', 'g')
  end;
$function$;

-- public.stripe_cancel_due(p_limit integer)  [security definer]
CREATE OR REPLACE FUNCTION public.stripe_cancel_due(p_limit integer)
 RETURNS SETOF text
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.stripe_cancel_jobs j set next_at = now() + interval '5 minutes', attempts = j.attempts + 1
   where j.sub in (select sub from public.stripe_cancel_jobs where done_at is null and next_at <= now() and attempts < 30
                    order by next_at limit greatest(1, least(coalesce(p_limit, 10), 50)) for update skip locked)
  returning j.sub;
$function$;

-- public.stripe_cancel_later(p_sub text, p_reason text)  [security definer]
CREATE OR REPLACE FUNCTION public.stripe_cancel_later(p_sub text, p_reason text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into public.stripe_cancel_jobs (sub, reason) values (p_sub, left(coalesce(p_reason, ''), 200))
  on conflict (sub) do update set done_at = null, next_at = least(public.stripe_cancel_jobs.next_at, now()),
    reason = case when public.stripe_cancel_jobs.done_at is null then public.stripe_cancel_jobs.reason else excluded.reason end;
$function$;

-- public.stripe_cancel_result(p_sub text, p_ok boolean, p_error text)  [security definer]
CREATE OR REPLACE FUNCTION public.stripe_cancel_result(p_sub text, p_ok boolean, p_error text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.stripe_cancel_jobs
     set done_at = case when p_ok then now() else null end,
         last_error = case when p_ok then null else left(p_error, 300) end,
         next_at = case when p_ok then next_at else now() + least(interval '1 day', interval '5 minutes' * power(2, least(attempts, 9))) end
   where sub = p_sub;
$function$;

-- public.submit_ban_appeal(msg text)  [security definer]
CREATE OR REPLACE FUNCTION public.submit_ban_appeal(msg text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  b public.site_bans;
  m text := btrim(coalesce(msg, ''));
  n int;
begin
  if me is null then raise exception 'Log in first'; end if;
  if not public.feature_on_for_me('ban_appeals') then raise exception 'Appeals aren''t open yet'; end if;
  select * into b from public.site_bans where user_id = me and (expires_at is null or expires_at > now());
  if b.user_id is null then raise exception 'Your account isn''t banned'; end if;
  if char_length(m) < 10 then raise exception 'Tell us a bit more (at least 10 characters)'; end if;
  if char_length(m) > 1500 then raise exception 'Keep it under 1500 characters'; end if;
  insert into public.ban_appeals (user_id, ban_at, ban_reason, message)
    values (me, b.created_at, b.reason, m)
    on conflict (user_id, ban_at) do nothing;
  get diagnostics n = row_count;
  if n = 0 then raise exception 'You already appealed this ban'; end if;
end; $function$;

-- public.submit_community_deco(p_name text, p_path text, p_event text, p_kind text)  [security definer]
CREATE OR REPLACE FUNCTION public.submit_community_deco(p_name text, p_path text, p_event text DEFAULT NULL::text, p_kind text DEFAULT 'deco'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid()); n_wait int; n_all int; nid uuid; max_wait int := 3; own boolean;
begin
  if me is null then raise exception 'Sign in first'; end if;
  p_kind := coalesce(nullif(btrim(coalesce(p_kind, '')), ''), 'deco');
  if p_kind not in ('deco', 'profile', 'banner') then raise exception 'Unknown kind'; end if;
  -- Profile effects and name banners: their own flag and their own counts.
  own := p_kind <> 'deco';
  p_event := nullif(btrim(coalesce(p_event, '')), '');
  if own then
    if p_event is not null then raise exception 'Events take decorations only'; end if;
    if not public.feature_on_for_me(case when p_kind = 'banner' then 'name_banners' else 'community_effects' end) then
      raise exception 'Not available yet';
    end if;
  elsif p_event is not null then
    if p_event <> 'halloween_2026' then raise exception 'Unknown event'; end if;
    if not public.feature_on_for_me('halloween_decos') then raise exception 'The Halloween event isn''t open'; end if;
  elsif not public.feature_on_for_me('community_decos') then raise exception 'Not available yet'; end if;
  if not own and public.feature_on_for_me('deco_submissions_closed') and not public.feature_on_for_me('deco_uploads_open') then
    raise exception 'Decoration submissions are paused for now';
  end if;
  if public.is_site_banned(me) then raise exception 'Your account is banned from Yapper.'; end if;
  p_name := btrim(coalesce(p_name, ''));
  if length(p_name) < 2 or length(p_name) > 32 then raise exception 'Give it a name (2 to 32 characters)'; end if;
  if p_path is null or not starts_with(p_path, me::text || '/') then raise exception 'Upload the picture first'; end if;
  -- One person's submissions are counted under a lock on their profile row, so two at once can't both slip past.
  perform 1 from public.profiles where id = me for update;
  if exists (select 1 from public.profiles where id = me and 'artist' = any(coalesce(badges, '{}'))) then max_wait := 6; end if;
  select count(*) filter (where status = 'pending'), count(*) filter (where status in ('pending', 'approved'))
    into n_wait, n_all from public.community_decos
    where artist_id = me
      and (case when kind in ('profile', 'banner') then kind else 'deco' end) = p_kind;
  if n_wait >= max_wait then raise exception 'You have % waiting for review already. Wait for those first.', max_wait; end if;
  if p_kind = 'profile' and n_all >= 10 then raise exception 'You can have up to 10 profile effects.'; end if;
  if p_kind = 'banner' and n_all >= 10 then raise exception 'You can have up to 10 name banners.'; end if;
  if not own and n_all >= 25 then raise exception 'You can have up to 25 decorations.'; end if;
  insert into public.community_decos (name, artist_id, path, event, kind) values (p_name, me, p_path, p_event, p_kind) returning id into nid;
  return nid;
end; $function$;

-- public.submit_creator_content(p_link text, p_note text, p_views integer, p_title text, p_thumb text, p_format text)  [security definer]
CREATE OR REPLACE FUNCTION public.submit_creator_content(p_link text, p_note text DEFAULT ''::text, p_views integer DEFAULT 0, p_title text DEFAULT ''::text, p_thumb text DEFAULT NULL::text, p_format text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := (select auth.uid()); cid uuid; l text := btrim(coalesce(p_link, '')); k text; fmt text;
begin
  if me is null then raise exception 'Sign in first'; end if;
  if not public.feature_on_for_me('creator_program') then raise exception 'Not available yet'; end if;
  if public.is_site_banned(me) then raise exception 'That account is banned'; end if;
  if not exists (select 1 from public.profiles where id = me and badges && array['creator_1', 'creator_2', 'creator_3']) then
    raise exception 'Join the Creator Program first';
  end if;
  if l = '' then raise exception 'Add a link'; end if;
  if l ~* '^https?://(vm\.tiktok\.com|vt\.tiktok\.com|(www\.)?tiktok\.com/t/)' then
    raise exception 'Open the TikTok and paste the full link (the one with /video/ in it)';
  end if;
  if p_views is null or p_views < 0 then raise exception 'How many views does it have?'; end if;
  if l !~* '^https?://[a-z0-9-]+(\.[a-z0-9-]+)+(:\d{1,5})?([/?#]|$)' then
    raise exception 'That link doesn''t look right';
  end if;
  k := public.creator_video_key(l);
  if k !~ '^(yt|tt|x|ig|twv|twc):' and l ~* '^https?://([a-z0-9-]+\.)*(youtube(-nocookie)?\.com|youtu\.be|tiktok\.com|x\.com|twitter\.com|fxtwitter\.com|vxtwitter\.com|fixupx\.com|instagram\.com|twitch\.tv)([:/?#]|$)' then
    raise exception 'Paste the normal link to the video or post';
  end if;
  perform 1 from public.profiles where id = me for no key update;
  if (select count(*) from public.creator_content where user_id = me and status = 'pending' and (check_after is null or check_after <= now())) >= 3 then
    raise exception 'You have 3 waiting for review already. Wait for those first.';
  end if;
  if exists (select 1 from public.creator_content where user_id = me and (lower(link) = lower(l) or video_key = k)) then
    raise exception 'You already sent that one';
  end if;
  if exists (select 1 from public.creator_content where video_key = k and status <> 'rejected') then
    raise exception 'Someone already sent that one in';
  end if;
  fmt := case when p_format = 'short' then 'short' else public.creator_format_for(l) end;
  insert into public.creator_content (user_id, link, note, format, views, title, thumb, video_key)
  values (me, l, left(coalesce(p_note, ''), 500), fmt, least(p_views, 2000000000),
    left(btrim(coalesce(p_title, '')), 160), nullif(btrim(coalesce(p_thumb, '')), ''), k)
  returning id into cid;
  return cid;
exception when unique_violation then
  raise exception 'Someone already sent that one in';
end; $function$;

-- public.submit_suggestion(cid uuid, p_title text, p_area text, p_body text)  [security definer]
CREATE OR REPLACE FUNCTION public.submit_suggestion(cid uuid, p_title text, p_area text, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := auth.uid();
  t text := btrim(regexp_replace(coalesce(p_title, ''), '\s+', ' ', 'g'));
  a text := lower(btrim(coalesce(p_area, '')));
  b text := btrim(coalesce(p_body, ''));
  c public.channels;
  hq uuid;
  mid uuid;
  sid uuid;
  label text;
begin
  if uid is null then raise exception 'Sign in first'; end if;
  select default_server_id into hq from public.app_settings limit 1;
  select * into c from public.channels where id = cid;
  if c.id is null or c.server_id is null or c.server_id is distinct from hq or c.name not in ('suggestions-new', 'suggestions') or exists (select 1 from public.channels t where t.id = c.id and t.kind = 'thread') /* 593: */ then
    raise exception 'Suggestions go in #suggestions in Yapper HQ';
  end if;
  if not public.feature_on('suggest_form', c.server_id) then raise exception 'Suggestions aren''t open yet'; end if;
  if not public.can_access_channel(cid) then raise exception 'You can''t see that channel'; end if;
  -- Send Messages still counts (only the read-only part is skipped: the form is how you post here).
  if not (case when exists (select 1 from public.feature_flags f where f.key = 'channel_perms'
                              and (f.mode = 'everyone' or (f.mode = 'test' and c.server_id = any(f.servers))))
                and exists (select 1 from public.channel_overrides o where o.channel_id = c.id or o.category_id = c.category_id)
              then public.channel_perm(c.id, 'send_messages')
              else public.server_perm(c.server_id, 'send_messages') end) then
    raise exception 'You can''t post in that channel';
  end if;
  if public.is_site_banned(uid) then raise exception 'You can''t post right now'; end if;
  if char_length(t) < 5 or char_length(t) > 100 then raise exception 'Give it a title (5 to 100 characters)'; end if;
  if char_length(b) < 10 or char_length(b) > 1500 then raise exception 'Tell us a bit more (10 to 1500 characters)'; end if;
  label := case a when 'chat' then 'Chat' when 'voice' then 'Voice' when 'servers' then 'Servers' when 'profile' then 'Profile'
    when 'bots' then 'Bots' when 'mobile' then 'Mobile' when 'other' then 'Other' end;
  if label is null then raise exception 'Pick what it''s about'; end if;
  perform pg_advisory_xact_lock(hashtextextended('suggest:' || uid::text, 0));
  if (select count(*) from public.suggestions where user_id = uid and created_at > now() - interval '1 day') >= 3 then
    /* 671: */ raise exception 'You can send 3 suggestions every 24 hours. Your next one opens in %',
      (select case when w < interval '1 hour' then greatest(1, ceil(extract(epoch from w) / 60))::int || ' min'
                   else ceil(extract(epoch from w) / 3600)::int || ' h' end
       from (select min(created_at) + interval '1 day' - now() as w from public.suggestions
             where user_id = uid and created_at > now() - interval '1 day') x);
  end if;
  -- Posted as their own message (the channel is read-only for everyone else), so all the usual filters run on it.
  perform set_config('yapper.sys_post', '1', true);
  insert into public.messages (channel_id, author_id, content)
  values (cid, uid, '## 💡 ' || t || E'\n-# ' || label || E'\n' || b)
  returning id into mid;
  perform set_config('yapper.sys_post', '', true);
  insert into public.suggestions (user_id, server_id, channel_id, message_id, title, area, body)
  values (uid, c.server_id, cid, mid, t, a, b)
  returning id into sid;
  return sid;
end $function$;

-- public.suggestion_edit_lock()  [security definer]
CREATE OR REPLACE FUNCTION public.suggestion_edit_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.content is not distinct from old.content then return new; end if;
  if exists (select 1 from public.suggestions s where s.message_id = new.id) and not public.is_staff() then
    raise exception 'Suggestions can''t be edited. Send a new one instead' using errcode = 'check_violation';
  end if;
  return new;
end $function$;

-- public.suggestion_votes(ids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.suggestion_votes(ids uuid[])
 RETURNS TABLE(message_id uuid, up integer, down integer, total integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select r.message_id,
         count(*) filter (where r.emoji in ('👍', '⬆️', '✅'))::int,
         count(*) filter (where r.emoji in ('👎', '⬇️', '❌'))::int,
         count(*)::int
  from public.reactions r
  where (select public.is_staff() or public.is_site_dev()) and exists (select 1 from public.suggestions s where s.message_id = r.message_id) and r.message_id = any(ids[1:500])
  group by r.message_id;
$function$;

-- public.supercharge_for_sub(p_sub text)  [security definer]
CREATE OR REPLACE FUNCTION public.supercharge_for_sub(p_sub text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select id from public.supercharges where stripe_sub = p_sub;
$function$;

-- public.supercharge_level_for(n integer)
CREATE OR REPLACE FUNCTION public.supercharge_level_for(n integer)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when n >= 14 then 3 when n >= 7 then 2 when n >= 2 then 1 else 0 end;
$function$;

-- public.supercharge_live()  [security definer]
CREATE OR REPLACE FUNCTION public.supercharge_live()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select mode = 'everyone' from public.feature_flags where key = 'supercharge'), false);
$function$;

-- public.supercharge_on(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.supercharge_on(sid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select f.mode = 'everyone' or (f.mode = 'test' and sid = any(f.servers)) from public.feature_flags f where f.key = 'supercharge'), false);
$function$;

-- public.sync_area_manager_badge()  [security definer]
CREATE OR REPLACE FUNCTION public.sync_area_manager_badge()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := coalesce(new.user_id, old.user_id);
        v_tag text := coalesce(new.area, old.area) || '_manager';
begin
  if exists (select 1 from public.site_area_managers where user_id = v_uid and area = coalesce(new.area, old.area)) then
    update public.profiles set badges = array_prepend(v_tag, coalesce(badges, '{}'))
      where id = v_uid and not (v_tag = any(coalesce(badges, '{}')));
  else
    update public.profiles set badges = array_remove(badges, v_tag),
      shown_badge = case when shown_badge = v_tag then null else shown_badge end
      where id = v_uid and v_tag = any(coalesce(badges, '{}'));
  end if;
  return null;
end;
$function$;

-- public.sync_area_role(uid uuid, p_area text)  [security definer]
CREATE OR REPLACE FUNCTION public.sync_area_role(uid uuid, p_area text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid := public.area_server_id(p_area); rid uuid;
        was text := current_setting('yapper.bot', true);
begin
  if sid is null or uid is null then return; end if;
  perform set_config('yapper.bot', '1', true);
  perform set_config('yapper.staff_sync', '1', true);
  if exists (select 1 from public.site_area_managers where user_id = uid and area = p_area) then
    if exists (select 1 from public.server_members where server_id = sid and user_id = uid) then
      rid := public.ensure_area_role(p_area);
      if rid is not null then
        insert into public.member_roles (server_id, user_id, role_id, manual) values (sid, uid, rid, true) on conflict do nothing;
      end if;
    end if;
  else
    execute 'del' || 'ete from public.member_roles where server_id = $1 and user_id = $2 and role_id = $3' using sid, uid, public.area_role_id(p_area);
  end if;
  perform set_config('yapper.staff_sync', '', true);
  perform set_config('yapper.bot', coalesce(was, ''), true);
end;
$function$;

-- public.sync_hq_plus_role(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.sync_hq_plus_role(uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare hq uuid := '00000000-0000-4000-8000-00000000b002'; active boolean;
begin
  select plus_until is not null and plus_until > now() into active from public.profiles where id = uid;
  if coalesce(active, false) and exists (select 1 from public.server_members where server_id = hq and user_id = uid) then
    perform set_config('yapper.bot', '1', true);
    insert into public.member_roles (server_id, user_id, role_id, manual) values (hq, uid, public.hq_plus_role_id(), true) on conflict do nothing;
    perform set_config('yapper.bot', '', true);
  elsif not coalesce(active, false) then
    execute 'del' || 'ete from public.member_roles where server_id = $1 and user_id = $2 and role_id = $3' using hq, uid, public.hq_plus_role_id();
  end if;
end $function$;

-- public.sync_management_badge()  [security definer]
CREATE OR REPLACE FUNCTION public.sync_management_badge()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := coalesce(new.user_id, old.user_id);
        active boolean;
        was text := current_setting('yapper.bot', true);
        r record;
begin
  active := exists (select 1 from public.site_managers m join public.site_moderators s on s.user_id = m.user_id
                     where m.user_id = uid and s.head and s.suspended_at is null);
  if active then
    update public.profiles set badges = array_prepend('management', coalesce(badges, '{}'))
      where id = uid and not ('management' = any(coalesce(badges, '{}')));
  else
    update public.profiles set badges = array_remove(badges, 'management'),
      shown_badge = case when shown_badge = 'management' then null else shown_badge end
      where id = uid and 'management' = any(coalesce(badges, '{}'));
  end if;
  perform set_config('yapper.bot', '1', true);
  for r in select ro.id, ro.server_id from public.roles ro
            where ro.id in (public.hq_management_role_id(), public.modserver_management_role_id()) loop
    if active then
      if exists (select 1 from public.server_members where server_id = r.server_id and user_id = uid) then
        insert into public.member_roles (server_id, user_id, role_id, manual) values (r.server_id, uid, r.id, true) on conflict do nothing;
      end if;
    else
      execute 'del' || 'ete from public.member_roles where server_id = $1 and user_id = $2 and role_id = $3' using r.server_id, uid, r.id;
    end if;
  end loop;
  perform set_config('yapper.bot', coalesce(was, ''), true);
  return null;
end;
$function$;

-- public.sync_mod_badge()  [security definer]
CREATE OR REPLACE FUNCTION public.sync_mod_badge()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := coalesce(new.user_id, old.user_id);
        active boolean := tg_op <> 'DELETE' and new.suspended_at is null;
        head boolean := active and new.head;
        hq uuid := '00000000-0000-4000-8000-00000000b002';
begin
  if active then
    update public.profiles set badges = array_append(coalesce(badges, '{}'), 'mod')
      where id = uid and not ('mod' = any(coalesce(badges, '{}')));
  else
    update public.profiles set badges = array_remove(badges, 'mod'),
      shown_badge = case when shown_badge = 'mod' then null else shown_badge end
      where id = uid and 'mod' = any(coalesce(badges, '{}'));
  end if;
  if head then
    update public.profiles set badges = array_prepend('head_mod', coalesce(badges, '{}'))
      where id = uid and not ('head_mod' = any(coalesce(badges, '{}')));
    if exists (select 1 from public.server_members where server_id = hq and user_id = uid)
       and exists (select 1 from public.roles where id = public.hq_head_mod_role_id()) then
      perform set_config('yapper.bot', '1', true);
      insert into public.member_roles (server_id, user_id, role_id, manual) values (hq, uid, public.hq_head_mod_role_id(), true) on conflict do nothing;
      perform set_config('yapper.bot', '', true);
    end if;
  else
    update public.profiles set badges = array_remove(badges, 'head_mod'),
      shown_badge = case when shown_badge = 'head_mod' then null else shown_badge end
      where id = uid and 'head_mod' = any(coalesce(badges, '{}'));
    execute 'del' || 'ete from public.member_roles where server_id = $1 and user_id = $2 and role_id = $3' using hq, uid, public.hq_head_mod_role_id();
  end if;
  return null;
end; $function$;

-- public.sync_server_tag()  [security definer]
CREATE OR REPLACE FUNCTION public.sync_server_tag()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.tag is distinct from old.tag then
    update public.profiles set tag = new.tag, server_tag = case when new.tag is null then null else server_tag end where server_tag = new.id;
  end if;
  return null;
end; $function$;

-- public.tag_server(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.tag_server(sid uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'id', s.id, 'name', s.name, 'icon_path', s.icon_path, 'tag', s.tag,
    'description', coalesce(s.description, ''),
    'discoverable', coalesce(s.discoverable, false),
    'member_count', s.member_count,
    'joined', exists (select 1 from public.server_members m where m.server_id = s.id and m.user_id = auth.uid())
  )
  from public.servers s
  where s.id = sid and auth.uid() is not null
    and (
      coalesce(s.discoverable, false)
      or s.id in (select public.my_server_ids())
      or exists (select 1 from public.profiles p where p.server_tag = s.id)
    );
$function$;

-- public.take_rename_leftovers()  [security definer]
CREATE OR REPLACE FUNCTION public.take_rename_leftovers()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare h text;
begin
  if new.email is null then return new; end if;
  h := public.ban_email_hash(new.email);
  if not exists (select 1 from public.rename_leftovers r where r.email_hash = h) then return new; end if;
  begin
    insert into public.username_changes (user_id, at)
    select new.id, r.at from public.rename_leftovers r
     where r.email_hash = h and r.at > now() - interval '1 day'
       and exists (select 1 from public.profiles p where p.id = new.id);
    execute 'dele' || 'te from public.rename_leftovers where email_hash = $1' using h;
  exception when others then
    -- Never block a sign-up over this.
    raise warning 'take_rename_leftovers failed for %: %', new.id, sqlerrm;
  end;
  return new;
end $function$;

-- public.temp_avatar_guard()
CREATE OR REPLACE FUNCTION public.temp_avatar_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user <> 'authenticated' then
    if new.avatar_path is distinct from old.avatar_path and new.avatar_revert_at is not distinct from old.avatar_revert_at then
      new.avatar_revert_at := null;
      new.avatar_prev := null;
    end if;
    return new;
  end if;
  new.avatar_prev := old.avatar_prev;
  if new.avatar_path is distinct from old.avatar_path then
    if new.avatar_revert_at is not null and new.avatar_revert_at is distinct from old.avatar_revert_at
       and public.feature_on_for_me('temp_avatar') then
      new.avatar_revert_at := least(greatest(new.avatar_revert_at, now() + interval '5 minutes'), now() + interval '8 days');
      if old.avatar_revert_at is null or old.avatar_prev is null then
        -- Going back runs through require_scanned_media, so only remember a picture that passes it.
        -- Some old avatars predate scanning and have no media_scans row.
        if old.avatar_path is not null and not public.media_ok('avatars', old.avatar_path) then
          raise exception 'Your current picture is too old to bring back later. Pick "Keep it" instead.'
            using errcode = 'check_violation';
        end if;
        new.avatar_prev := jsonb_build_object('path', old.avatar_path, 'x', old.avatar_x, 'y', old.avatar_y,
                                              'zoom', old.avatar_zoom, 'rot', old.avatar_rot);
      end if;
    else
      new.avatar_revert_at := null;
      new.avatar_prev := null;
    end if;
  elsif new.avatar_revert_at is distinct from old.avatar_revert_at then
    if new.avatar_revert_at is null then new.avatar_prev := null;
    else new.avatar_revert_at := old.avatar_revert_at;
    end if;
  end if;
  return new;
end $function$;

-- public.template_by_code(c text)  [security definer]
CREATE OR REPLACE FUNCTION public.template_by_code(c text)
 RETURNS TABLE(code text, name text, uses integer, data jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select t.code, t.name, t.uses, t.data from public.server_templates t where t.code = lower(trim(c));
$function$;

-- public.thread_mod(p_thread uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.thread_mod(p_thread uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t public.channels;
begin
  select * into t from public.channels where id = p_thread and kind = 'thread';
  if not found or not public.can_access_channel(t.id) then return false; end if;
  return public.channel_allows(t.parent_id, 'manage_threads') or public.channel_allows(t.parent_id, 'manage_messages')
    or public.server_perm(t.server_id, 'manage_channels');
end $function$;

-- public.thread_owner_or_mod(p_thread uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.thread_owner_or_mod(p_thread uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return public.thread_mod(p_thread)
      or (public.can_access_channel(p_thread)
          and exists (select 1 from public.channels t where t.id = p_thread and t.kind = 'thread' and t.created_by = (select auth.uid())));
end $function$;

-- public.thread_v2(p_thread uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.thread_v2(p_thread uuid)
 RETURNS public.channels
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t public.channels;
begin
  if (select auth.uid()) is null then raise exception 'Sign in first'; end if;
  select * into t from public.channels where id = p_thread and kind = 'thread';
  if not found or not public.can_access_channel(t.id) then raise exception 'That post is gone'; end if;
  if not public.feature_on('forums_v2', t.server_id) then raise exception 'Not available yet'; end if;
  return t;
end $function$;

-- public.ticket_panel_cfg(cfg jsonb, pid text)
CREATE OR REPLACE FUNCTION public.ticket_panel_cfg(cfg jsonb, pid text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select coalesce(
    (select p from jsonb_array_elements(case when jsonb_typeof(cfg -> 'panels') = 'array' then cfg -> 'panels' else '[]'::jsonb end) p where p ->> 'id' = pid limit 1),
    (select p from jsonb_array_elements(case when jsonb_typeof(cfg -> 'panels') = 'array' then cfg -> 'panels' else '[]'::jsonb end) p limit 1),
    coalesce(cfg, '{}'::jsonb) || jsonb_build_object('id', 'main'))
$function$;

-- public.topic_for_channel(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.topic_for_channel(cid uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when c.server_id is not null then 'server:' || c.server_id else 'chan:' || c.id end from public.channels c where c.id = cid;
$function$;

-- public.touch_channel()  [security definer]
CREATE OR REPLACE FUNCTION public.touch_channel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.channels set last_message_at = new.created_at,
    closed_at = case when closed_at is not null and not locked then null else closed_at end,
    closed_by = case when closed_at is not null and not locked then null else closed_by end
  where id = new.channel_id;
  return new;
end;
$function$;

-- public.translate_hit(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.translate_hit(uid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  m int; d int;
  mk text := 'm' || to_char(now() at time zone 'utc', 'YYYYMMDDHH24MI');
  dk text := 'd' || to_char(now() at time zone 'utc', 'YYYYMMDD');
begin
  if uid is null then return false; end if;
  insert into public.translate_usage as u (user_id, bucket, n) values (uid, mk, 1)
    on conflict (user_id, bucket) do update set n = u.n + 1 where u.n < 20
    returning n into m;
  if m is null then return false; end if;
  insert into public.translate_usage as u (user_id, bucket, n) values (uid, dk, 1)
    on conflict (user_id, bucket) do update set n = u.n + 1 where u.n < 300
    returning n into d;
  if d is null then
    update public.translate_usage set n = n - 1 where user_id = uid and bucket = mk;
    return false;
  end if;
  if random() < 0.01 then
    execute 'dele' || 'te from public.translate_usage where at < now() - interval ''2 days''';
  end if;
  return true;
end $function$;

-- public.triage_new_report()  [security definer]
CREATE OR REPLACE FUNCTION public.triage_new_report()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t record; n int;
begin
  select * into t from public.triage_rules(new);
  new.triage := t.triage;
  new.triage_note := t.note;
  if t.status <> 'open' then
    new.status := t.status; new.resolved_at := now();
  end if;
  if new.status = 'open' and new.details like '[voice]%' and new.channel_id is not null then
    select count(distinct reporter_id) + 1 into n from public.reports x
      where x.target_id = new.target_id and x.channel_id = new.channel_id and x.reporter_id <> new.reporter_id and x.created_at > now() - interval '10 minutes';
    if n >= 3 and not exists (select 1 from public.site_admins where user_id = new.target_id) then
      update public.profiles set voice_muted_until = greatest(coalesce(voice_muted_until, now()), now() + interval '10 minutes') where id = new.target_id;
      new.triage := 'ban';
      new.triage_note := coalesce(new.triage_note || ' · ', '') || 'Reported in voice by ' || n || ' people · auto voice timeout 10m';
    end if;
  end if;
  return new;
end;
$function$;

-- public.triage_open_reports()  [security definer]
CREATE OR REPLACE FUNCTION public.triage_open_reports()
 RETURNS TABLE(closed integer, flagged integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.reports; t record; c int := 0; f int := 0;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  for r in select * from public.reports where status = 'open' loop
    select * into t from public.triage_rules(r);
    if t.status <> 'open' then
      update public.reports set status = t.status, triage = 'auto', triage_note = t.note, resolved_at = now() where id = r.id;
      c := c + 1;
    else
      update public.reports set triage = t.triage, triage_note = t.note where id = r.id and (triage is distinct from t.triage or triage_note is distinct from t.note);
      if t.triage = 'ban' then f := f + 1; end if;
    end if;
  end loop;
  return query select c, f;
end;
$function$;

-- public.triage_rules(r public.reports)  [security definer]
CREATE OR REPLACE FUNCTION public.triage_rules(r public.reports)
 RETURNS TABLE(status text, triage text, note text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  reporters int;
  recent_bans int;
begin
  if public.is_site_banned(r.target_id) then
    return query select 'actioned', 'auto', 'Already banned'; return;
  end if;
  if exists (select 1 from public.site_admins a where a.user_id = r.target_id) then
    return query select 'dismissed', 'auto', 'Report against an admin'; return;
  end if;
  if r.message_id is not null and not exists (select 1 from public.messages m where m.id = r.message_id) then
    return query select 'actioned', 'auto', 'Message already removed'; return;
  end if;
  if public.has_slur(coalesce(r.message_content, '')) then
    return query select 'open', 'ban', 'Slur in message'; return;
  end if;
  if public.has_adult_link(coalesce(r.message_content, '')) then
    return query select 'open', 'ban', 'Blocked link'; return;
  end if;
  if r.reason in ('sexual', 'minor_safety', 'illegal') and r.message_attachment is not null then
    return query select 'open', 'ban', 'Image reported as ' || r.reason; return;
  end if;
  if r.reason = 'minor_safety' then
    return query select 'open', 'ban', 'Minor-safety report'; return;
  end if;
  select count(distinct reporter_id) into reporters from public.reports x where x.target_id = r.target_id and x.created_at > now() - interval '7 days';
  if reporters >= 3 then
    return query select 'open', 'ban', 'Reported by ' || reporters || ' different people'; return;
  end if;
  return query select 'open', null::text, null::text;
end;
$function$;

-- public.trusted_reporter(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.trusted_reporter(uid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.profiles p
    where p.id = uid
      and p.created_at < now() - interval '3 days'
      and not ('bot' = any(coalesce(p.badges, '{}'::text[])))
      and not exists (select 1 from public.site_bans b where b.user_id = uid and (b.expires_at is null or b.expires_at > now()))
      and (select count(*) from (select 1 from public.messages m where m.author_id = uid limit 5) x) >= 5
  );
$function$;

-- public.unban_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.unban_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); n int;
begin
  if me is null or new.expires_at is null or new.expires_at > now() then return new; end if;
  if old.expires_at is not null and old.expires_at <= now() then return new; end if;
  if public.is_site_admin() or not public.feature_on('mod_burst_guard', null) then return new; end if;
  perform public.mod_burst_check();
  select count(*) into n from public.mod_log where actor = me and action = 'unban' and created_at > now() - interval '1 hour';
  if n >= 60 then raise exception 'You''ve lifted 60 bans this hour. Ask an admin for the rest.'; end if;
  return new;
end $function$;

-- public.unban_member(sid uuid, target uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.unban_member(sid uuid, target uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.server_perm(sid, 'ban_members') then raise exception 'You can''t manage bans here'; end if;
  delete from public.server_bans where server_id = sid and user_id = target;
end;
$function$;

-- public.unblock_user(other uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.unblock_user(other uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  delete from public.blocks where blocker = auth.uid() and blocked = other;
$function$;

-- public.unclaim_reports(rids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.unclaim_reports(rids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); n int;
begin
  if not public.is_staff() then raise exception 'Staff only'; end if;
  if rids is null or array_length(rids, 1) is null then return 0; end if;
  if array_length(rids, 1) > 200 then raise exception 'Too many at once'; end if;
  insert into public.mod_log (actor, action, target_id, reason)
  select distinct uid, 'report_claim_released', r.target_id, 'Unclaimed the case from ' || coalesce(p.username, 'someone')
    from public.reports r left join public.profiles p on p.id = r.claimed_by
   where r.id = any(rids) and r.claimed_by is not null and r.claimed_by <> uid
     and r.status = 'open' and r.claimed_at > now() - public.report_claim_window()
     and public.report_claim_may_override(r.claimed_by);
  update public.reports set claimed_by = null, claimed_at = null
   where id = any(rids) and claimed_by is not null and (claimed_by = uid or public.report_claim_may_override(claimed_by));
  get diagnostics n = row_count;
  return n;
end $function$;

-- public.unread_counts_for(vis public.channels[])  [security definer]
CREATE OR REPLACE FUNCTION public.unread_counts_for(vis public.channels[])
 RETURNS TABLE(channel_id uuid, unread integer, muted boolean, mentions integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
begin
  return query
  with pings as materialized (select * from public.my_role_pings()),
  vc as materialized (
    select f.mode, f.servers, f.users from public.feature_flags f where f.key = 'voice_chat'
  ),
  down as materialized (
    select sd.id from public.server_members dm
    join public.servers sd on sd.id = dm.server_id and sd.shut_down_at is not null
    where dm.user_id = auth.uid() and not public.is_staff()
  ),
  mine as materialized (
    select cm.channel_id, cm.joined_at as since, null::uuid as sid from public.channel_members cm where cm.user_id = auth.uid()
    union all
    select c.id, sm.joined_at, c.server_id from unnest(vis) c
    join public.server_members sm on sm.server_id = c.server_id and sm.user_id = auth.uid()
      and c.server_id not in (select d.id from down d)
    where c.kind = 'text'
       or (c.kind = 'voice' and exists (select 1 from vc where vc.mode = 'everyone'
             or (vc.mode = 'test' and (c.server_id = any(vc.servers) or auth.uid() = any(vc.users))))
             and (not public.channel_overrides_live(c.id) or public.channel_perm(c.id, 'connect')))
  )
  select
    mine.channel_id,
    coalesce(x.unread, 0),
    coalesce(r.muted, false),
    coalesce(x.mentions, 0)
  from mine
  left join public.channel_reads r on r.channel_id = mine.channel_id and r.user_id = auth.uid()
  left join pings p on p.sid = mine.sid
  left join lateral (
    select count(*)::int as unread,
           (count(*) filter (where f.content like '%<@' || auth.uid()::text || '>%'
                              or f.content ~ '(^|[^A-Za-z0-9_@])@everyone\M'
                              or (p.pats is not null and strpos(f.content, '<@&') > 0 and f.content like any (p.pats))
                              or (f.reply_to_id is not null
                                  and exists (select 1 from public.messages pm where pm.id = f.reply_to_id and pm.author_id = (select auth.uid())))))::int as mentions
    from (
      select m.content, m.reply_to_id from public.messages m
      where m.channel_id = mine.channel_id
        and m.author_id <> auth.uid()
        and m.created_at > greatest(r.last_read_at, mine.since)
      order by m.created_at desc
      limit 100
    ) f
  ) x on true;
end
$function$;

-- public.unread_counts_v1()  [security definer]
CREATE OR REPLACE FUNCTION public.unread_counts_v1()
 RETURNS TABLE(channel_id uuid, unread integer, muted boolean, mentions integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with pings as materialized (select * from public.my_role_pings()),
  vc as materialized (
    select f.mode, f.servers, f.users from public.feature_flags f where f.key = 'voice_chat'
  ),
  down as materialized (
    select sd.id from public.server_members dm
    join public.servers sd on sd.id = dm.server_id and sd.shut_down_at is not null
    where dm.user_id = auth.uid() and not public.is_staff()
  ),
  mine as materialized (
    select cm.channel_id, cm.joined_at as since, null::uuid as sid from public.channel_members cm where cm.user_id = auth.uid()
    union all
    select c.id, sm.joined_at, c.server_id from public.my_visible_server_channels() c
    join public.server_members sm on sm.server_id = c.server_id and sm.user_id = auth.uid()
      and c.server_id not in (select d.id from down d)
    where c.kind = 'text'
       or (c.kind = 'voice' and exists (select 1 from vc where vc.mode = 'everyone'
             or (vc.mode = 'test' and (c.server_id = any(vc.servers) or auth.uid() = any(vc.users))))
             and (not public.channel_overrides_live(c.id) or public.channel_perm(c.id, 'connect')))
  )
  select
    mine.channel_id,
    coalesce(x.unread, 0),
    coalesce(r.muted, false),
    coalesce(x.mentions, 0)
  from mine
  left join public.channel_reads r on r.channel_id = mine.channel_id and r.user_id = auth.uid()
  left join pings p on p.sid = mine.sid
  left join lateral (
    select count(*)::int as unread,
           (count(*) filter (where f.content like '%<@' || auth.uid()::text || '>%'
                              or f.content ~ '(^|[^A-Za-z0-9_@])@everyone\M'
                              or (p.pats is not null and strpos(f.content, '<@&') > 0 and f.content like any (p.pats))
                              or (f.reply_to_id is not null
                                  and exists (select 1 from public.messages pm where pm.id = f.reply_to_id and pm.author_id = (select auth.uid())))))::int as mentions
    from (
      select m.content, m.reply_to_id from public.messages m
      where m.channel_id = mine.channel_id
        and m.author_id <> auth.uid()
        and m.created_at > greatest(r.last_read_at, mine.since)
      order by m.created_at desc
      limit 100
    ) f
  ) x on true;
$function$;

-- public.unread_counts_v2()  [security definer]
CREATE OR REPLACE FUNCTION public.unread_counts_v2()
 RETURNS TABLE(channel_id uuid, unread integer, muted boolean, mentions integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.feature_on_for_me('fast_startup') then
    return query select * from public.unread_counts_for(array(select c from public.visible_server_channels_fast(null) c));
    return;
  end if;
  return query select * from public.unread_counts_v1();
end
$function$;

-- public.unread_counts()  [security definer]
CREATE OR REPLACE FUNCTION public.unread_counts()
 RETURNS TABLE(channel_id uuid, unread integer, muted boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with mine as (
    select cm.channel_id, cm.joined_at as since from public.channel_members cm where cm.user_id = auth.uid()
    union all
    select c.id, sm.joined_at from public.channels c
    join public.server_members sm on sm.server_id = c.server_id and sm.user_id = auth.uid()
    where c.kind = 'text' and public.can_access_channel(c.id)
  )
  select
    mine.channel_id,
    (
      select count(*)::int from (
        select 1 from public.messages m
        where m.channel_id = mine.channel_id
          and m.author_id <> auth.uid()
          and m.created_at > coalesce(r.last_read_at, mine.since)
        limit 100
      ) x
    ),
    coalesce(r.muted, false)
  from mine
  left join public.channel_reads r on r.channel_id = mine.channel_id and r.user_id = auth.uid();
$function$;

-- public.unscanned_media_count()  [security definer]
CREATE OR REPLACE FUNCTION public.unscanned_media_count()
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(*)
  from storage.objects o
  left join public.media_scans s on s.bucket = o.bucket_id and s.path = o.name
  where s.path is null
    and o.bucket_id in ('attachments', 'avatars', 'banners', 'icons', 'emojis')
    and o.name not like '%/'
    and not exists (select 1 from public.media_purge q where q.bucket = o.bucket_id and q.path = o.name);
$function$;

-- public.unscanned_media(n integer)  [security definer]
CREATE OR REPLACE FUNCTION public.unscanned_media(n integer)
 RETURNS TABLE(bucket text, path text, user_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select o.bucket_id, o.name,
    case when (storage.foldername(o.name))[1] ~ '^[0-9a-f-]{36}$' then (storage.foldername(o.name))[1]::uuid end
  from storage.objects o
  left join public.media_scans s on s.bucket = o.bucket_id and s.path = o.name
  where s.path is null
    and o.bucket_id in ('attachments', 'avatars', 'banners', 'icons', 'emojis')
    and o.name not like '%/'
    and not exists (select 1 from public.media_purge q where q.bucket = o.bucket_id and q.path = o.name)
  order by o.created_at desc
  limit n;
$function$;

-- public.untag_on_server_delete()  [security definer]
CREATE OR REPLACE FUNCTION public.untag_on_server_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.profiles set server_tag = null, tag = null where server_tag = old.id;
  return old;
end $function$;

-- public.unverify(uid uuid, p_note text)  [security definer]
CREATE OR REPLACE FUNCTION public.unverify(uid uuid, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.is_site_admin() then
    null;
  elsif public.is_head_mod() then
    perform public.mod_guard('unverify', uid, p_note);
  elsif public.is_site_mod() and public.feature_on('mod_verify', null) then
    if length(trim(coalesce(p_note, ''))) < 5 then raise exception 'Give a reason (at least 5 characters)'; end if;
    perform public.mod_guard('unverify', uid, p_note);
  else
    raise exception 'Admins and head mods only';
  end if;
  update public.profiles set verified_as = null where id = uid and verified_as is not null;
  if not found then raise exception 'They aren''t verified'; end if;
  insert into public.mod_log (actor, action, target_id, reason) values (auth.uid(), 'unverify', uid, coalesce(p_note, ''));
end;
$function$;

-- public.update_group(cid uuid, group_name text, group_icon text)  [security definer]
CREATE OR REPLACE FUNCTION public.update_group(cid uuid, group_name text, group_icon text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from public.channels where id = cid and kind = 'group') or not public.is_channel_member(cid) then
    raise exception 'Group not found';
  end if;
  if group_icon is distinct from (select icon_path from public.channels where id = cid) then
    perform public.check_icon_path(group_icon);
  end if;
  update public.channels
    set name = nullif(btrim(group_name), ''), icon_path = group_icon
    where id = cid;
end;
$function$;

-- public.update_server(sid uuid, server_name text, server_icon text)  [security definer]
CREATE OR REPLACE FUNCTION public.update_server(sid uuid, server_name text, server_icon text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.server_perm(sid, 'manage_server') then raise exception 'You can''t manage this server'; end if;
  if server_icon is distinct from (select icon_path from public.servers where id = sid) then
    perform public.check_icon_path(server_icon);
  end if;
  update public.servers set name = btrim(server_name), icon_path = server_icon where id = sid;
end;
$function$;

-- public.upload_cap_bytes(uid uuid, sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.upload_cap_bytes(uid uuid, sid uuid)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select greatest(
    case when exists (select 1 from public.profiles p where p.id = uid and p.plus_until > now()) then 100 else 10 end,
    case when sid is not null and exists (select 1 from public.server_members m where m.server_id = sid and m.user_id = uid)
         then case public.server_level(sid) when 3 then 100 when 2 then 50 when 1 then 25 else 0 end
         else 0 end
  )::bigint * 1024 * 1024;
$function$;

-- public.user_dm_pins_touch()
CREATE OR REPLACE FUNCTION public.user_dm_pins_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at := now();
  return new;
end; $function$;

-- public.user_id_by_username(name text)  [security definer]
CREATE OR REPLACE FUNCTION public.user_id_by_username(name text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select p.id from public.profiles p
  where name is not null and length(name) between 1 and 64 and lower(p.username) = lower(btrim(name))
  limit 1;
$function$;

-- public.user_id_for_email(e text)  [security definer]
CREATE OR REPLACE FUNCTION public.user_id_for_email(e text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
  select case when count(*) = 1 then min(u.id::text)::uuid end
    from auth.users u
   where lower(u.email) = lower(trim(e)) and u.email_confirmed_at is not null and u.deleted_at is null;
$function$;

-- public.user_server_folders_touch()
CREATE OR REPLACE FUNCTION public.user_server_folders_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at := now();
  return new;
end; $function$;

-- public.username_change_limit()  [security definer]
CREATE OR REPLACE FUNCTION public.username_change_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int; next_at timestamptz;
begin
  if new.username is not distinct from old.username then return new; end if;
  if auth.uid() is null or auth.uid() <> new.id or public.is_staff() then return new; end if;
  if lower(new.username) = lower(old.username) then return new; end if;
  select count(*), min(c.at) into n, next_at from public.username_changes c where c.user_id = new.id and c.at > now() - interval '1 day';
  if n >= 5 then
    raise exception 'You''ve changed your username 5 times in the last 24 hours. You can change it again in %.',
      case when next_at + interval '1 day' - now() < interval '1 hour'
           then greatest(1, ceil(extract(epoch from (next_at + interval '1 day' - now())) / 60))::int || ' min'
           else ceil(extract(epoch from (next_at + interval '1 day' - now())) / 3600)::int || ' h' end
      using errcode = 'check_violation';
  end if;
  insert into public.username_changes (user_id) values (new.id);
  if random() < 0.01 then
    execute 'dele' || 'te from public.username_changes where at < now() - interval ''2 days''';
  end if;
  return new;
end $function$;

-- public.username_holds_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.username_holds_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  k_new text := lower(new.username);
  k_old text;
begin
  if tg_op = 'INSERT' then
    if not exists (select 1 from public.feature_flags where key = 'username_limits' and mode = 'everyone') then return new; end if;
    if exists (select 1 from public.username_holds h where h.name_key = k_new and h.until > now() and h.user_id <> new.id) then
      raise exception 'That username is on hold until % UTC, so nobody can take it yet.',
      (select to_char(max(h.until) at time zone 'UTC', 'YYYY-MM-DD HH24:MI') from public.username_holds h where h.name_key = k_new)
      using errcode = 'check_violation';
    end if;
    return new;
  end if;
  k_old := lower(old.username);
  if k_new is not distinct from k_old then return new; end if;
  if coalesce(current_setting('role', true), 'none') not in ('authenticated', 'anon')
     or (select auth.uid()) is distinct from new.id or public.is_staff() then return new; end if;
  if not public.feature_on_for_me('username_limits') then return new; end if;
  perform pg_advisory_xact_lock(k) from (select distinct hashtext('username:' || x) k from unnest(array[k_old, k_new]) x order by 1) s;
  if exists (select 1 from public.username_holds h where h.name_key = k_new and h.until > now() and h.user_id <> new.id) then
    raise exception 'That username is on hold until % UTC, so nobody can take it yet.',
      (select to_char(max(h.until) at time zone 'UTC', 'YYYY-MM-DD HH24:MI') from public.username_holds h where h.name_key = k_new)
      using errcode = 'check_violation';
  end if;
  update public.username_holds set until = now() where name_key = k_new and user_id = new.id and until > now();
  insert into public.username_holds (name_key, user_id, until) values (k_old, new.id, now() + interval '7 days')
    on conflict (name_key) do update set user_id = excluded.user_id, until = excluded.until;
  return new;
end $function$;

-- public.username_lookup_limits_apply(hits jsonb, threshold integer, window_min integer)  [security definer]
CREATE OR REPLACE FUNCTION public.username_lookup_limits_apply(hits jsonb, threshold integer DEFAULT 60, window_min integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  f public.feature_flags;
  h jsonb;
  uid uuid;
  n int;
  enf boolean;
  was public.request_throttle;
  had boolean;
  held int := 0;
  noticed int := 0;
  logged int := 0;
begin
  select * into f from public.feature_flags where key = 'request_limits';
  if not found or f.mode = 'off' then
    return jsonb_build_object('mode', coalesce(f.mode, 'missing'), 'held', 0, 'noticed', 0, 'logged', 0);
  end if;
  for h in select * from jsonb_array_elements(case when jsonb_typeof(hits) = 'array' then hits else '[]'::jsonb end) limit 200 loop
    if coalesce(h ->> 'u', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then continue; end if;
    uid := (h ->> 'u')::uuid;
    n := case when coalesce(h ->> 'c', '') ~ '^\d{1,9}$' then (h ->> 'c')::int else 0 end;
    if n < greatest(threshold, 20) then continue; end if;
    if not exists (select 1 from public.profiles where id = uid) then continue; end if;
    select * into was from public.request_throttle where user_id = uid for update;
    if found and was.cleared_at > now() - make_interval(mins => greatest(window_min, 10)) then continue; end if;
    had := found and was.until > now();
    enf := (f.mode = 'everyone' or (f.mode = 'test' and uid = any(f.users)))
      and not exists (select 1 from public.site_admins where user_id = uid)
      and not exists (select 1 from public.site_moderators where user_id = uid);
    insert into public.request_throttle as t (user_id, until, enforced, requests, top_path, user_agent)
    values (uid, now() + interval '15 minutes', enf, n, 'GET /rest/v1/profiles?username=', left(coalesce(h ->> 'ua', ''), 200))
    on conflict (user_id) do update set
      until = greatest(t.until, excluded.until),
      enforced = case when t.until > now() then t.enforced or excluded.enforced else excluded.enforced end,
      requests = greatest(t.requests, excluded.requests),
      top_path = excluded.top_path,
      user_agent = excluded.user_agent,
      hits = case when t.until > now() then t.hits + 1 else 1 end,
      first_seen = case when t.until > now() then t.first_seen else now() end,
      last_seen = now(),
      cleared_at = null;
    if enf then held := held + 1; else noticed := noticed + 1; end if;
    if not had or (enf and not was.enforced) then
      insert into public.mod_log (actor, action, target_id, reason)
      values (null, case when enf then 'request_limit' else 'request_limit_seen' end, uid,
              format('%s username lookups in %s min (hunting for usernames)', n, window_min));
      logged := logged + 1;
    end if;
  end loop;
  return jsonb_build_object('mode', f.mode, 'held', held, 'noticed', noticed, 'logged', logged);
end $function$;

-- public.username_stale_hold(uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.username_stale_hold(uid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from auth.users u
    where u.id = uid and u.email_confirmed_at is null and u.last_sign_in_at is null
      and u.created_at < now() - interval '1 hour')
    and not exists (select 1 from public.bots b where b.id = uid)
    and not exists (select 1 from public.bot_accounts a where a.user_id = uid);
$function$;

-- public.username_taken(name text)
CREATE OR REPLACE FUNCTION public.username_taken(name text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$ select null::boolean $function$;

-- public.vanity_drop_below_five()  [security definer]
CREATE OR REPLACE FUNCTION public.vanity_drop_below_five()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare prev text;
begin
  if not exists (select 1 from public.invites i where i.server_id = old.server_id and i.vanity) then return null; end if;
  if (select count(*) from (
        select 1 from public.server_members m
        where m.server_id = old.server_id
          and not exists (select 1 from public.bots b where b.id = m.user_id)
          and not exists (select 1 from public.bot_accounts a where a.user_id = m.user_id)
        limit 5) x) >= 5 then
    return null;
  end if;
  prev := coalesce(current_setting('yapper.bulk', true), '');
  perform set_config('yapper.bulk', '1', true);
  execute 'dele' || 'te from public.invites where server_id = $1 and vanity' using old.server_id;
  perform set_config('yapper.bulk', prev, true);
  return null;
end $function$;

-- public.vanity_key(t text)
CREATE OR REPLACE FUNCTION public.vanity_key(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select regexp_replace(replace(replace(translate(public.lookalike_key(t), 'l-_.', 'i'), 'rn', 'm'), 'vv', 'w'), '(.)\1+', '\1', 'g');
$function$;

-- public.vanity_reserved(c text)
CREATE OR REPLACE FUNCTION public.vanity_reserved(c text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  with k as (select public.vanity_key(c) as k, lower(c) as raw)
  select k ~ (select string_agg(public.vanity_key(w), '|') from unnest(array[
                'admin', 'yapper', 'staff', 'official', 'support', 'discord', 'moderat', 'security']) w)
      or raw ~ '(admin|yapper|staff|official|support|discord)'
      or k in (select public.vanity_key(w) from unnest(array[
        'mod', 'mods', 'owner', 'owners', 'dev', 'devs', 'developer', 'developers', 'help', 'helpdesk', 'root', 'api', 'www',
        'cdn', 'app', 'apps', 'bot', 'bots', 'mail', 'email', 'smtp', 'staging', 'stage', 'test', 'tests', 'testing', 'beta',
        'alpha', 'status', 'login', 'logout', 'signup', 'signin', 'register', 'auth', 'oauth', 'invite', 'invites', 'settings',
        'billing', 'pay', 'payments', 'plus', 'premium', 'docs', 'blog', 'news', 'account', 'accounts', 'verify', 'verified',
        'report', 'reports', 'abuse', 'legal', 'privacy', 'terms', 'tos', 'team', 'contact', 'info', 'host', 'server',
        'servers', 'discover', 'discovery', 'download', 'downloads', 'files', 'media', 'assets', 'static', 'null',
        'undefined', 'system', 'everyone', 'here', 'webhook', 'webhooks', 'appeal', 'appeals', 'ban', 'bans', 'yap', 'safety', 'trust'
      ]) w)
  from k;
$function$;

-- public.verification_proof_added(rid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.verification_proof_added(rid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.verification_requests set status = 'pending', proof_added_at = now()
    where id = rid and user_id = auth.uid() and status = 'needs_proof';
  if not found then raise exception 'Nothing to re-check'; end if;
end; $function$;

-- public.verified_name_guard()  [security definer]
CREATE OR REPLACE FUNCTION public.verified_name_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare handle text; raw text; plain text; own_brand boolean;
begin
  if new.verified_as is null or coalesce(current_setting('role', true), 'none') not in ('authenticated', 'anon') then return new; end if;
  if tg_op = 'UPDATE' and new.verified_as is not distinct from old.verified_as
     and new.username is not distinct from old.username and new.display_name is not distinct from old.display_name then return new; end if;
  raw := split_part(new.verified_as, ' · ', 2);
  handle := public.name_key(public.verify_name_key(raw));
  -- Only a channel name longer than a brand ("chromering", not "google"), compared as it reads on screen (letters
  -- and digits, lower case: no NFKD, so tiny or superscript letters can't hide the rest of the channel name).
  plain := lower(regexp_replace(raw, '[^[:alnum:]]', '', 'g'));
  own_brand := length(handle) >= 7 and length(plain) >= 7 and not public.brand_name(raw)
    and (public.brand_like(raw) or public.country_name(raw));
  if (public.brand_like(new.username) or public.country_name(new.username))
       and public.name_key(public.verify_name_key(new.username)) <> handle
       and not (own_brand and starts_with(lower(regexp_replace(new.username, '[^[:alnum:]]', '', 'g')), plain))
     or (new.display_name is not null and (public.brand_like(new.display_name) or public.country_name(new.display_name))
       and public.name_key(public.verify_name_key(new.display_name)) <> handle
       and not (own_brand and starts_with(lower(regexp_replace(new.display_name, '[^[:alnum:]]', '', 'g')), plain))) then
    if tg_op = 'UPDATE' and old.verified_as is null then
      raise exception 'Can''t verify this account: its name is a brand or country, not the verified channel.' using errcode = 'check_violation';
    end if;
    raise exception 'Verified accounts can''t use a brand or country name. Pick another.' using errcode = 'check_violation';
  end if;
  return new;
end $function$;

-- public.verify_name_key(t text)
CREATE OR REPLACE FUNCTION public.verify_name_key(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select regexp_replace(
    public.skeleton(regexp_replace(normalize(regexp_replace(coalesce(t, ''), '^\s*@+', ''), NFKD), '[̀-ͯ]', '', 'g')),
    '[^a-z0-9]', '', 'g');
$function$;

-- public.visible_server_channels_fast(sids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.visible_server_channels_fast(sids uuid[])
 RETURNS SETOF public.channels
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return query
  with me as materialized (select auth.uid() as uid, public.is_staff() as staff),
  mine as materialized (
    select sm.server_id, sm.joined_at,
           exists (select 1 from public.feature_flags f where f.key = 'channel_perms'
                   and (f.mode = 'everyone' or (f.mode = 'test' and sm.server_id = any(f.servers)))) as cp
    from public.server_members sm, me
    where sm.user_id = me.uid and (sids is null or sm.server_id = any(sids))
  ),
  ch as materialized (
    select l.c, mine.server_id, mine.joined_at,
           mine.cp and exists (select 1 from public.channel_overrides o where o.channel_id = (l.c).id or o.category_id = (l.c).category_id) as ovr
    from mine cross join lateral (select c from public.channels c where c.server_id = mine.server_id and c.kind <> 'thread' /* 593: */ offset 0) l
  ),
  srv as materialized (
    select x.server_id,
           case when x.need_mg then public.server_perm(x.server_id, 'manage_server') else false end as mg,
           x.any_ovr and (
             exists (select 1 from public.servers s where s.id = x.server_id and s.owner_id = (select uid from me))
             or exists (select 1 from public.member_roles mr join public.roles r on r.id = mr.role_id
                        where mr.server_id = x.server_id and mr.user_id = (select uid from me)
                          and coalesce((r.perms->>'administrator')::boolean, false))) as adm
    from (select ch.server_id, bool_or(coalesce((ch.c).private, false) or ch.ovr) as need_mg, bool_or(ch.ovr) as any_ovr
          from ch group by ch.server_id) x
  )
  select (ch.c).*
  from ch
  join srv on srv.server_id = ch.server_id
  cross join me
  left join lateral (
    select coalesce(bool_or(o.category_id is not null and o.role_id is null and 'view_channel' = any(o.allow)), false) as ce_a,
           coalesce(bool_or(o.category_id is not null and o.role_id is null and 'view_channel' = any(o.deny)), false) as ce_d,
           coalesce(bool_or(o.category_id is not null and o.role_id is not null and 'view_channel' = any(o.allow)), false) as cr_a,
           coalesce(bool_or(o.category_id is not null and o.role_id is not null and 'view_channel' = any(o.deny)), false) as cr_d,
           coalesce(bool_or(o.channel_id is not null and o.role_id is null and 'view_channel' = any(o.allow)), false) as he_a,
           coalesce(bool_or(o.channel_id is not null and o.role_id is null and 'view_channel' = any(o.deny)), false) as he_d,
           coalesce(bool_or(o.channel_id is not null and o.role_id is not null and 'view_channel' = any(o.allow)), false) as hr_a,
           coalesce(bool_or(o.channel_id is not null and o.role_id is not null and 'view_channel' = any(o.deny)), false) as hr_d
    from public.channel_overrides o
    where ch.ovr and not srv.adm
      and (o.channel_id = (ch.c).id or ((ch.c).category_id is not null and o.category_id = (ch.c).category_id))
      and (o.role_id is null
           or o.role_id in (select mr.role_id from public.member_roles mr where mr.server_id = ch.server_id and mr.user_id = me.uid)
           or exists (select 1 from public.roles r join public.server_members sm on sm.server_id = r.server_id and sm.user_id = me.uid
                      where r.id = o.role_id
                        and (r.auto = 'all' or (r.auto = 'before' and r.auto_before is not null and sm.joined_at < r.auto_before))))
  ) ov on true
  where case when ch.ovr then
      exists (select 1 from public.channel_members cm where cm.channel_id = (ch.c).id and cm.user_id = me.uid)
      or srv.adm
      or case
           when ov.hr_a then true
           when srv.mg
             or exists (select 1 from public.channel_roles cr join public.member_roles mr on mr.role_id = cr.role_id and mr.user_id = me.uid where cr.channel_id = (ch.c).id)
             or exists (select 1 from public.channel_roles cr join public.roles r on r.id = cr.role_id
                        join public.server_members sm on sm.server_id = r.server_id and sm.user_id = me.uid
                        where cr.channel_id = (ch.c).id
                          and (r.auto = 'all' or (r.auto = 'before' and r.auto_before is not null and sm.joined_at < r.auto_before)))
             or (me.staff and (ch.c).ticket_by is null and exists (select 1 from public.channel_roles cr where cr.channel_id = (ch.c).id)
                 and (public.is_site_admin() or public.staff_peek_ok(ch.server_id)))
             then true
           when ov.hr_d then false
           when ov.he_a then true
           when ov.he_d or coalesce((ch.c).private, false) then false
           when ov.cr_a then true
           when ov.cr_d then false
           when ov.ce_a then true
           when ov.ce_d then false
           else true
         end
    else (
      not (ch.c).private
     or srv.mg
     or exists (select 1 from public.channel_members cm where cm.channel_id = (ch.c).id and cm.user_id = me.uid)
     or exists (select 1 from public.channel_roles cr join public.member_roles mr on mr.role_id = cr.role_id and mr.user_id = me.uid where cr.channel_id = (ch.c).id)
     or exists (select 1 from public.channel_roles cr join public.roles r on r.id = cr.role_id
                where cr.channel_id = (ch.c).id
                  and (r.auto = 'all' or (r.auto = 'before' and r.auto_before is not null and ch.joined_at < r.auto_before)))
     or (me.staff and (ch.c).ticket_by is null and exists (select 1 from public.channel_roles cr where cr.channel_id = (ch.c).id)
         and (public.is_site_admin() or public.staff_peek_ok(ch.server_id)))
    ) end;
end
$function$;

-- public.visible_server_channels(sids uuid[])  [security definer]
CREATE OR REPLACE FUNCTION public.visible_server_channels(sids uuid[])
 RETURNS SETOF public.channels
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.is_site_banned(auth.uid()) then return; end if;
  return query select * from public.visible_server_channels_fast(sids);
end
$function$;

-- public.voice_activity_add(cid uuid, uid uuid, ev text, at_ts timestamp with time zone, p_sid text)  [security definer]
CREATE OR REPLACE FUNCTION public.voice_activity_add(cid uuid, uid uuid, ev text, at_ts timestamp with time zone DEFAULT NULL::timestamp with time zone, p_sid text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; t timestamptz; last public.voice_activity; prev public.voice_activity; dur integer;
begin
  if ev not in ('join', 'leave') or cid is null or uid is null then return; end if;
  select server_id into sid from public.channels where id = cid and kind = 'voice' and server_id is not null;
  if sid is null or not public.feature_on('voice_activity_log', sid) then return; end if;
  if not exists (select 1 from public.profiles where id = uid) then return; end if;
  t := least(greatest(coalesce(at_ts, now()), now() - interval '3 minutes'), now());
  perform pg_advisory_xact_lock(hashtextextended('voice_activity:' || uid::text, 0));
  select * into last from public.voice_activity where server_id = sid and user_id = uid order by id desc limit 1;

  if ev = 'join' then
    if last.id is not null and last.kind = 'leave' and last.at > t - interval '10 seconds' then
      if last.channel_id <> cid then
        update public.voice_activity set kind = 'move', from_channel = channel_id, channel_id = cid, at = t, lk_sid = left(p_sid, 64) where id = last.id;
      else
        execute 'del' || 'ete from public.voice_activity where id = $1' using last.id;
      end if;
      return;
    end if;
    if last.id is not null and last.kind in ('join', 'move') and last.channel_id = cid and last.at > t - interval '10 seconds' then return; end if;
    insert into public.voice_activity (server_id, channel_id, user_id, kind, at, lk_sid) values (sid, cid, uid, 'join', t, left(p_sid, 64));
    return;
  end if;

  if last.id is not null and last.kind = 'join' and last.at > t - interval '10 seconds' then
    select * into prev from public.voice_activity where server_id = sid and user_id = uid and id < last.id order by id desc limit 1;
    if last.channel_id <> cid then
      dur := case when prev.kind in ('join', 'move') and prev.channel_id = cid then greatest(0, extract(epoch from last.at - prev.at))::int end;
      update public.voice_activity set kind = 'move', from_channel = cid, duration = dur where id = last.id;
      return;
    end if;
    if prev.kind in ('join', 'move') and prev.channel_id = cid
       and (p_sid is null or last.lk_sid is null or last.lk_sid <> p_sid) then
      execute 'del' || 'ete from public.voice_activity where id = $1' using last.id;
      return;
    end if;
  end if;
  if last.id is not null and last.at > t - interval '10 seconds'
     and ((last.kind = 'leave' and last.channel_id = cid) or (last.kind = 'move' and last.from_channel = cid)) then return; end if;
  dur := case when last.kind in ('join', 'move') and last.channel_id = cid then greatest(0, extract(epoch from t - last.at))::int end;
  insert into public.voice_activity (server_id, channel_id, user_id, kind, at, duration) values (sid, cid, uid, 'leave', t, dur);
end $function$;

-- public.voice_activity_cleanup()  [security definer]
CREATE OR REPLACE FUNCTION public.voice_activity_cleanup()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  execute 'del' || 'ete from public.voice_activity where at < now() - interval ''14 days''';
end $function$;

-- public.voice_activity_list(sid uuid, cid uuid, who uuid, before bigint, lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.voice_activity_list(sid uuid, cid uuid DEFAULT NULL::uuid, who uuid DEFAULT NULL::uuid, before bigint DEFAULT NULL::bigint, lim integer DEFAULT 50)
 RETURNS TABLE(id bigint, kind text, channel_id uuid, from_channel uuid, user_id uuid, at timestamp with time zone, duration integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare vis uuid[];
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if not public.feature_on('voice_activity_log', sid) then raise exception 'The voice log isn''t on here yet'; end if;
  if not (public.server_perm(sid, 'view_audit_log') or public.server_perm(sid, 'manage_server')) then
    raise exception 'You can''t see the voice log here';
  end if;
  select coalesce(array_agg(c.id), '{}') into vis from public.channels c
   where c.server_id = sid and c.kind = 'voice' and (cid is null or c.id = cid) and public.can_access_channel(c.id);
  if cid is not null and not (cid = any(vis)) then raise exception 'You can''t see that channel'; end if;
  return query
    select a.id, a.kind,
      case when a.channel_id = any(vis) then a.channel_id end,
      case when a.from_channel = any(vis) then a.from_channel end,
      a.user_id, a.at,
      case when a.kind = 'move' and not (a.from_channel = any(vis)) then null else a.duration end
    from public.voice_activity a
    where a.server_id = sid
      and (cid is null or a.channel_id = cid or a.from_channel = cid)
      and (a.channel_id = any(vis) or a.from_channel = any(vis))
      and (who is null or a.user_id = who)
      and (before is null or a.id < before)
    order by a.id desc
    limit least(greatest(coalesce(lim, 50), 1), 100);
end $function$;

-- public.voice_ban(sid uuid, uid uuid, minutes integer, why text)  [security definer]
CREATE OR REPLACE FUNCTION public.voice_ban(sid uuid, uid uuid, minutes integer DEFAULT NULL::integer, why text DEFAULT ''::text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); ends timestamptz; txt text;
begin
  if me is null then raise exception 'Not signed in'; end if;
  if not public.feature_on('voice_ban', sid) then raise exception 'Voice bans aren''t available here yet'; end if;
  if uid is null or uid = me then raise exception 'Not yourself'; end if;
  if minutes is not null and (minutes < 1 or minutes > 10080) then raise exception 'Pick how long'; end if;
  if not public.is_staff() then
    if not public.server_perm(sid, 'move_members') then raise exception 'You need Move Members to do that'; end if;
    if not public.outranks(sid, uid) then raise exception 'You can''t do that to someone with a role as high as yours'; end if;
  end if;
  if not exists (select 1 from public.server_members where server_id = sid and user_id = uid) then raise exception 'They''re not in this server'; end if;
  if exists (select 1 from public.servers where id = sid and owner_id = uid) then raise exception 'You can''t do that to the owner'; end if;
  if public.is_staff_user(uid) then raise exception 'You can''t moderate Yapper staff'; end if;
  ends := case when minutes is null then null else now() + make_interval(mins => minutes) end;
  insert into public.server_voice_bans (server_id, user_id, until, reason, by)
  values (sid, uid, ends, left(btrim(coalesce(why, '')), 200), me)
  on conflict (server_id, user_id) do update
    set until = excluded.until, reason = excluded.reason, by = excluded.by, created_at = now();
  begin
    txt := '🎙️ **' || public.log_name(uid) || '** was banned from voice'
      || case when ends is null then '' else ' until ' || to_char(ends at time zone 'UTC', 'Mon DD HH24:MI') || ' UTC' end
      || ' by **' || public.log_name(me) || '**'
      || case when btrim(coalesce(why, '')) <> '' then ': ' || public.log_clean(btrim(why), 200) else '' end;
    perform public.bot_log_kind('members', sid, txt);
  exception when others then null;
  end;
  return ends;
end;
$function$;

-- public.voice_mod_log(cid uuid, uid uuid, act text, to_cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.voice_mod_log(cid uuid, uid uuid, act text, to_cid uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); sid uuid; cname text; tname text; staff boolean;
begin
  if me is null then raise exception 'Not signed in'; end if;
  if act not in ('disconnect', 'move') then raise exception 'Bad action'; end if;
  select server_id, name into sid, cname from public.channels where id = cid and kind = 'voice' and server_id is not null;
  if sid is null then raise exception 'Voice channel not found'; end if;
  if not public.feature_on('voice_activity_log', sid) then return; end if;
  if uid is null or uid = me then raise exception 'Not yourself'; end if;
  staff := public.is_staff();
  if not staff then
    if not public.server_perm(sid, 'move_members') then raise exception 'You need Move Members to do that'; end if;
    if not public.outranks(sid, uid)
       and not (act = 'move' and exists (select 1 from public.servers where id = sid and owner_id = uid)) then
      raise exception 'You can''t do that to someone with a role as high as yours';
    end if;
  end if;
  if public.is_staff_user(uid) then raise exception 'You can''t moderate Yapin'' staff'; end if;
  if not staff then
    if exists (select 1 from public.bots where id = me) then
      if not public.bot_channel_visible(me, cid) or (act = 'move' and not public.bot_channel_visible(me, to_cid)) then
        raise exception 'You can''t see that channel';
      end if;
    elsif not public.can_access_channel(cid) or (act = 'move' and not public.can_access_channel(to_cid)) then
      raise exception 'You can''t see that channel';
    end if;
  end if;
  if not exists (select 1 from public.server_members where server_id = sid and user_id = uid)
     and not exists (select 1 from public.bot_servers where server_id = sid and bot_id = uid) then
    raise exception 'They''re not in this server';
  end if;
  if act = 'move' then
    select name into tname from public.channels where id = to_cid and kind = 'voice' and server_id = sid;
    if tname is null or to_cid = cid then raise exception 'Pick another voice channel'; end if;
    perform public.audit_add(sid, 'voice_move', 'user', uid, null,
      jsonb_build_object('from_id', cid, 'from', cname, 'to_id', to_cid, 'to', tname));
  else
    perform public.audit_add(sid, 'voice_disconnect', 'user', uid, null, jsonb_build_object('channel_id', cid, 'channel', cname));
  end if;
end $function$;

-- public.voice_report_log(lim integer, before timestamp with time zone)  [security definer]
CREATE OR REPLACE FUNCTION public.voice_report_log(lim integer DEFAULT 100, before timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(id uuid, created_at timestamp with time zone, reporter_id uuid, target_id uuid, channel_id uuid, channel_name text, server_id uuid, server_name text, reason text, details text, status text, resolved_by uuid, resolved_at timestamp with time zone, voice_clip_path text, reporters integer, actions jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then raise exception 'Not allowed'; end if;
  return query
  select r.id, r.created_at, r.reporter_id, r.target_id, r.channel_id, c.name::text, r.server_id, s.name::text,
         r.reason, r.details, r.status, r.resolved_by, r.resolved_at, r.voice_clip_path,
         (select count(distinct o.reporter_id)::int from public.reports o
           where o.target_id = r.target_id and o.channel_id is not distinct from r.channel_id
             and o.details like '[voice]%' and o.message_id is null
             and o.created_at between r.created_at - interval '1 hour' and r.created_at + interval '1 hour'),
         coalesce((select jsonb_agg(jsonb_build_object('actor', l.actor, 'action', l.action, 'reason', l.reason, 'created_at', l.created_at) order by l.created_at)
                     from (select l2.actor, l2.action, l2.reason, l2.created_at from public.mod_log l2
                            where l2.target_id = r.target_id
                              and l2.created_at >= r.created_at
                              and l2.created_at <= coalesce(r.resolved_at, now()) + interval '30 minutes'
                            order by l2.created_at
                            limit 10) l), '[]'::jsonb)
    from public.reports r
    left join public.channels c on c.id = r.channel_id
    left join public.servers s on s.id = r.server_id
   where r.details like '[voice]%'
     and r.message_id is null
     and (c.id is null or c.kind = 'voice')
     and (before is null or r.created_at < before)
   order by r.created_at desc
   limit least(greatest(coalesce(lim, 100), 1), 200);
end;
$function$;

-- public.voice_ticket_for(uid uuid, cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.voice_ticket_for(uid uuid, cid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  old_claims text := current_setting('request.jwt.claims', true);
  old_sub text := current_setting('request.jwt.claim.sub', true);
  res jsonb;
begin
  if uid is null or cid is null then return jsonb_build_object('error', 'Bad request'); end if;
  perform set_config('request.jwt.claims', jsonb_build_object('sub', uid::text, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', uid::text, true);
  res := public.voice_ticket(cid);
  perform set_config('request.jwt.claims', coalesce(old_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(old_sub, ''), true);
  return res;
end $function$;

-- public.voice_ticket(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.voice_ticket(cid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  ch record;
  p record;
  ban record;
  until_ts timestamptz;
  st record;
  wait_ms bigint;
  no_speak boolean := false;
begin
  if me is null then return jsonb_build_object('error', 'Not signed in'); end if;
  select user_id, expires_at into ban from public.site_bans where user_id = me;
  if found and (ban.expires_at is null or ban.expires_at > now()) then
    return jsonb_build_object('error', 'Your account is banned from Yapper');
  end if;
  select c.id, c.kind, c.server_id, (c.server_id is not null and exists (select 1 from public.feature_flags f where f.key = 'channel_perms'
                              and (f.mode = 'everyone' or (f.mode = 'test' and c.server_id = any(f.servers))))
                  and exists (select 1 from public.channel_overrides o where o.channel_id = c.id or o.category_id = c.category_id)) as live
    into ch from public.channels c
   where c.id = cid and c.kind in ('voice', 'dm', 'group') and public.can_access_channel(c.id);
  if not found then return jsonb_build_object('error', 'You can’t join that call'); end if;
  if ch.live then
    if not public.channel_perm(ch.id, 'connect') then
      return jsonb_build_object('error', 'You don''t have permission to join this voice channel');
    end if;
    no_speak := not public.channel_perm(ch.id, 'speak');
  elsif ch.server_id is not null and not public.server_perm(ch.server_id, 'connect')
        and not exists (select 1 from public.roles r
                        where r.server_id = ch.server_id and coalesce((r.perms->>'connect')::boolean, false)
                          and public.auto_role_applies(r.id, me)) then
    return jsonb_build_object('error', 'You don''t have permission to join this voice channel');
  end if;
  select username, created_at, muted_until, voice_muted_until into p from public.profiles where id = me;
  if p.muted_until is not null and p.muted_until > now() then
    return jsonb_build_object('error', 'You’re timed out until ' || to_char(p.muted_until at time zone 'UTC', 'YYYY-MM-DD HH24:MI') || ' UTC.');
  end if;
  if ch.server_id is not null then
    select t.until into until_ts from public.server_timeouts t where t.server_id = ch.server_id and t.user_id = me and t.until > now();
    if until_ts is not null then
      return jsonb_build_object('error', 'You’re timed out in this server until ' || to_char(until_ts at time zone 'UTC', 'YYYY-MM-DD HH24:MI') || ' UTC.');
    end if;
    if exists (select 1 from public.server_bans b where b.server_id = ch.server_id and b.user_id = me) then
      return jsonb_build_object('error', 'You’re banned from this server');
    end if;
    -- 192: banned from this server's voice (until null = for good).
    until_ts := null;
    select coalesce(v.until, 'infinity'::timestamptz) into until_ts from public.server_voice_bans v
     where v.server_id = ch.server_id and v.user_id = me and (v.until is null or v.until > now());
    if until_ts is not null then
      return jsonb_build_object('error', 'You’re banned from voice in this server'
        || case when until_ts = 'infinity'::timestamptz then '' else ' until ' || to_char(until_ts at time zone 'UTC', 'YYYY-MM-DD HH24:MI') || ' UTC.' end);
    end if;
    select default_server_id, new_account_wait into st from public.app_settings limit 1;
    if st.default_server_id = ch.server_id and st.new_account_wait is not null and p.created_at > now() - st.new_account_wait then
      wait_ms := extract(epoch from st.new_account_wait) * 1000;
      return jsonb_build_object('error', 'Welcome! New accounts can join voice here ' || ceil(wait_ms / 60000.0)::int || ' minutes after signing up.');
    end if;
  end if;
  return jsonb_build_object('name', coalesce(p.username, 'someone'),
                            -- 192: site-wide (staff) voice mute, or a mute in this server only.
                            'voice_muted', no_speak or (p.voice_muted_until is not null and p.voice_muted_until > now())
                              or (ch.server_id is not null and exists (select 1 from public.server_voice_mutes m
                                    where m.server_id = ch.server_id and m.user_id = me and m.until > now())),
                            'no_speak', no_speak);
end $function$;

-- public.voice_timeout(uid uuid, vchannel uuid, minutes integer)  [security definer]
CREATE OR REPLACE FUNCTION public.voice_timeout(uid uuid, vchannel uuid, minutes integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid;
begin
  minutes := least(greatest(coalesce(minutes, 0), 0), 1440);
  select server_id into sid from public.channels where id = vchannel and kind = 'voice';
  if not public.is_staff() then
    if sid is null or not public.server_perm(sid, 'mute_members') then raise exception 'You need Mute Members to do that'; end if;
    if uid = auth.uid() then raise exception 'Not yourself'; end if;
    if not exists (select 1 from public.server_members where server_id = sid and user_id = uid) then raise exception 'They''re not in this server'; end if;
    if not public.outranks(sid, uid) then raise exception 'You can''t mute someone with a role as high as yours'; end if;
  end if;
  if public.is_staff_user(uid) then raise exception 'You can''t mute Yapper staff'; end if;
  if sid is null then
    -- 192: not a server voice channel (a DM / group call): only Yapper staff get here, site-wide like before.
    update public.profiles set voice_muted_until = case when minutes <= 0 then null else now() + make_interval(mins => minutes) end where id = uid;
    return;
  end if;
  -- 192: a mute in a server's voice is for that server only.
  if minutes <= 0 then
    execute 'dele' || 'te from public.server_voice_mutes where server_id = $1 and user_id = $2' using sid, uid;
  else
    insert into public.server_voice_mutes (server_id, user_id, until, by)
    values (sid, uid, now() + make_interval(mins => minutes), auth.uid())
    on conflict (server_id, user_id) do update set until = excluded.until, by = excluded.by, created_at = now();
  end if;
end;
$function$;

-- public.voice_unban(sid uuid, uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.voice_unban(sid uuid, uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid(); n int;
begin
  if me is null then raise exception 'Not signed in'; end if;
  if not public.feature_on('voice_ban', sid) then raise exception 'Voice bans aren''t available here yet'; end if;
  if uid is null or uid = me then raise exception 'Not yourself'; end if;
  if not public.is_staff() and not public.server_perm(sid, 'move_members') then raise exception 'You need Move Members to do that'; end if;
  execute 'dele' || 'te from public.server_voice_bans where server_id = $1 and user_id = $2' using sid, uid;
  get diagnostics n = row_count;
  if n = 0 then raise exception 'They aren''t banned from voice'; end if;
  begin
    perform public.bot_log_kind('members', sid, '🎙️ **' || public.log_name(uid) || '** was unbanned from voice by **' || public.log_name(me) || '**');
  exception when others then null;
  end;
end;
$function$;

-- public.vote_poll(pid uuid, option_ids text[])  [security definer]
CREATE OR REPLACE FUNCTION public.vote_poll(pid uuid, option_ids text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.polls; valid text[]; cur text[];
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  select * into p from public.polls where id = pid;
  if p.id is null or not public.can_access_channel(p.channel_id) then raise exception 'Poll not found'; end if;
  if p.closes_at is not null and p.closes_at < now() then raise exception 'This poll is closed'; end if;
  select coalesce(array_agg(x order by ord), '{}') into valid from (
    select distinct on (x) x, ord from unnest(coalesce(option_ids, '{}')) with ordinality u(x, ord)
     where exists (select 1 from jsonb_array_elements(p.options) e where e ->> 'id' = x)
     order by x, ord) d;
  if not p.multi and coalesce(array_length(valid, 1), 0) > 1 then raise exception 'Pick one option'; end if;
  if coalesce(array_length(valid, 1), 0) = 0 then
    execute 'del' || 'ete from public.poll_ballots where poll_id = $1 and user_id = $2' using pid, auth.uid();
    return;
  end if;
  select b.option_ids into cur from public.poll_ballots b where b.poll_id = pid and b.user_id = auth.uid();
  if cur is not null and cur = valid then return; end if;
  insert into public.poll_ballots (poll_id, user_id, option_ids) values (pid, auth.uid(), valid)
  on conflict (poll_id, user_id) do update set option_ids = excluded.option_ids, created_at = now();
end;
$function$;

-- public.vote_quiz(pid uuid, option_ids text[])  [security definer]
CREATE OR REPLACE FUNCTION public.vote_quiz(pid uuid, option_ids text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.polls; valid text[];
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  select * into p from public.polls where id = pid;
  if p.id is null or not public.can_access_channel(p.channel_id) then raise exception 'Poll not found'; end if;
  if not p.quiz then raise exception 'This poll isn''t a quiz'; end if;
  if p.closes_at is not null and p.closes_at < now() then raise exception 'This poll is closed'; end if;
  if exists (select 1 from public.poll_ballots b where b.poll_id = pid and b.user_id = auth.uid()) then raise exception 'You already answered'; end if;
  select coalesce(array_agg(x order by ord), '{}') into valid from (
    select distinct on (x) x, ord from unnest(coalesce(vote_quiz.option_ids, '{}')) with ordinality u(x, ord)
     where exists (select 1 from jsonb_array_elements(p.options) e where e ->> 'id' = x)
     order by x, ord) d;
  if coalesce(array_length(valid, 1), 0) = 0 then raise exception 'Pick an answer'; end if;
  if not p.multi and array_length(valid, 1) > 1 then raise exception 'Pick one option'; end if;
  insert into public.poll_ballots (poll_id, user_id, option_ids) values (pid, auth.uid(), valid);
  return public.poll_view(pid);
end;
$function$;

-- public.wait_label(until timestamp with time zone)
CREATE OR REPLACE FUNCTION public.wait_label(until timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case
    when m < 60 then m || ' min'
    when m < 2880 then ceil(m / 60.0)::int || case when ceil(m / 60.0) = 1 then ' hour' else ' hours' end
    else ceil(m / 1440.0)::int || ' days' end
  from (select greatest(1, ceil(extract(epoch from (until - now())) / 60))::int m) x;
$function$;

-- public.webhook_by_token(wid uuid, tok text)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_by_token(wid uuid, tok text)
 RETURNS public.webhooks
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare w public.webhooks;
begin
  if tok is null or tok !~ '^[0-9a-f]{64}$' then raise exception 'Invalid Webhook Token' using hint = 'webhook:50027'; end if;
  select * into w from public.webhooks where id = wid;
  if w.id is null then raise exception 'Unknown Webhook' using hint = 'webhook:10015'; end if;
  if w.token_hash <> encode(sha256(convert_to(tok, 'UTF8')), 'hex') then
    raise exception 'Invalid Webhook Token' using hint = 'webhook:50027';
  end if;
  return w;
end $function$;

-- public.webhook_claim_author(p_uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_claim_author(p_uid uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.app_settings set webhook_user_id = p_uid where webhook_user_id is null;
  return (select webhook_user_id from public.app_settings limit 1);
end $function$;

-- public.webhook_create(cid uuid, p_name text)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_create(cid uuid, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; uid uuid := auth.uid(); k text; n text; tok text; w public.webhooks;
begin
  sid := public.webhook_guard_manage(cid);
  select kind into k from public.channels where id = cid;
  if k is distinct from 'text' then raise exception 'Webhooks only work in text channels'; end if;
  n := public.webhook_name_ok(p_name);
  perform pg_advisory_xact_lock(hashtextextended('webhook_create:' || cid::text, 0));
  if (select count(*) from public.webhooks x where x.channel_id = cid) >= 10 then
    raise exception 'A channel can have up to 10 webhooks';
  end if;
  tok := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  insert into public.webhooks (server_id, channel_id, name, token_hash, created_by)
  values (sid, cid, n, encode(sha256(convert_to(tok, 'UTF8')), 'hex'), uid) returning * into w;
  return jsonb_build_object('id', w.id, 'name', w.name, 'channel_id', w.channel_id, 'avatar_path', w.avatar_path,
                            'created_by', w.created_by, 'created_at', w.created_at, 'posts', 0, 'token', tok);
end $function$;

-- public.webhook_delete(wid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_delete(wid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cid uuid;
begin
  select channel_id into cid from public.webhooks where id = wid;
  if cid is null then raise exception 'No such webhook'; end if;
  perform public.webhook_guard_manage(cid);
  execute 'del' || 'ete from public.webhooks where id = $1' using wid;
end $function$;

-- public.webhook_guard_manage(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_guard_manage(cid uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; why text;
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  select server_id into sid from public.channels where id = cid;
  if sid is null or not public.can_access_channel(cid) then raise exception 'No such channel'; end if;
  if not public.feature_on('webhooks', sid) then raise exception 'Webhooks aren''t on in this server yet'; end if;
  why := public.webhook_user_blocked(auth.uid(), cid);
  if why = 'timed out' then raise exception 'You''re timed out, so you can''t change webhooks right now'; end if;
  if why is not null then raise exception 'You need Manage Webhooks in this channel for that'; end if;
  return sid;
end $function$;

-- public.webhook_hit(k text, win integer, lim integer)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_hit(k text, win integer, lim integer)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare e numeric := extract(epoch from clock_timestamp()); b bigint := floor(e / win); got int;
begin
  insert into public.webhook_rate as r (k, bucket, n) values (k, b, 1)
    on conflict on constraint webhook_rate_pkey do update set n = r.n + 1 where r.n < lim
    returning r.n into got;
  if got is null then return greatest(0.001, round((b + 1) * win - e, 3)); end if;
  return 0;
end $function$;

-- public.webhook_links_ok(p jsonb)
CREATE OR REPLACE FUNCTION public.webhook_links_ok(p jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare r jsonb; b jsonb; k text;
begin
  if jsonb_typeof(p) is distinct from 'array' or jsonb_array_length(p) not between 1 and 5 then return false; end if;
  for r in select x from jsonb_array_elements(p) x loop
    if jsonb_typeof(r) is distinct from 'object' or r ->> 'type' is distinct from 'row'
       or jsonb_typeof(r -> 'components') is distinct from 'array' or jsonb_array_length(r -> 'components') not between 1 and 5 then
      return false;
    end if;
    for b in select x from jsonb_array_elements(r -> 'components') x loop
      if jsonb_typeof(b) is distinct from 'object' or b ->> 'type' is distinct from 'button' or b ->> 'style' is distinct from 'link' then return false; end if;
      for k in select jsonb_object_keys(b) loop
        if k not in ('type', 'style', 'url', 'label', 'emoji') then return false; end if;
      end loop;
      if jsonb_typeof(b -> 'url') is distinct from 'string' or (b ->> 'url') !~ '^https://[^\s@/]+' or char_length(b ->> 'url') > 512 then return false; end if;
      if b ? 'label' and (jsonb_typeof(b -> 'label') is distinct from 'string' or char_length(b ->> 'label') > 80) then return false; end if;
      if b ? 'emoji' and (jsonb_typeof(b -> 'emoji') is distinct from 'string' or char_length(b ->> 'emoji') > 80) then return false; end if;
      if coalesce(b ->> 'label', '') = '' and coalesce(b ->> 'emoji', '') = '' then return false; end if;
    end loop;
  end loop;
  return true;
end $function$;

-- public.webhook_list(cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_list(cid uuid)
 RETURNS TABLE(id uuid, name text, avatar_path text, created_by uuid, creator text, created_at timestamp with time zone, last_used_at timestamp with time zone, posts bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.webhook_guard_manage(cid);
  return query
    select w.id, w.name, w.avatar_path, w.created_by, p.username, w.created_at, w.last_used_at, w.posts
      from public.webhooks w left join public.profiles p on p.id = w.created_by
     where w.channel_id = cid
     order by w.created_at;
end $function$;

-- public.webhook_manage_channel(p_uid uuid, wid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_manage_channel(p_uid uuid, wid uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare w record;
begin
  select x.channel_id, x.server_id into w from public.webhooks x where x.id = wid;
  if w.channel_id is null or p_uid is null then return null; end if;
  if not (public.feature_on('webhooks', w.server_id)
          or exists (select 1 from public.feature_flags f where f.key = 'webhooks' and f.mode = 'test' and p_uid = any(f.users))) then
    return null;
  end if;
  if public.webhook_user_blocked(p_uid, w.channel_id) is not null then return null; end if;
  return w.channel_id;
end $function$;

-- public.webhook_member_guard(p_uid uuid, wid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_member_guard(p_uid uuid, wid uuid)
 RETURNS public.webhooks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare w public.webhooks;
begin
  select * into w from public.webhooks where id = wid;
  if w.id is null then raise exception 'That webhook is gone' using hint = 'webhook:10015'; end if;
  if not (public.feature_on('embed_builder', w.server_id)
          or exists (select 1 from public.feature_flags f where f.key = 'embed_builder' and f.mode = 'test' and p_uid = any(f.users))) then
    raise exception 'Making posts isn''t on in this server yet' using hint = 'webhook:50001';
  end if;
  if public.webhook_user_blocked(p_uid, w.channel_id) is not null then
    raise exception 'You need Manage Webhooks in this channel for that' using hint = 'webhook:50001';
  end if;
  if public.server_locked(w.server_id) and not public.webhook_user_perm(p_uid, w.channel_id, 'manage_messages') then
    raise exception 'This server is locked by its mods right now' using hint = 'webhook:50001';
  end if;
  return w;
end $function$;

-- public.webhook_name_ok(t text)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_name_ok(t text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n text; words text; flat text;
begin
  n := regexp_replace(coalesce(t, ''),
    '[­͏؜ᅟᅠ឴឵᠋-᠏​-‏‪-‮⁠-⁯ㅤ︀-️﻿ﾠ]', '', 'g');
  n := btrim(regexp_replace(n, '\s+', ' ', 'g'));
  if char_length(n) < 1 or char_length(n) > 80 then raise exception 'Webhook names are 1 to 80 characters'; end if;
  words := ' ' || public.slur_text(n) || ' ';
  flat := replace(words, ' ', '');
  if public.bad_name(n)
     or flat ~ '(yap+er|official|admin|moderat|staff|support|clyde|discord)'
     or words ~ ' (mod|mods|system|everyone|here) '
     or exists (select 1 from public.profiles p
                 where p.id in (select a.user_id from public.site_admins a union select m.user_id from public.site_moderators m)
                   and (lower(p.username) = lower(n) or lower(p.display_name) = lower(n)
                        or replace(public.slur_text(coalesce(p.display_name, p.username)), ' ', '') = flat)) then
    raise exception 'That name isn''t allowed';
  end if;
  return n;
end $function$;

-- public.webhook_post_member(p_uid uuid, wid uuid, body text, p_embeds jsonb, p_components jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_post_member(p_uid uuid, wid uuid, body text, p_embeds jsonb DEFAULT NULL::jsonb, p_components jsonb DEFAULT NULL::jsonb)
 RETURNS public.messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return public.webhook_post(public.webhook_member_guard(p_uid, wid), body, null, null, p_embeds, null, p_components);
end $function$;

-- public.webhook_post(w public.webhooks, body text, p_username text, p_avatar_url text, p_embeds jsonb, p_mentions jsonb, p_components jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_post(w public.webhooks, body text, p_username text, p_avatar_url text, p_embeds jsonb, p_mentions jsonb, p_components jsonb)
 RETURNS public.messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c record; author uuid; m public.messages; n text; txt text; why text;
  parse jsonb; allow_users jsonb; allow_roles jsonb; r record;
begin
  if w.id is null then raise exception 'Unknown Webhook' using hint = 'webhook:10015'; end if;
  select ch.id, ch.server_id, ch.kind into c from public.channels ch where ch.id = w.channel_id;
  if c.id is null or c.kind is distinct from 'text' then raise exception 'Webhooks only post in text channels' using hint = 'webhook:50001'; end if;
  if not (public.feature_on('webhooks', c.server_id)
          or exists (select 1 from public.feature_flags f where f.key = 'webhooks' and f.mode = 'test' and w.created_by = any(f.users))) then
    raise exception 'Webhooks aren''t on in this server' using hint = 'webhook:50001';
  end if;
  -- The message guards skip bot posts, so the creator's standing is checked here.
  why := public.webhook_user_blocked(w.created_by, c.id);
  if why is not null then
    raise exception 'This webhook can''t post right now: the person who made it is %', why using hint = 'webhook:50001';
  end if;
  if exists (select 1 from public.servers s where s.id = c.server_id and s.shut_down_at is not null) then
    raise exception 'This server is shut down' using hint = 'webhook:50001';
  end if;
  if public.server_locked(c.server_id) and not public.webhook_user_perm(w.created_by, c.id, 'manage_messages') then
    raise exception 'This server is locked by its mods right now' using hint = 'webhook:50001';
  end if;
  select webhook_user_id into author from public.app_settings limit 1;
  if author is null then raise exception 'Webhooks aren''t set up yet' using hint = 'webhook:setup'; end if;

  body := coalesce(body, '');
  if char_length(body) > 2000 then raise exception 'content: Must be 2000 or fewer in length.' using hint = 'webhook:50035'; end if;
  if p_embeds is not null and (jsonb_typeof(p_embeds) <> 'array' or jsonb_array_length(p_embeds) > 10) then
    raise exception 'embeds: Up to 10 embeds' using hint = 'webhook:50035';
  end if;
  if p_embeds is not null and jsonb_array_length(p_embeds) = 0 then p_embeds := null; end if;
  if p_components is not null and jsonb_typeof(p_components) = 'array' and jsonb_array_length(p_components) = 0 then p_components := null; end if;
  if p_components is not null then
    if not (public.feature_on('embed_builder', c.server_id)
            or exists (select 1 from public.feature_flags f where f.key = 'embed_builder' and f.mode = 'test' and w.created_by = any(f.users))) then
      raise exception 'components: Buttons on webhooks aren''t on in this server yet' using hint = 'webhook:50035';
    end if;
    if not public.webhook_links_ok(p_components) then
      raise exception 'components: Webhooks can only send link buttons (https), up to 5 rows of 5' using hint = 'webhook:50035';
    end if;
  end if;
  if btrim(body) = '' and p_embeds is null then raise exception 'Cannot send an empty message' using hint = 'webhook:50006'; end if;
  n := case when btrim(coalesce(p_username, '')) = '' then w.name else public.webhook_name_ok(p_username) end;
  if p_avatar_url is not null and (p_avatar_url !~ '^https://' or char_length(p_avatar_url) > 512) then p_avatar_url := null; end if;

  -- The message triggers check content; the name, the embed text and the button labels / links get the same filters here.
  txt := n;
  if p_embeds is not null then
    txt := txt || ' ' || coalesce((select string_agg(v #>> '{}', ' ')
      from jsonb_path_query(p_embeds, 'strict $.**') v where jsonb_typeof(v) = 'string'), '');
  end if;
  if p_components is not null then
    txt := txt || ' ' || coalesce((select string_agg(v #>> '{}', ' ')
      from jsonb_path_query(p_components, 'strict $.**') v where jsonb_typeof(v) = 'string'), '');
  end if;
  if public.has_slur(txt) then
    raise exception 'That contains a slur, so it wasn''t sent. Keep it respectful.' using hint = 'webhook:200000';
  end if;
  if public.has_adult_link(txt) then raise exception 'Links to that site aren''t allowed on Yapper.' using hint = 'webhook:200000'; end if;
  if public.has_self_harm_incitement(body || ' ' || txt) then
    raise exception 'Telling someone to hurt themselves isn''t allowed on Yapper.' using hint = 'webhook:200000';
  end if;

  -- allowed_mentions (null = Discord's default for webhooks here: users yes, @everyone and roles no).
  parse := case when p_mentions is null then '["users"]'::jsonb
                when jsonb_typeof(p_mentions -> 'parse') = 'array' then p_mentions -> 'parse' else '[]'::jsonb end;
  allow_users := case when jsonb_typeof(p_mentions -> 'users') = 'array' then p_mentions -> 'users' else '[]'::jsonb end;
  allow_roles := case when jsonb_typeof(p_mentions -> 'roles') = 'array' then p_mentions -> 'roles' else '[]'::jsonb end;
  if body ~* '@(everyone|here)'
     and not (parse ? 'everyone' and public.webhook_user_perm(w.created_by, c.id, 'mention_everyone')) then
    body := regexp_replace(body, '@(everyone|here)', '@' || chr(8203) || '\1', 'gi');
  end if;
  if strpos(body, '<@&') > 0 and not (parse ? 'roles') then
    for r in select distinct x[1] as rid from regexp_matches(body, '<@&([0-9a-f-]{36})>', 'g') x loop
      continue when allow_roles ? r.rid;
      body := replace(body, '<@&' || r.rid || '>', '@' || chr(8203) || coalesce(
        (select translate(ro.name, '<>', '') from public.roles ro where ro.id::text = r.rid and ro.server_id = c.server_id), 'deleted-role'));
    end loop;
  end if;
  if strpos(body, '<@') > 0 and not (parse ? 'users') then
    for r in select distinct x[1] as uid from regexp_matches(body, '<@([0-9a-f-]{36})>', 'g') x loop
      continue when allow_users ? r.uid;
      body := replace(body, '<@' || r.uid || '>', '@' || chr(8203) || coalesce(
        (select p.username from public.profiles p where p.id::text = r.uid), 'unknown-user'));
    end loop;
  end if;

  perform set_config('yapper.bot', '1', true);
  perform set_config('yapper.webhook', '1', true);
  insert into public.messages (channel_id, author_id, content, embeds, components, webhook)
  values (c.id, author, body, p_embeds, p_components, jsonb_build_object('id', w.id, 'name', n, 'avatar_url', p_avatar_url,
          'avatar_path', case when p_avatar_url is null then w.avatar_path end))
  returning * into m;
  perform set_config('yapper.webhook', '', true);
  perform set_config('yapper.bot', '', true);
  update public.webhooks set last_used_at = now(), posts = posts + 1 where id = w.id;
  return m;
end $function$;

-- public.webhook_rename(wid uuid, p_name text)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_rename(wid uuid, p_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cid uuid;
begin
  select channel_id into cid from public.webhooks where id = wid;
  if cid is null then raise exception 'No such webhook'; end if;
  perform public.webhook_guard_manage(cid);
  update public.webhooks set name = public.webhook_name_ok(p_name) where id = wid;
end $function$;

-- public.webhook_rotate(wid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_rotate(wid uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cid uuid; tok text;
begin
  select channel_id into cid from public.webhooks where id = wid;
  if cid is null then raise exception 'No such webhook'; end if;
  perform public.webhook_guard_manage(cid);
  tok := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  update public.webhooks set token_hash = encode(sha256(convert_to(tok, 'UTF8')), 'hex') where id = wid;
  return tok;
end $function$;

-- public.webhook_send_v2(wid uuid, tok text, body text, p_username text, p_avatar_url text, p_embeds jsonb, p_mentions jsonb, p_components jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_send_v2(wid uuid, tok text, body text, p_username text DEFAULT NULL::text, p_avatar_url text DEFAULT NULL::text, p_embeds jsonb DEFAULT NULL::jsonb, p_mentions jsonb DEFAULT NULL::jsonb, p_components jsonb DEFAULT NULL::jsonb)
 RETURNS public.messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return public.webhook_post(public.webhook_by_token(wid, tok), body, p_username, p_avatar_url, p_embeds, p_mentions, p_components);
end $function$;

-- public.webhook_send(wid uuid, tok text, body text, p_username text, p_avatar_url text, p_embeds jsonb, p_mentions jsonb)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_send(wid uuid, tok text, body text, p_username text DEFAULT NULL::text, p_avatar_url text DEFAULT NULL::text, p_embeds jsonb DEFAULT NULL::jsonb, p_mentions jsonb DEFAULT NULL::jsonb)
 RETURNS public.messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return public.webhook_post(public.webhook_by_token(wid, tok), body, p_username, p_avatar_url, p_embeds, p_mentions, null);
end $function$;

-- public.webhook_set_avatar(p_uid uuid, wid uuid, p_path text)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_set_avatar(p_uid uuid, wid uuid, p_path text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.webhook_manage_channel(p_uid, wid) is null then raise exception 'You need Manage Webhooks for that'; end if;
  update public.webhooks set avatar_path = p_path where id = wid;
end $function$;

-- public.webhook_take_member(p_uid uuid, wid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_take_member(p_uid uuid, wid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare w public.webhooks; wait numeric;
begin
  w := public.webhook_member_guard(p_uid, wid);
  wait := public.webhook_hit('w:' || w.id::text, 2, 5);
  if wait = 0 then wait := public.webhook_hit('c:' || w.channel_id::text, 60, 30); end if;
  if wait > 0 then return jsonb_build_object('code', 429, 'retry_after', wait); end if;
  return jsonb_build_object('ok', true);
end $function$;

-- public.webhook_take(wid uuid, tok text)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_take(wid uuid, tok text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare w record; wait numeric;
begin
  if tok is null or tok !~ '^[0-9a-f]{64}$' then return jsonb_build_object('code', 50027); end if;
  select x.id, x.channel_id, x.token_hash into w from public.webhooks x where x.id = wid;
  if w.id is null then return jsonb_build_object('code', 10015); end if;
  if w.token_hash <> encode(sha256(convert_to(tok, 'UTF8')), 'hex') then return jsonb_build_object('code', 50027); end if;
  wait := public.webhook_hit('w:' || w.id::text, 2, 5);
  if wait = 0 then wait := public.webhook_hit('c:' || w.channel_id::text, 60, 30); end if;
  if random() < 0.01 then
    execute 'del' || 'ete from public.webhook_rate where at < now() - interval ''10 minutes''';
  end if;
  if wait > 0 then return jsonb_build_object('code', 429, 'retry_after', wait); end if;
  return jsonb_build_object('ok', true);
end $function$;

-- public.webhook_user_blocked(uid uuid, cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_user_blocked(uid uuid, cid uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid;
begin
  if uid is null then return 'gone from Yapper'; end if;
  select server_id into sid from public.channels where id = cid;
  if sid is null then return 'no such channel'; end if;
  if public.is_site_banned(uid) then return 'banned from Yapper'; end if;
  if exists (select 1 from public.server_bans b where b.server_id = sid and b.user_id = uid) then return 'banned from the server'; end if;
  if not exists (select 1 from public.server_members m where m.server_id = sid and m.user_id = uid) then return 'not in the server'; end if;
  if public.server_timed_out(sid, uid) is not null
     or exists (select 1 from public.profiles p where p.id = uid and p.muted_until > now()) then return 'timed out'; end if;
  if not public.webhook_user_sees(uid, cid) then return 'unable to see the channel'; end if;
  if not public.webhook_user_perm(uid, cid, 'manage_webhooks') then return 'missing Manage Webhooks'; end if;
  return null;
end $function$;

-- public.webhook_user_perm(uid uuid, cid uuid, perm text)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_user_perm(uid uuid, cid uuid, perm text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c record; base boolean; cp boolean;
begin
  if uid is null then return false; end if;
  select ch.id, ch.server_id, ch.category_id into c from public.channels ch where ch.id = cid;
  if c.server_id is null then return false; end if;
  base := exists (select 1 from public.servers s where s.id = c.server_id and s.owner_id = uid)
    or exists (select 1 from public.member_roles mr join public.roles r on r.id = mr.role_id
               where mr.server_id = c.server_id and mr.user_id = uid
                 and (coalesce((r.perms ->> 'administrator')::boolean, false)
                      or (r.manage_server and public.legacy_manage_server(perm))
                      or (r.manage_messages and public.legacy_manage_messages(perm))
                      or coalesce((r.perms ->> perm)::boolean, false)));
  cp := exists (select 1 from public.feature_flags f where f.key = 'channel_perms'
                  and (f.mode = 'everyone' or (f.mode = 'test' and c.server_id = any(f.servers))))
        and exists (select 1 from public.channel_overrides o where o.channel_id = c.id or o.category_id = c.category_id);
  if cp then return public.channel_perm_of(uid, c.id, perm, base); end if;
  return base;
end $function$;

-- public.webhook_user_sees(uid uuid, cid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.webhook_user_sees(uid uuid, cid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare prev_sub text := current_setting('request.jwt.claim.sub', true);
        prev_claims text := current_setting('request.jwt.claims', true); ok boolean;
begin
  if uid is null then return false; end if;
  perform set_config('request.jwt.claim.sub', uid::text, true);
  perform set_config('request.jwt.claims', jsonb_build_object('sub', uid, 'role', 'authenticated')::text, true);
  begin
    ok := coalesce(public.can_access_channel(cid), false);
  exception when others then
    perform set_config('request.jwt.claim.sub', coalesce(prev_sub, ''), true);
    perform set_config('request.jwt.claims', coalesce(nullif(prev_claims, ''), '{}'), true);
    raise;
  end;
  perform set_config('request.jwt.claim.sub', coalesce(prev_sub, ''), true);
  perform set_config('request.jwt.claims', coalesce(nullif(prev_claims, ''), '{}'), true);
  return ok;
end $function$;

-- public.who_online(sid uuid, extra uuid[], since timestamp with time zone)  [security definer]
CREATE OR REPLACE FUNCTION public.who_online(sid uuid, extra uuid[], since timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  ttl interval := public.presence_ttl();
  ids uuid[] := (coalesce(extra, '{}'::uuid[]))[1:500];
  since_ timestamptz := case when since is null then null else greatest(least(since, now()), now() - interval '15 minutes') end;
  rows jsonb;
begin
  if me is null then return '{}'::jsonb; end if;
  if sid is not null and not exists (select 1 from public.server_members m where m.server_id = sid and m.user_id = me) then sid := null; end if;
  select coalesce(jsonb_agg(jsonb_build_array(p.user_id, case when p.last_seen > now() - ttl then p.status else 'off' end, p.activity)), '[]'::jsonb)
    into rows
  from public.presence p
  where p.last_seen > coalesce(since_, now()) - ttl
    and (p.user_id = any(ids) or (sid is not null and exists (select 1 from public.server_members m where m.server_id = sid and m.user_id = p.user_id)))
    and (
      (since_ is null and p.last_seen > now() - ttl)
      or (since_ is not null and (p.online_since > since_ or p.status_at > since_ or p.activity_at > since_ or (p.last_seen <= now() - ttl and p.last_seen > since_ - ttl)))
    );
  return jsonb_build_object('now', now(), 'rows', rows);
end; $function$;

-- public.withdraw_area_application(p_area text)  [security definer]
CREATE OR REPLACE FUNCTION public.withdraw_area_application(p_area text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  update public.area_applications set status = 'withdrawn', decided_at = now(), seen_at = now()
    where user_id = auth.uid() and area = p_area and status = 'pending';
end $function$;

-- public.withdraw_bug_report(bid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.withdraw_bug_report(bid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  if not public.feature_on_for_me('bug_report_edit') then raise exception 'Withdrawing bug reports isn''t available yet'; end if;
  update public.bug_reports set status = 'withdrawn', updated_at = now()
   where id = bid and user_id = auth.uid() and status = 'open' and staff_note = '' and not staff_pick;
  if not found then raise exception 'You can only delete your own reports before staff answer them'; end if;
end $function$;

-- public.withdraw_community_deco(p_id uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.withdraw_community_deco(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.community_decos;
begin
  select * into d from public.community_decos where id = p_id and artist_id = (select auth.uid()) for update;
  if not found then raise exception 'Not found'; end if;
  if d.status = 'removed' then return; end if;
  update public.community_decos set status = 'removed' where id = p_id;
  if d.status = 'approved' then perform public.community_deco_unwear(d.path); end if;
end; $function$;

-- public.withdraw_join_request(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.withdraw_join_request(sid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  update public.server_join_requests set status = 'withdrawn', decided_at = now(), seen_at = now()
    where server_id = sid and user_id = auth.uid() and status = 'pending';
end $function$;

-- public.withdraw_staff_application()  [security definer]
CREATE OR REPLACE FUNCTION public.withdraw_staff_application()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  update public.staff_applications set status = 'withdrawn', decided_at = now(), seen_at = now()
    where user_id = auth.uid() and status = 'pending';
end $function$;

-- public.wordle_answer(d date)  [security definer]
CREATE OR REPLACE FUNCTION public.wordle_answer(d date)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int; k int;
begin
  select count(*) into n from public.wordle_words where answer;
  if n = 0 then return null; end if;
  k := mod(('x' || left(md5('yapper-wordle:' || d::text), 7))::bit(28)::int, n);
  return (select word from public.wordle_words where answer order by word offset k limit 1);
end $function$;

-- public.wordle_board_rows(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.wordle_board_rows(sid uuid)
 RETURNS TABLE(user_id uuid, played integer, wins integer, avg_guesses numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select g.user_id, count(*)::int, (count(*) filter (where g.won))::int,
         round(avg(coalesce(array_length(g.guesses, 1), 0)) filter (where g.won), 1)
  from public.wordle_games g
  where g.server_id = sid
    and exists (select 1 from public.server_members m where m.server_id = sid and m.user_id = g.user_id)
  group by g.user_id
  order by 3 desc, 4 asc nulls last, 2 asc
  limit 10
$function$;

-- public.wordle_board(sid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.wordle_board(sid uuid)
 RETURNS TABLE(user_id uuid, played integer, wins integer, avg_guesses numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select * from public.wordle_board_rows(sid)
  where public.is_server_member(sid) and public.feature_on('wordle_bot', sid)
$function$;

-- public.wordle_cmd()  [security definer]
CREATE OR REPLACE FUNCTION public.wordle_cmd()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid; cfg jsonb; body text; is_cmd boolean; arg text;
begin
  if current_setting('yapper.bot', true) = '1' then return null; end if;
  body := btrim(coalesce(new.content, ''));
  is_cmd := body ~* '^[/!]wordy(\s|$)';
  if not is_cmd and body !~ '^[A-Za-z]{5}$' then return null; end if;
  select server_id into sid from public.channels where id = new.channel_id;
  if sid is null then return null; end if;
  cfg := public.bot_cfg(sid, 'wordle');
  if cfg is null or (cfg ->> 'channel_id') is distinct from new.channel_id::text then return null; end if;
  if not public.feature_on('wordle_bot', sid) then return null; end if;
  if exists (select 1 from public.bot_accounts where user_id = new.author_id) then return null; end if;
  arg := lower(btrim(case when is_cmd then substr(body, 8) else body end));
  perform public.wordle_play(sid, new.channel_id, new.author_id, new.id, is_cmd, arg);
  return null;
exception when others then
  perform set_config('yapper.bot', '', true);
  raise warning 'wordle_cmd: %', sqlerrm;
  return null;
end $function$;

-- public.wordle_daily_recap()  [security definer]
CREATE OR REPLACE FUNCTION public.wordle_daily_recap()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d date := public.wordle_day() - 1; s record; r record; played int; wins int; av numeric; ans text; body text; fast text; n int := 0;
begin
  ans := public.wordle_answer(d);
  -- The channel must be the server's own: set_server_bot stores any uuid a manager sends.
  for s in select sb.server_id, c.id as cid from public.server_bots sb
           join public.channels c on c.id = (sb.config ->> 'channel_id')::uuid and c.server_id = sb.server_id
           where sb.bot = 'wordle' and sb.enabled and nullif(sb.config ->> 'channel_id', '') ~ '^[0-9a-f-]{36}$' loop
    begin
      if not public.feature_on('wordle_bot', s.server_id) then continue; end if;
      select count(*), count(*) filter (where won), round(avg(array_length(guesses, 1)) filter (where won), 1)
        into played, wins, av from public.wordle_games where server_id = s.server_id and day = d;
      if played = 0 then continue; end if;
      fast := '';
      for r in select user_id, array_length(guesses, 1) as k from public.wordle_games
               where server_id = s.server_id and day = d and won order by 2, finished_at limit 3 loop
        fast := fast || case when fast = '' then '' else ', ' end || public.log_name(r.user_id) || ' ' || r.k || '/6';
      end loop;
      body := '📊 **Wordy #' || public.wordle_no(d) || '** is done: ' || played || ' played, ' || wins || ' got it'
        || case when wins > 0 then ' (avg ' || av || ' guesses)' else '' end || '.'
        || case when fast <> '' then E'\n' || 'Quickest: ' || fast else '' end
        || case when ans is not null then E'\n' || 'The word was ||' || upper(ans) || '||.' else '' end
        || E'\n' || 'Wordy #' || public.wordle_no(d + 1) || ' is up: type `/wordy`.';
      perform public.wordle_say(s.cid, body, null);
      n := n + 1;
    exception when others then
      perform set_config('yapper.bot', '', true);
      raise warning 'wordle_daily_recap % : %', s.server_id, sqlerrm;
    end;
  end loop;
  return n;
end $function$;

-- public.wordle_day()
CREATE OR REPLACE FUNCTION public.wordle_day()
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$ select (now() at time zone 'utc')::date $function$;

-- public.wordle_grid(guesses text[], answer text, letters boolean)
CREATE OR REPLACE FUNCTION public.wordle_grid(guesses text[], answer text, letters boolean)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(string_agg(public.wordle_squares(public.wordle_score(g, answer))
      || case when letters then ' ||' || upper(g) || '||' else '' end, E'\n' order by n), '')
  from unnest(guesses) with ordinality as u(g, n)
$function$;

-- public.wordle_no(d date)
CREATE OR REPLACE FUNCTION public.wordle_no(d date)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$ select (d - date '2026-10-27')::int $function$;

-- public.wordle_play(sid uuid, cid uuid, uid uuid, mid uuid, is_cmd boolean, arg text)  [security definer]
CREATE OR REPLACE FUNCTION public.wordle_play(sid uuid, cid uuid, uid uuid, mid uuid, is_cmd boolean, arg text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d date := public.wordle_day(); no int; g record; ans text; n int; hit boolean; board text; finished boolean;
begin
  no := public.wordle_no(d);
  if is_cmd and arg in ('stats', 'stat', 'top', 'leaderboard', 'board', 'streak') then
    perform public.wordle_say(cid, public.wordle_stats_text(sid, uid), mid);
    return;
  end if;
  if is_cmd and arg in ('help', '?') then
    perform public.wordle_say(cid, '**Wordy** · one five letter word a day, six tries.' || E'\n'
      || '`/wordy` starts today''s, then type your guesses here (or `/wordy crane`). 🟩 right spot, 🟨 in the word, ⬛ not in it.' || E'\n'
      || '`/wordy stats` shows your streaks and the top solvers here. New word at 00:00 UTC.', mid);
    return;
  end if;

  select * into g from public.wordle_games where user_id = uid and day = d for update;
  if not is_cmd then
    -- A bare word only counts while this person has a game running in this channel. Everything else is just chat.
    if g.user_id is null or g.finished_at is not null or g.channel_id is distinct from cid then return; end if;
  else
    if g.user_id is not null and g.server_id <> sid then
      perform public.wordle_say(cid, 'You already played today''s Wordy in another server. New word at 00:00 UTC!', mid);
      return;
    end if;
    -- The Wordle channel moved mid-day: a running game follows it.
    if g.user_id is not null and g.channel_id is distinct from cid then
      update public.wordle_games set channel_id = cid where user_id = uid and day = d;
      g.channel_id := cid;
    end if;
    if g.user_id is null then
      if arg <> '' and arg !~ '^[a-z]{5}$' then
        perform public.wordle_say(cid, 'Guesses are five letters: `/wordy crane`, or `/wordy` to start and type words here. `/wordy help` for the rest.', mid);
        return;
      end if;
      insert into public.wordle_games (user_id, day, server_id, channel_id) values (uid, d, sid, cid) returning * into g;
      if arg = '' then
        perform public.wordle_say(cid, '🟩 **Wordy #' || no || '** · six tries, go! Type a five letter word here. '
          || 'Your board answers each guess (letters behind a spoiler). `/wordy stats` for your streak.', mid);
        return;
      end if;
    end if;
    if arg = '' then
      n := coalesce(array_length(g.guesses, 1), 0);
      if g.finished_at is not null then
        perform public.wordle_say(cid, 'You already finished Wordy #' || no || ': **' || case when g.won then n || '/6' else 'X/6' end
          || '**. New word at 00:00 UTC.' || E'\n' || public.wordle_grid(g.guesses, public.wordle_answer(d), false), mid);
      else
        perform public.wordle_say(cid, 'Wordy #' || no || ', ' || n || '/6 used. Keep going, type a five letter word here.'
          || case when n > 0 then E'\n' || public.wordle_grid(g.guesses, public.wordle_answer(d), true) else '' end, mid);
      end if;
      return;
    end if;
    if g.finished_at is not null then
      perform public.wordle_say(cid, 'You already finished Wordy #' || no || '. New word at 00:00 UTC!', mid);
      return;
    end if;
  end if;

  -- A guess.
  if arg !~ '^[a-z]{5}$' then
    perform public.wordle_say(cid, 'Guesses are five letters.', mid);
    return;
  end if;
  if not exists (select 1 from public.wordle_words where word = arg) then
    perform public.wordle_say(cid, '**' || upper(arg) || '** isn''t in the word list. Try another.', mid);
    return;
  end if;
  ans := public.wordle_answer(d);
  if ans is null then return; end if;
  g.guesses := g.guesses || arg;
  n := array_length(g.guesses, 1);
  hit := arg = ans;
  finished := hit or n >= 6;
  update public.wordle_games set guesses = g.guesses, won = hit, finished_at = case when finished then now() end
  where user_id = uid and day = d;
  board := public.wordle_grid(g.guesses, ans, true);
  if hit then
    perform public.wordle_say(cid, '🎉 Got it! Wordy #' || no || ' **' || n || '/6**' || E'\n' || board
      || E'\n' || 'Squares only, for sharing:' || E'\n' || public.wordle_grid(g.guesses, ans, false), mid);
  elsif finished then
    perform public.wordle_say(cid, '😬 Out of tries. Wordy #' || no || ' **X/6**, the word was ||' || upper(ans) || '||.' || E'\n' || board, mid);
  else
    perform public.wordle_say(cid, board || E'\n' || n || '/6 used.', mid);
  end if;
end $function$;

-- public.wordle_say(cid uuid, body text, reply uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.wordle_say(cid uuid, body text, reply uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare bid uuid := public.bot_id('wordle');
begin
  if cid is null or bid is null or body is null or btrim(body) = '' then return; end if;
  perform set_config('yapper.bot', '1', true);
  insert into public.messages (channel_id, author_id, content, reply_to_id, created_at)
  values (cid, bid, left(body, 2000), reply, clock_timestamp());
  perform set_config('yapper.bot', '', true);
end $function$;

-- public.wordle_score(guess text, answer text)
CREATE OR REPLACE FUNCTION public.wordle_score(guess text, answer text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare res text[] := array['x','x','x','x','x']; used boolean[] := array[false,false,false,false,false]; i int; j int;
begin
  for i in 1..5 loop
    if substr(guess, i, 1) = substr(answer, i, 1) then res[i] := 'g'; used[i] := true; end if;
  end loop;
  for i in 1..5 loop
    if res[i] = 'x' then
      for j in 1..5 loop
        if not used[j] and substr(guess, i, 1) = substr(answer, j, 1) then res[i] := 'y'; used[j] := true; exit; end if;
      end loop;
    end if;
  end loop;
  return array_to_string(res, '');
end $function$;

-- public.wordle_squares(score text)
CREATE OR REPLACE FUNCTION public.wordle_squares(score text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select replace(replace(replace(score, 'g', '🟩'), 'y', '🟨'), 'x', '⬛')
$function$;

-- public.wordle_stats_text(sid uuid, uid uuid)  [security definer]
CREATE OR REPLACE FUNCTION public.wordle_stats_text(sid uuid, uid uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare played int; wins int; dist int[] := array[0,0,0,0,0,0]; s record; r record; line text; i int := 0; k int;
begin
  select count(*), count(*) filter (where won) into played, wins from public.wordle_games where user_id = uid;
  for r in select array_length(guesses, 1) n, count(*) c from public.wordle_games where user_id = uid and won group by 1 loop
    if r.n between 1 and 6 then dist[r.n] := r.c; end if;
  end loop;
  select * into s from public.wordle_streaks(uid);
  line := '📊 **Wordy stats for ' || public.log_name(uid) || '**' || E'\n';
  if played = 0 then
    line := line || 'No games yet. Type `/wordy` to start today''s.' || E'\n';
  else
    line := line || 'Played ' || played || ' · Won ' || wins || ' (' || round(100.0 * wins / played) || '%) · Streak '
      || s.cur || ' · Best streak ' || s.best || E'\n';
    line := line || 'Guesses: ';
    for k in 1..6 loop line := line || k || '️⃣ ' || dist[k] || case when k < 6 then ' · ' else '' end; end loop;
    line := line || E'\n';
  end if;
  line := line || '**Top solvers here**' || E'\n';
  for r in select * from public.wordle_board_rows(sid) limit 5 loop
    i := i + 1;
    line := line || i || '. ' || public.log_name(r.user_id) || ' · ' || r.wins || ' win' || case when r.wins = 1 then '' else 's' end
      || ' / ' || r.played || ' played' || case when r.avg_guesses is not null then ' · avg ' || r.avg_guesses else '' end || E'\n';
  end loop;
  if i = 0 then line := line || 'Nobody has played here yet.'; end if;
  return line;
end $function$;

-- public.wordle_streaks(uid uuid, OUT cur integer, OUT best integer)  [security definer]
CREATE OR REPLACE FUNCTION public.wordle_streaks(uid uuid, OUT cur integer, OUT best integer)
 RETURNS record
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare days date[]; d date; i int; run int := 0;
begin
  cur := 0; best := 0;
  select array_agg(g.day order by g.day) into days from public.wordle_games g where g.user_id = uid and g.won;
  if days is null then return; end if;
  d := public.wordle_day();
  if not (d = any(days)) then d := d - 1; end if;
  while d = any(days) loop cur := cur + 1; d := d - 1; end loop;
  for i in 1 .. array_length(days, 1) loop
    if i > 1 and days[i] = days[i - 1] + 1 then run := run + 1; else run := 1; end if;
    if run > best then best := run; end if;
  end loop;
end $function$;

-- public.yt_parse_feed(body text)
CREATE OR REPLACE FUNCTION public.yt_parse_feed(body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare x xml; nm text; vids jsonb;
begin
  -- Strip the <?xml ...?> line: xmlparse refuses an encoding declaration on an already decoded string.
  x := xmlparse(document regexp_replace(body, '^\s*<\?xml[^>]*\?>', ''));
  select t.title into nm from xmltable(xmlnamespaces('http://www.w3.org/2005/Atom' as a), '/a:feed' passing x
    columns title text path 'a:title') t;
  select coalesce(jsonb_agg(jsonb_build_object('id', v.vid, 'title', left(coalesce(v.title, ''), 300),
      'url', case when v.link ~ '^https://www\.youtube\.com/(watch\?v=|shorts/)[A-Za-z0-9_-]{11}$' then v.link
                  else 'https://www.youtube.com/watch?v=' || v.vid end,
      'published', v.published) order by v.published desc nulls last), '[]'::jsonb)
  into vids
  from xmltable(xmlnamespaces('http://www.w3.org/2005/Atom' as a, 'http://www.youtube.com/xml/schemas/2015' as yt),
    '/a:feed/a:entry' passing x
    columns vid text path 'yt:videoId', title text path 'a:title',
            link text path 'a:link[@rel="alternate"]/@href', published timestamptz path 'a:published') v
  where v.vid ~ '^[A-Za-z0-9_-]{11}$';
  return jsonb_build_object('name', left(btrim(nm), 100), 'videos', vids);
end $function$;
